    def showEvent(self, event):
        super().showEvent(event)
        if getattr(self, "_initial_splitter_applied", False):
            return
        self._initial_splitter_applied = True
        QTimer.singleShot(0, self._apply_initial_splitter_sizes)
        if (
            (not bool(getattr(self, "_isolated_system_window", False)))
            and not bool(getattr(self, "_startup_completed", False))
            and self._restore_tabs_on_startup_enabled()
        ):
            QTimer.singleShot(0, self._restore_center_tab_session)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        # Keep the 3-pane layout usable on narrower 16:9 screens and DPI scaling.
        if hasattr(self, "_main_splitter"):
            QTimer.singleShot(0, self._enforce_responsive_splitter_layout)
        self._update_active_mod_indicator()

    def _apply_initial_splitter_sizes(self):
        splitter = getattr(self, "_main_splitter", None)
        if splitter is None:
            return
        total = int(splitter.size().width())
        if total <= 0:
            total = int(self.size().width())
        if total <= 0:
            return

        left = max(170, min(320, int(total * 0.16)))
        right = max(230, min(420, int(total * 0.24)))
        center = total - left - right
        if center < 420:
            deficit = 420 - center
            shrink_right = min(deficit, max(0, right - 220))
            right -= shrink_right
            deficit -= shrink_right
            shrink_left = min(deficit, max(0, left - 150))
            left -= shrink_left
            center = total - left - right
        splitter.setSizes([left, max(300, center), right])
        self._enforce_responsive_splitter_layout()

    def _enforce_responsive_splitter_layout(self):
        splitter = getattr(self, "_main_splitter", None)
        if splitter is None:
            return
        sizes = splitter.sizes()
        if len(sizes) < 3:
            return
        total = int(splitter.size().width())
        if total <= 0:
            total = int(self.size().width())
        if total <= 0:
            return

        left = max(0, int(sizes[0]))
        center = max(0, int(sizes[1]))
        right = max(0, int(sizes[2]))
        if (left + center + right) <= 0:
            return

        is_browser = hasattr(self, "browser") and hasattr(self, "left_stack") and self.left_stack.currentWidget() is self.browser
        left_min = int(getattr(self, "_browser_compact_width", 240)) if is_browser else 120
        left_max = int(getattr(self, "_browser_compact_width", 240)) if is_browser else max(220, int(total * 0.34))
        right_min = 170
        right_max = max(right_min, int(total * 0.33))
        center_min = max(280, int(total * 0.34))

        left = max(left_min, min(left, left_max))
        right = max(right_min, min(right, right_max))
        center = total - left - right

        if center < center_min:
            deficit = center_min - center
            shrink_right = min(deficit, max(0, right - right_min))
            right -= shrink_right
            deficit -= shrink_right
            if deficit > 0:
                shrink_left = min(deficit, max(0, left - left_min))
                left -= shrink_left
            center = total - left - right

        if center < 220:
            center = 220
            remaining = total - center
            if remaining > 0:
                # Keep right panel smaller first if space is very limited.
                right = min(right, max(right_min, int(remaining * 0.45)))
                left = max(left_min, remaining - right)

        splitter.setSizes([max(0, left), max(220, center), max(0, right)])

    def _build_global_nav_bar(self, parent_layout: QVBoxLayout):
        self._global_nav_container = QWidget(self)
        self._global_nav_container.setObjectName("GlobalNavContainer")
        self._global_nav_container.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        container_layout = QVBoxLayout(self._global_nav_container)
        container_layout.setContentsMargins(0, 0, 0, 0)
        container_layout.setSpacing(0)

        self._global_nav_bar = QWidget(self._global_nav_container)
        self._global_nav_bar.setObjectName("GlobalNavBar")
        self._global_nav_bar.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        row = QHBoxLayout(self._global_nav_bar)
        row.setContentsMargins(8, 0, 8, 0)
        row.setSpacing(8)
        if hasattr(self, "center_tab_bar"):
            self.center_tab_bar.setParent(self._global_nav_bar)
            self.center_tab_bar.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            row.addWidget(self.center_tab_bar, 1)
        self.nav_savegame_btn = QPushButton(tr("action.savegame_editor"))
        self.nav_savegame_btn.setCheckable(False)
        self.nav_savegame_btn.setMinimumWidth(0)
        self.nav_savegame_btn.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        row.addWidget(self.nav_savegame_btn)
        self.nav_settings_btn = QPushButton(self._global_settings_caption())
        self.nav_settings_btn.setCheckable(False)
        self.nav_settings_btn.setMinimumWidth(0)
        self.nav_settings_btn.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        self.nav_settings_btn.clicked.connect(self._open_global_settings_view)
        row.addWidget(self.nav_settings_btn)
        self._apply_global_nav_tab_style()
        self.nav_savegame_btn.clicked.connect(self._launch_external_savegame_editor)
        container_layout.addWidget(self._global_nav_bar)
        self._global_loading_host = QWidget(self._global_nav_container)
        self._global_loading_host.setObjectName("GlobalLoadingHost")
        self._global_loading_host.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        container_layout.addWidget(self._global_loading_host)
        parent_layout.addWidget(self._global_nav_container)

    def _set_global_nav_active(self, key: str):
        # Legacy compatibility shim. Main navigation is tab-driven now.
        return

    def _prepare_editor_page(self, attr_name: str, title: str) -> tuple[QWidget, QVBoxLayout]:
        page, root = prepare_editor_page(
            center_stack=self.center_stack if hasattr(self, "center_stack") else None,
            center_tab_specs=self._center_tab_specs if hasattr(self, "_center_tab_specs") else None,
            center_tab_index_for_widget=self._center_tab_index_for_widget,
            center_sync_tab_bar=self._center_sync_tab_bar,
            old_page=getattr(self, attr_name, None),
            title=title,
        )
        setattr(self, attr_name, page)
        return page, root

    def _apply_feedback_button_style(self):
        if not hasattr(self, "feedback_btn"):
            return
        self.feedback_btn.setStyleSheet(
            """
            QPushButton {
                color: #ffffff;
                font-weight: 800;
                font-size: 9pt;
                padding: 7px 16px;
                border-radius: 11px;
                border: 1px solid #5ecbff;
                background: qlineargradient(
                    x1:0, y1:0, x2:0, y2:1,
                    stop:0 #2aa6ff,
                    stop:1 #116fdb
                );
            }
            QPushButton:hover {
                border: 1px solid #9adfff;
                background: qlineargradient(
                    x1:0, y1:0, x2:0, y2:1,
                    stop:0 #46b7ff,
                    stop:1 #1a86eb
                );
            }
            QPushButton:pressed {
                background: #0f61c4;
            }
            """
        )
        glow = QGraphicsDropShadowEffect(self.feedback_btn)
        glow.setBlurRadius(34.0)
        glow.setOffset(0.0, 0.0)
        glow.setColor(QColor(66, 188, 255, 210))
        self.feedback_btn.setGraphicsEffect(glow)

    def _global_settings_caption(self) -> str:
        return "FLAtlas Settings" if get_language() == "en" else "FLAtlas Einstellungen"

    def _build_standard_menu_bar(self):
        bar = self.menuBar()
        bar.setNativeMenuBar(False)
        bar.setVisible(True)
        bar.clear()
        lang_en = get_language() == "en"
        m_file = bar.addMenu("File" if lang_en else "Datei")
        m_edit = bar.addMenu("Edit" if lang_en else "Bearbeiten")
        m_view = bar.addMenu("View" if lang_en else "Ansicht")
        m_tools = bar.addMenu("Tools")
        m_browser = bar.addMenu("System Browser" if lang_en else "System-Browser")
        m_settings = bar.addMenu("Settings" if lang_en else "Einstellungen")
        m_language = bar.addMenu("Language")
        m_help = bar.addMenu("Help" if lang_en else "Hilfe")

        # Datei
        a_new_system = QAction(tr("btn.new_system"), self)
        a_new_system.triggered.connect(self._start_new_system)
        a_new_system.setEnabled(self._filepath is None)
        m_file.addAction(a_new_system)
        a_load_uni = QAction(tr("action.universe"), self)
        a_load_uni.triggered.connect(self._load_universe_action)
        m_file.addAction(a_load_uni)
        a_trade_routes = QAction(tr("action.trade_routes"), self)
        a_trade_routes.triggered.connect(self._open_trade_routes_view)
        m_file.addAction(a_trade_routes)
