    @staticmethod
    def _object_group_definitions(lang_en: bool) -> list[tuple[str, str]]:
        return [
            ("systems", "Systems" if lang_en else "Systeme"),
            ("stars", "Stars" if lang_en else "Sterne"),
            ("planets", "Planets" if lang_en else "Planeten"),
            ("stations", "Stations / Bases" if lang_en else "Stationen / Basen"),
            ("jump", "Jump Gates / Holes" if lang_en else "Sprungtore / -löcher"),
            ("tradelanes", "Trade Lanes" if lang_en else "Handelsringe"),
            ("buoys", "Buoys" if lang_en else "Bojen"),
            ("wrecks", "Wrecks" if lang_en else "Wracks"),
            ("platforms", "Platforms / Depots" if lang_en else "Plattformen / Depots"),
            ("zones_environment", "Zones: Environment" if lang_en else "Zonen: Umwelt"),
            ("zones_exclusion", "Zones: Exclusion" if lang_en else "Zonen: Exclusion"),
            ("zones_destroy_vignette", "Zones: Destroy Vignette" if lang_en else "Zonen: Destroy Vignette"),
            ("zones_patrol", "Zones: Patrol / Path" if lang_en else "Zonen: Patrol / Path"),
            ("zones_hazard", "Zones: Hazard" if lang_en else "Zonen: Gefahr"),
            ("zones_other", "Zones: Other" if lang_en else "Zonen: Sonstige"),
            ("misc_objects", "Other Objects" if lang_en else "Sonstige Objekte"),
        ]

    def _refresh_object_groups_dialog_texts(self):
        dlg = getattr(self, "_object_groups_dialog", None)
        if dlg is None:
            return
        lang_en = get_language() == "en"
        dlg.setWindowTitle("Object Groups" if lang_en else "Objektgruppen")
        labels = dict(self._object_group_definitions(lang_en))
        for key, cb in self._object_group_checkboxes.items():
            cb.setText(labels.get(key, key))

    def _open_object_groups_dialog(self):
        if self._object_groups_dialog is not None:
            self._refresh_object_groups_dialog_texts()
            for key, cb in self._object_group_checkboxes.items():
                cur = bool(self._object_group_visibility.get(key, True))
                if cb.isChecked() != cur:
                    cb.blockSignals(True)
                    cb.setChecked(cur)
                    cb.blockSignals(False)
            self._object_groups_dialog.show()
            self._object_groups_dialog.raise_()
            self._object_groups_dialog.activateWindow()
            return

        lang_en = get_language() == "en"
        dlg = QDialog(self)
        dlg.setModal(False)
        dlg.setWindowTitle("Object Groups" if lang_en else "Objektgruppen")
        dlg.resize(360, 520)
        root = QVBoxLayout(dlg)
        self._object_group_checkboxes = {}
        for key, label in self._object_group_definitions(lang_en):
            cb = QCheckBox(label)
            cb.setChecked(bool(self._object_group_visibility.get(key, True)))
            cb.toggled.connect(lambda checked, k=key: self._set_group_visibility(k, bool(checked)))
            self._object_group_checkboxes[key] = cb
            root.addWidget(cb)
        row = QHBoxLayout()
        row.addStretch(1)
        close_btn = QPushButton(tr("dlg.close"))
        close_btn.clicked.connect(dlg.close)
        row.addWidget(close_btn)
        root.addLayout(row)

        def _on_closed(_r: int):
            self._object_groups_dialog = None
            self._object_group_checkboxes = {}

        dlg.finished.connect(_on_closed)
        self._object_groups_dialog = dlg
        dlg.show()

    def _classify_object_group(self, obj) -> str:
        if isinstance(obj, UniverseSystem):
            return "systems"
        arch = str(getattr(obj, "data", {}).get("archetype", "")).lower()
        nick = str(getattr(obj, "nickname", "")).lower()
        if any(x in arch or x in nick for x in ("sun", "star")):
            return "stars"
        if "planet" in arch or "planet" in nick:
            return "planets"
        if any(x in arch or x in nick for x in ("jumpgate", "jump_gate", "jumphole", "jump_hole", "jumppoint_gate", "nomad_gate")):
            return "jump"
        if any(x in arch or x in nick for x in ("trade_lane_ring", "tradelane_ring")):
            return "tradelanes"
        if "buoy" in arch or "buoy" in nick:
            return "buoys"
        if "wreck" in arch or "wreck" in nick:
            return "wrecks"
        if (
            arch in {"wplatform", "small_wplatform", "mplatform"}
            or "platform" in arch
            or arch.startswith("depot")
            or "depot" in nick
        ):
            return "platforms"
        if (
            arch.strip() == "dock_ring"
            or any(x in arch for x in ("base", "station", "outpost", "shipyard", "space_"))
            or any(x in nick for x in ("base", "station", "outpost", "dock_ring"))
        ):
            return "stations"
        return "misc_objects"

    def _classify_zone_group(self, zone: ZoneItem) -> str:
        name = str(zone.nickname).lower()
        dmg = 0.0
        try:
            dmg = float(str(zone.data.get("damage", "")).strip() or "0")
        except Exception:
            dmg = 0.0
        if "destroy_vignette" in name:
            return "zones_destroy_vignette"
        if "exclusion" in name:
            return "zones_exclusion"
        if "path" in name and "tradelane" not in name:
            return "zones_patrol"
        if any(x in name for x in ("death", "sundeath", "radiation", "hazard")) or dmg > 0.0:
            return "zones_hazard"
        if any(x in name for x in ("nebula", "badlands", "asteroid", "debris", "field")):
            return "zones_environment"
        return "zones_other"

    def _set_group_visibility(self, key: str, visible: bool):
        self._object_group_visibility[key] = bool(visible)
        act = self._object_group_actions.get(key)
        if act is not None and act.isChecked() != bool(visible):
            act.blockSignals(True)
            act.setChecked(bool(visible))
            act.blockSignals(False)
        cb = self._object_group_checkboxes.get(key)
        if cb is not None and cb.isChecked() != bool(visible):
            cb.blockSignals(True)
            cb.setChecked(bool(visible))
            cb.blockSignals(False)
        self._cfg.set("view.group_visibility", dict(self._object_group_visibility))
        self._apply_group_visibility()

    def _restore_view_settings(self):
        zone_visible = bool(self._cfg.get("view.show_zones", True))
        labels_visible = bool(self._cfg.get("view.show_labels", True))
        self._avoid_label_overlap = bool(self._cfg.get("view.avoid_label_overlap", True))
        self._view3d_reference_grid_visible = bool(self._cfg.get("view.show_3d_grid", True))
        point_size_pct = int(self._cfg.get("view.point_size_pct", 100) or 100)
        native_preview_distance_fl = int(self._cfg.get("view.native_preview_distance_fl", -1) or -1)
        native_preview_hq_distance_fl = int(self._cfg.get("view.native_preview_hq_distance_fl", 20000) or 20000)
        point_size_pct = max(40, min(220, point_size_pct))
        if native_preview_distance_fl < 0:
            native_preview_distance_fl = -1
        else:
            native_preview_distance_fl = max(0, min(100000, native_preview_distance_fl))
        native_preview_hq_distance_fl = max(0, min(100000, native_preview_hq_distance_fl))
        try:
            self.zone_cb.blockSignals(True)
            self.zone_cb.setChecked(zone_visible)
        finally:
            self.zone_cb.blockSignals(False)
        self._toggle_zones(zone_visible)
        try:
            self.viewer_text_cb.blockSignals(True)
            self.viewer_text_cb.setChecked(labels_visible)
        finally:
            self.viewer_text_cb.blockSignals(False)
        self._toggle_viewer_text(labels_visible)
        if hasattr(self, "_point_size_slider"):
            try:
                self._point_size_slider_busy = True
                self._point_size_slider.setValue(point_size_pct)
            finally:
                self._point_size_slider_busy = False
            self._on_point_size_slider_changed(point_size_pct)
        if hasattr(self, "_native_preview_dist_slider"):
            try:
                self._native_preview_dist_slider.blockSignals(True)
                slider_value = 1001 if native_preview_distance_fl < 0 else int(round(native_preview_distance_fl / 100.0))
                self._native_preview_dist_slider.setValue(slider_value)
            finally:
                self._native_preview_dist_slider.blockSignals(False)
            self._on_native_preview_distance_changed(self._native_preview_dist_slider.value())
        if hasattr(self, "_native_preview_hq_slider"):
            try:
                self._native_preview_hq_slider.blockSignals(True)
                self._native_preview_hq_slider.setValue(int(round(native_preview_hq_distance_fl / 100.0)))
            finally:
                self._native_preview_hq_slider.blockSignals(False)
            self._on_native_preview_high_quality_distance_changed(self._native_preview_hq_slider.value())
        if hasattr(self, "_view3d_reference_grid_action"):
            try:
                self._view3d_reference_grid_action.blockSignals(True)
                self._view3d_reference_grid_action.setChecked(bool(self._view3d_reference_grid_visible))
            finally:
                self._view3d_reference_grid_action.blockSignals(False)
        self._toggle_view3d_reference_grid(bool(self._view3d_reference_grid_visible))

    def _save_view_settings(self):
        self._cfg.set("view.show_zones", bool(self.zone_cb.isChecked()))
        self._cfg.set("view.show_labels", bool(self.viewer_text_cb.isChecked()))
        self._cfg.set("view.avoid_label_overlap", bool(self._avoid_label_overlap))
        self._cfg.set("view.show_3d_grid", bool(self._view3d_reference_grid_visible))
        if hasattr(self, "_point_size_slider"):
            self._cfg.set("view.point_size_pct", int(self._point_size_slider.value()))
        if hasattr(self, "_native_preview_dist_slider"):
            self._cfg.set(
                "view.native_preview_distance_fl",
                self._native_preview_distance_from_slider(int(self._native_preview_dist_slider.value())),
            )
        if hasattr(self, "_native_preview_hq_slider"):
            self._cfg.set(
                "view.native_preview_hq_distance_fl",
                self._native_preview_high_quality_distance_from_slider(int(self._native_preview_hq_slider.value())),
            )
        self._cfg.set("view.group_visibility", dict(self._object_group_visibility))

    def _universe_system_visible_for_active_sector(self, obj: UniverseSystem, sector_name: str | None = None) -> bool:
        chosen = str(sector_name or getattr(self, "_uni_active_sector", "sirius") or "sirius").strip().lower() or "sirius"
        pos_map = self._uni_sector_positions.get(str(getattr(obj, "nickname", "") or "").upper(), {})
        if chosen == "galaxy":
            return bool(pos_map)
        meta = self._uni_sector_defs.get(chosen, {})
        source_map = str(meta.get("source_map", "universe") or "universe").strip().lower()
        if source_map != "universe":
            return source_map in pos_map
        if self._uni_multiverse_detected:
            has_explicit_maps = any(str(key).lower() != "universe" for key in dict(pos_map).keys())
            return ("sector01" in pos_map) if has_explicit_maps else True
        return True

    def _apply_group_visibility(self):
        active_base = str(self._base_builder_active_base_nick or "").strip().lower()
        zones_enabled = bool(self.zone_cb.isChecked()) if hasattr(self, "zone_cb") else True
        for obj in self._objects:
            group_key = self._classify_object_group(obj)
            visible = bool(self._object_group_visibility.get(group_key, True))
            if isinstance(obj, UniverseSystem):
                visible = visible and self._universe_system_visible_for_active_sector(obj)
            elif visible and active_base:
                visible = self._is_object_related_to_base(obj, active_base)
            try:
                obj.setVisible(visible)
            except Exception:
                pass
            self._apply_2d_object_label_policy(obj)
            if hasattr(self, "view3d") and hasattr(self.view3d, "set_item_visibility"):
                self.view3d.set_item_visibility(obj, visible)
        for zone in self._zones:
            group_key = self._classify_zone_group(zone)
            visible = zones_enabled and bool(self._object_group_visibility.get(group_key, True)) and not bool(active_base)
            try:
                zone.setVisible(visible)
            except Exception:
                pass
            if hasattr(self, "view3d") and hasattr(self.view3d, "set_item_visibility"):
                self.view3d.set_item_visibility(zone, visible)

