    @staticmethod
    def _read_text_best_effort(path: Path) -> str:
        raw = path.read_bytes()
        if raw[:4] == b"BINI":
            try:
                return decode_bini_to_ini_text(raw)
            except Exception:
                pass
        for enc in ("utf-8-sig", "cp1252", "latin-1"):
            try:
                return raw.decode(enc)
            except Exception:
                continue
        return raw.decode("utf-8", errors="ignore")

    def _resource_dlls_from_freelancer_ini(self, ini_path: Path) -> list[str]:
        try:
            sections = self._parser.parse(str(ini_path))
        except Exception:
            return []
        out: list[str] = []
        seen: set[str] = set()
        for sec_name, entries in sections:
            if sec_name.strip().lower() != "resources":
                continue
            for k, v in entries:
                if k.strip().lower() != "dll":
                    continue
                dll = v.split(",", 1)[0].strip()
                if not dll:
                    continue
                if self._is_ignored_lookup_dll(dll):
                    continue
                dl = dll.lower()
                if dl not in seen:
                    seen.add(dl)
                    out.append(dll)
            break
        return out

    @staticmethod
    def _is_ignored_lookup_dll(dll_name: str) -> bool:
        base = Path(str(dll_name or "").replace("\\", "/")).name.lower()
        return base == "resources_vanilla.dll"

    def _resource_dll_pairs_for_lookup(self) -> list[tuple[Path, str]]:
        """Builds DLL lookup order with Vanilla fallback even when mod freelancer.ini exists."""
        primary_ini = self._find_freelancer_ini_read()
        fallback_root = self._fallback_game_path().strip()
        fallback_ini = None
        if fallback_root:
            fb_base = Path(fallback_root)
            for rel in ("EXE/freelancer.ini", "freelancer.ini"):
                fp = ci_resolve(fb_base, rel)
                if fp and fp.is_file():
                    fallback_ini = fp
                    break

        primary_dlls = self._resource_dlls_from_freelancer_ini(primary_ini) if primary_ini else []
        fallback_dlls = self._resource_dlls_from_freelancer_ini(fallback_ini) if fallback_ini else []

        # Lookup-Regel:
        # 1) Wenn Mod-Liste erkennbar Vanilla enthält -> Mod-Reihenfolge respektieren.
        # 2) Wenn Mod-Liste keine Vanilla-DLL enthält -> Vanilla als Basis, Mod-DLLs zusätzlich.
        pset = {self._normalize_dll_name(x) for x in primary_dlls}
        fset = {self._normalize_dll_name(x) for x in fallback_dlls}
        has_overlap = bool(pset & fset)

        ordered: list[tuple[Path, str]] = []
        seen: set[str] = set()
        resolver = DllStringResolver()

        def _pick_ini_for_dll(
            dll_name: str,
            preferred_ini: Path | None,
            fallback_ini_local: Path | None,
        ) -> Path | None:
            # Prefer the configured order, but switch source ini if the DLL file
            # only exists on the fallback side.
            if preferred_ini is not None:
                try:
                    if resolver._resolve_dll_path(preferred_ini, dll_name) is not None:  # noqa: SLF001
                        return preferred_ini
                except Exception:
                    pass
            if fallback_ini_local is not None:
                try:
                    if resolver._resolve_dll_path(fallback_ini_local, dll_name) is not None:  # noqa: SLF001
                        return fallback_ini_local
                except Exception:
                    pass
            return preferred_ini or fallback_ini_local

        def _push(source_ini: Path | None, entries: list[str]) -> None:
            if source_ini is None and fallback_ini is None:
                return
            for dll in entries:
                key = self._normalize_dll_name(dll)
                if not key or key in seen or self._is_ignored_lookup_dll(dll):
                    continue
                seen.add(key)
                picked = _pick_ini_for_dll(dll, source_ini, fallback_ini if source_ini != fallback_ini else None)
                if picked is not None:
                    ordered.append((picked, dll))

        def _push_resources_dll(source_ini: Path | None) -> None:
            if source_ini is None:
                return
            dll = "resources.dll"
            key = self._normalize_dll_name(dll)
            if key in seen:
                return
            picked = _pick_ini_for_dll(dll, source_ini, fallback_ini if source_ini != fallback_ini else None)
            if picked is None:
                return
            seen.add(key)
            ordered.append((picked, dll))

        if primary_ini and (not fallback_dlls or has_overlap):
            _push(primary_ini, primary_dlls)
            _push_resources_dll(primary_ini)
            _push(fallback_ini, fallback_dlls)
            _push_resources_dll(fallback_ini)
            return ordered

        if fallback_ini:
            _push(fallback_ini, fallback_dlls)
            _push_resources_dll(fallback_ini)
        if primary_ini:
            _push(primary_ini, primary_dlls)
            _push_resources_dll(primary_ini)
        return ordered

    @staticmethod
    def _insert_resource_dll_line(raw_text: str, dll_name: str) -> tuple[str, bool]:
        lines = raw_text.splitlines()
        sec_start = -1
        sec_end = len(lines)
        for i, line in enumerate(lines):
            s = line.strip().lower()
            if s == "[resources]":
                sec_start = i
                for j in range(i + 1, len(lines)):
                    t = lines[j].strip()
                    if t.startswith("[") and t.endswith("]"):
                        sec_end = j
                        break
                break

        if sec_start < 0:
            out = lines[:]
            if out and out[-1].strip():
                out.append("")
            out.append("[Resources]")
            out.append(f"DLL = {dll_name}")
            return ("\n".join(out) + "\n"), True

        insert_at = sec_start + 1
        for i in range(sec_start + 1, sec_end):
            if lines[i].strip().lower().startswith("dll"):
                insert_at = i + 1
        out = lines[:insert_at] + [f"DLL = {dll_name}"] + lines[insert_at:]
        return ("\n".join(out) + "\n"), True

    @staticmethod
    def _remove_resource_dll_line(raw_text: str, dll_name: str) -> tuple[str, bool]:
        lines = raw_text.splitlines()
        target = MainWindow._normalize_dll_name(dll_name)
        out: list[str] = []
        removed = False
        for line in lines:
            s = str(line).strip()
            if "=" in s:
                k, v = s.split("=", 1)
                if k.strip().lower() == "dll":
                    dll = v.split(",", 1)[0].strip()
                    if MainWindow._normalize_dll_name(dll) == target:
                        removed = True
                        continue
            out.append(line)
        text = "\n".join(out)
        if text and not text.endswith("\n"):
            text += "\n"
        return text, removed

    @staticmethod
    def _normalize_dll_name(dll_name: str) -> str:
        return str(dll_name or "").strip().strip("\"'").replace("\\", "/").lower()

    @staticmethod
    def _entry_has_key(entries: list[tuple[str, str]], key: str) -> bool:
        target = str(key or "").strip().lower()
        if not target:
            return False
        for k, _v in entries:
            if str(k).strip().lower() == target:
                return True
        return False

    @staticmethod
    def _entry_set(entries: list[tuple[str, str]], key: str, value: str) -> list[tuple[str, str]]:
        out: list[tuple[str, str]] = []
        found = False
        target = str(key or "").strip().lower()
        for k, v in entries:
            if str(k).strip().lower() == target:
                out.append((k, str(value)))
                found = True
            else:
                out.append((k, v))
        if not found:
            out.append((str(key), str(value)))
        return out

    @staticmethod
    def _rc_escape(text: str) -> str:
        return (
            str(text or "")
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\r\n", "\\n")
            .replace("\n", "\\n")
        )

    @staticmethod
    def _decode_resource_text_blob(blob: bytes) -> str:
        if not blob:
            return ""
        if blob.startswith(b"\xff\xfe") or blob.startswith(b"\xfe\xff"):
            try:
                return blob.decode("utf-16", errors="ignore").strip()
            except Exception:
                pass
        if b"\x00" in blob:
            try:
                return blob.decode("utf-16le", errors="ignore").replace("\x00", "").strip()
            except Exception:
                pass
        for enc in ("utf-8", "cp1252", "latin-1"):
            try:
                return blob.decode(enc, errors="ignore").strip()
            except Exception:
                continue
        return ""

    def _load_dll_html_resources(self, dll_path: Path) -> dict[int, str]:
        out: dict[int, str] = {}
        if pefile is None or not dll_path or not dll_path.is_file():
            return out
        pe = None
        try:
            pe = pefile.PE(str(dll_path), fast_load=True)
            pe.parse_data_directories(
                directories=[pefile.DIRECTORY_ENTRY["IMAGE_DIRECTORY_ENTRY_RESOURCE"]]
            )
        except Exception:
            return out
        try:
            root = getattr(pe, "DIRECTORY_ENTRY_RESOURCE", None)
            if root is None:
                return out
            for type_entry in getattr(root, "entries", []):
                # RT_HTML = 23
                if getattr(type_entry, "id", None) != 23:
                    continue
                for name_entry in getattr(type_entry.directory, "entries", []):
                    local_id = getattr(name_entry, "id", None)
                    if not isinstance(local_id, int) or local_id <= 0:
                        continue
                    for lang_entry in getattr(name_entry.directory, "entries", []):
                        data_entry = getattr(lang_entry, "data", None)
                        if data_entry is None:
                            continue
                        rva = int(data_entry.struct.OffsetToData)
                        size = int(data_entry.struct.Size)
                        blob = pe.get_data(rva, size)
                        txt = self._decode_resource_text_blob(blob)
                        if txt:
                            out[int(local_id)] = txt
                        break
        finally:
            try:
                if pe is not None:
                    pe.close()
            except Exception:
                pass
        return out

    def _write_resource_dll_entries(
        self,
        dll_path: Path,
        strings_by_local_id: dict[int, str],
        infos_by_local_id: dict[int, str] | None = None,
    ) -> tuple[bool, str]:
        toolchain = self._resource_toolchain_commands()
        if toolchain is None:
            return (
                False,
                "No supported resource toolchain found "
                "(need llvm-windres+lld-link, llvm-rc+lld-link, or rc.exe+link.exe)",
            )
        cleaned: dict[int, str] = {}
        for k, v in strings_by_local_id.items():
            try:
                lid = int(k)
            except Exception:
                continue
            if lid <= 0:
                continue
            txt = str(v or "").strip()
            if txt:
                cleaned[lid] = txt
        info_cleaned: dict[int, str] = {}
        for k, v in dict(infos_by_local_id or {}).items():
            try:
                lid = int(k)
            except Exception:
                continue
            if lid <= 0:
                continue
            txt = str(v or "").strip()
            if txt:
                info_cleaned[lid] = txt
        if not cleaned and not info_cleaned:
            return False, "no strings to write"
        with tempfile.TemporaryDirectory(prefix="flatlas_ids_") as td:
            tdir = Path(td)
            rc_path, res_path, tmp_dll = write_resource_rc_bundle(
                tdir,
                strings_by_local_id=cleaned,
                infos_by_local_id=info_cleaned,
            )
            try:
                compile_cmd, link_cmd = toolchain(str(rc_path), str(res_path), str(tmp_dll))
                subprocess.run(
                    compile_cmd,
                    check=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                )
                subprocess.run(
                    link_cmd,
                    check=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                )
            except subprocess.CalledProcessError as exc:
                msg = exc.stderr.strip() or exc.stdout.strip() or str(exc)
                return False, msg
            try:
                dll_path.parent.mkdir(parents=True, exist_ok=True)
                last_err = None
                for _attempt in range(8):
                    try:
                        shutil.copy2(tmp_dll, dll_path)
                        last_err = None
                        break
                    except PermissionError as exc:
                        last_err = exc
                        time.sleep(0.15)
                    except OSError as exc:
                        last_err = exc
                        if getattr(exc, "winerror", None) in (5, 32, 33, 1224):
                            time.sleep(0.15)
                            continue
                        break
                if last_err is not None:
                    staged_path = dll_path.with_name(f"{dll_path.name}.new")
                    backup_path = dll_path.with_name(f"{dll_path.name}.bak")
                    try:
                        if staged_path.exists():
                            staged_path.unlink()
                        shutil.copy2(tmp_dll, staged_path)
                        if backup_path.exists():
                            backup_path.unlink()
                        if dll_path.exists():
                            dll_path.replace(backup_path)
                        staged_path.replace(dll_path)
                        last_err = None
                        try:
                            if backup_path.exists():
                                backup_path.unlink()
                        except Exception:
                            pass
                    except Exception:
                        try:
                            if staged_path.exists():
                                staged_path.unlink()
                        except Exception:
                            pass
                if last_err is not None:
                    raise last_err
            except Exception as exc:
                return False, str(exc)
        return True, ""

