    def _build_legend(self, layout: QVBoxLayout):
        from PySide6.QtWidgets import QSizePolicy
        self._status_grp = QGroupBox("")
        sgl = QHBoxLayout(self._status_grp)
        sgl.setContentsMargins(6, 1, 6, 1)
        self._status_history_btn = QPushButton("⋯")
        self._status_history_btn.setFixedWidth(28)
        self._status_history_btn.setToolTip(tr("tip.status_history"))
        self._status_history_btn.clicked.connect(self._open_status_history_dialog)
        self._status_info_lbl = QLabel("")
        self._status_info_lbl.setWordWrap(False)
        self._status_info_lbl.setStyleSheet("font-size:10pt; font-weight:600;")
        self._status_info_lbl.setMinimumHeight(16)
        self._status_info_lbl.setMaximumHeight(16)
        sgl.addWidget(self._status_info_lbl, 1)
        sgl.addWidget(self._status_history_btn)
        self._status_grp.setMinimumHeight(26)
        self._status_grp.setMaximumHeight(26)
        layout.addWidget(self._status_grp)
        # Nur einen sichtbaren Status-Standort nutzen (StatusBar unten).
        self._status_grp.setVisible(False)

        self.legend_box = QGroupBox(tr("grp.legend"))
        ll = QHBoxLayout(self.legend_box)
        ll.setContentsMargins(4, 2, 4, 2)
        ll.setSpacing(4)
        for col, key in _LEGEND_KEYS:
            if not col:
                ll.addSpacing(6)
                continue
            lbl = QLabel(f'<span style="color:{col}">■</span> {tr(key)}')
            lbl.setTextFormat(Qt.RichText)
            lbl.setStyleSheet("font-size:7pt;")
            ll.addWidget(lbl)
        # Legende kompakt halten, damit Statusmeldungen nicht verdeckt werden.
        self.legend_box.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Preferred)
        self.legend_box.setMaximumHeight(self.legend_box.sizeHint().height())
        self.statusBar().addPermanentWidget(self.legend_box, 0)
        self._build_loading_indicator()

    def _build_loading_indicator(self):
        if hasattr(self, "_loading_bar"):
            return
        host = getattr(self, "_global_loading_host", None)
        if host is None:
            return
        layout = QHBoxLayout(host)
        layout.setContentsMargins(10, 2, 10, 4)
        layout.setSpacing(8)
        self._loading_progress_row = host
        self._loading_track_bar = QProgressBar(host)
        self._loading_track_bar.setRange(0, 100)
        self._loading_track_bar.setValue(0)
        self._loading_track_bar.setTextVisible(False)
        self._loading_track_bar.setFixedHeight(8)
        self._loading_track_bar.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        layout.addWidget(self._loading_track_bar, 1)
        self._loading_percent_lbl = QLabel("0%", host)
        self._loading_percent_lbl.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        self._loading_percent_lbl.setMinimumWidth(40)
        layout.addWidget(self._loading_percent_lbl, 0)
        self._activity_tab_btn = QPushButton(tr("action.activity"), host)
        self._activity_tab_btn.setToolTip(tr("tip.activity_tab"))
        self._activity_tab_btn.clicked.connect(self._open_activity_view)
        self._activity_tab_btn.setMinimumWidth(84)
        layout.addWidget(self._activity_tab_btn, 0)
        self._loading_progress_row.setVisible(True)
        self._loading_bar = self._loading_track_bar
        self._loading_progress_timer = QTimer(self)
        self._loading_progress_timer.setInterval(70)
        self._loading_progress_timer.timeout.connect(self._advance_loading_progress)
        self._loading_bar.setValue(100)
        self._loading_percent_lbl.setText("100%")
        self._apply_global_nav_tab_style()

    def _set_loading_visible(self, visible: bool, message: str | None = None):
        if not hasattr(self, "_loading_bar"):
            return
        if visible:
            self._loading_depth += 1
            if self._loading_depth == 1:
                self._loading_progress_value = 0
                self._loading_progress_target = 92
                self._apply_loading_bar_palette(True)
                self._apply_loading_label_palette(True)
                self._set_loading_progress(4)
                self._loading_progress_timer.start()
            if message:
                self.statusBar().showMessage(message)
            QApplication.processEvents()
            return
        self._loading_depth = max(0, int(getattr(self, "_loading_depth", 0)) - 1)
        if self._loading_depth == 0:
            self._loading_progress_timer.stop()
            self._set_loading_progress(100)
            QTimer.singleShot(180, self._finalize_loading_indicator)
            QApplication.processEvents()

    def _set_loading_progress(self, value: int | float, message: str | None = None):
        if not hasattr(self, "_loading_bar"):
            return
        pct = max(0, min(int(round(float(value))), 100))
        self._loading_progress_value = pct
        self._loading_bar.setValue(pct)
        if hasattr(self, "_loading_percent_lbl"):
            self._loading_percent_lbl.setText(f"{pct}%")
        if message:
            self.statusBar().showMessage(message)

    def _on_view3d_native_preview_progress(self, payload: dict[str, object]) -> None:
        self._update_native_preview_status_label(payload)
        total = max(0, int(payload.get("total", 0) or 0))
        done = max(0, min(total, int(payload.get("done", 0) or 0)))
        active = bool(payload.get("active", False)) and total > 0
        is_current_3d = bool(
            hasattr(self, "center_stack")
            and hasattr(self, "view3d")
            and self.center_stack.currentWidget() is self.view3d
        )
        if not is_current_3d:
            active = False
        was_active = bool(getattr(self, "_view3d_native_preview_loading_active", False))
        if active and not was_active:
            self._view3d_native_preview_loading_active = True
            self._set_loading_visible(True, tr("status.loading_3d_objects"))
        if active:
            pct = 8 + int(round((float(done) / max(1.0, float(total))) * 84.0))
            self._set_loading_progress(
                pct,
                tr("status.loading_3d_objects_progress").format(done=done, total=total),
            )
            return
        if was_active:
            self._view3d_native_preview_loading_active = False
            self._set_loading_visible(False)

    def _advance_loading_progress(self):
        if int(getattr(self, "_loading_depth", 0)) <= 0:
            return
        current = int(getattr(self, "_loading_progress_value", 0))
        target = max(current, int(getattr(self, "_loading_progress_target", 92)))
        if current >= target:
            return
        remaining = max(1, target - current)
        step = 1 if remaining < 6 else 2 if remaining < 18 else 3
        self._set_loading_progress(min(target, current + step))

    def _finalize_loading_indicator(self):
        if int(getattr(self, "_loading_depth", 0)) != 0:
            return
        self._loading_progress_value = 100
        self._loading_progress_target = 100
        self._loading_bar.setValue(100)
        self._apply_loading_bar_palette(False)
        self._apply_loading_label_palette(False)
        if hasattr(self, "_loading_percent_lbl"):
            self._loading_percent_lbl.setText("100%")

    def _pump_ui(self, message: str | None = None):
        if message:
            self.statusBar().showMessage(message)
        QApplication.processEvents()

    def _make_mod_manager_progress(self, label: str, maximum: int) -> QProgressDialog:
        dlg = QProgressDialog(label, "", 0, max(0, int(maximum)), self)
        dlg.setWindowTitle(tr("mod_manager.title"))
        dlg.setWindowModality(Qt.WindowModal)
        dlg.setCancelButton(None)
        dlg.setMinimumDuration(0)
        dlg.setAutoClose(False)
        dlg.setAutoReset(False)
        dlg.setValue(0)
        dlg.setLabelText(label)
        dlg.setMinimumWidth(420)
        dlg.resize(520, 110)
        dlg.setProperty("mm_progress_counter", 0)
        dlg.setProperty("mm_progress_last_ui_flush", 0.0)
        self._set_loading_visible(True, label)
        self._set_loading_progress(0, label)
        QApplication.processEvents()
        return dlg

    def _flush_mod_manager_progress_ui(self, dlg: QProgressDialog, *, force: bool = False) -> None:
        if not hasattr(dlg, "property") or not hasattr(dlg, "setProperty"):
            QApplication.processEvents()
            return
        now = time.monotonic()
        last = float(dlg.property("mm_progress_last_ui_flush") or 0.0)
        if force or (now - last) >= 0.05:
            dlg.setProperty("mm_progress_last_ui_flush", now)
            QApplication.processEvents()

    def _append_mod_manager_progress_action(
        self,
        dlg: QProgressDialog,
        action: str,
        *,
        ok: bool = True,
    ) -> None:
        action_text = str(action or "").strip()
        if not action_text:
            return
        if not hasattr(dlg, "property") or not hasattr(dlg, "setProperty"):
            return
        counter = int(dlg.property("mm_progress_counter") or 0) + 1
        dlg.setProperty("mm_progress_counter", counter)
        self._flush_mod_manager_progress_ui(dlg)

    def _update_mod_manager_progress(
        self,
        dlg: QProgressDialog,
        value: int,
        *,
        template: str,
        path: str = "",
    ) -> None:
        maximum = max(1, int(dlg.maximum()))
        current = max(0, min(int(value), maximum))
        pct = int(round((current / maximum) * 100.0))
        shown_path = str(path or "").strip()
        if shown_path:
            label = str(template).format(path=shown_path, percent=pct)
        else:
            label = str(template).format(percent=pct)
        dlg.setLabelText(label)
        dlg.setValue(current)
        self._set_loading_progress(pct, label)
        self._flush_mod_manager_progress_ui(dlg, force=current >= maximum)

    def _build_flight_sidebar(self):
        self._flight_info_dock = QDockWidget(tr("flight.hud_title"), self)
        self._flight_info_dock.setAllowedAreas(Qt.LeftDockWidgetArea)
        self._flight_info_dock.setFeatures(QDockWidget.NoDockWidgetFeatures)
        host = QWidget(self._flight_info_dock)
        l = QVBoxLayout(host)
        l.setContentsMargins(6, 6, 6, 6)
        self.flight_free_btn = QPushButton(tr("flight.btn.free"), host)
        self.flight_free_btn.clicked.connect(self._on_flight_free_clicked)
        l.addWidget(self.flight_free_btn)
        self.flight_approach_btn = QPushButton(tr("flight.btn.approach"), host)
        self.flight_approach_btn.clicked.connect(self._on_flight_approach_clicked)
        l.addWidget(self.flight_approach_btn)
        self.flight_dock_btn = QPushButton(tr("flight.btn.dock"), host)
        self.flight_dock_btn.clicked.connect(self._on_flight_dock_clicked)
        l.addWidget(self.flight_dock_btn)
        self.flight_cam_dist_lbl = QLabel(tr("flight.cam_distance").format(mult="1.8"), host)
        l.addWidget(self.flight_cam_dist_lbl)
        self.flight_cam_dist_slider = QSlider(Qt.Horizontal, host)
        self.flight_cam_dist_slider.setRange(5, 80)  # 0.5x .. 8.0x Schifflänge
        self.flight_cam_dist_slider.setSingleStep(1)
        self.flight_cam_dist_slider.setPageStep(5)
        self.flight_cam_dist_slider.setValue(18)
        self.flight_cam_dist_slider.valueChanged.connect(self._on_flight_cam_distance_changed)
        l.addWidget(self.flight_cam_dist_slider)
        self.flight_info_view = QTextEdit(host)
        self.flight_info_view.setReadOnly(True)
        self.flight_info_view.setMinimumWidth(250)
        self.flight_info_view.setPlainText(tr("flight.hud_title"))
        l.addWidget(self.flight_info_view)
        self._flight_info_dock.setWidget(host)
        self.addDockWidget(Qt.LeftDockWidgetArea, self._flight_info_dock)
        self._flight_info_dock.hide()

    def _on_flight_free_clicked(self):
        if hasattr(self, "view3d") and hasattr(self.view3d, "flight_set_freeflight"):
            self.view3d.flight_set_freeflight()

    def _on_flight_approach_clicked(self):
        if hasattr(self, "view3d") and hasattr(self.view3d, "flight_start_autopilot_selected"):
            self.view3d.flight_start_autopilot_selected()

    def _on_flight_dock_clicked(self):
        if hasattr(self, "view3d") and hasattr(self.view3d, "flight_dock_selected_tradelane"):
            self.view3d.flight_dock_selected_tradelane()

    def _on_flight_cam_distance_changed(self, value: int):
        dist = float(value) / 10.0
        if hasattr(self, "flight_cam_dist_lbl"):
            self.flight_cam_dist_lbl.setText(tr("flight.cam_distance").format(mult=f"{dist:.1f}"))
        if hasattr(self, "view3d") and hasattr(self.view3d, "flight_set_chase_distance_ship_lengths"):
            self.view3d.flight_set_chase_distance_ship_lengths(dist)

    # ==================================================================
    #  Toolbar-Button-Style (aus aktuellem Theme generiert)
    # ==================================================================
    def _make_tb_btn_style(self) -> str:
        p = get_palette(current_theme())
        return (
            f"QToolButton, QPushButton {{ background:{p['btn_bg']}; border:1px solid {p['border_light']};"
            f" color:{p['fg']}; padding:4px 10px; border-radius:3px; font-weight:bold; }}"
            f" QToolButton:hover, QPushButton:hover {{ background:{p['btn_hover']}; }}"
            " QToolButton::menu-indicator { image:none; }"
        )

    def _apply_write_button_state_style(self):
        if not hasattr(self, "write_btn") or self.write_btn is None:
            return
        can_save = bool(self._filepath) and bool(self._dirty) and not self._flight_lock_active
        if can_save:
            self.write_btn.setStyleSheet(
                "QPushButton { background:#6a4f00; border:1px solid #d4af37;"
                " color:#ffdf80; padding:4px 10px; border-radius:3px; font-weight:bold; }"
                " QPushButton:hover { background:#8a6800; }"
            )
        else:
            self.write_btn.setStyleSheet(
                "QPushButton { background:#3a3a3a; border:1px solid #5a5a5a;"
                " color:#9a9a9a; padding:4px 10px; border-radius:3px; font-weight:bold; }"
                " QPushButton:hover { background:#3a3a3a; }"
                " QPushButton:disabled { background:#3a3a3a; color:#9a9a9a; }"
            )

    # ==================================================================
    #  Theme wechseln
    # ==================================================================
    def _on_theme_changed(self, theme_name: str):
        from PySide6.QtWidgets import QColorDialog
        if theme_name == "custom":
            cur = self._cfg.get("custom_accent", "#5060c0")
            color = QColorDialog.getColor(QColor(cur), self, tr("theme.pick_color"))
            if not color.isValid():
                return
            self._cfg.set("custom_accent", color.name(QColor.NameFormat.HexRgb))
        # Alle Häkchen aktualisieren
        for n, act in self._theme_actions.items():
            act.setChecked(n == theme_name)
        apply_theme(self, theme_name)
        # Persistenz zusätzlich über MainWindow-Config sicherstellen.
        self._cfg.set("theme", current_theme())
        self._apply_global_nav_tab_style()
        self._apply_active_mod_label_style()
        self._apply_trade_preview_theme()
        if hasattr(self, "ini_code_edit"):
            self.ini_code_edit.refresh_theme()
        if hasattr(self, "_ini_highlighter"):
            self._ini_highlighter.refresh_theme()
        if hasattr(self, "_ini_minimap"):
            self._ini_minimap.refresh_theme()
        if hasattr(self, "view") and hasattr(self.view, "_scene"):
            self._apply_scene_wallpaper()
            self._refresh_scene_theme_labels()
        # Toolbar-Button-Style aktualisieren
        self._tb_btn_style = self._make_tb_btn_style()
        for w in (
            self.new_system_btn, self.uni_save_btn, self.uni_undo_btn,
            self.uni_delete_btn, self.ids_scan_btn, self.ids_import_btn,
            self.flight_mode_btn, self.sys_settings_btn
        ):
            if w is not None:
                w.setStyleSheet(self._tb_btn_style)
        self._apply_write_button_state_style()
        for n, act in getattr(self, "_theme_actions", {}).items():
            act.setChecked(n == theme_name)
        self._build_standard_menu_bar()

