    def _set_language(self, lang: str):
        if not lang:
            return
        set_language(lang)
        self._cfg.set("language", lang)
        self._retranslate_ui()

    def _on_language_toggled(self):
        new_lang = "en" if get_language() == "de" else "de"
        self._set_language(new_lang)

