    @staticmethod
    def _default_infocard_xml_template() -> str:
        return default_infocard_xml_template()

    @staticmethod
    def _escape_xml_text(value: str) -> str:
        return escape_xml_text(value)

    @staticmethod
    def _xml_to_plain_preview(xml_text: str) -> str:
        return xml_to_plain_preview(xml_text)

    @staticmethod
    def _infocard_flags_to_css(flags: int) -> str:
        return infocard_flags_to_css(flags)

    @staticmethod
    def _infocard_normalize_align(loc: str) -> str:
        return infocard_normalize_align(loc)

    @staticmethod
    def _infocard_normalize_color(value: str) -> str:
        return infocard_normalize_color(value)

    def _info_builder_pick_color(self):
        cur = self._infocard_normalize_color(self.info_builder_color_edit.text())
        start = QColor(cur if cur != "default" else "#FFFFFF")
        picked = QColorDialog.getColor(start, self, tr("theme.pick_color"))
        if not picked.isValid():
            return
        color_name = picked.name().upper()
        self.info_builder_color_edit.setText(color_name)
        if hasattr(self, "info_live_edit"):
            fmt = QTextCharFormat()
            fmt.setForeground(QBrush(QColor(color_name)))
            cur_txt = self.info_live_edit.textCursor()
            cur_txt.mergeCharFormat(fmt)
            self.info_live_edit.mergeCurrentCharFormat(fmt)

    def _info_builder_reset_color(self):
        self.info_builder_color_edit.setText("default")
        if hasattr(self, "info_live_edit"):
            fmt = QTextCharFormat()
            fmt.clearForeground()
            cur_txt = self.info_live_edit.textCursor()
            cur_txt.mergeCharFormat(fmt)
            self.info_live_edit.mergeCurrentCharFormat(fmt)

    @staticmethod
    def _infocard_apply_tra_to_state(state: dict[str, str | int], attrs: dict[str, str]) -> None:
        infocard_apply_tra_to_state(state, attrs)

    def _render_infocard_xml_to_html(self, xml_text: str) -> str:
        raw = str(xml_text or "").strip()
        if not raw:
            return "<div></div>"
        try:
            root = ET.fromstring(raw)
        except Exception:
            safe = html.escape(raw)
            return f"<pre style='white-space:pre-wrap;margin:0'>{safe}</pre>"
        if str(root.tag).strip().upper() != "RDL":
            safe = html.escape(raw)
            return f"<pre style='white-space:pre-wrap;margin:0'>{safe}</pre>"

        state_stack: list[dict[str, str | int]] = [{"align": "left", "flags": 0, "color": "default"}]
        paragraphs: list[tuple[str, str]] = []
        segs: list[str] = []

        def cur_state() -> dict[str, str | int]:
            return state_stack[-1]

        def flush_para():
            nonlocal segs
            if not segs:
                return
            align = self._infocard_normalize_align(str(cur_state().get("align", "left") or "left"))
            paragraphs.append((align, "".join(segs)))
            segs = []

        for node in list(root):
            tag = str(node.tag or "").strip().upper()
            if tag == "PUSH":
                state_stack.append(dict(cur_state()))
                continue
            if tag == "POP":
                flush_para()
                if len(state_stack) > 1:
                    state_stack.pop()
                continue
            if tag == "JUST":
                cur_state()["align"] = self._infocard_normalize_align(str(node.attrib.get("loc", "") or ""))
                continue
            if tag == "TRA":
                attrs = {str(k).strip().lower(): str(v) for k, v in node.attrib.items()}
                self._infocard_apply_tra_to_state(cur_state(), attrs)
                continue
            if tag == "PARA":
                flush_para()
                continue
            if tag == "TEXT":
                txt = str(node.text or "")
                if txt:
                    css = self._infocard_flags_to_css(int(cur_state().get("flags", 0) or 0))
                    color = self._infocard_normalize_color(str(cur_state().get("color", "default")))
                    if color != "default":
                        css += f"color:{color};"
                    segs.append(f"<span style=\"{css}\">{html.escape(txt)}</span>")
                continue
            txt = str(node.text or "").strip()
            if txt:
                segs.append(html.escape(txt))
        flush_para()
        if not paragraphs:
            return "<div></div>"
        out: list[str] = ["<div style='font-family:Segoe UI,Arial,sans-serif;line-height:1.35'>"]
        for align, content in paragraphs:
            out.append(f"<p style='margin:0 0 8px 0; text-align:{align}'>{content}</p>")
        out.append("</div>")
        return "".join(out)

    def _info_set_live_error_state(self, is_error: bool):
        if not hasattr(self, "info_live_edit"):
            return
        if is_error:
            self.info_live_edit.setStyleSheet("QTextEdit { border: 2px solid #d64a4a; }")
        else:
            self.info_live_edit.setStyleSheet("")

    def _info_apply_rdl_xml_to_live(self, xml_text: str):
        html_text = self._render_infocard_xml_to_html(xml_text)
        self.info_live_edit.blockSignals(True)
        self.info_live_edit.setHtml(html_text)
        self.info_live_edit.blockSignals(False)

    def _info_live_to_rdl_xml(self) -> str:
        doc = self.info_live_edit.document()
        lines: list[str] = ["<RDL>", "  <PUSH/>"]
        block = doc.begin()
        first_block = True
        while block.isValid():
            text = block.text()
            if first_block:
                first_block = False
            else:
                lines.append("  <PARA />")
            align = block.blockFormat().alignment()
            if align & Qt.AlignHCenter:
                loc = "c"
            elif align & Qt.AlignRight:
                loc = "r"
            else:
                loc = "l"
            lines.append(f"  <JUST loc=\"{loc}\" />")
            it = block.begin()
            emitted = False
            while not it.atEnd():
                frag = it.fragment()
                if frag.isValid():
                    frag_text = str(frag.text() or "")
                    if frag_text:
                        fmt = frag.charFormat()
                        bold = "true" if fmt.fontWeight() >= QFont.Bold else "false"
                        italic = "true" if fmt.fontItalic() else "false"
                        underline = "true" if fmt.fontUnderline() else "false"
                        col = fmt.foreground().color()
                        col_txt = "default"
                        if col.isValid():
                            name = col.name().upper()
                            if name and name != "#000000":
                                col_txt = name
                        lines.append(f"  <TRA bold=\"{bold}\" italic=\"{italic}\" underline=\"{underline}\" color=\"{col_txt}\" />")
                        lines.append(f"  <TEXT>{self._escape_xml_text(frag_text)}</TEXT>")
                        emitted = True
                it += 1
            if not emitted and text:
                lines.append("  <TRA bold=\"false\" italic=\"false\" underline=\"false\" color=\"default\" />")
                lines.append(f"  <TEXT>{self._escape_xml_text(text)}</TEXT>")
            block = block.next()
        lines.extend(["  <POP />", "</RDL>"])
        return "\n".join(lines)

    def _info_xml_text_changed(self):
        if self._info_sync_busy:
            return
        xml_text = self.info_xml_edit.toPlainText()
        try:
            ET.fromstring(xml_text)
        except Exception:
            self._info_set_live_error_state(True)
            return
        self._info_sync_busy = True
        try:
            self._info_apply_rdl_xml_to_live(xml_text)
            self._info_set_live_error_state(False)
        finally:
            self._info_sync_busy = False

    def _info_live_text_changed(self):
        if self._info_sync_busy:
            return
        self._info_sync_busy = True
        try:
            xml_text = self._info_live_to_rdl_xml()
            self.info_xml_edit.blockSignals(True)
            self.info_xml_edit.setPlainText(xml_text)
            self.info_xml_edit.blockSignals(False)
            self._info_set_live_error_state(False)
        finally:
            self._info_sync_busy = False

    def _build_infocard_xml_from_fields(self, title: str, body: str, align: str, flags: int, color: str) -> str:
        return build_infocard_xml_from_fields(title, body, align, flags, color)

    def _extract_infocard_fields_from_xml(self, xml_text: str) -> dict[str, str | int]:
        out: dict[str, str | int] = {"title": "", "body": "", "align": "left", "flags": 0, "color": "default"}
        raw = str(xml_text or "").strip()
        if not raw:
            return out
        try:
            root = ET.fromstring(raw)
        except Exception:
            return out
        texts: list[str] = []
        for node in list(root):
            tag = str(node.tag or "").strip().upper()
            if tag == "JUST":
                if not texts:
                    out["align"] = self._infocard_normalize_align(str(node.attrib.get("loc", "") or ""))
            elif tag == "TRA":
                if not texts:
                    state = {"flags": int(out.get("flags", 0) or 0), "color": str(out.get("color", "default") or "default")}
                    attrs = {str(k).strip().lower(): str(v) for k, v in node.attrib.items()}
                    self._infocard_apply_tra_to_state(state, attrs)
                    out["flags"] = int(state.get("flags", 0) or 0)
                    out["color"] = str(state.get("color", "default") or "default")
            elif tag == "TEXT":
                txt = str(node.text or "").strip()
                if txt:
                    texts.append(txt)
        if texts:
            out["title"] = texts[0]
            if len(texts) > 1:
                out["body"] = "\n".join(texts[1:])
        return out

    def _info_live_set_char_style(self, key: str, enabled: bool):
        if not hasattr(self, "info_live_edit"):
            return
        fmt = QTextCharFormat()
        k = str(key or "").strip().lower()
        if k == "bold":
            fmt.setFontWeight(QFont.Bold if enabled else QFont.Normal)
        elif k == "italic":
            fmt.setFontItalic(bool(enabled))
        elif k == "underline":
            fmt.setFontUnderline(bool(enabled))
        else:
            return
        cur = self.info_live_edit.textCursor()
        cur.mergeCharFormat(fmt)
        self.info_live_edit.mergeCurrentCharFormat(fmt)

    def _info_builder_set_align(self, align: str):
        a = self._infocard_normalize_align(align)
        self.info_fmt_align_left_btn.setChecked(a == "left")
        self.info_fmt_align_center_btn.setChecked(a == "center")
        self.info_fmt_align_right_btn.setChecked(a == "right")
        if not hasattr(self, "info_live_edit"):
            return
        if a == "center":
            self.info_live_edit.setAlignment(Qt.AlignHCenter)
        elif a == "right":
            self.info_live_edit.setAlignment(Qt.AlignRight)
        else:
            self.info_live_edit.setAlignment(Qt.AlignLeft)

    def _populate_info_editor_data(self):
        cache_sig = (self._current_dll_lookup_signature(), self._preferred_resource_dll_name())
        if cache_sig == self._info_editor_cache_sig and self._info_editor_rows_cache:
            self._info_editor_rows = list(self._info_editor_rows_cache)
            self._info_editor_apply_filters()
            return
        preferred = self._preferred_resource_dll_name()
        preferred_slot = self._resource_slot_for_dll_name(preferred)
        rows: list[dict] = []
        resolver = DllStringResolver()
        for slot, (ini_path, dll_name) in enumerate(self._resource_dll_pairs_for_lookup(), start=1):
            dll_path = resolver._resolve_dll_path(Path(ini_path), str(dll_name))  # noqa: SLF001
            if not dll_path or not dll_path.is_file():
                continue
            local_infos = self._load_dll_html_resources_cached(dll_path)
            for lid, xml_text in local_infos.items():
                gid = DllStringResolver.make_global_id(int(slot), int(lid))
                rows.append(
                    {
                        "global_id": int(gid),
                        "local_id": int(lid),
                        "slot": int(slot),
                        "xml": str(xml_text),
                        "text": self._xml_to_plain_preview(str(xml_text)),
                        "dll": str(dll_name),
                        "editable": int(slot) == int(preferred_slot),
                    }
                )
        rows.sort(key=lambda r: int(r.get("global_id", 0)))
        self._info_editor_rows = rows
        self._info_editor_rows_cache = list(rows)
        self._info_editor_cache_sig = cache_sig
        self._info_editor_apply_filters()

    def _info_editor_apply_filters(self):
        if not hasattr(self, "info_ids_table"):
            return
        search = self.info_search_edit.text().strip().lower() if hasattr(self, "info_search_edit") else ""
        rows = self._info_editor_rows
        if search:
            rows = [
                r for r in rows
                if search in str(r.get("global_id", "")).lower()
                or search in str(r.get("text", "")).lower()
                or search in str(r.get("xml", "")).lower()
                or search in str(r.get("dll", "")).lower()
            ]
        tbl = self.info_ids_table
        self._info_editor_render_token += 1
        token = self._info_editor_render_token

        def _build_row(table: QTableWidget, row_index: int, row: dict):
            id_item = _NumericTableWidgetItem(int(row.get("global_id", 0)), decimals=0)
            id_item.setData(Qt.UserRole, row)
            table.setItem(row_index, 0, id_item)
            table.setItem(row_index, 1, QTableWidgetItem(str(row.get("text", ""))))
            table.setItem(row_index, 2, QTableWidgetItem(str(row.get("dll", ""))))
            table.setItem(row_index, 3, QTableWidgetItem(tr("name.yes") if bool(row.get("editable", False)) else tr("name.no")))

        self._render_table_rows_batched(
            tbl,
            rows,
            token_attr="_info_editor_render_token",
            token_value=token,
            row_builder=_build_row,
            select_first=True,
            empty_callback=self._clear_info_editor_selection_fields,
            finish_callback=self._info_editor_on_selection_changed,
        )

    def _clear_info_editor_selection_fields(self):
        self.info_selected_id_edit.setText("")
        self.info_dll_edit.setText("")
        self.info_live_edit.blockSignals(True)
        self.info_live_edit.clear()
        self.info_live_edit.blockSignals(False)

    def _info_editor_on_selection_changed(self):
        if not hasattr(self, "info_ids_table"):
            return
        row_idx = self.info_ids_table.currentRow()
        if row_idx < 0:
            self.info_selected_id_edit.setText("")
            self.info_dll_edit.setText("")
            self.info_live_edit.blockSignals(True)
            self.info_live_edit.clear()
            self.info_live_edit.blockSignals(False)
            return
        it = self.info_ids_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        if not isinstance(row, dict):
            return
        gid = int(row.get("global_id", 0) or 0)
        text = str(row.get("text", "") or "").strip() or "Infocard"
        self.info_selected_id_edit.setText(str(gid))
        self.info_dll_edit.setText(str(row.get("dll", "")))
        xml = str(row.get("xml", "") or "").strip()
        if not xml:
            xml = (
                "<RDL>\n"
                "  <PUSH/>\n"
                f"  <TEXT>{self._escape_xml_text(text)}</TEXT>\n"
                "  <PARA/>\n"
                f"  <TEXT>{self._escape_xml_text(tr('info.xml.placeholder.desc'))}</TEXT>\n"
                "  <POP/>\n"
                "</RDL>"
            )
        self.info_xml_edit.setPlainText(xml)

    def _info_editor_validate_xml(self):
        xml_text = self.info_xml_edit.toPlainText() if hasattr(self, "info_xml_edit") else ""
        try:
            ET.fromstring(xml_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("info.msg.invalid_xml.title"), tr("info.msg.invalid_xml.text").format(error=exc))
            return
        self._info_set_live_error_state(False)
        self.statusBar().showMessage(tr("info.status.validated"))

    def _info_editor_selected_row(self) -> dict | None:
        if not hasattr(self, "info_ids_table"):
            return None
        row_idx = self.info_ids_table.currentRow()
        if row_idx < 0:
            return None
        it = self.info_ids_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        return row if isinstance(row, dict) else None

    def _info_editor_jump_to_selected_usage(self):
        row = self._info_editor_selected_row()
        if row is None:
            return
        gid = int(row.get("global_id", 0) or 0)
        usage_rows = self._info_editor_usage_map.get(gid, [])
        jump_rows = [u for u in usage_rows if str(u.get("section", "")).strip().lower() in ("object", "zone")]
        if not jump_rows:
            self._show_non_system_usage_locations(usage_rows, "info.msg.no_jump_target", "info.msg.non_system_locations")
            return
        picked = self._choose_jump_usage(jump_rows, tr("info.msg.jump_choose_title"), tr("info.msg.jump_choose_text"))
        if picked is None:
            return
        if not self._jump_to_usage_entry(picked):
            QMessageBox.information(self, tr("msg.error"), tr("info.msg.no_jump_target"))

    def _info_editor_create_entry(self):
        xml_text = self.info_xml_edit.toPlainText().strip() if hasattr(self, "info_xml_edit") else ""
        if not xml_text:
            xml_text = self._default_infocard_xml_template()
            self.info_xml_edit.setPlainText(xml_text)
        try:
            new_gid = self._ensure_ids_info_in_user_dll("0", xml_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        self._populate_name_editor_data(self._primary_game_path())
        self.info_search_edit.setText(str(new_gid))
        self.statusBar().showMessage(tr("info.status.created").format(ids=new_gid))

    def _info_editor_update_selected(self):
        row = self._info_editor_selected_row()
        if row is None:
            return
        gid = str(row.get("global_id", "0"))
        xml_text = self.info_xml_edit.toPlainText().strip() if hasattr(self, "info_xml_edit") else ""
        if not xml_text:
            return
        try:
            new_gid = self._ensure_ids_info_in_user_dll(gid, xml_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        try:
            old_gid_int = int(str(gid).strip() or "0")
        except Exception:
            old_gid_int = 0
        try:
            new_gid_int = int(str(new_gid).strip() or "0")
        except Exception:
            new_gid_int = 0
        relink_files = 0
        relink_refs = 0
        if old_gid_int > 0 and new_gid_int > 0 and old_gid_int != new_gid_int:
            relink_files, relink_refs = self._relink_ids_info_references(old_gid_int, new_gid_int, self._primary_game_path())
        self._populate_name_editor_data(self._primary_game_path())
        self.info_search_edit.setText(str(new_gid))
        if relink_refs > 0:
            self.statusBar().showMessage(
                tr("info.status.saved_relinked").format(ids=new_gid, refs=relink_refs, files=relink_files)
            )
        else:
            self.statusBar().showMessage(tr("info.status.saved").format(ids=new_gid))

    def _open_name_editor_view(self):
        self._preserve_active_system_tab_document()
        game_path = self._data_lookup_game_path()
        if not game_path:
            self._warn_missing_game_path("msg.no_path")
            return

        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(**list_editor_layout(getattr(self, "left_name_panel", None))),
            nav_key="name",
            current_widget=self.name_editor_page,
            title=tr("app.title_name_editor"),
            apply_toolbar=True,
        )

        start_async_view_load(
            self,
            key="name-editor",
            worker=lambda gp=str(game_path): self._collect_name_editor_payload(gp),
            apply_result=self._apply_name_editor_payload,
            prepare_ui=self._name_editor_clear_for_loading,
            loading_message=tr("status.loading"),
            error_title=tr("msg.load_error"),
        )

    def _collect_name_editor_payload(self, game_path: str) -> dict[str, object]:
        self._reload_dll_name_cache()
        preferred = self._preferred_resource_dll_name()
        preferred_slot = self._resource_slot_for_dll_name(preferred)
        name_rows: list[dict] = []
        for slot, dll_name in sorted(self._dll_resolver.slot_to_dll.items(), key=lambda x: int(x[0])):
            loc = self._dll_resolver.slot_strings(slot)
            for lid, txt in loc.items():
                gid = DllStringResolver.make_global_id(int(slot), int(lid))
                name_rows.append(
                    {
                        "global_id": int(gid),
                        "text": str(txt),
                        "dll": str(dll_name),
                        "editable": int(slot) == int(preferred_slot),
                    }
                )
        name_rows.sort(key=lambda r: int(r.get("global_id", 0)))

        info_cache_sig = (self._current_dll_lookup_signature(), self._preferred_resource_dll_name())
        cached_info_rows = list(self._info_editor_rows_cache) if info_cache_sig == self._info_editor_cache_sig and self._info_editor_rows_cache else None
        if cached_info_rows is not None:
            info_rows = cached_info_rows
        else:
            info_rows = []
            resolver = DllStringResolver()
            for slot, (ini_path, dll_name) in enumerate(self._resource_dll_pairs_for_lookup(), start=1):
                dll_path = resolver._resolve_dll_path(Path(ini_path), str(dll_name))  # noqa: SLF001
                if not dll_path or not dll_path.is_file():
                    continue
                local_infos = self._load_dll_html_resources_cached(dll_path)
                for lid, xml_text in local_infos.items():
                    gid = DllStringResolver.make_global_id(int(slot), int(lid))
                    info_rows.append(
                        {
                            "global_id": int(gid),
                            "local_id": int(lid),
                            "slot": int(slot),
                            "xml": str(xml_text),
                            "text": self._xml_to_plain_preview(str(xml_text)),
                            "dll": str(dll_name),
                            "editable": int(slot) == int(preferred_slot),
                        }
                    )
            info_rows.sort(key=lambda r: int(r.get("global_id", 0)))

        return {
            "name_rows": name_rows,
            "missing_rows": self._scan_missing_ids_rows(game_path),
            "usage_map": self._scan_ids_usage_map(game_path),
            "info_usage_map": self._scan_ids_info_usage_map(game_path),
            "info_rows": info_rows,
            "info_cache_sig": info_cache_sig,
        }

    def _apply_name_editor_payload(self, payload: dict[str, object]):
        self._name_editor_name_rows = list(payload.get("name_rows", []))
        self._name_editor_missing_rows = list(payload.get("missing_rows", []))
        self._name_editor_usage_map = dict(payload.get("usage_map", {}))
        self._info_editor_usage_map = dict(payload.get("info_usage_map", {}))
        self._info_editor_rows = list(payload.get("info_rows", []))
        self._info_editor_rows_cache = list(self._info_editor_rows)
        self._info_editor_cache_sig = payload.get("info_cache_sig")
        self._name_editor_apply_filters()
        self._name_editor_render_usage_rows([])
        self._name_editor_render_missing_rows()
        self._info_editor_apply_filters()
        self.statusBar().showMessage(tr("status.name_editor_opened"))

    def _name_editor_clear_for_loading(self):
        self._name_editor_render_token += 1
        self._name_missing_render_token += 1
        self._info_editor_render_token += 1
        self._name_editor_name_rows = []
        self._name_editor_missing_rows = []
        self._name_editor_usage_map = {}
        self._info_editor_usage_map = {}
        self._info_editor_rows = []
        if hasattr(self, "name_ids_table"):
            self.name_ids_table.setRowCount(0)
        if hasattr(self, "name_missing_table"):
            self.name_missing_table.setRowCount(0)
        if hasattr(self, "name_usage_table"):
            self.name_usage_table.setRowCount(0)
        if hasattr(self, "info_ids_table"):
            self.info_ids_table.setRowCount(0)
        if hasattr(self, "name_selected_id_edit"):
            self.name_selected_id_edit.setText("")
        if hasattr(self, "name_text_edit"):
            self.name_text_edit.setText("")
        if hasattr(self, "info_selected_id_edit"):
            self.info_selected_id_edit.setText("")
        if hasattr(self, "info_dll_edit"):
            self.info_dll_edit.setText("")
        if hasattr(self, "info_live_edit"):
            self.info_live_edit.blockSignals(True)
            self.info_live_edit.clear()
            self.info_live_edit.blockSignals(False)

    def _render_table_rows_batched(
        self,
        table: QTableWidget,
        rows: list[dict],
        *,
        token_attr: str,
        token_value: int,
        row_builder,
        select_first: bool = False,
        empty_callback=None,
        finish_callback=None,
        batch_size: int = 250,
    ):
        if not isValid(table):
            return
        table.setSortingEnabled(False)
        table.setRowCount(0)
        index = 0

        def _step():
            nonlocal index
            if getattr(self, token_attr, 0) != token_value or not isValid(table):
                return
            end = min(index + batch_size, len(rows))
            table.setUpdatesEnabled(False)
            for row in rows[index:end]:
                current = table.rowCount()
                table.insertRow(current)
                row_builder(table, current, row)
            table.setUpdatesEnabled(True)
            table.viewport().update()
            index = end
            if index < len(rows):
                QTimer.singleShot(0, _step)
                return
            table.setSortingEnabled(True)
            if table.rowCount() > 0 and select_first:
                table.setCurrentCell(0, 0)
                table.selectRow(0)
                if finish_callback is not None:
                    QTimer.singleShot(0, finish_callback)
            elif table.rowCount() == 0 and empty_callback is not None:
                empty_callback()
            elif finish_callback is not None:
                QTimer.singleShot(0, finish_callback)

        QTimer.singleShot(0, _step)

    def _build_ini_editor_page(self):
        self.ini_editor_page = build_ini_editor_page(
            self,
            tr=tr,
            code_editor_factory=_IniCodeEditor,
            highlighter_factory=_IniSyntaxHighlighter,
            minimap_factory=_IniMiniMap,
        )

    def _ini_editor_context_root(self) -> Path | None:
        return ini_editor_context_root(
            self._mod_manager_editing_profile(),
            self._mod_manager_selected_profile(),
            self._mod_manager_profile_source,
        )

    def _ini_editor_reload_tree(self):
        root_path = self._ini_editor_context_root()
        fallback_root_path = None
        fallback_txt = str(self._fallback_game_path() or "").strip()
        if self._is_overlay_mode() and fallback_txt:
            candidate = Path(fallback_txt)
            if candidate.exists() and candidate.is_dir():
                fallback_root_path = candidate
        self.ini_tree.clear()
        self.ini_sections_list.clear()
        self._ini_editor_current_file = ""
        self._ini_editor_dirty = False
        self._ini_editor_current_tree_item = None
        self._ini_editor_fallback_root = str(fallback_root_path) if fallback_root_path is not None else ""
        self.ini_save_btn.setEnabled(False)
        if root_path is None:
            self.ini_root_path_lbl.setText(tr("ini.no_root"))
            self.ini_code_edit.setPlainText("")
            self._ini_editor_refresh_status_summary()
            return
        self._ini_editor_root = str(root_path)
        if fallback_root_path is not None:
            self.ini_root_path_lbl.setText(f"{root_path}  |  fallback: {fallback_root_path}")
        else:
            self.ini_root_path_lbl.setText(str(root_path))
        provider = QFileIconProvider()

        try:
            root_entry = IniTreeEntry(path=root_path, entry_type="dir", source="primary")
            top = self._ini_editor_add_tree_entry(None, root_entry, provider)
            self._ini_editor_populate_tree_children(top, root_path, fallback_root_path, provider)
            top.setExpanded(True)
        except Exception as ex:
            self.ini_root_path_lbl.setText(f"{root_path} ({ex})")
        self._ini_editor_refresh_status_summary()

    def _ini_editor_add_tree_entry(
        self,
        parent_item: QTreeWidgetItem | None,
        entry: IniTreeEntry,
        provider: QFileIconProvider,
    ) -> QTreeWidgetItem:
        source = str(getattr(entry, "source", "primary") or "primary").strip().lower()
        label = self._ini_editor_tree_entry_label(entry.path, entry.entry_type, source)
        mod_time = ""
        if entry.entry_type == "file":
            try:
                from datetime import datetime
                mtime = datetime.fromtimestamp(entry.path.stat().st_mtime)
                mod_time = mtime.strftime("%Y-%m-%d %H:%M")
            except Exception:
                pass
        item = QTreeWidgetItem([label, mod_time])
        item.setData(0, Qt.UserRole, str(entry.path))
        item.setData(0, Qt.UserRole + 1, entry.entry_type)
        item.setData(0, Qt.UserRole + 2, source)
        item.setData(0, Qt.UserRole + 3, False)
        item.setData(0, Qt.UserRole + 4, str(entry.path if entry.entry_type == "dir" else entry.path.parent))
        item.setData(0, Qt.UserRole + 5, "")
        item.setIcon(0, provider.icon(QFileInfo(str(entry.path))))
        if source == "fallback" and entry.entry_type == "file":
            item.setForeground(0, QBrush(QColor("#7a5a00")))
        if parent_item is None:
            self.ini_tree.addTopLevelItem(item)
        else:
            parent_item.addChild(item)
        if entry.entry_type == "dir" and entry.children:
            for child in entry.children:
                self._ini_editor_add_tree_entry(item, child, provider)
            item.setData(0, Qt.UserRole + 3, True)
        return item

    def _ini_editor_set_dir_loading_state(self, item: QTreeWidgetItem, has_children: bool):
        item.takeChildren()
        if has_children:
            item.setChildIndicatorPolicy(QTreeWidgetItem.ShowIndicator)
            item.addChild(QTreeWidgetItem([""]))
        else:
            item.setChildIndicatorPolicy(QTreeWidgetItem.DontShowIndicatorWhenChildless)

    def _ini_editor_populate_tree_children(
        self,
        item: QTreeWidgetItem,
        primary_dir: Path | None,
        fallback_dir: Path | None,
        provider: QFileIconProvider | None = None,
    ):
        if provider is None:
            provider = QFileIconProvider()
        item.takeChildren()
        children = list_ini_tree_entries_with_fallback(primary_dir or Path(), fallback_dir)
        for child in children:
            child_item = self._ini_editor_add_tree_entry(item, child, provider)
            if child.entry_type == "dir":
                child_primary = child.path if child.source == "primary" else None
                child_fallback = child.path if child.source == "fallback" else None
                if child_primary is not None and fallback_dir is not None:
                    fb_candidate = fallback_dir / child.path.name
                    if fb_candidate.exists() and fb_candidate.is_dir():
                        child_fallback = fb_candidate
                elif child_fallback is not None and primary_dir is not None:
                    pri_candidate = primary_dir / child.path.name
                    if pri_candidate.exists() and pri_candidate.is_dir():
                        child_primary = pri_candidate
                child_item.setData(0, Qt.UserRole + 4, str(child_primary) if child_primary is not None else "")
                child_item.setData(0, Qt.UserRole + 5, str(child_fallback) if child_fallback is not None else "")
                try:
                    has_children = bool(next(iter(child.path.iterdir()), None))
                except Exception:
                    has_children = False
                if not has_children and child_fallback is not None and child_fallback != child.path:
                    try:
                        has_children = bool(next(iter(Path(child_fallback).iterdir()), None))
                    except Exception:
                        has_children = False
                self._ini_editor_set_dir_loading_state(child_item, has_children)
        item.setData(0, Qt.UserRole + 3, True)

    def _ini_editor_on_tree_item_expanded(self, item: QTreeWidgetItem):
        if item is None:
            return
        if str(item.data(0, Qt.UserRole + 1) or "") != "dir":
            return
        if bool(item.data(0, Qt.UserRole + 3)):
            return
        primary_txt = str(item.data(0, Qt.UserRole + 4) or "").strip()
        fallback_txt = str(item.data(0, Qt.UserRole + 5) or "").strip()
        primary_dir = Path(primary_txt) if primary_txt else None
        fallback_dir = Path(fallback_txt) if fallback_txt else None
        try:
            self._ini_editor_populate_tree_children(item, primary_dir, fallback_dir)
        except Exception:
            item.takeChildren()
            item.setData(0, Qt.UserRole + 3, True)

    def _ini_editor_tab_key(self, path: str | Path) -> str:
        return f"ini-file:{self._mod_manager_normalized_path_key(path)}"

    def _ini_editor_tab_title(self, path: str | Path, dirty: bool = False) -> str:
        base = Path(path).name or str(path)
        return f"* {base}" if dirty else base

    def _ini_editor_tab_spec(self, key: str | None = None) -> dict[str, object] | None:
        specs = getattr(self, "_ini_file_tab_specs", [])
        if key is not None:
            for s in specs:
                if str(s.get("key", "") or "").strip() == str(key).strip():
                    return s
            return None
        return getattr(self, "_ini_file_current_spec", None)

    def _ini_editor_capture_tab_document(self, key: str | None = None):
        spec = self._ini_editor_tab_spec(key)
        if spec is None:
            return
        path = str(spec.get("path", "") or self._ini_editor_current_file or "").strip()
        if not path:
            return
        cursor_pos = 0
        if hasattr(self, "ini_code_edit"):
            try:
                cursor_pos = int(self.ini_code_edit.textCursor().position())
            except Exception:
                cursor_pos = 0
        doc = IniEditorDocument(
            path=path,
            text=self.ini_code_edit.toPlainText() if hasattr(self, "ini_code_edit") else "",
            dirty=bool(self._ini_editor_dirty),
            cursor_pos=cursor_pos,
            source=str(spec.get("source", "primary") or "primary").strip().lower(),
        )
        spec["document"] = doc
        spec["title"] = self._ini_editor_tab_title(path, dirty=doc.dirty)
        self._ini_file_tab_sync()

    def _ini_editor_apply_tab_document(self, spec: dict[str, object]):
        path = str(spec.get("path", "") or "").strip()
        if not path:
            return
        doc = spec.get("document")
        source = str(spec.get("source", "primary") or "primary").strip().lower()
        file_name = Path(path).name
        text = ""
        dirty = False
        cursor_pos = 0
        if isinstance(doc, IniEditorDocument) and str(doc.path or "").strip() == path:
            text = str(doc.text or "")
            dirty = bool(doc.dirty)
            cursor_pos = int(doc.cursor_pos or 0)
            source = str(doc.source or source).strip().lower()
        else:
            if not ini_editor_is_supported_text_file(path):
                if ini_editor_is_supported_model_file(path):
                    text = tr("ini.unsupported_model_placeholder").format(file=file_name)
                else:
                    text = tr("ini.unsupported_file_placeholder").format(file=file_name)
                dirty = False
            else:
                try:
                    ok, opened_path, loaded = ini_editor_open_file(path, self._read_text_best_effort)
                except Exception as ex:
                    QMessageBox.warning(self, tr("ini.title"), tr("ini.open_failed").format(error=ex))
                    return
                if not ok:
                    return
                path = str(opened_path)
                text = str(loaded)
                dirty = False
            doc = IniEditorDocument(path=path, text=text, dirty=dirty, cursor_pos=0, source=source)
            spec["document"] = doc
        self._ini_editor_opening_tab = True
        self._ini_editor_current_file = path if ini_editor_is_supported_text_file(path) else ""
        self._ini_editor_dirty = bool(dirty and ini_editor_is_supported_text_file(path))
        self.ini_save_btn.setEnabled(bool(self._ini_editor_dirty and self._ini_editor_current_file))
        if hasattr(self, "ini_discard_btn"):
            self.ini_discard_btn.setEnabled(bool(self._ini_editor_dirty and self._ini_editor_current_file))
        if not dirty:
            self._ini_editor_original_text = text
        self.ini_code_edit.blockSignals(True)
        self.ini_code_edit.setPlainText(text)
        self.ini_code_edit.blockSignals(False)
        if self._ini_editor_current_file and cursor_pos > 0:
            cur = self.ini_code_edit.textCursor()
            cur.setPosition(max(0, min(cursor_pos, len(text))))
            self.ini_code_edit.setTextCursor(cur)
        self._ini_editor_opening_tab = False
        if ini_editor_is_supported_model_file(path):
            self._ini_editor_show_model_preview(path)
        else:
            self._ini_editor_show_text_panel()
        self._ini_editor_refresh_change_markers()
        if self._ini_editor_current_file:
            history = self._ini_editor_load_line_history(self._ini_editor_current_file)
            self.ini_code_edit.set_line_history(self._ini_editor_line_history_map(history, text))
        else:
            self.ini_code_edit.set_line_history({})
        self._ini_editor_current_tree_item = self._ini_editor_find_tree_item_by_path(path)
        self._ini_editor_refresh_sections()
        self._ini_editor_refresh_status_summary()
        if hasattr(self, "_ini_minimap"):
            schedule_refresh = getattr(self._ini_minimap, "schedule_refresh", None)
            if callable(schedule_refresh):
                schedule_refresh()
        spec["path"] = path
        spec["source"] = source
        spec["title"] = self._ini_editor_tab_title(path, dirty=bool(self._ini_editor_dirty))
        self._ini_file_tab_sync()
        if self._ini_editor_current_file:
            self.statusBar().showMessage(tr("ini.status.opened").format(path=Path(path).name))
        else:
            self.statusBar().showMessage(tr("ini.status.unsupported").format(path=Path(path).name))

    def _ini_editor_open_file_in_tab(self, path: str, source: str = "primary", ensure_workspace: bool = True):
        clean_path = str(path or "").strip()
        if not clean_path:
            return
        if ensure_workspace:
            if not self._activate_ini_editor_workspace(reload_tree=not bool(getattr(self, "_ini_editor_root", ""))):
                return
        tab_key = self._ini_editor_tab_key(clean_path)
        # Capture outgoing document
        if getattr(self, "_ini_file_current_spec", None) is not None:
            self._ini_editor_capture_tab_document()
        # Find or create tab spec
        specs = getattr(self, "_ini_file_tab_specs", [])
        existing = None
        for s in specs:
            if str(s.get("key", "") or "").strip() == tab_key:
                existing = s
                break
        if existing is None:
            existing = {
                "key": tab_key,
                "title": self._ini_editor_tab_title(clean_path),
                "path": clean_path,
                "source": str(source or "primary").strip().lower(),
                "closable": True,
            }
            specs.append(existing)
        else:
            existing["path"] = clean_path
            existing["source"] = str(source or "primary").strip().lower()
        self._ini_file_current_spec = existing
        # Make sure we're on the ini page in center tabs
        if str(self._center_current_tab_key or "").strip() != "ini":
            self._activate_ini_editor_workspace(reload_tree=False)
        self._ini_editor_apply_tab_document(existing)
        self._ini_file_tab_sync()

    def _ini_editor_tab_is_dirty(self, spec: dict[str, object]) -> bool:
        if spec is getattr(self, "_ini_file_current_spec", None):
            return bool(self._ini_editor_dirty)
        doc = spec.get("document")
        if isinstance(doc, IniEditorDocument):
            return bool(doc.dirty)
        title = str(spec.get("title", "") or "")
        return title.startswith("* ")

    def _ini_editor_open_tree_item(self, item: QTreeWidgetItem, _column: int = 0):
        if item is None:
            return
        if str(item.data(0, Qt.UserRole + 1) or "") != "file":
            item.setExpanded(not item.isExpanded())
            self._ini_explorer_show_folder(item)
            return
        self._ini_explorer_hide()
        path = str(item.data(0, Qt.UserRole) or "").strip()
        if not path:
            return
        self._ini_editor_current_tree_item = item
        source = str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower()
        self._ini_editor_open_file_in_tab(path, source, ensure_workspace=False)

    def _ini_editor_clear_model_preview(self) -> None:
        host_layout = getattr(self, "_ini_model_preview_host_layout", None)
        if host_layout is not None:
            while host_layout.count() > 0:
                item = host_layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.deleteLater()
        self._ini_editor_current_model_entry = None

    def _ini_editor_show_text_panel(self) -> None:
        self._ini_editor_clear_model_preview()
        if hasattr(self, "_ini_model_preview_panel"):
            self._ini_model_preview_panel.setVisible(False)
        if hasattr(self, "_ini_folder_explorer"):
            self._ini_folder_explorer.setVisible(False)
        if hasattr(self, "_ini_editor_text_panel"):
            self._ini_editor_text_panel.setVisible(True)
        self.ini_code_edit.setVisible(True)
        if hasattr(self, "_ini_minimap"):
            self._ini_minimap.setVisible(True)
            schedule_refresh = getattr(self._ini_minimap, "schedule_refresh", None)
            if callable(schedule_refresh):
                schedule_refresh()
            else:
                self._ini_minimap.update()

    def _ini_editor_make_model_viewer_entry(self, model_path: Path) -> ModelViewerEntry:
        path_obj = Path(model_path)
        display_name = path_obj.stem or path_obj.name
        source_path = path_obj
        try:
            game_path = str(self._primary_game_path() or "").strip()
            if game_path and self._path_is_within_root(path_obj, game_path):
                source_path = path_obj
        except Exception:
            pass
        return ModelViewerEntry(
            category_key="file_explorer",
            category_label="File Explorer",
            nickname=display_name,
            display_name=display_name,
            archetype=display_name,
            da_archetype=str(path_obj).replace("/", "\\"),
            model_path=path_obj,
            source_ini_path=source_path,
            source_section="File Explorer",
            render_kind="Freelancer Native" if path_obj.suffix.lower() in {".cmp", ".3db", ".ale", ".mat"} else path_obj.suffix.lower(),
        )

    def _ini_editor_show_model_preview(self, model_path: str | Path) -> None:
        entry = self._ini_editor_make_model_viewer_entry(Path(model_path))
        self._ini_editor_clear_model_preview()
        host_layout = getattr(self, "_ini_model_preview_host_layout", None)
        if host_layout is None:
            return
        preview_widget = self._build_embedded_model_viewer_preview_widget(entry, self._ini_model_preview_host)
        if preview_widget is None:
            preview_widget = QLabel(tr("msg.3d_not_available").format(path=str(entry.model_path)), self._ini_model_preview_host)
            preview_widget.setAlignment(Qt.AlignCenter)
            preview_widget.setWordWrap(True)
        host_layout.addWidget(preview_widget, 1)
        self._ini_editor_current_model_entry = entry
        if hasattr(self, "_ini_model_preview_label"):
            self._ini_model_preview_label.setText(str(entry.model_path))
        if hasattr(self, "_ini_folder_explorer"):
            self._ini_folder_explorer.setVisible(False)
        if hasattr(self, "_ini_editor_text_panel"):
            self._ini_editor_text_panel.setVisible(False)
        self.ini_code_edit.setVisible(False)
        if hasattr(self, "_ini_minimap"):
            self._ini_minimap.setVisible(False)
        if hasattr(self, "_ini_model_preview_panel"):
            self._ini_model_preview_panel.setVisible(True)

    def _ini_editor_open_current_model_preview(self) -> None:
        entry = getattr(self, "_ini_editor_current_model_entry", None)
        if isinstance(entry, ModelViewerEntry):
            self._show_model_viewer_entry_3d_preview(entry)

    def _open_single_model_viewer_tab(self, model_path: str | Path) -> None:
        path_obj = Path(model_path)
        entry = self._ini_editor_make_model_viewer_entry(path_obj)
        page, root = self._prepare_editor_page("model_viewer_page", "3D Model Manager")
        viewer = ModelViewerWidget(
            page,
            entries=[entry],
            preview_callback=self._show_model_viewer_entry_3d_preview,
            embedded_preview_factory=self._build_embedded_model_viewer_preview_widget,
            open_ini_callback=self._open_model_viewer_entry_source_ini,
            refresh_callback=lambda: [entry],
        )
        root.addWidget(viewer, 1)
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="model_viewer",
            current_widget=page,
            tab_key="model_viewer",
            open_extra_tab=True,
            title="3D Model Manager",
        )

    def _ini_editor_open_current_model_in_manager(self) -> None:
        entry = getattr(self, "_ini_editor_current_model_entry", None)
        if isinstance(entry, ModelViewerEntry):
            self._open_single_model_viewer_tab(entry.model_path)

    def _ini_editor_is_system_ini(self, path: str | Path) -> bool:
        path_obj = Path(path)
        if path_obj.suffix.lower() != ".ini":
            return False
        try:
            sections = self._parser.parse(str(path_obj))
        except Exception:
            return False
        names = {str(section_name or "").strip().lower() for section_name, _entries in sections}
        return "systeminfo" in names

    def _ini_editor_refresh_sections(self):
        self.ini_sections_list.clear()
        for section_title, block_number in parse_ini_sections(self.ini_code_edit.toPlainText()):
            item = QListWidgetItem(section_title)
            item.setData(Qt.UserRole, int(block_number))
            self.ini_sections_list.addItem(item)

    def _ini_editor_jump_to_section(self, item):
        if item is None:
            return
        try:
            block_no = int(item.data(Qt.UserRole))
        except Exception:
            return
        block = self.ini_code_edit.document().findBlockByNumber(block_no)
        if not block.isValid():
            return
        cursor = self.ini_code_edit.textCursor()
        cursor.setPosition(block.position())
        self.ini_code_edit.setTextCursor(cursor)
        self.ini_code_edit.centerCursor()

    def _ini_editor_select_section_containing(self, text: str) -> bool:
        needle = str(text or "").strip().lower()
        if not needle or not hasattr(self, "ini_sections_list"):
            return False
        for row_index in range(self.ini_sections_list.count()):
            item = self.ini_sections_list.item(row_index)
            if item is None:
                continue
            if needle not in item.text().strip().lower():
                continue
            self.ini_sections_list.setCurrentItem(item)
            self._ini_editor_jump_to_section(item)
            return True
        return False

    @staticmethod
    def _ini_editor_line_text_at_cursor(cursor: QTextCursor) -> tuple[int, str, int]:
        block = cursor.block()
        block_number = int(block.blockNumber())
        line_text = str(block.text() or "")
        column = max(0, int(cursor.position() - block.position()))
        return block_number, line_text, column

    @staticmethod
    def _ini_editor_extract_line_paths(line_text: str) -> list[dict[str, object]]:
        matches: list[dict[str, object]] = []
        pattern = re.compile(r"(?<![\w.])([A-Za-z0-9_.-]+(?:[\\/][A-Za-z0-9_.-]+)+\.[A-Za-z0-9_]+)(?![\w.])")
        for match in pattern.finditer(str(line_text or "")):
            matches.append(
                {
                    "raw": str(match.group(1) or ""),
                    "start": int(match.start(1)),
                    "end": int(match.end(1)),
                }
            )
        return matches

    @staticmethod
    def _ini_editor_extract_ids_assignments(line_text: str) -> list[tuple[str, int]]:
        assignments: list[tuple[str, int]] = []
        pattern = re.compile(r"\b(ids_name|strid_name|ids_info)\s*=\s*(\d+)\b", re.IGNORECASE)
        for match in pattern.finditer(str(line_text or "")):
            key = str(match.group(1) or "").strip().lower()
            value = safe_int(str(match.group(2) or "0"))
            if value > 0:
                assignments.append((key, value))
        return assignments

    def _ini_editor_source_for_path(self, path: Path) -> str:
        path_obj = Path(path)
        fallback_root = str(getattr(self, "_ini_editor_fallback_root", "") or "").strip()
        if fallback_root and self._path_is_within_root(path_obj, fallback_root):
            return "fallback"
        return "primary"

    def _ini_editor_resolve_linked_path(self, raw_path: str) -> Path | None:
        clean = str(raw_path or "").strip().strip("\"'")
        if not clean:
            return None
        candidate = Path(clean)
        if candidate.exists():
            return candidate
        resolved = self._resolve_game_path_case_insensitive(self._primary_game_path() or "", clean)
        if resolved is not None:
            return resolved
        return None

    def _ini_editor_open_path_in_system(self, path: Path) -> None:
        target = Path(path)
        folder = target if target.is_dir() else target.parent
        if not folder:
            return
        if sys.platform == "win32":
            if target.is_file():
                subprocess.Popen(["explorer", "/select,", str(target)])
            else:
                subprocess.Popen(["explorer", str(folder)])
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(folder)])
        else:
            subprocess.Popen(["xdg-open", str(folder)])

    def _ini_editor_show_ids_value_dialog(self, key: str, ids_value: int) -> None:
        ids_key = str(key or "").strip().lower()
        if ids_key in {"ids_name", "strid_name"}:
            text = str(self._display_name_from_ids_name(ids_value) or "").strip()
        else:
            text = str(self._display_text_from_ids_value(ids_value) or "").strip()
        if not text:
            text = tr("ini.ids.not_found").format(key=ids_key, value=ids_value)
        QMessageBox.information(self, tr("ini.ids.title"), f"{ids_key} = {ids_value}\n\n{text}")

    def _ini_editor_on_text_changed(self):
        if bool(getattr(self, "_ini_editor_opening_tab", False)):
            return
        current_file = str(getattr(self, "_ini_editor_current_file", "") or "").strip()
        if not current_file:
            return
        self._ini_editor_dirty = True
        self.ini_save_btn.setEnabled(True)
        if hasattr(self, "ini_discard_btn"):
            self.ini_discard_btn.setEnabled(True)
        self._ini_editor_refresh_change_markers()
        spec = self._ini_editor_tab_spec()
        if isinstance(spec, dict):
            spec["title"] = self._ini_editor_tab_title(current_file, dirty=True)
            self._ini_file_tab_sync()
        self._ini_editor_schedule_live_refresh()

    def _ini_editor_live_refresh_delay_ms(self) -> int:
        editor = getattr(self, "ini_code_edit", None)
        if editor is None:
            return 80
        block_count = max(0, int(editor.blockCount()))
        char_count = max(0, int(editor.document().characterCount()))
        if block_count >= 12000 or char_count >= 800000:
            return 240
        if block_count >= 5000 or char_count >= 300000:
            return 160
        return 70

    def _ini_editor_schedule_live_refresh(self, force: bool = False):
        timer = getattr(self, "_ini_editor_live_refresh_timer", None)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(self._ini_editor_apply_live_refresh)
            self._ini_editor_live_refresh_timer = timer
        if force:
            timer.stop()
            self._ini_editor_apply_live_refresh()
            return
        timer.start(self._ini_editor_live_refresh_delay_ms())

    def _ini_editor_apply_live_refresh(self):
        if bool(getattr(self, "_ini_editor_opening_tab", False)):
            return
        current_file = str(getattr(self, "_ini_editor_current_file", "") or "").strip()
        if not current_file:
            return
        self._ini_editor_refresh_change_markers()
        self._ini_editor_refresh_sections()
        self._ini_editor_refresh_status_summary()

    def _ini_editor_target_dir_for_item(self, item: QTreeWidgetItem | None) -> Path | None:
        if item is None:
            return None
        entry_type = str(item.data(0, Qt.UserRole + 1) or "").strip().lower()
        primary_txt = str(item.data(0, Qt.UserRole + 4) or "").strip()
        fallback_txt = str(item.data(0, Qt.UserRole + 5) or "").strip()
        raw_path = str(item.data(0, Qt.UserRole) or "").strip()
        if entry_type == "dir":
            candidate = Path(primary_txt or fallback_txt or raw_path)
        else:
            candidate = Path(raw_path).parent if raw_path else Path(primary_txt or fallback_txt)
        return candidate if str(candidate or "").strip() else None

    def _ini_editor_create_new_file(self, target_dir: str | Path | None):
        if target_dir is None:
            return
        base_dir = Path(target_dir)
        if not str(base_dir).strip():
            return
        try:
            writable_dir = Path(self._ensure_writable_path(base_dir / "__new_file__.tmp")).parent
        except Exception:
            writable_dir = base_dir
        from PySide6.QtWidgets import QInputDialog
        file_name, ok = QInputDialog.getText(
            self,
            tr("ini.new_file.title"),
            tr("ini.new_file.prompt"),
            text="new_file.ini",
        )
        if not ok:
            return
        file_name = str(file_name or "").strip()
        if not file_name:
            return
        candidate = Path(file_name)
        if candidate.is_absolute() or any(part == ".." for part in candidate.parts):
            QMessageBox.warning(self, tr("ini.title"), tr("ini.new_file.invalid_name"))
            return
        target = writable_dir / candidate
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.exists():
                QMessageBox.warning(self, tr("ini.title"), tr("ini.new_file.exists").format(path=target.name))
                return
            target.touch()
        except Exception as ex:
            QMessageBox.warning(self, tr("ini.title"), tr("ini.new_file.failed").format(error=ex))
            return
        self._ini_editor_reload_tree()
        self._ini_explorer_refresh_current()
        self._ini_editor_open_file_in_tab(str(target), self._ini_editor_source_for_path(target), ensure_workspace=False)
        self.statusBar().showMessage(tr("ini.status.created").format(path=target.name))

    def _on_ini_editor_tree_context_menu(self, pos):
        if not hasattr(self, "ini_tree"):
            return
        item = self.ini_tree.itemAt(pos)
        if item is None:
            return
        entry_type = str(item.data(0, Qt.UserRole + 1) or "").strip().lower()
        path = str(item.data(0, Qt.UserRole) or "").strip()
        menu = QMenu(self)
        new_file_act = menu.addAction(tr("ini.ctx.new_file"))
        open_tab_act = None
        system_tab_act = None
        copy_act = None
        counterpart_act = None
        delete_act = None
        if entry_type == "file" and path:
            open_tab_act = menu.addAction(tr("ini.ctx.open_new_tab"))
            if self._ini_editor_is_system_ini(path):
                system_tab_act = menu.addAction(tr("ini.ctx.open_system_tab"))
            menu.addSeparator()
            copy_act = menu.addAction(tr("ini.ctx.copy_to_mod"))
            counterpart_act = menu.addAction(tr("ini.ctx.open_counterpart"))
            delete_act = menu.addAction(tr("ini.ctx.delete_file"))
            if not self._is_overlay_mode():
                copy_act.setEnabled(False)
            source = str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower()
            if source != "fallback":
                copy_act.setEnabled(False)
            counterpart_act.setEnabled(self._ini_editor_counterpart_path(item) is not None)
            delete_act.setEnabled(self._ini_editor_can_delete_tree_item(item))
        action = menu.exec(self.ini_tree.viewport().mapToGlobal(pos))
        if action is new_file_act:
            self._ini_editor_create_new_file(self._ini_editor_target_dir_for_item(item))
        elif open_tab_act is not None and action is open_tab_act:
            self._ini_editor_open_tree_item(item)
        elif system_tab_act is not None and action is system_tab_act:
            self._open_system_tab(path, new_tab=True)
        elif copy_act is not None and action is copy_act:
            self._ini_editor_copy_tree_item_to_mod(item)
        elif counterpart_act is not None and action is counterpart_act:
            self._ini_editor_open_counterpart(item)
        elif delete_act is not None and action is delete_act:
            self._ini_editor_delete_tree_item(item)

    def _ini_editor_source_tag(self, source: str) -> str:
        src = str(source or "primary").strip().lower()
        if src == "fallback":
            return tr("ini.tag.vanilla")
        if self._is_overlay_mode():
            return tr("ini.tag.mod")
        return tr("ini.tag.install")

    def _ini_editor_tree_entry_label(self, path: str | Path, entry_type: str, source: str) -> str:
        entry_path = Path(path)
        label = entry_path.name or str(entry_path)
        if str(entry_type or "").strip().lower() == "file":
            label = f"{label} [{self._ini_editor_source_tag(source)}]"
        return label

    def _ini_editor_counterpart_path(self, item: QTreeWidgetItem | None) -> Path | None:
        if item is None:
            return None
        if str(item.data(0, Qt.UserRole + 1) or "") != "file":
            return None
        path_txt = str(item.data(0, Qt.UserRole) or "").strip()
        if not path_txt:
            return None
        source = str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower()
        root_txt = str(getattr(self, "_ini_editor_root", "") or "").strip()
        fallback_txt = str(getattr(self, "_ini_editor_fallback_root", "") or "").strip()
        if not root_txt or not fallback_txt:
            return None
        current_path = Path(path_txt)
        source_root = Path(root_txt) if source != "fallback" else Path(fallback_txt)
        counterpart_root = Path(fallback_txt) if source != "fallback" else Path(root_txt)
        try:
            rel_path = current_path.resolve().relative_to(source_root.resolve())
        except Exception:
            try:
                rel_path = current_path.relative_to(source_root)
            except Exception:
                return None
        counterpart = counterpart_root / rel_path
        if counterpart.exists() and counterpart.is_file():
            return counterpart
        return None

    def _ini_editor_open_counterpart(self, item: QTreeWidgetItem | None):
        counterpart = self._ini_editor_counterpart_path(item)
        if counterpart is None:
            return
        source = str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower() if item is not None else "primary"
        target_source = "primary" if source == "fallback" else "fallback"
        self._ini_editor_open_file_in_tab(str(counterpart), target_source)
        self.statusBar().showMessage(tr("ini.status.opened_counterpart").format(path=counterpart.name))

    def _ini_editor_build_diff_text(self, current_path: str | Path, counterpart_path: str | Path) -> str:
        current = Path(current_path)
        counterpart = Path(counterpart_path)
        current_text = self._read_text_best_effort(current).splitlines()
        counterpart_text = self._read_text_best_effort(counterpart).splitlines()
        diff_lines = list(
            difflib.unified_diff(
                counterpart_text,
                current_text,
                fromfile=str(counterpart.name),
                tofile=str(current.name),
                lineterm="",
            )
        )
        if not diff_lines:
            return tr("ini.compare.identical")
        return "\n".join(diff_lines)

    def _ini_editor_build_compare_summary(self, current_path: str | Path, counterpart_path: str | Path) -> str:
        current = Path(current_path)
        counterpart = Path(counterpart_path)
        summary = compare_ini_sections(
            self._read_text_best_effort(current),
            self._read_text_best_effort(counterpart),
        )
        lines: list[str] = []
        for key, label_key in (
            ("changed", "ini.compare.summary_changed"),
            ("added", "ini.compare.summary_added"),
            ("removed", "ini.compare.summary_removed"),
        ):
            entries = list(summary.get(key, []) or [])
            if not entries:
                continue
            lines.append(f"{tr(label_key)}:")
            lines.extend(f"- {entry}" for entry in entries)
        if not lines:
            return tr("ini.compare.summary_none")
        return "\n".join(lines)

    def _ini_editor_show_compare_dialog(self, *, current_path: Path, counterpart_path: Path, diff_text: str, summary_text: str):
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("ini.compare.title"))
        dlg.resize(980, 720)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        current_lbl = QLabel(tr("ini.compare.current").format(path=str(current_path)))
        current_lbl.setTextInteractionFlags(Qt.TextSelectableByMouse)
        layout.addWidget(current_lbl)
        counterpart_lbl = QLabel(tr("ini.compare.counterpart").format(path=str(counterpart_path)))
        counterpart_lbl.setTextInteractionFlags(Qt.TextSelectableByMouse)
        layout.addWidget(counterpart_lbl)
        summary_title_lbl = QLabel(tr("ini.compare.summary_title"))
        summary_title_lbl.setStyleSheet("font-weight: bold;")
        layout.addWidget(summary_title_lbl)
        summary_view = QPlainTextEdit()
        summary_view.setReadOnly(True)
        summary_view.setMaximumHeight(160)
        summary_view.setPlainText(summary_text)
        layout.addWidget(summary_view)

        viewer = QPlainTextEdit()
        viewer.setReadOnly(True)
        viewer.setPlainText(diff_text)
        layout.addWidget(viewer, 1)

        close_btn = QPushButton(tr("dlg.close"))
        close_btn.clicked.connect(dlg.accept)
        layout.addWidget(close_btn, 0, Qt.AlignRight)
        dlg.exec()

    def _ini_editor_current_search_term(self) -> str:
        if not hasattr(self, "ini_code_edit"):
            return ""
        cursor = self.ini_code_edit.textCursor()
        selected = str(cursor.selectedText() or "").replace("\u2029", "\n").strip()
        if selected:
            return selected
        try:
            probe = self.ini_code_edit.textCursor()
            probe.select(QTextCursor.WordUnderCursor)
            return str(probe.selectedText() or "").strip()
        except Exception:
            return ""

    def _ini_editor_current_source(self) -> str:
        item = getattr(self, "_ini_editor_current_tree_item", None)
        current_path = str(getattr(self, "_ini_editor_current_file", "") or "").strip()
        if item is not None:
            item_path = str(item.data(0, Qt.UserRole) or "").strip()
            if item_path and (not current_path or item_path == current_path):
                return str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower()
        if current_path:
            match = self._ini_editor_find_tree_item_by_path(current_path)
            if match is not None:
                return str(match.data(0, Qt.UserRole + 2) or "primary").strip().lower()
        return "primary"

    def _ini_editor_refresh_status_summary(self):
        if not hasattr(self, "ini_status_summary_val"):
            return
        current_path_txt = str(getattr(self, "_ini_editor_current_file", "") or "").strip()
        current_path = Path(current_path_txt) if current_path_txt else None
        item = getattr(self, "_ini_editor_current_tree_item", None)
        if item is None and current_path is not None:
            item = self._ini_editor_find_tree_item_by_path(current_path)
        source = self._ini_editor_current_source() if current_path is not None else ""
        counterpart = self._ini_editor_counterpart_path(item) if item is not None else None

        if current_path is None:
            self.ini_status_summary_val.setText(tr("ini.state.no_file"))
            self.ini_status_summary_val.setToolTip("")
            return

        write_target = current_path
        try:
            if ini_editor_is_supported_text_file(current_path):
                write_target = Path(self._ensure_writable_path(current_path))
        except Exception:
            write_target = current_path

        if not ini_editor_is_supported_text_file(current_path):
            state_text = tr("ini.state.read_only")
        elif bool(getattr(self, "_ini_editor_dirty", False)):
            state_text = tr("ini.state.dirty")
        else:
            state_text = tr("ini.state.clean")
        source_text = self._ini_editor_source_tag(source)

        summary_parts = [current_path.name, source_text, state_text]
        if write_target.name != current_path.name:
            summary_parts.append(f"-> {write_target.name}")
        if counterpart is not None:
            summary_parts.append(f"vs {counterpart.name}")
        self.ini_status_summary_val.setText(" | ".join(summary_parts))

        tooltip_lines = [
            f"{tr('ini.status.file')} {current_path}",
            f"{tr('ini.status.source')} {source_text}",
            f"{tr('ini.status.write_target')} {write_target}",
            f"{tr('ini.status.counterpart')} {counterpart if counterpart is not None else '-'}",
            f"{tr('ini.status.state')} {state_text}",
        ]
        self.ini_status_summary_val.setToolTip("\n".join(tooltip_lines))

    def _ini_editor_usage_search_roots(self) -> list[tuple[Path, str]]:
        roots: list[tuple[Path, str]] = []
        root_txt = str(getattr(self, "_ini_editor_root", "") or "").strip()
        fallback_txt = str(getattr(self, "_ini_editor_fallback_root", "") or "").strip()
        if root_txt:
            roots.append((Path(root_txt), "primary"))
        if fallback_txt:
            roots.append((Path(fallback_txt), "fallback"))
        return roots

    def _ini_editor_find_usages(self, term: str) -> list[dict[str, object]]:
        needle = str(term or "").strip().lower()
        if not needle:
            return []
        results: list[dict[str, object]] = []
        seen_paths: set[str] = set()
        for root, source in self._ini_editor_usage_search_roots():
            if not root.exists() or not root.is_dir():
                continue
            for path in sorted(root.rglob("*")):
                if not path.is_file() or not ini_editor_is_supported_text_file(path):
                    continue
                norm = self._mod_manager_normalized_path_key(path)
                if norm in seen_paths:
                    continue
                seen_paths.add(norm)
                try:
                    text = self._read_text_best_effort(path)
                except Exception:
                    continue
                for line_no, raw_line in enumerate(text.splitlines(), start=1):
                    if needle not in raw_line.lower():
                        continue
                    results.append(
                        {
                            "path": str(path),
                            "source": source,
                            "line": line_no,
                            "line_text": raw_line.strip(),
                        }
                    )
        return results

    def _ini_editor_jump_to_line(self, line_no: int):
        if not hasattr(self, "ini_code_edit"):
            return
        try:
            block = self.ini_code_edit.document().findBlockByNumber(max(0, int(line_no) - 1))
        except Exception:
            return
        if not block.isValid():
            return
        cursor = self.ini_code_edit.textCursor()
        cursor.setPosition(block.position())
        self.ini_code_edit.setTextCursor(cursor)
        self.ini_code_edit.centerCursor()

    def _ini_editor_current_section_block_number(self) -> int | None:
        current_item = self.ini_sections_list.currentItem() if hasattr(self, "ini_sections_list") else None
        if current_item is not None:
            try:
                return int(current_item.data(Qt.UserRole))
            except Exception:
                pass
        if not hasattr(self, "ini_code_edit"):
            return None
        try:
            cursor_block = int(self.ini_code_edit.textCursor().blockNumber())
        except Exception:
            return None
        best_match: int | None = None
        for row_index in range(self.ini_sections_list.count()):
            item = self.ini_sections_list.item(row_index)
            if item is None:
                continue
            try:
                block_no = int(item.data(Qt.UserRole))
            except Exception:
                continue
            if block_no <= cursor_block:
                best_match = block_no
            else:
                break
        return best_match

    def _ini_editor_open_usage_result(self, usage: dict[str, object]):
        path = str(usage.get("path", "") or "").strip()
        if not path:
            return
        source = str(usage.get("source", "primary") or "primary").strip().lower()
        line_no = int(usage.get("line", 1) or 1)
        self._ini_editor_open_file_in_tab(path, source)
        self._ini_editor_jump_to_line(line_no)

    def _ini_editor_show_usages_dialog(self, term: str, results: list[dict[str, object]]):
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("ini.find_usages.title"))
        dlg.resize(920, 620)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        summary_lbl = QLabel(tr("ini.find_usages.results").format(count=len(results), term=term))
        layout.addWidget(summary_lbl)

        lst = QListWidget()
        for result in results:
            path = Path(str(result.get("path", "") or ""))
            source = self._ini_editor_source_tag(str(result.get("source", "primary") or "primary"))
            line_no = int(result.get("line", 1) or 1)
            line_text = str(result.get("line_text", "") or "").strip()
            item = QListWidgetItem(
                f"{path.name} [{source}] | {tr('ini.find_usages.line').format(line=line_no)} | {line_text}"
            )
            item.setData(Qt.UserRole, result)
            lst.addItem(item)
        layout.addWidget(lst, 1)

        def _open_selected(item=None):
            target = item or lst.currentItem()
            if target is None:
                return
            payload = target.data(Qt.UserRole)
            if isinstance(payload, dict):
                self._ini_editor_open_usage_result(payload)
                dlg.accept()

        lst.itemActivated.connect(_open_selected)
        lst.itemDoubleClicked.connect(_open_selected)

        close_btn = QPushButton(tr("dlg.close"))
        close_btn.clicked.connect(dlg.reject)
        layout.addWidget(close_btn, 0, Qt.AlignRight)
        dlg.exec()

    def _ini_editor_open_compare_dialog(self):
        item = getattr(self, "_ini_editor_current_tree_item", None)
        if item is None and str(getattr(self, "_ini_editor_current_file", "") or "").strip():
            item = self._ini_editor_find_tree_item_by_path(self._ini_editor_current_file)
        counterpart = self._ini_editor_counterpart_path(item)
        if item is None or counterpart is None:
            QMessageBox.information(self, tr("ini.compare.title"), tr("ini.compare.no_counterpart"))
            return
        current_txt = str(item.data(0, Qt.UserRole) or "").strip()
        if not current_txt:
            QMessageBox.information(self, tr("ini.compare.title"), tr("ini.compare.no_counterpart"))
            return
        current_path = Path(current_txt)
        diff_text = self._ini_editor_build_diff_text(current_path, counterpart)
        summary_text = self._ini_editor_build_compare_summary(current_path, counterpart)
        self._ini_editor_show_compare_dialog(
            current_path=current_path,
            counterpart_path=counterpart,
            diff_text=diff_text,
            summary_text=summary_text,
        )

    def _ini_editor_open_find_usages_dialog(self):
        term = self._ini_editor_current_search_term()
        if not term:
            term, ok = QInputDialog.getText(
                self,
                tr("ini.find_usages.title"),
                tr("ini.find_usages.prompt"),
            )
            if not ok:
                return
            term = str(term or "").strip()
        if not term:
            QMessageBox.information(self, tr("ini.find_usages.title"), tr("ini.find_usages.no_term"))
            return
        results = self._ini_editor_find_usages(term)
        if not results:
            QMessageBox.information(
                self,
                tr("ini.find_usages.title"),
                tr("ini.find_usages.none").format(term=term),
            )
            return
        self._ini_editor_show_usages_dialog(term, results)

    def _ini_editor_show_validation_dialog(self, findings: list[str]):
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("ini.validate.title"))
        dlg.resize(760, 480)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        summary_lbl = QLabel(tr("ini.validate.results").format(count=len(findings)))
        layout.addWidget(summary_lbl)

        results_list = QListWidget(dlg)
        for finding in findings:
            results_list.addItem(str(finding))
        layout.addWidget(results_list, 1)

        close_btn = QPushButton(tr("dlg.close"))
        close_btn.clicked.connect(dlg.accept)
        layout.addWidget(close_btn, 0, Qt.AlignRight)
        dlg.exec()

    def _ini_editor_open_validation_dialog(self):
        findings = validate_ini_text(self.ini_code_edit.toPlainText())
        if not findings:
            QMessageBox.information(self, tr("ini.validate.title"), tr("ini.validate.none"))
            return
        self._ini_editor_show_validation_dialog(findings)

    def _ini_editor_open_section_inspector(self):
        block_number = self._ini_editor_current_section_block_number()
        if block_number is None:
            QMessageBox.information(self, tr("ini.section_inspector.title"), tr("ini.section_inspector.no_section"))
            return
        details = parse_ini_section_details(self.ini_code_edit.toPlainText(), block_number)
        if details is None:
            QMessageBox.information(self, tr("ini.section_inspector.title"), tr("ini.section_inspector.no_section"))
            return
        if not details.fields:
            QMessageBox.information(self, tr("ini.section_inspector.title"), tr("ini.section_inspector.empty"))
            return

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("ini.section_inspector.title"))
        dlg.resize(760, 520)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        section_lbl = QLabel(tr("ini.section_inspector.section").format(title=details.title))
        layout.addWidget(section_lbl)

        table = QTableWidget(len(details.fields), 2, dlg)
        table.setHorizontalHeaderLabels([tr("ini.section_inspector.col.key"), tr("ini.section_inspector.col.value")])
        table.verticalHeader().setVisible(False)
        table.horizontalHeader().setStretchLastSection(True)
        for row, field in enumerate(details.fields):
            key_item = QTableWidgetItem(field.key if field.occurrence == 0 else f"{field.key} #{field.occurrence + 1}")
            key_item.setFlags(key_item.flags() & ~Qt.ItemIsEditable)
            key_item.setData(Qt.UserRole, {"key": field.key, "occurrence": field.occurrence})
            value_item = QTableWidgetItem(field.value)
            table.setItem(row, 0, key_item)
            table.setItem(row, 1, value_item)
        layout.addWidget(table, 1)

        buttons = QHBoxLayout()
        buttons.addStretch(1)
        apply_btn = QPushButton(tr("ini.section_inspector.apply"))
        close_btn = QPushButton(tr("dlg.close"))
        buttons.addWidget(apply_btn)
        buttons.addWidget(close_btn)
        layout.addLayout(buttons)

        def _apply_changes():
            updated_text = self.ini_code_edit.toPlainText()
            for row in range(table.rowCount()):
                meta_item = table.item(row, 0)
                value_item = table.item(row, 1)
                if meta_item is None or value_item is None:
                    continue
                payload = meta_item.data(Qt.UserRole)
                if not isinstance(payload, dict):
                    continue
                updated_text = update_ini_section_field(
                    updated_text,
                    block_number,
                    str(payload.get("key", "") or ""),
                    int(payload.get("occurrence", 0) or 0),
                    value_item.text(),
                )
            self.ini_code_edit.setPlainText(updated_text)
            if self._ini_editor_select_section_containing(details.title):
                self._ini_editor_refresh_sections()
            dlg.accept()

        apply_btn.clicked.connect(_apply_changes)
        close_btn.clicked.connect(dlg.reject)
        dlg.exec()

    def _ini_editor_can_delete_tree_item(self, item: QTreeWidgetItem | None) -> bool:
        if item is None:
            return False
        if str(item.data(0, Qt.UserRole + 1) or "") != "file":
            return False
        if not self._is_overlay_mode():
            return False
        source = str(item.data(0, Qt.UserRole + 2) or "primary").strip().lower()
        if source != "primary":
            return False
        path = str(item.data(0, Qt.UserRole) or "").strip()
        if not path:
            return False
        try:
            Path(path).resolve().relative_to(Path(self._primary_game_path()).resolve())
        except Exception:
            return False
        return True

    def _ini_editor_copy_tree_item_to_mod(self, item: QTreeWidgetItem):
        if item is None:
            return
        if str(item.data(0, Qt.UserRole + 1) or "") != "file":
            return
        path = str(item.data(0, Qt.UserRole) or "").strip()
        if not path:
            return
        src_path = Path(path)
        dst_path = Path(self._ensure_writable_path(src_path))
        if not dst_path.exists():
            QMessageBox.warning(self, tr("ini.title"), tr("ini.copy_to_mod_failed").format(error=tr("msg.not_found")))
            return
        item.setData(0, Qt.UserRole, str(dst_path))
        item.setData(0, Qt.UserRole + 2, "primary")
        item.setText(0, self._ini_editor_tree_entry_label(dst_path, "file", "primary"))
        item.setForeground(0, QBrush())
        if str(self._ini_editor_current_file or "").strip() == str(src_path):
            self._ini_editor_current_file = str(dst_path)
            spec = self._ini_editor_tab_spec()
            if isinstance(spec, dict):
                spec["path"] = str(dst_path)
                spec["source"] = "primary"
                spec["title"] = self._ini_editor_tab_title(dst_path, dirty=bool(self._ini_editor_dirty))
                doc = spec.get("document")
                if isinstance(doc, IniEditorDocument):
                    doc.path = str(dst_path)
                    doc.source = "primary"
                self._ini_file_tab_sync()
        self._ini_editor_refresh_status_summary()
        self.statusBar().showMessage(tr("ini.status.copied_to_mod").format(path=dst_path.name))

    def _ini_editor_delete_tree_item(self, item: QTreeWidgetItem):
        if not self._ini_editor_can_delete_tree_item(item):
            return
        path = str(item.data(0, Qt.UserRole) or "").strip()
        if not path:
            return
        target = Path(path)
        answer = QMessageBox.question(
            self,
            tr("ini.title"),
            tr("ini.delete_confirm").format(path=target.name),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return
        try:
            target.unlink()
        except Exception as ex:
            QMessageBox.warning(self, tr("ini.title"), tr("ini.delete_failed").format(error=ex))
            return
        if str(self._ini_editor_current_file or "").strip() == str(target):
            self._ini_editor_current_file = ""
            self._ini_editor_dirty = False
            self.ini_save_btn.setEnabled(False)
            self.ini_code_edit.blockSignals(True)
            self.ini_code_edit.setPlainText("")
            self.ini_code_edit.blockSignals(False)
            self._ini_editor_refresh_sections()
            spec = self._ini_editor_tab_spec()
            if isinstance(spec, dict):
                spec["document"] = IniEditorDocument(path=str(target), text="", dirty=False, cursor_pos=0, source="primary")
                spec["title"] = self._ini_editor_tab_title(target, dirty=False)
                self._ini_file_tab_sync()
        self._ini_editor_refresh_status_summary()
        self._ini_editor_reload_tree()
        self.statusBar().showMessage(tr("ini.status.deleted").format(path=target.name))

    def _ini_editor_save_current(self):
        path = str(self._ini_editor_current_file or "").strip()
        if not path:
            return
        try:
            old_text = str(getattr(self, "_ini_editor_original_text", "") or "")
            new_text = self.ini_code_edit.toPlainText()
            writable_path = str(self._ensure_writable_path(path))
            ok, saved_path = ini_editor_save_file(writable_path, new_text)
            if not ok:
                return
            history = self._ini_editor_save_line_history(saved_path, old_text, new_text)
            self._ini_editor_original_text = new_text
            self._ini_editor_current_file = str(saved_path)
            cur_item = getattr(self, "_ini_editor_current_tree_item", None)
            if isinstance(cur_item, QTreeWidgetItem):
                cur_item.setData(0, Qt.UserRole, str(saved_path))
                cur_item.setData(0, Qt.UserRole + 2, "primary")
                cur_item.setText(0, self._ini_editor_tree_entry_label(saved_path, "file", "primary"))
                cur_item.setForeground(0, QBrush())
            self._ini_editor_dirty = False
            self.ini_save_btn.setEnabled(False)
            if hasattr(self, "ini_discard_btn"):
                self.ini_discard_btn.setEnabled(False)
            self._ini_editor_refresh_change_markers()
            self.ini_code_edit.set_line_history(self._ini_editor_line_history_map(history, new_text))
            spec = self._ini_editor_tab_spec()
            if isinstance(spec, dict):
                spec["path"] = str(saved_path)
                spec["source"] = "primary"
                spec["title"] = self._ini_editor_tab_title(saved_path, dirty=False)
                spec["document"] = IniEditorDocument(
                    path=str(saved_path),
                    text=new_text,
                    dirty=False,
                    cursor_pos=int(self.ini_code_edit.textCursor().position()),
                    source="primary",
                )
                self._ini_file_tab_sync()
            self._ini_editor_refresh_status_summary()
            self.statusBar().showMessage(tr("ini.status.saved").format(path=Path(saved_path).name))
        except Exception as ex:
            QMessageBox.warning(self, tr("ini.title"), tr("ini.save_failed").format(error=ex))

    def _ini_editor_find_tree_item_by_path(self, path: str | Path) -> QTreeWidgetItem | None:
        if not hasattr(self, "ini_tree"):
            return None
        needle_path = Path(path)
        try:
            needle_resolved = needle_path.resolve()
        except Exception:
            needle_resolved = needle_path

        def _walk(item: QTreeWidgetItem) -> QTreeWidgetItem | None:
            item_path = str(item.data(0, Qt.UserRole) or "").strip()
            if item_path:
                candidate = Path(item_path)
                try:
                    candidate_resolved = candidate.resolve()
                except Exception:
                    candidate_resolved = candidate
                if candidate_resolved == needle_resolved or str(candidate) == str(needle_path):
                    return item
            for i in range(item.childCount()):
                hit = _walk(item.child(i))
                if hit is not None:
                    return hit
            return None

        for i in range(self.ini_tree.topLevelItemCount()):
            hit = _walk(self.ini_tree.topLevelItem(i))
            if hit is not None:
                return hit
        return None

    def _activate_ini_editor_workspace(self, tab_key: str = "ini", reload_tree: bool = False) -> bool:
        root_path = self._ini_editor_context_root()
        if root_path is None:
            self._warn_missing_game_path("msg.no_path")
            return False
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_widget=getattr(self, "browser", None),
                **extra_view_layout(),
            ),
            current_widget=self.ini_editor_page,
            tab_key=tab_key,
            title=tr("app.title_ini_editor"),
            apply_toolbar=True,
        )
        if reload_tree:
            self._ini_editor_reload_tree()
            self.statusBar().showMessage(tr("ini.status.opened_root").format(path=str(root_path)))
        return True

    def _open_ini_editor_view(self):
        self._preserve_active_system_tab_document()
        self._activate_ini_editor_workspace("ini", reload_tree=True)

    # ── Discard changes ──────────────────────────────────────────────
    def _ini_editor_discard_changes(self):
        original = str(getattr(self, "_ini_editor_original_text", "") or "")
        if not original and not self._ini_editor_dirty:
            return
        self._ini_editor_opening_tab = True
        self.ini_code_edit.setPlainText(original)
        self._ini_editor_opening_tab = False
        self._ini_editor_dirty = False
        self.ini_save_btn.setEnabled(False)
        if hasattr(self, "ini_discard_btn"):
            self.ini_discard_btn.setEnabled(False)
        self._ini_editor_refresh_change_markers()
        spec = self._ini_editor_tab_spec()
        if isinstance(spec, dict):
            spec["title"] = self._ini_editor_tab_title(self._ini_editor_current_file, dirty=False)
            self._ini_file_tab_sync()
        self._ini_editor_refresh_sections()
        self._ini_editor_refresh_status_summary()
        self.statusBar().showMessage(tr("ini.status.discarded"))

    # ── Internal file tab bar ────────────────────────────────────────
    def _ini_file_tab_sync(self):
        bar = getattr(self, "ini_file_tab_bar", None)
        if bar is None:
            return
        self._ini_file_tab_syncing = True
        try:
            while bar.count() > 0:
                bar.removeTab(bar.count() - 1)
            current_idx = -1
            specs = getattr(self, "_ini_file_tab_specs", [])
            current_spec = getattr(self, "_ini_file_current_spec", None)
            for i, spec in enumerate(specs):
                title = str(spec.get("title", "") or "").strip()
                bar.addTab(title)
                if spec is current_spec:
                    current_idx = i
            if current_idx >= 0:
                bar.setCurrentIndex(current_idx)
            bar.setVisible(bool(specs))
        finally:
            self._ini_file_tab_syncing = False

    def _on_ini_file_tab_changed(self, index: int):
        if getattr(self, "_ini_file_tab_syncing", False):
            return
        specs = getattr(self, "_ini_file_tab_specs", [])
        if index < 0 or index >= len(specs):
            return
        if getattr(self, "_ini_file_current_spec", None) is not None:
            self._ini_editor_capture_tab_document()
        spec = specs[index]
        self._ini_file_current_spec = spec
        self._ini_editor_apply_tab_document(spec)

    def _on_ini_file_tab_close_requested(self, index: int):
        specs = getattr(self, "_ini_file_tab_specs", [])
        if index < 0 or index >= len(specs):
            return
        spec = specs[index]
        is_current = spec is getattr(self, "_ini_file_current_spec", None)
        if is_current:
            self._ini_editor_capture_tab_document()
        doc = spec.get("document")
        close_title = str(spec.get("title", "") or "").lstrip("* ").strip() or tr("action.ini_editor")
        if isinstance(doc, IniEditorDocument) and not self._confirm_save_ini_document(doc, close_title):
            return
        specs.pop(index)
        if is_current:
            if specs:
                new_idx = min(index, len(specs) - 1)
                self._ini_file_current_spec = specs[new_idx]
                self._ini_editor_apply_tab_document(self._ini_file_current_spec)
            else:
                self._ini_file_current_spec = None
                self._ini_editor_current_file = ""
                self._ini_editor_dirty = False
                self.ini_save_btn.setEnabled(False)
                if hasattr(self, "ini_discard_btn"):
                    self.ini_discard_btn.setEnabled(False)
                self._ini_editor_opening_tab = True
                self.ini_code_edit.blockSignals(True)
                self.ini_code_edit.setPlainText("")
                self.ini_code_edit.blockSignals(False)
                self._ini_editor_opening_tab = False
                self._ini_editor_refresh_sections()
                self._ini_editor_refresh_status_summary()
        self._ini_file_tab_sync()
        self._save_center_tab_session()

    # ── Zoom & word wrap ─────────────────────────────────────────────
    def _ini_editor_close_tabs_left_of(self, index: int) -> None:
        for current in range(index - 1, -1, -1):
            specs = getattr(self, "_ini_file_tab_specs", [])
            if current < 0 or current >= len(specs):
                continue
            before = len(specs)
            self._on_ini_file_tab_close_requested(current)
            if len(getattr(self, "_ini_file_tab_specs", [])) == before:
                return

    def _ini_editor_close_tabs_right_of(self, index: int) -> None:
        current = len(getattr(self, "_ini_file_tab_specs", [])) - 1
        while current > index:
            specs = getattr(self, "_ini_file_tab_specs", [])
            if current < 0 or current >= len(specs):
                current -= 1
                continue
            before = len(specs)
            self._on_ini_file_tab_close_requested(current)
            if len(getattr(self, "_ini_file_tab_specs", [])) == before:
                return
            current = len(getattr(self, "_ini_file_tab_specs", [])) - 1

    def _on_ini_file_tab_context_menu(self, pos) -> None:
        bar = getattr(self, "ini_file_tab_bar", None)
        specs = getattr(self, "_ini_file_tab_specs", [])
        if bar is None:
            return
        index = bar.tabAt(pos)
        if index < 0 or index >= len(specs):
            return
        menu = QMenu(self)
        act_close = menu.addAction(tr("tabs.close_tab"))
        act_close.triggered.connect(lambda checked=False, i=index: self._on_ini_file_tab_close_requested(i))
        if index > 0:
            act_close_left = menu.addAction(tr("ini.tabs.close_left"))
            act_close_left.triggered.connect(lambda checked=False, i=index: self._ini_editor_close_tabs_left_of(i))
        if index < len(specs) - 1:
            act_close_right = menu.addAction(tr("ini.tabs.close_right"))
            act_close_right.triggered.connect(lambda checked=False, i=index: self._ini_editor_close_tabs_right_of(i))
        menu.exec(bar.mapToGlobal(pos))

    def _ini_editor_zoom_in(self):
        self.ini_code_edit.zoomIn(2)

    def _ini_editor_zoom_out(self):
        self.ini_code_edit.zoomOut(2)

    def _ini_editor_zoom_reset(self):
        font = self.ini_code_edit.font()
        font.setPointSize(10)
        self.ini_code_edit.setFont(font)

    def _ini_editor_toggle_wordwrap(self):
        from PySide6.QtWidgets import QPlainTextEdit
        if self.ini_code_edit.lineWrapMode() == QPlainTextEdit.NoWrap:
            self.ini_code_edit.setLineWrapMode(QPlainTextEdit.WidgetWidth)
        else:
            self.ini_code_edit.setLineWrapMode(QPlainTextEdit.NoWrap)

    # ── Changed-line markers ─────────────────────────────────────────
    def _ini_editor_refresh_change_markers(self):
        editor = getattr(self, "ini_code_edit", None)
        if editor is None or not hasattr(editor, "set_changed_lines"):
            return
        original = str(getattr(self, "_ini_editor_original_text", "") or "")
        if not original:
            editor.set_changed_lines(set())
            return
        orig_lines = original.splitlines()
        cur_lines = editor.toPlainText().splitlines()
        changed: set[int] = set()
        for i, cur_line in enumerate(cur_lines):
            if i >= len(orig_lines) or cur_line != orig_lines[i]:
                changed.add(i)
        editor.set_changed_lines(changed)

    # ── In-file search ───────────────────────────────────────────────
    def _ini_editor_selected_text_for_search(self) -> str:
        editor = getattr(self, "ini_code_edit", None)
        if editor is None:
            return ""
        cursor = editor.textCursor()
        selected = str(cursor.selectedText() or "")
        return selected.replace("\u2029", " ").strip()

    def _ini_editor_start_in_file_search(self, text: str = ""):
        bar = getattr(self, "_ini_search_bar", None)
        inp = getattr(self, "_ini_search_input", None)
        if bar is None or inp is None:
            return
        needle = str(text or "").strip()
        bar.setVisible(True)
        if needle:
            inp.setText(needle)
        inp.setFocus()
        inp.selectAll()
        current = str(inp.text() or "").strip()
        self._ini_editor_update_search_count(current)
        if current:
            self._ini_editor_find_next()

    def _ini_editor_start_global_search(self, text: str = ""):
        bar = getattr(self, "_ini_global_search_bar", None)
        inp = getattr(self, "_ini_global_search_input", None)
        if bar is None or inp is None:
            return
        needle = str(text or "").strip()
        bar.setVisible(True)
        if needle:
            inp.setText(needle)
        inp.setFocus()
        inp.selectAll()
        if str(inp.text() or "").strip():
            self._ini_editor_global_search()

    def _ini_editor_toggle_search(self):
        bar = getattr(self, "_ini_search_bar", None)
        if bar is None:
            return
        if bar.isVisible():
            bar.setVisible(False)
            self.ini_code_edit.setFocus()
            return
        self._ini_editor_start_in_file_search(self._ini_editor_selected_text_for_search())

    def _ini_editor_toggle_replace(self):
        bar = getattr(self, "_ini_search_bar", None)
        replace_row = getattr(self, "_ini_replace_row_widget", None)
        if bar is None or replace_row is None:
            return
        if not bar.isVisible():
            bar.setVisible(True)
            replace_row.setVisible(True)
            inp = getattr(self, "_ini_search_input", None)
            if inp is not None:
                inp.setFocus()
                inp.selectAll()
            return
        replace_row.setVisible(not replace_row.isVisible())

    def _ini_editor_close_search(self):
        bar = getattr(self, "_ini_search_bar", None)
        if bar is not None:
            bar.setVisible(False)
        replace_row = getattr(self, "_ini_replace_row_widget", None)
        if replace_row is not None:
            replace_row.setVisible(False)
        self.ini_code_edit.setFocus()

    def _ini_editor_close_global_search(self):
        bar = getattr(self, "_ini_global_search_bar", None)
        if bar is not None:
            bar.setVisible(False)
        results_panel = getattr(self, "_ini_global_results_panel", None)
        if results_panel is not None:
            results_panel.setVisible(False)
        results_list = getattr(self, "_ini_global_results_list", None)
        if results_list is not None:
            results_list.clear()
        splitter = getattr(self, "_ini_editor_vertical_splitter", None)
        if splitter is not None:
            try:
                total = max(1, splitter.height())
                splitter.setSizes([total, 0])
            except Exception:
                pass
        self.ini_code_edit.setFocus()

    def _ini_editor_find_next(self):
        self._ini_editor_find(forward=True)

    def _ini_editor_find_prev(self):
        self._ini_editor_find(forward=False)

    def _ini_editor_find(self, forward: bool = True):
        inp = getattr(self, "_ini_search_input", None)
        if inp is None:
            return
        needle = str(inp.text() or "").strip()
        if not needle:
            return
        from PySide6.QtGui import QTextDocument
        flags = QTextDocument.FindFlags()
        if not forward:
            flags |= QTextDocument.FindBackward
        editor = self.ini_code_edit
        found = editor.find(needle, flags)
        if not found:
            cursor = editor.textCursor()
            if forward:
                cursor.movePosition(cursor.MoveOperation.Start)
            else:
                cursor.movePosition(cursor.MoveOperation.End)
            editor.setTextCursor(cursor)
            found = editor.find(needle, flags)
        self._ini_editor_update_search_count(needle)

    def _ini_editor_update_search_count(self, needle: str):
        lbl = getattr(self, "_ini_search_count_lbl", None)
        if lbl is None:
            return
        if not needle:
            lbl.setText("")
            return
        text = self.ini_code_edit.toPlainText()
        count = text.lower().count(needle.lower())
        lbl.setText(f"{count} " + tr("ini.search.matches"))

    # ── Find and Replace ─────────────────────────────────────────────
    def _ini_editor_replace_current(self):
        inp = getattr(self, "_ini_search_input", None)
        rep = getattr(self, "_ini_replace_input", None)
        if inp is None or rep is None:
            return
        needle = str(inp.text() or "")
        replacement = str(rep.text() or "")
        if not needle:
            return
        editor = self.ini_code_edit
        cursor = editor.textCursor()
        if cursor.hasSelection() and cursor.selectedText().lower() == needle.lower():
            cursor.insertText(replacement)
            editor.setTextCursor(cursor)
        self._ini_editor_find(forward=True)

    def _ini_editor_replace_all(self):
        inp = getattr(self, "_ini_search_input", None)
        rep = getattr(self, "_ini_replace_input", None)
        if inp is None or rep is None:
            return
        needle = str(inp.text() or "")
        replacement = str(rep.text() or "")
        if not needle:
            return
        editor = self.ini_code_edit
        text = editor.toPlainText()
        import re as _re
        new_text = _re.sub(_re.escape(needle), replacement, text, flags=_re.IGNORECASE)
        if new_text != text:
            editor.setPlainText(new_text)
        self._ini_editor_update_search_count(needle)

    # ── Cross-file search ────────────────────────────────────────────
    def _ini_editor_toggle_global_search(self):
        bar = getattr(self, "_ini_global_search_bar", None)
        if bar is None:
            return
        if bar.isVisible():
            self._ini_editor_close_global_search()
            return
        self._ini_editor_start_global_search(self._ini_editor_selected_text_for_search())

    def _ini_editor_global_search(self):
        inp = getattr(self, "_ini_global_search_input", None)
        results_list = getattr(self, "_ini_global_results_list", None)
        results_panel = getattr(self, "_ini_global_results_panel", None)
        splitter = getattr(self, "_ini_editor_vertical_splitter", None)
        results_label = getattr(self, "_ini_global_results_label", None)
        if inp is None or results_list is None or results_panel is None:
            return
        term = str(inp.text() or "").strip()
        if not term:
            return
        results_list.clear()
        results_panel.setVisible(True)
        needle = term.lower()
        found_count = 0
        for root, source in self._ini_editor_usage_search_roots():
            if not root.exists() or not root.is_dir():
                continue
            for path in sorted(root.rglob("*")):
                if not path.is_file():
                    continue
                name_match = needle in path.name.lower()
                if not ini_editor_is_supported_text_file(path) and not name_match:
                    continue
                if name_match:
                    from PySide6.QtWidgets import QListWidgetItem
                    item = QListWidgetItem(f"\U0001F4C4 {path.name}  [{self._ini_editor_source_tag(source)}]  {path.parent}")
                    item.setData(Qt.UserRole, {"path": str(path), "source": source, "line": 1})
                    results_list.addItem(item)
                    found_count += 1
                if ini_editor_is_supported_text_file(path):
                    try:
                        text = self._read_text_best_effort(path)
                    except Exception:
                        continue
                    for line_no, raw_line in enumerate(text.splitlines(), start=1):
                        if needle in raw_line.lower():
                            from PySide6.QtWidgets import QListWidgetItem
                            tag = self._ini_editor_source_tag(source)
                            display = f"{path.name} [{tag}] | {tr('ini.find_usages.line').format(line=line_no)} | {raw_line.strip()}"
                            item = QListWidgetItem(display)
                            item.setData(Qt.UserRole, {"path": str(path), "source": source, "line": line_no})
                            results_list.addItem(item)
                            found_count += 1
        if found_count == 0:
            from PySide6.QtWidgets import QListWidgetItem
            results_list.addItem(QListWidgetItem(tr("ini.find_usages.none").format(term=term)))
        if results_label is not None:
            results_label.setText(tr("ini.search.global_results").format(count=found_count, term=term))
        if splitter is not None:
            try:
                sizes = splitter.sizes()
                total = sum(sizes) if sizes else max(1, splitter.height())
                bottom = sizes[1] if len(sizes) > 1 else 0
                target_bottom = max(160, bottom or min(240, max(160, total // 3)))
                splitter.setSizes([max(1, total - target_bottom), target_bottom])
            except Exception:
                pass
        self.statusBar().showMessage(tr("ini.search.global_results").format(count=found_count, term=term))

    def _ini_editor_open_global_search_result(self, item):
        if item is None:
            return
        payload = item.data(Qt.UserRole)
        if not isinstance(payload, dict):
            return
        path = str(payload.get("path", "") or "").strip()
        if not path:
            return
        source = str(payload.get("source", "primary") or "primary")
        line_no = int(payload.get("line", 1) or 1)
        self._ini_editor_open_file_in_tab(path, source)
        self._ini_editor_jump_to_line(line_no)

    # ── Line change history (git-like blame) ─────────────────────────
    def _ini_editor_history_dir(self) -> Path | None:
        root_txt = str(getattr(self, "_ini_editor_root", "") or "").strip()
        if not root_txt:
            return None
        return Path(root_txt) / ".flatlas" / "history"

    def _ini_editor_history_path(self, file_path: str | Path) -> Path | None:
        history_dir = self._ini_editor_history_dir()
        if history_dir is None:
            return None
        import hashlib
        file_key = hashlib.sha256(str(file_path).encode("utf-8", errors="replace")).hexdigest()[:16]
        return history_dir / f"{Path(file_path).name}.{file_key}.json"

    def _ini_editor_load_line_history(self, file_path: str | Path) -> dict:
        hp = self._ini_editor_history_path(file_path)
        if hp is None or not hp.exists():
            return {}
        try:
            import json
            return json.loads(hp.read_text(encoding="utf-8"))
        except Exception:
            return {}

    def _ini_editor_new_line_history_id(self, file_path: str | Path, line_index: int, content: str) -> str:
        seed = f"{file_path}|{line_index}|{content}|{time.time_ns()}"
        return f"line-{hashlib.sha1(seed.encode('utf-8', errors='replace')).hexdigest()[:16]}"

    def _ini_editor_normalize_line_history(self, history: dict, current_lines: list[str], file_path: str | Path) -> dict:
        raw_timestamps = history.get("line_timestamps", history.get("lines", {}))
        raw_snapshots = history.get("line_snapshots", {})
        raw_current_line_ids = history.get("current_line_ids", [])

        line_timestamps: dict[str, str] = {}
        if isinstance(raw_timestamps, dict):
            for key, value in raw_timestamps.items():
                if value:
                    line_timestamps[str(key)] = str(value)

        line_snapshots: dict[str, list[dict[str, str]]] = {}
        if isinstance(raw_snapshots, dict):
            for key, entries in raw_snapshots.items():
                snaps: list[dict[str, str]] = []
                if isinstance(entries, list):
                    for entry in entries:
                        if not isinstance(entry, dict):
                            continue
                        snap: dict[str, str] = {}
                        for snap_key in ("timestamp", "content", "kind"):
                            value = entry.get(snap_key)
                            if value is not None:
                                snap[snap_key] = str(value)
                        if snap:
                            snaps.append(snap)
                line_snapshots[str(key)] = snaps

        current_line_ids = [str(value) for value in raw_current_line_ids if str(value or "").strip()]
        legacy_mode = (
            len(current_line_ids) != len(current_lines)
            or any(str(key).isdigit() for key in line_timestamps)
            or any(str(key).isdigit() for key in line_snapshots)
        )
        if legacy_mode:
            migrated_ids: list[str] = []
            for index, line in enumerate(current_lines):
                line_id = self._ini_editor_new_line_history_id(file_path, index, line)
                legacy_key = str(index)
                if legacy_key in line_timestamps and line_id not in line_timestamps:
                    line_timestamps[line_id] = str(line_timestamps[legacy_key])
                if legacy_key in line_snapshots and line_id not in line_snapshots:
                    line_snapshots[line_id] = list(line_snapshots[legacy_key])
                migrated_ids.append(line_id)
            current_line_ids = migrated_ids
        elif len(current_line_ids) < len(current_lines):
            for index in range(len(current_line_ids), len(current_lines)):
                current_line_ids.append(
                    self._ini_editor_new_line_history_id(file_path, index, current_lines[index])
                )
        elif len(current_line_ids) > len(current_lines):
            current_line_ids = current_line_ids[: len(current_lines)]

        return {
            "version": 2,
            "line_timestamps": line_timestamps,
            "line_snapshots": line_snapshots,
            "current_line_ids": current_line_ids,
        }

    def _ini_editor_line_history_map(self, history: dict, current_text: str) -> dict[str, str]:
        current_lines = current_text.splitlines()
        normalized = self._ini_editor_normalize_line_history(
            history,
            current_lines,
            self._ini_editor_current_file or history.get("file", ""),
        )
        line_timestamps = normalized.get("line_timestamps", {})
        line_snapshots = normalized.get("line_snapshots", {})
        current_line_ids = normalized.get("current_line_ids", [])
        markers: dict[str, str] = {}
        for index, line_id in enumerate(current_line_ids):
            if line_id in line_timestamps or line_id in line_snapshots:
                markers[str(index)] = str(line_timestamps.get(line_id, ""))
        return markers

    def _ini_editor_save_line_history(self, file_path: str | Path, old_text: str, new_text: str) -> dict:
        hp = self._ini_editor_history_path(file_path)
        if hp is None:
            return {}
        from datetime import datetime, timezone
        history = self._ini_editor_load_line_history(file_path)
        old_lines = old_text.splitlines()
        new_lines = new_text.splitlines()
        normalized = self._ini_editor_normalize_line_history(history, old_lines, file_path)
        line_timestamps: dict[str, str] = dict(normalized.get("line_timestamps", {}))
        line_snapshots: dict[str, list[dict[str, str]]] = {
            str(key): list(value) for key, value in normalized.get("line_snapshots", {}).items()
        }
        old_line_ids = list(normalized.get("current_line_ids", []))
        now = datetime.now(timezone.utc).isoformat()
        if len(old_line_ids) < len(old_lines):
            for index in range(len(old_line_ids), len(old_lines)):
                old_line_ids.append(self._ini_editor_new_line_history_id(file_path, index, old_lines[index]))

        def _append_snapshot(line_id: str, *, content: str, kind: str) -> None:
            snapshots = line_snapshots.setdefault(line_id, [])
            snapshots.append({"timestamp": now, "content": content, "kind": kind})
            line_timestamps[line_id] = now

        new_line_ids = [""] * len(new_lines)
        matcher = difflib.SequenceMatcher(a=old_lines, b=new_lines, autojunk=False)
        for tag, i1, i2, j1, j2 in matcher.get_opcodes():
            if tag == "equal":
                for old_index, new_index in zip(range(i1, i2), range(j1, j2)):
                    new_line_ids[new_index] = old_line_ids[old_index]
                continue
            if tag == "replace":
                shared = min(i2 - i1, j2 - j1)
                for offset in range(shared):
                    old_index = i1 + offset
                    new_index = j1 + offset
                    line_id = old_line_ids[old_index]
                    new_line_ids[new_index] = line_id
                    if old_lines[old_index] != new_lines[new_index]:
                        _append_snapshot(line_id, content=old_lines[old_index], kind="changed")
                for old_index in range(i1 + shared, i2):
                    _append_snapshot(old_line_ids[old_index], content=old_lines[old_index], kind="deleted")
                for new_index in range(j1 + shared, j2):
                    line_id = self._ini_editor_new_line_history_id(file_path, new_index, new_lines[new_index])
                    new_line_ids[new_index] = line_id
                    _append_snapshot(line_id, content="", kind="added")
                continue
            if tag == "delete":
                for old_index in range(i1, i2):
                    _append_snapshot(old_line_ids[old_index], content=old_lines[old_index], kind="deleted")
                continue
            if tag == "insert":
                for new_index in range(j1, j2):
                    line_id = self._ini_editor_new_line_history_id(file_path, new_index, new_lines[new_index])
                    new_line_ids[new_index] = line_id
                    _append_snapshot(line_id, content="", kind="added")
                continue

        for new_index, line_id in enumerate(new_line_ids):
            if not line_id:
                new_line_ids[new_index] = self._ini_editor_new_line_history_id(file_path, new_index, new_lines[new_index])
                _append_snapshot(new_line_ids[new_index], content="", kind="added")

        history["version"] = 2
        history["line_timestamps"] = line_timestamps
        history["line_snapshots"] = line_snapshots
        history["current_line_ids"] = new_line_ids
        history["lines"] = self._ini_editor_line_history_map(history, new_text)
        history["file"] = str(file_path)
        history["last_modified"] = now
        try:
            hp.parent.mkdir(parents=True, exist_ok=True)
            hp.write_text(json.dumps(history, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass
        return history

    # ── Folder explorer ──────────────────────────────────────────────
    def _ini_explorer_show_folder(self, item: QTreeWidgetItem):
        explorer = getattr(self, "_ini_folder_explorer", None)
        file_tree = getattr(self, "_ini_fe_file_tree", None)
        if explorer is None or file_tree is None:
            return
        primary_txt = str(item.data(0, Qt.UserRole + 4) or "").strip()
        fallback_txt = str(item.data(0, Qt.UserRole + 5) or "").strip()
        dir_path = Path(primary_txt or fallback_txt or str(item.data(0, Qt.UserRole) or ""))
        if not dir_path.exists() or not dir_path.is_dir():
            return
        self._ini_explorer_current_dir = str(dir_path)
        path_lbl = getattr(self, "_ini_fe_path_lbl", None)
        if path_lbl is not None:
            path_lbl.setText(str(dir_path))
        file_tree.clear()
        from PySide6.QtWidgets import QFileIconProvider
        provider = QFileIconProvider()
        try:
            entries = sorted(dir_path.iterdir(), key=lambda p: (p.is_file(), p.name.lower()))
        except OSError:
            entries = []
        for entry in entries:
            if entry.name.startswith("."):
                continue
            cols = [entry.name]
            if entry.is_file():
                size = entry.stat().st_size
                if size < 1024:
                    cols.append(f"{size} B")
                elif size < 1024 * 1024:
                    cols.append(f"{size / 1024:.1f} KB")
                else:
                    cols.append(f"{size / (1024 * 1024):.1f} MB")
            else:
                cols.append("")
            from datetime import datetime
            try:
                mtime = datetime.fromtimestamp(entry.stat().st_mtime)
                cols.append(mtime.strftime("%Y-%m-%d %H:%M"))
            except Exception:
                cols.append("")
            tree_item = QTreeWidgetItem(cols)
            tree_item.setData(0, Qt.UserRole, str(entry))
            tree_item.setData(0, Qt.UserRole + 1, "dir" if entry.is_dir() else "file")
            tree_item.setIcon(0, provider.icon(QFileInfo(str(entry))))
            file_tree.addTopLevelItem(tree_item)
        if hasattr(self, "_ini_model_preview_panel"):
            self._ini_model_preview_panel.setVisible(False)
        self._ini_editor_clear_model_preview()
        if hasattr(self, "_ini_editor_text_panel"):
            self._ini_editor_text_panel.setVisible(False)
        self.ini_code_edit.setVisible(False)
        if hasattr(self, "_ini_minimap"):
            self._ini_minimap.setVisible(False)
        explorer.setVisible(True)

    def _ini_explorer_hide(self):
        explorer = getattr(self, "_ini_folder_explorer", None)
        if explorer is not None:
            explorer.setVisible(False)
        if hasattr(self, "_ini_model_preview_panel"):
            self._ini_model_preview_panel.setVisible(False)
        if hasattr(self, "_ini_editor_text_panel"):
            self._ini_editor_text_panel.setVisible(True)
        self.ini_code_edit.setVisible(True)
        if hasattr(self, "_ini_minimap"):
            self._ini_minimap.setVisible(True)

    def _ini_explorer_selected_paths(self) -> list[Path]:
        file_tree = getattr(self, "_ini_fe_file_tree", None)
        if file_tree is None:
            return []
        paths: list[Path] = []
        for item in file_tree.selectedItems():
            p = str(item.data(0, Qt.UserRole) or "").strip()
            if p:
                paths.append(Path(p))
        return paths

    def _ini_explorer_copy_files(self):
        from PySide6.QtWidgets import QFileDialog
        paths = self._ini_explorer_selected_paths()
        if not paths:
            return
        target_dir = QFileDialog.getExistingDirectory(self, tr("ini.explorer.copy_title"), str(paths[0].parent))
        if not target_dir:
            return
        import shutil
        target = Path(target_dir)
        copied = 0
        for p in paths:
            try:
                dest = target / p.name
                if p.is_dir():
                    shutil.copytree(str(p), str(dest), dirs_exist_ok=True)
                else:
                    shutil.copy2(str(p), str(dest))
                copied += 1
            except Exception:
                pass
        self.statusBar().showMessage(tr("ini.explorer.copied").format(count=copied))
        self._ini_explorer_refresh_current()

    def _ini_explorer_move_files(self):
        from PySide6.QtWidgets import QFileDialog
        paths = self._ini_explorer_selected_paths()
        if not paths:
            return
        target_dir = QFileDialog.getExistingDirectory(self, tr("ini.explorer.move_title"), str(paths[0].parent))
        if not target_dir:
            return
        import shutil
        target = Path(target_dir)
        moved = 0
        for p in paths:
            try:
                shutil.move(str(p), str(target / p.name))
                moved += 1
            except Exception:
                pass
        self.statusBar().showMessage(tr("ini.explorer.moved").format(count=moved))
        self._ini_explorer_refresh_current()

    def _ini_explorer_delete_files(self):
        paths = self._ini_explorer_selected_paths()
        if not paths:
            return
        names = "\n".join(p.name for p in paths[:10])
        if len(paths) > 10:
            names += f"\n... (+{len(paths) - 10})"
        reply = QMessageBox.question(
            self, tr("ini.explorer.delete_title"),
            tr("ini.explorer.delete_confirm").format(files=names),
            QMessageBox.Yes | QMessageBox.No,
        )
        if reply != QMessageBox.Yes:
            return
        import shutil
        deleted = 0
        for p in paths:
            try:
                if p.is_dir():
                    shutil.rmtree(str(p))
                else:
                    p.unlink()
                deleted += 1
            except Exception:
                pass
        self.statusBar().showMessage(tr("ini.explorer.deleted").format(count=deleted))
        self._ini_explorer_refresh_current()

    def _ini_explorer_rename_file(self):
        paths = self._ini_explorer_selected_paths()
        if len(paths) != 1:
            return
        old_path = paths[0]
        from PySide6.QtWidgets import QInputDialog
        new_name, ok = QInputDialog.getText(
            self, tr("ini.explorer.rename_title"),
            tr("ini.explorer.rename_prompt"),
            text=old_path.name,
        )
        if not ok or not new_name.strip():
            return
        new_path = old_path.parent / new_name.strip()
        try:
            old_path.rename(new_path)
        except Exception as ex:
            QMessageBox.warning(self, tr("ini.explorer.rename_title"), str(ex))
            return
        self.statusBar().showMessage(tr("ini.explorer.renamed").format(old=old_path.name, new=new_path.name))
        self._ini_explorer_refresh_current()

    def _ini_explorer_open_in_system(self):
        dir_path = str(getattr(self, "_ini_explorer_current_dir", "") or "").strip()
        if not dir_path:
            return
        import subprocess, sys
        if sys.platform == "win32":
            subprocess.Popen(["explorer", dir_path])
        elif sys.platform == "darwin":
            subprocess.Popen(["open", dir_path])
        else:
            subprocess.Popen(["xdg-open", dir_path])

    def _ini_explorer_open_item(self, item: QTreeWidgetItem, _column: int = 0):
        if item is None:
            return
        path = str(item.data(0, Qt.UserRole) or "").strip()
        entry_type = str(item.data(0, Qt.UserRole + 1) or "")
        if not path:
            return
        if entry_type == "dir":
            tree_item = self._ini_editor_find_tree_item_by_path(path)
            if tree_item is not None:
                tree_item.setExpanded(True)
                self._ini_explorer_show_folder(tree_item)
            return
        self._ini_explorer_hide()
        file_path = Path(path)
        self._ini_editor_open_file_in_tab(path, self._ini_editor_source_for_path(file_path), ensure_workspace=False)

    def _ini_explorer_refresh_current(self):
        dir_path = str(getattr(self, "_ini_explorer_current_dir", "") or "").strip()
        if not dir_path:
            return
        tree_item = self._ini_editor_find_tree_item_by_path(dir_path)
        if tree_item is not None:
            self._ini_explorer_show_folder(tree_item)
        self._ini_editor_reload_tree()

    # ── Right-click line history ─────────────────────────────────────
    def _ini_editor_show_line_history_menu(self, pos):
        cursor = self.ini_code_edit.cursorForPosition(pos)
        line_no, line_text, column = self._ini_editor_line_text_at_cursor(cursor)
        history = self._ini_editor_load_line_history(self._ini_editor_current_file)
        current_lines = self.ini_code_edit.toPlainText().splitlines()
        normalized = self._ini_editor_normalize_line_history(history, current_lines, self._ini_editor_current_file)
        current_line_ids = normalized.get("current_line_ids", [])
        line_id = current_line_ids[line_no] if line_no < len(current_line_ids) else ""
        line_timestamps = normalized.get("line_timestamps", {})
        line_snapshots = normalized.get("line_snapshots", {})
        has_history = bool(line_id) and (line_id in line_timestamps or line_id in line_snapshots)
        menu = self.ini_code_edit.createStandardContextMenu(pos)
        selected_text = self._ini_editor_selected_text_for_search()
        if selected_text:
            menu.addSeparator()
            search_in_file_action = menu.addAction(tr("ini.ctx.search_selection_in_file"))
            search_in_file_action.triggered.connect(
                lambda checked=False, text=selected_text: self._ini_editor_start_in_file_search(text)
            )
            search_global_action = menu.addAction(tr("ini.ctx.search_selection_global"))
            search_global_action.triggered.connect(
                lambda checked=False, text=selected_text: self._ini_editor_start_global_search(text)
            )
        path_matches = self._ini_editor_extract_line_paths(line_text)
        selected_path_match = next(
            (
                match for match in path_matches
                if int(match.get("start", -1)) <= column <= int(match.get("end", -1))
            ),
            path_matches[0] if path_matches else None,
        )
        linked_path = None
        if isinstance(selected_path_match, dict):
            linked_path = self._ini_editor_resolve_linked_path(str(selected_path_match.get("raw", "") or ""))
        ids_assignments = self._ini_editor_extract_ids_assignments(line_text)
        if linked_path is not None or ids_assignments or has_history:
            menu.addSeparator()
        if linked_path is not None:
            open_folder_action = menu.addAction(tr("ini.ctx.open_path_folder"))
            open_folder_action.triggered.connect(
                lambda checked=False, p=Path(linked_path): self._ini_editor_open_path_in_system(p)
            )
            if linked_path.is_file() and ini_editor_is_supported_text_file(linked_path):
                open_path_tab_action = menu.addAction(tr("ini.ctx.open_path_tab"))
                open_path_tab_action.triggered.connect(
                    lambda checked=False, p=Path(linked_path): self._ini_editor_open_file_in_tab(
                        str(p),
                        self._ini_editor_source_for_path(p),
                        ensure_workspace=False,
                    )
                )
            if linked_path.is_file() and ini_editor_is_supported_model_file(linked_path):
                open_model_action = menu.addAction(tr("ini.ctx.open_model_manager"))
                open_model_action.triggered.connect(
                    lambda checked=False, p=Path(linked_path): self._open_single_model_viewer_tab(p)
                )
        for ids_key, ids_value in ids_assignments:
            title_key = "ini.ctx.show_ids_info" if ids_key == "ids_info" else "ini.ctx.show_ids_name"
            action = menu.addAction(tr(title_key))
            action.triggered.connect(
                lambda checked=False, key=ids_key, value=ids_value: self._ini_editor_show_ids_value_dialog(key, value)
            )
        if has_history:
            hist_action = menu.addAction(tr("ini.ctx.line_history"))
            hist_action.triggered.connect(lambda: self._ini_editor_show_line_history_dialog(line_no))
        menu.exec(self.ini_code_edit.viewport().mapToGlobal(pos))

    def _on_ini_explorer_file_context_menu(self, pos):
        file_tree = getattr(self, "_ini_fe_file_tree", None)
        if file_tree is None:
            return
        item = file_tree.itemAt(pos)
        menu = QMenu(self)
        current_dir = str(getattr(self, "_ini_explorer_current_dir", "") or "").strip()
        new_file_act = menu.addAction(tr("ini.ctx.new_file"))
        if not current_dir:
            new_file_act.setEnabled(False)
        if item is None:
            action = menu.exec(file_tree.viewport().mapToGlobal(pos))
            if action is new_file_act:
                self._ini_editor_create_new_file(current_dir)
            return
        path = str(item.data(0, Qt.UserRole) or "").strip()
        entry_type = str(item.data(0, Qt.UserRole + 1) or "").strip().lower()
        open_tab_act = None
        system_tab_act = None
        delete_act = None
        menu.addSeparator()
        open_folder_act = menu.addAction(tr("ini.ctx.open_path_folder"))
        if path and entry_type == "file":
            open_tab_act = menu.addAction(tr("ini.ctx.open_new_tab"))
            if self._ini_editor_is_system_ini(path):
                system_tab_act = menu.addAction(tr("ini.ctx.open_system_tab"))
            delete_act = menu.addAction(tr("ini.ctx.delete_file"))
        action = menu.exec(file_tree.viewport().mapToGlobal(pos))
        if action is new_file_act:
            target_dir = Path(path).parent if path and entry_type == "file" else Path(path or current_dir)
            self._ini_editor_create_new_file(target_dir)
        elif open_tab_act is not None and action is open_tab_act:
            self._ini_explorer_open_item(item)
        elif system_tab_act is not None and action is system_tab_act:
            self._open_system_tab(path, new_tab=True)
        elif action is open_folder_act:
            self._ini_editor_open_path_in_system(Path(path))
        elif delete_act is not None and action is delete_act:
            if not item.isSelected():
                file_tree.clearSelection()
                item.setSelected(True)
            self._ini_explorer_delete_files()

    def _ini_editor_show_line_history_dialog(self, line_no: int):
        from PySide6.QtWidgets import QDialog, QVBoxLayout, QListWidget, QLabel, QDialogButtonBox
        history = self._ini_editor_load_line_history(self._ini_editor_current_file)
        current_lines = self.ini_code_edit.toPlainText().splitlines()
        normalized = self._ini_editor_normalize_line_history(history, current_lines, self._ini_editor_current_file)
        current_line_ids = normalized.get("current_line_ids", [])
        line_id = current_line_ids[line_no] if line_no < len(current_line_ids) else ""
        snapshots = normalized.get("line_snapshots", {}).get(line_id, [])
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("ini.history.title").format(line=line_no + 1))
        dlg.resize(700, 400)
        layout = QVBoxLayout(dlg)
        current_content = current_lines[line_no] if line_no < len(current_lines) else ""
        layout.addWidget(QLabel(tr("ini.history.current").format(content=current_content)))
        lst = QListWidget()
        if snapshots:
            for snap in reversed(snapshots):
                ts = str(snap.get("timestamp", ""))
                content = str(snap.get("content", ""))
                kind = str(snap.get("kind", "changed") or "changed").strip().lower()
                try:
                    from datetime import datetime
                    dt = datetime.fromisoformat(ts)
                    display_ts = dt.strftime("[%Y-%m-%d--%H:%M]")
                except Exception:
                    display_ts = f"[{ts}]"
                if kind == "added":
                    label = f"{display_ts} [+] {content}"
                elif kind == "deleted":
                    label = f"{display_ts} [-] {content}"
                else:
                    label = f"{display_ts} {content}"
                lst.addItem(label)
        else:
            ts = normalized.get("line_timestamps", {}).get(line_id, "")
            if ts:
                try:
                    from datetime import datetime
                    dt = datetime.fromisoformat(ts)
                    display_ts = dt.strftime("[%Y-%m-%d--%H:%M]")
                except Exception:
                    display_ts = f"[{ts}]"
                lst.addItem(tr("ini.history.changed_at").format(timestamp=display_ts))
        layout.addWidget(lst, 1)
        btn_box = QDialogButtonBox(QDialogButtonBox.Close)
        btn_box.rejected.connect(dlg.close)
        layout.addWidget(btn_box)
        dlg.exec()

    # ==================================================================
    #  Mod-Manager Seite
    # ==================================================================
    def _build_mod_settings_page(self):
        self.mod_settings_page = build_mod_settings_page(self, tr=tr)

    def _sync_mod_settings_tab_visibility(self):
        if not hasattr(self, "mod_settings_page") or not hasattr(self, "_center_tab_specs"):
            return
        has_context = bool(self._mod_manager_editing_profile()) and bool(str(self._primary_game_path() or "").strip())
        idx = self._center_tab_index_for_key("mod_settings")
        if has_context:
            if idx < 0:
                self._center_register_tab(self.mod_settings_page, tr("mod_settings.title"), "mod_settings", closable=False)
            else:
                spec = self._center_tab_specs[idx]
                spec["title"] = tr("mod_settings.title")
                self._center_sync_tab_bar()
            self._mod_settings_refresh()
            return
        if idx < 0:
            return
        was_current = str(self._center_current_tab_key or "").strip() == "mod_settings"
        self._center_tab_specs.pop(idx)
        self._center_sync_tab_bar()
        if was_current:
            self._center_set_current_widget(self.mod_manager_page, "mods")

    def _mod_settings_find_exe(self, game_root: Path | None, exe_name: str) -> Path | None:
        clean_name = str(exe_name or "").strip()
        if game_root is None or not clean_name:
            return None
        try:
            if game_root.is_file():
                return game_root if game_root.name.lower() == clean_name.lower() else None
        except Exception:
            return None
        direct = ci_resolve(game_root, clean_name)
        if direct is not None and direct.is_file():
            return direct
        if str(clean_name).lower() == "flserver.exe":
            return mod_manager_find_flserver_exe(game_root, ci_resolve)
        return mod_manager_find_freelancer_exe(game_root, ci_resolve)

    def _mod_settings_profile_config_path(self, profile: dict | None = None) -> Path | None:
        prof = profile if isinstance(profile, dict) else self._mod_manager_editing_profile()
        if not isinstance(prof, dict):
            return None
        source = self._mod_manager_profile_source(prof)
        if source is None:
            return None
        return source / ".flatlas_mod_settings.json"

    def _mod_settings_read_profile_config(self, profile: dict | None = None) -> dict:
        cfg_path = self._mod_settings_profile_config_path(profile)
        if cfg_path is None or not cfg_path.is_file():
            return {}
        try:
            payload = json.loads(cfg_path.read_text(encoding="utf-8"))
        except Exception:
            return {}
        return payload if isinstance(payload, dict) else {}

    def _mod_settings_write_profile_config(self, data: dict, profile: dict | None = None):
        cfg_path = self._mod_settings_profile_config_path(profile)
        if cfg_path is None:
            raise FileNotFoundError("Mod settings path could not be resolved")
        cfg_path.parent.mkdir(parents=True, exist_ok=True)
        cfg_path.write_text(
            json.dumps(dict(data or {}), indent=2, ensure_ascii=False),
            encoding="utf-8",
        )

    def _mod_settings_profile_exe_override(self, profile: dict | None = None) -> str:
        prof = profile if isinstance(profile, dict) else self._mod_manager_editing_profile()
        if not isinstance(prof, dict):
            return ""
        cfg = self._mod_settings_read_profile_config(prof)
        stored = str(cfg.get("exe_override_path", "") or "").strip()
        if stored:
            return stored
        return str(prof.get("exe_override_path", "") or "").strip()

    def _mod_settings_override_root(self, profile: dict | None = None) -> Path | None:
        raw = self._mod_settings_profile_exe_override(profile)
        if not raw:
            return None
        p = Path(raw)
        if p.is_file():
            return p.parent
        if p.exists() and p.is_dir():
            return p
        return p

    def _mod_settings_exe_paths(self, exe_name: str, profile: dict | None = None) -> tuple[Path | None, Path | None]:
        prof = profile if isinstance(profile, dict) else self._mod_manager_editing_profile()
        override_root = self._mod_settings_override_root(prof)
        if isinstance(prof, dict):
            primary_root_resolved = self._mod_manager_game_root_for_profile(prof)
            primary_txt = str(primary_root_resolved or "").strip()
            fallback_txt = ""
            mode = str(prof.get("mode", "") or "").strip().lower()
            if mode != "direct":
                fallback_txt = str(self._mod_manager_clean_root_path() or self._vanilla_game_path or "").strip()
        else:
            primary_txt = str(self._primary_game_path() or "").strip()
            fallback_txt = str(self._fallback_game_path() or "").strip()
        primary_root = Path(primary_txt) if primary_txt else None
        fallback_root = Path(fallback_txt) if fallback_txt else None
        override = self._mod_settings_find_exe(override_root, exe_name) if override_root is not None else None
        primary = override if override is not None else self._mod_settings_find_exe(primary_root, exe_name)
        allow_fallback = (str(prof.get("mode", "") or "").strip().lower() != "direct") if isinstance(prof, dict) else self._is_overlay_mode()
        fallback = None if not allow_fallback else self._mod_settings_find_exe(fallback_root, exe_name)
        return primary, fallback

    def _mod_settings_display_exe_path(self) -> str:
        stored = self._mod_settings_profile_exe_override()
        if stored:
            return stored
        primary, fallback = self._mod_settings_exe_paths("Freelancer.exe")
        chosen = primary if primary is not None else fallback
        if chosen is not None:
            return str(chosen.parent)
        primary_txt = str(self._primary_game_path() or "").strip()
        if primary_txt:
            return primary_txt
        fallback_txt = str(self._fallback_game_path() or "").strip()
        return fallback_txt

    def _mod_settings_writable_exe_path(self, exe_name: str) -> Path | None:
        primary, fallback = self._mod_settings_exe_paths(exe_name)
        if primary is not None and primary.is_file():
            return primary
        if fallback is not None and fallback.is_file():
            try:
                target = self._ensure_writable_path(fallback)
            except Exception:
                return None
            return target if target.is_file() else None
        return None

    def _mod_settings_browse_exe_path(self):
        current = str(getattr(self, "mod_settings_exe_path_edit", QLineEdit()).text() or "").strip()
        start = current or str(self._mod_settings_override_root() or self._primary_game_path() or Path.home())
        chosen = QFileDialog.getExistingDirectory(self, tr("mod_settings.exe_path_group"), start)
        if chosen and hasattr(self, "mod_settings_exe_path_edit"):
            self.mod_settings_exe_path_edit.setText(str(chosen))

    def _mod_settings_apply_exe_path(self):
        profile = self._mod_manager_editing_profile()
        if not isinstance(profile, dict):
            return
        raw = str(self.mod_settings_exe_path_edit.text() if hasattr(self, "mod_settings_exe_path_edit") else "").strip()
        normalized = raw
        if normalized:
            p = Path(normalized)
            if p.is_file():
                normalized = str(p.parent)
        pid = str(profile.get("id", "") or "").strip()
        for prof in self._mm_profiles:
            if str(prof.get("id", "") or "").strip() != pid:
                continue
            prof["exe_override_path"] = normalized
            break
        try:
            cfg = self._mod_settings_read_profile_config(profile)
            if normalized:
                cfg["exe_override_path"] = normalized
            else:
                cfg.pop("exe_override_path", None)
            self._mod_settings_write_profile_config(cfg, profile)
        except Exception as exc:
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_manager.version.failed").format(error=str(exc)),
            )
            return
        self._mod_manager_save_state()
        self._mod_settings_refresh()
        self.statusBar().showMessage(tr("mod_settings.msg.saved_exe_path").format(path=normalized or tr("mod_settings.path_default")))

    def _mod_settings_open_config_in_editor(self, _link: str = ""):
        profile = self._mod_manager_editing_profile()
        if not isinstance(profile, dict):
            return
        cfg_path = self._mod_settings_profile_config_path(profile)
        if cfg_path is None:
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_settings.err.config_unavailable"),
            )
            return
        try:
            if not cfg_path.exists():
                self._mod_settings_write_profile_config(self._mod_settings_read_profile_config(profile), profile)
        except Exception as exc:
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_settings.err.config_open_failed").format(error=str(exc)),
            )
            return
        self._ini_editor_open_file_in_tab(str(cfg_path), "primary", ensure_workspace=True)

    def _mod_settings_ensure_exe_backup(self, exe_path: Path) -> Path:
        backup = exe_path.parent / f"{exe_path.name}.old"
        if not backup.exists():
            shutil.copy2(exe_path, backup)
        return backup

    def _mod_settings_version_source_label(self, exe_name: str) -> str:
        override_root = self._mod_settings_override_root()
        primary, fallback = self._mod_settings_exe_paths(exe_name)
        if override_root is not None and primary is not None and primary.is_file():
            try:
                if primary.parent.resolve() == override_root.resolve():
                    return tr("mod_settings.exe.source_custom")
            except Exception:
                if str(primary.parent).strip().lower() == str(override_root).strip().lower():
                    return tr("mod_settings.exe.source_custom")
        if primary is not None and primary.is_file():
            return tr("mod_settings.exe.source_mod")
        if fallback is not None and fallback.is_file():
            return tr("mod_settings.exe.source_fallback")
        return tr("mod_settings.exe.source_missing")

    def _mod_settings_apply_top_view_icon_toggle(self, checked: bool):
        profile = self._mod_manager_editing_profile()
        if not isinstance(profile, dict):
            return
        cfg = self._mod_settings_read_profile_config(profile)
        cfg["top_view_icons_mod_content_enabled"] = bool(checked)
        self._mod_settings_write_profile_config(cfg, profile)
        self._refresh_all_top_view_icons()
        self.statusBar().showMessage(
            f"2D top-view icons for mod content {'enabled' if checked else 'disabled'}."
        )

    def _mod_settings_prewarm_top_view_icon_cache(self):
        profile = self._mod_manager_editing_profile()
        if not isinstance(profile, dict):
            return
        primary_root = str(self._primary_game_path() or "").strip()
        if not primary_root:
            QMessageBox.warning(self, tr("mod_settings.title"), tr("msg.no_path_text"))
            return

        if hasattr(self, "mod_settings_top_view_icons_mod_content_cb"):
            self.mod_settings_top_view_icons_mod_content_cb.setChecked(True)
        else:
            self._mod_settings_apply_top_view_icon_toggle(True)

        self._build_archetype_model_index(primary_root)
        candidates: list[tuple[str, Path, Path]] = []
        seen_cache_paths: set[str] = set()
        for archetype in sorted(self._arch_model_map.keys()):
            model_path = self._native_model_path_for_archetype_cached(archetype, primary_root)
            if model_path is None or not self._path_is_within_root(model_path, primary_root):
                continue
            preview_resolution = resolve_preview_mesh_candidate(model_path)
            if not preview_resolution.is_freelancer_native:
                continue
            cache_path = top_view_icon_cache_path(
                profile_key=self._top_view_icon_profile_key_for_model_path(model_path),
                archetype=archetype,
                model_path=model_path,
            )
            cache_key = str(cache_path)
            if cache_key in seen_cache_paths:
                continue
            seen_cache_paths.add(cache_key)
            candidates.append((archetype, model_path, cache_path))

        progress = self._make_mod_manager_progress("Prebuilding mod top-view icons...", max(1, len(candidates)))
        built_count = 0
        skipped_count = 0
        failed_count = 0
        try:
            if not candidates:
                self._update_mod_manager_progress(progress, 1, template="No mod-native 3D models found.", path="")
            for index, (archetype, model_path, cache_path) in enumerate(candidates, start=1):
                shown = f"{archetype} [{index}/{len(candidates)}]"
                self._update_mod_manager_progress(progress, index - 1, template="{path}", path=shown)
                if cache_path.exists():
                    skipped_count += 1
                    continue
                result = load_native_scene_data(model_path)
                scene_data = getattr(result, "scene_data", None)
                image = render_native_scene_top_view_icon(scene_data) if scene_data is not None else None
                if image is None or image.isNull():
                    failed_count += 1
                    continue
                if not save_top_view_icon(cache_path, image):
                    failed_count += 1
                    continue
                pixmap = QPixmap.fromImage(image)
                if not pixmap.isNull():
                    self._top_view_icon_pixmap_cache[str(cache_path)] = pixmap
                built_count += 1
            self._update_mod_manager_progress(
                progress,
                max(1, len(candidates)),
                template="Prebuilt mod top-view icons.",
                path="",
            )
        finally:
            progress.setValue(progress.maximum())
            progress.close()
            self._set_loading_visible(False)
            self._refresh_all_top_view_icons()
        QMessageBox.information(
            self,
            tr("mod_settings.title"),
            f"Mod icon cache ready.\nBuilt: {built_count}\nSkipped: {skipped_count}\nFailed: {failed_count}",
        )

    def _mod_settings_refresh(self):
        if not hasattr(self, "mod_settings_profile_lbl"):
            return
        profile = self._mod_manager_editing_profile()
        if not isinstance(profile, dict):
            self.mod_settings_profile_lbl.setText(tr("mod_settings.no_context"))
            if hasattr(self, "mod_settings_top_view_icons_mod_content_cb"):
                blocker = self.mod_settings_top_view_icons_mod_content_cb.blockSignals(True)
                self.mod_settings_top_view_icons_mod_content_cb.setChecked(False)
                self.mod_settings_top_view_icons_mod_content_cb.setEnabled(False)
                self.mod_settings_top_view_icons_mod_content_cb.blockSignals(blocker)
            if hasattr(self, "mod_settings_top_view_icons_prewarm_btn"):
                self.mod_settings_top_view_icons_prewarm_btn.setEnabled(False)
            return
        self.mod_settings_profile_lbl.setText(
            tr("mod_settings.active_mod").format(name=str(profile.get("name", "") or "").strip() or "?")
        )
        if hasattr(self, "mod_settings_top_view_icons_mod_content_cb"):
            blocker = self.mod_settings_top_view_icons_mod_content_cb.blockSignals(True)
            self.mod_settings_top_view_icons_mod_content_cb.setEnabled(True)
            self.mod_settings_top_view_icons_mod_content_cb.setChecked(
                bool(self._mod_settings_top_view_icons_mod_content_enabled(profile))
            )
            self.mod_settings_top_view_icons_mod_content_cb.blockSignals(blocker)
        if hasattr(self, "mod_settings_top_view_icons_prewarm_btn"):
            self.mod_settings_top_view_icons_prewarm_btn.setEnabled(True)
        if hasattr(self, "mod_settings_exe_path_edit"):
            self.mod_settings_exe_path_edit.setText(self._mod_settings_display_exe_path())
        if hasattr(self, "mod_settings_exe_path_resolved_lbl"):
            resolved_primary, resolved_fallback = self._mod_settings_exe_paths("Freelancer.exe")
            actual = resolved_primary if resolved_primary is not None else resolved_fallback
            if actual is not None:
                source = self._mod_settings_version_source_label("Freelancer.exe")
                self.mod_settings_exe_path_resolved_lbl.setText(
                    tr("mod_settings.exe_path_resolved").format(path=str(actual.parent), source=source)
                )
            else:
                self.mod_settings_exe_path_resolved_lbl.setText(tr("mod_settings.exe_path_unresolved"))

        from .exe_version import format_version_tuple, read_version_info

        for exe_name, label in getattr(self, "mod_settings_version_current_labels", {}).items():
            current_path, fallback_path = self._mod_settings_exe_paths(exe_name)
            display_path = current_path if current_path is not None else fallback_path
            source_text = self._mod_settings_version_source_label(exe_name)
            version_text = "-"
            if display_path is not None and display_path.is_file():
                info = read_version_info(display_path)
                if info is not None:
                    version_text = format_version_tuple(info.file_version)
            label.setText(f"{version_text} ({source_text})")
            edit = self.mod_settings_version_editors.get(exe_name)
            if isinstance(edit, QLineEdit):
                edit.setText(version_text if version_text != "-" else "")

        table = getattr(self, "mod_settings_offset_table", None)
        if table is None:
            return
        exe_path, fallback_path = self._mod_settings_exe_paths("Freelancer.exe")

        def _read_offset_display(spec):
            for candidate in (exe_path, fallback_path):
                if candidate is None or not candidate.is_file():
                    continue
                try:
                    return (
                        format_exe_offset_value(read_exe_offset_value(candidate, spec), spec),
                        candidate,
                        resolve_exe_offset(candidate, spec),
                    )
                except Exception:
                    continue
            return format_exe_offset_value(spec.default_value, spec), None, spec.offset

        for row, spec in enumerate(KNOWN_EXE_OFFSETS):
            current_value, value_source, resolved_offset = _read_offset_display(spec)
            if value_source == exe_path and exe_path is not None:
                source_note = tr("mod_settings.exe.source_mod")
            elif value_source == fallback_path and fallback_path is not None:
                source_note = tr("mod_settings.exe.source_fallback")
            else:
                source_note = tr("mod_settings.exe.source_default")
            table.setItem(row, 0, QTableWidgetItem(tr(spec.label_key)))
            table.setItem(row, 1, QTableWidgetItem(spec.exe_name))
            table.setItem(row, 2, QTableWidgetItem(f"0x{resolved_offset:X}"))
            table.setItem(row, 3, QTableWidgetItem(spec.value_type))
            table.setItem(row, 4, QTableWidgetItem(current_value))
            table.setItem(row, 6, QTableWidgetItem(f"{tr(spec.note_key)} [{source_note}]"))
            edit = self.mod_settings_offset_value_edits.get(spec.key)
            if isinstance(edit, QLineEdit):
                edit.setText(current_value)

    def _mod_settings_apply_version(self, exe_name: str):
        from .exe_version import patch_exe_version

        target = self._mod_settings_writable_exe_path(exe_name)
        if target is None or not target.is_file():
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_manager.version.no_exe").format(exe=exe_name),
            )
            return
        edit = self.mod_settings_version_editors.get(exe_name)
        new_ver = str(edit.text() if isinstance(edit, QLineEdit) else "").strip()
        if not new_ver:
            QMessageBox.information(self, tr("mod_settings.title"), tr("mod_settings.msg.no_changes"))
            return
        try:
            backup = self._mod_settings_ensure_exe_backup(target)
        except Exception as exc:
            QMessageBox.warning(self, tr("mod_settings.title"), tr("mod_manager.version.failed").format(error=str(exc)))
            return
        success, err = patch_exe_version(target, new_file_version=new_ver, new_product_version=new_ver)
        if not success:
            QMessageBox.warning(self, tr("mod_settings.title"), tr("mod_manager.version.failed").format(error=err))
            return
        self._mod_settings_refresh()
        self._mod_manager_refresh_table()
        QMessageBox.information(
            self,
            tr("mod_settings.title"),
            tr("mod_settings.msg.saved_version").format(exe=exe_name, version=new_ver, path=str(target), backup=str(backup)),
        )

    def _mod_settings_launch_exe(self, exe_name: str):
        target = self._mod_settings_writable_exe_path(exe_name)
        if target is None or not target.is_file():
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_manager.version.no_exe").format(exe=exe_name),
            )
            return
        try:
            subprocess.Popen([str(target)], cwd=str(target.parent))
        except Exception as exc:
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_settings.err.launch_failed").format(exe=exe_name, error=str(exc)),
            )
            return
        self.statusBar().showMessage(tr("mod_settings.msg.launched_exe").format(exe=exe_name, path=str(target)))

    def _mod_settings_apply_offsets(self):
        target = self._mod_settings_writable_exe_path("Freelancer.exe")
        if target is None or not target.is_file():
            QMessageBox.warning(
                self,
                tr("mod_settings.title"),
                tr("mod_manager.version.no_exe").format(exe="Freelancer.exe"),
            )
            return
        pending: list[tuple[object, float | int]] = []
        for row, spec in enumerate(KNOWN_EXE_OFFSETS):
            edit = self.mod_settings_offset_value_edits.get(spec.key)
            if not isinstance(edit, QLineEdit):
                continue
            new_text = str(edit.text() or "").strip()
            current_text = ""
            current_item = self.mod_settings_offset_table.item(row, 4)
            if current_item is not None:
                current_text = str(current_item.text() or "").strip()
            if not new_text or new_text == current_text:
                continue
            try:
                parsed_value = parse_exe_offset_value(new_text, spec)
            except Exception as exc:
                QMessageBox.warning(
                    self,
                    tr("mod_settings.title"),
                    tr("mod_settings.err.invalid_value").format(name=tr(spec.label_key), value=new_text, error=str(exc)),
                )
                return
            pending.append((spec, parsed_value))
        if not pending:
            QMessageBox.information(self, tr("mod_settings.title"), tr("mod_settings.msg.no_changes"))
            return
        try:
            backup = self._mod_settings_ensure_exe_backup(target)
            for spec, parsed_value in pending:
                write_exe_offset_value(target, spec, parsed_value)
        except Exception as exc:
            QMessageBox.warning(self, tr("mod_settings.title"), tr("mod_manager.version.failed").format(error=str(exc)))
            return
        self._mod_settings_refresh()
        QMessageBox.information(
            self,
            tr("mod_settings.title"),
            tr("mod_settings.msg.saved_offsets").format(count=len(pending), path=str(target), backup=str(backup)),
        )

    def _build_mod_manager_page(self):
        self.mod_manager_page = build_mod_manager_page(self, tr=tr, sys_platform=sys.platform)

    def _mod_manager_on_setup_notice_link(self, link: str):
        if str(link or "").strip().lower() == "settings":
            self._open_global_settings_view("mod_manager")

    def _mod_manager_update_setup_notice(self):
        if not hasattr(self, "mm_setup_notice_lbl"):
            return
        lines: list[str] = []
        if self._mod_manager_repo_root_path() is None:
            lines.append(tr("mod_manager.notice.repo_missing_with_link"))
        direct_profiles = self._mod_manager_direct_profiles()
        if not direct_profiles:
            lines.append(tr("mod_manager.notice.no_installation"))
        elif self._mod_manager_clean_target_profile() is None:
            lines.append(tr("mod_manager.notice.target_not_set"))
        lbl = self.mm_setup_notice_lbl
        if lines:
            lbl.setText("<br>".join(lines))
            lbl.setVisible(True)
        else:
            lbl.clear()
            lbl.setVisible(False)

    def _mod_manager_update_target_inline_label(self):
        if not hasattr(self, "mm_target_line_lbl"):
            return
        profile = self._mod_manager_clean_target_profile()
        if isinstance(profile, dict):
            target_name = str(profile.get("name", "") or "").strip() or tr("mod_manager.clean_none")
            self.mm_target_line_lbl.setText(tr("mod_manager.target_inline_with_remove").format(name=target_name))
            return
        self.mm_target_line_lbl.setText(tr("mod_manager.target_inline_none"))

    def _mod_manager_on_target_inline_link(self, link: str):
        if str(link or "").strip().lower() != "remove":
            return
        if self._mod_manager_has_active_entries():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.target_installation.block_active"))
            return
        self._mod_manager_clear_target_installation()

