    def _mod_manager_on_direct_selection_changed(self):
        if hasattr(self, "mm_repo_grid") and self.mm_table.selectionModel() is not None:
            if self.mm_table.selectionModel().hasSelection():
                self.mm_repo_grid.blockSignals(True)
                self.mm_repo_grid.clearSelection()
                self.mm_repo_grid.setCurrentCell(-1, -1)
                self.mm_repo_grid.blockSignals(False)
        self._mod_manager_update_action_states()

    def _mod_manager_on_repo_selection_changed(self):
        if hasattr(self, "mm_repo_grid") and self.mm_repo_grid.selectionModel() is not None:
            if self.mm_repo_grid.selectionModel().hasSelection() and hasattr(self, "mm_table"):
                self.mm_table.blockSignals(True)
                self.mm_table.clearSelection()
                self.mm_table.setCurrentCell(-1, -1)
                self.mm_table.blockSignals(False)
        self._mod_manager_update_action_states()

    def _mod_manager_log(self, message: str):
        if not hasattr(self, "mm_log"):
            return
        stamp = datetime.now().strftime("%H:%M:%S")
        self.mm_log.append(f"[{stamp}] {message}")
        self._append_mod_change_file(message, category="MOD")

    def _mod_manager_save_paths_from_ui(self):
        if hasattr(self, "gs_repo_edit"):
            self._mm_repo_root = self.gs_repo_edit.text().strip()
        if hasattr(self, "mm_linux_cmd_edit"):
            self._mm_linux_launch_cmd = self.mm_linux_cmd_edit.text().strip()
        added = self._mod_manager_sync_repo_profiles()
        self._mod_manager_save_state()
        self._mod_manager_log(tr("mod_manager.log.paths_saved"))
        if added:
            self._mod_manager_log(tr("mod_manager.log.auto_detected").format(count=added))
        self._mod_manager_refresh_table()

    def _mod_manager_browse_path(self, which: str):
        start = str(Path.home())
        if which == "repo":
            start = self.gs_repo_edit.text().strip() if hasattr(self, "gs_repo_edit") else self._mm_repo_root
        chosen = QFileDialog.getExistingDirectory(self, tr("mod_manager.pick_folder"), start or str(Path.home()))
        if not chosen:
            return
        if which == "repo" and hasattr(self, "gs_repo_edit"):
            self.gs_repo_edit.setText(chosen)

    def _mod_manager_refresh_table(self, preferred_pid: str | None = None):
        if not hasattr(self, "mm_table"):
            return
        current_pid = str(preferred_pid or "").strip()
        if not current_pid:
            cur = self._mod_manager_selected_profile()
            if cur is not None:
                current_pid = str(cur.get("id", "") or "").strip()
        self._mod_manager_sync_repo_profiles()
        self._mod_manager_update_setup_notice()
        self._mod_manager_update_target_inline_label()
        if hasattr(self, "gs_repo_edit"):
            self.gs_repo_edit.setText(self._mm_repo_root)
        if hasattr(self, "gs_xml_editor_edit"):
            self.gs_xml_editor_edit.setText(str(self._cfg.get("settings.system_editor_xml_editor_path", "") or "").strip())
        if hasattr(self, "mm_linux_cmd_edit"):
            self.mm_linux_cmd_edit.setText(str(getattr(self, "_mm_linux_launch_cmd", "") or ""))
        if hasattr(self, "mm_launch_ratio_combo"):
            want_ratio = self._mm_launch_ratio or self._mod_manager_ratio_for_resolution_text(self._mm_launch_resolution) or "16:9"
            self.mm_launch_ratio_combo.blockSignals(True)
            if self.mm_launch_ratio_combo.findText(want_ratio) < 0:
                self.mm_launch_ratio_combo.addItem(want_ratio)
            self.mm_launch_ratio_combo.setCurrentText(want_ratio)
            self.mm_launch_ratio_combo.blockSignals(False)
        if hasattr(self, "mm_launch_res_combo"):
            want_ratio = self._mm_launch_ratio or self._mod_manager_ratio_for_resolution_text(self._mm_launch_resolution) or "16:9"
            want_res = self._mm_launch_resolution or self._mod_manager_default_resolution_text()
            self.mm_launch_res_combo.blockSignals(True)
            self.mm_launch_res_combo.clear()
            self.mm_launch_res_combo.addItems(self._mod_manager_resolution_options(want_ratio))
            if self.mm_launch_res_combo.findText(want_res) < 0:
                self.mm_launch_res_combo.addItem(want_res)
            self.mm_launch_res_combo.setCurrentText(want_res)
            self.mm_launch_res_combo.blockSignals(False)
        if hasattr(self, "mm_launch_apply_res_cb"):
            self.mm_launch_apply_res_cb.blockSignals(True)
            self.mm_launch_apply_res_cb.setChecked(bool(self._mm_launch_apply_resolution))
            self.mm_launch_apply_res_cb.blockSignals(False)
            if hasattr(self, "mm_launch_ratio_lbl"):
                self.mm_launch_ratio_lbl.setEnabled(bool(self._mm_launch_apply_resolution))
            if hasattr(self, "mm_launch_ratio_combo"):
                self.mm_launch_ratio_combo.setEnabled(bool(self._mm_launch_apply_resolution))
            if hasattr(self, "mm_launch_res_lbl"):
                self.mm_launch_res_lbl.setEnabled(bool(self._mm_launch_apply_resolution))
            if hasattr(self, "mm_launch_res_combo"):
                self.mm_launch_res_combo.setEnabled(bool(self._mm_launch_apply_resolution))
            if hasattr(self, "mm_launch_depth_cb"):
                self.mm_launch_depth_cb.setEnabled(bool(self._mm_launch_apply_resolution))
        if hasattr(self, "mm_launch_depth_cb"):
            self.mm_launch_depth_cb.blockSignals(True)
            self.mm_launch_depth_cb.setChecked(bool(self._mm_launch_set_color_depth_32))
            self.mm_launch_depth_cb.blockSignals(False)
        has_active = self._mod_manager_has_active_entries()
        if hasattr(self, "mm_deactivate_btn"):
            self.mm_deactivate_btn.setEnabled(has_active)
        self._mod_manager_apply_button_styles(has_active)
        tbl = self.mm_table
        tbl.setRowCount(0)
        repo_tbl = self.mm_repo_grid if hasattr(self, "mm_repo_grid") else None
        if repo_tbl is not None:
            repo_tbl.clearContents()
            repo_tbl.setRowCount(0)
            repo_tbl.setColumnCount(5)
        active_ids = self._mod_manager_active_ids()
        editing_id = str(self._mm_editing_mod_id or "").strip()
        preferred_direct_row = -1
        preferred_repo_cell: tuple[int, int] | None = None

        repo_profiles, direct_profiles = mod_manager_partition_profiles(self._mm_profiles)

        def _status_meta(p: dict) -> tuple[str, set[str], dict[str, set[str]]]:
            return mod_manager_status_summary(
                p,
                active_ids=active_ids,
                editing_id=editing_id,
                is_target_installation=self._mod_manager_is_target_installation(p),
                conflicting_active_ids=self._mod_manager_conflicting_active_ids,
                partial_conflict_details=self._mod_manager_partial_conflict_details,
                profile_savegame_risk=self._mod_manager_profile_savegame_risk,
                tr_func=tr,
            )

        def _style_table_row(row: int, p: dict, conflicts: set[str], partial_conflicts: dict[str, set[str]]):
            pid = str(p.get("id", "") or "").strip()
            col_count = tbl.columnCount()
            if pid and pid in active_ids:
                active_bg = QColor("#ffe066")
                active_fg = QColor("#1f1f1f")
                for col in range(col_count):
                    it = tbl.item(row, col)
                    if it is None:
                        continue
                    it.setBackground(QBrush(active_bg))
                    it.setForeground(QBrush(active_fg))
                    f = it.font()
                    f.setBold(True)
                    it.setFont(f)
            elif self._mod_manager_is_target_installation(p):
                target_bg = QColor("#b8f2d3") if current_theme() in ("light", "xp") else QColor("#1c5a44")
                target_fg = QColor("#103424") if current_theme() in ("light", "xp") else QColor("#eafff3")
                for col in range(col_count):
                    it = tbl.item(row, col)
                    if it is None:
                        continue
                    it.setBackground(QBrush(target_bg))
                    it.setForeground(QBrush(target_fg))
            if conflicts:
                bad_fg = QColor("#b91c1c") if current_theme() in ("light", "xp") else QColor("#ff7b7b")
                for col in range(col_count):
                    it = tbl.item(row, col)
                    if it is not None:
                        it.setForeground(QBrush(bad_fg))
            elif partial_conflicts:
                warn_fg = QColor("#b45309") if current_theme() in ("light", "xp") else QColor("#ffd166")
                for col in range(col_count):
                    it = tbl.item(row, col)
                    if it is not None:
                        it.setForeground(QBrush(warn_fg))

        def _add_direct_profile_row(p: dict):
            nonlocal preferred_direct_row
            row = tbl.rowCount()
            tbl.insertRow(row)
            pid = str(p.get("id", "") or "").strip()
            mode = str(p.get("mode", "") or "").strip().lower()
            src = self._mod_manager_profile_source(p)
            src_txt = str(src) if src is not None else "-"
            status, conflicts, partial_conflicts = _status_meta(p)
            display_name = mod_manager_display_name(p, self._mod_manager_is_flmm_repo_profile(p))
            name_item = QTableWidgetItem(display_name)
            icon = self._mod_manager_icon_for_profile(p)
            if icon is not None and not icon.isNull():
                name_item.setIcon(icon)
            tbl.setItem(row, 0, name_item)
            tbl.setItem(
                row,
                1,
                QTableWidgetItem(tr("mod_manager.type.direct") if mode == "direct" else tr("mod_manager.type.repository")),
            )
            tbl.setItem(row, 2, QTableWidgetItem(src_txt))
            # EXE-Version column
            version_txt = ""
            game_root = self._mod_manager_game_root_for_profile(p)
            fl_exe = self._mod_manager_find_freelancer_exe(game_root)
            if fl_exe is not None:
                from .exe_version import read_version_info, format_version_tuple
                vi = read_version_info(fl_exe)
                if vi is not None:
                    version_txt = format_version_tuple(vi.file_version)
            tbl.setItem(row, 3, QTableWidgetItem(version_txt))
            tbl.setItem(row, 4, QTableWidgetItem(status))
            row_tooltip = self._mod_manager_tooltip_for_profile(p)
            for col in range(tbl.columnCount()):
                it = tbl.item(row, col)
                if it is not None:
                    it.setToolTip(row_tooltip)
            _style_table_row(row, p, conflicts, partial_conflicts)
            tbl.item(row, 0).setData(Qt.UserRole, pid)
            if current_pid and pid == current_pid:
                preferred_direct_row = row
            elif preferred_direct_row < 0 and editing_id and pid == editing_id:
                preferred_direct_row = row
            elif preferred_direct_row < 0 and pid in active_ids:
                preferred_direct_row = row

        def _add_repo_profile_cell(p: dict, index: int):
            nonlocal preferred_repo_cell
            if repo_tbl is None:
                return
            cols = max(1, int(repo_tbl.columnCount()))
            row = index // cols
            col = index % cols
            while repo_tbl.rowCount() <= row:
                repo_tbl.insertRow(repo_tbl.rowCount())
            _status, conflicts, partial_conflicts = _status_meta(p)
            display_name = mod_manager_display_name(p, self._mod_manager_is_flmm_repo_profile(p))
            item = QTableWidgetItem(display_name)
            icon = self._mod_manager_icon_for_profile(p)
            if icon is not None and not icon.isNull():
                item.setIcon(icon)
            item.setData(Qt.UserRole, str(p.get("id", "") or "").strip())
            item.setTextAlignment(Qt.AlignHCenter | Qt.AlignVCenter)
            item.setToolTip(self._mod_manager_tooltip_for_profile(p))
            font = item.font()
            font.setBold(False)
            item.setFont(font)
            item.setSizeHint(QSize(138, 96))
            if str(p.get("id", "") or "").strip() in active_ids:
                item.setBackground(QBrush(QColor("#ffe066")))
                item.setForeground(QBrush(QColor("#1f1f1f")))
            elif conflicts:
                item.setForeground(QBrush(QColor("#b91c1c") if current_theme() in ("light", "xp") else QColor("#ff7b7b")))
            elif partial_conflicts:
                item.setForeground(QBrush(QColor("#b45309") if current_theme() in ("light", "xp") else QColor("#ffd166")))
            repo_tbl.setItem(row, col, item)
            repo_tbl.setRowHeight(row, 102)
            repo_tbl.setColumnWidth(col, 142)
            if current_pid and str(p.get("id", "") or "").strip() == current_pid:
                preferred_repo_cell = (row, col)
            elif preferred_repo_cell is None and editing_id and str(p.get("id", "") or "").strip() == editing_id:
                preferred_repo_cell = (row, col)
            elif preferred_repo_cell is None and str(p.get("id", "") or "").strip() in active_ids:
                preferred_repo_cell = (row, col)

        visible_direct_profiles = [p for p in direct_profiles if not self._mod_manager_is_target_installation(p)]

        for p in visible_direct_profiles:
            _add_direct_profile_row(p)
        for idx, p in enumerate(repo_profiles):
            _add_repo_profile_cell(p, idx)
        if preferred_direct_row >= 0 and preferred_direct_row < tbl.rowCount():
            tbl.selectRow(preferred_direct_row)
        elif preferred_repo_cell is not None and repo_tbl is not None:
            item = repo_tbl.item(preferred_repo_cell[0], preferred_repo_cell[1])
            if item is not None:
                repo_tbl.setCurrentItem(item)
        elif tbl.rowCount() > 0:
            tbl.selectRow(0)
        elif repo_tbl is not None and repo_tbl.rowCount() > 0:
            for row in range(repo_tbl.rowCount()):
                for col in range(repo_tbl.columnCount()):
                    item = repo_tbl.item(row, col)
                    if item is not None and str(item.data(Qt.UserRole) or "").strip():
                        repo_tbl.setCurrentItem(item)
                        break
                if repo_tbl.currentItem() is not None:
                    break
        self._mod_manager_update_action_states()

    def _mod_manager_profile_by_id(self, pid: str | None) -> dict | None:
        want = str(pid or "").strip()
        if not want:
            return None
        for p in self._mm_profiles:
            if str(p.get("id", "") or "").strip() == want:
                return p
        return None

    def _mod_manager_launch_profile(self) -> dict | None:
        return mod_manager_launch_profile(
            self._mod_manager_selected_profile(),
            self._mod_manager_clean_target_profile(),
            self._mod_manager_last_active_entry(),
            self._mod_manager_profile_by_id,
        )

    def _mod_manager_game_root_for_profile(self, profile: dict) -> Path | None:
        return mod_manager_game_root_for_profile(
            profile,
            self._mod_manager_profile_source(profile),
            self._mod_manager_clean_root_path(),
        )

    @staticmethod
    def _mod_manager_find_freelancer_exe(game_root: Path | None) -> Path | None:
        return mod_manager_find_freelancer_exe(game_root, ci_resolve)

    def _mod_manager_icon_from_exe(self, exe_path: Path | None) -> QIcon | None:
        if exe_path is None or not exe_path.is_file():
            return None
        key = self._mod_manager_normalized_path_key(exe_path)
        if not key:
            key = str(exe_path)
        cached = self._mm_exe_icon_cache.get(key)
        if isinstance(cached, QIcon) and not cached.isNull():
            return cached
        try:
            provider = QFileIconProvider()
            icon = provider.icon(QFileInfo(str(exe_path)))
            if icon is not None and not icon.isNull():
                self._mm_exe_icon_cache[key] = icon
                return icon
        except Exception:
            return None
        return None

    def _mod_manager_repo_icon_source_profile(self) -> dict | None:
        return mod_manager_repo_icon_source_profile(
            self._mod_manager_clean_target_profile(),
            self._mod_manager_last_active_entry(),
            self._mod_manager_profile_by_id,
        )

    def _mod_manager_flatlas_icon(self) -> QIcon | None:
        icon = self.windowIcon()
        if icon is not None and not icon.isNull():
            return icon
        return None

    def _mod_manager_flmm_icon(self) -> QIcon | None:
        candidates = mod_manager_flmm_icon_candidates(getattr(self, "_mm_flmm_install_path", ""))
        seen: set[str] = set()
        for cand in candidates:
            key = self._mod_manager_normalized_path_key(cand)
            if key and key in seen:
                continue
            if key:
                seen.add(key)
            if cand.is_file():
                icon = self._mod_manager_icon_from_exe(cand)
                if icon is not None and not icon.isNull():
                    return icon
        return self._mod_manager_flatlas_icon()

    def _mod_manager_icon_for_profile(self, profile: dict | None) -> QIcon | None:
        if not isinstance(profile, dict):
            return None
        mode = str(profile.get("mode", "") or "").strip().lower()
        if mode != "direct":
            if self._mod_manager_is_flmm_repo_profile(profile):
                return self._mod_manager_flmm_icon()
            return self._mod_manager_flatlas_icon()
        icon_profile = profile
        game_root = self._mod_manager_game_root_for_profile(icon_profile)
        exe_path = self._mod_manager_find_freelancer_exe(game_root)
        return self._mod_manager_icon_from_exe(exe_path)

    def _mod_manager_launch_fl_clicked(self):
        profile = self._mod_manager_launch_profile()
        if not isinstance(profile, dict):
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_first"))
            return
        game_root = self._mod_manager_game_root_for_profile(profile)
        exe_path, _fallback_exe_path = self._mod_settings_exe_paths("Freelancer.exe", profile)
        if exe_path is None:
            root_txt = self._mod_settings_profile_exe_override(profile) or (str(game_root) if game_root is not None else "-")
            QMessageBox.warning(
                self,
                tr("mod_manager.title"),
                tr("mod_manager.launch.no_exe").format(path=root_txt),
            )
            return
        try:
            if hasattr(self, "mm_launch_res_combo"):
                self._mm_launch_resolution = self.mm_launch_res_combo.currentText().strip()
            ok_saves, saves_msg = self._mod_manager_prepare_savegames_for_profile(profile)
            if ok_saves:
                if saves_msg:
                    self._mod_manager_log(saves_msg)
            else:
                QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.saves.error").format(error=saves_msg))
                return
            if bool(getattr(self, "_mm_launch_apply_resolution", False)):
                res = self._mod_manager_parse_resolution(self._mm_launch_resolution)
                if not res:
                    QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.launch.resolution_invalid"))
                    return
                w, h = res
                ok_res, msg_res = self._mod_manager_apply_resolution_to_perfoptions(
                    w,
                    h,
                    set_color_depth_32=bool(getattr(self, "_mm_launch_set_color_depth_32", False)),
                )
                if ok_res:
                    self._mod_manager_log(msg_res)
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg_res)
                ok_fl, msg_fl = self._mod_manager_apply_resolution_to_freelancer_ini(
                    game_root,
                    w,
                    h,
                    set_color_depth_32=bool(getattr(self, "_mm_launch_set_color_depth_32", False)),
                )
                if ok_fl:
                    self._mod_manager_log(msg_fl)
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg_fl)
                ok_cam, msg_cam, mod_cam_override = self._mod_manager_apply_current_fov_to_cameras_ini(
                    profile,
                    game_root,
                    w,
                    h,
                    force_patch=False,
                )
                if ok_cam:
                    self._mod_manager_log(msg_cam)
                    if mod_cam_override:
                        QMessageBox.information(
                            self,
                            tr("mod_manager.title"),
                            tr("mod_manager.launch.camera_skipped_override"),
                        )
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg_cam)
            if sys.platform.startswith("win"):
                subprocess.Popen([str(exe_path)], cwd=str(exe_path.parent))
            else:
                cmd = str(getattr(self, "_mm_linux_launch_cmd", "") or "").strip()
                if hasattr(self, "mm_linux_cmd_edit"):
                    cmd = self.mm_linux_cmd_edit.text().strip()
                    self._mm_linux_launch_cmd = cmd
                    self._mod_manager_save_state()
                if not cmd:
                    QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.launch.linux_cmd_missing"))
                    return
                cmd_line = (
                    cmd.replace("{exe}", shlex.quote(str(exe_path)))
                    .replace("{game}", shlex.quote(str(game_root or exe_path.parent)))
                )
                subprocess.Popen(cmd_line, cwd=str(game_root or exe_path.parent), shell=True)
            self.statusBar().showMessage(tr("mod_manager.launch.started"))
        except Exception as exc:
            QMessageBox.warning(self, tr("mod_manager.title"), f"{tr('mod_manager.launch.failed')}\n{exc}")

    def _mod_manager_set_launch_resolution(self, value: str):
        res = self._mod_manager_parse_resolution(value)
        if res is None:
            return
        self._mm_launch_resolution = self._mod_manager_resolution_text(res[0], res[1])
        ratio = self._mod_manager_ratio_for_resolution_text(self._mm_launch_resolution)
        if ratio:
            self._mm_launch_ratio = ratio
        self._mod_manager_save_state()

    def _mod_manager_set_launch_ratio(self, value: str):
        ratio = str(value or "").strip()
        if not ratio:
            return
        self._mm_launch_ratio = ratio
        if hasattr(self, "mm_launch_res_combo"):
            current_res = self._mm_launch_resolution or self._mod_manager_default_resolution_text()
            options = self._mod_manager_resolution_options(ratio)
            replacement = current_res if current_res in options else (options[0] if options else current_res)
            self.mm_launch_res_combo.blockSignals(True)
            self.mm_launch_res_combo.clear()
            self.mm_launch_res_combo.addItems(options)
            if self.mm_launch_res_combo.findText(replacement) < 0:
                self.mm_launch_res_combo.addItem(replacement)
            self.mm_launch_res_combo.setCurrentText(replacement)
            self.mm_launch_res_combo.blockSignals(False)
            self._mm_launch_resolution = replacement
        self._mod_manager_save_state()

    def _mod_manager_set_launch_apply_resolution(self, checked: bool):
        self._mm_launch_apply_resolution = bool(checked)
        if hasattr(self, "mm_launch_ratio_lbl"):
            self.mm_launch_ratio_lbl.setEnabled(self._mm_launch_apply_resolution)
        if hasattr(self, "mm_launch_ratio_combo"):
            self.mm_launch_ratio_combo.setEnabled(self._mm_launch_apply_resolution)
        if hasattr(self, "mm_launch_res_lbl"):
            self.mm_launch_res_lbl.setEnabled(self._mm_launch_apply_resolution)
        if hasattr(self, "mm_launch_res_combo"):
            self.mm_launch_res_combo.setEnabled(self._mm_launch_apply_resolution)
        if hasattr(self, "mm_launch_depth_cb"):
            self.mm_launch_depth_cb.setEnabled(self._mm_launch_apply_resolution)
        if not self._mm_launch_apply_resolution:
            profile = self._mod_manager_launch_profile()
            if isinstance(profile, dict):
                game_root = self._mod_manager_game_root_for_profile(profile)
                ok_cam, msg_cam, mod_cam_override = self._mod_manager_reset_cameras_ini_to_default(
                    profile,
                    game_root,
                    force_patch=False,
                )
                if ok_cam:
                    self._mod_manager_log(msg_cam)
                    if mod_cam_override:
                        QMessageBox.information(
                            self,
                            tr("mod_manager.title"),
                            tr("mod_manager.launch.camera_skipped_override"),
                        )
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg_cam)
        self._mod_manager_save_state()

    def _mod_manager_set_launch_color_depth_32(self, checked: bool):
        self._mm_launch_set_color_depth_32 = bool(checked)
        self._mod_manager_save_state()

    def _mod_manager_set_selected_force_save_backup(self, checked: bool):
        p = self._mod_manager_selected_profile()
        if not isinstance(p, dict):
            return
        if str(p.get("mode", "") or "").strip().lower() == "direct":
            return
        pid = str(p.get("id", "") or "").strip()
        if not pid:
            return
        for prof in self._mm_profiles:
            if str(prof.get("id", "") or "").strip() != pid:
                continue
            prof["force_save_backup"] = bool(checked)
            break
        self._mod_manager_save_state()
        self._mod_manager_refresh_table(preferred_pid=pid)

    def _mod_manager_selected_profile(self) -> dict | None:
        pid = ""
        if hasattr(self, "mm_table"):
            row = self.mm_table.currentRow()
            if row >= 0:
                item = self.mm_table.item(row, 0)
                if item is not None:
                    pid = str(item.data(Qt.UserRole) or "").strip()
        if not pid and hasattr(self, "mm_repo_grid"):
            item = self.mm_repo_grid.currentItem()
            if item is not None:
                pid = str(item.data(Qt.UserRole) or "").strip()
        if not pid:
            return None
        for p in self._mm_profiles:
            if str(p.get("id", "")).strip() == pid:
                return p
        return None

    def _mod_manager_repair_caption(self) -> str:
        return "Repair target installation" if get_language() == "en" else "Zielinstallation reparieren"

    def _mod_manager_update_action_states(self):
        p = self._mod_manager_selected_profile()
        has_active = self._mod_manager_has_active_entries()
        active_ids = self._mod_manager_active_ids()
        pid = str(p.get("id", "") or "").strip() if isinstance(p, dict) else ""
        active_entry = self._mod_manager_active_entry_by_id(pid)
        conflicts = self._mod_manager_conflicting_active_ids(p) if isinstance(p, dict) else set()
        state = mod_manager_action_state(
            p,
            has_active=has_active,
            active_ids=active_ids,
            active_entry=active_entry,
            conflicts=conflicts,
            editing_mod_id=str(self._mm_editing_mod_id or ""),
            repo_setup_complete=self._mod_manager_repo_setup_complete(),
            can_edit_sp_starter_ship=self._mod_manager_can_edit_sp_starter_ship(p),
            has_profile_source=self._mod_manager_profile_source(p) is not None if isinstance(p, dict) else False,
        )
        apply_enabled_state(
            state,
            {
                "open_folder_enabled": getattr(self, "mm_open_folder_btn", None),
                "edit_ctx_enabled": getattr(self, "mm_edit_ctx_btn", None),
                "clear_edit_ctx_enabled": getattr(self, "mm_clear_edit_ctx_btn", None),
                "activate_enabled": getattr(self, "mm_activate_btn", None),
                "repair_enabled": getattr(self, "mm_repair_btn", None),
                "delete_enabled": getattr(self, "mm_delete_btn", None),
                "deactivate_enabled": getattr(self, "mm_deactivate_btn", None),
                "new_repo_enabled": getattr(self, "mm_new_repo_btn", None),
                "create_install_from_mod_enabled": getattr(self, "mm_create_install_from_mod_btn", None),
                "edit_sp_ship_enabled": getattr(self, "mm_edit_sp_ship_btn", None),
                "set_target_enabled": getattr(self, "mm_set_target_btn", None),
            },
        )
        self._mod_manager_apply_button_styles(has_active)
        if hasattr(self, "mm_opensp_cb"):
            self.mm_opensp_cb.blockSignals(True)
            self.mm_opensp_cb.setEnabled(bool(state["opensp_enabled"]))
            self.mm_opensp_cb.setVisible(bool(state["opensp_visible"]))
            self.mm_opensp_cb.setChecked(bool(state["opensp_checked"]))
            self.mm_opensp_cb.blockSignals(False)
        if hasattr(self, "mm_force_saves_cb"):
            self.mm_force_saves_cb.blockSignals(True)
            self.mm_force_saves_cb.setEnabled(bool(state["force_saves_enabled"]))
            self.mm_force_saves_cb.setVisible(bool(state["force_saves_visible"]))
            self.mm_force_saves_cb.setChecked(bool(state["force_saves_checked"]))
            self.mm_force_saves_cb.blockSignals(False)
        if hasattr(self, "mm_profile_header_lbl"):
            if str(state["profile_header_name"] or "").strip():
                self.mm_profile_header_lbl.setText(
                    tr("mod_manager.selected_profile_header").format(name=str(state["profile_header_name"]))
                )
            else:
                self.mm_profile_header_lbl.setText(tr("mod_manager.selected_profile_none"))

    def _mod_manager_can_edit_sp_starter_ship(self, profile: dict | None) -> bool:
        if not isinstance(profile, dict):
            return False
        if not bool(profile.get("opensp_enabled", False)):
            return False
        mode = str(profile.get("mode", "") or "").strip().lower()
        if mode == "direct":
            src = self._mod_manager_profile_source(profile)
            return bool(src is not None and src.exists() and src.is_dir())
        pid = str(profile.get("id", "") or "").strip()
        active = self._mod_manager_active_entry_by_id(pid)
        if not pid or not isinstance(active, dict):
            return False
        return bool(active.get("opensp_enabled", False))

    def _mod_manager_opensp_target_root(self, profile: dict) -> Path | None:
        mode = str(profile.get("mode", "") or "").strip().lower()
        if mode == "direct":
            return self._mod_manager_profile_source(profile)
        pid = str(profile.get("id", "") or "").strip()
        active = self._mod_manager_active_entry_by_id(pid)
        if not pid or not isinstance(active, dict):
            return None
        if not bool(active.get("opensp_enabled", False)):
            return None
        root = str(active.get("target_root", "") or "").strip()
        if not root:
            return None
        p = Path(root)
        return p if p.exists() and p.is_dir() else None

    def _sp_starter_current_from_ini(self, ini_path: Path) -> tuple[str, str] | None:
        try:
            raw = self._read_text_best_effort(ini_path)
        except Exception:
            return None
        return sp_starter_current_from_lines(raw.splitlines(), self._find_ini_section_bounds)

    def _sp_starter_set_in_ini(self, ini_path: Path, ship: str, loadout: str) -> tuple[bool, str]:
        try:
            raw = self._read_text_best_effort(ini_path)
        except Exception as exc:
            return False, str(exc)
        ok, patched_text, error_code = sp_starter_set_in_text(
            raw,
            ship=ship,
            loadout=loadout,
            find_ini_section_bounds=self._find_ini_section_bounds,
        )
        if not ok and error_code == "trigger_missing":
            return False, tr("mod_manager.sp_ship.err_trigger_missing")
        try:
            ok, patched_text, error_code = sp_starter_write_trigger_ini(
                ini_path,
                raw_text=raw,
                ship=ship,
                loadout=loadout,
                find_ini_section_bounds=self._find_ini_section_bounds,
            )
            if not ok and error_code == "trigger_missing":
                return False, tr("mod_manager.sp_ship.err_trigger_missing")
        except Exception as exc:
            return False, str(exc)
        return True, tr("mod_manager.sp_ship.saved").format(path=str(ini_path), ship=ship, loadout=loadout)

    def _sp_starter_loadout_pairs(self, root: Path) -> list[tuple[str, str]]:
        out: list[tuple[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for ini_path in self._sp_starter_loadout_files(root):
            try:
                sections = self._parser.parse(str(ini_path))
            except Exception:
                continue
            for sec, entries in sections:
                if str(sec).strip().lower() != "loadout":
                    continue
                nick = self._entry_get_value(entries, "nickname").strip()
                arch = self._entry_get_value(entries, "archetype").strip()
                if not nick or not arch:
                    continue
                key = (arch, nick)
                if key in seen:
                    continue
                seen.add(key)
                out.append(key)
        out.sort(key=lambda x: (x[0].lower(), x[1].lower()))
        return out

    def _sp_starter_ship_display_names(self, root: Path) -> dict[str, str]:
        shiparch_ini = ci_resolve(root, "data\\ships\\shiparch.ini")
        if shiparch_ini is None:
            return {}
        try:
            sections = self._parser.parse(str(shiparch_ini))
        except Exception:
            return {}
        out: dict[str, str] = {}
        for sec, entries in sections:
            if str(sec).strip().lower() != "ship":
                continue
            nick = self._entry_get_value(entries, "nickname").strip()
            if not nick:
                continue
            ids_name = self._entry_get_value(entries, "ids_name").strip()
            if not ids_name:
                ids_name = self._entry_get_value(entries, "strid_name").strip()
            if not ids_name:
                continue
            disp = self._display_name_from_ids_name(ids_name).strip()
            if disp:
                out[nick.lower()] = disp
        return out

    def _sp_starter_ship_slot_caps(self, root: Path) -> dict[str, tuple[int, int]]:
        shiparch_ini = ci_resolve(root, "data\\ships\\shiparch.ini")
        if shiparch_ini is None:
            return {}
        try:
            sections = self._parser.parse(str(shiparch_ini))
        except Exception:
            return {}
        out: dict[str, tuple[int, int]] = {}
        for sec, entries in sections:
            if str(sec).strip().lower() != "ship":
                continue
            nick = self._entry_get_value(entries, "nickname").strip().lower()
            if not nick:
                continue
            w_count = 0
            t_count = 0
            for k, v in entries:
                if str(k).strip().lower() != "hp_type":
                    continue
                parts = [x.strip() for x in str(v or "").split(",")]
                if len(parts) < 2:
                    continue
                hp = parts[1].lower()
                if hp.startswith("hpweapon"):
                    w_count += 1
                elif hp.startswith("hpturret"):
                    t_count += 1
            out[nick] = (w_count, t_count)
        return out

    def _sp_starter_ship_hp_flags(self, root: Path) -> dict[str, dict[str, bool]]:
        shiparch_ini = ci_resolve(root, "data\\ships\\shiparch.ini")
        if shiparch_ini is None:
            return {}
        try:
            sections = self._parser.parse(str(shiparch_ini))
        except Exception:
            return {}
        out: dict[str, dict[str, bool]] = {}
        for sec, entries in sections:
            if str(sec).strip().lower() != "ship":
                continue
            nick = self._entry_get_value(entries, "nickname").strip().lower()
            if not nick:
                continue
            flags = {
                "shield": False,
                "thruster": False,
                "mine": False,
                "torpedo": False,
                "cm": False,
            }
            for k, v in entries:
                if str(k).strip().lower() != "hp_type":
                    continue
                parts = [x.strip() for x in str(v or "").split(",")]
                if len(parts) < 2:
                    continue
                hp = parts[1].lower()
                if hp.startswith("hpshield"):
                    flags["shield"] = True
                elif hp.startswith("hpthruster"):
                    flags["thruster"] = True
                elif hp.startswith("hpmine"):
                    flags["mine"] = True
                elif hp.startswith("hptorpedo"):
                    flags["torpedo"] = True
                elif hp.startswith("hpcm"):
                    flags["cm"] = True
            out[nick] = flags
        return out

    def _sp_starter_item_display_names(self, root: Path) -> dict[str, str]:
        out = dict(self._sp_starter_ship_display_names(root))
        for fp in self._iter_equipment_ini_paths_for_usage(str(root)):
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for _sec, entries in sections:
                nick = self._entry_get_value(entries, "nickname").strip()
                if not nick:
                    continue
                key = nick.lower()
                if key in out:
                    continue
                ids_name = self._entry_get_value(entries, "ids_name").strip()
                if not ids_name:
                    ids_name = self._entry_get_value(entries, "strid_name").strip()
                if not ids_name:
                    continue
                disp = self._display_name_from_ids_name(ids_name).strip()
                if disp:
                    out[key] = disp
        return out

    def _sp_starter_loadout_files(self, root: Path) -> list[Path]:
        out: list[Path] = []
        seen: set[str] = set()
        direct_files = [
            "data\\ships\\loadouts.ini",
            "data\\ships\\loadouts_special.ini",
            "data\\solar\\loadouts.ini",
        ]
        for rel in direct_files:
            p = ci_resolve(root, rel)
            if p is None:
                continue
            key = str(p).lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(p)
        ships_dir = ci_resolve(root, "data\\ships")
        if ships_dir and ships_dir.is_dir():
            try:
                extra = sorted(x for x in ships_dir.glob("loadouts*.ini") if x.is_file())
            except Exception:
                extra = []
            for p in extra:
                key = str(p).lower()
                if key in seen:
                    continue
                seen.add(key)
                out.append(p)
        return out

    def _sp_starter_resolve_display_name(self, nick: str, name_map: dict[str, str]) -> str:
        key = str(nick or "").strip()
        if not key:
            return ""
        disp = str(name_map.get(key.lower(), "") or "").strip()
        if disp and disp.lower() != key.lower():
            return f"{key} - {disp}"
        return key

    def _sp_starter_find_loadout(self, root: Path, loadout_nick: str) -> tuple[list[tuple[str, str]] | None, Path | None]:
        target = str(loadout_nick or "").strip()
        if not target:
            return None, None
        for ini_path in self._sp_starter_loadout_files(root):
            try:
                sections = self._parser.parse(str(ini_path))
            except Exception:
                continue
            for sec_name, entries in sections:
                if str(sec_name).strip().lower() != "loadout":
                    continue
                nick = self._entry_get_value(entries, "nickname").strip()
                if nick.lower() == target.lower():
                    return entries, ini_path
        return None, None

    def _sp_starter_loadout_info_text(self, root: Path, loadout_nick: str, name_map: dict[str, str]) -> str:
        target = str(loadout_nick or "").strip()
        if not target:
            return ""
        found_entries, found_file = self._sp_starter_find_loadout(root, target)
        if found_entries is None:
            return f"Loadout nicht gefunden: {target}"

        lines: list[str] = [f"Loadout: {target}"]
        arch = self._entry_get_value(found_entries, "archetype").strip()
        if arch:
            lines.append(f"Archetype: {self._sp_starter_resolve_display_name(arch, name_map)}")
        if found_file is not None:
            lines.append(f"Datei: {found_file}")
        lines.append("")
        lines.append("Inhalt:")
        for k, v in found_entries:
            kl = str(k).strip().lower()
            val = str(v or "").strip()
            if not val:
                continue
            if kl == "equip":
                parts = [x.strip() for x in val.split(",")]
                nick = parts[0] if parts else ""
                shown = self._sp_starter_resolve_display_name(nick, name_map) if nick else ""
                if len(parts) >= 2 and parts[1]:
                    lines.append(f"- equip: {shown}, {parts[1]}")
                else:
                    lines.append(f"- equip: {shown}")
            elif kl == "cargo":
                parts = [x.strip() for x in val.split(",")]
                nick = parts[0] if parts else ""
                shown = self._sp_starter_resolve_display_name(nick, name_map) if nick else ""
                amount = parts[1] if len(parts) >= 2 else ""
                if amount:
                    lines.append(f"- cargo: {shown}, {amount}")
                else:
                    lines.append(f"- cargo: {shown}")
        return "\n".join(lines)

    def _sp_starter_equipment_by_type(self, root: Path) -> dict[str, list[str]]:
        by_type: dict[str, set[str]] = {}
        for fp in self._iter_equipment_ini_paths_for_usage(str(root)):
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for sec_name, entries in sections:
                nick = self._entry_get_value(entries, "nickname").strip()
                if not nick:
                    continue
                typ = str(sec_name or "").strip().lower()
                if not typ:
                    continue
                by_type.setdefault(typ, set()).add(nick)
        out: dict[str, list[str]] = {}
        for k, vals in by_type.items():
            out[k] = sorted(vals, key=str.lower)
        return out

    def _sp_starter_write_custom_loadout(
        self,
        root: Path,
        nickname: str,
        archetype: str,
        equip_lines: list[str],
        cargo_lines: list[str],
    ) -> tuple[bool, str]:
        loadout_ini = ci_resolve(root, "data\\ships\\loadouts.ini")
        if loadout_ini is None:
            loadout_ini = Path(root) / "DATA" / "SHIPS" / "loadouts.ini"
        try:
            loadout_ini.parent.mkdir(parents=True, exist_ok=True)
            if not loadout_ini.exists():
                write_text_atomic(loadout_ini, "")
            raw = self._read_text_best_effort(loadout_ini)
        except Exception as exc:
            return False, str(exc)
        try:
            patched = sp_starter_write_custom_loadout_ini(
                loadout_ini,
                raw_text=raw,
                nickname=nickname,
                archetype=archetype,
                equip_lines=equip_lines,
                cargo_lines=cargo_lines,
                find_ini_section_bounds=self._find_ini_section_bounds,
            )
        except Exception as exc:
            return False, str(exc)
        return True, str(loadout_ini)

    def _mod_manager_edit_sp_starter_ship(self):
        p = self._mod_manager_selected_profile()
        if not isinstance(p, dict):
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_first"))
            return
        if not self._mod_manager_can_edit_sp_starter_ship(p):
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.sp_ship.not_available"))
            return
        root = self._mod_manager_opensp_target_root(p)
        if root is None:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.sp_ship.no_target"))
            return
        m01a = ci_resolve(root, "data\\missions\\m01a\\m01a.ini")
        if m01a is None:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.sp_ship.m01a_missing"))
            return
        current = self._sp_starter_current_from_ini(m01a)
        cur_ship, cur_loadout = current if current else ("ge_fighter", "msn_playerloadout")

        pairs = self._sp_starter_loadout_pairs(root)
        ship_names = self._sp_starter_ship_display_names(root)
        ship_slot_caps = self._sp_starter_ship_slot_caps(root)
        ship_hp_flags = self._sp_starter_ship_hp_flags(root)
        item_names = self._sp_starter_item_display_names(root)
        loadouts_by_arch: dict[str, list[str]] = {}
        loadout_arch_by_nick: dict[str, str] = {}
        for arch, nick in pairs:
            akey = arch.lower()
            nkey = nick.lower()
            loadouts_by_arch.setdefault(akey, []).append(nick)
            loadout_arch_by_nick.setdefault(nkey, arch)
        for akey in list(loadouts_by_arch.keys()):
            uniq = sorted(set(loadouts_by_arch[akey]), key=str.lower)
            loadouts_by_arch[akey] = uniq
        presets: list[tuple[str, str, str]] = [
            ("Default", "ge_fighter", "msn_playerloadout"),
            ("Ozu Dragon", "ku_dragon", "MSN09_Ozu"),
            ("Tobias Fighter", "ge_fighter4", "MSN07_Tobias"),
            ("Juni Defender", "li_elite2", "MSN11_Juni"),
        ]

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("mod_manager.sp_ship.title"))
        dlg.resize(1280, 760)
        dlg.setMinimumWidth(1200)
        lay = QVBoxLayout(dlg)
        lay.setAlignment(Qt.AlignTop)
        info = QLabel(tr("mod_manager.sp_ship.info").format(path=m01a.name))
        info.setWordWrap(False)
        info.setToolTip(str(m01a))
        info.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Fixed)
        info.setMaximumHeight(info.sizeHint().height() + 2)
        lay.addWidget(info)
        cur_lbl = QLabel(tr("mod_manager.sp_ship.current").format(ship=cur_ship, loadout=cur_loadout))
        cur_lbl.setWordWrap(False)
        cur_lbl.setToolTip(f"{cur_ship}, {cur_loadout}")
        cur_lbl.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Fixed)
        cur_lbl.setMaximumHeight(cur_lbl.sizeHint().height() + 2)
        lay.addWidget(cur_lbl)
        form = QFormLayout()
        preset_cb = QComboBox(dlg)
        preset_cb.addItem(tr("mod_manager.sp_ship.preset_custom"), ("", ""))
        for title, ship, load in presets:
            preset_cb.addItem(f"{title}: {ship}, {load}", (ship, load))
        ship_cb = QComboBox(dlg)
        ship_cb.setEditable(True)
        loadout_cb = QComboBox(dlg)
        loadout_cb.setEditable(True)
        ships = sorted({a for a, _n in pairs})
        for s in ships:
            disp = str(ship_names.get(s.lower(), "") or "").strip()
            label = f"{s} - {disp}" if disp and disp.lower() != s.lower() else s
            ship_cb.addItem(label, s)
        loadout_cb.setEditText(cur_loadout)

        def _selected_ship_arch() -> str:
            data = ship_cb.currentData()
            if isinstance(data, str) and data.strip():
                return data.strip()
            txt = ship_cb.currentText().strip()
            if " - " in txt:
                txt = txt.split(" - ", 1)[0].strip()
            return txt

        _rebuild_guard = {"active": False}

        def _rebuild_loadouts_for_ship(preferred: str = ""):
            if _rebuild_guard["active"]:
                return
            _rebuild_guard["active"] = True
            try:
                arch = _selected_ship_arch().strip()
                options = loadouts_by_arch.get(arch.lower(), []) if arch else []
                keep = preferred.strip() or loadout_cb.currentText().strip()
                loadout_cb.blockSignals(True)
                loadout_cb.clear()
                for n in options:
                    loadout_cb.addItem(n, n)
                if keep:
                    idx = -1
                    for i in range(loadout_cb.count()):
                        if str(loadout_cb.itemData(i) or "").strip().lower() == keep.lower():
                            idx = i
                            break
                    if idx >= 0:
                        loadout_cb.setCurrentIndex(idx)
                    else:
                        loadout_cb.setEditText(keep)
                elif loadout_cb.count() > 0:
                    loadout_cb.setCurrentIndex(0)
                loadout_cb.blockSignals(False)
            finally:
                _rebuild_guard["active"] = False

        def _set_ship_value(arch: str):
            want = str(arch or "").strip()
            if not want:
                return
            idx = -1
            for i in range(ship_cb.count()):
                data = ship_cb.itemData(i)
                if str(data or "").strip().lower() == want.lower():
                    idx = i
                    break
            if idx >= 0:
                ship_cb.setCurrentIndex(idx)
            else:
                ship_cb.setEditText(want)

        _set_ship_value(cur_ship)
        _rebuild_loadouts_for_ship(cur_loadout)

        def _on_loadout_change(_idx: int):
            data = loadout_cb.currentData()
            load_nick = ""
            if isinstance(data, str):
                load_nick = data.strip()
            if not load_nick:
                load_nick = loadout_cb.currentText().strip()
            if load_nick.endswith(")") and " (" in load_nick:
                load_nick = load_nick.rsplit(" (", 1)[0].strip()
            if load_nick:
                arch = str(loadout_arch_by_nick.get(load_nick.lower(), "") or "").strip()
                if arch:
                    _set_ship_value(arch)
                    _rebuild_loadouts_for_ship(load_nick)

        def _on_preset_change(_idx: int):
            data = preset_cb.currentData()
            if isinstance(data, tuple) and len(data) == 2 and data[0] and data[1]:
                _set_ship_value(str(data[0]))
                _rebuild_loadouts_for_ship(str(data[1]))

        loadout_cb.currentIndexChanged.connect(_on_loadout_change)
        ship_cb.currentIndexChanged.connect(lambda _i: _rebuild_loadouts_for_ship())
        ship_cb.editTextChanged.connect(lambda _t: _rebuild_loadouts_for_ship())
        preset_cb.currentIndexChanged.connect(_on_preset_change)
        form.addRow(tr("mod_manager.sp_ship.preset"), preset_cb)
        form.addRow(tr("mod_manager.sp_ship.ship"), ship_cb)
        form.addRow(tr("mod_manager.sp_ship.loadout"), loadout_cb)
        form_wrap = QWidget(dlg)
        form_wrap.setLayout(form)
        form_wrap.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Fixed)
        lay.addWidget(form_wrap)

        custom_enable_cb = QCheckBox(tr("mod_manager.sp_ship.custom_enable"), dlg)
        lay.addWidget(custom_enable_cb)
        custom_box = QGroupBox(tr("mod_manager.sp_ship.custom_group"), dlg)
        custom_box.setEnabled(False)
        cform = QFormLayout(custom_box)
        custom_name_edit = QLineEdit(dlg)
        custom_name_edit.setPlaceholderText(tr("mod_manager.sp_ship.custom_placeholder"))
        cform.addRow(tr("mod_manager.sp_ship.custom_nickname"), custom_name_edit)

        equip_by_type = self._sp_starter_equipment_by_type(root)
        all_equip_nicks = sorted({x for vals in equip_by_type.values() for x in vals}, key=str.lower)

        def _opts(type_keys: list[str], contains: list[str] | None = None) -> list[str]:
            vals: set[str] = set()
            for k in type_keys:
                vals.update(equip_by_type.get(k.lower(), []))
            if contains:
                for n in all_equip_nicks:
                    nl = n.lower()
                    if any(c.lower() in nl for c in contains):
                        vals.add(n)
            return sorted(vals, key=str.lower)

        def _combo(options: list[str]) -> QComboBox:
            cb = QComboBox(dlg)
            cb.setEditable(True)
            cb.addItem("")
            for opt in options:
                cb.addItem(self._sp_starter_resolve_display_name(opt, item_names), opt)
            return cb

        def _combo_nick(cb: QComboBox) -> str:
            data = cb.currentData()
            if isinstance(data, str) and data.strip():
                return data.strip()
            txt = cb.currentText().strip()
            if " - " in txt:
                txt = txt.split(" - ", 1)[0].strip()
            return txt

        def _set_combo_nick(cb: QComboBox, nick: str, *, only_if_empty: bool = False):
            want = str(nick or "").strip()
            if not want:
                return
            if only_if_empty and _combo_nick(cb).strip():
                return
            idx = -1
            for i in range(cb.count()):
                data = cb.itemData(i)
                if str(data or "").strip().lower() == want.lower():
                    idx = i
                    break
            if idx >= 0:
                cb.setCurrentIndex(idx)
            else:
                cb.setEditText(want)

        def _pair_row(left: QWidget, right: QWidget) -> QWidget:
            w = QWidget(dlg)
            h = QHBoxLayout(w)
            h.setContentsMargins(0, 0, 0, 0)
            h.setSpacing(6)
            h.addWidget(left, 1)
            h.addWidget(right, 1)
            return w

        engine_cb = _combo(_opts(["engine"]))
        shield_cb = _combo(_opts(["shieldgenerator"]))
        scanner_cb = _combo(_opts(["scanner"]))
        tractor_cb = _combo(_opts(["tractor"]))
        thruster_cb = _combo(_opts(["thruster"]))
        power_cb = _combo(_opts(["power"]))
        armor_cb = _combo(_opts(["armor"]))
        weapon_cbs = [_combo(_opts(["gun", "cgun"], [])) for _ in range(6)]
        turret_cbs = [_combo(_opts(["turret", "cturret"], [])) for _ in range(2)]
        mine_cb = _combo(_opts(["minedropper"], ["mine"]))
        torp_cb = _combo(_opts(["gun", "cgun"], ["torpedo"]))
        cm_cb = _combo(_opts(["countermeasuredropper"], ["cm_", "countermeasure"]))
        battery_cb = _combo(_opts(["shieldbattery"], ["battery"]))
        repair_cb = _combo(_opts(["repairkit"], ["repair"]))
        mine_amt = QSpinBox(dlg); mine_amt.setRange(0, 999); mine_amt.setValue(50)
        torp_amt = QSpinBox(dlg); torp_amt.setRange(0, 999); torp_amt.setValue(50)
        cm_amt = QSpinBox(dlg); cm_amt.setRange(0, 999); cm_amt.setValue(50)
        bat_amt = QSpinBox(dlg); bat_amt.setRange(0, 999); bat_amt.setValue(30)
        rep_amt = QSpinBox(dlg); rep_amt.setRange(0, 999); rep_amt.setValue(30)
        _custom_defaults = {
            "mine": mine_amt.value(),
            "torp": torp_amt.value(),
            "cm": cm_amt.value(),
            "bat": bat_amt.value(),
            "rep": rep_amt.value(),
        }
        row_es = _pair_row(engine_cb, shield_cb); cform.addRow("Engine / Shield", row_es)
        cform.addRow("Scanner / Tractor", _pair_row(scanner_cb, tractor_cb))
        row_tp = _pair_row(thruster_cb, power_cb); cform.addRow("Thruster / Power", row_tp)
        cform.addRow("Armor", armor_cb)
        row_w12 = _pair_row(weapon_cbs[0], weapon_cbs[1]); cform.addRow("Weapon 1/2", row_w12)
        row_w34 = _pair_row(weapon_cbs[2], weapon_cbs[3]); cform.addRow("Weapon 3/4", row_w34)
        row_w56 = _pair_row(weapon_cbs[4], weapon_cbs[5]); cform.addRow("Weapon 5/6", row_w56)
        row_t12 = _pair_row(turret_cbs[0], turret_cbs[1]); cform.addRow("Turret 1/2", row_t12)
        row_mine = _pair_row(mine_cb, mine_amt); cform.addRow("Mine / Ammo", row_mine)
        row_torp = _pair_row(torp_cb, torp_amt); cform.addRow("Torpedo / Ammo", row_torp)
        row_cm = _pair_row(cm_cb, cm_amt); cform.addRow("Countermeasure / Ammo", row_cm)
        cform.addRow("Battery / Amount", _pair_row(battery_cb, bat_amt))
        cform.addRow("Repair / Amount", _pair_row(repair_cb, rep_amt))
        custom_box.setVisible(False)
        lay.addWidget(custom_box)

        def _set_form_row_visible(field: QWidget, visible: bool):
            field.setVisible(visible)
            lbl = cform.labelForField(field)
            if lbl is not None:
                lbl.setVisible(visible)

        def _apply_ship_slot_caps():
            arch = _selected_ship_arch().strip().lower()
            caps = ship_slot_caps.get(arch, (len(weapon_cbs), len(turret_cbs)))
            flags = ship_hp_flags.get(arch, {"shield": True, "thruster": True, "mine": True, "torpedo": True, "cm": True})
            max_w = max(0, int(caps[0]))
            max_t = max(0, int(caps[1]))
            _set_form_row_visible(row_w12, max_w >= 1)
            _set_form_row_visible(row_w34, max_w >= 3)
            _set_form_row_visible(row_w56, max_w >= 5)
            _set_form_row_visible(row_t12, max_t >= 1)
            _set_form_row_visible(row_mine, bool(flags.get("mine", False)))
            _set_form_row_visible(row_torp, bool(flags.get("torpedo", False)))
            _set_form_row_visible(row_cm, bool(flags.get("cm", False)))
            shield_cb.setEnabled(bool(flags.get("shield", False)))
            if not shield_cb.isEnabled():
                shield_cb.setCurrentIndex(0)
            thruster_cb.setEnabled(bool(flags.get("thruster", False)))
            if not thruster_cb.isEnabled():
                thruster_cb.setCurrentIndex(0)
            for i, cb in enumerate(weapon_cbs, start=1):
                enabled = i <= max_w
                cb.setEnabled(enabled)
                if not enabled:
                    cb.setCurrentIndex(0)
            for i, cb in enumerate(turret_cbs, start=1):
                enabled = i <= max_t
                cb.setEnabled(enabled)
                if not enabled:
                    cb.setCurrentIndex(0)

        def _selected_loadout_nick() -> str:
            data = loadout_cb.currentData()
            if isinstance(data, str) and data.strip():
                return data.strip()
            txt = loadout_cb.currentText().strip()
            if txt.endswith(")") and " (" in txt:
                txt = txt.rsplit(" (", 1)[0].strip()
            return txt

        def _prefill_custom_from_loadout():
            load_nick = _selected_loadout_nick()
            entries, _src_file = self._sp_starter_find_loadout(root, load_nick)
            if entries is None:
                return
            equip_map: dict[str, str] = {}
            cargo_map: dict[str, int] = {}
            for k, v in entries:
                kl = str(k).strip().lower()
                val = str(v or "").strip()
                if not val:
                    continue
                if kl == "equip":
                    parts = [x.strip() for x in val.split(",")]
                    if not parts:
                        continue
                    nick = parts[0]
                    mount = parts[1].lower() if len(parts) >= 2 and parts[1] else ""
                    if mount:
                        equip_map[mount] = nick
                    else:
                        nl = nick.lower()
                        if "engine" in nl:
                            equip_map.setdefault("engine", nick)
                        elif "shield" in nl:
                            equip_map.setdefault("shield", nick)
                        elif "scanner" in nl:
                            equip_map.setdefault("scanner", nick)
                        elif "tractor" in nl:
                            equip_map.setdefault("tractor", nick)
                        elif "thruster" in nl:
                            equip_map.setdefault("hpthruster01", nick)
                        elif "armor" in nl:
                            equip_map.setdefault("armor", nick)
                        elif "power" in nl:
                            equip_map.setdefault("power", nick)
                elif kl == "cargo":
                    parts = [x.strip() for x in val.split(",")]
                    if not parts:
                        continue
                    nick = parts[0]
                    try:
                        amt = int(float(parts[1])) if len(parts) >= 2 else 0
                    except Exception:
                        amt = 0
                    cargo_map[nick.lower()] = amt

            _set_combo_nick(engine_cb, equip_map.get("engine", ""), only_if_empty=True)
            _set_combo_nick(shield_cb, equip_map.get("hpshield01", "") or equip_map.get("shield", ""), only_if_empty=True)
            _set_combo_nick(scanner_cb, equip_map.get("scanner", ""), only_if_empty=True)
            _set_combo_nick(tractor_cb, equip_map.get("tractor", ""), only_if_empty=True)
            _set_combo_nick(thruster_cb, equip_map.get("hpthruster01", ""), only_if_empty=True)
            _set_combo_nick(power_cb, equip_map.get("power", ""), only_if_empty=True)
            _set_combo_nick(armor_cb, equip_map.get("armor", ""), only_if_empty=True)
            for i, cb in enumerate(weapon_cbs, start=1):
                _set_combo_nick(cb, equip_map.get(f"hpweapon{i:02d}", ""), only_if_empty=True)
            for i, cb in enumerate(turret_cbs, start=1):
                _set_combo_nick(cb, equip_map.get(f"hpturret{i:02d}", ""), only_if_empty=True)
            _set_combo_nick(mine_cb, equip_map.get("hpmine01", ""), only_if_empty=True)
            _set_combo_nick(torp_cb, equip_map.get("hptorpedo01", ""), only_if_empty=True)
            _set_combo_nick(cm_cb, equip_map.get("hpcm01", ""), only_if_empty=True)

            mine_n = _combo_nick(mine_cb).lower()
            torp_n = _combo_nick(torp_cb).lower()
            cm_n = _combo_nick(cm_cb).lower()
            if mine_n and mine_amt.value() == _custom_defaults["mine"]:
                mine_amt.setValue(max(0, int(cargo_map.get(f"{mine_n}_ammo", mine_amt.value()))))
            if torp_n and torp_amt.value() == _custom_defaults["torp"]:
                torp_amt.setValue(max(0, int(cargo_map.get(f"{torp_n}_ammo", torp_amt.value()))))
            if cm_n and cm_amt.value() == _custom_defaults["cm"]:
                cm_amt.setValue(max(0, int(cargo_map.get(f"{cm_n}_ammo", cm_amt.value()))))

            bat_cands = [k for k in cargo_map.keys() if "battery" in k]
            rep_cands = [k for k in cargo_map.keys() if "repair" in k]
            if bat_cands:
                _set_combo_nick(battery_cb, bat_cands[0], only_if_empty=True)
                if bat_amt.value() == _custom_defaults["bat"]:
                    bat_amt.setValue(max(0, int(cargo_map.get(bat_cands[0], bat_amt.value()))))
            if rep_cands:
                _set_combo_nick(repair_cb, rep_cands[0], only_if_empty=True)
                if rep_amt.value() == _custom_defaults["rep"]:
                    rep_amt.setValue(max(0, int(cargo_map.get(rep_cands[0], rep_amt.value()))))

        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, parent=dlg)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        lay.addWidget(bb)
        custom_enable_cb.toggled.connect(custom_box.setEnabled)
        custom_enable_cb.toggled.connect(custom_box.setVisible)
        custom_enable_cb.toggled.connect(lambda on: loadout_cb.setEnabled(not on))
        custom_enable_cb.toggled.connect(lambda on: preset_cb.setEnabled(not on))
        custom_enable_cb.toggled.connect(lambda on: _prefill_custom_from_loadout() if on else None)
        ship_cb.currentIndexChanged.connect(lambda _i: _apply_ship_slot_caps())
        ship_cb.editTextChanged.connect(lambda _t: _apply_ship_slot_caps())
        loadout_cb.currentIndexChanged.connect(lambda _i: _prefill_custom_from_loadout() if custom_enable_cb.isChecked() else None)
        _apply_ship_slot_caps()
        if dlg.exec() != QDialog.Accepted:
            return
        ship_data = ship_cb.currentData()
        if isinstance(ship_data, str) and ship_data.strip():
            ship = ship_data.strip()
        else:
            ship = ship_cb.currentText().strip()
            if " - " in ship:
                ship = ship.split(" - ", 1)[0].strip()
        loadout = loadout_cb.currentText().strip()
        if custom_enable_cb.isChecked():
            custom_nick = custom_name_edit.text().strip()
            if not custom_nick:
                custom_nick = f"custom_{ship}_start"
            def _norm(v: str) -> str:
                return str(v or "").strip()
            equip_lines: list[str] = []
            cargo_lines: list[str] = []
            def _push_e(v: str, hp: str = ""):
                vv = _norm(v)
                if not vv:
                    return
                equip_lines.append(f"{vv}, {hp}" if hp else vv)
            def _push_c(v: str, amt: int):
                vv = _norm(v)
                if not vv or int(amt) <= 0:
                    return
                cargo_lines.append(f"{vv}, {int(amt)}")
            _push_e(_combo_nick(engine_cb))
            if shield_cb.isEnabled():
                _push_e(_combo_nick(shield_cb), "HpShield01")
            _push_e(_combo_nick(scanner_cb))
            _push_e(_combo_nick(tractor_cb))
            if thruster_cb.isEnabled():
                _push_e(_combo_nick(thruster_cb), "HpThruster01")
            _push_e(_combo_nick(power_cb))
            _push_e(_combo_nick(armor_cb))
            for i, cb in enumerate(weapon_cbs, start=1):
                if cb.isEnabled():
                    _push_e(_combo_nick(cb), f"HpWeapon{i:02d}")
            for i, cb in enumerate(turret_cbs, start=1):
                if cb.isEnabled():
                    _push_e(_combo_nick(cb), f"HpTurret{i:02d}")
            mine_n = _norm(_combo_nick(mine_cb)) if mine_cb.isEnabled() else ""
            if mine_n:
                _push_e(mine_n, "HpMine01")
                _push_c(f"{mine_n}_ammo", mine_amt.value())
            torp_n = _norm(_combo_nick(torp_cb)) if torp_cb.isEnabled() else ""
            if torp_n:
                _push_e(torp_n, "HpTorpedo01")
                _push_c(f"{torp_n}_ammo", torp_amt.value())
            cm_n = _norm(_combo_nick(cm_cb)) if cm_cb.isEnabled() else ""
            if cm_n:
                _push_e(cm_n, "HpCM01")
                _push_c(f"{cm_n}_ammo", cm_amt.value())
            _push_c(_combo_nick(battery_cb), bat_amt.value())
            _push_c(_combo_nick(repair_cb), rep_amt.value())
            if not equip_lines:
                QMessageBox.warning(self, tr("mod_manager.title"), "Bitte mindestens ein Equipment für das Custom-Loadout auswählen.")
                return
            ok_custom, custom_path = self._sp_starter_write_custom_loadout(root, custom_nick, ship, equip_lines, cargo_lines)
            if not ok_custom:
                QMessageBox.warning(self, tr("mod_manager.title"), f"Custom-Loadout konnte nicht gespeichert werden:\n{custom_path}")
                return
            self._mod_manager_log(f"Custom-Loadout gespeichert: {custom_nick} ({ship}) in {custom_path}")
            loadout = custom_nick
        if not ship or not loadout:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.sp_ship.err_empty"))
            return
        ok, msg = self._sp_starter_set_in_ini(m01a, ship, loadout)
        if not ok:
            QMessageBox.warning(self, tr("mod_manager.title"), msg)
            return
        self._mod_manager_log(msg)
        self.statusBar().showMessage(tr("mod_manager.sp_ship.saved_short").format(ship=ship, loadout=loadout))

    def _mod_manager_set_selected_opensp(self, checked: bool):
        p = self._mod_manager_selected_profile()
        if not p:
            return
        mode = str(p.get("mode", "") or "").strip().lower()
        if mode != "direct":
            pid = str(p.get("id", "") or "").strip()
            for prof in self._mm_profiles:
                if str(prof.get("id", "") or "").strip() == pid:
                    prof["opensp_enabled"] = False
                    break
            if hasattr(self, "mm_opensp_cb"):
                self.mm_opensp_cb.blockSignals(True)
                self.mm_opensp_cb.setChecked(False)
                self.mm_opensp_cb.blockSignals(False)
            self._mod_manager_save_state()
            return
        pid = str(p.get("id", "") or "").strip()
        if not pid:
            return
        for prof in self._mm_profiles:
            if str(prof.get("id", "") or "").strip() == pid:
                prof["opensp_enabled"] = bool(checked)
                break
        live_msg = ""
        if mode == "direct":
            if checked:
                ok, msg = self._mod_manager_apply_opensp_to_direct_profile(p)
                if ok:
                    live_msg = tr("mod_manager.msg.opensp_enabled") + ("\n" + msg if msg else "")
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg)
                    p["opensp_enabled"] = False
                    if hasattr(self, "mm_opensp_cb"):
                        self.mm_opensp_cb.blockSignals(True)
                        self.mm_opensp_cb.setChecked(False)
                        self.mm_opensp_cb.blockSignals(False)
            else:
                ok, msg = self._mod_manager_disable_opensp_for_direct_profile(p)
                if ok:
                    live_msg = msg
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg)
                    p["opensp_enabled"] = True
                    if hasattr(self, "mm_opensp_cb"):
                        self.mm_opensp_cb.blockSignals(True)
                        self.mm_opensp_cb.setChecked(True)
                        self.mm_opensp_cb.blockSignals(False)
        # Wenn der ausgewählte Mod gerade aktiv ist: OpenSP sofort live umschalten.
        active_entry = self._mod_manager_active_entry_by_id(pid)
        if isinstance(active_entry, dict):
            active = dict(active_entry)
            clean_root = Path(str(active.get("target_root", "") or "").strip())
            backup_dir = Path(str(active.get("backup_dir", "") or "").strip())
            if checked and not bool(active.get("opensp_enabled", False)):
                ok, msg, opensp_overwritten_rel = self._mod_manager_apply_opensp_patch(
                    clean_root,
                    backup_dir=backup_dir,
                    existing_created_rel=[str(x) for x in active.get("created_rel", []) if str(x).strip()],
                    existing_overwritten_rel=[
                        str(x) for x in active.get("overwritten_rel", []) if str(x).strip()
                    ] + [str(x) for x in active.get("opensp_overwritten_rel", []) if str(x).strip()],
                )
                if ok:
                    active["opensp_enabled"] = True
                    merged = [str(x) for x in active.get("opensp_overwritten_rel", []) if str(x).strip()]
                    for rel in opensp_overwritten_rel:
                        if rel not in merged:
                            merged.append(rel)
                    active["opensp_overwritten_rel"] = merged
                    for idx, entry in enumerate(self._mm_active):
                        if isinstance(entry, dict) and str(entry.get("mod_id", "") or "").strip() == pid:
                            self._mm_active[idx] = active
                            break
                    live_msg = tr("mod_manager.msg.opensp_enabled") + ("\n" + msg if msg else "")
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg)
                    for prof in self._mm_profiles:
                        if str(prof.get("id", "") or "").strip() == pid:
                            prof["opensp_enabled"] = False
                            break
                    if hasattr(self, "mm_opensp_cb"):
                        self.mm_opensp_cb.blockSignals(True)
                        self.mm_opensp_cb.setChecked(False)
                        self.mm_opensp_cb.blockSignals(False)
            elif (not checked) and bool(active.get("opensp_enabled", False)):
                ok, msg = self._mod_manager_disable_opensp_for_active(active)
                if ok:
                    live_msg = msg
                else:
                    QMessageBox.warning(self, tr("mod_manager.title"), msg)
                    for prof in self._mm_profiles:
                        if str(prof.get("id", "") or "").strip() == pid:
                            prof["opensp_enabled"] = True
                            break
                    if hasattr(self, "mm_opensp_cb"):
                        self.mm_opensp_cb.blockSignals(True)
                        self.mm_opensp_cb.setChecked(True)
                        self.mm_opensp_cb.blockSignals(False)
        self._mod_manager_save_state()
        self._mod_manager_refresh_table(preferred_pid=pid)
        if live_msg:
            self._mod_manager_log(live_msg)
            self.statusBar().showMessage(live_msg.splitlines()[0])

    def _on_mod_manager_table_context_menu(self, pos):
        widget = self.sender()
        if widget is None:
            widget = self.mm_table if hasattr(self, "mm_table") else None
        if widget is None:
            return
        if widget is getattr(self, "mm_table", None):
            row = widget.rowAt(pos.y())
            if row >= 0:
                widget.selectRow(row)
        elif widget is getattr(self, "mm_repo_grid", None):
            item = widget.itemAt(pos)
            if item is not None:
                widget.setCurrentItem(item)

        p = self._mod_manager_selected_profile()
        menu = QMenu(self)
        if p is not None:
            mode = str(p.get("mode", "") or "").strip().lower()
            pid = str(p.get("id", "") or "").strip()
            is_selected_active = self._mod_manager_active_entry_by_id(pid) is not None
            a_activate = menu.addAction(tr("mod_manager.ctx.activate_clean")) if mode != "direct" else None
            a_info = menu.addAction(tr("mod_manager.ctx.info"))
            a_error_log = menu.addAction(tr("mod_manager.ctx.error_log"))
            a_open = menu.addAction(tr("mod_manager.ctx.open_folder"))
            a_open_xml = menu.addAction(tr("mod_manager.ctx.edit_xml")) if self._mod_manager_xml_path(p) is not None else None
            a_edit = menu.addAction(tr("mod_manager.ctx.open_for_editing"))
            a_create_install = menu.addAction(tr("mod_manager.ctx.create_install_from_mod")) if mode != "direct" else None
            a_repair = menu.addAction(self._mod_manager_repair_caption()) if mode != "direct" else None
            a_set_target = menu.addAction(tr("mod_manager.ctx.set_target_installation")) if mode == "direct" else None
            a_deactivate = menu.addAction(
                tr("mod_manager.ctx.deactivate_selected") if is_selected_active else tr("mod_manager.ctx.deactivate_active")
            )
            a_opensp = (
                menu.addAction(
                    tr("mod_manager.ctx.opensp_disable") if bool(p.get("opensp_enabled", False))
                    else tr("mod_manager.ctx.opensp_enable")
                )
                if mode == "direct"
                else None
            )
            # --- EXE version change entries ---
            _ctx_game_root = self._mod_manager_game_root_for_profile(p)
            _ctx_fl_exe = self._mod_manager_find_freelancer_exe(_ctx_game_root)
            _ctx_srv_exe = mod_manager_find_flserver_exe(_ctx_game_root, ci_resolve) if _ctx_game_root else None
            a_change_exe_ver = menu.addAction(tr("mod_manager.ctx.change_exe_version")) if _ctx_fl_exe is not None else None
            a_change_srv_ver = menu.addAction(tr("mod_manager.ctx.change_server_version")) if _ctx_srv_exe is not None else None
            menu.addSeparator()
            a_delete = menu.addAction(tr("mod_manager.ctx.delete_mod"))
            menu.addSeparator()
            a_refresh = menu.addAction(tr("mod_manager.ctx.refresh"))
            chosen = menu.exec(widget.viewport().mapToGlobal(pos))
            if chosen is a_info:
                self._mod_manager_show_selected_mod_info()
            elif chosen is a_error_log:
                self._mod_manager_show_selected_error_log()
            elif chosen is a_open:
                self._mod_manager_open_selected_folder()
            elif a_open_xml is not None and chosen is a_open_xml:
                self._mod_manager_open_selected_xml()
            elif chosen is a_edit:
                self._mod_manager_use_for_editing()
            elif a_create_install is not None and chosen is a_create_install:
                self._mod_manager_create_installation_from_selected_mod()
            elif a_repair is not None and chosen is a_repair:
                self._mod_manager_repair_selected()
            elif a_activate is not None and chosen is a_activate:
                self._mod_manager_activate_selected()
            elif a_set_target is not None and chosen is a_set_target:
                self._mod_manager_set_selected_as_target_installation()
            elif chosen is a_deactivate:
                self._mod_manager_deactivate_clicked()
            elif a_opensp is not None and chosen is a_opensp:
                if hasattr(self, "mm_opensp_cb"):
                    self.mm_opensp_cb.setChecked(not bool(p.get("opensp_enabled", False)))
            elif a_change_exe_ver is not None and chosen is a_change_exe_ver:
                self._mod_manager_change_exe_version(_ctx_fl_exe, "Freelancer.exe")
            elif a_change_srv_ver is not None and chosen is a_change_srv_ver:
                self._mod_manager_change_exe_version(_ctx_srv_exe, "FLServer.exe")
            elif chosen is a_delete:
                self._mod_manager_delete_selected()
            elif chosen is a_refresh:
                self._mod_manager_refresh_table()
            return

        a_new = menu.addAction(tr("mod_manager.ctx.new_mod"))
        a_direct = menu.addAction(tr("mod_manager.ctx.add_direct_mod"))
        a_create_install = menu.addAction(tr("mod_manager.ctx.create_install_from_mod"))
        menu.addSeparator()
        a_open_settings = menu.addAction(tr("mod_manager.btn.open_global_settings"))
        a_refresh = menu.addAction(tr("mod_manager.ctx.refresh"))
        chosen = menu.exec(widget.viewport().mapToGlobal(pos))
        if chosen is a_new:
            self._mod_manager_create_repo_mod()
        elif chosen is a_direct:
            self._mod_manager_add_direct_mod()
        elif chosen is a_create_install:
            self._mod_manager_create_installation_from_selected_mod()
        elif chosen is a_open_settings:
            self._open_global_settings_view("mod_manager")
        elif chosen is a_refresh:
            self._mod_manager_refresh_table()

    def _mod_manager_create_repo_mod(self):
        repo_root = self._mod_manager_repo_root_path()
        if repo_root is None:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.warn.set_repo_first_non_flmm"))
            return
        if not self._mod_manager_repo_setup_complete():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.warn.setup_incomplete"))
            return
        name, ok = QInputDialog.getText(self, tr("mod_manager.dialog.new_title"), tr("mod_manager.dialog.mod_name"))
        if not ok:
            return
        name = str(name or "").strip()
        if not name:
            return
        safe = re.sub(r"[^A-Za-z0-9._ -]+", "_", name).strip()
        if not safe:
            safe = "NewMod"
        target = repo_root / safe
        if target.exists():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.warn.folder_exists").format(path=str(target)))
            return
        try:
            target.mkdir(parents=True, exist_ok=False)
        except Exception as exc:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.warn.folder_create_failed").format(error=str(exc)))
            return
        profile = {
            "id": self._mod_manager_make_id(name),
            "name": name,
            "mode": "repo",
            "repo_folder": safe,
            "direct_path": "",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "opensp_enabled": False,
        }
        self._mm_profiles.append(profile)
        self._mm_repo_root = str(repo_root)
        self._mod_manager_save_state()
        self._mod_manager_refresh_table(preferred_pid=str(profile.get("id", "") or ""))
        self._mod_manager_log(tr("mod_manager.log.created").format(name=name))
        if self._mod_manager_clean_target_profile() is not None and not self._mod_manager_has_active_entries():
            ok_edit, msg_edit = self._mod_manager_switch_edit_context(profile)
            self._mod_manager_refresh_table(preferred_pid=str(profile.get("id", "") or ""))
            if ok_edit and str(msg_edit or "").strip():
                self.statusBar().showMessage(msg_edit)
                self._mod_manager_log(msg_edit)

    def _mod_manager_find_direct_profile_by_path(self, path: Path | str | None) -> dict | None:
        want = self._mod_manager_normalized_path_key(path)
        if not want:
            return None
        for profile in self._mod_manager_direct_profiles():
            existing = self._mod_manager_normalized_path_key(profile.get("direct_path", ""))
            if existing and existing == want:
                return profile
        return None

    def _mod_manager_add_direct_profile(self, src: Path, *, name: str) -> tuple[bool, dict | None, str]:
        existing = self._mod_manager_find_direct_profile_by_path(src)
        if existing is not None:
            return False, existing, tr("mod_manager.warn.direct_exists").format(path=str(src))
        profile = {
            "id": self._mod_manager_make_id(name + str(src)),
            "name": str(name or "").strip() or src.name,
            "mode": "direct",
            "repo_folder": "",
            "direct_path": str(src),
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "opensp_enabled": False,
        }
        self._mm_profiles.append(profile)
        return True, profile, ""

    def _mod_manager_create_installation_from_selected_mod(self):
        profile = self._mod_manager_selected_profile()
        if not isinstance(profile, dict) or str(profile.get("mode", "") or "").strip().lower() == "direct":
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_repo_first"))
            return
        if self._mod_manager_has_active_entries():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.target_installation.block_active"))
            return
        direct_profiles = self._mod_manager_direct_profiles()
        if not direct_profiles:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.notice.no_installation"))
            return

        labels = [str(item.get("name", "") or item.get("direct_path", "") or "").strip() for item in direct_profiles]
        picked_label, ok = QInputDialog.getItem(
            self,
            tr("mod_manager.dialog.create_install_from_mod_title"),
            tr("mod_manager.dialog.create_install_pick_source"),
            labels,
            0,
            False,
        )
        if not ok or not str(picked_label or "").strip():
            return
        source_profile = next((item for item, label in zip(direct_profiles, labels) if label == picked_label), None)
        if not isinstance(source_profile, dict):
            return
        source_root = self._mod_manager_profile_source(source_profile)
        if source_root is None or not source_root.exists() or not source_root.is_dir():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.err.source_not_found"))
            return

        default_name = f"{str(profile.get('name', '') or '').strip()} - Copy".strip(" -")
        install_name, ok = QInputDialog.getText(
            self,
            tr("mod_manager.dialog.create_install_from_mod_title"),
            tr("mod_manager.dialog.display_name"),
            text=default_name,
        )
        if not ok:
            return
        install_name = str(install_name or "").strip() or default_name or "New Installation"

        dest_parent = QFileDialog.getExistingDirectory(
            self,
            tr("mod_manager.dialog.create_install_pick_destination"),
            str(source_root.parent),
        )
        if not dest_parent:
            return
        safe_folder = self._mod_manager_safe_name_for_fs(install_name) or "FreelancerInstall"
        target_root = Path(dest_parent) / safe_folder
        if target_root.exists():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.warn.folder_exists").format(path=str(target_root)))
            return

        self._set_loading_visible(True, tr("mod_manager.msg.create_installation_copying"))
        old_target_id = str(getattr(self, "_mm_clean_profile_id", "") or "")
        profile_id = str(profile.get("id", "") or "").strip()
        new_profile: dict | None = None
        try:
            shutil.copytree(source_root, target_root)
            added, new_profile, add_msg = self._mod_manager_add_direct_profile(target_root, name=install_name)
            if not added or not isinstance(new_profile, dict):
                try:
                    shutil.rmtree(target_root, ignore_errors=True)
                except Exception:
                    pass
                QMessageBox.warning(self, tr("mod_manager.title"), add_msg or tr("mod_manager.warn.direct_exists").format(path=str(target_root)))
                return

            self._mm_clean_profile_id = str(new_profile.get("id", "") or "").strip()
            ok_activate, msg = self._mod_manager_activate_profile(profile, show_dialog=False)
            if not ok_activate:
                self._mm_profiles = [p for p in self._mm_profiles if p is not new_profile]
                self._mm_clean_profile_id = old_target_id
                self._mod_manager_save_state()
                try:
                    shutil.rmtree(target_root, ignore_errors=True)
                except Exception:
                    pass
                QMessageBox.warning(self, tr("mod_manager.title"), msg)
                return

            active_entry = self._mod_manager_active_entry_by_id(profile_id)
            if isinstance(active_entry, dict) and str(active_entry.get("target_root", "") or "").strip() == str(target_root):
                backup_dir = Path(str(active_entry.get("backup_dir", "") or "").strip())
                self._mm_active = [
                    entry for entry in self._mm_active
                    if not (
                        isinstance(entry, dict)
                        and str(entry.get("mod_id", "") or "").strip() == profile_id
                        and str(entry.get("target_root", "") or "").strip() == str(target_root)
                    )
                ]
                try:
                    if backup_dir.exists():
                        shutil.rmtree(backup_dir, ignore_errors=True)
                except Exception:
                    pass

            self._mm_clean_profile_id = old_target_id

            self._mod_manager_save_state()
            self._mod_manager_refresh_table(preferred_pid=str(new_profile.get("id", "") or ""))
            self._update_active_mod_indicator()
            self._mod_manager_log(tr("mod_manager.log.direct_added").format(name=install_name))
            self._mod_manager_log(tr("mod_manager.log.created_install_from_mod").format(name=install_name, mod=str(profile.get("name", "") or "")))
            QMessageBox.information(
                self,
                tr("mod_manager.title"),
                tr("mod_manager.msg.create_install_from_mod_done").format(
                    name=install_name,
                    path=str(target_root),
                    mod=str(profile.get("name", "") or ""),
                ) + "\n\n" + msg,
            )
        except Exception as exc:
            if isinstance(new_profile, dict):
                self._mm_profiles = [p for p in self._mm_profiles if p is not new_profile]
            self._mm_clean_profile_id = old_target_id
            self._mod_manager_save_state()
            try:
                shutil.rmtree(target_root, ignore_errors=True)
            except Exception:
                pass
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.err.create_install_from_mod_failed").format(error=str(exc)))
        finally:
            self._set_loading_visible(False)

    def _mod_manager_add_direct_mod(self):
        start = self.gs_repo_edit.text().strip() if hasattr(self, "gs_repo_edit") else str(Path.home())
        chosen = QFileDialog.getExistingDirectory(self, tr("mod_manager.dialog.pick_direct"), start or str(Path.home()))
        if not chosen:
            return
        src = Path(chosen)
        name, ok = QInputDialog.getText(
            self, tr("mod_manager.dialog.direct_title"), tr("mod_manager.dialog.display_name"), text=src.name
        )
        if not ok:
            return
        name = str(name or "").strip() or src.name
        added, profile, msg = self._mod_manager_add_direct_profile(src, name=name)
        if not added or not isinstance(profile, dict):
            QMessageBox.warning(self, tr("mod_manager.title"), msg)
            return
        self._mod_manager_save_state()
        self._mod_manager_refresh_table(preferred_pid=str(profile.get("id", "") or ""))
        self._mod_manager_log(tr("mod_manager.log.direct_added").format(name=name))

    def _mod_manager_delete_selected(self):
        p = self._mod_manager_selected_profile()
        if not p:
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_first"))
            return
        pid = str(p.get("id", "") or "").strip()
        mode = str(p.get("mode", "") or "").strip().lower()
        name = str(p.get("name", "") or "").strip()
        active_ids = self._mod_manager_active_ids()
        editing_id = str(self._mm_editing_mod_id or "").strip()
        if active_ids:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.delete.block_active"))
            return
        if pid and pid == editing_id:
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.delete.block_editing"))
            return
        if mode == "direct":
            confirm_text = tr("mod_manager.delete.confirm_direct").format(name=name)
        else:
            confirm_text = tr("mod_manager.delete.confirm_repo").format(name=name)
        ans = QMessageBox.question(self, tr("mod_manager.delete.title"), confirm_text)
        if ans != QMessageBox.Yes:
            return
        src = self._mod_manager_profile_source(p)
        self._mm_profiles = [x for x in self._mm_profiles if str(x.get("id", "")).strip() != pid]
        if mode == "repo" and src is not None and src.exists():
            ans_del_files = QMessageBox.question(
                self,
                tr("mod_manager.delete.folder_title"),
                tr("mod_manager.delete.folder_confirm").format(path=str(src)),
            )
            if ans_del_files == QMessageBox.Yes:
                try:
                    shutil.rmtree(src)
                except Exception as exc:
                    QMessageBox.warning(
                        self, tr("mod_manager.title"), tr("mod_manager.delete.folder_failed").format(error=str(exc))
                    )
        self._mod_manager_save_state()
        self._mod_manager_refresh_table()
        self._mod_manager_log(tr("mod_manager.log.deleted").format(name=str(p.get("name", "") or "")))

    def _mod_manager_change_exe_version(self, exe_path: Path, exe_label: str):
        """Prompt user for a new version, create backup, and patch the EXE."""
        from .exe_version import read_version_info, patch_exe_version, format_version_tuple

        if exe_path is None or not exe_path.is_file():
            QMessageBox.warning(self, tr("mod_manager.version.title"), tr("mod_manager.version.no_exe").format(exe=exe_label))
            return

        current_info = read_version_info(exe_path)
        current_ver = format_version_tuple(current_info.file_version) if current_info else "0.0.0.0"

        new_ver, ok = QInputDialog.getText(
            self,
            tr("mod_manager.version.title"),
            tr("mod_manager.version.prompt").format(exe=exe_label),
            text=current_ver,
        )
        if not ok:
            return
        new_ver = str(new_ver or "").strip()
        if not new_ver:
            return

        # Create backup
        backup_path = exe_path.parent / (exe_path.name + ".old")
        if backup_path.exists():
            ans = QMessageBox.question(
                self,
                tr("mod_manager.version.title"),
                tr("mod_manager.version.backup_exists").format(path=str(backup_path)),
            )
            if ans != QMessageBox.Yes:
                return
        try:
            shutil.copy2(exe_path, backup_path)
        except Exception as exc:
            QMessageBox.warning(self, tr("mod_manager.version.title"), tr("mod_manager.version.failed").format(error=str(exc)))
            return

        success, err = patch_exe_version(exe_path, new_file_version=new_ver, new_product_version=new_ver)
        if success:
            QMessageBox.information(
                self,
                tr("mod_manager.version.title"),
                tr("mod_manager.version.success").format(exe=exe_label, version=new_ver, backup=str(backup_path)),
            )
            self._mod_manager_refresh_table()
        else:
            QMessageBox.warning(self, tr("mod_manager.version.title"), tr("mod_manager.version.failed").format(error=err))

    def _mod_manager_open_selected_folder(self):
        p = self._mod_manager_selected_profile()
        if not p:
            return
        src = self._mod_manager_profile_source(p)
        if src is None:
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(src)))

    def _mod_manager_open_selected_xml(self):
        p = self._mod_manager_selected_profile()
        if not p:
            return
        xml_path = self._mod_manager_xml_path(p)
        if xml_path is None or not xml_path.is_file():
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.xml.not_found"))
            return
        editor_path = str(self._cfg.get("settings.system_editor_xml_editor_path", "") or "").strip()
        if not editor_path:
            QMessageBox.warning(
                self,
                tr("mod_manager.title"),
                tr("mod_manager.xml.editor_missing"),
            )
            self._open_global_settings_view("system_editor")
            return
        editor_exe = Path(editor_path)
        if not editor_exe.is_file():
            QMessageBox.warning(
                self,
                tr("mod_manager.title"),
                tr("mod_manager.xml.editor_invalid").format(path=editor_path),
            )
            self._open_global_settings_view("system_editor")
            return
        try:
            subprocess.Popen([str(editor_exe), str(xml_path)])
        except Exception:
            try:
                subprocess.Popen(f'"{editor_exe}" "{xml_path}"')
            except Exception:
                QMessageBox.warning(
                    self,
                    tr("mod_manager.title"),
                    tr("mod_manager.xml.open_failed").format(path=str(xml_path)),
                )

    def _mod_manager_open_savegames_folder(self):
        path = self._mod_manager_accounts_dir()
        try:
            path.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

    def _mod_manager_set_selected_as_target_installation(self):
        if self._mod_manager_has_active_entries():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.target_installation.block_active"))
            return
        p = self._mod_manager_selected_profile()
        if not isinstance(p, dict):
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_first"))
            return
        if str(p.get("mode", "") or "").strip().lower() != "direct":
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.target_installation.direct_only"))
            return
        src = self._mod_manager_profile_source(p)
        if src is None or not src.exists() or not src.is_dir():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.err.clean_invalid"))
            return
        self._mm_clean_profile_id = str(p.get("id", "") or "").strip()
        self._mm_clean_root = str(src)
        self._mod_manager_save_state()
        self._mod_manager_refresh_table(preferred_pid=self._mm_clean_profile_id)
        self.statusBar().showMessage(
            tr("mod_manager.target_installation.set").format(name=str(p.get("name", "") or "").strip())
        )

    def _mod_manager_clear_target_installation(self):
        if self._mod_manager_has_active_entries():
            QMessageBox.warning(self, tr("mod_manager.title"), tr("mod_manager.target_installation.block_active"))
            return
        self._mm_clean_profile_id = ""
        self._mm_clean_root = ""
        self._mod_manager_save_state()
        self._mod_manager_refresh_table()
        self.statusBar().showMessage(tr("mod_manager.target_installation.cleared"))

    def _mod_manager_activate_selected(self):
        p = self._mod_manager_selected_profile()
        self._mod_manager_save_paths_from_ui()
        if p is None:
            p = self._mod_manager_selected_profile()
        if not p:
            QMessageBox.information(self, tr("mod_manager.title"), tr("mod_manager.select_first"))
            return
        pid = str(p.get("id", "") or "").strip()
        self._set_loading_visible(True, tr("status.loading"))
        try:
            ok, msg = self._mod_manager_activate_profile(p, show_dialog=True)
        finally:
            self._set_loading_visible(False)
        self._mod_manager_refresh_table(preferred_pid=pid)
        self._update_active_mod_indicator()
        self._mod_manager_log(msg)
        if ok:
            self.statusBar().showMessage(tr("mod_manager.msg.activated"))

    def _mod_manager_deactivate_clicked(self):
        p = self._mod_manager_selected_profile()
        pid = str(p.get("id", "") or "").strip() if isinstance(p, dict) else ""
        ok, msg = self._mod_manager_deactivate_active(pid or None, show_dialog=True)
        self._mod_manager_refresh_table()
        self._update_active_mod_indicator()
        self._mod_manager_log(msg)
