    def _iter_equipment_ini_paths_for_usage(self, game_path: str) -> list[Path]:
        paths: list[Path] = []
        seen_rel: set[str] = set()
        roots: list[str] = []
        gp = str(game_path or "").strip()
        if gp:
            roots.append(gp)
        fallback = str(self._fallback_game_path() or "").strip()
        if fallback:
            try:
                same_root = Path(fallback).resolve() == Path(gp).resolve()
            except Exception:
                same_root = fallback == gp
            if not same_root:
                roots.append(fallback)
        for root in roots:
            data_dir = ci_find(Path(root), "DATA")
            if not data_dir:
                continue
            equip_dir = ci_find(data_dir, "EQUIPMENT")
            if not equip_dir or not equip_dir.is_dir():
                continue
            try:
                ini_files = sorted(p for p in equip_dir.rglob("*.ini") if p.is_file())
            except Exception:
                ini_files = []
            for ini_path in ini_files:
                try:
                    rel_key = str(ini_path.relative_to(equip_dir)).replace("\\", "/").lower()
                except Exception:
                    rel_key = str(ini_path).lower()
                if rel_key in seen_rel:
                    continue
                seen_rel.add(rel_key)
                paths.append(ini_path)
        return paths

    def _name_editor_render_usage_rows(self, rows: list[dict]):
        tbl = self.name_usage_table
        tbl.setSortingEnabled(False)
        tbl.setRowCount(0)
        for row in rows:
            r = tbl.rowCount()
            tbl.insertRow(r)
            tbl.setItem(r, 0, QTableWidgetItem(str(row.get("system", ""))))
            tbl.setItem(r, 1, QTableWidgetItem(str(row.get("section", ""))))
            tbl.setItem(r, 2, QTableWidgetItem(str(row.get("nickname", ""))))
            tbl.setItem(r, 3, QTableWidgetItem(str(row.get("archetype", ""))))
            tbl.setItem(r, 4, QTableWidgetItem(str(row.get("path", ""))))
        tbl.setSortingEnabled(True)

    @staticmethod
    def _entry_get_value(entries: list[tuple[str, str]], key: str) -> str:
        want = str(key or "").strip().lower()
        for k, v in entries:
            if str(k).strip().lower() == want:
                return str(v or "").strip()
        return ""

    def _name_editor_on_id_selection_changed(self):
        row_idx = self.name_ids_table.currentRow()
        if row_idx < 0:
            self.name_selected_id_edit.setText("")
            self.name_text_edit.setText("")
            self._name_editor_render_usage_rows([])
            return
        it = self.name_ids_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        if not isinstance(row, dict):
            return
        gid = int(row.get("global_id", 0) or 0)
        self.name_selected_id_edit.setText(str(gid))
        self.name_text_edit.setText(str(row.get("text", "")))
        self._name_editor_render_usage_rows(self._name_editor_usage_map.get(gid, []))

    @staticmethod
    def _name_from_nickname_guess(nickname: str) -> str:
        return name_from_nickname_guess(nickname)

    def _name_editor_on_missing_selection_changed(self):
        row_idx = self.name_missing_table.currentRow()
        if row_idx < 0:
            return
        it = self.name_missing_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        if not isinstance(row, dict):
            return
        if not self.name_missing_text_edit.text().strip():
            self.name_missing_text_edit.setText(self._name_from_nickname_guess(str(row.get("nickname", ""))))

    def _name_editor_selected_name_row(self) -> dict | None:
        row_idx = self.name_ids_table.currentRow()
        if row_idx < 0:
            return None
        it = self.name_ids_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        return row if isinstance(row, dict) else None

    def _jump_to_usage_entry(self, usage: dict) -> bool:
        if not isinstance(usage, dict):
            return False
        path = str(usage.get("path", "") or "").strip()
        nickname = str(usage.get("nickname", "") or "").strip()
        section = str(usage.get("section", "") or "").strip().lower()
        if not path or not nickname or section not in ("object", "zone"):
            return False
        try:
            target_path = str(Path(path).resolve())
        except Exception:
            target_path = path
        current_path = str(getattr(self, "_filepath", "") or "")
        try:
            current_path = str(Path(current_path).resolve()) if current_path else ""
        except Exception:
            pass
        if target_path != current_path:
            self._load_from_browser(path)
        want = nickname.lower()
        if section == "zone":
            item = next((z for z in self._zones if z.nickname.strip().lower() == want), None)
            if item is None:
                return False
            self._select_zone(item)
        else:
            item = next((o for o in self._objects if o.nickname.strip().lower() == want and not hasattr(o, "sys_path")), None)
            if item is None:
                return False
            self._select(item)
        try:
            self.view.centerOn(item)
        except Exception:
            pass
        try:
            self._jump_view3d_to_item_preserving_camera(item)
        except Exception:
            pass
        self.statusBar().showMessage(tr("status.centered").format(name=nickname))
        return True

    @staticmethod
    def _usage_location_line(usage: dict) -> str:
        return usage_location_line(usage)

    def _choose_jump_usage(self, usage_rows: list[dict], title: str, label: str) -> dict | None:
        if not usage_rows:
            return None
        if len(usage_rows) == 1:
            return usage_rows[0]
        items: list[str] = []
        by_item: dict[str, dict] = {}
        for idx, usage in enumerate(usage_rows, start=1):
            text = f"{idx:02d} | {self._usage_location_line(usage)}"
            items.append(text)
            by_item[text] = usage
        picked, ok = QInputDialog.getItem(self, title, label, items, 0, False)
        if not ok or not picked:
            return None
        return by_item.get(str(picked))

    def _show_non_system_usage_locations(self, usage_rows: list[dict], empty_key: str, found_key: str):
        if not usage_rows:
            QMessageBox.information(self, tr("msg.error"), tr(empty_key))
            return
        lines = [self._usage_location_line(u) for u in usage_rows]
        max_lines = 18
        shown = lines[:max_lines]
        if len(lines) > max_lines:
            shown.append(f"... +{len(lines) - max_lines}")
        QMessageBox.information(self, tr("msg.error"), tr(found_key).format(locations="\n".join(shown)))

    def _name_editor_jump_to_selected_usage(self):
        row = self._name_editor_selected_name_row()
        if row is None:
            return
        gid = int(row.get("global_id", 0) or 0)
        usage_rows = self._name_editor_usage_map.get(gid, [])
        jump_rows = [u for u in usage_rows if str(u.get("section", "")).strip().lower() in ("object", "zone")]
        if not jump_rows:
            self._show_non_system_usage_locations(usage_rows, "name.msg.no_jump_target", "name.msg.non_system_locations")
            return
        picked = self._choose_jump_usage(jump_rows, tr("name.msg.jump_choose_title"), tr("name.msg.jump_choose_text"))
        if picked is None:
            return
        if not self._jump_to_usage_entry(picked):
            QMessageBox.information(self, tr("msg.error"), tr("name.msg.no_jump_target"))

    def _name_editor_update_selected(self):
        row = self._name_editor_selected_name_row()
        if row is None:
            return
        text = self.name_text_edit.text().strip()
        if not text:
            return
        gid = str(row.get("global_id", "0"))
        try:
            new_gid = self._ensure_ids_name_in_user_dll(gid, text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        self._populate_name_editor_data(self._primary_game_path())
        self.name_search_edit.setText(str(new_gid))
        self.statusBar().showMessage(tr("status.name_saved").format(ids=new_gid))

    def _name_editor_create_entry(self):
        text = self.name_text_edit.text().strip() or self.name_missing_text_edit.text().strip()
        if not text:
            return
        try:
            new_gid = self._ensure_ids_name_in_user_dll("0", text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        self._populate_name_editor_data(self._primary_game_path())
        self.name_search_edit.setText(str(new_gid))
        self.statusBar().showMessage(tr("status.name_created").format(ids=new_gid))

    def _name_editor_assign_missing_selected(self):
        row_idx = self.name_missing_table.currentRow()
        if row_idx < 0:
            return
        it = self.name_missing_table.item(row_idx, 0)
        row = it.data(Qt.UserRole) if it is not None else None
        if not isinstance(row, dict):
            return
        name_text = self.name_missing_text_edit.text().strip()
        if not name_text:
            name_text = self._name_from_nickname_guess(str(row.get("nickname", "")))
            self.name_missing_text_edit.setText(name_text)
        if not name_text:
            return
        try:
            new_gid = self._ensure_ids_name_in_user_dll("0", name_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        ids_key = str(row.get("ids_key", "ids_name") or "ids_name").strip()
        ok = self._update_ids_in_file(
            str(row.get("path", "")),
            str(row.get("section", "object")).strip().lower(),
            str(row.get("nickname", "")),
            ids_key,
            str(new_gid),
        )
        if not ok:
            QMessageBox.warning(self, tr("msg.save_error"), tr("msg.no_changes"))
            return
        gp = self._primary_game_path()
        self._populate_name_editor_data(gp)
        self.name_search_edit.setText(str(new_gid))
        self.statusBar().showMessage(tr("status.missing_assigned").format(ids=new_gid))

    def _name_editor_collect_conflicts(self) -> list[dict]:
        by_gid: dict[int, list[dict]] = {}
        for row in self._name_editor_name_rows:
            gid = int(row.get("global_id", 0) or 0)
            if gid <= 0:
                continue
            by_gid.setdefault(gid, []).append(row)
        conflicts: list[dict] = []
        for gid in sorted(by_gid.keys()):
            rows = by_gid[gid]
            if len(rows) <= 1:
                continue
            txt = str(rows[0].get("text", "") or "").strip() or self._display_name_from_ids_name(gid)
            conflicts.append({"ids": gid, "text": txt, "rows": rows})
        return conflicts

    @staticmethod
    def _name_editor_conflict_report(conflicts: list[dict]) -> str:
        lines: list[str] = []
        for c in conflicts:
            gid = int(c.get("ids", 0) or 0)
            txt = str(c.get("text", "") or "").strip()
            rows = list(c.get("rows", []))
            title = f"[{gid}] {txt}" if txt else f"[{gid}]"
            lines.append(title)
            for r in rows:
                lines.append(
                    "  - {dll} | {text} | editable={editable}".format(
                        dll=str(r.get("dll", "")),
                        text=str(r.get("text", "")),
                        editable="yes" if bool(r.get("editable", False)) else "no",
                    )
                )
            lines.append("")
        return "\n".join(lines).strip()

    def _name_editor_check_conflicts(self):
        gp = self._primary_game_path()
        if not gp:
            self._warn_missing_game_path("msg.no_path")
            return
        self._populate_name_editor_data(gp)
        conflicts = self._name_editor_collect_conflicts()
        if not conflicts:
            QMessageBox.information(self, tr("name.conflict.none.title"), tr("name.conflict.none.text"))
            return

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("name.conflict.title"))
        dlg.resize(980, 620)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(8)
        summary = QLabel(
            tr("name.conflict.summary").format(
                count=len(conflicts),
                refs=sum(len(c.get("rows", [])) for c in conflicts),
            )
        )
        summary.setWordWrap(True)
        lay.addWidget(summary)
        details = QTextEdit()
        details.setReadOnly(True)
        details.setPlainText(self._name_editor_conflict_report(conflicts))
        lay.addWidget(details, 1)
        btn_row = QHBoxLayout()
        btn_row.setContentsMargins(0, 0, 0, 0)
        btn_row.setSpacing(6)
        fix_btn = QPushButton(tr("name.conflict.fix"))
        close_btn = QPushButton(tr("name.conflict.close"))
        btn_row.addWidget(fix_btn)
        btn_row.addStretch()
        btn_row.addWidget(close_btn)
        lay.addLayout(btn_row)
        close_btn.clicked.connect(dlg.reject)
        fix_btn.clicked.connect(lambda: self._name_editor_fix_conflicts(conflicts, dlg))
        dlg.exec()

    def _name_editor_fix_conflicts(self, conflicts: list[dict], dlg: QDialog | None = None):
        fixed = 0
        skipped = 0
        errors: list[str] = []
        for c in conflicts:
            gid = int(c.get("ids", 0) or 0)
            rows = list(c.get("rows", []))
            if len(rows) <= 1:
                continue
            for row in rows[1:]:
                if not bool(row.get("editable", False)):
                    skipped += 1
                    continue
                try:
                    base_text = str(row.get("text", "") or "").strip()
                    if not base_text:
                        base_text = f"IDS {gid}"
                    _new_gid = self._ensure_ids_name_in_user_dll("0", base_text)
                    ok = True
                except Exception as exc:
                    ok = False
                    if len(errors) < 20:
                        errors.append(f"{gid}: {exc}")
                if ok:
                    fixed += 1
                else:
                    skipped += 1
        gp = self._primary_game_path()
        if gp:
            self._populate_name_editor_data(gp)
        if dlg is not None:
            dlg.accept()
        msg = tr("name.conflict.fix.result").format(fixed=fixed, skipped=skipped)
        if errors:
            msg += "\n\n" + "\n".join(errors[:20])
        QMessageBox.information(self, tr("name.conflict.title"), msg)
        self.statusBar().showMessage(tr("status.name_conflicts_fixed").format(fixed=fixed, skipped=skipped))

    def _populate_trade_routes_data(self, game_path: str):
        payload = self._collect_trade_routes_payload(game_path)
        self._apply_trade_routes_payload(payload)

    def _clear_trade_routes_for_loading(self):
        self._trade_routes_render_token += 1
        self._trade_routes_rows = []
        self._trade_route_commodity_options = []
        self._trade_route_commodity_display_map = {}
        self._trade_route_commodity_base_prices = {}
        if hasattr(self, "trade_routes_table"):
            self.trade_routes_table.setRowCount(0)
        if hasattr(self, "trade_filter_commodity_cb"):
            self.trade_filter_commodity_cb.blockSignals(True)
            self.trade_filter_commodity_cb.clear()
            self.trade_filter_commodity_cb.addItem("All Commodities", "")
            self.trade_filter_commodity_cb.blockSignals(False)
        if hasattr(self, "trade_results_lbl"):
            self.trade_results_lbl.setText(tr("trade.results_count").format(count=0))
        if hasattr(self, "trade_connections_lbl"):
            self.trade_connections_lbl.setText(tr("trade.connections_count").format(count=0))
        if hasattr(self, "trade_route_scene"):
            self.trade_route_scene.clear()

    def _collect_trade_routes_payload(self, game_path: str) -> dict[str, object]:
        self._build_trade_route_nav_cache(game_path)
        self._reload_dll_name_cache()
        try:
            _commodity_nicks, commodity_base_prices = self._scan_commodity_nicknames(game_path)
        except Exception:
            commodity_base_prices = {}
        commodity_display_map = self._scan_commodity_display_names(game_path)
        rows, commodities = self._load_trade_routes_from_market(game_path)
        return build_trade_route_payload(
            commodity_base_prices=commodity_base_prices,
            commodity_display_map=commodity_display_map,
            rows=rows,
            commodities=commodities,
            fallback_display_name=self._commodity_fallback_display_name,
        )

    def _apply_trade_routes_payload(self, payload: dict[str, object]):
        self._trade_route_commodity_base_prices = dict(payload.get("commodity_base_prices", {}))
        self._trade_route_commodity_display_map = dict(payload.get("commodity_display_map", {}))
        self._trade_route_commodity_options = list(payload.get("commodities", []))
        self._trade_routes_rows = list(payload.get("rows", []))

        self.trade_filter_commodity_cb.blockSignals(True)
        self.trade_filter_commodity_cb.clear()
        self.trade_filter_commodity_cb.addItem("All Commodities", "")
        for text, nick in build_trade_route_commodity_items(
            self._trade_route_commodity_options,
            self._trade_route_commodity_display_map,
            self._commodity_fallback_display_name,
        ):
            self.trade_filter_commodity_cb.addItem(text, nick)
        self.trade_filter_commodity_cb.setCurrentIndex(0)
        self.trade_filter_commodity_cb.blockSignals(False)

        # Populate source/target system filter combos
        if hasattr(self, "trade_filter_source_system") and hasattr(self, "trade_filter_target_system"):
            system_items = build_trade_route_system_items(
                self._trade_route_base_index,
                self._system_display_name,
            )
            for combo in (self.trade_filter_source_system, self.trade_filter_target_system):
                combo.blockSignals(True)
                combo.clear()
                combo.addItem("")
                for text, sys_nick in system_items:
                    combo.addItem(text, sys_nick)
                combo.setCurrentIndex(0)
                combo.blockSignals(False)

        self._apply_trade_route_filters()
        self.statusBar().showMessage(tr("status.trade_view_opened"))

    def _load_trade_routes_from_market(self, game_path: str) -> tuple[list[dict], list[str]]:
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.is_file():
            return [], []

        try:
            sections = self._parser.parse(str(market_file))
        except Exception:
            return [], []

        _commodity_nicks, commodity_base_prices = self._scan_commodity_nicknames(game_path)

        display_map = getattr(self, "_trade_route_commodity_display_map", {})
        rows, commodities = build_trade_route_rows_from_market_sections(
            sections,
            base_index=self._trade_route_base_index,
            commodity_base_prices=commodity_base_prices,
            commodity_display_map=display_map,
        )
        return rows, commodities

    def _build_trade_route_nav_cache(self, game_path: str):
        self._trade_route_base_index = {}
        self._trade_route_system_cache = {}
        self._trade_route_universe_pos = {}
        self._trade_route_adjacency = {}
        base_names_from_universe: dict[str, str] = {}
        uni_ini = self._find_universe_ini_read(game_path)
        if uni_ini and uni_ini.is_file():
            try:
                uni_sections = self._parser.parse(str(uni_ini))
            except Exception:
                uni_sections = []
            for sec_name, entries in uni_sections:
                if sec_name.lower() != "base":
                    continue
                base_nick = self._entry_get_value(entries, "nickname").strip()
                if not base_nick:
                    continue
                ids_name_raw = self._entry_get_value(entries, "strid_name").strip() or self._entry_get_value(entries, "ids_name").strip()
                disp = self._base_display_name(base_nick, ids_name_raw)
                base_names_from_universe[base_nick.lower()] = disp or base_nick
        try:
            systems = self._find_all_systems(game_path)
        except Exception:
            systems = []
        for s in systems:
            sys_nick = str(s.get("nickname", "")).upper()
            if not sys_nick:
                continue
            self._trade_route_universe_pos[sys_nick] = tuple(s.get("pos", (0.0, 0.0)))
            try:
                secs = self._parser.parse(s["path"])
                objs = self._parser.get_objects(secs)
                zones = self._parser.get_zones(secs)
            except Exception:
                objs = []
                zones = []
            draw_objs: list[dict] = []
            env_zones: list[dict] = []
            bases: dict[str, tuple[float, float]] = {}
            jump_links: dict[str, list[dict]] = {}
            tl_map: dict[str, dict] = {}
            tl_edges: list[tuple[tuple[float, float], tuple[float, float]]] = []
            dock_with_targets = {
                str(o.get("dock_with", "")).strip().lower()
                for o in objs
                if str(o.get("dock_with", "")).strip()
            }
            for o in objs:
                x, _y, z = parse_position(o.get("pos", "0,0,0"))
                arch = str(o.get("archetype", "")).lower()
                nickname = str(o.get("nickname", ""))
                label_text = nickname
                obj_base = str(o.get("base", "")).strip()
                obj_dock_with = str(o.get("dock_with", "")).strip()
                bn = obj_base or obj_dock_with
                is_disabled_miner_base = bool(bn and bn.lower().endswith("_miner"))
                is_dockable_base = bool(
                    not is_disabled_miner_base
                    and (
                        obj_dock_with
                        or (
                            obj_base
                            and ("planet" not in arch or obj_base.strip().lower() in dock_with_targets)
                        )
                    )
                )
                if bn and is_dockable_base:
                    ids_name_raw = str(o.get("ids_name", "") or "").strip()
                    display_name = base_names_from_universe.get(bn.lower())
                    if not display_name:
                        display_name = self._base_display_name(bn, ids_name_raw)
                    if display_name and display_name.lower() != bn.lower():
                        label_text = f"{display_name} - {bn}"
                    else:
                        label_text = bn or nickname
                jump_kind = classify_jump_connection_kind(
                    archetype=arch,
                    msg_id_prefix=o.get("msg_id_prefix", ""),
                    reputation=o.get("reputation", ""),
                    jump_effect=o.get("jump_effect", ""),
                    goto_value=o.get("goto", ""),
                )
                draw_objs.append(
                    {"nickname": nickname, "label": label_text, "archetype": arch, "pos": (x, z)}
                )
                if bn and is_dockable_base:
                    bases[bn.lower()] = (x, z)
                    self._trade_route_base_index[bn.lower()] = {
                        "base_nick": bn,
                        "display_name": display_name,
                        "system": sys_nick,
                        "pos": (x, z),
                    }
                if "trade_lane_ring" in arch or "tradelane_ring" in arch:
                    tl_map[nickname.strip().lower()] = o
                if jump_kind in ("gate", "hole"):
                    dest = ""
                    goto = str(o.get("goto", "")).strip()
                    if goto:
                        dest = goto.split(",")[0].strip().upper()
                    if not dest:
                        m = re.search(r"to_([A-Za-z0-9]+)", nickname, re.IGNORECASE)
                        if m:
                            dest = m.group(1).upper()
                    if dest:
                        jump_links.setdefault(dest, []).append(
                            {
                                "nickname": nickname,
                                "pos": (x, z),
                                "archetype": arch,
                            }
                        )
            for nick_l, o in tl_map.items():
                x, _y, z = parse_position(o.get("pos", "0,0,0"))
                nxt = str(o.get("next_ring", "")).strip().lower()
                if nxt and nxt in tl_map:
                    nx, _ny, nz = parse_position(tl_map[nxt].get("pos", "0,0,0"))
                    tl_edges.append(((x, z), (nx, nz)))

            for z in zones:
                nickname = str(z.get("nickname", "")).strip()
                nl = nickname.lower()
                if not any(k in nl for k in ("nebula", "badlands", "asteroid", "debris", "field")):
                    continue
                shape = str(z.get("shape", "SPHERE")).upper()
                px, _py, pz = parse_position(z.get("pos", "0,0,0"))
                sx, sy, sz = self._parse_vec3(z.get("size", "1000,1000,1000"), (1000.0, 1000.0, 1000.0))
                _rx, ry, _rz = self._parse_vec3(z.get("rotate", "0,0,0"))
                env_zones.append(
                    {
                        "nickname": nickname,
                        "shape": shape,
                        "pos": (px, pz),
                        "size": (sx, sy, sz),
                        "rotate_y": ry,
                    }
                )

            self._trade_route_system_cache[sys_nick] = {
                "objects": draw_objs,
                "env_zones": env_zones,
                "bases": bases,
                "jump_links": jump_links,
                "lane_edges": tl_edges,
            }
        edges = self._compute_universe_edges(systems) if systems else {}
        for key in edges.keys():
            pair = list(key)
            if len(pair) != 2:
                continue
            a = str(pair[0]).upper()
            b = str(pair[1]).upper()
            self._trade_route_adjacency.setdefault(a, set()).add(b)
            self._trade_route_adjacency.setdefault(b, set()).add(a)

    def _load_custom_trade_routes(self) -> list[dict]:
        return load_custom_trade_routes(self._cfg)

    def _save_custom_trade_routes(self, rows: list[dict]):
        save_custom_trade_routes(self._cfg, rows)

    def _trade_route_base_price(self, commodity_nick: str, game_path: str) -> int:
        key = str(commodity_nick or "").strip().lower()
        if not key:
            return 0
        price_map = getattr(self, "_trade_route_commodity_base_prices", {})
        if key in price_map:
            try:
                return int(price_map[key])
            except Exception:
                return 0
        try:
            _nicks, base_prices = self._scan_commodity_nicknames(game_path)
        except Exception:
            return 0
        for nick, val in base_prices.items():
            nk = str(nick).strip().lower()
            if not nk:
                continue
            try:
                price_map[nk] = int(val)
            except Exception:
                continue
        self._trade_route_commodity_base_prices = price_map
        try:
            return int(price_map.get(key, 0))
        except Exception:
            return 0

    @staticmethod
    def _trade_route_format_multiplier(multiplier: float) -> str:
        return trade_route_format_multiplier(multiplier)

    def _trade_route_upsert_marketgood(
        self,
        game_path: str,
        base_nick: str,
        commodity_nick: str,
        price: float,
        relation_flag: int,
    ) -> tuple[bool, str]:
        base = str(base_nick or "").strip()
        commodity = str(commodity_nick or "").strip()
        if not base or not commodity:
            return False, "Ungueltige Base/Commodity."
        if float(price) <= 0.0:
            return False, "Preis muss groesser als 0 sein."

        market_file = self._target_game_path_for_rel(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if market_file is None:
            return False, "market_commodities.ini konnte nicht aufgeloest werden."
        market_file = self._ensure_writable_path(market_file)
        if not market_file.exists():
            try:
                market_file.parent.mkdir(parents=True, exist_ok=True)
                market_file.write_text("", encoding="utf-8")
            except Exception as exc:
                return False, f"market_commodities.ini konnte nicht erstellt werden: {exc}"

        base_price = self._trade_route_base_price(commodity, game_path)
        if base_price <= 0:
            return False, f"Kein Grundpreis fuer Commodity gefunden: {commodity}"
        multiplier = float(price) / float(base_price)
        if multiplier <= 0.0:
            return False, f"Ungueltiger Multiplikator fuer {commodity}"
        mult_txt = self._trade_route_format_multiplier(multiplier)

        try:
            sections = self._parser.parse(str(market_file))
        except Exception as exc:
            return False, f"market_commodities.ini konnte nicht gelesen werden: {exc}"

        sections = trade_route_upsert_marketgood_section(
            sections,
            base=base,
            commodity=commodity,
            relation_flag=relation_flag,
            multiplier_text=mult_txt,
        )
        try:
            write_text_atomic(market_file, serialize_ini_sections(sections))
        except Exception as exc:
            return False, f"market_commodities.ini konnte nicht gespeichert werden: {exc}"

        return True, str(market_file)

    def _trade_route_persist_to_market(self, route: dict) -> tuple[bool, str]:
        game_path = self._primary_game_path()
        if not game_path:
            return False, self._missing_game_path_message()
        commodity = str(route.get("commodity", "")).strip()
        buy_loc = str(route.get("buy_loc", "")).strip().lower()
        sell_loc = str(route.get("sell_loc", "")).strip().lower()
        buy_price = float(route.get("buy_price", 0.0) or 0.0)
        sell_price = float(route.get("sell_price", 0.0) or 0.0)
        if not commodity or not buy_loc or not sell_loc:
            return False, "Route ist unvollstaendig (Commodity/Buy/Sell)."
        ok_buy, msg_buy = self._trade_route_upsert_marketgood(
            game_path=game_path,
            base_nick=buy_loc,
            commodity_nick=commodity,
            price=buy_price,
            relation_flag=0,
        )
        if not ok_buy:
            return False, msg_buy
        ok_sell, msg_sell = self._trade_route_upsert_marketgood(
            game_path=game_path,
            base_nick=sell_loc,
            commodity_nick=commodity,
            price=sell_price,
            relation_flag=1,
        )
        if not ok_sell:
            return False, msg_sell
        return True, msg_sell

    def _trade_route_remove_marketgood(
        self,
        game_path: str,
        base_nick: str,
        commodity_nick: str,
    ) -> tuple[bool, str]:
        base = str(base_nick or "").strip().lower()
        commodity = str(commodity_nick or "").strip().lower()
        if not base or not commodity:
            return False, "Ungueltige Base/Commodity."
        market_file = self._target_game_path_for_rel(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if market_file is None:
            return False, "market_commodities.ini konnte nicht aufgeloest werden."
        market_file = self._ensure_writable_path(market_file)
        if not market_file.exists():
            return False, "market_commodities.ini nicht gefunden."
        try:
            sections = self._parser.parse(str(market_file))
        except Exception as exc:
            return False, f"market_commodities.ini konnte nicht gelesen werden: {exc}"

        sections, changed = trade_route_remove_marketgood_section(
            sections,
            base=base,
            commodity=commodity,
        )
        if not changed:
            return False, "Kein passender MarketGood-Eintrag gefunden."
        try:
            write_text_atomic(market_file, serialize_ini_sections(sections))
        except Exception as exc:
            return False, f"market_commodities.ini konnte nicht gespeichert werden: {exc}"
        return True, str(market_file)

    def _trade_route_make_name(self, commodity: str, commodity_label: str, buy_loc: str, sell_loc: str) -> str:
        c = str(commodity_label or "").strip() or str(commodity or "").strip() or "Commodity"
        b = str(buy_loc or "").strip().lower() or "buy"
        s = str(sell_loc or "").strip().lower() or "sell"
        return f"{c}: {b} -> {s}"

    def _trade_route_sell_base_buys_commodity(self, game_path: str, sell_base: str, commodity: str) -> bool:
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.is_file():
            return False
        sell_low = str(sell_base or "").strip().lower()
        comm_low = str(commodity or "").strip().lower()
        if not sell_low or not comm_low:
            return False
        try:
            sections = self._parser.parse(str(market_file))
        except Exception:
            return False
        for sec_name, entries in sections:
            if sec_name.lower() != "basegood":
                continue
            base_nick = ""
            for k, v in entries:
                if k.lower() == "base":
                    base_nick = str(v).strip().lower()
                    break
            if base_nick != sell_low:
                continue
            for k, v in entries:
                if k.lower() != "marketgood":
                    continue
                fields = [f.strip() for f in str(v).split(",")]
                if len(fields) < 7:
                    continue
                if str(fields[0]).strip().lower() != comm_low:
                    continue
                try:
                    relation_flag = int(float(fields[5]))
                    multiplier = float(fields[6])
                except Exception:
                    continue
                if relation_flag == 1 and multiplier > 0.0:
                    return True
        return False

    def _trade_route_validate_creation(self, route: dict) -> tuple[bool, str]:
        commodity = str(route.get("commodity", "")).strip().lower()
        buy_loc = str(route.get("buy_loc", "")).strip().lower()
        sell_loc = str(route.get("sell_loc", "")).strip().lower()
        if not commodity or not buy_loc or not sell_loc:
            return False, "Route ist unvollständig (Commodity/Buy/Sell)."

        for r in self._trade_routes_rows:
            if (
                str(r.get("commodity", "")).strip().lower() == commodity
                and str(r.get("buy_loc", "")).strip().lower() == buy_loc
                and str(r.get("sell_loc", "")).strip().lower() == sell_loc
            ):
                return False, "Diese Verbindung existiert bereits."

        game_path = self._primary_game_path()
        if game_path and self._trade_route_sell_base_buys_commodity(game_path, sell_loc, commodity):
            return False, "Die Sell-Base kauft dieses Commodity bereits (Konflikt)."

        return True, ""

    def _trade_route_system_path(self, src: str, dst: str) -> list[str]:
        return system_path_bfs(self._trade_route_adjacency, src, dst)

    @staticmethod
    def _distance2d(a: tuple[float, float], b: tuple[float, float]) -> float:
        return math.hypot(float(a[0]) - float(b[0]), float(a[1]) - float(b[1]))

    def _trade_route_pick_jump_point(
        self,
        system_nick: str,
        target_system_nick: str,
        anchor: tuple[float, float] | None = None,
    ) -> tuple[float, float] | None:
        sys_u = str(system_nick).upper()
        dst_u = str(target_system_nick).upper()
        info = self._trade_route_system_cache.get(sys_u, {})
        cands = list(info.get("jump_links", {}).get(dst_u, []))
        if not cands:
            return None
        if anchor is None:
            return tuple(cands[0].get("pos", (0.0, 0.0)))
        best = None
        best_d = None
        for c in cands:
            p = tuple(c.get("pos", (0.0, 0.0)))
            d = self._distance2d(p, anchor)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best

    def _trade_route_local_path(
        self,
        sys_info: dict,
        start_pt: tuple[float, float],
        end_pt: tuple[float, float],
    ) -> list[tuple[float, float]]:
        lane_edges = list(sys_info.get("lane_edges", []))
        nodes: list[tuple[float, float]] = [start_pt, end_pt]
        node_idx: dict[tuple[int, int], int] = {}

        def _add_node(pt: tuple[float, float]) -> int:
            key = (int(round(pt[0] * 10)), int(round(pt[1] * 10)))
            if key in node_idx:
                return node_idx[key]
            node_idx[key] = len(nodes)
            nodes.append(pt)
            return node_idx[key]

        for a, b in lane_edges:
            _add_node(a)
            _add_node(b)

        n = len(nodes)
        adj: list[list[tuple[int, float]]] = [[] for _ in range(n)]

        def _link(i: int, j: int, w: float):
            adj[i].append((j, w))
            adj[j].append((i, w))

        _link(0, 1, self._distance2d(nodes[0], nodes[1]))
        for i in range(2, n):
            _link(0, i, self._distance2d(nodes[0], nodes[i]))
            _link(1, i, self._distance2d(nodes[1], nodes[i]))

        for a, b in lane_edges:
            ia = _add_node(a)
            ib = _add_node(b)
            _link(ia, ib, self._distance2d(a, b) * 0.35)

        dist = [float("inf")] * len(nodes)
        prev = [-1] * len(nodes)
        used = [False] * len(nodes)
        dist[0] = 0.0
        for _ in range(len(nodes)):
            u = -1
            best = float("inf")
            for i in range(len(nodes)):
                if not used[i] and dist[i] < best:
                    best = dist[i]
                    u = i
            if u < 0:
                break
            if u == 1:
                break
            used[u] = True
            for v, w in adj[u]:
                nd = dist[u] + w
                if nd < dist[v]:
                    dist[v] = nd
                    prev[v] = u
        if prev[1] < 0:
            return [start_pt, end_pt]
        path = [1]
        cur = 1
        while cur != 0 and cur >= 0:
            cur = prev[cur]
            if cur >= 0:
                path.append(cur)
        path.reverse()
        return [nodes[i] for i in path]

    def _apply_trade_route_filters(self):
        if not hasattr(self, "trade_routes_table"):
            return
        rows = list(self._trade_routes_rows)
        commodity_filter = str(self.trade_filter_commodity_cb.currentData() or "").strip().lower()
        if not commodity_filter:
            commodity_filter = self.trade_filter_commodity_cb.currentText().strip().lower()
        min_profit = float(self.trade_filter_min_profit.value())
        min_profit_per_jump = float(self.trade_filter_min_profit_per_jump.value()) if hasattr(self, "trade_filter_min_profit_per_jump") else 0.0
        same_system_only = self.trade_filter_same_system_cb.isChecked()
        search = self.trade_filter_search.text().strip().lower()

        max_jumps_val = self.trade_filter_max_jumps.value() if hasattr(self, "trade_filter_max_jumps") else 0
        max_jumps = max_jumps_val if max_jumps_val > 0 else None
        source_system = ""
        if hasattr(self, "trade_filter_source_system"):
            source_system = self.trade_filter_source_system.currentText().strip()
        target_system = ""
        if hasattr(self, "trade_filter_target_system"):
            target_system = self.trade_filter_target_system.currentText().strip()
        cargo_capacity = 1
        if hasattr(self, "trade_filter_cargo_capacity"):
            cargo_capacity = max(1, int(self.trade_filter_cargo_capacity.value()))

        enriched_routes = filter_routes(
            rows,
            base_index=self._trade_route_base_index,
            adjacency=self._trade_route_adjacency,
            commodity_display_map=self._trade_route_commodity_display_map,
            system_display_fn=self._system_display_name,
            commodity_filter=commodity_filter,
            min_profit=min_profit,
            same_system_only=same_system_only,
            search_text=search,
            max_jumps=max_jumps,
            source_system=source_system,
            target_system=target_system,
            cargo_capacity=cargo_capacity,
            min_profit_per_jump=min_profit_per_jump,
        )
        self._trade_route_filtered_cache = enriched_routes
        filtered = [r.to_dict() for r in enriched_routes]
        connection_count = len(
            {
                (
                    str(route.get("buy_loc", "")).strip().lower(),
                    str(route.get("sell_loc", "")).strip().lower(),
                )
                for route in filtered
                if str(route.get("buy_loc", "")).strip() and str(route.get("sell_loc", "")).strip()
            }
        )

        tbl = self.trade_routes_table
        self._trade_routes_render_token += 1
        token = self._trade_routes_render_token
        self.trade_results_lbl.setText(tr("trade.results_count").format(count=len(filtered)))
        if hasattr(self, "trade_connections_lbl"):
            self.trade_connections_lbl.setText(tr("trade.connections_count").format(count=connection_count))

        def _build_row(table: QTableWidget, row_index: int, row: dict):
            item_commodity = QTableWidgetItem(str(row.get("commodity_label", row["commodity"])))
            item_commodity.setData(Qt.UserRole, row)
            table.setItem(row_index, 0, item_commodity)
            table.setItem(row_index, 1, QTableWidgetItem(str(row.get("buy_label", row["buy_loc"]))))
            table.setItem(row_index, 2, _NumericTableWidgetItem(row["buy_price"], decimals=0))
            table.setItem(row_index, 3, QTableWidgetItem(str(row.get("sell_label", row["sell_loc"]))))
            table.setItem(row_index, 4, _NumericTableWidgetItem(row["sell_price"], decimals=0))
            table.setItem(row_index, 5, QTableWidgetItem(str(row.get("buy_system_label", row.get("buy_system", "")))))
            table.setItem(row_index, 6, QTableWidgetItem(str(row.get("sell_system_label", row.get("sell_system", "")))))
            table.setItem(row_index, 7, QTableWidgetItem(str(row.get("route_type", ""))))
            table.setItem(row_index, 8, _NumericTableWidgetItem(row["profit"], decimals=0))
            table.setItem(row_index, 9, _NumericTableWidgetItem(row["jumps"], decimals=0))
            table.setItem(row_index, 10, _NumericTableWidgetItem(row.get("profit_per_jump", 0), decimals=0))
            table.setItem(row_index, 11, _NumericTableWidgetItem(row.get("net_profit", 0), decimals=0))
            table.setItem(row_index, 12, _NumericTableWidgetItem(row["score"], decimals=0))

        self._render_table_rows_batched(
            tbl,
            filtered,
            token_attr="_trade_routes_render_token",
            token_value=token,
            row_builder=_build_row,
            select_first=True,
            empty_callback=self.trade_route_scene.clear,
        )

    def _on_trade_route_selection_changed(self):
        row_idx = self.trade_routes_table.currentRow()
        if row_idx < 0:
            self.trade_route_scene.clear()
            return
        first_item = self.trade_routes_table.item(row_idx, 0)
        row = first_item.data(Qt.UserRole) if first_item is not None else None
        if not isinstance(row, dict):
            self.trade_route_scene.clear()
            return
        self._trade_route_render_to_scene(row, self.trade_route_scene)

    def _trade_route_selected_row(self) -> dict | None:
        row_idx = self.trade_routes_table.currentRow()
        if row_idx < 0:
            return None
        first_item = self.trade_routes_table.item(row_idx, 0)
        row = first_item.data(Qt.UserRole) if first_item is not None else None
        if not isinstance(row, dict):
            return None
        return row

    def _trade_route_open_dialog(self, existing: dict | None = None) -> dict | None:
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("trade.dlg.edit") if existing else tr("trade.dlg.create"))
        fl = QFormLayout(dlg)
        is_edit = existing is not None
        commodity_cb = QComboBox()
        commodity_cb.setEditable(True)
        for nick in getattr(self, "_trade_route_commodity_options", [])[:400]:
            lbl = self._trade_route_commodity_display_map.get(
                str(nick).lower(),
                self._commodity_fallback_display_name(str(nick)),
            )
            text = f"{lbl} ({nick})" if str(lbl).lower() != str(nick).lower() else str(lbl)
            commodity_cb.addItem(text, nick)
        if existing:
            ex_commodity = str(existing.get("commodity", "")).strip()
            ci = commodity_cb.findData(ex_commodity)
            if ci >= 0:
                commodity_cb.setCurrentIndex(ci)
            else:
                commodity_cb.setCurrentText(ex_commodity)
        buy_cb = QComboBox()
        buy_cb.setEditable(True)
        sell_cb = QComboBox()
        sell_cb.setEditable(True)
        base_list = sorted(self._trade_route_base_index.keys())
        for b in base_list:
            info = self._trade_route_base_index.get(b, {})
            disp = str(info.get("display_name", b))
            text = f"{b} - {disp}" if disp.lower() != str(b).lower() else b
            buy_cb.addItem(text, b)
            sell_cb.addItem(text, b)
        buy_loc_existing = ""
        sell_loc_existing = ""
        if existing:
            buy_key = str(existing.get("buy_loc", "")).strip().lower()
            sell_key = str(existing.get("sell_loc", "")).strip().lower()
            buy_loc_existing = buy_key
            sell_loc_existing = sell_key
            bi = buy_cb.findData(buy_key)
            si = sell_cb.findData(sell_key)
            if bi >= 0:
                buy_cb.setCurrentIndex(bi)
            else:
                buy_cb.setCurrentText(buy_key)
            if si >= 0:
                sell_cb.setCurrentIndex(si)
            else:
                sell_cb.setCurrentText(sell_key)
        buy_price = QDoubleSpinBox()
        buy_price.setRange(0.0, 1_000_000.0)
        buy_price.setDecimals(2)
        buy_price.setValue(float(existing.get("buy_price", 0.0)) if existing else 0.0)
        sell_price = QDoubleSpinBox()
        sell_price.setRange(0.0, 1_000_000.0)
        sell_price.setDecimals(2)
        sell_price.setValue(float(existing.get("sell_price", 0.0)) if existing else 0.0)
        enabled_cb = QCheckBox()
        enabled_cb.setChecked(bool(existing.get("enabled", True)) if existing else True)
        base_price_lbl = QLabel("-")

        def _update_base_price_label(_commodity_text: str):
            key = str(commodity_cb.currentData() or commodity_cb.currentText() or "").strip().lower()
            price_map = getattr(self, "_trade_route_commodity_base_prices", {})
            price = price_map.get(key)
            if price is None:
                base_price_lbl.setText("-")
            else:
                base_price_lbl.setText(f"{int(price):,} cr")

        fl.addRow(tr("trade.field.commodity"), commodity_cb)
        fl.addRow(tr("trade.field.base_price"), base_price_lbl)
        if is_edit:
            buy_info = self._trade_route_base_index.get(buy_loc_existing, {})
            sell_info = self._trade_route_base_index.get(sell_loc_existing, {})
            buy_disp = str(buy_info.get("display_name", buy_loc_existing))
            sell_disp = str(sell_info.get("display_name", sell_loc_existing))
            buy_text = f"{buy_loc_existing} - {buy_disp}" if buy_disp.lower() != buy_loc_existing.lower() else buy_loc_existing
            sell_text = f"{sell_loc_existing} - {sell_disp}" if sell_disp.lower() != sell_loc_existing.lower() else sell_loc_existing
            fl.addRow(tr("trade.field.buy_base"), QLabel(buy_text))
            fl.addRow(tr("trade.field.sell_base"), QLabel(sell_text))
        else:
            fl.addRow(tr("trade.field.buy_base"), buy_cb)
            fl.addRow(tr("trade.field.sell_base"), sell_cb)
        fl.addRow(tr("trade.field.buy_price"), buy_price)
        fl.addRow(tr("trade.field.sell_price"), sell_price)
        fl.addRow(tr("trade.field.enabled"), enabled_cb)
        commodity_cb.currentTextChanged.connect(_update_base_price_label)
        _update_base_price_label(commodity_cb.currentText())

        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        fl.addRow(bb)
        if dlg.exec() != QDialog.Accepted:
            return None
        commodity = str(commodity_cb.currentData() or commodity_cb.currentText()).strip()
        commodity_label = self._trade_route_commodity_display_map.get(
            commodity.lower(),
            str(commodity_cb.currentText()).strip(),
        )
        if is_edit:
            buy_loc = buy_loc_existing
            sell_loc = sell_loc_existing
        else:
            buy_loc = str(buy_cb.currentData() or buy_cb.currentText()).strip().lower()
            sell_loc = str(sell_cb.currentData() or sell_cb.currentText()).strip().lower()
        out = {
            "name": self._trade_route_make_name(commodity, commodity_label, buy_loc, sell_loc),
            "commodity": commodity,
            "commodity_label": commodity_label,
            "buy_loc": buy_loc,
            "sell_loc": sell_loc,
            "buy_price": float(buy_price.value()),
            "sell_price": float(sell_price.value()),
            "enabled": bool(enabled_cb.isChecked()),
        }
        return out

    def _trade_route_create(self):
        route = self._trade_route_open_dialog()
        if route is None:
            return
        valid, reason = self._trade_route_validate_creation(route)
        if not valid:
            QMessageBox.warning(self, tr("trade.msg.title"), reason)
            return
        ok, msg = self._trade_route_persist_to_market(route)
        if not ok:
            QMessageBox.warning(self, tr("trade.msg.title"), msg)
            return
        self._trade_routes_rows.append(route)
        self._save_custom_trade_routes(self._trade_routes_rows)
        self.statusBar().showMessage(f"market_commodities.ini aktualisiert: {msg}")
        self._apply_trade_route_filters()

    def _trade_route_edit_selected(self):
        row = self._trade_route_selected_row()
        if row is None:
            return
        route = self._trade_route_open_dialog(row)
        if route is None:
            return
        ok, msg = self._trade_route_persist_to_market(route)
        if not ok:
            QMessageBox.warning(self, tr("trade.msg.title"), msg)
            return
        target_commodity = str(row.get("commodity", "")).strip().lower()
        target_buy = str(row.get("buy_loc", "")).strip().lower()
        target_sell = str(row.get("sell_loc", "")).strip().lower()
        replaced = False
        for i, r in enumerate(self._trade_routes_rows):
            if (
                str(r.get("commodity", "")).strip().lower() == target_commodity
                and str(r.get("buy_loc", "")).strip().lower() == target_buy
                and str(r.get("sell_loc", "")).strip().lower() == target_sell
            ):
                self._trade_routes_rows[i] = route
                replaced = True
                break
        if not replaced:
            self._trade_routes_rows.append(route)
        self._save_custom_trade_routes(self._trade_routes_rows)
        self.statusBar().showMessage(f"market_commodities.ini aktualisiert: {msg}")
        self._apply_trade_route_filters()

    def _trade_route_delete_selected(self):
        row = self._trade_route_selected_row()
        if row is None:
            return
        if QMessageBox.question(
            self,
            tr("trade.msg.title"),
            tr("trade.msg.delete_confirm").format(name=row.get("name", "")),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        ) != QMessageBox.Yes:
            return
        game_path = self._primary_game_path()
        commodity = str(row.get("commodity", "")).strip()
        buy_loc = str(row.get("buy_loc", "")).strip().lower()
        sell_loc = str(row.get("sell_loc", "")).strip().lower()
        removed_targets: list[str] = []
        remove_errors: list[str] = []
        if game_path and commodity and buy_loc:
            ok_buy, msg_buy = self._trade_route_remove_marketgood(game_path, buy_loc, commodity)
            if ok_buy:
                removed_targets.append(f"{buy_loc}:{commodity}")
            else:
                remove_errors.append(f"{buy_loc}:{commodity} -> {msg_buy}")
        if game_path and commodity and sell_loc and sell_loc != buy_loc:
            ok_sell, msg_sell = self._trade_route_remove_marketgood(game_path, sell_loc, commodity)
            if ok_sell:
                removed_targets.append(f"{sell_loc}:{commodity}")
            else:
                remove_errors.append(f"{sell_loc}:{commodity} -> {msg_sell}")
        target_commodity = str(row.get("commodity", "")).strip().lower()
        target_buy = str(row.get("buy_loc", "")).strip().lower()
        target_sell = str(row.get("sell_loc", "")).strip().lower()
        kept: list[dict] = []
        removed = False
        for r in self._trade_routes_rows:
            is_target = (
                str(r.get("commodity", "")).strip().lower() == target_commodity
                and str(r.get("buy_loc", "")).strip().lower() == target_buy
                and str(r.get("sell_loc", "")).strip().lower() == target_sell
                and not removed
            )
            if is_target:
                removed = True
                continue
            kept.append(r)
        self._trade_routes_rows = kept
        self._save_custom_trade_routes(self._trade_routes_rows)
        self._apply_trade_route_filters()
        if removed_targets:
            self.statusBar().showMessage(f"MarketGood entfernt: {', '.join(removed_targets)}")
        elif remove_errors:
            self.statusBar().showMessage(f"Route geloescht, MarketGood nicht entfernt: {remove_errors[0]}")

    def _on_trade_routes_context_menu(self, pos):
        from PySide6.QtWidgets import QMenu

        menu = QMenu(self)
        act_new = menu.addAction(tr("trade.btn.create"))
        act_new.triggered.connect(self._trade_route_create)
        sel = self._trade_route_selected_row()
        if sel is not None:
            act_edit = menu.addAction(tr("trade.btn.edit"))
            act_edit.triggered.connect(self._trade_route_edit_selected)
            act_del = menu.addAction(tr("trade.btn.delete"))
            act_del.triggered.connect(self._trade_route_delete_selected)
            menu.addSeparator()
            act_vis = menu.addAction(tr("trade.btn.visualize"))
            act_vis.triggered.connect(self._trade_route_visualize_selected)
            menu.addSeparator()
            act_buy_sys = menu.addAction(tr("trade.btn.open_buy_system"))
            act_buy_sys.triggered.connect(lambda: self._trade_route_jump_to_system(sel, "buy"))
            act_sell_sys = menu.addAction(tr("trade.btn.open_sell_system"))
            act_sell_sys.triggered.connect(lambda: self._trade_route_jump_to_system(sel, "sell"))
            act_buy_base = menu.addAction(tr("trade.btn.open_buy_base"))
            act_buy_base.triggered.connect(lambda: self._trade_route_jump_to_base(sel, "buy"))
            act_sell_base = menu.addAction(tr("trade.btn.open_sell_base"))
            act_sell_base.triggered.connect(lambda: self._trade_route_jump_to_base(sel, "sell"))
            act_buy_market = menu.addAction(tr("trade.btn.open_buy_market_section"))
            act_buy_market.triggered.connect(lambda: self._trade_route_open_market_section(sel, "buy"))
            act_sell_market = menu.addAction(tr("trade.btn.open_sell_market_section"))
            act_sell_market.triggered.connect(lambda: self._trade_route_open_market_section(sel, "sell"))
            act_ini = menu.addAction(tr("trade.btn.open_market_ini"))
            act_ini.triggered.connect(self._trade_route_open_market_ini)
            act_goods = menu.addAction(tr("trade.btn.open_goods_ini"))
            act_goods.triggered.connect(self._trade_route_open_goods_ini)
        menu.addSeparator()
        act_market = menu.addAction(tr("trade.btn.market_editor"))
        act_market.triggered.connect(self._open_market_editor)
        act_analysis = menu.addAction(tr("trade.btn.analysis"))
        act_analysis.triggered.connect(self._open_trade_route_analysis)
        act_csv = menu.addAction(tr("trade.btn.export_csv"))
        act_csv.triggered.connect(self._trade_route_export_csv)
        menu.exec(self.trade_routes_table.viewport().mapToGlobal(pos))

    def _open_market_editor(self):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("trade.msg.title"), self._missing_game_path_message())
            return
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.exists():
            QMessageBox.warning(self, tr("trade.msg.title"), tr("trade.market_editor.file_not_found"))
            return
        try:
            sections = self._parser.parse(str(market_file))
        except Exception as exc:
            QMessageBox.warning(self, tr("trade.msg.title"), str(exc))
            return

        updated, changed = open_market_editor_dialog(
            self,
            sections=sections,
            base_index=self._trade_route_base_index,
            commodity_base_prices=getattr(self, "_trade_route_commodity_base_prices", {}),
            commodity_display_map=getattr(self, "_trade_route_commodity_display_map", {}),
            tr=tr,
        )
        if changed and updated is not None:
            target = self._ensure_writable_path(market_file)
            try:
                write_text_atomic(target, serialize_ini_sections(updated))
                self.statusBar().showMessage(tr("trade.market_editor.saved"))
            except Exception as exc:
                QMessageBox.warning(self, tr("trade.msg.title"), str(exc))
                return
            self._populate_trade_routes_data(self._primary_game_path())

    def _open_trade_route_analysis(self):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("trade.msg.title"), self._missing_game_path_message())
            return
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.exists():
            QMessageBox.warning(self, tr("trade.msg.title"), tr("trade.market_editor.file_not_found"))
            return
        try:
            sections = self._parser.parse(str(market_file))
        except Exception as exc:
            QMessageBox.warning(self, tr("trade.msg.title"), str(exc))
            return

        selected = self._trade_route_selected_row()
        initial_commodity = ""
        if isinstance(selected, dict):
            initial_commodity = str(selected.get("commodity", "") or "").strip().lower()

        open_trade_route_analysis_dialog(
            self,
            sections=sections,
            base_index=self._trade_route_base_index,
            commodity_base_prices=getattr(self, "_trade_route_commodity_base_prices", {}),
            commodity_display_map=getattr(self, "_trade_route_commodity_display_map", {}),
            tr=tr,
            initial_commodity=initial_commodity,
        )

    def _trade_route_jump_to_system(self, row: dict, side: str):
        """Open the buy or sell system in the system editor."""
        system_nick = row.get("buy_system" if side == "buy" else "sell_system", "")
        if not system_nick:
            return
        game_path = self._primary_game_path()
        if not game_path:
            return
        dest_path = linked_system_path(self._find_all_systems(game_path), system_nick)
        if not dest_path:
            self.statusBar().showMessage(tr("trade.msg.system_not_found").format(system=system_nick))
            return
        self._open_system_tab(dest_path)

    def _trade_route_select_base_object(self, base_nick: str) -> bool:
        target = str(base_nick or "").strip().lower()
        if not target:
            return False

        primary_match = None
        secondary_match = None
        for obj in getattr(self, "_objects", []):
            if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                continue
            obj_base = str(obj.data.get("base", "") or "").strip().lower()
            obj_dock = str(obj.data.get("dock_with", "") or "").strip().lower()
            if obj_base == target:
                primary_match = obj
                break
            if secondary_match is None and obj_dock == target:
                secondary_match = obj

        selected = primary_match or secondary_match
        if selected is None:
            return False

        self._select(selected)
        try:
            self.view.centerOn(selected)
        except Exception:
            pass
        try:
            self._jump_view3d_to_item_preserving_camera(selected)
        except Exception:
            pass
        self.statusBar().showMessage(tr("status.centered").format(name=self._object_display_label(selected)))
        return True

    def _trade_route_jump_to_base(self, row: dict, side: str):
        """Open the buy or sell system and select the linked base object."""
        side_key = "buy" if side == "buy" else "sell"
        base_nick = str(row.get(f"{side_key}_loc", "") or "").strip().lower()
        if not base_nick:
            return
        info = self._trade_route_base_index.get(base_nick, {})
        system_nick = str(row.get(f"{side_key}_system", "") or info.get("system", "")).strip()
        if not system_nick:
            self.statusBar().showMessage(tr("trade.msg.base_not_found").format(base=base_nick))
            return
        game_path = self._primary_game_path()
        if not game_path:
            return
        dest_path = linked_system_path(self._find_all_systems(game_path), system_nick)
        if not dest_path:
            self.statusBar().showMessage(tr("trade.msg.system_not_found").format(system=system_nick))
            return
        self._open_system_tab(dest_path)
        if not self._trade_route_select_base_object(base_nick):
            self.statusBar().showMessage(tr("trade.msg.base_not_found").format(base=base_nick))

    def _trade_route_open_market_ini(self):
        """Open market_commodities.ini in the INI editor."""
        game_path = self._primary_game_path()
        if not game_path:
            return
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.exists():
            self.statusBar().showMessage(tr("trade.market_editor.file_not_found"))
            return
        self._ini_editor_open_file_in_tab(str(market_file))

    def _trade_route_open_market_section(self, row: dict, side: str):
        """Open market_commodities.ini and jump to the selected base section."""
        side_key = "buy" if side == "buy" else "sell"
        base_nick = str(row.get(f"{side_key}_loc", "") or "").strip().lower()
        if not base_nick:
            return
        game_path = self._primary_game_path()
        if not game_path:
            return
        market_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/market_commodities.ini")
        if not market_file or not market_file.exists():
            self.statusBar().showMessage(tr("trade.market_editor.file_not_found"))
            return
        self._ini_editor_open_file_in_tab(str(market_file))
        if not self._ini_editor_select_section_containing(f"base = {base_nick}"):
            self.statusBar().showMessage(tr("trade.market_editor.base_section_not_found").format(base=base_nick))

    def _trade_route_open_goods_ini(self):
        """Open goods.ini and jump to the selected commodity definition."""
        row = self._trade_route_selected_row()
        if row is None:
            return
        commodity = str(row.get("commodity", "") or "").strip().lower()
        if not commodity:
            return
        game_path = self._primary_game_path()
        if not game_path:
            return
        goods_file = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/goods.ini")
        if not goods_file or not goods_file.exists():
            self.statusBar().showMessage(tr("trade.goods.file_not_found"))
            return
        self._ini_editor_open_file_in_tab(str(goods_file))
        if not self._ini_editor_select_section_containing(f"nickname = {commodity}"):
            self.statusBar().showMessage(tr("trade.goods.section_not_found").format(commodity=commodity))

    def _trade_route_export_csv(self):
        """Export currently filtered trade routes to CSV."""
        from PySide6.QtWidgets import QFileDialog

        cached = getattr(self, "_trade_route_filtered_cache", None)
        if not cached:
            self.statusBar().showMessage(tr("trade.export.no_data"))
            return
        path, _ = QFileDialog.getSaveFileName(
            self, tr("trade.btn.export_csv"), "trade_routes.csv", "CSV (*.csv)",
        )
        if not path:
            return
        csv_text = export_routes_csv(cached)
        try:
            Path(path).write_text(csv_text, encoding="utf-8-sig")
            self.statusBar().showMessage(tr("trade.export.saved").format(path=path))
        except Exception as exc:
            QMessageBox.warning(self, tr("trade.msg.title"), str(exc))

    def _trade_route_visualize_selected(self):
        row = self._trade_route_selected_row()
        if row is None:
            return
        self._trade_route_render_to_scene(row, self.trade_route_scene)
        self.statusBar().showMessage(
            tr("status.trade_preview_updated").format(name=row.get("name", ""))
        )

    def _on_trade_preview_splitter_moved(self, _pos: int, _index: int):
        row = self._trade_route_selected_row()
        if row is None:
            return
        self._trade_route_render_to_scene(row, self.trade_route_scene)

    def _trade_route_render_to_scene(self, row: dict, scene: QGraphicsScene):
        buy = self._trade_route_base_index.get(str(row.get("buy_loc", "")).lower())
        sell = self._trade_route_base_index.get(str(row.get("sell_loc", "")).lower())
        if not buy or not sell:
            QMessageBox.warning(
                self,
                tr("trade.msg.title"),
                tr("trade.msg.invalid_base_pair"),
            )
            return
        src_sys = str(buy.get("system", "")).upper()
        dst_sys = str(sell.get("system", "")).upper()
        if not src_sys or not dst_sys:
            return
        path = self._trade_route_system_path(src_sys, dst_sys)
        if not path and src_sys != dst_sys:
            self.statusBar().showMessage(tr("trade.msg.route_unreachable").format(src=src_sys, dst=dst_sys))
            scene.clear()
            return
        scene.clear()

        def _draw_arrow_line(ax: float, ay: float, bx: float, by: float, pen: QPen):
            scene.addLine(ax, ay, bx, by, pen)
            ang = math.atan2(by - ay, bx - ax)
            head = 10.0
            spread = 0.45
            p1x = bx - head * math.cos(ang - spread)
            p1y = by - head * math.sin(ang - spread)
            p2x = bx - head * math.cos(ang + spread)
            p2y = by - head * math.sin(ang + spread)
            scene.addLine(bx, by, p1x, p1y, pen)
            scene.addLine(bx, by, p2x, p2y, pen)

        def _to_scene_point(
            pt: tuple[float, float],
            min_x: float,
            max_x: float,
            min_z: float,
            max_z: float,
            ox: float,
            oy: float,
            w: float,
            h: float,
        ) -> tuple[float, float]:
            dx = max(1e-6, max_x - min_x)
            dz = max(1e-6, max_z - min_z)
            scale = min(w / dx, h / dz)
            pad_x = (w - dx * scale) * 0.5
            pad_y = (h - dz * scale) * 0.5
            sx = ox + pad_x + (pt[0] - min_x) * scale
            sy = oy + pad_y + (pt[1] - min_z) * scale
            return sx, sy

        def _draw_system(
            sys_nick: str,
            left: float,
            top: float,
            width: float,
            height: float,
            start_pt: tuple[float, float] | None,
            end_pt: tuple[float, float] | None,
            highlight_jumps: list[tuple[float, float]] | None = None,
        ) -> dict:
            info = self._trade_route_system_cache.get(sys_nick, {})
            objs = list(info.get("objects", []))
            pts = [tuple(o.get("pos", (0.0, 0.0))) for o in objs]
            if not pts:
                pts = [(0.0, 0.0)]
            xs = [p[0] for p in pts]
            zs = [p[1] for p in pts]
            min_x, max_x = min(xs), max(xs)
            min_z, max_z = min(zs), max(zs)
            margin = 25.0
            view_x = left + margin
            view_y = top + margin
            view_w = width - 2 * margin
            view_h = height - 2 * margin
            view_x2 = view_x + view_w
            view_y2 = view_y + view_h
            world_dx = max(1e-6, max_x - min_x)
            world_dz = max(1e-6, max_z - min_z)
            world_scale = min(view_w / world_dx, view_h / world_dz)
            scene.addRect(left, top, width, height, QPen(self._scene_role_color("panel_border", 200)))
            lbl = scene.addText(sys_nick)
            lbl.setDefaultTextColor(self._theme_color("fg_accent"))
            lbl.setPos(left + 6, top + 4)

            for z in info.get("env_zones", []):
                zp = tuple(z.get("pos", (0.0, 0.0)))
                sx, sy = _to_scene_point(zp, min_x, max_x, min_z, max_z, view_x, view_y, view_w, view_h)
                shape = str(z.get("shape", "SPHERE")).upper()
                sz = z.get("size", (1000.0, 1000.0, 1000.0))
                s0 = float(sz[0]) if len(sz) > 0 else 1000.0
                s1 = float(sz[1]) if len(sz) > 1 else s0
                s2 = float(sz[2]) if len(sz) > 2 else s0
                if shape == "SPHERE":
                    hw_w, hw_h = s0 * world_scale, s0 * world_scale
                elif shape == "ELLIPSOID":
                    hw_w, hw_h = s0 * world_scale, s2 * world_scale
                elif shape == "BOX":
                    hw_w, hw_h = s0 * world_scale * 0.5, s2 * world_scale * 0.5
                elif shape == "CYLINDER":
                    hw_w, hw_h = s0 * world_scale, s1 * world_scale * 0.5
                else:
                    hw_w, hw_h = s0 * world_scale, s0 * world_scale
                # Zonen auf das dargestellte Systempanel begrenzen.
                hw_w = min(hw_w, max(0.0, sx - view_x), max(0.0, view_x2 - sx))
                hw_h = min(hw_h, max(0.0, sy - view_y), max(0.0, view_y2 - sy))
                if hw_w <= 0.0 or hw_h <= 0.0:
                    continue
                zn = str(z.get("nickname", "")).lower()
                if "nebula" in zn or "badlands" in zn:
                    pen = QPen(self._scene_role_color("jump", 170), 1)
                    brush = QBrush(self._scene_role_color("jump_fill", 20))
                else:
                    pen = QPen(self._scene_role_color("zone", 170), 1)
                    brush = QBrush(self._scene_role_color("zone_fill", 20))
                if shape in ("BOX", "CYLINDER"):
                    it = scene.addRect(sx - hw_w, sy - hw_h, hw_w * 2, hw_h * 2, pen, brush)
                    it.setTransformOriginPoint(sx, sy)
                    it.setRotation(float(z.get("rotate_y", 0.0)))
                else:
                    scene.addEllipse(sx - hw_w, sy - hw_h, hw_w * 2, hw_h * 2, pen, brush)

            for obj in objs:
                p = tuple(obj.get("pos", (0.0, 0.0)))
                sx, sy = _to_scene_point(p, min_x, max_x, min_z, max_z, view_x, view_y, view_w, view_h)
                arch = str(obj.get("archetype", "")).lower()
                nick = str(obj.get("nickname", ""))
                rad = 1.6
                col = self._scene_object_color("default", 210)
                label_col = self._scene_object_color("default_label", 235)
                if "sun" in arch or "star" in arch:
                    rad = 4.2
                    col = self._scene_object_color("star", 230)
                elif "planet" in arch:
                    rad = 3.4
                    col = self._scene_object_color("planet", 230)
                elif any(k in arch for k in ("jumpgate", "jump_gate", "jumphole", "jump_hole", "nomad_gate")):
                    rad = 3.2
                    col = self._scene_object_color("jump", 230)
                    label_col = self._scene_object_color("jump_label", 235)
                elif "trade_lane_ring" in arch or "tradelane_ring" in arch:
                    rad = 1.8
                    col = self._scene_object_color("tradelane", 220)
                elif any(k in arch for k in ("station", "base", "outpost", "dock_ring")):
                    rad = 2.8
                    col = self._scene_object_color("base", 230)
                    label_col = self._scene_object_color("base_label", 235)
                scene.addEllipse(sx - rad, sy - rad, rad * 2, rad * 2, QPen(self._theme_color("fg", alpha=80)), QBrush(col))
                label_text = str(obj.get("label", "") or nick)
                if ("base" in arch or "dock_ring" in arch or "jump" in arch) and nick:
                    t = scene.addText(label_text)
                    t.setDefaultTextColor(label_col)
                    t.setScale(0.7)
                    t.setPos(sx + 3, sy - 3)

            for cand_list in info.get("jump_links", {}).values():
                for cand in cand_list:
                    jp = tuple(cand.get("pos", (0.0, 0.0)))
                    sx, sy = _to_scene_point(
                        jp, min_x, max_x, min_z, max_z,
                        view_x, view_y, view_w, view_h,
                    )
                    scene.addRect(
                        sx - 2.5, sy - 2.5, 5.0, 5.0,
                        QPen(self._scene_role_color("jump", 200)),
                        QBrush(self._scene_role_color("jump_fill", 140)),
                    )

            if highlight_jumps:
                for hj in highlight_jumps:
                    sx, sy = _to_scene_point(
                        hj, min_x, max_x, min_z, max_z,
                        view_x, view_y, view_w, view_h,
                    )
                    scene.addEllipse(
                        sx - 5, sy - 5, 10, 10,
                        QPen(self._scene_role_color("highlight"), 2),
                        QBrush(self._scene_role_color("highlight", 110)),
                    )

            path_pts: list[tuple[float, float]] = []
            if start_pt is not None and end_pt is not None:
                local_path = self._trade_route_local_path(info, start_pt, end_pt)
                for i in range(len(local_path) - 1):
                    a = _to_scene_point(
                        local_path[i], min_x, max_x, min_z, max_z,
                        view_x, view_y, view_w, view_h,
                    )
                    b = _to_scene_point(
                        local_path[i + 1], min_x, max_x, min_z, max_z,
                        view_x, view_y, view_w, view_h,
                    )
                    scene.addLine(a[0], a[1], b[0], b[1], QPen(self._scene_role_color("path", 240), 2))
                    if i == 0:
                        path_pts.append(a)
                    path_pts.append(b)
                if path_pts:
                    s0 = path_pts[0]
                    s1 = path_pts[-1]
                    scene.addEllipse(s0[0] - 4, s0[1] - 4, 8, 8, QPen(self._scene_role_color("measure")), QBrush(self._scene_role_color("measure")))
                    scene.addEllipse(s1[0] - 4, s1[1] - 4, 8, 8, QPen(self._scene_role_color("highlight")), QBrush(self._scene_role_color("highlight")))
            return {
                "path": path_pts,
                "start": path_pts[0] if path_pts else None,
                "end": path_pts[-1] if path_pts else None,
            }

        if len(path) <= 1:
            _draw_system(src_sys, 40, 40, 1280, 640, tuple(buy["pos"]), tuple(sell["pos"]))
        else:
            src_jump = self._trade_route_pick_jump_point(src_sys, path[1], tuple(buy["pos"])) or tuple(buy["pos"])
            dst_jump = self._trade_route_pick_jump_point(dst_sys, path[-2], tuple(sell["pos"])) or tuple(sell["pos"])
            src_res = _draw_system(
                src_sys,
                40,
                40,
                560,
                640,
                tuple(buy["pos"]),
                tuple(src_jump),
                highlight_jumps=[tuple(src_jump)],
            )
            dst_res = _draw_system(
                dst_sys,
                800,
                40,
                560,
                640,
                tuple(dst_jump),
                tuple(sell["pos"]),
                highlight_jumps=[tuple(dst_jump)],
            )

            chain_scene_points: list[tuple[float, float]] = []
            if src_res.get("end") is not None:
                chain_scene_points.append(tuple(src_res["end"]))
            transit = path[1:-1]
            if transit:
                start_x = 640.0
                end_x = 760.0
                y_vals: list[float] = []
                for sn in path:
                    if sn in self._trade_route_universe_pos:
                        y_vals.append(float(self._trade_route_universe_pos[sn][1]))
                y_min = min(y_vals) if y_vals else 0.0
                y_max = max(y_vals) if y_vals else 1.0
                y_span = max(1e-6, y_max - y_min)
                for i, sn in enumerate(transit):
                    cx = start_x + (i + 1) * ((end_x - start_x) / (len(transit) + 1))
                    uy = float(self._trade_route_universe_pos.get(sn, (0.0, float(i)))[1])
                    ny = (uy - y_min) / y_span
                    cy = 320.0 + (ny - 0.5) * 180.0
                    scene.addEllipse(cx - 4, cy - 4, 8, 8, QPen(self._theme_color("fg_dim")), QBrush(self._theme_color("fg_dim", alpha=200)))
                    t = scene.addText(sn)
                    t.setDefaultTextColor(self._theme_color("fg_dim"))
                    t.setPos(cx - 18, cy + 7)
                    chain_scene_points.append((cx, cy))
            if dst_res.get("start") is not None:
                chain_scene_points.append(tuple(dst_res["start"]))

            dash_pen = QPen(self._scene_role_color("path", 220), 2, Qt.DashLine)
            for i in range(len(chain_scene_points) - 1):
                a = chain_scene_points[i]
                b = chain_scene_points[i + 1]
                _draw_arrow_line(a[0], a[1], b[0], b[1], dash_pen)

        bounds = scene.itemsBoundingRect()
        if not bounds.isNull():
            self.trade_route_preview.fitInView(bounds.adjusted(-20, -20, 20, 20), Qt.KeepAspectRatio)

    def _help_tree_file_candidates(self) -> list[Path]:
        base_dir = Path(__file__).parent / "help"
        return help_tree_file_candidates(base_dir, get_language())

    @staticmethod
    def _help_xml_inner_html(node: ET.Element) -> str:
        return help_xml_inner_html(node)

    def _load_help_tree_sections(self) -> list[dict]:
        base_dir = Path(__file__).parent / "help"
        return load_help_tree_sections(base_dir, get_language())

    def _show_help(self):
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("app.title_help"))
        dlg.resize(1040, 760)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(8)
        lang_en = get_language() == "en"

        search_row = QHBoxLayout()
        search_row.addWidget(QLabel("Search:" if lang_en else "Suche:"))
        search_edit = QLineEdit()
        search_edit.setPlaceholderText("Search help..." if lang_en else "Hilfe durchsuchen...")
        search_next_btn = QPushButton("Next" if lang_en else "Weiter")
        search_status = QLabel("")
        search_status.setStyleSheet("color:#8aa0b8;")
        search_row.addWidget(search_edit, 1)
        search_row.addWidget(search_next_btn)
        lay.addLayout(search_row)
        lay.addWidget(search_status)

        split = QSplitter(Qt.Horizontal)
        lay.addWidget(split, 1)
        tree = QTreeWidget()
        tree.setHeaderHidden(True)
        tree.setMinimumWidth(280)
        tree.setMaximumWidth(440)
        split.addWidget(tree)
        info = QTextEdit()
        info.setReadOnly(True)
        info.setAcceptRichText(True)
        split.addWidget(info)
        split.setStretchFactor(0, 0)
        split.setStretchFactor(1, 1)

        sections = self._load_help_tree_sections()
        if not sections:
            info.setHtml(
                "<h3>Help</h3><p>No help content files found.</p>"
                if lang_en
                else "<h3>Hilfe</h3><p>Keine Hilfe-Dateien gefunden.</p>"
            )

        content_by_item: dict[QTreeWidgetItem, str] = {}
        flat_items: list[QTreeWidgetItem] = []
        for section in sections:
            parent = QTreeWidgetItem([str(section.get("title", ""))])
            tree.addTopLevelItem(parent)
            parent.setExpanded(True)
            flat_items.append(parent)
            for entry in section.get("children", []):
                child = QTreeWidgetItem([str(entry.get("title", ""))])
                parent.addChild(child)
                flat_items.append(child)
                content_by_item[child] = str(entry.get("content", "<p>-</p>"))

        btn_row = QWidget()
        bl = QHBoxLayout(btn_row)
        bl.setContentsMargins(0, 2, 0, 0)
        bl.setSpacing(8)
        self.help_reset_btn = QPushButton(tr("help.reset_factory"))
        self.help_reset_btn.clicked.connect(lambda: self._factory_reset_from_help(dlg))
        bl.addWidget(self.help_reset_btn)
        help_discord_btn = QPushButton(tr("action.discord"))
        help_discord_btn.clicked.connect(self._open_discord_invite)
        bl.addWidget(help_discord_btn)
        bl.addStretch(1)
        close_bb = QDialogButtonBox(QDialogButtonBox.Close)
        close_bb.rejected.connect(dlg.reject)
        close_bb.accepted.connect(dlg.accept)
        bl.addWidget(close_bb)
        lay.addWidget(btn_row)

        def _show_item_content(item: QTreeWidgetItem | None):
            if item is None:
                info.setHtml("<p>-</p>")
                return
            html_body = content_by_item.get(item)
            if html_body:
                info.setHtml(html_body)
                return
            info.setHtml(
                f"<h3>{item.text(0)}</h3>"
                + ("<p>Select a sub-item on the left.</p>" if lang_en else "<p>Waehle links einen Unterpunkt.</p>")
            )

        tree.currentItemChanged.connect(lambda cur, _prev: _show_item_content(cur))
        if tree.topLevelItemCount() > 0:
            first = tree.topLevelItem(0)
            if first is not None and first.childCount() > 0:
                tree.setCurrentItem(first.child(0))
            else:
                tree.setCurrentItem(first)

        searchable: list[tuple[int, QTreeWidgetItem, str]] = []
        for i, it in enumerate(flat_items):
            blob = (it.text(0) + " " + content_by_item.get(it, "")).lower()
            searchable.append((i, it, blob))
        search_state = {"idx": -1}

        def _run_search(next_only: bool = False):
            term = search_edit.text().strip().lower()
            if not term:
                search_status.setText("")
                return
            if not searchable:
                search_status.setText("No help pages." if lang_en else "Keine Hilfe-Seiten.")
                return
            start_idx = 0 if search_state["idx"] < 0 else search_state["idx"]
            if next_only:
                start_idx = (start_idx + 1) % len(searchable)
            for offs in range(len(searchable)):
                idx = (start_idx + offs) % len(searchable)
                _i, it, blob = searchable[idx]
                if term in blob:
                    search_state["idx"] = idx
                    tree.setCurrentItem(it)
                    search_status.setText(
                        (f'Found in "{it.text(0)}"' if lang_en else f'Gefunden in "{it.text(0)}"')
                    )
                    return
            search_status.setText("No results." if lang_en else "Keine Treffer.")

        connect_debounced_line_edit(search_edit, lambda: _run_search(next_only=False), trigger_return_pressed=False)
        search_next_btn.clicked.connect(lambda: _run_search(next_only=True))
        search_edit.returnPressed.connect(lambda: _run_search(next_only=True))
        dlg.exec()

