    #  System laden
    # ------------------------------------------------------------------
    def _load(self, path: str, restore: QTransform | None = None):
        load_system(self, path, restore=restore)

    def _retranslate_trade_route_headers(self):
        if not hasattr(self, "trade_routes_table"):
            return
        self.trade_routes_table.setHorizontalHeaderLabels(
            [
                tr("trade.col.commodity"),
                tr("trade.col.buy_at"),
                tr("trade.col.buy_price"),
                tr("trade.col.sell_at"),
                tr("trade.col.sell_price"),
                tr("trade.col.source_system"),
                tr("trade.col.target_system"),
                tr("trade.col.route_type"),
                tr("trade.col.profit"),
                tr("trade.col.jumps"),
                tr("trade.col.profit_per_jump"),
                tr("trade.col.net_profit"),
                tr("trade.col.score"),
            ]
        )
        self._sync_flight_button_visibility()

    # ==================================================================
    #  Auswahl
    # ==================================================================
    def _clear_multi_selection(self):
        for it in list(self._multi_selected):
            if isinstance(it, SolarObject) and hasattr(it, "setPen") and hasattr(it, "pen"):
                try:
                    p = it.pen()
                    p.setColor(self._theme_color("fg", alpha=70))
                    p.setWidth(1)
                    it.setPen(p)
                except Exception:
                    pass
        self._multi_selected.clear()

    def _toggle_multi_selection(self, it):
        if it in self._multi_selected:
            self._multi_selected.remove(it)
            if isinstance(it, SolarObject) and hasattr(it, "setPen") and hasattr(it, "pen"):
                p = it.pen()
                p.setColor(self._theme_color("fg", alpha=70))
                p.setWidth(1)
                it.setPen(p)
        else:
            self._multi_selected.append(it)
            if isinstance(it, SolarObject) and hasattr(it, "setPen") and hasattr(it, "pen"):
                p = it.pen()
                p.setColor(self._theme_color("fg_accent"))
                p.setWidth(2)
                it.setPen(p)
        self.statusBar().showMessage(
            tr("status.multi_select_count").format(count=len(self._multi_selected))
        )

    def _on_2d_item_clicked(self, item, ctrl_held: bool):
        if self._filepath is None:
            return
        if not ctrl_held:
            return
        resolved_item = self._resolve_2d_interaction_item(item)
        if isinstance(resolved_item, (SolarObject, ZoneItem)):
            self._toggle_multi_selection(resolved_item)

    def _on_2d_object_selected(self, obj) -> None:
        resolved_obj = self._resolve_2d_interaction_item(obj)
        if isinstance(resolved_obj, SolarObject):
            self._select(resolved_obj)

    def _resolve_2d_interaction_item(self, item):
        if not isinstance(item, SolarObject) or hasattr(item, "sys_path"):
            return item
        if not self._is_base_builder_child_object(item):
            return item
        return self._base_display_root_object(item) or item

    def _select(self, obj: SolarObject):
        if self._selected is not obj:
            self._clear_move_delta_indicator()
        # Docking-Ring-Workflow: Planet-Auswahl abfangen
        if (self._pending_dock_ring
                and self._pending_dock_ring.get("step") == 1
                and isinstance(obj, SolarObject)
                and not hasattr(obj, "sys_path")):
            if not self._is_planet_object(obj):
                self.statusBar().showMessage("Bitte einen Planeten auswählen")
                return
            self._on_dock_ring_planet_selected(obj)
            return

        if hasattr(obj, "sys_path"):
            # Universum-System: Auswahl erlauben für Verschieben + Editor
            if self._selected and self._selected is not obj:
                self._selected._pos_change_cb = None
                self._selected._drag_finished_cb = None
                if hasattr(self._selected, "set_highlighted"):
                    self._selected.set_highlighted(False)
            self._selected = obj
            obj._pos_change_cb = self._on_universe_system_moved
            obj._drag_finished_cb = self._on_universe_drag_finished
            obj.set_highlighted(True)
            self.uni_delete_btn.setEnabled(True)
            self.statusBar().showMessage(
                tr("status.system_info").format(nickname=self._system_display_name(obj.nickname))
            )
            self._show_uni_system_editor(obj.nickname)
            self._set_active_overlap_system(obj.nickname)
            self._update_universe_lines()
            self._refresh_base_builder_dialog_state()
            return

        if self._selected:
            self._selected._pos_change_cb = None
            self._selected._drag_finished_cb = None
            if (
                hasattr(self._selected, "setPen")
                and hasattr(self._selected, "pen")
                and self._selected not in self._multi_selected
            ):
                p = self._selected.pen()
                p.setColor(self._theme_color("fg", alpha=70))
                p.setWidth(1)
                self._selected.setPen(p)

        self._selected = obj
        if hasattr(obj, "setPen") and hasattr(obj, "pen"):
            p = obj.pen()
            p.setColor(self._scene_role_color("measure"))
            p.setWidth(2)
            obj.setPen(p)
            obj._pos_change_cb = self._on_obj_moved
            obj._drag_finished_cb = self._on_obj_drag_finished
            obj._last_scene_pos = (obj.pos().x(), obj.pos().y())
            obj._drag_snapshot_taken = False

        if obj not in self._multi_selected:
            self._clear_multi_selection()
        self.name_lbl.setText(f"📍 {self._object_display_label(obj)}")
        self.editor.setPlainText(obj.raw_text())
        self.editor.setVisible(True)
        self.apply_btn.setVisible(True)
        self._hide_zone_extra_editors()
        self.edit_obj_btn.setEnabled(True)
        self.apply_btn.setEnabled(True)
        self.delete_btn.setEnabled(True)
        self.preview3d_btn.setEnabled(True)
        self.add_exclusion_btn.setEnabled(False)
        self.statusBar().showMessage(tr("status.object_selected").format(nickname=self._object_display_label(obj)))
        self.view3d.set_selected(obj)
        self._sync_view3d_selected_native_scene_data()
        self._sync_obj_combo_to_selection()
        self._refresh_editing_action_states()

        # Quick-Editor füllen
        self.arch_cb.blockSignals(True)
        self.loadout_cb.blockSignals(True)
        self.faction_cb.blockSignals(True)
        self.arch_cb.setCurrentText(obj.data.get("archetype", ""))
        self.loadout_cb.setCurrentText(obj.data.get("loadout", ""))
        rep_val = obj.data.get("reputation", "")
        if rep_val:
            parts = [p.strip() for p in rep_val.split(",")]
            self.faction_cb.setCurrentText(self._faction_ui_label(parts[0] if parts else ""))
            self.rep_edit.setText(parts[1] if len(parts) > 1 else "")
        else:
            self.faction_cb.setCurrentText("")
            self.rep_edit.clear()
        self.arch_cb.blockSignals(False)
        self.loadout_cb.blockSignals(False)
        self.faction_cb.blockSignals(False)
        if self._flight_lock_active:
            self._set_flight_edit_lock(True)
        self._refresh_base_builder_dialog_state()

    def _select_zone(self, zone):
        self._clear_move_delta_indicator()
        if self._pending_dock_ring and self._pending_dock_ring.get("step") == 1:
            # Klick auf Zone statt Planet: versuche passenden Planeten am Zonen-Zentrum zu finden.
            best_obj = None
            best_dist = None
            zx = zone.pos().x()
            zy = zone.pos().y()
            for obj in self._objects:
                if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                    continue
                if not self._is_planet_object(obj):
                    continue
                dx = obj.pos().x() - zx
                dy = obj.pos().y() - zy
                d2 = dx * dx + dy * dy
                if best_dist is None or d2 < best_dist:
                    best_dist = d2
                    best_obj = obj
            if best_obj is not None and best_dist is not None and best_dist <= (25.0 * 25.0):
                self._on_dock_ring_planet_selected(best_obj)
                return
            self.statusBar().showMessage("Bitte einen Planeten auswählen")
            return

        if not self.zone_cb.isChecked():
            return
        if zone not in self._multi_selected:
            self._clear_multi_selection()
        self.name_lbl.setText(f"📍 {zone.nickname}")
        self.editor.setPlainText(zone.raw_text())
        self.editor.setVisible(True)
        self.apply_btn.setVisible(True)
        self._hide_zone_extra_editors()
        self.edit_obj_btn.setEnabled(True)
        self.apply_btn.setEnabled(True)
        self.delete_btn.setEnabled(True)
        self.preview3d_btn.setEnabled(False)
        self.add_exclusion_btn.setEnabled(self._is_field_zone(zone.nickname))
        self.statusBar().showMessage(tr("status.zone_selected").format(nickname=zone.nickname))
        self._selected = zone
        self.view3d.set_selected(None)
        self._sync_view3d_selected_native_scene_data()
        self._sync_obj_combo_to_selection()
        self._refresh_editing_action_states()
        if self._flight_lock_active:
            self._set_flight_edit_lock(True)
        self._refresh_base_builder_dialog_state()

    def _clear_selection_ui(self):
        """Setzt die UI-Elemente zurück wenn nichts ausgewählt ist."""
        self._clear_move_delta_indicator()
        if self._selected is not None:
            self._selected._pos_change_cb = None
            self._selected._drag_finished_cb = None
        self._clear_multi_selection()
        self._selected = None
        self.view3d.set_selected(None)
        self._sync_view3d_selected_native_scene_data()
        self.apply_btn.setEnabled(False)
        self.edit_obj_btn.setEnabled(False)
        self.name_lbl.setText(tr("lbl.no_object"))
        self.editor.clear()
        self.editor.setVisible(True)
        self.apply_btn.setVisible(True)
        self.delete_btn.setEnabled(False)
        self.preview3d_btn.setEnabled(False)
        self.add_exclusion_btn.setEnabled(False)
        if hasattr(self, "uni_delete_btn"):
            self.uni_delete_btn.setEnabled(False)
        self.write_btn.setEnabled(False)
        self._apply_write_button_state_style()
        self._refresh_editing_action_states()
        if self._flight_lock_active:
            self._set_flight_edit_lock(True)
        self._refresh_base_builder_dialog_state()

    def _cancel_selection(self):
        if self._selected is None and not self._multi_selected:
            return
        self._clear_selection_ui()
        self._hide_zone_extra_editors()
        self.obj_combo.blockSignals(True)
        self.obj_combo.setCurrentIndex(-1)
        self.obj_combo.blockSignals(False)
        self.statusBar().showMessage(tr("status.selection_cleared"))

    # ==================================================================
    #  Echtzeit-Position (Drag)
    # ==================================================================
    def _on_obj_moved(self, obj: SolarObject):
        if self._ed_busy or obj is not self._selected:
            return
        new_pos = obj.fl_pos_str()
        obj.data["_entries"] = [
            (k, new_pos if k.lower() == "pos" else v) for k, v in obj.data.get("_entries", [])
        ]
        obj.data["pos"] = new_pos
        self._sync_object_section_from_obj(obj)
        updated = []
        for line in self.editor.toPlainText().splitlines():
            if line.partition("=")[0].strip().lower() == "pos":
                updated.append(f"pos = {new_pos}")
            else:
                updated.append(line)
        self._ed_busy = True
        cur = self.editor.textCursor().position()
        self.editor.setPlainText("\n".join(updated))
        tc = self.editor.textCursor()
        tc.setPosition(min(cur, len(self.editor.toPlainText())))
        self.editor.setTextCursor(tc)
        self._ed_busy = False
        self._set_dirty(True)
        self.view3d.update_object_position(obj, self._scale)
        nx, ny, nz = parse_position(new_pos)
        drag_start = getattr(obj, "_drag_start_scene_pos", None)
        start_scene = drag_start if isinstance(drag_start, QPointF) else None
        start_fl = None
        if start_scene is not None:
            start_fl = (start_scene.x() / self._scale, ny, start_scene.y() / self._scale)
        self._update_move_delta_indicator(
            obj,
            (nx, ny, nz),
            QPointF(obj.pos().x(), obj.pos().y()),
            origin_fl=start_fl,
            origin_scene=start_scene,
        )

        # Zugehörige Death-Zonen mitverschieben
        self._move_linked_zones(obj)
        self._move_linked_docking_rings(obj)

    def _on_obj_drag_finished(self, obj: SolarObject, start_pos: QPointF, end_pos: QPointF):
        if obj is None:
            return
        obj._drag_snapshot_taken = False
        obj._last_scene_pos = (end_pos.x(), end_pos.y())
        _, cur_y, _ = parse_position(obj.data.get("pos", "0,0,0"))
        old_pos = self._scene_to_fl_pos_with_y(start_pos, cur_y)
        new_pos = self._scene_to_fl_pos_with_y(end_pos, cur_y)
        if old_pos != new_pos:
            self._push_undo_action(
                {
                    "type": "move_object",
                    "label": f"Objekt verschoben: {obj.nickname}",
                    "filepath": self._filepath or "",
                    "nickname": obj.nickname,
                    "old_pos": old_pos,
                    "new_pos": new_pos,
                }
            )
        sx = start_pos.x() / self._scale
        sz = start_pos.y() / self._scale
        ex = end_pos.x() / self._scale
        ez = end_pos.y() / self._scale
        self._append_change_log(
            f"Objekt verschoben: {obj.nickname} ({sx:.1f}, {sz:.1f}) → ({ex:.1f}, {ez:.1f})"
        )
        self._reset_move_delta_origin()

    def _on_universe_drag_finished(self, obj: SolarObject, start_pos: QPointF, end_pos: QPointF):
        if obj is None:
            return
        sx = start_pos.x() / self._scale
        sy = start_pos.y() / self._scale
        ex = end_pos.x() / self._scale
        ey = end_pos.y() / self._scale
        dx = ex - sx
        dy = ey - sy
        moved_count = 1
        if abs(dx) > 1e-6 or abs(dy) > 1e-6:
            self._push_undo_action(
                {
                    "type": "move_universe_system",
                    "label": f"System verschoben: {obj.nickname}",
                    "nickname": obj.nickname,
                    "old_x": sx,
                    "old_y": sy,
                    "new_x": ex,
                    "new_y": ey,
                }
            )
            group = [
                it for it in self._multi_selected
                if isinstance(it, SolarObject) and hasattr(it, "sys_path")
            ]
            if obj in group and len(group) > 1:
                moved_count = len(group)
                for other in group:
                    if other is obj:
                        continue
                    ox = other.pos().x() / self._scale
                    oy = other.pos().y() / self._scale
                    self._push_undo_action(
                        {
                            "type": "move_universe_system",
                            "label": f"System verschoben: {other.nickname}",
                            "nickname": other.nickname,
                            "old_x": ox - dx,
                            "old_y": oy - dy,
                            "new_x": ox,
                            "new_y": oy,
                        }
                    )
                    self._append_change_log(
                        f"System verschoben: {other.nickname} ({ox - dx:.0f}, {oy - dy:.0f}) → ({ox:.0f}, {oy:.0f})"
                    )
                    other._last_scene_pos = (other.pos().x(), other.pos().y())
        self._append_change_log(
            f"System verschoben: {obj.nickname} ({sx:.0f}, {sy:.0f}) → ({ex:.0f}, {ey:.0f})"
        )
        obj._last_scene_pos = (obj.pos().x(), obj.pos().y())
        self._apply_universe_overlap_spread()
        self._update_universe_lines()
        if (abs(dx) > 1e-6 or abs(dy) > 1e-6) and moved_count > 1:
            self.statusBar().showMessage(tr("status.multi_systems_moved").format(count=moved_count))

    def _apply_universe_overlap_spread(self):
        if self._filepath is not None:
            return
        self._uni_overlap_group_by_system = {}
        self._uni_overlap_members_by_group = {}
        self._uni_overlap_default_by_group = {}
        systems = [o for o in self._objects if isinstance(o, UniverseSystem) and o.isVisible()]
        groups: dict[tuple[float, float], list[UniverseSystem]] = {}
        for obj in systems:
            key = (round(float(obj.pos().x()), 2), round(float(obj.pos().y()), 2))
            groups.setdefault(key, []).append(obj)

        step_scene = max(0.3 * float(self._scale), 0.01)
        for group_key, members in groups.items():
            if len(members) <= 1:
                members[0].set_overlap_compact(False)
                continue
            self._uni_overlap_members_by_group[group_key] = [str(m.nickname).upper() for m in members]
            default_nick = str(members[0].nickname).upper()
            self._uni_overlap_default_by_group[group_key] = default_nick
            active_nick = str(self._uni_overlap_active_by_group.get(group_key, default_nick) or default_nick).upper()
            if active_nick not in self._uni_overlap_members_by_group[group_key]:
                active_nick = default_nick
            self._uni_overlap_active_by_group[group_key] = active_nick
            cols = max(1, int(math.ceil(math.sqrt(len(members)))))
            rows = int(math.ceil(len(members) / cols))
            anchor_x = float(members[0].pos().x())
            anchor_y = float(members[0].pos().y())
            for idx, obj in enumerate(members):
                nick_u = str(obj.nickname).upper()
                self._uni_overlap_group_by_system[nick_u] = group_key
                gx = (idx % cols) - (cols - 1) * 0.5
                gy = (idx // cols) - (rows - 1) * 0.5
                obj.setPos(anchor_x + gx * step_scene, anchor_y + gy * step_scene)
                obj._last_scene_pos = (obj.pos().x(), obj.pos().y())
                obj.set_overlap_compact(True)

    def _center_universe_visible_systems(self):
        if self._filepath is not None:
            return
        visible = [
            o for o in self._objects
            if isinstance(o, UniverseSystem) and o.isVisible()
        ]
        if not visible:
            return
        xs = [float(o.pos().x()) for o in visible]
        ys = [float(o.pos().y()) for o in visible]
        cx = (min(xs) + max(xs)) * 0.5
        cy = (min(ys) + max(ys)) * 0.5
        self.view.centerOn(QPointF(cx, cy))

    def _refresh_universe_line_length_limit(self):
        if self._filepath is not None:
            self._uni_line_length_limit_world = 0.0
            return
        if self._scale <= 1e-9:
            self._uni_line_length_limit_world = 0.0
            return
        visible = [
            o for o in self._objects
            if isinstance(o, UniverseSystem) and o.isVisible()
        ]
        if not visible:
            self._uni_line_length_limit_world = 0.0
            return
        xs = [float(o.pos().x()) / self._scale for o in visible]
        ys = [float(o.pos().y()) / self._scale for o in visible]
        span = max(max(xs) - min(xs), max(ys) - min(ys))
        self._uni_line_length_limit_world = max(float(span), 0.0)

    def _set_active_overlap_system(self, nickname: str):
        nick_u = str(nickname or "").strip().upper()
        if not nick_u:
            return
        group_key = self._uni_overlap_group_by_system.get(nick_u)
        if group_key is None:
            return
        self._uni_overlap_active_by_group[group_key] = nick_u

    def _is_overlap_endpoint_visible(self, nickname: str) -> bool:
        nick_u = str(nickname or "").strip().upper()
        if not nick_u:
            return False
        group_key = self._uni_overlap_group_by_system.get(nick_u)
        if group_key is None:
            return True
        active = str(self._uni_overlap_active_by_group.get(group_key, "")).upper()
        if not active:
            active = str(self._uni_overlap_default_by_group.get(group_key, nick_u)).upper()
            self._uni_overlap_active_by_group[group_key] = active
        return nick_u == active

    def _is_overlap_endpoint_red(self, nickname: str) -> bool:
        nick_u = str(nickname or "").strip().upper()
        if not nick_u:
            return False
        group_key = self._uni_overlap_group_by_system.get(nick_u)
        if group_key is None:
            return False
        active = str(self._uni_overlap_active_by_group.get(group_key, "")).upper()
        default_nick = str(self._uni_overlap_default_by_group.get(group_key, "")).upper()
        return bool(active and active == nick_u and default_nick and active != default_nick)

    def _move_linked_zones(self, obj: SolarObject):
        """Verschiebt Death-Zonen, die zum Objekt gehören (z.B. Zone_SUN01_death)."""
        nick = obj.nickname.lower()
        # Suche nach Zonen mit Muster: Zone_{NICK}_death, {NICK}_death, zone_{NICK}
        for z in self._zones:
            zn = z.nickname.lower()
            if nick in zn and ("death" in zn or "exclusion" in zn):
                z.setPos(obj.pos())
                # Zone-Daten aktualisieren
                new_pos = obj.fl_pos_str()
                if "_entries" in z.data:
                    z.data["_entries"] = [
                        (k, new_pos) if k.lower() == "pos" else (k, v)
                        for k, v in z.data["_entries"]
                    ]
                z.data["pos"] = new_pos
                self._sync_zone_section_from_zone(z)
                self._set_dirty(True)

    def _move_linked_docking_rings(self, obj: SolarObject):
        arch = obj.data.get("archetype", "").lower()
        if "planet" not in arch:
            return
        base_nick = obj.data.get("base", "").strip()
        if not base_nick:
            return

        prev_scene = getattr(obj, "_last_scene_pos", None)
        if prev_scene is None:
            prev_scene = (obj.pos().x(), obj.pos().y())
        dx = obj.pos().x() - prev_scene[0]
        dy = obj.pos().y() - prev_scene[1]
        if abs(dx) < 0.001 and abs(dy) < 0.001:
            obj._last_scene_pos = (obj.pos().x(), obj.pos().y())
            return

        bn_lower = base_nick.lower()
        for other in self._objects:
            if other is obj:
                continue
            if other.data.get("dock_with", "").strip().lower() != bn_lower:
                continue

            other.setPos(other.pos().x() + dx, other.pos().y() + dy)
            cur_pos_raw = other.data.get("pos", "0, 0, 0")
            cur_parts = [p.strip() for p in cur_pos_raw.split(",")]
            try:
                cur_y = float(cur_parts[1])
            except (ValueError, IndexError):
                cur_y = 0.0
            new_pos = (
                f"{other.pos().x() / self._scale:.2f}, "
                f"{cur_y:.2f}, "
                f"{other.pos().y() / self._scale:.2f}"
            )
            other.data["_entries"] = [
                (k, new_pos if k.lower() == "pos" else v)
                for k, v in other.data.get("_entries", [])
            ]
            other.data["pos"] = new_pos
            self._sync_object_section_from_obj(other)
            self.view3d.update_object_position(other, self._scale)
            self._set_dirty(True)
        obj._last_scene_pos = (obj.pos().x(), obj.pos().y())

    def _sync_object_section_from_obj(self, obj: SolarObject):
        try:
            obj_idx = self._objects.index(obj)
        except ValueError:
            return
        count = 0
        for i, (sec_name, _entries) in enumerate(self._sections):
            if sec_name.lower() != "object":
                continue
            if count == obj_idx:
                self._sections[i] = ("Object", list(obj.data.get("_entries", [])))
                return
            count += 1

    def _sync_zone_section_from_zone(self, zone: ZoneItem):
        try:
            zone_idx = self._zones.index(zone)
        except ValueError:
            return
        count = 0
        for i, (sec_name, _entries) in enumerate(self._sections):
            if sec_name.lower() != "zone":
                continue
            if count == zone_idx:
                self._sections[i] = ("Zone", list(zone.data.get("_entries", [])))
                return
            count += 1

    # ==================================================================
    #  Editor-Feld-Update (Quick-Editor)
    # ==================================================================
    def _update_editor_field(self, key: str, value: str):
        if not self._selected:
            return
        updated = []
        found = False
        lc_key = key.lower()
        for line in self.editor.toPlainText().splitlines():
            if line.partition("=")[0].strip().lower() == lc_key:
                if value.strip():
                    updated.append(f"{key} = {value}")
                found = True
            else:
                updated.append(line)
        if not found and value.strip():
            updated.append(f"{key} = {value}")
        self._ed_busy = True
        cur = self.editor.textCursor().position()
        self.editor.setPlainText("\n".join(updated))
        tc = self.editor.textCursor()
        tc.setPosition(min(cur, len(self.editor.toPlainText())))
        self.editor.setTextCursor(tc)
        self._ed_busy = False
        self._set_dirty(True)

    def _on_faction_changed(self, text: str):
        if not text:
            return
        faction_nick = self._faction_from_ui(text)
        if not faction_nick:
            return
        rep_val = self.rep_edit.text().strip()
        if rep_val:
            self._update_editor_field("reputation", f"{faction_nick},{rep_val}")
        else:
            self._update_editor_field("reputation", faction_nick)

    def _on_rep_changed(self):
        if not self.faction_cb.currentText():
            return
        faction_nick = self._faction_from_ui(self.faction_cb.currentText())
        if not faction_nick:
            return
        val = self.rep_edit.text().strip()
        if val:
            self._update_editor_field("reputation", f"{faction_nick},{val}")
        else:
            self._update_editor_field("reputation", faction_nick)

    # ==================================================================
    #  Objekt-Editor / Zone-Link-Editor
    # ==================================================================
    def _start_object_edit(self):
        if not self._selected:
            return
        sel = self._selected
        self._sync_obj_combo_to_selection()
        if isinstance(sel, ZoneItem):
            self._open_zone_editor(sel)
            return
        if not isinstance(sel, SolarObject):
            return

        entries = sel.data.get("_entries", [])
        arch = sel.data.get("archetype", "").lower()
        nick = sel.nickname.lower()
        has_base = any(k.lower() in ("base", "dock_with") and str(v).strip() for k, v in entries)
        is_tradelane = (
            "trade_lane_ring" in arch
            or "tradelane_ring" in arch
            or "trade_lane_ring" in nick
            or "tradelane_ring" in nick
        )

        if has_base:
            self._edit_base()
            return
        if is_tradelane:
            self._edit_tradelane()
            return
        self._open_generic_object_editor(sel)

    @staticmethod
    def _parse_vec3(raw: str, default: tuple[float, float, float] = (0.0, 0.0, 0.0)) -> tuple[float, float, float]:
        vals = [s.strip() for s in str(raw or "").split(",")]
        out = [default[0], default[1], default[2]]
        for i in range(min(3, len(vals))):
            try:
                out[i] = float(vals[i])
            except ValueError:
                pass
        return out[0], out[1], out[2]

    def _open_generic_object_editor(self, obj: SolarObject):
        old_entries = [(str(k), str(v)) for k, v in obj.data.get("_entries", [])]
        old_nickname = str(obj.nickname)
        dlg = QDialog(self)
        dlg.setWindowTitle(f"{tr('btn.edit_object')}: {self._object_display_label(obj)}")
        dlg.setModal(True)
        fl = QFormLayout(dlg)

        nick_edit = QLineEdit(obj.data.get("nickname", obj.nickname))
        ids_name_current = str(obj.data.get("ids_name", "") or "").strip()
        ids_name_display = self._display_name_from_ids_name(ids_name_current) if ids_name_current else ""
        ids_name_text_edit = QLineEdit(ids_name_display)
        ids_name_text_edit.setPlaceholderText("Ingame Name (ids_name)")
        arch_cb = QComboBox()
        arch_cb.setEditable(True)
        arch_vals = [self.arch_cb.itemText(i) for i in range(self.arch_cb.count()) if self.arch_cb.itemText(i)]
        arch_cb.addItems(arch_vals)
        arch_cb.setCurrentText(obj.data.get("archetype", ""))

        loadout_cb = QComboBox()
        loadout_cb.setEditable(True)
        loadout_vals = [self.loadout_cb.itemText(i) for i in range(self.loadout_cb.count()) if self.loadout_cb.itemText(i)]
        loadout_cb.addItems(loadout_vals)
        loadout_cb.setCurrentText(obj.data.get("loadout", ""))

        faction_cb = QComboBox()
        faction_cb.setEditable(True)
        faction_vals = [self.faction_cb.itemText(i) for i in range(self.faction_cb.count()) if self.faction_cb.itemText(i)]
        faction_cb.addItems(faction_vals)
        rep_raw = str(obj.data.get("reputation", "") or "").strip()
        rep_parts = [p.strip() for p in rep_raw.split(",", 1)] if rep_raw else []
        faction_ui = self._faction_ui_label(rep_parts[0] if rep_parts else "")
        if len(rep_parts) > 1 and rep_parts[1]:
            faction_ui = f"{faction_ui}, {rep_parts[1]}"
        faction_cb.setCurrentText(faction_ui)

        px, py, pz = self._parse_vec3(obj.data.get("pos", "0,0,0"))
        rx, ry, rz = self._parse_vec3(obj.data.get("rotate", "0,0,0"))

        pos_x = QDoubleSpinBox()
        pos_y = QDoubleSpinBox()
        pos_z = QDoubleSpinBox()
        for spin, val in ((pos_x, px), (pos_y, py), (pos_z, pz)):
            spin.setRange(-10000000.0, 10000000.0)
            spin.setDecimals(2)
            spin.setValue(val)

        rot_x = QDoubleSpinBox()
        rot_y = QDoubleSpinBox()
        rot_z = QDoubleSpinBox()
        for spin, val in ((rot_x, rx), (rot_y, ry), (rot_z, rz)):
            spin.setRange(-360.0, 360.0)
            spin.setDecimals(2)
            spin.setValue(val)

        fl.addRow("Nickname", nick_edit)
        fl.addRow("Ingame Name", ids_name_text_edit)
        fl.addRow("Archetype", arch_cb)
        fl.addRow("Loadout", loadout_cb)
        fl.addRow("Reputation", faction_cb)
        fl.addRow("Pos X", pos_x)
        fl.addRow("Pos Y", pos_y)
        fl.addRow("Pos Z", pos_z)
        fl.addRow("Rot X", rot_x)
        fl.addRow("Rot Y", rot_y)
        fl.addRow("Rot Z", rot_z)

        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        fl.addRow(bb)

        if dlg.exec() != QDialog.Accepted:
            return

        new_map = {
            "nickname": nick_edit.text().strip(),
            "archetype": arch_cb.currentText().strip(),
            "loadout": loadout_cb.currentText().strip(),
            "reputation": self._normalize_reputation_value(faction_cb.currentText().strip()),
            "pos": f"{pos_x.value():.2f}, {pos_y.value():.2f}, {pos_z.value():.2f}",
            "rotate": f"{rot_x.value():.2f}, {rot_y.value():.2f}, {rot_z.value():.2f}",
        }
        new_ids_name = ids_name_current
        ids_name_new_text = ids_name_text_edit.text().strip()
        if ids_name_new_text and ids_name_new_text != ids_name_display:
            try:
                new_ids_name = self._ensure_ids_name_in_user_dll(ids_name_current, ids_name_new_text)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
                return
        if new_ids_name:
            new_map["ids_name"] = new_ids_name

        entries = list(obj.data.get("_entries", []))
        changed_keys: set[str] = set()
        merged: list[tuple[str, str]] = []
        for k, v in entries:
            lk = k.lower()
            if lk in new_map and lk not in changed_keys:
                nv = new_map[lk]
                if nv:
                    merged.append((k, nv))
                changed_keys.add(lk)
            else:
                merged.append((k, v))
        for lk, nv in new_map.items():
            if lk not in changed_keys and nv:
                merged.append((lk, nv))

        obj.data["_entries"] = merged
        for k, v in merged:
            obj.data[k.lower()] = v
        obj.nickname = obj.data.get("nickname", obj.nickname)
        if obj.label:
            obj.label.setPlainText(self._object_display_label(obj))

        px2, _, pz2 = self._parse_vec3(obj.data.get("pos", "0,0,0"))
        obj.setPos(px2 * self._scale, pz2 * self._scale)

        obj_idx = None
        try:
            obj_idx = self._objects.index(obj)
        except ValueError:
            obj_idx = None
        if obj_idx is not None:
            count = 0
            for i, (sec_name, _) in enumerate(self._sections):
                if sec_name.lower() == "object":
                    if count == obj_idx:
                        self._sections[i] = ("Object", list(merged))
                        break
                    count += 1

        self.editor.setPlainText(obj.raw_text())
        self._rebuild_object_combo()
        self._selected = obj
        self._sync_obj_combo_to_selection()
        self.name_lbl.setText(f"📍 {self._object_display_label(obj)}")
        new_entries = [(str(k), str(v)) for k, v in obj.data.get("_entries", [])]
        if new_entries != old_entries:
            try:
                obj_idx = self._objects.index(obj)
            except ValueError:
                obj_idx = None
            self._push_undo_action(
                {
                    "type": "edit_object",
                    "label": f"Objekt bearbeitet: {obj.nickname}",
                    "filepath": self._filepath or "",
                    "object_index": obj_idx,
                    "old_nickname": old_nickname,
                    "new_nickname": obj.nickname,
                    "old_entries": [list(p) for p in old_entries],
                    "new_entries": [list(p) for p in new_entries],
                }
            )
            self._append_change_log(f"Objekt bearbeitet: {old_nickname} -> {obj.nickname}")
        self._set_dirty(True)
        self._refresh_3d_scene()
        self.statusBar().showMessage(tr("status.changes_applied").format(nickname=self._object_display_label(obj)))

    def _open_zone_editor(self, zone: ZoneItem):
        old_entries = [(str(k), str(v)) for k, v in zone.data.get("_entries", [])]
        old_nickname = str(zone.nickname)

        dlg = QDialog(self)
        dlg.setWindowTitle(f"{tr('ctx.edit_zone')}: {zone.nickname}")
        dlg.setModal(True)
        fl = QFormLayout(dlg)

        nick_edit = QLineEdit(zone.data.get("nickname", zone.nickname))
        ids_name_current = str(zone.data.get("ids_name", "") or "").strip()
        ids_name_display = self._display_name_from_ids_name(ids_name_current) if ids_name_current else ""
        ids_name_text_edit = QLineEdit(ids_name_display)
        ids_name_text_edit.setPlaceholderText("Ingame Name (ids_name)")

        shape_cb = QComboBox()
        shape_cb.setEditable(True)
        shape_cb.addItems(["SPHERE", "ELLIPSOID", "BOX", "CYLINDER", "RING"])
        shape_cb.setCurrentText(str(zone.data.get("shape", "SPHERE")).upper())

        px, py, pz = self._parse_vec3(zone.data.get("pos", "0,0,0"))
        rx, ry, rz = self._parse_vec3(zone.data.get("rotate", "0,0,0"))
        sx, sy, sz = self._parse_vec3(zone.data.get("size", "1000,1000,1000"), (1000.0, 1000.0, 1000.0))

        pos_x = QDoubleSpinBox()
        pos_y = QDoubleSpinBox()
        pos_z = QDoubleSpinBox()
        for spin, val in ((pos_x, px), (pos_y, py), (pos_z, pz)):
            spin.setRange(-10000000.0, 10000000.0)
            spin.setDecimals(2)
            spin.setValue(val)

        size_x = QDoubleSpinBox()
        size_y = QDoubleSpinBox()
        size_z = QDoubleSpinBox()
        for spin, val in ((size_x, sx), (size_y, sy), (size_z, sz)):
            spin.setRange(0.0, 10000000.0)
            spin.setDecimals(2)
            spin.setValue(max(0.0, val))

        rot_x = QDoubleSpinBox()
        rot_y = QDoubleSpinBox()
        rot_z = QDoubleSpinBox()
        for spin, val in ((rot_x, rx), (rot_y, ry), (rot_z, rz)):
            spin.setRange(-360.0, 360.0)
            spin.setDecimals(2)
            spin.setValue(val)

        sort_edit = QLineEdit(str(zone.data.get("sort", "")).strip())
        damage_edit = QLineEdit(str(zone.data.get("damage", "")).strip())

        fl.addRow("Nickname", nick_edit)
        fl.addRow("Ingame Name", ids_name_text_edit)
        fl.addRow("Shape", shape_cb)
        fl.addRow("Pos X", pos_x)
        fl.addRow("Pos Y", pos_y)
        fl.addRow("Pos Z", pos_z)
        fl.addRow("Size X", size_x)
        fl.addRow("Size Y", size_y)
        fl.addRow("Size Z", size_z)
        fl.addRow("Rot X", rot_x)
        fl.addRow("Rot Y", rot_y)
        fl.addRow("Rot Z", rot_z)
        fl.addRow("Sort", sort_edit)
        fl.addRow("Damage", damage_edit)

        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        fl.addRow(bb)

        if dlg.exec() != QDialog.Accepted:
            return

        nick_val = nick_edit.text().strip() or zone.nickname
        shape_val = shape_cb.currentText().strip().upper() or "SPHERE"

        new_map = {
            "nickname": nick_val,
            "shape": shape_val,
            "pos": f"{pos_x.value():.2f}, {pos_y.value():.2f}, {pos_z.value():.2f}",
            "size": f"{size_x.value():.2f}, {size_y.value():.2f}, {size_z.value():.2f}",
            "rotate": f"{rot_x.value():.2f}, {rot_y.value():.2f}, {rot_z.value():.2f}",
            "sort": sort_edit.text().strip(),
            "damage": damage_edit.text().strip(),
        }
        new_ids_name = ids_name_current
        ids_name_new_text = ids_name_text_edit.text().strip()
        if ids_name_new_text and ids_name_new_text != ids_name_display:
            try:
                new_ids_name = self._ensure_ids_name_in_user_dll(ids_name_current, ids_name_new_text)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
                return
        if new_ids_name:
            new_map["ids_name"] = new_ids_name

        entries = list(zone.data.get("_entries", []))
        changed_keys: set[str] = set()
        merged: list[tuple[str, str]] = []
        for k, v in entries:
            lk = k.lower()
            if lk in new_map and lk not in changed_keys:
                nv = new_map[lk]
                if nv:
                    merged.append((k, nv))
                changed_keys.add(lk)
            else:
                merged.append((k, v))
        for lk, nv in new_map.items():
            if lk not in changed_keys and nv:
                merged.append((lk, nv))

        zone.apply_text("\n".join(f"{k} = {v}" for k, v in merged))
        self._sync_zone_section_from_zone(zone)

        self.editor.setPlainText(zone.raw_text())
        self._rebuild_object_combo()
        self._selected = zone
        self._sync_obj_combo_to_selection()
        self.name_lbl.setText(f"📍 {zone.nickname}")

        new_entries = [(str(k), str(v)) for k, v in zone.data.get("_entries", [])]
        if new_entries != old_entries:
            try:
                zone_idx = self._zones.index(zone)
            except ValueError:
                zone_idx = None
            self._push_undo_action(
                {
                    "type": "edit_zone",
                    "label": f"Zone bearbeitet: {zone.nickname}",
                    "filepath": self._filepath or "",
                    "zone_index": zone_idx,
                    "old_nickname": old_nickname,
                    "new_nickname": zone.nickname,
                    "old_entries": [list(p) for p in old_entries],
                    "new_entries": [list(p) for p in new_entries],
                }
            )
            self._append_change_log(f"Zone bearbeitet: {old_nickname} -> {zone.nickname}")
        self._set_dirty(True)
        self._refresh_3d_scene(preserve_camera=True)
        self.statusBar().showMessage(tr("status.changes_applied").format(nickname=zone.nickname))

    def _hide_zone_extra_editors(self):
        self.zone_link_lbl.setVisible(False)
        self.zone_link_editor.setVisible(False)
        self.zone_file_lbl.setVisible(False)
        self.zone_file_editor.setVisible(False)
        self.zone_link_editor.clear()
        self.zone_file_editor.clear()
        self._zone_link_section_index = None
        self._zone_link_section_name = None
        self._zone_link_file_path = None

    def _show_zone_extra_editors(self, zone: ZoneItem):
        game_path = self._primary_game_path()
        if not game_path:
            self._hide_zone_extra_editors()
            return
        zone_nick = zone.nickname.strip().lower()
        match_idx = match_sec_name = match_entries = None
        for idx, (sec_name, entries) in enumerate(self._sections):
            if sec_name.lower() not in ("nebula", "asteroids"):
                continue
            zone_val = ""
            for k, v in entries:
                if k.lower() == "zone":
                    zone_val = v.strip().lower()
                    break
            if zone_val == zone_nick:
                match_idx, match_sec_name, match_entries = idx, sec_name, entries
                break
        if match_idx is None or match_entries is None or match_sec_name is None:
            self._hide_zone_extra_editors()
            return
        file_rel = ""
        for k, v in match_entries:
            if k.lower() == "file":
                file_rel = v.strip()
                break
        if not file_rel:
            self._hide_zone_extra_editors()
            return
        linked_file = self._resolve_game_path_case_insensitive(game_path, file_rel)
        if not linked_file:
            self._hide_zone_extra_editors()
            return
        self._zone_link_section_index = match_idx
        self._zone_link_section_name = match_sec_name
        self._zone_link_file_path = linked_file
        self.zone_link_lbl.setVisible(True)
        self.zone_link_editor.setVisible(True)
        self.zone_file_lbl.setVisible(True)
        self.zone_file_editor.setVisible(True)
        self.zone_link_editor.setPlainText(
            self._entries_to_text(match_sec_name, match_entries)
        )
        self.zone_file_lbl.setText(tr("lbl.zone_file_value").format(file=file_rel))
        try:
            self.zone_file_editor.setPlainText(
                self._read_text_best_effort(linked_file)
            )
        except Exception as ex:
            self.zone_file_editor.setPlainText(tr("lbl.zone_file_error").format(error=ex))

    @staticmethod
    def _entries_to_text(section_name: str, entries: list[tuple[str, str]]) -> str:
        lines = [f"[{section_name}]"]
        for k, v in entries:
            lines.append(f"{k} = {v}")
        return "\n".join(lines)

    @staticmethod
    def _text_to_section_entries(text: str, default_section: str) -> tuple[str, list[tuple[str, str]]]:
        sec_name = default_section
        entries: list[tuple[str, str]] = []
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line.startswith(";") or line.startswith("//"):
                continue
            if line.startswith("[") and line.endswith("]"):
                sec_name = line[1:-1].strip() or default_section
                continue
            if "=" in line:
                k, _, v = line.partition("=")
                entries.append((k.strip(), v.strip()))
        return sec_name, entries

    # ==================================================================
    #  Objekt/Zonen Combo
    # ==================================================================
    def _selected_has_base_reference(self) -> bool:
        obj = self._selected
        if not isinstance(obj, SolarObject):
            return False
        entries = list(obj.data.get("_entries", []))
        for k, v in entries:
            kl = str(k).strip().lower()
            if kl in ("base", "dock_with") and str(v).strip():
                return True
        return False

    def _selected_can_open_base_builder(self) -> bool:
        obj = self._selected
        if not isinstance(obj, SolarObject):
            return False
        return bool(self._base_nickname_for_object(obj))

    def _system_has_tradelanes(self) -> bool:
        return system_has_tradelanes(self._objects)

    def _refresh_editing_action_states(self):
        if not hasattr(self, "edit_tradelane_btn"):
            return
        state = build_editing_action_state(
            locked=bool(getattr(self, "_flight_lock_active", False)),
            has_system=bool(self._filepath),
            has_tradelanes=bool(self._filepath) and self._system_has_tradelanes(),
            is_zone_selected=isinstance(self._selected, ZoneItem),
            has_base_selected=self._selected_has_base_reference(),
        )

        self.edit_tradelane_btn.setEnabled(bool(state["edit_tradelane_enabled"]))
        self.edit_zone_pop_btn.setEnabled(bool(state["edit_zone_pop_enabled"]))
        self.edit_base_btn.setEnabled(bool(state["edit_base_enabled"]))
        if hasattr(self, "base_builder_btn"):
            self.base_builder_btn.setEnabled(
                bool(self._selected_can_open_base_builder() and not getattr(self, "_flight_lock_active", False))
            )
        if hasattr(self, "open_system_ini_btn"):
            self.open_system_ini_btn.setEnabled(bool(state["open_system_ini_enabled"]))

    def _rebuild_object_combo(self):
        self.obj_combo.blockSignals(True)
        self.obj_combo.clear()
        for label, item in build_object_combo_rows(
            self._object_combo_display_objects(),
            self._zones,
            object_label=self._object_combo_display_label,
            no_items_label=tr("lbl.no_items"),
        ):
            self.obj_combo.addItem(label, item)
            if isinstance(item, SolarObject):
                tooltip = self._object_combo_tooltip(item)
                if tooltip:
                    self.obj_combo.setItemData(self.obj_combo.count() - 1, tooltip, Qt.ToolTipRole)
        self.obj_combo.blockSignals(False)
        self._refresh_editing_action_states()

    def _sync_obj_combo_to_selection(self):
        items = [self.obj_combo.itemData(i) for i in range(self.obj_combo.count())]
        selected_item = self._base_display_root_object(self._selected) if isinstance(self._selected, SolarObject) else self._selected
        index = object_combo_selected_index(items, selected_item)
        self.obj_combo.blockSignals(True)
        self.obj_combo.setCurrentIndex(index)
        self.obj_combo.blockSignals(False)

    def _on_obj_combo_changed(self, index):
        items = [self.obj_combo.itemData(i) for i in range(self.obj_combo.count())]
        item = object_combo_item_at_index(items, index)
        if item is None:
            return
        if isinstance(item, ZoneItem):
            self._select_zone(item)
        elif isinstance(item, SolarObject):
            self._select(item)

    def _jump_to_selected_from_combo(self):
        items = [self.obj_combo.itemData(i) for i in range(self.obj_combo.count())]
        item = object_combo_item_at_index(items, self.obj_combo.currentIndex())
        if item is None:
            return
        if isinstance(item, ZoneItem):
            self._select_zone(item)
        else:
            self._select(item)
        try:
            self.view.centerOn(item)
        except Exception:
            pass
        try:
            self._jump_view3d_to_item_preserving_camera(item)
        except Exception:
            pass
        name = getattr(item, "nickname", tr("type.selection"))
        self.statusBar().showMessage(tr("status.centered").format(name=name))

    @staticmethod
    def _normalize_angle_180(val: float) -> float:
        return normalize_angle_180(val)

    def _get_object_rotate(self, obj: SolarObject) -> tuple[float, float, float]:
        return parse_object_rotate(str(obj.data.get("rotate", "0,0,0")))

    def _set_object_rotate(self, obj: SolarObject, rot_xyz: tuple[float, float, float]):
        entries, rotate_str = apply_object_rotate_entries(list(obj.data.get("_entries", [])), rot_xyz)
        obj.data["_entries"] = entries
        obj.data["rotate"] = rotate_str
        try:
            if hasattr(obj, "_apply_rotation_from_data"):
                obj._apply_rotation_from_data()
            else:
                obj.setRotation(-parse_object_rotate(rotate_str)[1])
        except Exception:
            pass
        if self._selected is obj:
            self.editor.setPlainText(obj.raw_text())

    def _rotate_selected_object(self, delta: float, axis: int = 1):
        obj = self._selected
        if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
            return
        rx, ry, rz = self._get_object_rotate(obj)
        rot = [rx, ry, rz]
        axis_idx = max(0, min(2, int(axis)))
        rot[axis_idx] = self._normalize_angle_180(rot[axis_idx] + float(delta))
        self._set_object_rotate(obj, (rot[0], rot[1], rot[2]))
        self._set_dirty(True)
        if hasattr(self, "view3d") and hasattr(self.view3d, "update_object_rotation"):
            self.view3d.update_object_rotation(obj)
        axis_name = ("X", "Y", "Z")[axis_idx]
        self.statusBar().showMessage(f"Rotation {axis_name}: {rot[axis_idx]:.0f}°")

    def _jump_to_linked_system(self, obj: SolarObject, new_tab: bool = False):
        dest = goto_destination_nickname(obj.data.get("goto", ""))
        if not dest:
            self.statusBar().showMessage(tr("status.goto_missing"))
            return
        game_path = self._primary_game_path()
        if not game_path:
            return
        try:
            dest_path = linked_system_path(self._find_all_systems(game_path), dest)
        except Exception:
            dest_path = None
        if not dest_path:
            self.statusBar().showMessage(tr("status.goto_not_found").format(dest=dest))
            return
        self._open_system_tab(dest_path, new_tab=new_tab)

    def _open_info_editor_with_id(self, ids_info: int):
        ids_val = safe_int(ids_info)
        if ids_val <= 0:
            QMessageBox.information(self, tr("msg.error"), tr("msg.infocard_no_ids_info"))
            return
        self._open_name_editor_view()
        self._set_name_editor_sub_view("info")
        if hasattr(self, "info_search_edit"):
            self.info_search_edit.setText(str(ids_val))
        if hasattr(self, "info_ids_table"):
            tbl = self.info_ids_table
            rows = []
            for r in range(tbl.rowCount()):
                it = tbl.item(r, 0)
                rows.append(it.data(Qt.UserRole) if it is not None else None)
            row_index = find_info_editor_row_index(rows, ids_val)
            if row_index is not None:
                tbl.selectRow(row_index)
        self.statusBar().showMessage(tr("status.infocard_opened").format(ids=ids_val))

    def _ensure_universe_sections_for_edit(self) -> bool:
        ok, uni_path, sections = ensure_universe_sections_for_edit(
            self._uni_sections,
            self._uni_ini_path,
            primary_game_path=self._primary_game_path(),
            find_universe_ini_read=self._find_universe_ini_read,
            parse_sections=self._parser.parse,
        )
        if ok:
            self._uni_ini_path = Path(uni_path) if uni_path is not None else None
            self._uni_sections = sections
        return ok

    def _find_universe_system_section_index(self, system_nickname: str) -> int | None:
        return find_universe_system_section_index(
            self._uni_sections,
            system_nickname,
            entry_get_value=self._entry_get_value,
        )

    def _write_universe_sections(self) -> bool:
        try:
            ok, uni_path = write_universe_sections(
                self._uni_ini_path,
                self._uni_sections,
                ensure_writable_path=self._ensure_writable_path,
                write_sections_to_file=self._write_sections_to_file,
            )
            if ok:
                self._uni_ini_path = Path(uni_path) if uni_path is not None else None
            return ok
        except Exception:
            return False

    @staticmethod
    def _safe_int(raw: str | int | None) -> int:
        return safe_int(raw)

    def _edit_infocard_for_scene_object(self, obj: SolarObject):
        if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
            return
        ids_info = self._safe_int(obj.data.get("ids_info"))
        if ids_info <= 0:
            ans = QMessageBox.question(
                self,
                tr("ctx.edit_infocard"),
                tr("msg.infocard_object_no_ids_info_create"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes,
            )
            if ans == QMessageBox.Yes:
                self._create_infocard_for_scene_object(obj)
            return
        self._open_info_editor_with_id(ids_info)

    def _edit_infocard_for_scene_zone(self, zone: ZoneItem):
        if not isinstance(zone, ZoneItem):
            return
        ids_info = self._safe_int(zone.data.get("ids_info"))
        if ids_info <= 0:
            ans = QMessageBox.question(
                self,
                tr("ctx.edit_infocard"),
                tr("msg.infocard_zone_no_ids_info_create"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes,
            )
            if ans == QMessageBox.Yes:
                self._create_infocard_for_scene_zone(zone)
            return
        self._open_info_editor_with_id(ids_info)

    def _default_scene_infocard_xml(self, title: str) -> str:
        return default_scene_infocard_xml(title, tr("info.xml.placeholder.desc"))

    def _run_infocard_create_dialog(self, window_title: str, intro_text: str, initial_xml: str) -> str | None:
        dlg = QDialog(self)
        dlg.setWindowTitle(window_title)
        dlg.resize(900, 680)
        root = QVBoxLayout(dlg)
        info_lbl = QLabel(intro_text)
        info_lbl.setWordWrap(True)
        root.addWidget(info_lbl)
        split = QSplitter(Qt.Vertical)
        root.addWidget(split, 1)
        xml_edit = QTextEdit()
        xml_edit.setAcceptRichText(False)
        xml_edit.setPlainText(initial_xml)
        split.addWidget(xml_edit)
        preview = QTextEdit()
        preview.setReadOnly(True)
        split.addWidget(preview)
        split.setSizes([360, 260])
        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        ok_btn = bb.button(QDialogButtonBox.Ok)
        if ok_btn is not None:
            ok_btn.setText(tr("btn.create_assign"))
        root.addWidget(bb)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)

        def _refresh_preview():
            raw = xml_edit.toPlainText().strip()
            if ok_btn is not None:
                ok_btn.setEnabled(False)
            if not raw:
                preview.clear()
                preview.setStyleSheet("border: 2px solid #b04040;")
                return
            valid, payload = validate_infocard_xml(raw)
            if valid:
                preview.setHtml(self._render_infocard_xml_to_html(payload))
                preview.setStyleSheet("")
                if ok_btn is not None:
                    ok_btn.setEnabled(True)
                return
            preview.setPlainText(str(payload))
            preview.setStyleSheet("border: 2px solid #b04040;")

        xml_edit.textChanged.connect(_refresh_preview)
        _refresh_preview()

        if dlg.exec() != QDialog.Accepted:
            return None
        valid, payload = validate_infocard_xml(xml_edit.toPlainText())
        if not valid and not payload:
            return None
        if not valid:
            QMessageBox.warning(self, tr("info.msg.invalid_xml.title"), tr("info.msg.invalid_xml.text").format(error=payload))
            return None
        return payload

    def _assign_infocard_to_scene_item(self, item: SolarObject | ZoneItem, ids_info: str) -> bool:
        if not isinstance(item, (SolarObject, ZoneItem)):
            return False
        entries, ids_value = assign_ids_info_entry(
            item.data.get("_entries", []),
            ids_info,
            entry_set=self._entry_set,
        )
        item.data["_entries"] = entries
        item.data["ids_info"] = ids_value
        if item is self._selected:
            self.editor.setPlainText(self._format_entries(entries))
        self._set_dirty(True)
        self._write_to_file(reload=False)
        return True

    def _create_infocard_for_scene_object(self, obj: SolarObject):
        if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
            return
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return

        obj_name = self._object_display_label(obj)
        xml_text = self._run_infocard_create_dialog(
            tr("dlg.object_infocard_create").format(name=obj_name),
            tr("msg.object_infocard_create_intro"),
            self._default_scene_infocard_xml(obj_name),
        )
        if not xml_text:
            return
        try:
            new_gid = self._ensure_ids_info_in_user_dll("0", xml_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return

        if not self._assign_infocard_to_scene_item(obj, str(new_gid)):
            return
        self.statusBar().showMessage(tr("status.object_infocard_saved").format(ids=new_gid))
        self._append_change_log(f"Objekt-Infocard erstellt: {obj.nickname} -> ids_info {new_gid}")
        self._open_info_editor_with_id(self._safe_int(new_gid))

    def _create_infocard_for_scene_zone(self, zone: ZoneItem):
        if not isinstance(zone, ZoneItem):
            return
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return

        zone_name = str(getattr(zone, "nickname", "") or "Zone").strip() or "Zone"
        xml_text = self._run_infocard_create_dialog(
            tr("dlg.zone_infocard_create").format(name=zone_name),
            tr("msg.zone_infocard_create_intro"),
            self._default_scene_infocard_xml(zone_name),
        )
        if not xml_text:
            return
        try:
            new_gid = self._ensure_ids_info_in_user_dll("0", xml_text)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return

        if not self._assign_infocard_to_scene_item(zone, str(new_gid)):
            return
        self.statusBar().showMessage(tr("status.zone_infocard_saved").format(ids=new_gid))
        self._append_change_log(f"Zone-Infocard erstellt: {zone_name} -> ids_info {new_gid}")
        self._open_info_editor_with_id(self._safe_int(new_gid))

    def _edit_infocard_for_universe_system(self, sys_item: SolarObject):
        if not isinstance(sys_item, SolarObject) or not hasattr(sys_item, "sys_path"):
            return
        if not self._ensure_universe_sections_for_edit():
            QMessageBox.warning(self, tr("msg.error"), tr("msg.universe_not_found"))
            return
        idx = self._find_universe_system_section_index(sys_item.nickname)
        if idx is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.system_not_found").format(nickname=sys_item.nickname))
            return
        ids_info = universe_system_ids_info(
            self._uni_sections,
            sys_item.nickname,
            entry_get_value=self._entry_get_value,
            safe_int=self._safe_int,
        )
        if ids_info <= 0:
            ans = QMessageBox.question(
                self,
                tr("ctx.edit_infocard"),
                tr("msg.infocard_system_no_ids_info_generate"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes,
            )
            if ans == QMessageBox.Yes:
                self._open_system_infocard_generator(sys_item.nickname)
            return
        self._open_info_editor_with_id(ids_info)

    def _generate_system_infocard_draft_xml(self, system_nickname: str) -> str:
        sys_nick = str(system_nickname or "").strip().upper()
        sys_name = self._system_display_name(sys_nick)
        game_path = self._primary_game_path()
        system_path = ""
        if game_path:
            for s in self._find_all_systems(game_path):
                if str(s.get("nickname", "")).strip().upper() == sys_nick:
                    system_path = str(s.get("path", "") or "")
                    break

        object_count = 0
        zone_count = 0
        star_count = 0
        nebula_count = 0
        asteroid_count = 0
        jump_targets: set[str] = set()
        local_faction = ""
        planet_names: list[str] = []
        base_names: list[str] = []

        base_ids_from_universe: dict[str, str] = {}
        try:
            if self._uni_sections:
                base_ids_from_universe = collect_base_ids_from_universe_sections(
                    self._uni_sections,
                    entry_get_value=self._entry_get_value,
                )
        except Exception:
            pass

        if system_path:
            try:
                sections = self._parser.parse(system_path)
            except Exception:
                sections = []
            for sec_name, entries in sections:
                low = sec_name.lower()
                if low == "object":
                    object_count += 1
                    arch = self._entry_get_value(entries, "archetype").lower()
                    nick = self._entry_get_value(entries, "nickname").strip()
                    ids_name_val = self._entry_get_value(entries, "ids_name").strip()
                    display_name = self._display_name_from_ids_name(ids_name_val) if ids_name_val else ""
                    if not display_name:
                        display_name = nick
                    if "sun" in arch:
                        star_count += 1
                    if "planet" in arch:
                        if display_name:
                            planet_names.append(display_name)
                    base_nick = self._entry_get_value(entries, "base").strip()
                    if base_nick:
                        base_ids = ids_name_val or base_ids_from_universe.get(base_nick.lower(), "")
                        bn_disp = self._base_display_name(base_nick, base_ids)
                        if bn_disp:
                            base_names.append(bn_disp)
                    jump_kind = classify_jump_connection_kind(
                        archetype=arch,
                        msg_id_prefix=self._entry_get_value(entries, "msg_id_prefix"),
                        reputation=self._entry_get_value(entries, "reputation"),
                        jump_effect=self._entry_get_value(entries, "jump_effect"),
                        goto_value=self._entry_get_value(entries, "goto"),
                    )
                    if jump_kind in ("gate", "hole", "alien_gate"):
                        dest = self._entry_get_value(entries, "goto").split(",")[0].strip().upper()
                        if dest and dest != sys_nick:
                            jump_targets.add(dest)
                elif low == "zone":
                    zone_count += 1
                elif low == "nebula":
                    nebula_count += 1
                elif low == "asteroids":
                    asteroid_count += 1
                elif low == "systeminfo":
                    local_faction = self._entry_get_value(entries, "local_faction")

        dest_names = [self._system_display_name(d) for d in sorted(jump_targets)]
        planet_names = sorted({str(n).strip() for n in planet_names if str(n).strip()}, key=str.lower)
        base_names = sorted({str(n).strip() for n in base_names if str(n).strip()}, key=str.lower)
        local_faction_disp = self._faction_ui_label(local_faction) if local_faction else ""
        lang = str(get_language() or "en").strip().lower()
        return build_system_infocard_draft_xml(
            sys_name=sys_name,
            lang=lang,
            object_count=object_count,
            zone_count=zone_count,
            star_count=star_count,
            nebula_count=nebula_count,
            asteroid_count=asteroid_count,
            dest_names=dest_names,
            local_faction_disp=local_faction_disp,
            base_names=base_names,
            planet_names=planet_names,
        )

    def _open_system_infocard_generator(self, system_nickname: str):
        sys_nick = str(system_nickname or "").strip().upper()
        if not sys_nick:
            return
        if not self._ensure_universe_sections_for_edit():
            QMessageBox.warning(self, tr("msg.error"), tr("msg.universe_not_found"))
            return
        idx = self._find_universe_system_section_index(sys_nick)
        if idx is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.system_not_found").format(nickname=sys_nick))
            return
        sec_name, entries = self._uni_sections[idx]
        old_ids_info = self._safe_int(self._entry_get_value(entries, "ids_info"))
        initial_xml = self._generate_system_infocard_draft_xml(sys_nick)

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("dlg.system_infocard_generator").format(system=self._system_display_name(sys_nick)))
        dlg.resize(950, 720)
        root = QVBoxLayout(dlg)
        info_lbl = QLabel(tr("msg.system_infocard_generator_intro"))
        info_lbl.setWordWrap(True)
        root.addWidget(info_lbl)
        split = QSplitter(Qt.Vertical)
        root.addWidget(split, 1)
        xml_edit = QTextEdit()
        xml_edit.setAcceptRichText(False)
        xml_edit.setPlainText(initial_xml)
        split.addWidget(xml_edit)
        preview = QTextEdit()
        preview.setReadOnly(True)
        split.addWidget(preview)
        split.setSizes([380, 260])
        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        ok_btn = bb.button(QDialogButtonBox.Ok)
        if ok_btn is not None:
            ok_btn.setText(tr("btn.use_draft"))
        root.addWidget(bb)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)

        def _refresh_preview():
            raw = xml_edit.toPlainText().strip()
            if ok_btn is not None:
                ok_btn.setEnabled(False)
            if not raw:
                preview.clear()
                preview.setStyleSheet("border: 2px solid #b04040;")
                return
            valid, payload = validate_infocard_xml(raw)
            if valid:
                preview.setHtml(self._render_infocard_xml_to_html(payload))
                preview.setStyleSheet("")
                if ok_btn is not None:
                    ok_btn.setEnabled(True)
                return
            preview.setPlainText(str(payload))
            preview.setStyleSheet("border: 2px solid #b04040;")

        xml_edit.textChanged.connect(_refresh_preview)
        _refresh_preview()

        if dlg.exec() != QDialog.Accepted:
            return
        valid, payload = validate_infocard_xml(xml_edit.toPlainText())
        if not valid and not payload:
            return
        if not valid:
            QMessageBox.warning(self, tr("info.msg.invalid_xml.title"), tr("info.msg.invalid_xml.text").format(error=payload))
            return
        try:
            new_gid = self._ensure_ids_info_in_user_dll(str(old_ids_info), payload)
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))
            return
        self._uni_sections, entries = assign_universe_system_ids_info(
            self._uni_sections,
            idx,
            str(new_gid),
            entry_set=self._entry_set,
        )
        if not self._write_universe_sections():
            QMessageBox.warning(self, tr("msg.save_error"), tr("msg.error"))
            return
        if should_refresh_universe_system_editor(self._uni_selected_nick, sys_nick):
            self._show_uni_system_editor(sys_nick)
        self.statusBar().showMessage(tr("status.system_infocard_saved").format(ids=new_gid))
        self._append_change_log(f"System-Infocard gespeichert: {sys_nick} -> ids_info {new_gid}")
        self._open_info_editor_with_id(self._safe_int(new_gid))

    def _clear_measure_line(self):
        if self._measure_line is not None:
            try:
                self.view._scene.removeItem(self._measure_line)
            except Exception:
                pass
            self._measure_line = None
        if self._measure_label is not None:
            try:
                self.view._scene.removeItem(self._measure_label)
            except Exception:
                pass
            self._measure_label = None
        self._measure_start = None
        if not self._has_pending_placement():
            self._set_placement_mode(False)

    def _start_measure_from(self, pos: QPointF):
        if self._filepath is None:
            return
        self._clear_measure_line()
        self._measure_start = QPointF(pos.x(), pos.y())
        self._set_placement_mode(True, tr("placement.measure"))
        self.statusBar().showMessage(tr("status.measure_start"))

    def _finish_measure_to(self, pos: QPointF):
        if self._measure_start is None:
            return
        p0 = self._measure_start
        p1 = QPointF(pos.x(), pos.y())
        pen = QPen(self._scene_role_color("measure", 220), 2, Qt.DashLine)
        self._measure_line = self.view._scene.addLine(p0.x(), p0.y(), p1.x(), p1.y(), pen)
        self._measure_line.setZValue(9997)
        dist_km = (
            math.hypot(p1.x() - p0.x(), p1.y() - p0.y())
            / max(self._scale, 1e-9)
            / 1000.0
        )
        mid = QPointF((p0.x() + p1.x()) * 0.5, (p0.y() + p1.y()) * 0.5)
        self._measure_label = self.view._scene.addText(f"{dist_km:,.2f} km".replace(",", "."))
        self._measure_label.setDefaultTextColor(self._scene_role_color("measure"))
        self._measure_label.setPos(mid.x() + 6, mid.y() + 6)
        self._measure_label.setZValue(9998)
        self._measure_start = None
        if not self._has_pending_placement():
            self._set_placement_mode(False)
        dist_text = f"{dist_km:,.2f}".replace(",", ".")
        self.statusBar().showMessage(tr("status.measure_distance").format(distance=dist_text))

    def _on_view_context_menu(self, scene_pos: QPointF, item):
        from PySide6.QtWidgets import QMenu

        zones_at_pos = self._zones_at_scene_pos(scene_pos)
        selected_zone_for_menu = zones_at_pos[0] if zones_at_pos else None

        if isinstance(item, ZoneItem) and len(zones_at_pos) <= 1:
            self._select_zone(item)
        elif isinstance(item, SolarObject):
            self._select(item)

        menu = QMenu(self)
        if len(zones_at_pos) > 1:
            pick_zone_menu = menu.addMenu("Zone auswählen")
            for zone in zones_at_pos:
                act_pick = pick_zone_menu.addAction(zone.nickname)
                act_pick.setCheckable(True)
                act_pick.setChecked(self._selected is zone)
                act_pick.triggered.connect(
                    lambda checked=False, z=zone: self._select_zone(z)
                )
            menu.addSeparator()

        if isinstance(item, SolarObject) and hasattr(item, "sys_path"):
            act_open = menu.addAction(tr("ctx.open_system"))
            act_open.triggered.connect(lambda checked=False, p=item.sys_path: self._load_from_browser(p))
            act_open_new_tab = menu.addAction(tr("ctx.open_system_new_tab"))
            act_open_new_tab.triggered.connect(lambda checked=False, p=item.sys_path: self._open_system_tab(p, new_tab=True))
            act_info = menu.addAction(tr("ctx.edit_infocard"))
            act_info.triggered.connect(lambda checked=False, o=item: self._edit_infocard_for_universe_system(o))
            act_info_draft = menu.addAction(tr("ctx.generate_system_infocard"))
            act_info_draft.triggered.connect(lambda checked=False, o=item: self._open_system_infocard_generator(o.nickname))
            if self._filepath is None:
                act_del_sys = menu.addAction(tr("ctx.delete_system"))
                act_del_sys.triggered.connect(lambda checked=False, o=item: self._delete_universe_system(o))
        elif isinstance(item, ZoneItem):
            zone_entries = list(item.data.get("_entries", []))
            if self._entry_has_key(zone_entries, "ids_name"):
                act_edit = menu.addAction(tr("ctx.edit_zone"))
                act_edit.triggered.connect(self._start_object_edit)
            act_edit_info = menu.addAction(tr("ctx.edit_infocard"))
            act_edit_info.triggered.connect(lambda checked=False, z=item: self._edit_infocard_for_scene_zone(z))
            act_del = menu.addAction(tr("ctx.delete_zone"))
            act_del.triggered.connect(self._delete_object)
        elif isinstance(item, SolarObject):
            obj_entries = list(item.data.get("_entries", []))
            if self._entry_has_key(obj_entries, "ids_name"):
                act_edit_obj = menu.addAction(tr("btn.edit_object"))
                act_edit_obj.triggered.connect(self._start_object_edit)
            act_edit_info = menu.addAction(tr("ctx.edit_infocard"))
            act_edit_info.triggered.connect(lambda checked=False, o=item: self._edit_infocard_for_scene_object(o))
            base_nick = ""
            for k, v in obj_entries:
                kl = str(k).strip().lower()
                if kl == "base" and str(v).strip():
                    base_nick = str(v).strip()
                    break
            if not base_nick:
                for k, v in obj_entries:
                    if str(k).strip().lower() == "dock_with" and str(v).strip():
                        base_nick = str(v).strip()
                        break
            if base_nick:
                act_create_npc = menu.addAction(tr("ctx.create_npc"))
                act_create_npc.triggered.connect(
                    lambda checked=False, b=base_nick: self._open_npc_editor(b)
                )
                act_base_builder = menu.addAction(tr("ctx.base_builder"))
                act_base_builder.triggered.connect(
                    lambda checked=False, o=item: self._open_base_builder_for_object(o)
                )
            act_rot_l = menu.addAction(tr("ctx.rotate_y_neg"))
            act_rot_l.triggered.connect(lambda: self._rotate_selected_object(-15.0, axis=1))
            act_rot_r = menu.addAction(tr("ctx.rotate_y_pos"))
            act_rot_r.triggered.connect(lambda: self._rotate_selected_object(15.0, axis=1))
            arch = item.data.get("archetype", "").lower()
            jump_kind = classify_jump_connection_kind(
                archetype=arch,
                msg_id_prefix=item.data.get("msg_id_prefix", ""),
                reputation=item.data.get("reputation", ""),
                jump_effect=item.data.get("jump_effect", ""),
                goto_value=item.data.get("goto", ""),
            )
            if jump_kind in ("gate", "hole", "alien_gate"):
                act_jump = menu.addAction(tr("ctx.jump_target"))
                act_jump.triggered.connect(lambda checked=False, o=item: self._jump_to_linked_system(o))
                act_jump_new_tab = menu.addAction(tr("ctx.jump_target_new_tab"))
                act_jump_new_tab.triggered.connect(lambda checked=False, o=item: self._jump_to_linked_system(o, new_tab=True))
            act_del = menu.addAction(tr("ctx.delete_object"))
            act_del.triggered.connect(self._delete_object)
        elif selected_zone_for_menu is not None:
            zone_entries = list(selected_zone_for_menu.data.get("_entries", []))
            if self._entry_has_key(zone_entries, "ids_name"):
                act_edit_zone = menu.addAction(tr("ctx.edit_zone"))
                act_edit_zone.triggered.connect(
                    lambda checked=False, z=selected_zone_for_menu: self._select_zone(z)
                )
                act_edit_zone.triggered.connect(self._start_object_edit)
            act_edit_zone_info = menu.addAction(tr("ctx.edit_infocard"))
            act_edit_zone_info.triggered.connect(
                lambda checked=False, z=selected_zone_for_menu: self._edit_infocard_for_scene_zone(z)
            )
            act_del_zone = menu.addAction(tr("ctx.delete_zone"))
            act_del_zone.triggered.connect(
                lambda checked=False, z=selected_zone_for_menu: self._select_zone(z)
            )
            act_del_zone.triggered.connect(self._delete_object)
        elif self._filepath is None and item is None:
            act_new_system = menu.addAction(tr("btn.new_system"))
            act_new_system.triggered.connect(self._start_new_system)

        if self._filepath is not None:
            menu.addSeparator()
            if self._measure_start is None:
                act_m0 = menu.addAction(tr("ctx.measure_start"))
                act_m0.triggered.connect(lambda checked=False, p=QPointF(scene_pos.x(), scene_pos.y()): self._start_measure_from(p))
                if self._measure_line is not None:
                    act_md = menu.addAction(tr("ctx.measure_clear"))
                    act_md.triggered.connect(self._clear_measure_line)
            else:
                act_m1 = menu.addAction(tr("ctx.measure_end"))
                act_m1.triggered.connect(lambda checked=False, p=QPointF(scene_pos.x(), scene_pos.y()): self._finish_measure_to(p))
                act_mc = menu.addAction(tr("ctx.measure_cancel"))
                act_mc.triggered.connect(self._clear_measure_line)
            if self._selected is not None or self._multi_selected:
                menu.addSeparator()
                act_sc = menu.addAction(tr("ctx.clear_selection"))
                act_sc.triggered.connect(self._cancel_selection)

        if not menu.actions():
            return
        global_pos = self.view.mapToGlobal(self.view.mapFromScene(scene_pos))
        menu.exec(global_pos)

    def _on_view3d_context_menu(self, item, global_pos):
        from PySide6.QtWidgets import QMenu

        if item is None:
            return
        if isinstance(item, ZoneItem):
            self._select_zone(item)
        elif isinstance(item, SolarObject):
            self._select(item)

        menu = QMenu(self)
        if isinstance(item, (SolarObject, ZoneItem)):
            act_jump = menu.addAction(tr("ctx.jump_to_object"))
            act_jump.triggered.connect(lambda checked=False, it=item: self._jump_view3d_to_item_preserving_camera(it))
        if self._selected is not None or self._multi_selected:
            menu.addSeparator()
            act_clear = menu.addAction(tr("ctx.clear_selection"))
            act_clear.triggered.connect(self._cancel_selection)
        if not menu.actions():
            return
        menu.exec(global_pos)

    def _zones_at_scene_pos(self, scene_pos: QPointF) -> list[ZoneItem]:
        zones: list[ZoneItem] = []
        seen: set[int] = set()
        for it in self.view._scene.items(scene_pos):
            cur = it
            if isinstance(cur, QGraphicsTextItem):
                cur = cur.parentItem()
            if isinstance(cur, ZoneItem):
                zone_id = id(cur)
                if zone_id in seen:
                    continue
                seen.add(zone_id)
                zones.append(cur)
        return zones

    def _delete_selected_universe_system(self):
        if self._filepath is not None:
            return
        if isinstance(self._selected, SolarObject) and hasattr(self._selected, "sys_path"):
            self._delete_universe_system(self._selected)

    def _delete_universe_system(self, sys_item: SolarObject):
        if self._filepath is not None:
            return
        if not hasattr(sys_item, "sys_path"):
            return
        sys_nick = getattr(sys_item, "nickname", "").strip()
        sys_disp = self._system_display_name(sys_nick)
        sys_path = getattr(sys_item, "sys_path", "")
        if not sys_nick or not sys_path or not self._uni_ini_path:
            return
        ans = QMessageBox.warning(
            self,
            tr("msg.delete_system_title"),
            tr("msg.delete_system_text").format(nickname=sys_disp),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if ans != QMessageBox.Yes:
            return

        kept_sections: list[tuple[str, list[tuple[str, str]]]] = []
        removed = False
        for sec_name, entries in self._uni_sections:
            if sec_name.lower() != "system":
                kept_sections.append((sec_name, entries))
                continue
            nick_val = ""
            for k, v in entries:
                if k.lower() == "nickname":
                    nick_val = v.strip()
                    break
            if nick_val.upper() == sys_nick.upper():
                removed = True
                continue
            kept_sections.append((sec_name, entries))
        if not removed:
            return

        write_sections_to_file(self._uni_ini_path, kept_sections)

        removed_links = self._remove_jump_objects_targeting_system(sys_nick, sys_path)

        try:
            p = Path(sys_path)
            if p.exists():
                p.unlink()
            parent = p.parent
            if parent.exists() and not any(parent.iterdir()):
                parent.rmdir()
        except Exception:
            pass

        self._uni_sections = kept_sections
        game_path = self._primary_game_path()
        if game_path:
            self._load_universe(game_path)
        self.statusBar().showMessage(
            tr("status.system_deleted_with_links").format(
                nickname=sys_nick,
                count=removed_links,
            )
        )

    def _remove_jump_objects_targeting_system(self, deleted_system_nick: str, deleted_sys_path: str) -> int:
        game_path = self._primary_game_path()
        if not game_path:
            return 0
        deleted_upper = deleted_system_nick.upper()
        deleted_path = str(Path(deleted_sys_path).resolve())
        removed_total = 0
        try:
            systems = self._find_all_systems(game_path)
        except Exception:
            return 0

        for sys_ in systems:
            path = sys_.get("path", "")
            if not path:
                continue
            try:
                if str(Path(path).resolve()) == deleted_path:
                    continue
                sections = self._parser.parse(path)
            except Exception:
                continue
            new_sections: list[tuple[str, list[tuple[str, str]]]] = []
            changed = False
            for sec_name, entries in sections:
                if sec_name.lower() != "object":
                    new_sections.append((sec_name, entries))
                    continue
                data = {}
                for k, v in entries:
                    lk = k.lower()
                    if lk not in data:
                        data[lk] = v
                jump_kind = classify_jump_connection_kind(
                    archetype=data.get("archetype", ""),
                    msg_id_prefix=data.get("msg_id_prefix", ""),
                    reputation=data.get("reputation", ""),
                    jump_effect=data.get("jump_effect", ""),
                    goto_value=data.get("goto", ""),
                )
                if jump_kind not in ("gate", "hole", "alien_gate"):
                    new_sections.append((sec_name, entries))
                    continue
                goto_val = str(data.get("goto", "")).strip()
                target = ""
                if goto_val:
                    toks = [t.strip() for t in goto_val.split(",") if t.strip()]
                    if toks:
                        target = toks[0].upper()
                if target == deleted_upper:
                    changed = True
                    removed_total += 1
                    continue
                new_sections.append((sec_name, entries))
            if not changed:
                continue
            try:
                write_sections_to_file(path, new_sections)
            except Exception:
                pass
        return removed_total

