    #  Erstellen  (Objekt, Zone, Sonne, Planet, Jump)
    # ==================================================================
    def _create_new_object(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        self._pending_new_object = True
        self.statusBar().showMessage(tr("status.click_place_object"))
        self._set_placement_mode(True, tr("placement.object"))

    def _create_object_at_pos(self, pos: QPointF):
        has_ids_toolchain = bool(self._has_ids_resource_toolchain())
        game_path = str(self._primary_game_path() or "").strip()
        raw_archetypes = [self.arch_cb.itemText(i) for i in range(self.arch_cb.count()) if self.arch_cb.itemText(i)]
        if game_path:
            archetypes = [
                a for a in raw_archetypes
                if self._is_known_archetype(game_path, a)
            ]
        else:
            archetypes = list(raw_archetypes)
        arch_keys = {str(a).strip().lower() for a in archetypes if str(a).strip()}
        raw_loadouts = [self.loadout_cb.itemText(i) for i in range(self.loadout_cb.count()) if self.loadout_cb.itemText(i)]
        available_pairs: list[tuple[str, str]] = []
        seen_pair: set[tuple[str, str]] = set()
        roots: list[Path] = []
        if game_path:
            roots.append(Path(game_path))
        fallback = self._fallback_game_path().strip()
        if fallback:
            fb_root = Path(fallback)
            if fb_root not in roots:
                roots.append(fb_root)
        for root in roots:
            for arch, nick in self._sp_starter_loadout_pairs(root):
                key = (str(arch).strip().lower(), str(nick).strip().lower())
                if key in seen_pair:
                    continue
                seen_pair.add(key)
                available_pairs.append((str(arch).strip(), str(nick).strip()))
        existing_loadout_nicks = {
            nick.lower()
            for arch, nick in available_pairs
            if nick and arch and (not arch_keys or arch.lower() in arch_keys)
        }
        loadouts = [
            lo for lo in raw_loadouts
            if str(lo).strip().lower() in existing_loadout_nicks
        ]
        if not loadouts:
            loadouts = [nick for _arch, nick in available_pairs if nick]
        if not loadouts:
            loadouts = list(raw_loadouts)
        factions = [self.faction_cb.itemText(i) for i in range(self.faction_cb.count()) if self.faction_cb.itemText(i)]
        dlg = ObjectCreationDialog(self, archetypes, loadouts, factions)
        dlg.nick_edit.setText(
            self._suggest_system_scoped_name("object", [o.nickname for o in self._objects])
        )
        if dlg.exec() != QDialog.Accepted:
            self._pending_new_object = False
            return
        data_in = dlg.payload()
        nickname = data_in.get("nickname", "").strip() or self._suggest_system_scoped_name(
            "object", [o.nickname for o in self._objects]
        )
        ids_name_text = str(data_in.get("ids_name_text", "") or "").strip()
        pos_str = f"{pos.x() / self._scale:.2f}, 0, {pos.y() / self._scale:.2f}"
        entries = [
            ("nickname", nickname),
            ("pos", pos_str),
            ("ids_name", "0"),
            ("ids_info", "0"),
            ("rotate", "0,0,0"),
        ]
        arch = data_in.get("archetype", "").strip()
        if arch:
            entries.append(("archetype", arch))
        loadout = data_in.get("loadout", "").strip()
        if loadout:
            entries.append(("loadout", loadout))
        faction = self._faction_from_ui(data_in.get("faction", "").strip())
        if faction:
            rep_val = data_in.get("rep", "").strip()
            entries.append(("reputation", f"{faction},{rep_val}" if rep_val else faction))
        if ids_name_text and has_ids_toolchain:
            try:
                new_ids_name = self._ensure_ids_name_in_user_dll("0", ids_name_text)
                entries = self._entry_set(entries, "ids_name", new_ids_name)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
        self._add_object_from_entries(entries, "Object")
        self._pending_new_object = False

    def _add_object_from_entries(
        self,
        entries: list[tuple[str, str]],
        section_name: str,
        *,
        refresh_3d: bool = True,
        select_created: bool = True,
        push_undo: bool = True,
        refresh_builder: bool = True,
        rebuild_combo: bool = True,
    ):
        """Erzeugt ein SolarObject aus Eintrags-Tupeln und fügt es zur Szene hinzu."""
        data = {"_entries": entries}
        for k, v in entries:
            if k.lower() not in data:
                data[k.lower()] = v
        obj = SolarObject(data, self._scale)
        if hasattr(obj, "set_label_visibility"):
            obj.set_label_visibility(self._viewer_text_visible)
        obj.setFlag(QGraphicsItem.ItemIsMovable, self.move_cb.isChecked())
        self.view._scene.addItem(obj)
        self._objects.append(obj)
        self._sections.append((section_name, list(entries)))
        if rebuild_combo:
            self._rebuild_object_combo()
        if select_created:
            self._select(obj)
        if push_undo:
            self._push_undo_action(
                {
                    "type": "create_object",
                    "label": f"Objekt erstellt: {obj.nickname}",
                    "filepath": self._filepath or "",
                    "nickname": obj.nickname,
                }
            )
            self._append_change_log(f"Objekt erstellt: {obj.nickname}")
        self._set_dirty(True)
        self._apply_group_visibility()
        if refresh_builder:
            self._refresh_base_builder_dialog_parts()
        if refresh_3d:
            self._refresh_3d_scene()
        return obj

