    def _start_buoy_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        dlg = BuoyDialog(self)
        if dlg.exec() != QDialog.Accepted:
            return
        data = dlg.payload()
        self._pending_buoy = {"step": 1, **data}
        if data.get("pattern", "LINE").upper() == "SINGLE":
            self.statusBar().showMessage(tr("status.click_place_buoy_single"))
            self._set_placement_mode(True, tr("placement.buoy_single"))
        else:
            self.statusBar().showMessage(tr("status.click_place_buoy_start"))
            self._set_placement_mode(True, tr("placement.buoy_start"))

    def _create_buoy_entries(self, buoy_type: str, pos: QPointF, index: int) -> list[tuple[str, str]]:
        sys_nick = Path(self._filepath).stem.upper() if self._filepath else "SYS"
        prefix = f"{sys_nick}_{buoy_type.upper()}"
        nickname = self._next_auto_object_nickname(prefix)
        pos_str = f"{pos.x() / self._scale:.2f}, 0, {pos.y() / self._scale:.2f}"
        if self._has_ids_resource_toolchain():
            if buoy_type == "hazard_buoy":
                ids_name = "261163"
                ids_info = "66144"
            elif buoy_type == "nav_buoy":
                ids_name = "261162"
                ids_info = "66147"
            else:
                ids_name = "0"
                ids_info = "0"
        else:
            ids_name = "0"
            ids_info = "0"
        return [
            ("nickname", nickname),
            ("ids_name", ids_name),
            ("ids_info", ids_info),
            ("pos", pos_str),
            ("rotate", "0,0,0"),
            ("archetype", buoy_type),
        ]

    def _create_buoys_line(self, start: QPointF, end: QPointF, buoy_type: str, count: int):
        for i in range(count):
            t = 0.0 if count <= 1 else i / (count - 1)
            p = QPointF(
                start.x() + (end.x() - start.x()) * t,
                start.y() + (end.y() - start.y()) * t,
            )
            self._add_object_from_entries(self._create_buoy_entries(buoy_type, p, i), "Object")

    def _create_buoys_circle(self, center: QPointF, radius_scene: float, buoy_type: str, count: int):
        for i in range(count):
            angle = (2.0 * math.pi * i) / max(1, count)
            p = QPointF(
                center.x() + math.cos(angle) * radius_scene,
                center.y() + math.sin(angle) * radius_scene,
            )
            self._add_object_from_entries(self._create_buoy_entries(buoy_type, p, i), "Object")

    def _on_buoy_click(self, pos: QPointF):
        pb = self._pending_buoy
        if not pb:
            return
        step = pb.get("step", 1)
        pattern = pb.get("pattern", "LINE")
        buoy_type = pb.get("buoy_type", "nav_buoy")
        count = int(pb.get("count", 8))
        spacing_world = float(pb.get("spacing", 3000) or 3000)

        if pattern == "SINGLE":
            self._add_object_from_entries(self._create_buoy_entries(buoy_type, pos, 0), "Object")
            self._pending_buoy = None
            self.statusBar().showMessage(tr("status.buoy_created").format(count=1, buoy_type=buoy_type))
            return

        if step == 1:
            pb["start"] = pos
            pb["step"] = 2
            if pattern == "LINE":
                pen = QPen(self._scene_role_color("simple_zone", 180), 2, Qt.DashLine)
                self._tl_rubber_line = self.view._scene.addLine(pos.x(), pos.y(), pos.x(), pos.y(), pen)
                self._tl_rubber_line.setZValue(9999)
                self.view.mouse_moved.connect(self._update_tl_rubber_line)
            else:
                pen = QPen(self._scene_role_color("simple_zone", 200), 2, Qt.DashLine)
                brush = QBrush(self._scene_role_color("simple_zone_fill", 20))
                # Shape aus Dialog holen, falls vorhanden
                shape = None
                if self._pending_zone and "shape" in self._pending_zone:
                    shape = self._pending_zone["shape"].upper()
                elif self._pending_simple_zone and "shape" in self._pending_simple_zone:
                    shape = self._pending_simple_zone["shape"].upper()
                elif self._pending_exclusion_zone and "shape" in self._pending_exclusion_zone:
                    shape = self._pending_exclusion_zone["shape"].upper()
                else:
                    shape = "SPHERE"
                if shape == "BOX":
                    self._zone_rubber_ellipse = QGraphicsRectItem(pos.x(), pos.y(), 0, 0)
                    self._zone_rubber_ellipse.setPen(pen)
                    self._zone_rubber_ellipse.setBrush(brush)
                    self.view._scene.addItem(self._zone_rubber_ellipse)
                else:
                    self._zone_rubber_ellipse = self.view._scene.addEllipse(pos.x(), pos.y(), 0, 0, pen, brush)
                self._zone_rubber_ellipse.setZValue(9999)
                self._zone_rubber_origin = pos
                self.view.mouse_moved.connect(self._update_zone_rubber_ellipse)
            self.statusBar().showMessage(tr("status.click_place_buoy_end"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.buoy_end")))
            return

        start = pb.get("start", pos)
        if pattern == "LINE":
            self._remove_tl_rubber_line()
            dist_scene = math.hypot(pos.x() - start.x(), pos.y() - start.y())
            dist_world = dist_scene / max(self._scale, 1e-9)
            auto_count = max(2, int(round(dist_world / max(spacing_world, 1.0))) + 1)
            count = auto_count
            self._create_buoys_line(start, pos, buoy_type, count)
        else:
            self._remove_zone_rubber_ellipse()
            radius_scene = max(10.0, math.hypot(pos.x() - start.x(), pos.y() - start.y()))
            self._create_buoys_circle(start, radius_scene, buoy_type, count)

        self._pending_buoy = None
        self.statusBar().showMessage(tr("status.buoy_created").format(count=count, buoy_type=buoy_type))

    def _create_solar_at_pos(self, pos: QPointF):
        spec = self._pending_create
        if not spec:
            return
        has_ids_toolchain = bool(self._has_ids_resource_toolchain())
        fx = pos.x() / self._scale
        fz = pos.y() / self._scale
        pos_str = f"{fx:.2f}, 0, {fz:.2f}"

        ids_name = "261008" if (has_ids_toolchain and spec.get("kind") == "sun") else "0"
        ids_info = "66162" if (has_ids_toolchain and spec.get("kind") == "sun") else "0"
        ids_name_text = str(spec.get("ids_name_text", "") or "").strip()
        if ids_name_text and has_ids_toolchain:
            try:
                ids_name = self._ensure_ids_name_in_user_dll(ids_name, ids_name_text)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")

        entries = [
            ("nickname", spec["nickname"]),
            ("ids_name", ids_name),
            ("ids_info", ids_info),
            ("pos", pos_str),
            ("rotate", "0,0,0"),
            ("archetype", spec["archetype"]),
        ]
        if spec.get("kind") == "planet":
            entries.append(("spin", "0,0,0"))
            entries.append(("atmosphere_range", str(spec.get("atmosphere_range", 2000) or 2000)))
            planet_ring = str(spec.get("planet_ring", "") or "").strip()
            if planet_ring:
                entries.append(("ring", planet_ring))
        if spec.get("kind") == "sun":
            entries.append(("atmosphere_range", str(spec.get("atmosphere_range", 5000))))
            entries.append(("star", spec.get("star", "med_white_sun") or "med_white_sun"))
        if spec.get("burn_color"):
            entries.append(("burn_color", spec["burn_color"]))

        data = {"_entries": list(entries)}
        for k, v in entries:
            if k.lower() not in data:
                data[k.lower()] = v
        obj = SolarObject(data, self._scale)
        obj.setFlag(QGraphicsItem.ItemIsMovable, self.move_cb.isChecked())
        self.view._scene.addItem(obj)
        self._objects.append(obj)
        self._sections.append(("Object", list(entries)))

        # Death-Zone
        z_nick = f"Zone_{spec['nickname']}_death"
        zone_entries = [
            ("nickname", z_nick),
            ("pos", pos_str),
            ("rotate", "0,0,0"),
            ("shape", "SPHERE"),
            ("size", str(spec["radius"])),
            ("damage", str(spec["damage"])),
            ("ids_info", "0"),
        ]
        z_data = {"_entries": list(zone_entries)}
        for k, v in zone_entries:
            if k.lower() not in z_data:
                z_data[k.lower()] = v
        z_item = ZoneItem(z_data, self._scale)
        if hasattr(z_item, "set_label_visibility"):
            z_item.set_label_visibility(self._viewer_text_visible)
        self.view._scene.addItem(z_item)
        self._zones.append(z_item)
        self._sections.append(("Zone", list(zone_entries)))

        self._rebuild_object_combo()
        self._select(obj)
        self._set_dirty(True)
        created_typ = tr("type.sun") if spec.get("kind") == "sun" else tr("type.planet")
        self.statusBar().showMessage(tr("status.death_zone_created").format(type=created_typ, nickname=spec['nickname']))
        self._pending_create = None
        self._refresh_3d_scene()

    # ------------------------------------------------------------------
    #  Tradelane-Generator
    # ------------------------------------------------------------------
    def _start_tradelane_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        self._pending_tradelane = {"step": 1}
        self.statusBar().showMessage(tr("status.click_tl_start"))
        self._set_placement_mode(True, tr("placement.tl_start"))

    def _on_tradelane_click(self, pos: QPointF):
        step = self._pending_tradelane.get("step", 1) if self._pending_tradelane else 1
        if step == 1:
            self._pending_tradelane["start"] = pos
            self._pending_tradelane["step"] = 2
            # Rubber-Band-Linie starten
            pen = QPen(self._scene_role_color("measure", 180), 2, Qt.DashLine)
            self._tl_rubber_line = self.view._scene.addLine(
                pos.x(), pos.y(), pos.x(), pos.y(), pen
            )
            self._tl_rubber_line.setZValue(9999)
            self.view.mouse_moved.connect(self._update_tl_rubber_line)
            self.statusBar().showMessage(tr("status.click_tl_end"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.tl_end")))
        elif step == 2:
            self._pending_tradelane["end"] = pos
            self._remove_tl_rubber_line()
            self._set_placement_mode(False)
            self._show_tradelane_dialog()

    def _update_tl_rubber_line(self, scene_pos: QPointF):
        if self._tl_rubber_line:
            line = self._tl_rubber_line.line()
            self._tl_rubber_line.setLine(
                line.x1(), line.y1(), scene_pos.x(), scene_pos.y()
            )

    def _remove_tl_rubber_line(self):
        if self._tl_rubber_line:
            self.view._scene.removeItem(self._tl_rubber_line)
            self._tl_rubber_line = None
            self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_tl_rubber_line)

    # ------------------------------------------------------------------
    #  Zonen-Größen-Vorschau (Rubber-Band-Ellipse)
    # ------------------------------------------------------------------
    def _update_zone_rubber_ellipse(self, scene_pos: QPointF):
        if self._zone_rubber_ellipse and self._zone_rubber_origin:
            ox, oy = self._zone_rubber_origin.x(), self._zone_rubber_origin.y()
            shape = None
            if self._pending_zone and "shape" in self._pending_zone:
                shape = self._pending_zone["shape"].upper()
            elif self._pending_simple_zone and "shape" in self._pending_simple_zone:
                shape = self._pending_simple_zone["shape"].upper()
            elif self._pending_exclusion_zone:
                try:
                    shape = str(self._pending_exclusion_zone.get("params", {}).get("shape", "SPHERE")).upper()
                except Exception:
                    shape = "SPHERE"
            else:
                shape = "SPHERE"
            excl_ellipsoid_rect = (
                shape == "ELLIPSOID"
                and self._pending_exclusion_zone is not None
                and self._pending_zone is None
                and self._pending_simple_zone is None
            )
            if shape in ("BOX", "CYLINDER") or excl_ellipsoid_rect:
                # Draw rectangle from first click to current mouse position (scene coordinates)
                x0, y0 = ox, oy
                x1, y1 = scene_pos.x(), scene_pos.y()
                left = min(x0, x1)
                top = min(y0, y1)
                width = abs(x1 - x0)
                height = abs(y1 - y0)
                self._zone_rubber_ellipse.setRect(left, top, width, height)
            else:
                dx = abs(scene_pos.x() - ox)
                dy = abs(scene_pos.y() - oy)
                self._zone_rubber_ellipse.setRect(
                    ox - dx, oy - dy, 2 * dx, 2 * dy
                )

    def _remove_zone_rubber_ellipse(self):
        if self._zone_rubber_ellipse:
            self.view._scene.removeItem(self._zone_rubber_ellipse)
            self._zone_rubber_ellipse = None
            self._zone_rubber_origin = None
            self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_zone_rubber_ellipse)
        if self._zone_axis_line:
            self.view._scene.removeItem(self._zone_axis_line)
            self._zone_axis_line = None
            self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_zone_axis_line)
        if self._zone_width_poly:
            self.view._scene.removeItem(self._zone_width_poly)
            self._zone_width_poly = None
            self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_zone_width_poly)

    @staticmethod
    def _oriented_rect_polygon(p0: QPointF, p1: QPointF, half_w: float) -> QPolygonF:
        dx = p1.x() - p0.x()
        dy = p1.y() - p0.y()
        ln = math.hypot(dx, dy)
        if ln < 1e-6:
            nx, ny = 0.0, 1.0
        else:
            nx, ny = -dy / ln, dx / ln
        return QPolygonF(
            [
                QPointF(p0.x() + nx * half_w, p0.y() + ny * half_w),
                QPointF(p1.x() + nx * half_w, p1.y() + ny * half_w),
                QPointF(p1.x() - nx * half_w, p1.y() - ny * half_w),
                QPointF(p0.x() - nx * half_w, p0.y() - ny * half_w),
            ]
        )

    @staticmethod
    def _point_line_distance(p: QPointF, a: QPointF, b: QPointF) -> float:
        dx = b.x() - a.x()
        dy = b.y() - a.y()
        ln = math.hypot(dx, dy)
        if ln < 1e-6:
            return math.hypot(p.x() - a.x(), p.y() - a.y())
        return abs((dx * (a.y() - p.y()) - (a.x() - p.x()) * dy) / ln)

    def _update_zone_axis_line(self, scene_pos: QPointF):
        if not self._zone_axis_line:
            return
        line = self._zone_axis_line.line()
        self._zone_axis_line.setLine(line.x1(), line.y1(), scene_pos.x(), scene_pos.y())

    def _update_zone_width_poly(self, scene_pos: QPointF):
        pz = self._pending_simple_zone
        if not pz:
            pz = self._pending_exclusion_zone
        if not pz or not self._zone_width_poly:
            return
        a = pz.get("axis_start")
        b = pz.get("axis_end")
        if not isinstance(a, QPointF) or not isinstance(b, QPointF):
            return
        half_w = max(1.0, self._point_line_distance(scene_pos, a, b))
        self._zone_width_poly.setPolygon(self._oriented_rect_polygon(a, b, half_w))

    def _show_tradelane_dialog(self):
        tl = self._pending_tradelane
        if not tl:
            return
        start: QPointF = tl["start"]
        end: QPointF = tl["end"]
        sx, sz = start.x() / self._scale, start.y() / self._scale
        ex, ez = end.x() / self._scale, end.y() / self._scale
        dist = math.sqrt((ex - sx) ** 2 + (ez - sz) ** 2)
        spacing = 7500.0
        ring_count = max(2, round(dist / spacing) + 1)

        system_nick = Path(self._filepath).stem
        # Finde nächste freie Ring-Nummer
        max_num = 0
        prefix = f"{system_nick}_Trade_Lane_Ring_".lower()
        for o in self._objects:
            nn = o.nickname.lower()
            if nn.startswith(prefix):
                try:
                    num = int(nn[len(prefix):])
                    max_num = max(max_num, num)
                except ValueError:
                    pass
        start_num = max_num + 1

        # Factions aus Cache
        factions = list(self._cached_faction_labels) if self._cached_faction_labels else list(self._cached_factions)

        dlg = TradeLaneDialog(
            self,
            system_nick=system_nick,
            start_num=start_num,
            ring_count=ring_count,
            distance=dist,
            factions=factions,
        )
        if dlg.exec() != QDialog.Accepted:
            self._pending_tradelane = None
            return
        payload = dlg.payload()
        payload["reputation"] = self._normalize_reputation_value(payload.get("reputation", ""))
        try:
            payload["ids_name"] = self._resolve_ids_name_input(payload.get("ids_name", "0"))
            payload["space_name_start"] = self._resolve_ids_name_input(payload.get("space_name_start", "0"))
            payload["space_name_end"] = self._resolve_ids_name_input(payload.get("space_name_end", "0"))
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
            self._pending_tradelane = None
            return
        self._generate_tradelane(sx, sz, ex, ez, payload, system_nick)
        self._pending_tradelane = None

    def _resolve_ids_name_input(self, raw_value: str | int | None) -> str:
        """Accepts numeric ids_name or plain text; text is written to user DLL."""
        txt = str(raw_value or "").strip()
        if not txt or txt == "0":
            return "0"
        try:
            num = int(txt)
            if num >= 0:
                return str(num)
        except Exception:
            pass
        return str(self._ensure_ids_name_in_user_dll("0", txt))

    def _generate_tradelane(self, sx: float, sz: float,
                            ex: float, ez: float,
                            cfg: dict, system_nick: str):
        """Erzeugt alle Trade_Lane_Ring-Objekte zwischen Start und Ende."""
        count = cfg["ring_count"]
        start_num = cfg["start_num"]

        # Richtungsvektor und gleichmäßige Abstände
        dx = ex - sx
        dz = ez - sz

        # Rotation: Y-Winkel = Richtung der Lane (Grad)
        # Freelancer-Konvention: Ring zeigt entgegen der Flugrichtung → +180°
        angle_rad = math.atan2(dx, dz)
        angle_deg = math.degrees(angle_rad) + 180.0
        if angle_deg > 180.0:
            angle_deg -= 360.0
        rotate_str = f"0, {angle_deg:.0f}, 0"

        for i in range(count):
            t = i / max(count - 1, 1)
            px = sx + dx * t
            pz = sz + dz * t
            pos_str = f"{px:.0f}, 0, {pz:.0f}"
            num = start_num + i
            nickname = f"{system_nick}_Trade_Lane_Ring_{num}"

            entries: list[tuple[str, str]] = [
                ("nickname", nickname),
                ("ids_name", cfg["ids_name"]),
                ("pos", pos_str),
                ("rotate", rotate_str),
                ("Archetype", "Trade_Lane_Ring"),
                ("ids_info", "66170"),
            ]

            # prev_ring / next_ring  (doubly linked list)
            if i > 0:
                prev_nick = f"{system_nick}_Trade_Lane_Ring_{start_num + i - 1}"
                entries.append(("prev_ring", prev_nick))
            if i < count - 1:
                next_nick = f"{system_nick}_Trade_Lane_Ring_{start_num + i + 1}"
                entries.append(("next_ring", next_nick))

            entries.append(("behavior", "NOTHING"))
            entries.append(("difficulty_level", str(cfg["difficulty_level"])))
            entries.append(("loadout", cfg["loadout"]))
            entries.append(("pilot", cfg["pilot"]))
            if cfg["reputation"]:
                entries.append(("reputation", cfg["reputation"]))

            # tradelane_space_name nur auf erstem und letztem Ring
            if i == 0 and cfg.get("space_name_start", "0") != "0":
                entries.append(("tradelane_space_name", cfg["space_name_start"]))
            elif i == count - 1 and cfg.get("space_name_end", "0") != "0":
                entries.append(("tradelane_space_name", cfg["space_name_end"]))

            self._add_object_from_entries(entries, "Object")

        self.statusBar().showMessage(
            tr("status.tl_created_detail").format(
                count=count,
                first=f"{system_nick}_Trade_Lane_Ring_{start_num}",
                last=f"{system_nick}_Trade_Lane_Ring_{start_num + count - 1}"
            )
        )

    # ------------------------------------------------------------------
    #  Tradelane-Routen bearbeiten (Erkennung, Löschen, Repositionieren)
    # ------------------------------------------------------------------
    def _find_tradelane_chains(self) -> list[list[dict]]:
        """Erkennt zusammengehörige Trade-Lane-Ringe über prev_ring/next_ring.

        Gibt eine Liste von Ketten zurück; jede Kette ist eine geordnete
        Liste von Dicts mit nickname, pos, rotate, loadout, prev_ring, next_ring,
        und einem Verweis auf das SolarObject (_obj).
        """
        def _entry_value(obj: SolarObject, key: str) -> str:
            key_l = key.strip().lower()
            val = str(obj.data.get(key, "") or "").strip()
            if val:
                return val
            for ek, ev in obj.data.get("_entries", []) or []:
                if str(ek).strip().lower() == key_l:
                    return str(ev).strip()
            return ""

        def _resolved_ids_text(ids_raw: str) -> str:
            txt = str(ids_raw or "").strip()
            if not txt or txt == "0":
                return ""
            return self._display_name_from_ids_name(txt) or ""

        # Alle TL-Ringe nach Nickname indizieren
        tl_map: dict[str, SolarObject] = {}
        for obj in self._objects:
            arch = obj.data.get("archetype", "").lower()
            name = obj.nickname.lower()
            if "trade_lane_ring" in arch or "trade_lane_ring" in name:
                tl_map[obj.nickname.lower()] = obj

        visited: set[str] = set()
        chains: list[list[dict]] = []

        for nick_lc, obj in tl_map.items():
            if nick_lc in visited:
                continue
            # Zum Anfang der Kette laufen
            cur = obj
            while True:
                prev = cur.data.get("prev_ring", "").strip().lower()
                if prev and prev in tl_map and prev not in visited:
                    cur = tl_map[prev]
                else:
                    break
            # Kette vorwärts aufbauen
            chain: list[dict] = []
            while cur:
                nn = cur.nickname.lower()
                if nn in visited:
                    break
                visited.add(nn)
                ids_name_raw = _entry_value(cur, "ids_name")
                space_name_raw = _entry_value(cur, "tradelane_space_name")
                chain.append({
                    "nickname": cur.nickname,
                    "pos": cur.data.get("pos", ""),
                    "rotate": cur.data.get("rotate", ""),
                    "loadout": cur.data.get("loadout", ""),
                    "prev_ring": cur.data.get("prev_ring", ""),
                    "next_ring": cur.data.get("next_ring", ""),
                    "ids_name": ids_name_raw,
                    "tradelane_space_name": space_name_raw,
                    "_obj": cur,
                })
                nxt = cur.data.get("next_ring", "").strip().lower()
                cur = tl_map.get(nxt) if nxt else None
            if chain:
                route_ids = ""
                for ring in chain:
                    cand = str(ring.get("ids_name", "") or "").strip()
                    if cand and cand != "0":
                        route_ids = cand
                        break

                start_ids = ""
                for ring in chain:
                    cand = str(ring.get("tradelane_space_name", "") or "").strip()
                    if cand and cand != "0":
                        start_ids = cand
                        break

                end_ids = ""
                for ring in reversed(chain):
                    cand = str(ring.get("tradelane_space_name", "") or "").strip()
                    if cand and cand != "0":
                        end_ids = cand
                        break

                route_text = _resolved_ids_text(route_ids)
                start_text = _resolved_ids_text(start_ids)
                end_text = _resolved_ids_text(end_ids)
                for ring in chain:
                    ring["route_name"] = route_text
                    ring["start_name"] = start_text
                    ring["end_name"] = end_text
                chains.append(chain)

        return chains

    def _edit_tradelane(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        chains = self._find_tradelane_chains()
        if not chains:
            QMessageBox.information(
                self, tr("msg.no_tradelanes"),
                tr("msg.no_tradelanes_text")
            )
            return
        dlg = TradeLaneEditDialog(self, chains=chains)
        if dlg.exec() != QDialog.Accepted:
            return
        idx = dlg.selected_chain_index
        if idx < 0 or idx >= len(chains):
            return
        chain = chains[idx]
        action = dlg.action

        if action == "delete":
            self._delete_tradelane_chain(chain)
        elif action == "reposition":
            self._reposition_tradelane_chain(chain)
        elif action == "update_names":
            route_name, start_name, end_name = dlg.edited_names
            self._update_tradelane_chain_names(chain, route_name, start_name, end_name)

    def _delete_tradelane_chain(self, chain: list[dict]):
        nicks = [r["nickname"] for r in chain]
        msg = tr("msg.delete_tl_text").format(
            count=len(chain), first=nicks[0], last=nicks[-1]
        )
        if QMessageBox.warning(
            self, tr("msg.delete_route"), msg,
            QMessageBox.Ok | QMessageBox.Cancel
        ) != QMessageBox.Ok:
            return

        for ring in chain:
            obj: SolarObject = ring["_obj"]
            # Sektion aus _sections entfernen
            obj_idx = None
            try:
                obj_idx = self._objects.index(obj)
            except ValueError:
                continue
            count = 0
            for i, (sec_name, entries) in enumerate(list(self._sections)):
                if sec_name.lower() == "object":
                    if count == obj_idx:
                        self._sections.pop(i)
                        break
                    count += 1
            self.view._scene.removeItem(obj)
            if obj in self._objects:
                self._objects.remove(obj)

        self._rebuild_object_combo()
        self._selected = None
        self._clear_selection_ui()
        self._set_dirty(True)
        self._write_to_file(reload=False)
        self.statusBar().showMessage(
            tr("status.tl_deleted_detail").format(
                count=len(chain), first=nicks[0], last=nicks[-1]
            )
        )
        self._refresh_3d_scene()

    def _reposition_tradelane_chain(self, chain: list[dict]):
        """Startet den Zwei-Klick-Modus zum Neusetzen von Start-/Endpunkt."""
        self._pending_tl_reposition = {
            "chain": chain,
            "step": 1,
        }
        self.statusBar().showMessage(tr("status.click_tl_new_start"))
        self._set_placement_mode(True, tr("placement.tl_new_start"))

    def _on_tl_reposition_click(self, pos: QPointF):
        rp = self._pending_tl_reposition
        if not rp:
            return
        step = rp.get("step", 1)
        if step == 1:
            rp["new_start"] = pos
            rp["step"] = 2
            # Rubber-Band-Linie
            pen = QPen(self._theme_color("cb_checked", alpha=180), 2, Qt.DashLine)
            self._tl_rubber_line = self.view._scene.addLine(
                pos.x(), pos.y(), pos.x(), pos.y(), pen
            )
            self._tl_rubber_line.setZValue(9999)
            self.view.mouse_moved.connect(self._update_tl_rubber_line)
            self.statusBar().showMessage(tr("status.click_tl_new_end"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.tl_new_end")))
        elif step == 2:
            rp["new_end"] = pos
            self._remove_tl_rubber_line()
            self._set_placement_mode(False)
            self._apply_tl_reposition()

    def _apply_tl_reposition(self):
        rp = self._pending_tl_reposition
        if not rp:
            return
        chain = rp["chain"]
        start_pos: QPointF = rp["new_start"]
        end_pos: QPointF = rp["new_end"]

        sx = start_pos.x() / self._scale
        sz = start_pos.y() / self._scale
        ex = end_pos.x() / self._scale
        ez = end_pos.y() / self._scale
        count = len(chain)

        dx = ex - sx
        dz = ez - sz

        # Neue Rotation berechnen
        angle_rad = math.atan2(dx, dz)
        angle_deg = math.degrees(angle_rad) + 180.0
        if angle_deg > 180.0:
            angle_deg -= 360.0
        rotate_str = f"0, {angle_deg:.0f}, 0"

        for i, ring in enumerate(chain):
            obj: SolarObject = ring["_obj"]
            t = i / max(count - 1, 1)
            px = sx + dx * t
            pz = sz + dz * t
            new_pos = f"{px:.0f}, 0, {pz:.0f}"

            # Einträge aktualisieren
            entries = obj.data.get("_entries", [])
            new_entries = []
            for k, v in entries:
                if k.lower() == "pos":
                    new_entries.append((k, new_pos))
                else:
                    new_entries.append((k, v))
            obj.data["_entries"] = new_entries
            obj.data["pos"] = new_pos
            rx, _ry, rz = self._get_object_rotate(obj)
            self._set_object_rotate(obj, (rx, angle_deg, rz))
            new_entries = list(obj.data.get("_entries", []))

            # Grafik-Position aktualisieren
            parts = new_pos.split(",")
            gx = float(parts[0].strip()) * self._scale
            gz = float(parts[2].strip()) * self._scale
            obj.setPos(gx - obj.rect().width() / 2,
                       gz - obj.rect().height() / 2)

            # Sektion in _sections aktualisieren
            obj_idx = None
            try:
                obj_idx = self._objects.index(obj)
            except ValueError:
                continue
            count_s = 0
            for si, (sec_name, sec_entries) in enumerate(self._sections):
                if sec_name.lower() == "object":
                    if count_s == obj_idx:
                        self._sections[si] = (sec_name, list(new_entries))
                        break
                    count_s += 1

        self._pending_tl_reposition = None
        self._set_dirty(True)
        self._write_to_file(reload=False)
        self.statusBar().showMessage(
            tr("status.tl_repositioned_detail").format(count=count)
        )
        self._refresh_3d_scene()

    def _entry_remove(self, entries: list[tuple[str, str]], key: str) -> list[tuple[str, str]]:
        target = str(key or "").strip().lower()
        if not target:
            return list(entries or [])
        out: list[tuple[str, str]] = []
        for k, v in entries or []:
            if str(k).strip().lower() != target:
                out.append((k, v))
        return out

    def _update_tradelane_chain_names(self, chain: list[dict], route_name: str, start_name: str, end_name: str):
        if not chain:
            return
        try:
            route_name = str(route_name or "").strip()
            start_name = str(start_name or "").strip()
            end_name = str(end_name or "").strip()

            existing_route_id = ""
            for ring in chain:
                cur_id = str(ring.get("ids_name", "") or "").strip()
                if cur_id and cur_id != "0":
                    existing_route_id = cur_id
                    break
            existing_start_id = str(chain[0].get("tradelane_space_name", "") or "").strip()
            existing_end_id = str(chain[-1].get("tradelane_space_name", "") or "").strip()

            route_id = "0"
            if route_name:
                route_id = str(self._ensure_ids_name_in_user_dll(existing_route_id or "0", route_name) or "0")
            start_id = "0"
            if start_name:
                start_id = str(self._ensure_ids_name_in_user_dll(existing_start_id or "0", start_name) or "0")
            end_id = "0"
            if end_name:
                end_id = str(self._ensure_ids_name_in_user_dll(existing_end_id or "0", end_name) or "0")

            for i, ring in enumerate(chain):
                obj: SolarObject = ring["_obj"]
                entries = list(obj.data.get("_entries", []) or [])

                # Route name (ids_name) on all rings.
                if route_id != "0":
                    entries = self._entry_set(entries, "ids_name", route_id)
                    obj.data["ids_name"] = route_id
                else:
                    entries = self._entry_remove(entries, "ids_name")
                    obj.data["ids_name"] = ""

                # Endpoint names only on first and last ring.
                if i == 0:
                    if start_id != "0":
                        entries = self._entry_set(entries, "tradelane_space_name", start_id)
                        obj.data["tradelane_space_name"] = start_id
                    else:
                        entries = self._entry_remove(entries, "tradelane_space_name")
                        obj.data["tradelane_space_name"] = ""
                elif i == len(chain) - 1:
                    if end_id != "0":
                        entries = self._entry_set(entries, "tradelane_space_name", end_id)
                        obj.data["tradelane_space_name"] = end_id
                    else:
                        entries = self._entry_remove(entries, "tradelane_space_name")
                        obj.data["tradelane_space_name"] = ""
                else:
                    entries = self._entry_remove(entries, "tradelane_space_name")
                    obj.data["tradelane_space_name"] = ""

                obj.data["_entries"] = entries

                obj_idx = None
                try:
                    obj_idx = self._objects.index(obj)
                except ValueError:
                    continue
                count_s = 0
                for si, (sec_name, _sec_entries) in enumerate(self._sections):
                    if sec_name.lower() == "object":
                        if count_s == obj_idx:
                            self._sections[si] = (sec_name, list(entries))
                            break
                        count_s += 1

            self._ids_display_cache.clear()
            self._set_dirty(True)
            self._write_to_file(reload=False)
            self.statusBar().showMessage(tr("status.saved"))
        except Exception as exc:
            QMessageBox.warning(self, tr("msg.save_error"), str(exc))

    # ==================================================================
    #  Zone Population bearbeiten
    # ==================================================================
    def _edit_zone_population(self):
        """Öffnet den Zone-Population-Dialog für die ausgewählte Zone."""
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return

        # Ausgewählte Zone aus dem Combo ermitteln
        idx = self.obj_combo.currentIndex()
        if idx < 0:
            self.statusBar().showMessage(tr("status.no_zone_selected"))
            return
        item = self.obj_combo.itemData(idx)
        if not isinstance(item, ZoneItem):
            QMessageBox.information(
                self, tr("msg.no_zone"),
                tr("msg.no_zone_text")
            )
            return
        zone = item

        # Zugehörige Section in _sections finden
        zone_nick = zone.nickname.strip().lower()
        sec_idx: int | None = None
        sec_entries: list[tuple[str, str]] | None = None
        for i, (sec_name, entries) in enumerate(self._sections):
            if sec_name.lower() == "zone":
                nick = ""
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip().lower()
                        break
                if nick == zone_nick:
                    sec_idx = i
                    sec_entries = entries
                    break

        if sec_idx is None or sec_entries is None:
            QMessageBox.warning(
                self, tr("msg.not_found"),
                tr("msg.zone_not_found").format(nickname=zone.nickname)
            )
            return

        # Verfügbare EncounterParameters sammeln
        enc_params: list[str] = []
        for sec_name, entries in self._sections:
            if sec_name.lower() == "encounterparameters":
                for k, v in entries:
                    if k.lower() == "nickname":
                        enc_params.append(v.strip())

        # Alle verfügbaren Encounters aus DATA/MISSIONS/ENCOUNTERS laden
        game_path = self._primary_game_path()
        all_encounters: list[str] = list(enc_params)  # vorhandene zuerst
        if game_path:
            # ci_resolve gibt nur Dateien zurück → Verzeichnisse manuell auflösen
            enc_dir = self._resolve_data_subdir_case_insensitive(game_path, "MISSIONS/ENCOUNTERS")
            if enc_dir and enc_dir.is_dir():
                for f in sorted(enc_dir.iterdir()):
                    if f.suffix.lower() == ".ini":
                        nick = f.stem
                        if nick not in all_encounters:
                            all_encounters.append(nick)

        # Dialog öffnen
        dlg = ZonePopulationDialog(
            self,
            zone_nickname=zone.nickname,
            entries=sec_entries,
            encounter_params=enc_params,
            all_encounters=all_encounters,
            factions=self._cached_faction_labels if self._cached_faction_labels else self._cached_factions,
        )
        if dlg.exec() != QDialog.Accepted:
            return

        # Neue EncounterParameters-Sektionen anlegen (nach [SystemInfo])
        new_enc = dlg.new_encounter_params
        if new_enc:
            # Einfügeposition: direkt nach [SystemInfo]
            insert_pos = 1
            for i, (sn, _) in enumerate(self._sections):
                if sn.lower() == "systeminfo":
                    insert_pos = i + 1
                    break
            for enc_nick in sorted(new_enc):
                enc_entries: list[tuple[str, str]] = [
                    ("nickname", enc_nick),
                    ("filename", f"missions\\encounters\\{enc_nick}.ini"),
                ]
                self._sections.insert(insert_pos, ("EncounterParameters", enc_entries))
                insert_pos += 1
                # sec_idx verschiebt sich durch das Einfügen
                sec_idx += 1

        # Einträge aktualisieren
        new_entries = dlg.build_entries()
        new_entries = [
            (k, self._faction_from_ui(v) if k.lower() == "faction" else v)
            for k, v in new_entries
        ]
        self._sections[sec_idx] = ("Zone", new_entries)
        zone.data["_entries"] = list(new_entries)
        # Einfache Felder im data-dict aktualisieren
        for k, v in new_entries:
            kl = k.lower()
            if kl != "_entries":
                zone.data[kl] = v

        # Text-Editor synchronisieren, damit _write_to_file die neuen
        # Einträge nicht mit dem alten Editor-Text überschreibt
        if self._selected is zone:
            self.editor.setPlainText(zone.raw_text())

        self._set_dirty(True)
        self._write_to_file(reload=False)
        self.statusBar().showMessage(
            tr("status.zone_pop_updated").format(nickname=zone.nickname)
        )

    # ------------------------------------------------------------------
    #  Base bearbeiten  (Attribute + Market-Dateien)
    # ------------------------------------------------------------------
    def _invalidate_base_template_dialog_cache(self, game_path: str = "") -> None:
        target = str(game_path or "").strip()
        if not target or self._base_template_dialog_cache_game_path == target:
            self._base_template_dialog_cache = {}
            if target:
                self._base_template_dialog_cache_game_path = target

    def _zone_reference_files(self, game_path: str, subdir: str) -> list[str]:
        game_root = str(game_path or "").strip()
        folder = str(subdir or "").strip()
        if not game_root or not folder:
            return []
        if self._zone_ref_file_cache_game_path != game_root:
            self._zone_ref_file_cache = {}
            self._zone_ref_file_cache_game_path = game_root
        cache_key = folder.lower()
        cached = self._zone_ref_file_cache.get(cache_key)
        if cached is not None:
            return list(cached)

        out: list[str] = []
        seen: set[str] = set()
        roots: list[Path] = [Path(game_root)]
        fb = self._fallback_game_path().strip()
        if fb:
            fb_path = Path(fb)
            if fb_path not in roots:
                roots.append(fb_path)

        def _resolve_dir(base: Path, rel: str) -> Path | None:
            cur = base
            for seg in [s for s in rel.replace("\\", "/").split("/") if s]:
                nxt = ci_find(cur, seg)
                if not nxt or not nxt.is_dir():
                    return None
                cur = nxt
            return cur if cur.is_dir() else None

        for base in roots:
            candidates: list[Path] = []
            p1 = _resolve_dir(base, f"DATA/SOLAR/{folder}")
            if p1:
                candidates.append(p1)
            p2 = _resolve_dir(base, f"SOLAR/{folder}")
            if p2:
                candidates.append(p2)
            data_dir = ci_find(base, "DATA")
            if data_dir and data_dir.is_dir():
                p3 = _resolve_dir(data_dir, f"SOLAR/{folder}")
                if p3:
                    candidates.append(p3)

            for path in candidates:
                try:
                    for ini_file in path.glob("*.ini"):
                        if not ini_file.is_file():
                            continue
                        name = ini_file.name
                        key = name.lower()
                        if key in seen:
                            continue
                        seen.add(key)
                        out.append(name)
                except Exception:
                    continue

        result = sorted(out, key=str.lower)
        self._zone_ref_file_cache[cache_key] = list(result)
        return result

    def _base_template_dialog_data(self, game_path: str, base_nick: str) -> dict[str, object]:
        game_root = str(game_path or "").strip()
        base_key = str(base_nick or "").strip().lower()
        if not game_root or not base_key:
            return {"details": [], "room_npcs": {}, "virtual_targets": []}
        if self._base_template_dialog_cache_game_path != game_root:
            self._base_template_dialog_cache = {}
            self._base_template_dialog_cache_game_path = game_root
        cached = self._base_template_dialog_cache.get(base_key)
        if cached is not None:
            return deepcopy(cached)

        template_rooms = self._load_template_rooms(game_path, base_nick)
        bundle = {
            "details": self._load_base_room_template_details(game_path, base_nick),
            "room_npcs": self._load_base_template_room_npcs(game_path, base_nick),
            "virtual_targets": load_base_template_virtual_room_targets(
                template_rooms=template_rooms,
                extract_virtual_room_targets=self._extract_virtual_room_targets,
            ),
        }
        self._base_template_dialog_cache[base_key] = deepcopy(bundle)
        return bundle

    def _base_dialog_static_data(self, game_path: str) -> dict[str, object]:
        game_root = str(game_path or "").strip()
        if not game_root:
            return {}
        if self._base_dialog_static_cache_game_path == game_root and self._base_dialog_static_cache:
            return {
                key: deepcopy(value) if isinstance(value, (dict, list, tuple)) else value
                for key, value in self._base_dialog_static_cache.items()
            }

        archetypes = self._base_archetypes_from_solararch(game_root)
        static_data = {
            "archetypes": list(archetypes),
            "default_loadouts_by_archetype": self._base_default_loadouts_from_solararch(game_root),
            "pilots": self._scan_pilots(game_root),
            "voices": self._scan_voices(game_root),
            "bodyparts": self._scan_bodyparts(game_root),
            "equip_groups": self._scan_equip_nicknames(game_root),
            "commodity_scan": self._scan_commodity_nicknames(game_root),
            "display_names": self._scan_good_display_names(game_root),
            "commodity_display_names": self._scan_commodity_display_names(game_root),
            "base_prices": self._scan_good_base_prices(game_root),
            "ship_nicks": self._scan_ship_nicknames(game_root),
        }
        self._base_dialog_static_cache = {
            key: deepcopy(value) if isinstance(value, (dict, list, tuple)) else value
            for key, value in static_data.items()
        }
        self._base_dialog_static_cache_game_path = game_root
        return static_data

    def _load_market_goods(
        self, game_path: str, market_file: str, base_nick: str
    ) -> list[list[str]]:
        """Liest MarketGood-Einträge aus einer Market-Datei für eine Base."""
        if self._market_goods_cache_game_path != game_path:
            self._market_goods_cache = {}
            self._market_goods_cache_game_path = game_path
        cache_key = (str(market_file or "").strip().lower(), str(base_nick or "").strip().lower())
        cached = self._market_goods_cache.get(cache_key)
        if cached is not None:
            return [list(row) for row in cached]
        mf = self._resolve_game_path_case_insensitive(game_path, f"DATA/EQUIPMENT/{market_file}")
        if not mf or not mf.is_file():
            return []
        try:
            sections = self._parser.parse(str(mf))
        except Exception:
            return []
        bn = base_nick.strip().lower()
        for sec_name, entries in sections:
            if sec_name.lower() != "basegood":
                continue
            sec_base = ""
            for k, v in entries:
                if k.lower() == "base":
                    sec_base = v.strip().lower()
                    break
            if sec_base != bn:
                continue
            # MarketGood-Einträge sammeln
            goods: list[list[str]] = []
            for k, v in entries:
                if k.lower() == "marketgood":
                    fields = [f.strip() for f in v.split(",")]
                    goods.append(fields)
            self._market_goods_cache[cache_key] = [list(row) for row in goods]
            return goods
        return []

    def _save_market_goods(
        self,
        game_path: str,
        market_file: str,
        base_nick: str,
        goods: list[list[str]],
    ) -> bool:
        """Aktualisiert MarketGood-Einträge in einer Market-Datei.

        Falls kein [BaseGood] für *base_nick* existiert, wird einer
        am Ende der Datei angelegt.
        """
        mf = self._target_game_path_for_rel(game_path, f"DATA/EQUIPMENT/{market_file}")
        if not mf:
            return False
        mf = self._ensure_writable_path(mf)
        if not mf.exists():
            try:
                mf.parent.mkdir(parents=True, exist_ok=True)
                mf.write_text("", encoding="utf-8")
            except Exception:
                return False
        try:
            sections = self._parser.parse(str(mf))
        except Exception:
            return False

        bn = base_nick.strip().lower()
        found_idx: int | None = None
        for i, (sec_name, entries) in enumerate(sections):
            if sec_name.lower() != "basegood":
                continue
            for k, v in entries:
                if k.lower() == "base":
                    if v.strip().lower() == bn:
                        found_idx = i
                        break
            if found_idx is not None:
                break

        # Neue Einträge aufbauen
        new_entries: list[tuple[str, str]] = [("base", base_nick)]
        for row in goods:
            new_entries.append(("MarketGood", ", ".join(row)))

        if found_idx is not None:
            sections[found_idx] = ("BaseGood", new_entries)
        else:
            # Neuen [BaseGood] am Ende anlegen
            sections.append(("BaseGood", new_entries))

        try:
            write_sections_to_file(mf, sections)
        except Exception:
            return False
        if self._market_goods_cache_game_path == game_path:
            self._market_goods_cache.pop((str(market_file or "").strip().lower(), bn), None)
        return True

    def _scan_equip_nicknames(self, game_path: str) -> dict[str, list[str]]:
        """Scannt *_good.ini + goods.ini nach Equipment-Goods, gruppiert nach Quelle.

        Rückgabe: ``{Gruppenname: [nickname, …]}``
        """
        groups: dict[str, list[str]] = {}
        # (Dateiname, Gruppenlabel)
        sources = [
            ("weapon_good.ini", tr("market.weapons")),
            ("st_good.ini", tr("market.shields_thrusters")),
            ("misc_good.ini", tr("market.misc")),
            ("goods.ini", tr("market.general")),
        ]
        seen: set[str] = set()
        for fname, label in sources:
            gf = self._resolve_game_path_case_insensitive(game_path, f"DATA/EQUIPMENT/{fname}")
            if not gf or not gf.is_file():
                continue
            nicks: list[str] = []
            try:
                sections = self._parser.parse(str(gf))
                for sec_name, entries in sections:
                    if sec_name.lower() != "good":
                        continue
                    nick = ""
                    cat = ""
                    for k, v in entries:
                        kl = k.lower()
                        if kl == "nickname":
                            nick = v.strip()
                        elif kl == "category":
                            cat = v.strip().lower()
                    if not nick or cat != "equipment":
                        continue
                    nl = nick.lower()
                    if nl not in seen:
                        seen.add(nl)
                        nicks.append(nick)
            except Exception:
                pass
            if nicks:
                groups[label] = sorted(nicks, key=str.lower)
        return groups

    def _scan_commodity_nicknames(self, game_path: str) -> tuple[list[str], dict[str, int]]:
        """Scannt goods.ini nach commodity-Goods.

        Rückgabe: ``(nicknames, {nickname: base_price})``
        """
        gf = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/goods.ini")
        if not gf or not gf.is_file():
            return [], {}
        try:
            sections = self._parser.parse(str(gf))
        except Exception:
            return [], {}
        return scan_commodity_nicknames_from_sections(sections)

    def _scan_commodity_display_names(self, game_path: str) -> dict[str, str]:
        """Scannt Equipment-INI-Dateien nach Commodity-ids_name und löst Ingame-Namen auf."""
        out: dict[str, str] = {}
        nick_to_ids: dict[str, str] = {}
        for fp in self._iter_equipment_ini_paths_for_usage(game_path):
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for _sec_name, entries in sections:
                nick = ""
                ids_name = ""
                for k, v in entries:
                    kl = k.lower()
                    if kl == "nickname":
                        nick = v.strip()
                    elif kl == "ids_name":
                        ids_name = v.strip()
                if not nick or not nick.lower().startswith("commodity_"):
                    continue
                nl = nick.lower()
                if ids_name and nl not in nick_to_ids:
                    nick_to_ids[nl] = ids_name
        for nick, ids_name in nick_to_ids.items():
            disp = self._display_name_from_ids_name(ids_name)
            if disp:
                out[nick] = disp
        # Fallback: für nicht auflösbare IDS-Werte den Nickname lesbar machen.
        for nick in nick_to_ids:
            out.setdefault(nick, self._commodity_fallback_display_name(nick))
        return out

    def _scan_good_display_names(self, game_path: str) -> dict[str, str]:
        """Scannt *good.ini / goods.ini nach ids_name und liefert nickname -> Ingame-Name."""
        out: dict[str, str] = {}
        data_dir = self._resolve_data_subdir_case_insensitive(game_path, "EQUIPMENT")
        if not data_dir or not data_dir.is_dir():
            return out
        try:
            ini_files = sorted(p for p in data_dir.glob("*good*.ini") if p.is_file())
        except Exception:
            ini_files = []
        extra = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/goods.ini")
        if extra and extra.is_file() and extra not in ini_files:
            ini_files.append(extra)
        for fp in ini_files:
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for sec_name, entries in sections:
                if str(sec_name).strip().lower() != "good":
                    continue
                nick = self._entry_get_value(entries, "nickname").strip()
                if not nick:
                    continue
                ids_name = self._entry_get_value(entries, "ids_name").strip()
                if not ids_name:
                    continue
                disp = self._display_name_from_ids_name(ids_name).strip()
                if disp:
                    out.setdefault(nick.lower(), disp)
        return out

    def _scan_good_base_prices(self, game_path: str) -> dict[str, int]:
        """Liest Good-Preise (nickname -> price) aus *good*.ini / goods.ini."""
        out: dict[str, int] = {}
        data_dir = self._resolve_data_subdir_case_insensitive(game_path, "EQUIPMENT")
        if not data_dir or not data_dir.is_dir():
            return out
        try:
            ini_files = sorted(p for p in data_dir.glob("*good*.ini") if p.is_file())
        except Exception:
            ini_files = []
        extra = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/goods.ini")
        if extra and extra.is_file() and extra not in ini_files:
            ini_files.append(extra)
        for fp in ini_files:
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for sec_name, entries in sections:
                if str(sec_name).strip().lower() != "good":
                    continue
                nick = self._entry_get_value(entries, "nickname").strip()
                if not nick:
                    continue
                raw_price = self._entry_get_value(entries, "price").strip()
                if not raw_price:
                    continue
                try:
                    val = int(float(raw_price))
                except Exception:
                    continue
                out.setdefault(nick.lower(), val)
        return out

    def _base_has_shipdealer_room_or_virtual(self, base_ini_path: Path) -> bool:
        if not base_ini_path or not base_ini_path.exists():
            return False
        try:
            base_secs = self._parser.parse(str(base_ini_path))
        except Exception:
            return False
        room_files: list[Path] = []
        for sec_name, entries in base_secs:
            if str(sec_name).strip().lower() != "room":
                continue
            rn = self._entry_get_value(entries, "nickname").strip().lower()
            rf = self._entry_get_value(entries, "file").strip()
            if rn == "shipdealer":
                return True
            rp = self._resolve_game_path_case_insensitive(self._primary_game_path() or "", rf) if rf else None
            if not rp and rf:
                rp = base_ini_path.parent / "ROOMS" / Path(rf).name
            if rp and rp.exists():
                room_files.append(rp)
        for rp in room_files:
            try:
                txt = self._read_text_best_effort(rp).lower()
            except Exception:
                continue
            if "virtual_room = shipdealer" in txt or "set_virtual_room = shipdealer" in txt or "room_switch = shipdealer" in txt:
                return True
        return False

    @staticmethod
    def _commodity_fallback_display_name(nickname: str) -> str:
        return _commodity_fallback_display_name(nickname)

    def _scan_ship_nicknames(self, game_path: str) -> list[str]:
        """Scannt goods.ini nach allen [Good]-Einträgen mit _package im Nickname."""
        nicks: list[str] = []
        gf = self._resolve_game_path_case_insensitive(game_path, "DATA/EQUIPMENT/goods.ini")
        if not gf or not gf.is_file():
            return nicks
        try:
            sections = self._parser.parse(str(gf))
            for sec_name, entries in sections:
                if sec_name.lower() != "good":
                    continue
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip()
                        if "_package" in nick.lower():
                            nicks.append(nick)
                        break
        except Exception:
            pass
        return nicks

    def _base_nickname_for_object(self, obj: SolarObject | None) -> str:
        if obj is None:
            return ""
        parent_nickname = find_base_builder_parent_nickname(getattr(obj, "data", {}).get("_entries", []))
        if parent_nickname:
            return parent_nickname
        nickname = str(getattr(obj, "nickname", "") or getattr(obj, "data", {}).get("nickname", "") or "").strip()
        if nickname and self._has_child_objects_for_parent_nickname(nickname):
            return nickname
        for key in ("base", "dock_with"):
            value = str(getattr(obj, "data", {}).get(key, "") or "").strip()
            if value and self._has_child_objects_for_parent_nickname(value):
                return value
        for key in ("base", "dock_with"):
            value = str(getattr(obj, "data", {}).get(key, "") or "").strip()
            if value:
                return value
        return ""

    def _has_child_objects_for_parent_nickname(self, nickname: str) -> bool:
        target = str(nickname or "").strip().lower()
        if not target:
            return False
        for candidate in getattr(self, "_objects", []):
            if not isinstance(candidate, SolarObject) or hasattr(candidate, "sys_path"):
                continue
            if self._is_base_builder_child_object(candidate, target):
                return True
        return False

    def _is_base_builder_child_object(self, obj: SolarObject | None, base_nickname: str | None = None) -> bool:
        if obj is None or hasattr(obj, "sys_path"):
            return False
        return is_base_builder_child_entries(getattr(obj, "data", {}).get("_entries", []), base_nickname)

    def _is_object_related_to_base(self, obj: SolarObject | None, base_nickname: str | None) -> bool:
        if obj is None or hasattr(obj, "sys_path"):
            return False
        target = str(base_nickname or "").strip().lower()
        if not target:
            return True
        data = getattr(obj, "data", {})
        obj_nickname = str(getattr(obj, "nickname", "") or data.get("nickname", "") or "").strip().lower()
        obj_base = str(data.get("base", "") or "").strip().lower()
        obj_dock = str(data.get("dock_with", "") or "").strip().lower()
        obj_parent = find_base_builder_parent_nickname(data.get("_entries", []))
        return (
            obj_nickname == target
            or obj_base == target
            or obj_dock == target
            or str(obj_parent or "").strip().lower() == target
        )

    def _related_base_objects(self, base_nickname: str) -> list[SolarObject]:
        target = str(base_nickname or "").strip().lower()
        if not target:
            return []
        related: list[SolarObject] = []
        for obj in getattr(self, "_objects", []):
            if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                continue
            if self._is_object_related_to_base(obj, target):
                related.append(obj)
        return related

    def _base_display_root_object(self, obj: SolarObject | None) -> SolarObject | None:
        if obj is None or hasattr(obj, "sys_path"):
            return obj
        base_nickname = self._base_nickname_for_object(obj)
        if not base_nickname:
            return obj
        related = self._related_base_objects(base_nickname)
        if not related:
            return obj
        for candidate in related:
            if not self._is_base_builder_child_object(candidate, base_nickname):
                return candidate
        return obj

    def _base_display_child_objects(self, obj: SolarObject | None) -> list[SolarObject]:
        root_obj = self._base_display_root_object(obj)
        if root_obj is None or hasattr(root_obj, "sys_path"):
            return []
        base_nickname = self._base_nickname_for_object(root_obj)
        if not base_nickname:
            return []
        children: list[SolarObject] = []
        for candidate in self._related_base_objects(base_nickname):
            if candidate is root_obj:
                continue
            if self._is_base_builder_child_object(candidate, base_nickname):
                children.append(candidate)
        return children

    def _object_combo_display_objects(self) -> list[SolarObject]:
        display_objects: list[SolarObject] = []
        seen_roots: set[int] = set()
        for obj in getattr(self, "_objects", []):
            if not isinstance(obj, SolarObject):
                continue
            root_obj = self._base_display_root_object(obj)
            if root_obj is None:
                continue
            if root_obj is not obj and self._is_base_builder_child_object(obj):
                root_key = id(root_obj)
                if root_key in seen_roots:
                    continue
                seen_roots.add(root_key)
                display_objects.append(root_obj)
                continue
            root_key = id(root_obj)
            if root_key in seen_roots:
                continue
            seen_roots.add(root_key)
            display_objects.append(root_obj)
        return display_objects

    def _object_combo_display_label(self, obj) -> str:
        label = self._object_display_label(obj)
        if not isinstance(obj, SolarObject):
            return label
        nickname = str(getattr(obj, "nickname", "") or getattr(obj, "data", {}).get("nickname", "") or "").strip()
        child_count = len(self._base_display_child_objects(obj))
        if child_count <= 0:
            return label
        if nickname and nickname.lower() not in label.lower():
            return f"{label} [{nickname}] (+{child_count} parts)"
        return f"{label} (+{child_count} parts)"

    def _object_combo_tooltip(self, obj) -> str:
        if not isinstance(obj, SolarObject):
            return ""
        children = self._base_display_child_objects(obj)
        if not children:
            return ""
        root_nickname = str(getattr(obj, "nickname", "") or getattr(obj, "data", {}).get("nickname", "") or "").strip()
        lines = [f"Multipart base: {root_nickname}", f"Parts: {len(children)}"]
        for child in children:
            child_nickname = str(getattr(child, "nickname", "") or getattr(child, "data", {}).get("nickname", "") or "").strip()
            child_label = self._object_display_label(child)
            if child_nickname and child_nickname.lower() not in child_label.lower():
                lines.append(f"- {child_label} [{child_nickname}]")
            else:
                lines.append(f"- {child_label}")
        return "\n".join(lines)

    @staticmethod
    def _transform_native_preview_geometry(
        geometry: NativePreviewGeometry,
        object_rotation: QQuaternion,
        inverse_root_rotation: QQuaternion,
        offset_world: QVector3D,
    ) -> NativePreviewGeometry:
        transformed_positions: list[tuple[float, float, float]] = []
        for position in getattr(geometry, "positions", ()):
            local_vec = QVector3D(float(position[0]), float(position[1]), float(position[2]))
            world_vec = object_rotation.rotatedVector(local_vec) + offset_world
            root_vec = inverse_root_rotation.rotatedVector(world_vec)
            transformed_positions.append((root_vec.x(), root_vec.y(), root_vec.z()))
        transformed_bounds = aggregate_native_preview_bounds((replace(geometry, positions=tuple(transformed_positions)),))
        return replace(geometry, positions=tuple(transformed_positions), bounds=transformed_bounds)

    def _resolve_system_view_native_scene_data_for_object(self, obj) -> object | None:
        if self._is_base_builder_child_object(obj):
            return self._resolve_native_scene_data_for_object(obj)
        root_obj = self._base_display_root_object(obj)
        if not isinstance(root_obj, SolarObject):
            return self._resolve_native_scene_data_for_object(obj)
        child_objects = self._base_display_child_objects(root_obj)
        if not child_objects:
            return self._resolve_native_scene_data_for_object(root_obj)

        part_objects = [root_obj, *child_objects]
        root_position = parse_position(str(getattr(root_obj, "data", {}).get("pos", "0, 0, 0") or "0, 0, 0"))
        root_rotation = rotation_quaternion_from_fl(*self._get_object_rotate(root_obj))
        inverse_root_rotation = root_rotation.conjugated()

        aggregated_geometries: list[NativePreviewGeometry] = []
        aggregated_all_geometries: list[NativePreviewGeometry] = []
        aggregated_texture_paths: list[str | None] = []
        aggregated_all_texture_paths: list[str | None] = []
        texture_path = None
        cmp_up_correction = (0.0, 0.0, 0.0)
        cmp_orientation_debug_rows: tuple[tuple[str, str], ...] = ()
        cmp_transform_hints = ()

        for part_obj in part_objects:
            scene_data = self._resolve_native_scene_data_for_object(part_obj)
            if scene_data is None:
                continue
            part_position = parse_position(str(getattr(part_obj, "data", {}).get("pos", "0, 0, 0") or "0, 0, 0"))
            offset_world = QVector3D(
                float(part_position[0] - root_position[0]),
                float(part_position[1] - root_position[1]),
                float(part_position[2] - root_position[2]),
            )
            object_rotation = rotation_quaternion_from_fl(*self._get_object_rotate(part_obj))
            transformed_geometries = [
                self._transform_native_preview_geometry(geometry, object_rotation, inverse_root_rotation, offset_world)
                for geometry in getattr(scene_data, "geometries", ())
            ]
            transformed_all_geometries = [
                self._transform_native_preview_geometry(geometry, object_rotation, inverse_root_rotation, offset_world)
                for geometry in getattr(scene_data, "all_geometries", ())
            ]
            aggregated_geometries.extend(transformed_geometries)
            aggregated_all_geometries.extend(transformed_all_geometries)

            geometry_texture_paths = list(getattr(scene_data, "geometry_texture_paths", ()) or ())
            if transformed_geometries:
                if len(geometry_texture_paths) < len(transformed_geometries):
                    geometry_texture_paths.extend([None] * (len(transformed_geometries) - len(geometry_texture_paths)))
                aggregated_texture_paths.extend(geometry_texture_paths[: len(transformed_geometries)])

            all_geometry_texture_paths = list(getattr(scene_data, "all_geometry_texture_paths", ()) or ())
            if transformed_all_geometries:
                if len(all_geometry_texture_paths) < len(transformed_all_geometries):
                    all_geometry_texture_paths.extend([None] * (len(transformed_all_geometries) - len(all_geometry_texture_paths)))
                aggregated_all_texture_paths.extend(all_geometry_texture_paths[: len(transformed_all_geometries)])

            if texture_path is None:
                texture_path = getattr(scene_data, "texture_path", None)
            if cmp_up_correction == (0.0, 0.0, 0.0):
                cmp_up_correction = tuple(
                    getattr(scene_data, "cmp_up_correction_euler_deg", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0)
                )
            if not cmp_orientation_debug_rows:
                cmp_orientation_debug_rows = tuple(getattr(scene_data, "cmp_orientation_debug_rows", ()) or ())
            if not cmp_transform_hints:
                cmp_transform_hints = tuple(getattr(scene_data, "cmp_transform_hints", ()) or ())

        if not aggregated_geometries:
            return self._resolve_native_scene_data_for_object(root_obj)

        bounds = aggregate_native_preview_bounds(tuple(aggregated_geometries))
        all_geometries = tuple(aggregated_all_geometries) if aggregated_all_geometries else tuple(aggregated_geometries)
        return NativePreviewSceneData(
            geometries=tuple(aggregated_geometries),
            primary_geometry=aggregated_geometries[0],
            bounds=bounds,
            part_names=tuple(
                str(getattr(part_obj, "nickname", "") or "") for part_obj in part_objects if str(getattr(part_obj, "nickname", "") or "")
            ),
            texture_path=texture_path,
            geometry_texture_paths=tuple(aggregated_texture_paths),
            all_geometries=all_geometries,
            all_geometry_texture_paths=tuple(aggregated_all_texture_paths) if aggregated_all_texture_paths else tuple(aggregated_texture_paths),
            cmp_orientation_debug_rows=cmp_orientation_debug_rows,
            cmp_up_correction_euler_deg=cmp_up_correction,
            cmp_transform_hints=cmp_transform_hints,
        )

    def _resolve_system_view_native_scene_prepared_payload_for_object(self, obj) -> object | None:
        if self._is_base_builder_child_object(obj):
            return self._resolve_native_scene_prepared_payload_for_object(obj)
        root_obj = self._base_display_root_object(obj)
        if not isinstance(root_obj, SolarObject):
            return self._resolve_native_scene_prepared_payload_for_object(obj)
        if not self._base_display_child_objects(root_obj):
            return self._resolve_native_scene_prepared_payload_for_object(root_obj)
        scene_data = self._resolve_system_view_native_scene_data_for_object(root_obj)
        if scene_data is None:
            return None
        return SimpleNamespace(scene_data=scene_data, geometry_count=len(getattr(scene_data, "geometries", ()) or ()))

    def _set_active_base_focus(self, base_nickname: str | None) -> None:
        self._base_builder_active_base_nick = str(base_nickname or "").strip() or None
        self._apply_group_visibility()
        self._refresh_base_builder_dialog_state(refresh_parts=True)

    def _reset_base_builder_draft_state(self) -> None:
        self._base_builder_draft_root_obj = None
        self._base_builder_draft_parts = []
        self._base_builder_selected_object = None
        self._base_builder_draft_source_by_nickname = {}
        self._base_builder_history = []
        self._base_builder_history_index = -1
        self._base_builder_saved_history_index = -1

    def _create_base_builder_draft_object(self, entries: list[tuple[str, str]] | list[list[str]]) -> SolarObject:
        clone = SolarObject(self._entries_to_data(list(entries or [])), self._scale)
        if hasattr(clone, "set_label_visibility"):
            clone.set_label_visibility(False)
        clone.setFlag(QGraphicsItem.ItemIsMovable, False)
        return clone

    def _clone_object_for_base_builder(self, obj: SolarObject) -> SolarObject:
        return self._create_base_builder_draft_object(list(obj.data.get("_entries", [])))

    def _base_builder_draft_objects(self) -> list[SolarObject]:
        objects: list[SolarObject] = []
        if isinstance(self._base_builder_draft_root_obj, SolarObject):
            objects.append(self._base_builder_draft_root_obj)
        objects.extend([obj for obj in self._base_builder_draft_parts if isinstance(obj, SolarObject)])
        return objects

    def _base_builder_is_draft_object(self, obj: SolarObject | None) -> bool:
        if not isinstance(obj, SolarObject):
            return False
        if obj is self._base_builder_draft_root_obj:
            return True
        return any(obj is part for part in self._base_builder_draft_parts)

    def _find_base_builder_draft_object_by_nickname(self, nickname: str) -> SolarObject | None:
        target = str(nickname or "").strip().lower()
        if not target:
            return None
        for obj in self._base_builder_draft_objects():
            if str(getattr(obj, "nickname", "") or "").strip().lower() == target:
                return obj
        return None

    def _initialize_base_builder_draft(self, base_nickname: str, selected_obj: SolarObject | None = None) -> None:
        self._reset_base_builder_draft_state()
        root_obj = self._base_display_root_object(selected_obj) if isinstance(selected_obj, SolarObject) else None
        if not isinstance(root_obj, SolarObject):
            root_obj = None
            for candidate in self._related_base_objects(base_nickname):
                if not self._is_base_builder_child_object(candidate, base_nickname):
                    root_obj = candidate
                    break
        if root_obj is None:
            return
        self._base_builder_draft_root_obj = self._clone_object_for_base_builder(root_obj)
        self._base_builder_draft_source_by_nickname[str(root_obj.nickname or "").strip().lower()] = root_obj
        for child in self._base_display_child_objects(root_obj):
            draft_child = self._clone_object_for_base_builder(child)
            self._base_builder_draft_parts.append(draft_child)
            self._base_builder_draft_source_by_nickname[str(draft_child.nickname or "").strip().lower()] = child
        if isinstance(selected_obj, SolarObject):
            selected_nickname = str(getattr(selected_obj, "nickname", "") or "").strip()
            self._base_builder_selected_object = self._find_base_builder_draft_object_by_nickname(selected_nickname)
        self._base_builder_reset_history()

    def _base_builder_snapshot_source_nickname(self, draft_obj: SolarObject | None) -> str | None:
        if not isinstance(draft_obj, SolarObject):
            return None
        draft_nickname = str(getattr(draft_obj, "nickname", "") or "").strip().lower()
        if not draft_nickname:
            return None
        source_obj = self._base_builder_draft_source_by_nickname.get(draft_nickname)
        if not isinstance(source_obj, SolarObject):
            return None
        source_nickname = str(getattr(source_obj, "nickname", "") or "").strip()
        return source_nickname or None

    def _capture_base_builder_snapshot(self, label: str) -> dict[str, object] | None:
        if self._base_builder_draft_root_obj is None:
            return None
        return {
            "label": str(label or "Base Builder"),
            "ts": datetime.now().strftime("%H:%M:%S"),
            "selected_nickname": str(getattr(self._base_builder_selected_object, "nickname", "") or "").strip(),
            "root": {
                "entries": [list(pair) for pair in self._base_builder_draft_root_obj.data.get("_entries", [])],
                "source_nickname": self._base_builder_snapshot_source_nickname(self._base_builder_draft_root_obj),
            },
            "parts": [
                {
                    "entries": [list(pair) for pair in obj.data.get("_entries", [])],
                    "source_nickname": self._base_builder_snapshot_source_nickname(obj),
                }
                for obj in self._base_builder_draft_parts
                if isinstance(obj, SolarObject)
            ],
        }

    def _restore_base_builder_snapshot(self, snapshot: dict[str, object]) -> None:
        root_state = snapshot.get("root") if isinstance(snapshot, dict) else None
        if not isinstance(root_state, dict):
            return
        self._base_builder_draft_root_obj = None
        self._base_builder_draft_parts = []
        self._base_builder_selected_object = None
        self._base_builder_draft_source_by_nickname = {}

        root_entries = list(root_state.get("entries", []) or [])
        if root_entries:
            root_obj = self._create_base_builder_draft_object(root_entries)
            self._base_builder_draft_root_obj = root_obj
            root_nick = str(getattr(root_obj, "nickname", "") or "").strip().lower()
            if root_nick:
                source_nick = str(root_state.get("source_nickname", "") or "").strip()
                self._base_builder_draft_source_by_nickname[root_nick] = self._find_scene_object_by_nickname(source_nick)

        for row in list(snapshot.get("parts", []) or []):
            if not isinstance(row, dict):
                continue
            part_entries = list(row.get("entries", []) or [])
            if not part_entries:
                continue
            part_obj = self._create_base_builder_draft_object(part_entries)
            self._base_builder_draft_parts.append(part_obj)
            part_nick = str(getattr(part_obj, "nickname", "") or "").strip().lower()
            if part_nick:
                source_nick = str(row.get("source_nickname", "") or "").strip()
                self._base_builder_draft_source_by_nickname[part_nick] = self._find_scene_object_by_nickname(source_nick)

        selected_nickname = str(snapshot.get("selected_nickname", "") or "").strip()
        self._base_builder_selected_object = self._find_base_builder_draft_object_by_nickname(selected_nickname)

    def _base_builder_reset_history(self) -> None:
        snapshot = self._capture_base_builder_snapshot("Initial state")
        if snapshot is None:
            self._base_builder_history = []
            self._base_builder_history_index = -1
            self._base_builder_saved_history_index = -1
            return
        self._base_builder_history = [snapshot]
        self._base_builder_history_index = 0
        self._base_builder_saved_history_index = 0

    def _base_builder_push_history(self, label: str) -> None:
        snapshot = self._capture_base_builder_snapshot(label)
        if snapshot is None:
            return
        next_index = self._base_builder_history_index + 1
        if next_index < len(self._base_builder_history):
            self._base_builder_history = self._base_builder_history[:next_index]
            if self._base_builder_saved_history_index >= next_index:
                self._base_builder_saved_history_index = next_index - 1
        self._base_builder_history.append(snapshot)
        self._base_builder_history_index = len(self._base_builder_history) - 1

    def _base_builder_mark_saved(self) -> None:
        self._base_builder_saved_history_index = self._base_builder_history_index

    def _base_builder_has_unsaved_changes(self) -> bool:
        if self._base_builder_history_index < 0:
            return False
        return self._base_builder_history_index != self._base_builder_saved_history_index

    def _base_builder_history_rows(self) -> list[dict[str, object]]:
        rows: list[dict[str, object]] = []
        for index, snapshot in enumerate(self._base_builder_history):
            if not isinstance(snapshot, dict):
                continue
            rows.append(
                {
                    "label": str(snapshot.get("label", "Base Builder") or "Base Builder"),
                    "timestamp": str(snapshot.get("ts", "") or "").strip(),
                    "is_current": index == self._base_builder_history_index,
                    "is_saved": index == self._base_builder_saved_history_index,
                }
            )
        return rows

    def _base_builder_undo(self) -> bool:
        self._base_builder_end_transform(commit=True)
        if self._base_builder_history_index <= 0:
            return False
        next_index = self._base_builder_history_index - 1
        if next_index < 0 or next_index >= len(self._base_builder_history):
            return False
        snapshot = self._base_builder_history[next_index]
        if not isinstance(snapshot, dict):
            return False
        self._base_builder_history_index = next_index
        self._restore_base_builder_snapshot(snapshot)
        self._refresh_base_builder_dialog_state(refresh_parts=True)
        self.statusBar().showMessage(f"Base Builder undo: {snapshot.get('label', 'previous state')}")
        return True

    def _base_builder_select_object(self, obj) -> None:
        if obj is not None and not self._base_builder_is_draft_object(obj):
            if isinstance(obj, SolarObject) and self._is_object_related_to_base(obj, self._base_builder_active_base_nick):
                self._select(obj)
                self._refresh_base_builder_dialog_state()
            return
        self._base_builder_selected_object = obj if isinstance(obj, SolarObject) else None
        self._refresh_base_builder_dialog_state()

    def _base_builder_clear_selection(self) -> None:
        self._base_builder_selected_object = None
        self._refresh_base_builder_dialog_state()

    def _remove_object_for_base_builder_save(self, obj: SolarObject) -> None:
        try:
            obj_idx = self._objects.index(obj)
        except ValueError:
            obj_idx = None
        if obj_idx is not None:
            sec_idx = self._section_index_for_object_index(obj_idx)
            if sec_idx is not None and 0 <= sec_idx < len(self._sections):
                self._sections.pop(sec_idx)
        try:
            self.view._scene.removeItem(obj)
        except Exception:
            pass
        if obj in self._objects:
            self._objects.remove(obj)

    def _apply_base_builder_draft_to_real_object(self, real_obj: SolarObject, draft_obj: SolarObject) -> None:
        real_obj.data = self._entries_to_data(list(draft_obj.data.get("_entries", [])))
        real_obj.nickname = real_obj.data.get("nickname", real_obj.nickname)
        if getattr(real_obj, "label", None) is not None:
            real_obj.label.setPlainText(real_obj.nickname)
        px, _py, pz = self._parse_vec3(real_obj.data.get("pos", "0,0,0"))
        pos_cb = getattr(real_obj, "_pos_change_cb", None)
        try:
            real_obj._pos_change_cb = None
            real_obj.setPos(px * self._scale, pz * self._scale)
        finally:
            real_obj._pos_change_cb = pos_cb
        try:
            real_obj._apply_rotation_from_data()
        except Exception:
            pass
        try:
            real_obj.refresh_top_view_icon()
        except Exception:
            pass
        self._sync_object_section_from_obj(real_obj)

    def _sync_base_builder_draft_object_from_real_object(self, draft_obj: SolarObject, real_obj: SolarObject) -> None:
        if not isinstance(draft_obj, SolarObject) or not isinstance(real_obj, SolarObject):
            return
        draft_obj.data = self._entries_to_data(list(real_obj.data.get("_entries", [])))
        draft_obj.nickname = draft_obj.data.get("nickname", draft_obj.nickname)
        try:
            draft_obj._apply_rotation_from_data()
        except Exception:
            pass
        px, _py, pz = self._parse_vec3(draft_obj.data.get("pos", "0,0,0"))
        pos_cb = getattr(draft_obj, "_pos_change_cb", None)
        try:
            draft_obj._pos_change_cb = None
            draft_obj.setPos(px * self._scale, pz * self._scale)
        finally:
            draft_obj._pos_change_cb = pos_cb
        draft_nickname = str(getattr(draft_obj, "nickname", "") or "").strip().lower()
        if draft_nickname:
            self._base_builder_draft_source_by_nickname[draft_nickname] = real_obj

    def _commit_base_builder_draft(self) -> SolarObject | None:
        active_base = str(self._base_builder_active_base_nick or "").strip()
        if not active_base or self._base_builder_draft_root_obj is None:
            return None
        draft_parts = list(self._base_builder_draft_parts)
        selected_nickname = str(getattr(self._base_builder_selected_object, "nickname", "") or "").strip().lower()
        draft_by_nickname = {
            str(getattr(obj, "nickname", "") or "").strip().lower(): obj
            for obj in draft_parts
        }
        selected_real_obj: SolarObject | None = None

        for real_obj in list(self._objects):
            if not isinstance(real_obj, SolarObject) or hasattr(real_obj, "sys_path"):
                continue
            if not self._is_base_builder_child_object(real_obj, active_base):
                continue
            real_nickname = str(real_obj.nickname or "").strip().lower()
            draft_obj = draft_by_nickname.get(real_nickname)
            if draft_obj is None:
                self._remove_object_for_base_builder_save(real_obj)
                continue
            self._apply_base_builder_draft_to_real_object(real_obj, draft_obj)
            self._sync_base_builder_draft_object_from_real_object(draft_obj, real_obj)
            if selected_nickname and real_nickname == selected_nickname:
                selected_real_obj = real_obj

        for draft_obj in draft_parts:
            draft_nickname = str(getattr(draft_obj, "nickname", "") or "").strip().lower()
            source_obj = self._base_builder_draft_source_by_nickname.get(draft_nickname)
            if isinstance(source_obj, SolarObject) and source_obj in self._objects:
                continue
            created_obj = self._add_object_from_entries(
                list(draft_obj.data.get("_entries", [])),
                "Object",
                refresh_3d=False,
                select_created=False,
                push_undo=False,
                refresh_builder=False,
                rebuild_combo=False,
            )
            if isinstance(created_obj, SolarObject):
                self._sync_base_builder_draft_object_from_real_object(draft_obj, created_obj)
                if selected_nickname and draft_nickname == selected_nickname:
                    selected_real_obj = created_obj

        return selected_real_obj

    def _find_scene_object_by_nickname(self, nickname: str) -> SolarObject | None:
        target = str(nickname or "").strip().lower()
        if not target:
            return None
        for obj in getattr(self, "_objects", []):
            if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                continue
            if str(obj.nickname or "").strip().lower() == target:
                return obj
        return None

    def _collect_base_builder_part_entries(self) -> list[ModelViewerEntry]:
        game_path = self._primary_game_path()
        if not game_path:
            return []
        allowed_archetypes = {
            str(a).strip().lower() for a in self._base_archetypes_from_solararch(game_path) if str(a).strip()
        }
        entries: list[ModelViewerEntry] = []
        seen: set[str] = set()
        for entry in self._collect_3d_model_viewer_entries():
            arch_key = str(entry.archetype or "").strip().lower()
            if not arch_key:
                continue
            if allowed_archetypes and arch_key not in allowed_archetypes and entry.category_key != "stations":
                continue
            if arch_key in seen:
                continue
            seen.add(arch_key)
            entries.append(entry)
        entries.sort(key=lambda entry: ((entry.display_name or entry.nickname).lower(), entry.archetype.lower()))
        return entries

    def _base_builder_existing_parts(self, base_nickname: str) -> list[dict[str, str]]:
        target = str(base_nickname or "").strip().lower()
        rows: list[dict[str, str]] = []
        if not target:
            return rows
        if str(self._base_builder_active_base_nick or "").strip().lower() == target and self._base_builder_draft_parts:
            for obj in self._base_builder_draft_parts:
                rows.append(
                    {
                        "nickname": str(obj.nickname or "").strip(),
                        "label": self._object_display_label(obj),
                        "archetype": str(obj.data.get("archetype", "") or "").strip(),
                    }
                )
            rows.sort(key=lambda row: (str(row.get("label", "")).lower(), str(row.get("nickname", "")).lower()))
            return rows
        for obj in getattr(self, "_objects", []):
            if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                continue
            if not self._is_base_builder_child_object(obj, target):
                continue
            rows.append(
                {
                    "nickname": str(obj.nickname or "").strip(),
                    "label": self._object_display_label(obj),
                    "archetype": str(obj.data.get("archetype", "") or "").strip(),
                }
            )
        rows.sort(key=lambda row: (str(row.get("label", "")).lower(), str(row.get("nickname", "")).lower()))
        return rows

    def _base_builder_scene_payload(self) -> tuple[list[SolarObject], list[object], float]:
        active = str(self._base_builder_active_base_nick or "").strip()
        draft_objects = self._base_builder_draft_objects()
        if active and draft_objects:
            return (draft_objects, [], float(self._scale))
        return (self._related_base_objects(active), [], float(self._scale))

    def _configure_base_builder_3d_view(self, view3d) -> None:
        if view3d is None:
            return
        if hasattr(view3d, "set_native_scene_resolver"):
            view3d.set_native_scene_resolver(self._resolve_native_scene_data_for_object)
        if hasattr(view3d, "set_native_scene_prepared_payload_resolver"):
            view3d.set_native_scene_prepared_payload_resolver(self._resolve_native_scene_prepared_payload_for_object)
        if hasattr(view3d, "set_preview_mesh_resolver"):
            view3d.set_preview_mesh_resolver(self._resolve_preview_mesh_for_object)
        if hasattr(view3d, "set_planet_texture_resolver"):
            view3d.set_planet_texture_resolver(self._resolve_planet_texture_for_object)
        if hasattr(view3d, "set_planet_cloud_texture_resolver"):
            view3d.set_planet_cloud_texture_resolver(self._resolve_planet_cloud_texture_for_object)
        if hasattr(view3d, "set_planet_ring_resolver"):
            view3d.set_planet_ring_resolver(self._resolve_planet_ring_render_info_for_object)
        if hasattr(view3d, "set_native_preview_max_distance_fl"):
            view3d.set_native_preview_max_distance_fl(-1.0)
        if hasattr(view3d, "set_native_preview_high_quality_distance_fl"):
            view3d.set_native_preview_high_quality_distance_fl(1000000.0)
        if hasattr(view3d, "set_native_wireframe_visible"):
            view3d.set_native_wireframe_visible(True)
        if hasattr(view3d, "set_reference_overlay_visible"):
            view3d.set_reference_overlay_visible(False)
        if hasattr(view3d, "set_label_visibility"):
            view3d.set_label_visibility(False)
        if hasattr(view3d, "set_max_orbit_distance_scene"):
            view3d.set_max_orbit_distance_scene(3500.0)
        try:
            view3d._native_preview_visibility_stable_ms = 0
            view3d._native_preview_camera_idle_delay_ms = 0
            view3d._native_preview_free_camera_idle_delay_ms = 0
            view3d._native_preview_batch_size = 8
            view3d._native_preview_geometry_batch_size = 32
            view3d._native_preview_max_active_count = 64
            view3d._native_preview_force_coarsest_lod = False
        except Exception:
            pass

    def _refresh_base_builder_dialog_scene(self) -> None:
        dlg = self._base_builder_dialog
        if dlg is None or not isValid(dlg):
            return
        try:
            dlg.refresh_existing_parts()
        except Exception:
            pass

    def _refresh_base_builder_dialog_parts(self) -> None:
        dlg = self._base_builder_dialog
        if dlg is None or not isValid(dlg):
            return
        self._refresh_base_builder_dialog_state(refresh_parts=True)

    def _base_builder_selected_part(self) -> SolarObject | None:
        obj = self._base_builder_selected_object or self._selected
        active = str(self._base_builder_active_base_nick or "").strip().lower()
        if not active or not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
            return None
        if not self._is_base_builder_child_object(obj, active):
            return None
        return obj

    def _refresh_base_builder_dialog_state(self, *, refresh_parts: bool = False) -> None:
        dlg = self._base_builder_dialog
        if dlg is None or not isValid(dlg):
            return
        if refresh_parts:
            self._refresh_base_builder_dialog_scene()
        selected_part = self._base_builder_selected_part()
        if selected_part is not None:
            label = self._object_display_label(selected_part)
            can_transform = True
            can_delete = True
            focus_obj = selected_part
        else:
            selected_obj = self._base_builder_selected_object
            if isinstance(selected_obj, SolarObject):
                label = self._object_display_label(selected_obj)
                focus_obj = selected_obj
            elif isinstance(self._base_builder_draft_root_obj, SolarObject):
                label = self._object_display_label(self._base_builder_draft_root_obj)
                focus_obj = self._base_builder_draft_root_obj
            elif isinstance(self._selected, SolarObject):
                label = self._object_display_label(self._selected)
                focus_obj = self._selected
            elif self._selected is None:
                label = "no object selected"
                focus_obj = None
            else:
                label = "zone selected"
                focus_obj = None
            can_transform = False
            can_delete = False
        try:
            dlg.set_selected_scene_object(
                scene_object=focus_obj,
                label=label,
                can_transform=can_transform,
                can_delete=can_delete,
            )
        except Exception:
            pass
        if hasattr(dlg, "refresh_history"):
            try:
                dlg.refresh_history()
            except Exception:
                pass
        if hasattr(dlg, "set_dirty_state"):
            try:
                dlg.set_dirty_state(self._base_builder_has_unsaved_changes())
            except Exception:
                pass

    def _update_base_builder_dialog_object_position(self, obj: SolarObject) -> None:
        dlg = self._base_builder_dialog
        if dlg is None or not isValid(dlg):
            return
        if not self._is_object_related_to_base(obj, self._base_builder_active_base_nick):
            return
        try:
            dlg.update_scene_object_position(obj, self._scale)
        except Exception:
            self._refresh_base_builder_dialog_scene()

    def _update_base_builder_dialog_object_rotation(self, obj: SolarObject) -> None:
        dlg = self._base_builder_dialog
        if dlg is None or not isValid(dlg):
            return
        if not self._is_object_related_to_base(obj, self._base_builder_active_base_nick):
            return
        try:
            dlg.update_scene_object_rotation(obj)
        except Exception:
            self._refresh_base_builder_dialog_scene()

    def _close_base_builder(self) -> None:
        self._base_builder_end_transform(commit=True)
        self._set_active_base_focus(None)
        self._base_builder_dialog = None
        self._reset_base_builder_draft_state()
        if hasattr(self, "view3d") and hasattr(self.view3d, "update"):
            try:
                self.view3d.update()
            except Exception:
                pass

    def _base_builder_select_existing_part(self, nickname: str) -> None:
        obj = self._find_base_builder_draft_object_by_nickname(nickname)
        if obj is None:
            obj = self._find_scene_object_by_nickname(nickname)
        if obj is None:
            return
        if self._base_builder_is_draft_object(obj):
            self._base_builder_selected_object = obj
        else:
            self._select(obj)
        self._refresh_base_builder_dialog_state()

    def _base_builder_delete_selected_part(self) -> None:
        obj = self._base_builder_selected_part()
        if obj is None:
            return
        if self._base_builder_is_draft_object(obj):
            obj_label = self._object_display_label(obj)
            self._base_builder_draft_parts = [part for part in self._base_builder_draft_parts if part is not obj]
            if self._base_builder_selected_object is obj:
                self._base_builder_selected_object = None
            self._base_builder_push_history(f"Deleted part: {obj_label}")
            self._refresh_base_builder_dialog_state(refresh_parts=True)
            return
        self._delete_solar_object(obj)

    def _base_builder_save(self) -> None:
        if not self._filepath:
            return
        self._base_builder_end_transform(commit=True)
        selected_real_obj = self._commit_base_builder_draft()
        self._rebuild_object_combo()
        self._set_dirty(True)
        self._write_to_file(reload=False)
        self._refresh_3d_scene(preserve_camera=True)
        if isinstance(selected_real_obj, SolarObject):
            self._select(selected_real_obj)
        self._base_builder_mark_saved()
        self._refresh_base_builder_dialog_state(refresh_parts=True)
        self.statusBar().showMessage(tr("status.base_builder_saved"))

    def _base_builder_default_part_pos_xyz(
        self,
        base_obj: SolarObject,
        base_nickname: str,
    ) -> tuple[float, float, float]:
        px, py, pz = self._parse_vec3(base_obj.data.get("pos", "0,0,0"))
        active_target = str(self._base_builder_active_base_nick or "").strip().lower()
        if active_target and active_target == str(base_nickname or "").strip().lower() and self._base_builder_draft_parts:
            existing_children = len(self._base_builder_draft_parts)
        else:
            existing_children = len(self._base_display_child_objects(base_obj))
        slot_index = max(0, int(existing_children))
        ring_index = slot_index // 8
        angle_deg = float((slot_index % 8) * 45.0)
        radius = 140.0 + (float(ring_index) * 90.0)
        angle_rad = math.radians(angle_deg)
        local_offset = QVector3D(
            float(math.cos(angle_rad) * radius),
            0.0,
            float(math.sin(angle_rad) * radius),
        )
        base_rotation = rotation_quaternion_from_fl(*self._get_object_rotate(base_obj))
        world_offset = base_rotation.rotatedVector(local_offset)
        return (
            float(px + world_offset.x()),
            float(py + world_offset.y()),
            float(pz + world_offset.z()),
        )

    def _base_builder_set_object_pos_xyz(self, obj: SolarObject, pos_xyz: tuple[float, float, float]) -> None:
        px, py, pz = (float(pos_xyz[0]), float(pos_xyz[1]), float(pos_xyz[2]))
        pos_str = f"{px:.2f}, {py:.2f}, {pz:.2f}"
        obj.data["_entries"] = [
            (k, pos_str if k.lower() == "pos" else v) for k, v in obj.data.get("_entries", [])
        ]
        obj.data["pos"] = pos_str
        pos_cb = getattr(obj, "_pos_change_cb", None)
        try:
            obj._pos_change_cb = None
            obj.setPos(px * self._scale, pz * self._scale)
        finally:
            obj._pos_change_cb = pos_cb
        if self._base_builder_is_draft_object(obj):
            self._update_base_builder_dialog_object_position(obj)
            return
        self._sync_object_section_from_obj(obj)
        if self._selected is obj:
            self.editor.setPlainText(obj.raw_text())
        self._set_dirty(True)
        if hasattr(self, "view3d") and hasattr(self.view3d, "update_object_position"):
            self.view3d.update_object_position(obj, self._scale)
        self._update_base_builder_dialog_object_position(obj)

    def _base_builder_begin_transform(self, mode: str, axis: str) -> bool:
        obj = self._base_builder_selected_part()
        if obj is None:
            return False
        self._base_builder_transform_state = {
            "obj": obj,
            "mode": str(mode),
            "axis": str(axis).lower(),
            "start_pos": self._parse_vec3(obj.data.get("pos", "0,0,0")),
            "start_rot": self._get_object_rotate(obj),
            "old_entries": [(str(k), str(v)) for k, v in obj.data.get("_entries", [])],
        }
        return True

    def _base_builder_apply_transform_delta(self, delta: float) -> None:
        state = self._base_builder_transform_state
        if not isinstance(state, dict):
            return
        obj = state.get("obj")
        if not isinstance(obj, SolarObject):
            return
        axis_map = {"x": 0, "y": 1, "z": 2}
        axis_idx = axis_map.get(str(state.get("axis", "")).lower())
        if axis_idx is None:
            return
        mode = str(state.get("mode", "")).lower()
        signed_delta = float(delta)
        try:
            modifiers = QApplication.keyboardModifiers()
        except Exception:
            modifiers = Qt.NoModifier
        fine_mode = bool(modifiers & Qt.ShiftModifier)
        snap_mode = bool(modifiers & Qt.ControlModifier)
        if mode == "move":
            sensitivity = {0: 6.0, 1: 4.0, 2: 6.0}.get(axis_idx, 5.0)
            if fine_mode:
                sensitivity *= 0.25
            pos = list(state.get("start_pos", (0.0, 0.0, 0.0)))
            pos[axis_idx] = float(pos[axis_idx]) + signed_delta * sensitivity
            if snap_mode:
                pos[axis_idx] = round(float(pos[axis_idx]))
            self._base_builder_set_object_pos_xyz(obj, (pos[0], pos[1], pos[2]))
            return
        if mode == "rotate":
            sensitivity = 0.2
            if fine_mode:
                sensitivity *= 0.25
            rot = list(state.get("start_rot", (0.0, 0.0, 0.0)))
            next_angle = float(rot[axis_idx]) + signed_delta * sensitivity
            if snap_mode:
                step = 5.0
                if abs(next_angle) >= 1e-9:
                    next_angle = math.copysign(max(step, math.ceil(abs(next_angle) / step) * step), next_angle)
            rot[axis_idx] = self._normalize_angle_180(next_angle)
            self._set_object_rotate(obj, (rot[0], rot[1], rot[2]))
            if self._base_builder_is_draft_object(obj):
                self._update_base_builder_dialog_object_rotation(obj)
                return
            self._sync_object_section_from_obj(obj)
            self._set_dirty(True)
            if hasattr(self, "view3d") and hasattr(self.view3d, "update_object_rotation"):
                self.view3d.update_object_rotation(obj)
            self._update_base_builder_dialog_object_rotation(obj)

    def _base_builder_end_transform(self, commit: bool) -> None:
        state = self._base_builder_transform_state
        self._base_builder_transform_state = None
        if not isinstance(state, dict):
            return
        obj = state.get("obj")
        if not isinstance(obj, SolarObject):
            return
        old_entries = [(str(k), str(v)) for k, v in state.get("old_entries", [])]
        if not commit:
            if old_entries:
                obj.data = self._entries_to_data(old_entries)
                obj.nickname = obj.data.get("nickname", obj.nickname)
                fx, _fy, fz = parse_position(obj.data.get("pos", "0,0,0"))
                obj.setPos(fx * self._scale, fz * self._scale)
                if self._base_builder_is_draft_object(obj):
                    try:
                        obj._apply_rotation_from_data()
                    except Exception:
                        pass
                    self._update_base_builder_dialog_object_position(obj)
                    self._update_base_builder_dialog_object_rotation(obj)
                    self._refresh_base_builder_dialog_state()
                    return
                self._sync_object_section_from_obj(obj)
                if self._selected is obj:
                    self.editor.setPlainText(obj.raw_text())
                if hasattr(self, "view3d") and hasattr(self.view3d, "update_object_position"):
                    self.view3d.update_object_position(obj, self._scale)
                if hasattr(self, "view3d") and hasattr(self.view3d, "update_object_rotation"):
                    self.view3d.update_object_rotation(obj)
                self._update_base_builder_dialog_object_position(obj)
                self._update_base_builder_dialog_object_rotation(obj)
            return
        if self._base_builder_is_draft_object(obj):
            new_entries = [(str(k), str(v)) for k, v in obj.data.get("_entries", [])]
            if new_entries != old_entries:
                mode = str(state.get("mode", "") or "").strip().lower()
                obj_label = self._object_display_label(obj)
                if mode == "rotate":
                    self._base_builder_push_history(f"Rotated part: {obj_label}")
                else:
                    self._base_builder_push_history(f"Moved part: {obj_label}")
            self._refresh_base_builder_dialog_state()
            return
        new_entries = [(str(k), str(v)) for k, v in obj.data.get("_entries", [])]
        if new_entries == old_entries:
            return
        try:
            obj_idx = self._objects.index(obj)
        except ValueError:
            obj_idx = None
        self._push_undo_action(
            {
                "type": "edit_object",
                "label": f"Objekt bearbeitet: {obj.nickname}",
                "filepath": self._filepath or "",
                "object_index": obj_idx,
                "old_nickname": str(self._entry_get_value(old_entries, "nickname") or obj.nickname),
                "new_nickname": str(obj.nickname),
                "old_entries": [list(p) for p in old_entries],
                "new_entries": [list(p) for p in new_entries],
            }
        )
        self._append_change_log(f"Objekt bearbeitet: {obj.nickname}")
        self._write_to_file(reload=False)
        self._refresh_base_builder_dialog_state(refresh_parts=True)

    def _base_builder_add_part(self, base_nickname: str, entry: ModelViewerEntry) -> None:
        target_base = str(base_nickname or "").strip()
        base_obj = self._base_builder_draft_root_obj
        if not isinstance(base_obj, SolarObject):
            base_obj = None
            for obj in getattr(self, "_objects", []):
                if not isinstance(obj, SolarObject) or hasattr(obj, "sys_path"):
                    continue
                if self._is_base_builder_child_object(obj):
                    continue
                if self._base_nickname_for_object(obj).lower() == target_base.lower():
                    base_obj = obj
                    break
        if base_obj is None:
            QMessageBox.warning(self, tr("msg.no_base"), tr("msg.base_builder_base_missing"))
            return
        existing_nicknames = [
            str(obj.nickname or "")
            for obj in [*self._objects, *self._base_builder_draft_parts]
            if isinstance(obj, SolarObject)
        ]
        nickname = suggest_base_builder_part_nickname(target_base, existing_nicknames)
        px, py, pz = self._base_builder_default_part_pos_xyz(base_obj, target_base)
        rx, ry, rz = self._get_object_rotate(base_obj)
        reputation = self._normalize_reputation_value(str(base_obj.data.get("reputation", "") or "").strip())
        loadout_map = self._base_default_loadouts_from_solararch(self._primary_game_path() or "")
        loadout = str(loadout_map.get(str(entry.archetype or "").strip().lower(), "") or "").strip()
        entries = build_base_builder_part_entries(
            base_nickname=target_base,
            part_nickname=nickname,
            archetype=str(entry.archetype or "").strip(),
            pos_xyz=(px, py, pz),
            rotate_xyz=(rx, ry, rz),
            reputation=reputation,
            loadout=loadout,
        )
        new_obj = SolarObject(self._entries_to_data(entries), self._scale)
        if hasattr(new_obj, "set_label_visibility"):
            new_obj.set_label_visibility(False)
        new_obj.setFlag(QGraphicsItem.ItemIsMovable, False)
        self._base_builder_draft_parts.append(new_obj)
        self._base_builder_draft_source_by_nickname[str(new_obj.nickname or "").strip().lower()] = None
        self._base_builder_selected_object = new_obj
        self._base_builder_push_history(f"Added part: {self._object_display_label(new_obj)}")
        self._refresh_base_builder_dialog_state(refresh_parts=True)
        self.statusBar().showMessage(
            tr("status.base_builder_part_added").format(nickname=nickname, base=target_base)
        )

    def _open_base_builder_for_object(self, obj: SolarObject | None = None) -> None:
        item = obj if isinstance(obj, SolarObject) else self._selected
        if not isinstance(item, SolarObject):
            QMessageBox.information(self, tr("msg.no_object"), tr("msg.no_object_text"))
            return
        base_nick = self._base_nickname_for_object(item)
        if not base_nick:
            QMessageBox.information(self, tr("msg.no_base"), tr("msg.no_base_text"))
            return
        part_entries = self._collect_base_builder_part_entries()
        if not part_entries:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.base_builder_no_parts"))
            return
        existing = self._base_builder_dialog
        if existing is not None and isValid(existing):
            try:
                existing.close()
            except Exception:
                pass
        self._set_active_base_focus(base_nick)
        self._initialize_base_builder_draft(base_nick, item)
        self._select(item)
        try:
            self.view.centerOn(item)
        except Exception:
            pass
        dlg = BaseBuilderDialog(
            self,
            base_nickname=base_nick,
            scene=self.view._scene,
            part_entries=part_entries,
            scene_payload_provider=self._base_builder_scene_payload,
            existing_parts_provider=lambda bn=base_nick: self._base_builder_existing_parts(bn),
            selected_scene_data_provider=self._resolve_native_scene_data_for_object,
            configure_3d_view_callback=self._configure_base_builder_3d_view,
            embedded_preview_factory=self._build_embedded_model_viewer_preview_widget,
            add_part_callback=lambda part_entry, bn=base_nick: self._base_builder_add_part(bn, part_entry),
            delete_selected_callback=self._base_builder_delete_selected_part,
            save_callback=self._base_builder_save,
            undo_callback=self._base_builder_undo,
            history_provider=self._base_builder_history_rows,
            is_dirty_callback=self._base_builder_has_unsaved_changes,
            select_existing_part_callback=self._base_builder_select_existing_part,
            select_object_callback=self._base_builder_select_object,
            clear_selection_callback=self._base_builder_clear_selection,
            begin_transform_callback=self._base_builder_begin_transform,
            update_transform_callback=self._base_builder_apply_transform_delta,
            finish_transform_callback=self._base_builder_end_transform,
            closed_callback=self._close_base_builder,
        )
        self._base_builder_dialog = dlg
        dlg.show()
        dlg.raise_()
        dlg.activateWindow()
        self._refresh_base_builder_dialog_state(refresh_parts=True)

    def _show_base_related_3d_preview(self, obj: SolarObject, base_nickname: str) -> bool:
        if not hasattr(self, "view3d"):
            return False
        related_objects = self._related_base_objects(base_nickname)
        if len(related_objects) <= 1:
            return False
        dlg = QDialog(self)
        dlg.setWindowTitle(f"3D Preview - {base_nickname}")
        dlg.resize(1100, 760)
        root = QVBoxLayout(dlg)
        info_lbl = QLabel(f"Multipart base preview for {base_nickname}", dlg)
        root.addWidget(info_lbl)
        preview_view = BaseAssemblyPreviewView()
        self._configure_base_builder_3d_view(preview_view)
        root.addWidget(preview_view, 1)
        preview_view.set_data(related_objects, [], self._scale)
        preview_view.set_selected(obj)
        try:
            preview_view.center_on_item(obj)
        except Exception:
            pass
        reset_btn = QPushButton("Reset Camera", dlg)
        reset_btn.clicked.connect(lambda: preview_view.center_on_item(obj))
        root.addWidget(reset_btn)
        dlg.exec()
        try:
            preview_view.clear_scene()
        except Exception:
            pass
        return True

    def _edit_base(self):
        """Öffnet den Base-Editor im Layout des Base-Creation-Dialogs."""
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return

        idx = self.obj_combo.currentIndex()
        if idx < 0:
            self.statusBar().showMessage(tr("status.no_object_selected"))
            return
        item = self.obj_combo.itemData(idx)
        if not isinstance(item, SolarObject):
            QMessageBox.information(self, tr("msg.no_object"), tr("msg.no_object_text"))
            return

        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"), tr("msg.no_game_path_text"))
            return

        base_nick = ""
        for k, v in item.data.get("_entries", []):
            if str(k).strip().lower() == "base":
                base_nick = str(v).strip()
                break
        if not base_nick:
            for k, v in item.data.get("_entries", []):
                if str(k).strip().lower() == "dock_with":
                    base_nick = str(v).strip()
                    break
        if not base_nick:
            QMessageBox.information(self, tr("msg.no_base"), tr("msg.no_base_text"))
            return

        obj_nick = str(item.data.get("nickname", "")).strip()
        sec_idx: int | None = None
        obj_entries: list[tuple[str, str]] = []
        for i, (sec_name, entries) in enumerate(self._sections):
            if str(sec_name).strip().lower() != "object":
                continue
            nick = self._entry_get_value(entries, "nickname").strip().lower()
            if nick == obj_nick.lower():
                sec_idx = i
                obj_entries = list(entries)
                break
        if sec_idx is None:
            QMessageBox.warning(self, tr("msg.not_found"), tr("msg.zone_not_found").format(nickname=obj_nick))
            return

        if not self._ensure_universe_sections_for_edit():
            QMessageBox.warning(self, tr("msg.not_found"), tr("msg.dir_not_found"))
            return

        sys_nick = Path(self._filepath).stem
        base_sec_idx: int | None = None
        base_sec_entries: list[tuple[str, str]] = []
        for i, (sec_name, entries) in enumerate(self._uni_sections):
            if str(sec_name).strip().lower() != "base":
                continue
            if self._entry_get_value(entries, "nickname").strip().lower() == base_nick.lower():
                base_sec_idx = i
                base_sec_entries = list(entries)
                break

        base_file_rel = self._entry_get_value(base_sec_entries, "file").strip()
        if not base_file_rel:
            base_file_rel = f"Universe\\Systems\\{sys_nick}\\Bases\\{base_nick}.ini"
        base_ini_path = self._resolve_game_path_case_insensitive(game_path, base_file_rel)
        if base_ini_path is None:
            base_ini_path = Path(self._ensure_writable_path(str(Path(self._filepath).parent / "BASES" / f"{base_nick}.ini")))

        start_room = "Deck"
        price_variance = 0.15
        existing_rooms: list[str] = []
        room_scene_by_name: dict[str, str] = {}
        if base_ini_path.exists():
            try:
                base_secs = self._parser.parse(str(base_ini_path))
            except Exception:
                base_secs = []
            room_file_rel_by_name: dict[str, str] = {}
            for sec_name, entries in base_secs:
                sec_low = str(sec_name).strip().lower()
                if sec_low == "baseinfo":
                    sr = self._entry_get_value(entries, "start_room").strip()
                    if sr:
                        start_room = sr
                    try:
                        pv = float(self._entry_get_value(entries, "price_variance").strip() or "0.15")
                        if pv >= 0:
                            price_variance = pv
                    except Exception:
                        pass
                elif sec_low == "room":
                    rn = self._entry_get_value(entries, "nickname").strip()
                    rf = self._entry_get_value(entries, "file").strip()
                    if not rn:
                        continue
                    if rn not in existing_rooms:
                        existing_rooms.append(rn)
                    if rf:
                        room_file_rel_by_name[rn.lower()] = rf
            for room_name in existing_rooms:
                rel = room_file_rel_by_name.get(room_name.lower(), "")
                room_path = self._resolve_game_path_case_insensitive(game_path, rel) if rel else None
                if not room_path:
                    room_path = base_ini_path.parent / "ROOMS" / f"{base_nick}_{room_name.lower()}.ini"
                if room_path and room_path.exists():
                    try:
                        content = self._read_text_best_effort(room_path)
                        room_scene_by_name[room_name.lower()] = self._extract_room_scene_path(content)
                    except Exception:
                        pass

        # Vorlagen-/Dropdowndaten wie im Create-Dialog
        static_data = self._base_dialog_static_data(game_path)
        archetypes = list(static_data.get("archetypes", []))
        default_loadouts_by_archetype = dict(static_data.get("default_loadouts_by_archetype", {}))
        if not archetypes:
            QMessageBox.warning(self, tr("msg.error"), "No base archetypes found in DATA/SOLAR/solararch.ini.")
            return
        misc_goods = self._load_market_goods(game_path, "market_misc.ini", base_nick)
        comm_goods = self._load_market_goods(game_path, "market_commodities.ini", base_nick)
        ship_goods = self._load_market_goods(game_path, "market_ships.ini", base_nick)
        equip_groups = dict(static_data.get("equip_groups", {}))
        commodity_nicks, commodity_prices = tuple(static_data.get("commodity_scan", ([], {})))
        ship_nicks = list(static_data.get("ship_nicks", []))
        display_names = dict(static_data.get("display_names", {}))
        display_names.update(dict(static_data.get("commodity_display_names", {})))
        base_prices = dict(static_data.get("base_prices", {}))
        shipdealer_enabled = self._base_has_shipdealer_room_or_virtual(base_ini_path)
        loadouts = [self.loadout_cb.itemText(i) for i in range(self.loadout_cb.count()) if self.loadout_cb.itemText(i)]
        factions = [self.faction_cb.itemText(i) for i in range(self.faction_cb.count()) if self.faction_cb.itemText(i)]
        pilots = list(static_data.get("pilots", []))
        voices = list(static_data.get("voices", []))
        heads, bodies = tuple(static_data.get("bodyparts", ([], [])))

        existing_bases: list[tuple[str, str]] = []
        for sec_name, entries in self._uni_sections:
            if str(sec_name).strip().lower() != "base":
                continue
            bn = self._entry_get_value(entries, "nickname").strip()
            if not bn:
                continue
            strid = self._entry_get_value(entries, "strid_name").strip()
            ingame = self._display_name_from_ids_name(strid)
            ingame = str(ingame or "").strip() or bn
            existing_bases.append((f"{bn} - {ingame}", bn))

        current_ids_name = self._entry_get_value(obj_entries, "ids_name").strip()
        current_name_text = self._display_name_from_ids_name(current_ids_name) if current_ids_name else ""
        current_ids_info = self._safe_int(self._entry_get_value(obj_entries, "ids_info").strip())
        current_infocard_xml = self._resolve_infocard_xml_by_global_id(current_ids_info) if current_ids_info > 0 else ""
        room_npcs_existing = self._base_template_dialog_data(game_path, base_nick).get("room_npcs", {})

        dlg = BaseCreationDialog(
            self,
            system_nick=sys_nick,
            archetypes=archetypes,
            loadouts=loadouts,
            factions=factions,
            existing_bases=existing_bases,
            next_base_num=1,
            pilots=pilots,
            voices=voices,
            heads=heads,
            bodies=bodies,
            template_data_provider=lambda template_nick, gp=game_path: self._base_template_dialog_data(gp, template_nick),
            ids_info_template_xml=current_infocard_xml,
            default_loadouts_by_archetype=default_loadouts_by_archetype,
            market_equip_groups=equip_groups,
            market_misc_goods=misc_goods,
            market_commodity_nicks=commodity_nicks,
            market_commodity_goods=comm_goods,
            market_commodity_prices=commodity_prices,
            market_ship_nicks=ship_nicks,
            market_ship_goods=ship_goods,
            market_display_names=display_names,
            market_base_prices=base_prices,
            market_shipdealer_enabled=shipdealer_enabled,
        )
        dlg.setWindowTitle(f"{tr('edit.base')}: {base_nick}")
        dlg.base_nick_edit.setText(base_nick)
        dlg.base_nick_edit.setReadOnly(True)
        dlg.obj_nick_edit.setText(obj_nick)
        dlg.obj_nick_edit.setReadOnly(True)
        dlg.ids_name_edit.setText(str(current_name_text or "").strip())
        dlg._ids_info_template_xml = str(current_infocard_xml or "").strip()
        dlg.ids_info_preview.setPlainText(dlg._xml_to_plain_preview(dlg._ids_info_template_xml))

        dlg.arch_cb.setCurrentText(self._entry_get_value(obj_entries, "archetype").strip())
        dlg.loadout_cb.setCurrentText(self._entry_get_value(obj_entries, "loadout").strip())
        dlg.faction_cb.setCurrentText(self._entry_get_value(obj_entries, "reputation").strip())
        dlg.pilot_cb.setCurrentText(self._entry_get_value(obj_entries, "pilot").strip() or "pilot_solar_easiest")
        dlg.voice_cb.setCurrentText(self._entry_get_value(obj_entries, "voice").strip())
        costume = self._entry_get_value(obj_entries, "space_costume").strip()
        cparts = [p.strip() for p in costume.split(",", 1)] if costume else ["", ""]
        if len(cparts) < 2:
            cparts.append("")
        dlg.head_cb.setCurrentText(cparts[0] or "benchmark_male_head")
        dlg.body_cb.setCurrentText(cparts[1] or "benchmark_male_body")
        dlg.bgcs_edit.setText(self._entry_get_value(base_sec_entries, "BGCS_base_run_by").strip())
        dlg.copy_npcs_cb.setChecked(bool(room_npcs_existing))

        dlg._updating_rooms = True
        try:
            for r in range(dlg.room_table.rowCount()):
                check_item = dlg.room_table.item(r, 0)
                if check_item:
                    check_item.setCheckState(Qt.Unchecked)
            for room_name in existing_rooms:
                scene = room_scene_by_name.get(room_name.lower(), BaseCreationDialog._default_scene_for_room(room_name))
                dlg._set_room_row(room_name, True, scene, room_npcs_existing.get(room_name.lower(), []))
            for room_name, _default in BaseCreationDialog.ROOM_CHOICES:
                dlg._set_room_row_locked(room_name, False)
        finally:
            dlg._updating_rooms = False
        dlg._refresh_room_npc_tabs()
        dlg._refresh_start_room_choices(preferred=start_room or "Deck")
        if start_room:
            dlg.start_room_cb.setCurrentText(start_room)
        dlg.price_var_spin.setValue(float(price_variance))

        previous_focus = self._base_builder_active_base_nick
        self._set_active_base_focus(base_nick)
        try:
            if dlg.exec() != QDialog.Accepted:
                return

            payload = dlg.payload()
            rooms = [str(r).strip() for r in payload.get("rooms", []) if str(r).strip()]
            if not rooms:
                QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.min_one_room"))
                return
            if payload.get("start_room", "") not in rooms:
                QMessageBox.warning(self, tr("msg.invalid"), tr("msg.start_room_invalid").format(room=payload.get("start_room", "")))
                return

            # 1) Objekt aktualisieren
            ids_name_val = current_ids_name or "0"
            ids_info_val = str(current_ids_info or 0)
            new_name_text = str(payload.get("ids_name_text", "") or "").strip()
            if new_name_text != str(current_name_text or "").strip():
                ids_name_val = self._ensure_ids_name_in_user_dll(ids_name_val, new_name_text)
            new_infocard_xml = str(payload.get("ids_info_template_xml", "") or "").strip()
            if new_infocard_xml != str(current_infocard_xml or "").strip() and new_infocard_xml:
                ids_info_val = self._ensure_ids_info_in_user_dll(ids_info_val, new_infocard_xml)

            rep_nick = self._normalize_reputation_value(payload.get("reputation", ""))
            safe_archetype, _arch_changed = self._normalize_base_archetype(game_path, payload.get("archetype", ""))
            space_costume = str(payload.get("space_costume", "") or "").strip()
            obj_updates: dict[str, str] = {
                "nickname": obj_nick,
                "base": base_nick,
                "dock_with": base_nick,
                "archetype": safe_archetype,
                "loadout": str(payload.get("loadout", "") or "").strip(),
                "reputation": rep_nick,
                "pilot": str(payload.get("pilot", "") or "").strip(),
                "voice": str(payload.get("voice", "") or "").strip(),
                "space_costume": space_costume,
                "ids_name": str(ids_name_val),
                "ids_info": str(ids_info_val),
            }
            removable_if_empty = {"loadout", "reputation", "pilot", "voice", "space_costume"}
            new_obj_entries: list[tuple[str, str]] = []
            handled: set[str] = set()
            for k, v in obj_entries:
                kl = str(k).strip().lower()
                if kl not in obj_updates or kl in handled:
                    new_obj_entries.append((k, v))
                    continue
                nv = obj_updates.get(kl, "")
                handled.add(kl)
                if kl in removable_if_empty and not str(nv).strip():
                    continue
                new_obj_entries.append((k, nv))
            for key, val in obj_updates.items():
                if key in handled:
                    continue
                if key in removable_if_empty and not str(val).strip():
                    continue
                new_obj_entries.append((key, val))

            self._sections[sec_idx] = ("Object", new_obj_entries)
            item.data["_entries"] = list(new_obj_entries)
            for k, v in new_obj_entries:
                item.data[str(k).strip().lower()] = v

            # 2) Base/Room-Dateien aktualisieren
            sys_dir = Path(self._filepath).parent
            bases_dir = sys_dir / "BASES"
            rooms_dir = bases_dir / "ROOMS"
            bases_dir.mkdir(parents=True, exist_ok=True)
            rooms_dir.mkdir(parents=True, exist_ok=True)
            base_ini_path = Path(self._ensure_writable_path(str(base_ini_path)))
            base_ini_path.parent.mkdir(parents=True, exist_ok=True)

            selected_rooms = list(rooms)
            template_base = str(payload.get("template_base", "") or "").strip()
            template_rooms = self._load_template_rooms(game_path, template_base) if template_base else {}
            room_customizations = payload.get("room_customizations", {}) if isinstance(payload.get("room_customizations"), dict) else {}

            sync_base_room_files(
                rooms_dir=rooms_dir,
                base_nick=base_nick,
                selected_rooms=selected_rooms,
                existing_rooms=existing_rooms,
                start_room=str(payload.get("start_room", "Deck")),
                template_rooms=template_rooms,
                room_customizations=room_customizations,
                room_scene_by_name=room_scene_by_name,
                adapt_template_room=self._adapt_template_room,
                read_room_text=self._read_text_best_effort,
                generate_room_ini=self._generate_room_ini,
                override_room_scene=self._override_room_scene,
                normalize_room_navigation_callback=MainWindow._normalize_room_navigation,
                remove_room_file=lambda path: path.unlink(),
            )

            write_base_ini(
                base_ini_path,
                base_nick=base_nick,
                system_nick=sys_nick,
                start_room=str(payload.get("start_room", "Deck")),
                price_variance=float(payload.get("price_variance", 0.15)),
                rooms=selected_rooms,
            )

            # 3) universe.ini-Base-Eintrag aktualisieren
            strid_name_val = str(ids_name_val).strip() or "0"
            if base_sec_idx is None:
                base_sec_entries = build_universe_base_entries(
                    base_nick=base_nick,
                    system_nick=sys_nick,
                    strid_name_val=strid_name_val,
                    file_rel=f"Universe\\Systems\\{sys_nick}\\Bases\\{base_nick}.ini",
                    bgcs_base_run_by=str(payload.get("bgcs_base_run_by", "") or ""),
                )
                self._uni_sections.append(("Base", base_sec_entries))
            else:
                entries = update_universe_base_entries(
                    list(base_sec_entries),
                    base_nick=base_nick,
                    system_nick=sys_nick,
                    strid_name_val=strid_name_val,
                    file_rel=f"Universe\\Systems\\{sys_nick}\\Bases\\{base_nick}.ini",
                    bgcs_base_run_by=str(payload.get("bgcs_base_run_by", "") or ""),
                )
                self._uni_sections[base_sec_idx] = ("Base", entries)
            self._write_universe_sections()

            # 4) mbases/NPCs synchronisieren
            self._ensure_mbase_entry_for_base(
                game_path=game_path,
                base_nick=base_nick,
                local_faction=(rep_nick or "li_n_grp"),
                diff=1,
            )
            npc_rooms, npc_customizations = normalize_room_npc_customizations(
                existing_rooms=existing_rooms,
                selected_rooms=selected_rooms,
                room_customizations=room_customizations,
                room_npcs_existing=room_npcs_existing,
            )

            self._apply_room_npcs_to_base(
                game_path=game_path,
                base_nick=base_nick,
                local_faction=(rep_nick or "li_n_grp"),
                room_customizations=npc_customizations,
                valid_rooms=npc_rooms,
            )

            # 5) Market-Dateien speichern
            self._save_market_goods(
                game_path,
                "market_misc.ini",
                base_nick,
                payload.get("market_misc_goods", misc_goods) or [],
            )
            self._save_market_goods(
                game_path,
                "market_commodities.ini",
                base_nick,
                payload.get("market_commodities_goods", comm_goods) or [],
            )
            self._save_market_goods(
                game_path,
                "market_ships.ini",
                base_nick,
                payload.get("market_ships_goods", ship_goods) or [],
            )

            if self._selected is item:
                self.editor.setPlainText(item.raw_text())
            self._reload_dll_name_cache()
            self._ids_display_cache.clear()
            self._invalidate_base_template_dialog_cache(game_path)
            self._set_dirty(True)
            self._write_to_file(reload=False)
            self.statusBar().showMessage(tr("status.base_updated").format(nickname=base_nick))
        finally:
            self._set_active_base_focus(previous_focus)

    def _npc_collect_bases(self, game_path: str) -> list[dict]:
        if not self._ensure_universe_sections_for_edit():
            return []
        rows: list[dict] = []
        for sec_name, entries in self._uni_sections:
            if str(sec_name).strip().lower() != "base":
                continue
            nick = self._entry_get_value(entries, "nickname").strip()
            if not nick:
                continue
            sys_nick = self._entry_get_value(entries, "system").strip()
            strid = self._entry_get_value(entries, "strid_name").strip() or self._entry_get_value(entries, "ids_name").strip()
            file_rel = self._entry_get_value(entries, "file").strip()
            disp = self._base_display_name(nick, strid)
            rows.append(
                {
                    "nickname": nick,
                    "display": disp or nick,
                    "system": sys_nick,
                    "file": file_rel,
                }
            )
        rows.sort(key=lambda r: (str(r.get("system", "")).lower(), str(r.get("display", "")).lower()))
        return rows

    def _npc_rooms_for_base(self, game_path: str, base_nickname: str) -> list[str]:
        base_nick = str(base_nickname or "").strip().lower()
        if not base_nick:
            return []
        if not self._ensure_universe_sections_for_edit():
            return []
        base_file_rel = ""
        for sec_name, entries in self._uni_sections:
            if str(sec_name).strip().lower() != "base":
                continue
            nick = self._entry_get_value(entries, "nickname").strip().lower()
            if nick != base_nick:
                continue
            base_file_rel = self._entry_get_value(entries, "file").strip()
            break
        if not base_file_rel:
            return []
        base_ini = self._resolve_game_path_case_insensitive(game_path, base_file_rel)
        if not base_ini or not base_ini.exists():
            return []
        try:
            secs = self._parser.parse(str(base_ini))
        except Exception:
            return []
        rooms: list[str] = []
        seen: set[str] = set()
        for sec_name, entries in secs:
            if str(sec_name).strip().lower() != "room":
                continue
            room = self._entry_get_value(entries, "nickname").strip()
            if not room:
                continue
            key = room.lower()
            if key in seen:
                continue
            seen.add(key)
            rooms.append(room)
        order = {"deck": 1, "bar": 2, "trader": 3, "equipment": 4, "shipdealer": 5, "cityscape": 6}
        rooms.sort(key=lambda x: (order.get(x.lower(), 99), x.lower()))
        return rooms

    @staticmethod
    def _npc_suggest_nickname(base_nickname: str, sections: list[tuple[str, list[tuple[str, str]]]]) -> str:
        base = re.sub(r"[^a-zA-Z0-9_]+", "_", str(base_nickname or "").strip()).strip("_")
        if not base:
            base = "base"
        prefix = f"{base.lower()}_npc_"
        used: set[int] = set()
        for sec_name, entries in sections:
            if str(sec_name).strip().lower() != "gf_npc":
                continue
            nick = ""
            for k, v in entries:
                if str(k).strip().lower() == "nickname":
                    nick = str(v).strip().lower()
                    break
            if not nick.startswith(prefix):
                continue
            tail = nick[len(prefix):]
            if tail.isdigit():
                used.add(int(tail))
        nxt = 1
        while nxt in used:
            nxt += 1
        return f"{prefix}{nxt:03d}"

    @staticmethod
    def _npc_find_section_range(sections: list[tuple[str, list[tuple[str, str]]]], start_idx: int) -> tuple[int, int]:
        return npc_find_section_range(sections, start_idx)

    def _npc_attach_to_mbase(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        base_nickname: str,
        faction_nickname: str,
        npc_nickname: str,
    ) -> list[tuple[str, list[tuple[str, str]]]]:
        return npc_attach_to_mbase(
            sections,
            base_nickname=base_nickname,
            faction_nickname=faction_nickname,
            npc_nickname=npc_nickname,
            entry_get_value=self._entry_get_value,
        )

    def _npc_insert_gf_for_base(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        base_nickname: str,
        npc_entries: list[tuple[str, str]],
    ) -> list[tuple[str, list[tuple[str, str]]]]:
        return npc_insert_gf_for_base(
            sections,
            base_nickname=base_nickname,
            npc_entries=npc_entries,
            entry_get_value=self._entry_get_value,
        )

    def _npc_detach_from_mbase(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        base_nickname: str,
        npc_nickname: str,
    ) -> list[tuple[str, list[tuple[str, str]]]]:
        return npc_detach_from_mbase(
            sections,
            base_nickname=base_nickname,
            npc_nickname=npc_nickname,
            entry_get_value=self._entry_get_value,
        )

    def _npc_find_gf_section_index(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        npc_nickname: str,
    ) -> int | None:
        return npc_find_gf_section_index(
            sections,
            npc_nickname=npc_nickname,
            entry_get_value=self._entry_get_value,
        )

    def _npc_collect_for_base(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        base_nickname: str,
    ) -> list[dict]:
        return npc_collect_for_base(
            sections,
            base_nickname=base_nickname,
            entry_get_value=self._entry_get_value,
        )

    def _open_npc_editor(self, preset_base_nickname: str = ""):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"), tr("msg.no_game_path_text"))
            return
        bases = self._npc_collect_bases(game_path)
        if not bases:
            QMessageBox.warning(self, tr("msg.error"), tr("npc.msg.no_bases"))
            return

        mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
        if mbases_path is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.dir_not_found"))
            return
        if mbases_path.exists():
            try:
                mbases_sections = self._parser.parse(str(mbases_path))
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.error"), str(exc))
                return
        else:
            mbases_sections = []

        page, root = self._prepare_editor_page("npc_editor_page", tr("dlg.npc_editor"))
        intro = QLabel(tr("npc.msg.intro"))
        intro.setWordWrap(True)
        root.addWidget(intro)
        tabs = QTabWidget()
        root.addWidget(tabs, 1)
        create_box = QGroupBox(tr("npc.group.create"))
        edit_box = QGroupBox(tr("npc.group.edit"))
        tabs.addTab(create_box, tr("npc.group.create"))
        tabs.addTab(edit_box, tr("npc.group.edit"))

        system_rows: list[tuple[str, str]] = []
        seen_systems: set[str] = set()
        for row in bases:
            sys_nick = str(row.get("system", "")).strip()
            if not sys_nick:
                continue
            sys_code = sys_nick.upper()
            sys_key = sys_code.lower()
            if sys_key in seen_systems:
                continue
            seen_systems.add(sys_key)
            sys_name = self._system_display_name(sys_code).strip() or sys_code
            label = f"{sys_code} - {sys_name}" if sys_name.lower() != sys_code.lower() else sys_code
            system_rows.append((label, sys_code))
        system_rows.sort(key=lambda x: x[0].lower())
        bodies, heads = self._scan_bodyparts(game_path)
        voices = self._scan_voices(game_path)

        def _fill_faction_combo(cb: QComboBox):
            cb.setEditable(True)
            cb.clear()
            for i in range(self.faction_cb.count()):
                txt = self.faction_cb.itemText(i)
                if txt:
                    cb.addItem(txt)

        def _fill_body_head_voice(body: QComboBox, head: QComboBox, voice: QComboBox):
            body.setEditable(True)
            head.setEditable(True)
            voice.setEditable(True)
            body.clear()
            head.clear()
            voice.clear()
            for b in bodies:
                body.addItem(b)
            for hd in heads:
                head.addItem(hd)
            for v in voices:
                voice.addItem(v)

        npc_state_values: set[str] = {
            "base_0_rank",
            "mission_end",
            "freetime_01_02",
            "freetime_02_03",
            "freetime_03_04",
        }
        npc_misn_types: set[str] = {"DestroyMission"}
        npc_existing_misn_lines: set[str] = set()
        npc_existing_rumor_lines: set[str] = set()
        npc_existing_rumor2_lines: set[str] = set()
        npc_existing_rumor_ids: set[str] = set()
        for sec_name, entries in mbases_sections:
            if str(sec_name).strip().lower() != "gf_npc":
                continue
            for k, v in entries:
                kl = str(k).strip().lower()
                val = str(v).strip()
                if not val:
                    continue
                parts = [p.strip() for p in val.split(",")]
                if kl == "misn" and parts and parts[0]:
                    npc_misn_types.add(parts[0])
                    npc_existing_misn_lines.add(val)
                elif kl in ("rumor", "rumor_type2"):
                    if len(parts) > 0 and parts[0]:
                        npc_state_values.add(parts[0])
                    if len(parts) > 1 and parts[1]:
                        npc_state_values.add(parts[1])
                    if kl == "rumor":
                        npc_existing_rumor_lines.add(val)
                    else:
                        npc_existing_rumor2_lines.add(val)
                    if len(parts) > 3 and parts[3]:
                        npc_existing_rumor_ids.add(parts[3])

        def _npc_rumor_line_label(line: str) -> str:
            return npc_rumor_line_label(line, self._display_name_from_ids_name)

        def _npc_sync_hidden_from_list(lst: QListWidget, hidden: QTextEdit):
            lines = [lst.item(i).text().strip() for i in range(lst.count()) if lst.item(i).text().strip()]
            hidden.blockSignals(True)
            hidden.setPlainText("\n".join(lines))
            hidden.blockSignals(False)

        def _npc_fill_list_from_hidden(lst: QListWidget, hidden: QTextEdit):
            lst.clear()
            for ln in npc_multiline_values(hidden.toPlainText()):
                lst.addItem(ln)

        def _npc_build_guided_editor(container: QFormLayout, hidden: QTextEdit, mode: str):
            box = QGroupBox(
                tr("npc.group.misn") if mode == "misn"
                else tr("npc.group.rumor") if mode == "rumor"
                else tr("npc.group.rumor2")
            )
            v = QVBoxLayout(box)
            hint = QLabel(
                tr("npc.help.misn") if mode == "misn"
                else tr("npc.help.rumor") if mode == "rumor"
                else tr("npc.help.rumor2")
            )
            hint.setWordWrap(True)
            v.addWidget(hint)
            listw = QListWidget()
            listw.setMinimumHeight(90)
            v.addWidget(listw)
            existing_lines = (
                sorted(npc_existing_misn_lines)
                if mode == "misn"
                else sorted(npc_existing_rumor_lines)
                if mode == "rumor"
                else sorted(npc_existing_rumor2_lines)
            )
            existing_row = QHBoxLayout()
            existing_row.addWidget(QLabel(tr("npc.field.existing_lines")))
            existing_cb = QComboBox()
            existing_cb.setEditable(False)
            for ln in existing_lines:
                existing_cb.addItem(_npc_rumor_line_label(ln) if mode != "misn" else ln, ln)
            existing_row.addWidget(existing_cb, 1)
            add_existing_btn = QPushButton(tr("npc.btn.add_existing"))
            existing_row.addWidget(add_existing_btn)
            v.addLayout(existing_row)

            row = QHBoxLayout()
            add_btn = QPushButton(tr("npc.btn.add_line"))
            upd_btn = QPushButton(tr("npc.btn.update_line"))
            rem_btn = QPushButton(tr("npc.btn.remove_line"))

            if mode == "misn":
                t_cb = QComboBox()
                t_cb.setEditable(True)
                t_cb.addItems(sorted(npc_misn_types))
                min_e = QLineEdit()
                max_e = QLineEdit()
                w_e = QLineEdit()
                min_e.setPlaceholderText("2.309610")
                max_e.setPlaceholderText("8.110100")
                w_e.setPlaceholderText("100")
                row.addWidget(QLabel(tr("npc.col.type")))
                row.addWidget(t_cb, 2)
                row.addWidget(QLabel(tr("npc.col.min")))
                row.addWidget(min_e, 1)
                row.addWidget(QLabel(tr("npc.col.max")))
                row.addWidget(max_e, 1)
                row.addWidget(QLabel(tr("npc.col.weight")))
                row.addWidget(w_e, 1)
            else:
                s_from = QComboBox()
                s_to = QComboBox()
                for cb in (s_from, s_to):
                    cb.setEditable(True)
                    cb.addItems(sorted(npc_state_values))
                weight = QSpinBox()
                weight.setRange(0, 100)
                weight.setValue(1)
                ids = QComboBox()
                ids.setEditable(True)
                ids.setMinimumWidth(280)
                for rid in sorted(npc_existing_rumor_ids, key=lambda x: int(x) if str(x).isdigit() else 0):
                    # Keep dialog opening responsive: resolve only StringTable text in bulk.
                    rtxt = self._display_name_from_ids_name(rid).replace("\n", " ").strip()
                    if len(rtxt) > 65:
                        rtxt = rtxt[:62] + "..."
                    ids.addItem(f"{rid} - {rtxt}" if rtxt else rid, rid)
                row.addWidget(QLabel(tr("npc.field.state_from")))
                row.addWidget(s_from, 2)
                row.addWidget(QLabel(tr("npc.field.state_to")))
                row.addWidget(s_to, 2)
                row.addWidget(QLabel(tr("npc.field.weight")))
                row.addWidget(weight, 1)
                row.addWidget(QLabel(tr("npc.col.ids")))
                row.addWidget(ids, 1)
                s_from.setCurrentText("base_0_rank")
                s_to.setCurrentText("mission_end")
            row.addWidget(add_btn)
            row.addWidget(upd_btn)
            row.addWidget(rem_btn)
            v.addLayout(row)

            def _line_from_controls() -> str:
                if mode == "misn":
                    return ", ".join([
                        t_cb.currentText().strip(),
                        min_e.text().strip(),
                        max_e.text().strip(),
                        w_e.text().strip(),
                    ]).strip(", ").strip()
                rid = npc_parse_rumor_id(str(ids.currentData() if ids.currentData() is not None else ids.currentText()))
                return ", ".join([
                    s_from.currentText().strip(),
                    s_to.currentText().strip(),
                    str(weight.value()),
                    rid,
                ]).strip(", ").strip()

            def _load_controls_from_line(raw: str):
                vals = npc_split_csv(raw, 4)
                if mode == "misn":
                    t_cb.setCurrentText(vals[0])
                    min_e.setText(vals[1])
                    max_e.setText(vals[2])
                    w_e.setText(vals[3])
                else:
                    s_from.setCurrentText(vals[0])
                    s_to.setCurrentText(vals[1])
                    try:
                        weight.setValue(int(vals[2] or "1"))
                    except Exception:
                        weight.setValue(1)
                    rid = npc_parse_rumor_id(vals[3])
                    idx = ids.findData(rid)
                    if idx >= 0:
                        ids.setCurrentIndex(idx)
                    else:
                        ids.setCurrentText(rid)

            def _add_line():
                line = _line_from_controls()
                if not line:
                    return
                listw.addItem(line)
                _npc_sync_hidden_from_list(listw, hidden)

            def _add_existing_line():
                line = str(existing_cb.currentData() if existing_cb.currentData() is not None else existing_cb.currentText()).strip()
                if not line:
                    return
                listw.addItem(line)
                _npc_sync_hidden_from_list(listw, hidden)
                _load_controls_from_line(line)

            def _upd_line():
                it = listw.currentItem()
                if it is None:
                    _add_line()
                    return
                line = _line_from_controls()
                if not line:
                    return
                it.setText(line)
                _npc_sync_hidden_from_list(listw, hidden)

            def _rem_line():
                row_idx = listw.currentRow()
                if row_idx < 0:
                    return
                listw.takeItem(row_idx)
                _npc_sync_hidden_from_list(listw, hidden)

            def _sel_changed():
                it = listw.currentItem()
                if it is None:
                    return
                _load_controls_from_line(it.text())

            add_btn.clicked.connect(_add_line)
            add_existing_btn.clicked.connect(_add_existing_line)
            upd_btn.clicked.connect(_upd_line)
            rem_btn.clicked.connect(_rem_line)
            listw.currentItemChanged.connect(lambda _cur, _prev: _sel_changed())
            hidden.textChanged.connect(lambda: _npc_fill_list_from_hidden(listw, hidden))
            _npc_fill_list_from_hidden(listw, hidden)
            container.addRow("", box)

        # ----- Create area -----
        create_layout = QVBoxLayout(create_box)
        create_scroll = QScrollArea()
        create_scroll.setWidgetResizable(True)
        create_inner = QWidget()
        create_scroll.setWidget(create_inner)
        create_layout.addWidget(create_scroll, 1)
        cform = QFormLayout(create_inner)
        c_system_cb = QComboBox()
        for label, sys_code in system_rows:
            c_system_cb.addItem(label, sys_code)
        cform.addRow(tr("npc.field.system"), c_system_cb)
        c_base_cb = QComboBox()
        cform.addRow(tr("npc.field.base"), c_base_cb)
        c_room_cb = QComboBox()
        cform.addRow(tr("npc.field.room"), c_room_cb)
        c_nick_edit = QLineEdit()
        cform.addRow(tr("npc.field.nickname"), c_nick_edit)
        c_name_edit = QLineEdit()
        cform.addRow(tr("npc.field.name"), c_name_edit)
        c_faction_cb = QComboBox()
        _fill_faction_combo(c_faction_cb)
        cform.addRow(tr("npc.field.faction"), c_faction_cb)
        c_aff_cb = QComboBox()
        _fill_faction_combo(c_aff_cb)
        cform.addRow(tr("npc.field.affiliation"), c_aff_cb)
        c_body_cb = QComboBox()
        c_head_cb = QComboBox()
        c_voice_cb = QComboBox()
        _fill_body_head_voice(c_body_cb, c_head_cb, c_voice_cb)
        cform.addRow(tr("npc.field.body"), c_body_cb)
        cform.addRow(tr("npc.field.head"), c_head_cb)
        c_lh_edit = QLineEdit("benchmark_male_hand_left")
        c_rh_edit = QLineEdit("benchmark_male_hand_right")
        cform.addRow(tr("npc.field.lefthand"), c_lh_edit)
        cform.addRow(tr("npc.field.righthand"), c_rh_edit)
        cform.addRow(tr("npc.field.voice"), c_voice_cb)
        c_misn_edit = QTextEdit()
        c_misn_edit.setAcceptRichText(False)
        c_misn_edit.setMinimumHeight(44)
        cform.addRow(tr("npc.field.misn"), c_misn_edit)
        c_rumor_edit = QTextEdit()
        c_rumor_edit.setAcceptRichText(False)
        c_rumor_edit.setMinimumHeight(80)
        cform.addRow(tr("npc.field.rumor"), c_rumor_edit)
        c_rumor2_edit = QTextEdit()
        c_rumor2_edit.setAcceptRichText(False)
        c_rumor2_edit.setMinimumHeight(80)
        cform.addRow(tr("npc.field.rumor_type2"), c_rumor2_edit)
        c_misn_edit.setVisible(False)
        c_rumor_edit.setVisible(False)
        c_rumor2_edit.setVisible(False)
        _npc_build_guided_editor(cform, c_misn_edit, "misn")
        _npc_build_guided_editor(cform, c_rumor_edit, "rumor")
        _npc_build_guided_editor(cform, c_rumor2_edit, "rumor_type2")
        c_create_btn = QPushButton(tr("npc.btn.create"))
        cform.addRow("", c_create_btn)

        auto_nickname = {"active": True}

        def _create_fill_bases():
            sys_nick = str(c_system_cb.currentData() or "").strip().upper()
            rows = [b for b in bases if str(b.get("system", "")).strip().upper() == sys_nick]
            c_base_cb.blockSignals(True)
            c_base_cb.clear()
            for row in rows:
                c_base_cb.addItem(f"{row['display']} ({row['nickname']})", row["nickname"])
            c_base_cb.blockSignals(False)
            if c_base_cb.count() > 0:
                c_base_cb.setCurrentIndex(0)
            _create_fill_rooms_and_nick()

        def _create_fill_rooms_and_nick():
            base_nick = str(c_base_cb.currentData() or "").strip()
            rooms = self._npc_rooms_for_base(game_path, base_nick)
            c_room_cb.blockSignals(True)
            c_room_cb.clear()
            c_room_cb.addItems(rooms or ["bar"])
            c_room_cb.blockSignals(False)
            if auto_nickname["active"] or not c_nick_edit.text().strip():
                c_nick_edit.setText(self._npc_suggest_nickname(base_nick, mbases_sections))

        def _create_one():
            nonlocal mbases_sections
            base_nick = str(c_base_cb.currentData() or "").strip()
            room = c_room_cb.currentText().strip() or "bar"
            npc_nick = c_nick_edit.text().strip()
            if not npc_nick:
                QMessageBox.warning(self, tr("msg.incomplete"), tr("npc.msg.nickname_required"))
                return
            for sec_name, entries in mbases_sections:
                if str(sec_name).strip().lower() != "gf_npc":
                    continue
                if self._entry_get_value(entries, "nickname").strip().lower() == npc_nick.lower():
                    QMessageBox.warning(self, tr("msg.error"), tr("npc.msg.nickname_exists").format(nickname=npc_nick))
                    return
            faction = self._faction_from_ui(c_faction_cb.currentText()) or c_faction_cb.currentText().strip()
            affiliation = self._faction_from_ui(c_aff_cb.currentText()) or c_aff_cb.currentText().strip() or faction
            ids_name_text = c_name_edit.text().strip()
            individual_name = "0"
            if ids_name_text:
                try:
                    individual_name = self._ensure_ids_name_in_user_dll("0", ids_name_text)
                    self._reload_dll_name_cache()
                    self._ids_display_cache.clear()
                except Exception as exc:
                    QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                    return
            mbases_sections = self._npc_attach_to_mbase(mbases_sections, base_nick, faction, npc_nick)
            misn_lines = npc_multiline_values(c_misn_edit.toPlainText())
            rumor_lines = npc_multiline_values(c_rumor_edit.toPlainText())
            rumor2_lines = npc_multiline_values(c_rumor2_edit.toPlainText())
            npc_entries: list[tuple[str, str]] = [
                ("nickname", npc_nick),
                ("body", c_body_cb.currentText().strip()),
                ("head", c_head_cb.currentText().strip()),
                ("lefthand", c_lh_edit.text().strip() or "benchmark_male_hand_left"),
                ("righthand", c_rh_edit.text().strip() or "benchmark_male_hand_right"),
                ("affiliation", affiliation),
                ("voice", c_voice_cb.currentText().strip()),
            ]
            if individual_name and individual_name != "0":
                npc_entries.insert(5, ("individual_name", individual_name))
            npc_entries.append(("room", room))
            npc_entries = npc_apply_mission_and_rumors(
                npc_entries,
                misn_lines,
                rumor_lines,
                rumor2_lines,
            )
            mbases_sections = self._npc_insert_gf_for_base(mbases_sections, base_nick, npc_entries)
            try:
                mbases_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(mbases_path), mbases_sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self.statusBar().showMessage(tr("status.npc_created").format(nickname=npc_nick, base=base_nick))
            self._append_change_log(f"NPC erstellt: {npc_nick} -> {base_nick} ({room})")
            _create_fill_rooms_and_nick()
            _edit_fill_npcs()

        c_system_cb.currentIndexChanged.connect(_create_fill_bases)
        c_base_cb.currentIndexChanged.connect(_create_fill_rooms_and_nick)
        c_nick_edit.textEdited.connect(lambda _t: auto_nickname.update({"active": False}))
        c_create_btn.clicked.connect(_create_one)

        # ----- Edit area -----
        edit_layout = QVBoxLayout(edit_box)
        edit_scroll = QScrollArea()
        edit_scroll.setWidgetResizable(True)
        edit_inner = QWidget()
        edit_scroll.setWidget(edit_inner)
        edit_layout.addWidget(edit_scroll, 1)
        eform = QFormLayout(edit_inner)
        e_system_cb = QComboBox()
        for label, sys_code in system_rows:
            e_system_cb.addItem(label, sys_code)
        eform.addRow(tr("npc.field.system"), e_system_cb)
        e_base_cb = QComboBox()
        eform.addRow(tr("npc.field.base"), e_base_cb)
        e_npc_cb = QComboBox()
        eform.addRow(tr("npc.field.npc_select"), e_npc_cb)
        e_nick_edit = QLineEdit()
        eform.addRow(tr("npc.field.nickname"), e_nick_edit)
        e_name_edit = QLineEdit()
        eform.addRow(tr("npc.field.name"), e_name_edit)
        e_room_cb = QComboBox()
        eform.addRow(tr("npc.field.room"), e_room_cb)
        e_faction_cb = QComboBox()
        _fill_faction_combo(e_faction_cb)
        eform.addRow(tr("npc.field.faction"), e_faction_cb)
        e_aff_cb = QComboBox()
        _fill_faction_combo(e_aff_cb)
        eform.addRow(tr("npc.field.affiliation"), e_aff_cb)
        e_body_cb = QComboBox()
        e_head_cb = QComboBox()
        e_voice_cb = QComboBox()
        _fill_body_head_voice(e_body_cb, e_head_cb, e_voice_cb)
        eform.addRow(tr("npc.field.body"), e_body_cb)
        eform.addRow(tr("npc.field.head"), e_head_cb)
        e_lh_edit = QLineEdit("benchmark_male_hand_left")
        e_rh_edit = QLineEdit("benchmark_male_hand_right")
        eform.addRow(tr("npc.field.lefthand"), e_lh_edit)
        eform.addRow(tr("npc.field.righthand"), e_rh_edit)
        eform.addRow(tr("npc.field.voice"), e_voice_cb)
        e_misn_edit = QTextEdit()
        e_misn_edit.setAcceptRichText(False)
        e_misn_edit.setMinimumHeight(44)
        eform.addRow(tr("npc.field.misn"), e_misn_edit)
        e_rumor_edit = QTextEdit()
        e_rumor_edit.setAcceptRichText(False)
        e_rumor_edit.setMinimumHeight(80)
        eform.addRow(tr("npc.field.rumor"), e_rumor_edit)
        e_rumor2_edit = QTextEdit()
        e_rumor2_edit.setAcceptRichText(False)
        e_rumor2_edit.setMinimumHeight(80)
        eform.addRow(tr("npc.field.rumor_type2"), e_rumor2_edit)
        e_misn_edit.setVisible(False)
        e_rumor_edit.setVisible(False)
        e_rumor2_edit.setVisible(False)
        _npc_build_guided_editor(eform, e_misn_edit, "misn")
        _npc_build_guided_editor(eform, e_rumor_edit, "rumor")
        _npc_build_guided_editor(eform, e_rumor2_edit, "rumor_type2")
        e_save_btn = QPushButton(tr("npc.btn.save"))
        e_delete_btn = QPushButton(tr("npc.btn.delete"))
        e_actions = QWidget()
        e_actions_l = QHBoxLayout(e_actions)
        e_actions_l.setContentsMargins(0, 0, 0, 0)
        e_actions_l.addWidget(e_save_btn)
        e_actions_l.addWidget(e_delete_btn)
        eform.addRow("", e_actions)

        def _edit_fill_bases():
            sys_nick = str(e_system_cb.currentData() or "").strip().upper()
            rows = [b for b in bases if str(b.get("system", "")).strip().upper() == sys_nick]
            e_base_cb.blockSignals(True)
            e_base_cb.clear()
            for row in rows:
                e_base_cb.addItem(f"{row['display']} ({row['nickname']})", row["nickname"])
            e_base_cb.blockSignals(False)
            if e_base_cb.count() > 0:
                e_base_cb.setCurrentIndex(0)
            _edit_fill_npcs()

        def _edit_fill_npcs():
            base_nick = str(e_base_cb.currentData() or "").strip()
            rows = self._npc_collect_for_base(mbases_sections, base_nick)
            e_npc_cb.blockSignals(True)
            e_npc_cb.clear()
            for row in rows:
                e_npc_cb.addItem(str(row.get("nickname", "")), row)
            if e_npc_cb.count() == 0:
                e_npc_cb.addItem(tr("npc.msg.no_npcs_for_base"), None)
            e_npc_cb.blockSignals(False)
            _edit_load_selected()

        def _edit_load_selected():
            row = e_npc_cb.currentData()
            base_nick = str(e_base_cb.currentData() or "").strip()
            rooms = self._npc_rooms_for_base(game_path, base_nick) or ["bar"]
            e_room_cb.blockSignals(True)
            e_room_cb.clear()
            e_room_cb.addItems(rooms)
            e_room_cb.blockSignals(False)
            if not isinstance(row, dict):
                e_nick_edit.clear()
                e_name_edit.clear()
                e_misn_edit.clear()
                e_rumor_edit.clear()
                e_rumor2_edit.clear()
                return
            entries = list(row.get("entries", []))
            nick = self._entry_get_value(entries, "nickname").strip()
            e_nick_edit.setText(nick)
            e_faction_cb.setCurrentText(str(row.get("faction", "")))
            e_aff_cb.setCurrentText(self._entry_get_value(entries, "affiliation").strip())
            e_body_cb.setCurrentText(self._entry_get_value(entries, "body").strip())
            e_head_cb.setCurrentText(self._entry_get_value(entries, "head").strip())
            e_lh_edit.setText(self._entry_get_value(entries, "lefthand").strip() or "benchmark_male_hand_left")
            e_rh_edit.setText(self._entry_get_value(entries, "righthand").strip() or "benchmark_male_hand_right")
            e_voice_cb.setCurrentText(self._entry_get_value(entries, "voice").strip())
            e_room_cb.setCurrentText(self._entry_get_value(entries, "room").strip() or "bar")
            ids_val = self._entry_get_value(entries, "individual_name").strip()
            e_name_edit.setText(self._display_name_from_ids_name(ids_val) if ids_val else "")
            e_misn_edit.setPlainText("\n".join(npc_collect_multi(entries, "misn")))
            e_rumor_edit.setPlainText("\n".join(npc_collect_multi(entries, "rumor")))
            e_rumor2_edit.setPlainText("\n".join(npc_collect_multi(entries, "rumor_type2")))

        def _edit_save():
            nonlocal mbases_sections
            row = e_npc_cb.currentData()
            if not isinstance(row, dict):
                return
            old_nick = str(row.get("nickname", "")).strip()
            new_nick = e_nick_edit.text().strip() or old_nick
            base_nick = str(e_base_cb.currentData() or "").strip()
            new_faction = self._faction_from_ui(e_faction_cb.currentText()) or e_faction_cb.currentText().strip()
            new_aff = self._faction_from_ui(e_aff_cb.currentText()) or e_aff_cb.currentText().strip() or new_faction
            if new_nick.lower() != old_nick.lower():
                idx = self._npc_find_gf_section_index(mbases_sections, new_nick)
                if idx is not None:
                    QMessageBox.warning(self, tr("msg.error"), tr("npc.msg.nickname_exists").format(nickname=new_nick))
                    return
            gf_idx = self._npc_find_gf_section_index(mbases_sections, old_nick)
            if gf_idx is None:
                return
            sec_name, entries = mbases_sections[gf_idx]
            entries = self._entry_set(entries, "nickname", new_nick)
            entries = self._entry_set(entries, "body", e_body_cb.currentText().strip())
            entries = self._entry_set(entries, "head", e_head_cb.currentText().strip())
            entries = self._entry_set(entries, "lefthand", e_lh_edit.text().strip() or "benchmark_male_hand_left")
            entries = self._entry_set(entries, "righthand", e_rh_edit.text().strip() or "benchmark_male_hand_right")
            entries = self._entry_set(entries, "affiliation", new_aff)
            entries = self._entry_set(entries, "voice", e_voice_cb.currentText().strip())
            entries = self._entry_set(entries, "room", e_room_cb.currentText().strip() or "bar")
            misn_lines = npc_multiline_values(e_misn_edit.toPlainText())
            rumor_lines = npc_multiline_values(e_rumor_edit.toPlainText())
            rumor2_lines = npc_multiline_values(e_rumor2_edit.toPlainText())
            ids_name_text = e_name_edit.text().strip()
            if ids_name_text:
                try:
                    new_id = self._ensure_ids_name_in_user_dll(self._entry_get_value(entries, "individual_name").strip() or "0", ids_name_text)
                    entries = self._entry_set(entries, "individual_name", new_id)
                    self._reload_dll_name_cache()
                    self._ids_display_cache.clear()
                except Exception as exc:
                    QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                    return
            entries = npc_apply_mission_and_rumors(
                entries,
                misn_lines,
                rumor_lines,
                rumor2_lines,
            )
            mbases_sections.pop(gf_idx)
            mbases_sections = self._npc_detach_from_mbase(mbases_sections, base_nick, old_nick)
            mbases_sections = self._npc_attach_to_mbase(mbases_sections, base_nick, new_faction, new_nick)
            mbases_sections = self._npc_insert_gf_for_base(mbases_sections, base_nick, entries)
            try:
                mbases_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(mbases_path), mbases_sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self.statusBar().showMessage(tr("status.npc_updated").format(nickname=new_nick))
            self._append_change_log(f"NPC bearbeitet: {old_nick} -> {new_nick}")
            _edit_fill_npcs()

        def _edit_delete():
            nonlocal mbases_sections
            row = e_npc_cb.currentData()
            if not isinstance(row, dict):
                return
            npc_nick = str(row.get("nickname", "")).strip()
            if not npc_nick:
                return
            base_nick = str(e_base_cb.currentData() or "").strip()
            ans = QMessageBox.question(
                self,
                tr("npc.btn.delete"),
                tr("npc.msg.delete_confirm").format(nickname=npc_nick),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if ans != QMessageBox.Yes:
                return
            gf_idx = self._npc_find_gf_section_index(mbases_sections, npc_nick)
            if gf_idx is not None:
                mbases_sections.pop(gf_idx)
            mbases_sections = self._npc_detach_from_mbase(mbases_sections, base_nick, npc_nick)
            try:
                mbases_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(mbases_path), mbases_sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self.statusBar().showMessage(tr("status.npc_deleted").format(nickname=npc_nick))
            self._append_change_log(f"NPC gelöscht: {npc_nick} ({base_nick})")
            _edit_fill_npcs()

        e_system_cb.currentIndexChanged.connect(_edit_fill_bases)
        e_base_cb.currentIndexChanged.connect(_edit_fill_npcs)
        e_npc_cb.currentIndexChanged.connect(_edit_load_selected)
        e_save_btn.clicked.connect(_edit_save)
        e_delete_btn.clicked.connect(_edit_delete)

        # initial selection from preset base
        preset_low = str(preset_base_nickname or "").strip().lower()
        if preset_low:
            for row in bases:
                if str(row.get("nickname", "")).strip().lower() == preset_low:
                    sys_n = str(row.get("system", "")).strip().upper()
                    if sys_n:
                        c_idx = c_system_cb.findData(sys_n)
                        if c_idx >= 0:
                            c_system_cb.setCurrentIndex(c_idx)
                        e_idx = e_system_cb.findData(sys_n)
                        if e_idx >= 0:
                            e_system_cb.setCurrentIndex(e_idx)
                    break

        _create_fill_bases()
        _edit_fill_bases()

        bb = QDialogButtonBox(QDialogButtonBox.Close)
        bb.rejected.connect(self._load_universe_action)
        root.addWidget(bb)
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="npc",
            current_widget=page,
            tab_key="npc",
            open_extra_tab=True,
            title=tr("dlg.npc_editor"),
        )

    def _news_item_to_row(self, entries: list[tuple[str, str]]) -> dict:
        return news_item_to_row(entries)

    @staticmethod
    def _news_split_rank(raw: str) -> tuple[str, str]:
        return news_split_rank(raw)

    @staticmethod
    def _news_build_entries(row: dict) -> list[tuple[str, str]]:
        return news_build_entries(row)

    def _news_row_title(self, row: dict, idx: int) -> str:
        hid = str(row.get("headline", "0") or "0").strip()
        title = self._display_name_from_ids_name(hid) if hid and hid != "0" else ""
        if not title:
            title = f"News #{idx + 1}"
        bases = [str(x).strip() for x in row.get("bases", []) if str(x).strip()]
        if bases:
            return f"{title} [{len(bases)}]"
        return title

    def _open_rumor_editor(self):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"), tr("msg.no_game_path_text"))
            return
        self._reload_dll_name_cache()
        self._ids_display_cache.clear()
        mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
        if mbases_path is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.dir_not_found"))
            return
        if mbases_path.exists():
            try:
                sections = self._parser.parse(str(mbases_path))
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.error"), str(exc))
                return
        else:
            sections = []

        bases = self._npc_collect_bases(game_path)
        base_by_nick: dict[str, dict] = {}
        system_to_bases: dict[str, list[str]] = {}
        system_label_by_nick: dict[str, str] = {}
        for row in bases:
            base_nick = str(row.get("nickname", "")).strip()
            if not base_nick:
                continue
            sys_nick = str(row.get("system", "")).strip().upper()
            if not sys_nick:
                continue
            sys_name = self._system_display_name(sys_nick).strip() or sys_nick
            sys_label = f"{sys_nick} - {sys_name}" if sys_name.lower() != sys_nick.lower() else sys_nick
            system_label_by_nick[sys_nick] = sys_label
            base_by_nick[base_nick.lower()] = {
                "nickname": base_nick,
                "display": str(row.get("display", "")).strip() or base_nick,
                "system": sys_nick,
                "system_label": sys_label,
            }
            system_to_bases.setdefault(sys_nick, []).append(base_nick)
        for sys_n, base_list in system_to_bases.items():
            base_list.sort(key=lambda bn: str(base_by_nick.get(bn.lower(), {}).get("display", bn)).lower())

        npc_to_base: dict[str, str] = {}
        for idx, (sec_name, entries) in enumerate(sections):
            if str(sec_name).strip().lower() != "mbase":
                continue
            base_nick = self._entry_get_value(entries, "nickname").strip()
            if not base_nick:
                continue
            start_idx, end_idx = self._npc_find_section_range(sections, idx)
            for i in range(start_idx + 1, end_idx):
                child_name, child_entries = sections[i]
                if str(child_name).strip().lower() != "basefaction":
                    continue
                for k, v in child_entries:
                    if str(k).strip().lower() != "npc":
                        continue
                    npc_nick = str(v).strip()
                    if npc_nick:
                        npc_to_base.setdefault(npc_nick.lower(), base_nick)

        state_values = {"base_0_rank", "mission_end"}
        scope_rows: list[dict] = []

        def _row_label(r: dict) -> str:
            return rumor_row_label(r, self._display_name_from_ids_name)

        def _collect_scope_rows():
            rows, states = collect_rumor_scope_rows(
                sections,
                npc_to_base,
                base_by_nick,
                str(system_cb.currentData() or ""),
                str(base_cb.currentData() or ""),
            )
            scope_rows.clear()
            scope_rows.extend(rows)
            state_values.clear()
            state_values.update(states)

        page, page_root = self._prepare_editor_page("rumor_editor_page", tr("dlg.rumor_editor"))
        root = QHBoxLayout()
        page_root.addLayout(root, 1)
        left = QVBoxLayout()
        right = QVBoxLayout()
        root.addLayout(left, 2)
        root.addLayout(right, 3)

        group_form = QFormLayout()
        system_cb = QComboBox()
        system_cb.addItem(tr("rumor.system.select"), "")
        for sys_nick in sorted(system_to_bases.keys(), key=lambda s: str(system_label_by_nick.get(s, s)).lower()):
            system_cb.addItem(system_label_by_nick.get(sys_nick, sys_nick), sys_nick)
        base_cb = QComboBox()
        base_cb.addItem(tr("rumor.base.all_in_system"), "")
        search_edit = QLineEdit()
        search_edit.setPlaceholderText(tr("rumor.filter.search"))
        hide_story_cb = QCheckBox(tr("rumor.filter.hide_story"))
        hide_story_cb.setChecked(True)
        group_form.addRow(tr("rumor.filter.system"), system_cb)
        group_form.addRow(tr("rumor.filter.base"), base_cb)
        group_form.addRow(tr("rumor.filter.search"), search_edit)
        group_form.addRow("", hide_story_cb)
        left.addLayout(group_form)

        left.addWidget(QLabel(tr("rumor.list")))
        rumor_list = QListWidget()
        left.addWidget(rumor_list, 1)
        left_help = QLabel(tr("rumor.help.left"))
        left_help.setWordWrap(True)
        left.addWidget(left_help)

        form = QFormLayout()
        right.addLayout(form)
        help_lbl = QLabel(tr("rumor.help.fields"))
        help_lbl.setWordWrap(True)
        right.addWidget(help_lbl)

        type_cb = QComboBox()
        type_cb.addItem(tr("rumor.kind.normal"), "rumor")
        type_cb.addItem(tr("rumor.kind.type2"), "rumor_type2")
        state_from_cb = QComboBox()
        state_from_cb.setEditable(True)
        state_to_cb = QComboBox()
        state_to_cb.setEditable(True)
        weight_sb = QSpinBox()
        weight_sb.setRange(0, 100)
        weight_sb.setValue(1)
        id_edit = QLineEdit()
        id_edit.setPlaceholderText("131130")
        text_edit = QTextEdit()
        text_edit.setAcceptRichText(False)
        text_edit.setMinimumHeight(120)
        text_preview = QTextEdit()
        text_preview.setReadOnly(True)
        text_preview.setMinimumHeight(120)

        form.addRow(tr("rumor.field.type"), type_cb)
        form.addRow(tr("rumor.field.state_from"), state_from_cb)
        form.addRow(tr("rumor.field.state_to"), state_to_cb)
        form.addRow(tr("rumor.field.weight"), weight_sb)
        form.addRow(tr("rumor.field.id"), id_edit)
        form.addRow(tr("rumor.field.text_edit"), text_edit)
        form.addRow(tr("rumor.field.text_preview"), text_preview)

        btn_row = QHBoxLayout()
        btn_new = QPushButton(tr("rumor.btn.new"))
        btn_write_id = QPushButton(tr("rumor.btn.write_id"))
        btn_copy = QPushButton(tr("rumor.btn.copy_line"))
        btn_save = QPushButton(tr("rumor.btn.save"))
        btn_delete = QPushButton(tr("rumor.btn.delete"))
        btn_close = QPushButton(tr("dlg.close"))
        btn_row.addWidget(btn_new)
        btn_row.addWidget(btn_write_id)
        btn_row.addWidget(btn_copy)
        btn_row.addWidget(btn_save)
        btn_row.addWidget(btn_delete)
        btn_row.addStretch()
        btn_row.addWidget(btn_close)
        right.addLayout(btn_row)

        selection = {"sec_idx": -1, "entry_idx": -1, "kind": "rumor", "line": ""}

        def _selected_row_key() -> tuple[int, int]:
            return (int(selection.get("sec_idx", -1)), int(selection.get("entry_idx", -1)))

        def _apply_list_filter(select_key: tuple[int, int] | None = None):
            term = search_edit.text().strip().lower()
            hide_story = bool(hide_story_cb.isChecked())
            filtered: list[dict] = []
            for row in scope_rows:
                if hide_story and str(row.get("kind", "")).lower() == "rumor_type2":
                    continue
                hay = " | ".join(
                    [
                        str(row.get("line", "")),
                        str(row.get("npc", "")),
                        str(row.get("base_nick", "")),
                        str(row.get("base_display", "")),
                    ]
                ).lower()
                if term and term not in hay:
                    continue
                filtered.append(row)
            rumor_list.blockSignals(True)
            rumor_list.clear()
            if not str(system_cb.currentData() or "").strip():
                hint = QListWidgetItem(tr("rumor.msg.select_system_first"))
                hint.setFlags(Qt.ItemIsEnabled)
                rumor_list.addItem(hint)
                rumor_list.blockSignals(False)
                return
            if not filtered:
                hint = QListWidgetItem(tr("rumor.msg.no_entries_scope"))
                hint.setFlags(Qt.ItemIsEnabled)
                rumor_list.addItem(hint)
                rumor_list.blockSignals(False)
                return
            group_counts: dict[tuple[str, str], int] = {}
            for row in filtered:
                key = (str(row.get("system_label", "")), str(row.get("base_display", "")))
                group_counts[key] = int(group_counts.get(key, 0)) + 1
            current_group: tuple[str, str] | None = None
            selected_index = -1
            for row in filtered:
                gk = (str(row.get("system_label", "")), str(row.get("base_display", "")))
                if current_group != gk:
                    current_group = gk
                    header = QListWidgetItem(f"{gk[0]} / {gk[1]} ({group_counts.get(gk, 0)})")
                    header.setFlags(Qt.ItemIsEnabled)
                    rumor_list.addItem(header)
                item = QListWidgetItem(_row_label(row))
                item.setData(Qt.UserRole, row)
                rumor_list.addItem(item)
                if select_key is not None and (
                    int(row.get("sec_idx", -1)) == select_key[0]
                    and int(row.get("entry_idx", -1)) == select_key[1]
                ):
                    selected_index = rumor_list.count() - 1
            rumor_list.blockSignals(False)
            if selected_index >= 0:
                rumor_list.setCurrentRow(selected_index)
            else:
                for i in range(rumor_list.count()):
                    it = rumor_list.item(i)
                    if isinstance(it.data(Qt.UserRole), dict):
                        rumor_list.setCurrentRow(i)
                        break

        def _rebuild_base_combo():
            sys_nick = str(system_cb.currentData() or "").strip().upper()
            prev = str(base_cb.currentData() or "").strip().lower()
            base_cb.blockSignals(True)
            base_cb.clear()
            base_cb.addItem(tr("rumor.base.all_in_system"), "")
            for base_nick in system_to_bases.get(sys_nick, []):
                meta = base_by_nick.get(base_nick.lower(), {})
                base_cb.addItem(f"{meta.get('display', base_nick)} ({base_nick})", base_nick)
            if prev:
                idx = base_cb.findData(prev)
                if idx >= 0:
                    base_cb.setCurrentIndex(idx)
            base_cb.blockSignals(False)

        def _fill_state_combos():
            current_from = state_from_cb.currentText().strip()
            current_to = state_to_cb.currentText().strip()
            state_from_cb.blockSignals(True)
            state_to_cb.blockSignals(True)
            state_from_cb.clear()
            state_to_cb.clear()
            ordered = sorted(state_values)
            state_from_cb.addItems(ordered)
            state_to_cb.addItems(ordered)
            state_from_cb.setCurrentText(current_from or "base_0_rank")
            state_to_cb.setCurrentText(current_to or "mission_end")
            state_from_cb.blockSignals(False)
            state_to_cb.blockSignals(False)

        def _refresh_scope(select_key: tuple[int, int] | None = None):
            _collect_scope_rows()
            _fill_state_combos()
            _apply_list_filter(select_key)

        def _current_line() -> str:
            return build_rumor_line(
                state_from=state_from_cb.currentText(),
                state_to=state_to_cb.currentText(),
                weight=weight_sb.value(),
                rumor_id=id_edit.text(),
            )

        def _refresh_preview():
            rid = id_edit.text().strip()
            txt = self._display_text_from_ids_value(rid) if rid else ""
            text_preview.setPlainText(txt or tr("rumor.msg.id_not_resolved").format(id=rid or "0"))

        def _load_selected():
            item = rumor_list.currentItem()
            if item is None:
                return
            row = item.data(Qt.UserRole)
            if not isinstance(row, dict):
                return
            selection.update(
                {
                    "sec_idx": int(row.get("sec_idx", -1)),
                    "entry_idx": int(row.get("entry_idx", -1)),
                    "kind": str(row.get("kind", "rumor")),
                    "line": str(row.get("line", "")),
                }
            )
            form_data = rumor_form_data(selection["kind"], selection["line"])
            type_cb.setCurrentIndex(int(form_data["type_index"]))
            state_from_cb.setCurrentText(str(form_data["state_from"]))
            state_to_cb.setCurrentText(str(form_data["state_to"]))
            weight_sb.setValue(int(form_data["weight"]))
            rumor_id = str(form_data["rumor_id"])
            id_edit.setText(rumor_id)
            text_edit.setPlainText(self._display_text_from_ids_value(rumor_id) if rumor_id else "")
            _refresh_preview()

        def _new_line():
            selection.update({"sec_idx": -1, "entry_idx": -1, "kind": "rumor", "line": ""})
            type_cb.setCurrentIndex(0)
            state_from_cb.setCurrentText("base_0_rank")
            state_to_cb.setCurrentText("mission_end")
            weight_sb.setValue(1)
            id_edit.setText("")
            text_edit.clear()
            _refresh_preview()

        def _write_text_to_dll():
            raw = text_edit.toPlainText().strip()
            if not raw:
                return
            cur = id_edit.text().strip() or "0"
            try:
                gid = str(self._ensure_ids_name_in_user_dll(cur, raw))
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            id_edit.setText(gid)
            self._reload_dll_name_cache()
            self._ids_display_cache.clear()
            _refresh_preview()

        def _save_line():
            sec_idx = int(selection.get("sec_idx", -1))
            entry_idx = int(selection.get("entry_idx", -1))
            if sec_idx < 0 or entry_idx < 0:
                QMessageBox.information(self, tr("msg.incomplete"), tr("rumor.msg.select_entry"))
                return
            if not (0 <= sec_idx < len(sections)):
                return
            sec_name, entries = sections[sec_idx]
            if not (0 <= entry_idx < len(entries)):
                return
            new_key = str(type_cb.currentData() or "rumor").strip()
            new_line = _current_line()
            if not new_line:
                QMessageBox.warning(self, tr("msg.incomplete"), tr("rumor.msg.line_required"))
                return
            entries = list(entries)
            entries[entry_idx] = (new_key, new_line)
            sections[sec_idx] = (sec_name, entries)
            try:
                mbases_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(mbases_path), sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self._append_change_log(f"Rumor bearbeitet: {new_key} = {new_line}")
            self.statusBar().showMessage(tr("status.rumor_saved"))
            _refresh_scope(_selected_row_key())

        def _delete_line():
            sec_idx = int(selection.get("sec_idx", -1))
            entry_idx = int(selection.get("entry_idx", -1))
            if sec_idx < 0 or entry_idx < 0:
                return
            ans = QMessageBox.question(
                self,
                tr("rumor.btn.delete"),
                tr("rumor.msg.delete_confirm"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if ans != QMessageBox.Yes:
                return
            if not (0 <= sec_idx < len(sections)):
                return
            sec_name, entries = sections[sec_idx]
            entries = list(entries)
            if not (0 <= entry_idx < len(entries)):
                return
            _k, old_line = entries.pop(entry_idx)
            sections[sec_idx] = (sec_name, entries)
            try:
                mbases_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(mbases_path), sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self._append_change_log(f"Rumor gelöscht: {old_line}")
            self.statusBar().showMessage(tr("status.rumor_deleted"))
            _refresh_scope()

        def _copy_line():
            line = _current_line()
            if not line:
                return
            QApplication.clipboard().setText(line)
            self.statusBar().showMessage(tr("status.rumor_line_copied"))

        def _on_system_changed():
            _rebuild_base_combo()
            _refresh_scope()

        def _on_base_changed():
            _refresh_scope()

        rumor_list.currentRowChanged.connect(lambda _r: _load_selected())
        id_edit.textChanged.connect(lambda _t: _refresh_preview())
        connect_debounced_line_edit(search_edit, lambda: _apply_list_filter(_selected_row_key()))
        hide_story_cb.toggled.connect(lambda _c: _apply_list_filter(_selected_row_key()))
        system_cb.currentIndexChanged.connect(_on_system_changed)
        base_cb.currentIndexChanged.connect(_on_base_changed)
        btn_new.clicked.connect(_new_line)
        btn_write_id.clicked.connect(_write_text_to_dll)
        btn_copy.clicked.connect(_copy_line)
        btn_save.clicked.connect(_save_line)
        btn_delete.clicked.connect(_delete_line)
        btn_close.clicked.connect(self._load_universe_action)

        _on_system_changed()
        if rumor_list.count() == 0:
            _new_line()
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="rumor",
            current_widget=page,
            tab_key="rumor",
            open_extra_tab=True,
            title=tr("dlg.rumor_editor"),
        )

    def _open_news_editor(self):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"), tr("msg.no_game_path_text"))
            return
        self._reload_dll_name_cache()
        self._ids_display_cache.clear()
        news_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/news.ini")
        if news_path is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.dir_not_found"))
            return
        if news_path.exists():
            try:
                sections = self._parser.parse(str(news_path))
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.error"), str(exc))
                return
        else:
            sections = []
        rank_states: set[str] = set()
        logo_values: set[str] = set()
        icon_values: set[str] = set()
        for sec_name, entries in sections:
            if str(sec_name).strip().lower() != "newsitem":
                continue
            for k, v in entries:
                key = str(k).strip().lower()
                val = str(v).strip()
                if key == "rank":
                    a, b = self._news_split_rank(val)
                    if a:
                        rank_states.add(a)
                    if b:
                        rank_states.add(b)
                elif key == "logo" and val:
                    logo_values.add(val)
                elif key == "icon" and val:
                    icon_values.add(val)
        if not icon_values:
            icon_values = {"world", "critical"}
        bases = self._npc_collect_bases(game_path)
        known_base_rows = sorted(
            [(str(b.get("nickname", "")).strip(), str(b.get("display", "")).strip()) for b in bases if str(b.get("nickname", "")).strip()],
            key=lambda x: x[1].lower(),
        )

        page, page_root = self._prepare_editor_page("news_editor_page", tr("dlg.news_editor"))
        root = QHBoxLayout()
        page_root.addLayout(root, 1)

        left = QVBoxLayout()
        right = QVBoxLayout()
        root.addLayout(left, 1)
        root.addLayout(right, 2)

        news_list = QListWidget()
        left.addWidget(QLabel(tr("news.list")))
        left.addWidget(news_list, 1)
        left_btns = QHBoxLayout()
        btn_new = QPushButton(tr("news.btn.new"))
        btn_delete = QPushButton(tr("news.btn.delete"))
        left_btns.addWidget(btn_new)
        left_btns.addWidget(btn_delete)
        left.addLayout(left_btns)
        left_help = QLabel(tr("news.help.left"))
        left_help.setWordWrap(True)
        left.addWidget(left_help)

        form = QFormLayout()
        right.addLayout(form)

        help_lbl = QLabel(tr("news.help.fields"))
        help_lbl.setWordWrap(True)
        right.addWidget(help_lbl)

        rank_from_edit = QComboBox()
        rank_from_edit.setEditable(True)
        rank_from_edit.addItems(sorted(rank_states))
        rank_to_edit = QComboBox()
        rank_to_edit.setEditable(True)
        rank_to_edit.addItems(sorted(rank_states))
        form.addRow(tr("news.field.rank_from"), rank_from_edit)
        form.addRow(tr("news.field.rank_to"), rank_to_edit)
        autoselect_cb = QCheckBox(tr("news.field.autoselect"))
        form.addRow("", autoselect_cb)
        icon_edit = QComboBox()
        icon_edit.setEditable(True)
        icon_edit.addItems(sorted(icon_values))
        logo_edit = QComboBox()
        logo_edit.setEditable(True)
        logo_edit.addItems(sorted(logo_values))
        form.addRow(tr("news.field.icon"), icon_edit)
        form.addRow(tr("news.field.logo"), logo_edit)

        category_id_edit = QLineEdit("0")
        category_text_edit = QLineEdit()
        form.addRow(tr("news.field.category_id"), category_id_edit)
        form.addRow(tr("news.field.category_text"), category_text_edit)
        headline_id_edit = QLineEdit("0")
        headline_text_edit = QLineEdit()
        form.addRow(tr("news.field.headline_text"), headline_text_edit)
        text_id_edit = QLineEdit("0")
        text_text_edit = QTextEdit()
        text_text_edit.setAcceptRichText(False)
        text_text_edit.setMinimumHeight(120)
        form.addRow(tr("news.field.text_text"), text_text_edit)

        form.addRow(QLabel(tr("news.field.bases")))
        base_list = QListWidget()
        base_list.setSelectionMode(QAbstractItemView.NoSelection)
        base_items: dict[str, QListWidgetItem] = {}
        for base_nick, base_disp in known_base_rows:
            it = QListWidgetItem(f"{base_disp} ({base_nick})")
            it.setData(Qt.UserRole, base_nick)
            it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
            it.setCheckState(Qt.Unchecked)
            base_list.addItem(it)
            base_items[base_nick.lower()] = it
        right.addWidget(base_list, 1)

        usage_view = QTextEdit()
        usage_view.setReadOnly(True)
        usage_view.setMinimumHeight(120)
        right.addWidget(QLabel(tr("news.usage")))
        right.addWidget(usage_view)

        action_row = QHBoxLayout()
        btn_save = QPushButton(tr("news.btn.save"))
        btn_close = QPushButton(tr("dlg.close"))
        action_row.addWidget(btn_save)
        action_row.addStretch()
        action_row.addWidget(btn_close)
        right.addLayout(action_row)

        def _collect_news_indices() -> list[int]:
            return [i for i, (sec, _en) in enumerate(sections) if str(sec).strip().lower() == "newsitem"]

        news_indices = _collect_news_indices()
        current_news_index = {"value": -1}

        def _ensure_base_item(base_nick: str):
            b = str(base_nick or "").strip()
            if not b:
                return None
            key = b.lower()
            if key in base_items:
                return base_items[key]
            it = QListWidgetItem(f"{b} ({tr('news.base_unknown')})")
            it.setData(Qt.UserRole, b)
            it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
            it.setCheckState(Qt.Unchecked)
            base_list.addItem(it)
            base_items[key] = it
            return it

        def _set_checked_bases(bases_list: list[str]):
            wanted = {str(x).strip().lower() for x in bases_list if str(x).strip()}
            for i in range(base_list.count()):
                it = base_list.item(i)
                bn = str(it.data(Qt.UserRole) or "").strip().lower()
                it.setCheckState(Qt.Checked if bn in wanted else Qt.Unchecked)

        def _checked_bases() -> list[str]:
            out: list[str] = []
            for i in range(base_list.count()):
                it = base_list.item(i)
                if it.checkState() == Qt.Checked:
                    bn = str(it.data(Qt.UserRole) or "").strip()
                    if bn:
                        out.append(bn)
            return out

        def _refresh_usage():
            selected = _checked_bases()
            if not selected:
                usage_view.setPlainText(tr("news.usage_none"))
                return
            lines = [tr("news.usage_count").format(count=len(selected))]
            lines.extend(selected)
            usage_view.setPlainText("\n".join(lines))

        def _refresh_list(select_pos: int | None = None):
            nonlocal news_indices
            news_indices = _collect_news_indices()
            news_list.blockSignals(True)
            news_list.clear()
            for pos, sec_idx in enumerate(news_indices):
                row = self._news_item_to_row(list(sections[sec_idx][1]))
                title = self._news_row_title(row, pos)
                item = QListWidgetItem(title)
                item.setData(Qt.UserRole, sec_idx)
                news_list.addItem(item)
            news_list.blockSignals(False)
            if news_list.count() == 0:
                current_news_index["value"] = -1
                return
            fm = news_list.fontMetrics()
            max_w = fm.horizontalAdvance("News #00000 [000]")
            for i in range(news_list.count()):
                max_w = max(max_w, fm.horizontalAdvance(news_list.item(i).text()))
            target_w = max(210, min(max_w + 48, 420))
            news_list.setMinimumWidth(target_w)
            news_list.setMaximumWidth(target_w + 20)
            if select_pos is None:
                select_pos = 0
            select_pos = max(0, min(select_pos, news_list.count() - 1))
            news_list.setCurrentRow(select_pos)

        def _load_selected():
            item = news_list.currentItem()
            if item is None:
                current_news_index["value"] = -1
                return
            sec_idx = int(item.data(Qt.UserRole))
            current_news_index["value"] = sec_idx
            row = self._news_item_to_row(list(sections[sec_idx][1]))
            r1, r2 = self._news_split_rank(str(row.get("rank", "")))
            rank_from_edit.setCurrentText(r1)
            rank_to_edit.setCurrentText(r2)
            autoselect_cb.setChecked(bool(row.get("autoselect", False)))
            icon_edit.setCurrentText(str(row.get("icon", "") or ""))
            logo_edit.setCurrentText(str(row.get("logo", "") or ""))
            category_id = str(row.get("category", "0") or "0")
            headline_id = str(row.get("headline", "0") or "0")
            text_id = str(row.get("text", "0") or "0")
            category_id_edit.setText(category_id)
            headline_id_edit.setText(headline_id)
            text_id_edit.setText(text_id)
            category_resolved = self._display_name_from_ids_name(category_id)
            headline_resolved = self._display_name_from_ids_name(headline_id)
            text_resolved = self._display_name_from_ids_name(text_id)
            category_text_edit.setText(category_resolved or tr("news.msg.id_not_resolved").format(id=category_id))
            headline_text_edit.setText(headline_resolved or tr("news.msg.id_not_resolved").format(id=headline_id))
            text_text_edit.setPlainText(text_resolved or tr("news.msg.id_not_resolved").format(id=text_id))
            for b in row.get("bases", []):
                _ensure_base_item(str(b))
            _set_checked_bases([str(b) for b in row.get("bases", [])])
            _refresh_usage()

        def _new_item():
            entries = self._news_build_entries(
                {
                    "rank_from": "base_0_rank",
                    "rank_to": "mission_end",
                    "autoselect": False,
                    "icon": "world",
                    "logo": "",
                    "category": "0",
                    "headline": "0",
                    "text": "0",
                    "bases": [],
                }
            )
            sections.append(("NewsItem", entries))
            _refresh_list(news_list.count())

        def _delete_item():
            cur = news_list.currentRow()
            if cur < 0:
                return
            ans = QMessageBox.question(
                self,
                tr("news.btn.delete"),
                tr("news.msg.delete_confirm"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if ans != QMessageBox.Yes:
                return
            item = news_list.currentItem()
            if item is None:
                return
            sec_idx = int(item.data(Qt.UserRole))
            if 0 <= sec_idx < len(sections):
                sections.pop(sec_idx)
            _refresh_list(max(0, cur - 1))

        def _save_item():
            item = news_list.currentItem()
            if item is None:
                return
            sec_idx = int(item.data(Qt.UserRole))
            if not (0 <= sec_idx < len(sections)):
                return

            def _resolve_id(current_raw: str, text_raw: str) -> str:
                txt = str(text_raw or "").strip()
                cur = str(current_raw or "").strip() or "0"
                if not txt:
                    return cur
                try:
                    return str(self._ensure_ids_name_in_user_dll(cur, txt))
                except Exception:
                    return cur

            cat_id = _resolve_id(category_id_edit.text(), category_text_edit.text())
            head_id = _resolve_id(headline_id_edit.text(), headline_text_edit.text())
            txt_id = _resolve_id(text_id_edit.text(), text_text_edit.toPlainText())

            row = build_news_save_row(
                rank_from=rank_from_edit.currentText(),
                rank_to=rank_to_edit.currentText(),
                autoselect=autoselect_cb.isChecked(),
                icon=icon_edit.currentText(),
                logo=logo_edit.currentText(),
                category_id=cat_id,
                headline_id=head_id,
                text_id=txt_id,
                bases=_checked_bases(),
            )
            sections[sec_idx] = ("NewsItem", self._news_build_entries(row))
            try:
                news_path.parent.mkdir(parents=True, exist_ok=True)
                self._write_sections_to_file(str(news_path), sections)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), str(exc))
                return
            self._reload_dll_name_cache()
            self._ids_display_cache.clear()
            _refresh_list(news_list.currentRow())
            self.statusBar().showMessage(tr("status.news_saved"))
            self._append_change_log(f"News gespeichert: {self._news_row_title(row, news_list.currentRow())}")

        news_list.currentRowChanged.connect(lambda _r: _load_selected())
        base_list.itemChanged.connect(lambda _it: _refresh_usage())
        btn_new.clicked.connect(_new_item)
        btn_delete.clicked.connect(_delete_item)
        btn_save.clicked.connect(_save_item)
        btn_close.clicked.connect(self._load_universe_action)

        _refresh_list(0)
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="news",
            current_widget=page,
            tab_key="news",
            open_extra_tab=True,
            title=tr("dlg.news_editor"),
        )

    # ------------------------------------------------------------------
    #  Base löschen
    # ------------------------------------------------------------------
    def _delete_base(self):
        """Löscht die ausgewählte Base komplett: Objekt, universe.ini-Eintrag,
        Market-Einträge, Base-INI und Room-Dateien."""
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return

        idx = self.obj_combo.currentIndex()
        if idx < 0:
            self.statusBar().showMessage(tr("status.no_object_selected"))
            return
        item = self.obj_combo.itemData(idx)
        if not isinstance(item, SolarObject):
            QMessageBox.information(
                self, tr("msg.no_object"),
                tr("msg.no_object_text")
            )
            return

        base_nick = base_nickname_from_object_entries(item.data.get("_entries", []))
        if not base_nick:
            QMessageBox.information(
                self, tr("msg.no_base"),
                tr("msg.no_base_text")
            )
            return

        # Bestätigung
        reply = QMessageBox.warning(
            self, tr("msg.delete_base"),
            tr("msg.delete_base_text").format(
                nickname=base_nick,
                details=tr("msg.delete_base_details")
            ),
            QMessageBox.Ok | QMessageBox.Cancel,
        )
        if reply != QMessageBox.Ok:
            return

        game_path = self._primary_game_path()
        bn_lower = base_nick.lower()
        result: list[str] = []

        # ── 1) Alle Objekte mit dieser Base aus dem System entfernen ──
        objs_to_remove: list[SolarObject] = []
        for obj in self._objects:
            for k, v in obj.data.get("_entries", []):
                kl = k.lower()
                if kl in ("base", "dock_with") and v.strip().lower() == bn_lower:
                    objs_to_remove.append(obj)
                    break

        for obj in objs_to_remove:
            obj_idx = None
            try:
                obj_idx = self._objects.index(obj)
            except ValueError:
                continue
            # Sektion in _sections entfernen
            count = 0
            for i, (sec_name, entries) in enumerate(list(self._sections)):
                if sec_name.lower() == "object":
                    if count == obj_idx:
                        self._sections.pop(i)
                        break
                    count += 1
            self.view._scene.removeItem(obj)
            self._objects.remove(obj)
            result.append(tr("result.obj_removed").format(nickname=obj.nickname))

        # ── 2) [Base] aus universe.ini entfernen ──
        if hasattr(self, "_uni_sections") and self._uni_sections:
            self._uni_sections, uni_removed = remove_base_from_universe_sections(self._uni_sections, base_nick)
            if uni_removed:
                uni_ini = self._find_universe_ini_write(game_path)
                if uni_ini:
                    try:
                        self._write_sections_to_file(str(uni_ini), self._uni_sections)
                        result.append(tr("result.base_removed_uni").format(nickname=base_nick))
                    except Exception as ex:
                        result.append(tr("result.uni_error").format(error=ex))
            else:
                result.append(tr("result.base_not_in_uni").format(nickname=base_nick))
        else:
            # _uni_sections nicht geladen – universe.ini direkt parsen
            uni_ini = self._find_universe_ini_write(game_path)
            if uni_ini:
                try:
                    uni_secs = self._parser.parse(str(uni_ini))
                    new_secs, removed = remove_base_from_universe_sections(uni_secs, base_nick)
                    if removed:
                        self._write_sections_to_file(str(uni_ini), new_secs)
                        result.append(tr("result.base_removed_uni").format(nickname=base_nick))
                    else:
                        result.append(tr("result.base_not_in_uni").format(nickname=base_nick))
                except Exception as ex:
                    result.append(tr("result.uni_error").format(error=ex))

        # ── 3) MBase-Block aus mbases.ini entfernen ──
        try:
            mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
            if mbases_path and mbases_path.exists():
                mbases_path = Path(self._ensure_writable_path(mbases_path))
                mb_sections = self._parser.parse(str(mbases_path))
                mbase_idx: int | None = None
                for i, (sec_name, entries) in enumerate(mb_sections):
                    if str(sec_name).strip().lower() != "mbase":
                        continue
                    if self._entry_get_value(entries, "nickname").strip().lower() == bn_lower:
                        mbase_idx = i
                        break
                if mbase_idx is not None:
                    mb_sections, _removed, block_count, stray_removed = remove_mbase_block_for_base(
                        mb_sections,
                        base_nick,
                    )
                    mbases_path.parent.mkdir(parents=True, exist_ok=True)
                    self._write_sections_to_file(str(mbases_path), mb_sections)
                    result.append(
                        f"mbases.ini: removed block for {base_nick} ({block_count} sections, {stray_removed} stray GF_NPC)"
                    )
                else:
                    result.append(f"mbases.ini: no MBase block found for {base_nick}")
        except Exception as ex:
            result.append(f"mbases.ini: cleanup failed ({ex})")

        # ── 4) Market-Einträge entfernen ──
        for mf_name in ("market_misc.ini", "market_commodities.ini", "market_ships.ini"):
            if self._remove_market_base(game_path, mf_name, base_nick):
                result.append(tr("result.basegood_removed").format(file=mf_name))

        # ── 5) Base-INI und Room-Dateien löschen ──
        if game_path:
            sys_nick = Path(self._filepath).stem
            uni_dir = self._resolve_data_subdir_case_insensitive(game_path, "UNIVERSE")
            if uni_dir:
                    # Base-INI suchen
                    base_ini = ci_resolve(
                        uni_dir, f"SYSTEMS/{sys_nick}/BASES/{base_nick}.ini"
                    )
                    if base_ini and base_ini.exists():
                        # Room-Dateien aus Base-INI lesen und löschen
                        try:
                            base_secs = self._parser.parse(str(base_ini))
                            for room_rel in room_files_from_base_sections(base_secs):
                                room_file = self._resolve_game_path_case_insensitive(game_path, room_rel)
                                if room_file and room_file.exists():
                                    room_file.unlink()
                                    result.append(
                                        tr("result.room_deleted").format(file=room_file.name)
                                    )
                        except Exception:
                            pass

                        # Base-INI selbst löschen
                        base_ini.unlink()
                        result.append(tr("result.base_ini_deleted").format(file=base_ini.name))

                        # Verbleibende Room-Dateien im ROOMS-Ordner aufräumen
                        sys_dir = ci_find(uni_dir / "SYSTEMS" if (uni_dir / "SYSTEMS").exists()
                                          else uni_dir, sys_nick) if uni_dir else None
                        if not sys_dir:
                            sys_dir = ci_find(uni_dir, "SYSTEMS")
                            if sys_dir:
                                sys_dir = ci_find(sys_dir, sys_nick)
                        bases_dir = ci_find(sys_dir, "BASES") if sys_dir else None
                        rooms_dir = ci_find(bases_dir, "ROOMS") if bases_dir else None
                        if rooms_dir and rooms_dir.is_dir():
                            remaining = [
                                f for f in rooms_dir.iterdir()
                                if f.name.lower().startswith(base_nick.lower() + "_")
                            ]
                            for rf in remaining:
                                rf.unlink()
                                result.append(tr("result.room_deleted").format(file=rf.name))
                    else:
                        result.append(tr("result.base_ini_not_found").format(nickname=base_nick))

        # ── Abschluss ──
        if self._selected in objs_to_remove:
            self._selected = None
            self._clear_selection_ui()
            self._hide_zone_extra_editors()

        self._rebuild_object_combo()
        self._set_dirty(True)
        self._write_to_file(reload=False)
        if self._base_builder_active_base_nick and base_nick.lower() == str(self._base_builder_active_base_nick).lower():
            self._close_base_builder()
        self._refresh_3d_scene()

        QMessageBox.information(
            self, tr("msg.base_deleted"),
            tr("msg.base_deleted_text").format(
                nickname=base_nick, details="\n".join(result)
            )
        )
        self.statusBar().showMessage(tr("status.base_deleted").format(nickname=base_nick))

    def _remove_market_base(
        self, game_path: str, market_file: str, base_nick: str
    ) -> bool:
        """Entfernt den [BaseGood]-Eintrag einer Base aus einer Market-Datei."""
        mf = self._target_game_path_for_rel(game_path, f"DATA/EQUIPMENT/{market_file}")
        if not mf:
            return False
        mf = self._ensure_writable_path(mf)
        if not mf.exists():
            return False
        try:
            sections = self._parser.parse(str(mf))
        except Exception:
            return False

        bn = base_nick.strip().lower()
        new_sections = []
        removed = False
        for sec_name, entries in sections:
            if sec_name.lower() == "basegood":
                is_match = False
                for k, v in entries:
                    if k.lower() == "base" and v.strip().lower() == bn:
                        is_match = True
                        break
                if is_match:
                    removed = True
                    continue  # Diese Sektion überspringen
            new_sections.append((sec_name, entries))

        if not removed:
            return False

        # Datei zurückschreiben
        lines: list[str] = []
        for sec_name, entries in new_sections:
            lines.append(f"[{sec_name}]")
            for k, v in entries:
                lines.append(f"{k} = {v}")
            lines.append("")
        try:
            tmp = str(mf) + ".tmp"
            Path(tmp).write_text("\n".join(lines), encoding="utf-8")
            shutil.move(tmp, str(mf))
        except Exception:
            return False
        return True

    # ------------------------------------------------------------------
    #  Docking Ring an Planet anhängen
    # ------------------------------------------------------------------
    def _attach_docking_ring(self):
        """Startet den Docking-Ring-Workflow: Klick auf Planet → Dialog → Orbit-Platzierung."""
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        game_path = self._primary_game_path()
        if not game_path:
            self._warn_missing_game_path("msg.error")
            return
        self._pending_dock_ring = {"step": 1, "game_path": game_path}
        self._set_placement_mode(True, tr("placement.dock_ring"))

    def _on_dock_ring_planet_selected(self, item: SolarObject):
        """Schritt 1: Planet wurde angeklickt – kombinierter Dialog für Ring + Base."""
        dr = self._pending_dock_ring
        if not dr or dr.get("step") != 1:
            return

        planet_nick = item.data.get("nickname", "").strip()
        game_path = dr["game_path"]

        # Prüfe: Hat der Planet ein base-Feld?
        base_nick = ""
        for k, v in item.data.get("_entries", []):
            if k.lower() == "base":
                base_nick = v.strip()
                break

        needs_base = not base_nick

        # Prüfe: Gibt es schon einen Docking Ring mit dock_with auf diese Base?
        if base_nick:
            for sec_name, entries in self._sections:
                if sec_name.lower() != "object":
                    continue
                has_dock_with = False
                for k, v in entries:
                    if k.lower() == "dock_with" and v.strip().lower() == base_nick.lower():
                        has_dock_with = True
                        break
                if has_dock_with:
                    ring_nick = ""
                    for k, v in entries:
                        if k.lower() == "nickname":
                            ring_nick = v.strip()
                            break
                    ret = QMessageBox.question(
                        self, tr("msg.dock_ring_exists"),
                        tr("msg.dock_ring_exists_text").format(
                            nickname=ring_nick, base=base_nick
                        ),
                        QMessageBox.Yes | QMessageBox.No,
                    )
                    if ret != QMessageBox.Yes:
                        self._pending_dock_ring = None
                        self._set_placement_mode(False)
                        return

        # Base-Nickname generieren falls nötig
        sys_nick = Path(self._filepath).stem
        sys_upper = sys_nick.upper()
        if needs_base:
            existing_nums: list[int] = []
            prefix = f"{sys_upper}_"
            for sec_name, entries in self._uni_sections:
                if sec_name.lower() == "base":
                    for k, v in entries:
                        if k.lower() == "nickname":
                            nick = v.strip().upper()
                            if nick.startswith(prefix) and nick.endswith("_BASE"):
                                mid = nick[len(prefix):-len("_BASE")]
                                if mid.isdigit():
                                    existing_nums.append(int(mid))
                            break
            next_num = max(existing_nums, default=0) + 1
            base_nick = f"{sys_upper}_{next_num:02d}_Base"

        # Existierende Bases für Template-Dropdown
        existing_bases: list[tuple[str, str]] = []
        for sec_name, entries in self._uni_sections:
            if sec_name.lower() == "base":
                base_nick = ""
                base_strid = ""
                for k, v in entries:
                    kl = k.lower()
                    if kl == "nickname":
                        base_nick = v.strip()
                    elif kl == "strid_name":
                        base_strid = v.strip()
                if base_nick:
                    base_label = self._base_display_name(base_nick, base_strid)
                    if base_label and base_label.lower() != base_nick.lower():
                        base_label = f"{base_label} ({base_nick})"
                    elif not base_label:
                        base_label = base_nick
                    existing_bases.append((base_label, base_nick))

        # Listen zusammenbauen
        loadouts = [
            self.loadout_cb.itemText(i)
            for i in range(self.loadout_cb.count())
            if self.loadout_cb.itemText(i)
        ]
        factions = [
            self.faction_cb.itemText(i)
            for i in range(self.faction_cb.count())
            if self.faction_cb.itemText(i)
        ]
        pilots = self._scan_pilots(game_path)
        voices = self._scan_voices(game_path)

        dlg = DockingRingDialog(
            self,
            planet_nickname=planet_nick,
            base_nickname=base_nick,
            loadouts=loadouts,
            factions=factions,
            existing_bases=existing_bases if needs_base else None,
            pilots=pilots,
            voices=voices,
            needs_base=needs_base,
        )
        if dlg.exec() != QDialog.Accepted:
            self._pending_dock_ring = None
            self._set_placement_mode(False)
            return

        data_in = dlg.payload()
        nickname = data_in.get("nickname", "").strip()
        if not nickname:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.enter_nickname"))
            self._pending_dock_ring = None
            self._set_placement_mode(False)
            return

        # Validierung: Rooms (nur wenn Base neu erstellt wird)
        if needs_base:
            if not data_in.get("rooms"):
                QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.min_one_room"))
                self._pending_dock_ring = None
                self._set_placement_mode(False)
                return
            if data_in.get("start_room") not in data_in.get("rooms", []):
                QMessageBox.warning(
                    self, tr("msg.invalid"),
                    tr("msg.start_room_invalid").format(room=data_in.get('start_room'))
                )
                self._pending_dock_ring = None
                self._set_placement_mode(False)
                return

        # Prüfe Nickname-Eindeutigkeit
        for obj in self._objects:
            if obj.data.get("nickname", "").strip().lower() == nickname.lower():
                QMessageBox.warning(
                    self, tr("msg.nickname_exists"),
                    tr("msg.nickname_exists_text").format(nickname=nickname)
                )
                self._pending_dock_ring = None
                self._set_placement_mode(False)
                return

        # Planet-Position (Szenenkoordinaten) und Orbit-Radius bestimmen
        planet_scene_x = item.pos().x()
        planet_scene_y = item.pos().y()

        # atmosphere_range als Orbit-Radius verwenden
        atmo = 0
        for k, v in item.data.get("_entries", []):
            if k.lower() == "atmosphere_range":
                try:
                    atmo = int(v.strip())
                except ValueError:
                    pass
                break
        orbit_world = max(atmo, 1000)  # Minimum 1000 als Sicherheit
        orbit_scene = orbit_world * self._scale

        # Orbit-Kreis zeichnen (gestrichelt, gelb)
        pen = QPen(self._scene_role_color("measure", 180), 2, Qt.DashLine)
        self._dock_ring_orbit_circle = self.view._scene.addEllipse(
            planet_scene_x - orbit_scene,
            planet_scene_y - orbit_scene,
            orbit_scene * 2,
            orbit_scene * 2,
            pen,
        )
        self._dock_ring_orbit_circle.setZValue(9998)

        # Vorschau-Punkt auf dem Kreis (kleiner gefüllter Kreis)
        dot_r = 3
        dot_pen = QPen(self._scene_role_color("highlight"), 2)
        dot_brush = QBrush(self._scene_role_color("highlight", 200))
        self._dock_ring_preview_dot = self.view._scene.addEllipse(
            -dot_r, -dot_r, dot_r * 2, dot_r * 2, dot_pen, dot_brush,
        )
        self._dock_ring_preview_dot.setZValue(9999)

        # Planet-Weltkoordinaten für spätere Berechnung
        planet_pos_str = item.data.get("pos", "0, 0, 0")
        parts = [p.strip() for p in planet_pos_str.split(",")]
        try:
            px, py, pz = float(parts[0]), float(parts[1]), float(parts[2])
        except (ValueError, IndexError):
            px, py, pz = 0.0, 0.0, 0.0

        # State für Schritt 2 speichern
        dr["step"] = 2
        dr["planet_item"] = item
        dr["planet_nick"] = planet_nick
        dr["base_nick"] = data_in.get("base_nickname", base_nick)
        dr["needs_base"] = needs_base
        dr["sys_nick"] = sys_nick
        dr["planet_scene_x"] = planet_scene_x
        dr["planet_scene_y"] = planet_scene_y
        dr["planet_world"] = (px, py, pz)
        dr["orbit_scene"] = orbit_scene
        dr["orbit_world"] = orbit_world
        dr["dialog_data"] = data_in

        if not bool(getattr(self, "_dock_ring_preview_connected", False)):
            self.view.mouse_moved.connect(self._update_dock_ring_preview)
            self._dock_ring_preview_connected = True
        self.mode_lbl.setText(tr("placement.esc").format(text=tr("status.click_orbit")))
        self.statusBar().showMessage(tr("status.click_orbit"))

    def _update_dock_ring_preview(self, scene_pos: QPointF):
        """Bewegt den Vorschau-Punkt entlang des Orbit-Kreises."""
        dr = self._pending_dock_ring
        if not dr or dr.get("step") != 2:
            return
        cx = dr["planet_scene_x"]
        cy = dr["planet_scene_y"]
        orbit_r = dr["orbit_scene"]
        dx = scene_pos.x() - cx
        dy = scene_pos.y() - cy
        dist = math.sqrt(dx * dx + dy * dy)
        if dist < 1:
            return
        # Punkt auf den Kreis projizieren
        snap_x = cx + (dx / dist) * orbit_r
        snap_y = cy + (dy / dist) * orbit_r
        dot_r = 3
        self._dock_ring_preview_dot.setRect(
            snap_x - dot_r, snap_y - dot_r, dot_r * 2, dot_r * 2
        )

    def _on_dock_ring_orbit_click(self, pos: QPointF):
        """Schritt 2: Klick auf der Karte → Ring platzieren + ggf. Base erstellen."""
        dr = self._pending_dock_ring
        if not dr or dr.get("step") != 2:
            return
        cx = dr["planet_scene_x"]
        cy = dr["planet_scene_y"]
        orbit_r = dr["orbit_scene"]
        orbit_world = dr["orbit_world"]
        px, py, pz = dr["planet_world"]
        data_in = dr["dialog_data"]
        needs_base = dr.get("needs_base", False)
        game_path = dr["game_path"]
        sys_nick = dr["sys_nick"]
        base_nick = dr.get("base_nick", data_in.get("base_nickname", ""))
        planet_item = dr["planet_item"]
        planet_nick = dr["planet_nick"]

        # Winkel berechnen (Szenen-Koordinaten → Spielkoordinaten)
        dx = pos.x() - cx
        dy = pos.y() - cy
        angle = math.atan2(dy, dx)  # Szene: X=rechts, Y=unten

        # Ring-Position in Spielkoordinaten (X/Z-Ebene)
        rx = px + orbit_world * math.cos(angle)
        rz = pz + orbit_world * math.sin(angle)
        pos_str = f"{rx:.2f}, {py:.2f}, {rz:.2f}"

        # Ring-Rotation: Öffnung muss vom Planeten weg zeigen.
        angle_deg = math.degrees(angle)
        y_rot = 90.0 - angle_deg
        # Auf [-180, 180] normalisieren
        y_rot = (y_rot + 180) % 360 - 180
        rotate = f"0, {y_rot:.2f}, 0"

        nickname = data_in.get("nickname", "Dock_Ring")

        patch_result: list[str] = []

        # ── Base erstellen (falls Planet noch keine hat) ──────────────
        if needs_base:
            rooms = data_in.get("rooms", [])
            start_room = data_in.get("start_room", "Deck")
            template_base = data_in.get("template_base", "")

            sys_dir = Path(self._filepath).parent
            bases_dir = sys_dir / "BASES"
            rooms_dir = bases_dir / "ROOMS"
            bases_dir.mkdir(parents=True, exist_ok=True)
            rooms_dir.mkdir(parents=True, exist_ok=True)

            # 1) Room-INI-Dateien erstellen
            template_rooms: dict[str, str] = {}
            if template_base:
                template_rooms = self._load_template_rooms(game_path, template_base)

            for room_name in rooms:
                room_lower = room_name.lower()
                room_file = rooms_dir / f"{base_nick}_{room_lower}.ini"
                if room_file.exists():
                    patch_result.append(tr("result.room_exists").format(file=room_file.name))
                    continue
                if room_lower in template_rooms:
                    content = self._adapt_template_room(
                        template_rooms[room_lower], base_nick, rooms
                    )
                else:
                    content = self._generate_room_ini(room_name, rooms, start_room)
                content = MainWindow._normalize_room_navigation(
                    content, room_name, rooms, start_room
                )
                write_room_ini(room_file, content)
                patch_result.append(tr("result.room_created").format(file=room_file.name))

            # 2) Base-INI erstellen
            base_ini_path = bases_dir / f"{base_nick}.ini"
            price_var = data_in.get("price_variance", 0.15)
            write_base_ini(
                base_ini_path,
                base_nick=base_nick,
                system_nick=sys_nick,
                start_room=start_room,
                price_variance=float(price_var),
                rooms=rooms,
            )
            patch_result.append(tr("result.base_ini_created").format(file=base_ini_path.name))

            # 3) [Base] in universe.ini anhängen
            uni_ini = self._find_universe_ini_write(game_path)
            if uni_ini:
                strid_name = data_in.get("strid_name", 0)
                rel_base = f"Universe\\Systems\\{sys_nick}\\Bases\\{base_nick}.ini"
                base_entries: list[tuple[str, str]] = [
                    ("nickname", base_nick),
                    ("system", sys_nick),
                    ("strid_name", str(strid_name)),
                    ("file", rel_base),
                ]
                append_ini_section_block(uni_ini, "Base", base_entries)
                self._uni_sections.append(("Base", base_entries))
                patch_result.append(tr("result.base_registered").format(nickname=base_nick))
            else:
                patch_result.append(tr("result.uni_not_found"))

            # 3b) Minimalen MBase-Eintrag in mbases.ini sicherstellen
            try:
                ring_fac = self._normalize_reputation_value(data_in.get("faction", "")) or "li_n_grp"
                mbase_added, _ = self._ensure_mbase_entry_for_base(
                    game_path=game_path,
                    base_nick=base_nick,
                    local_faction=ring_fac,
                    diff=1,
                )
                if mbase_added:
                    patch_result.append(f"mbases.ini: created MBase for {base_nick}")
            except Exception as exc:
                patch_result.append(f"mbases.ini: could not create MBase ({exc})")

            # 4) 'base = ...' zum Planeten-Objekt hinzufügen
            elist = list(planet_item.data.get("_entries", []))
            elist.append(("base", base_nick))
            planet_item.data["_entries"] = elist
            planet_item.data["base"] = base_nick

            pnick_l = planet_nick.lower()
            for i, (sec_name, sec_entries) in enumerate(self._sections):
                if sec_name.lower() != "object":
                    continue
                for k, v in sec_entries:
                    if k.lower() == "nickname" and v.strip().lower() == pnick_l:
                        sec_entries.append(("base", base_nick))
                        break

        # ── Docking-Ring-Objekt erstellen ─────────────────────────────
        entries: list[tuple[str, str]] = [
            ("nickname", nickname),
            ("ids_name", data_in.get("ids_name", "0")),
            ("ids_info", data_in.get("ids_info", "0")),
            ("pos", pos_str),
            ("rotate", rotate),
            ("Archetype", data_in.get("archetype", "dock_ring")),
            ("dock_with", base_nick),
            ("loadout", data_in.get("loadout", "docking_ring")),
            ("behavior", "NOTHING"),
        ]
        voice = data_in.get("voice", "").strip()
        if voice:
            entries.append(("voice", voice))
        costume = data_in.get("costume", "").strip()
        if costume:
            entries.append(("space_costume", costume))
        pilot = data_in.get("pilot", "").strip()
        if pilot:
            entries.append(("pilot", pilot))
        entries.append(("difficulty_level", str(data_in.get("difficulty", 1))))
        faction = self._faction_from_ui(data_in.get("faction", "").strip())
        if faction:
            entries.append(("reputation", faction))

        self._remove_dock_ring_orbit()
        self._add_object_from_entries(entries, "Object")
        patch_result.append(tr("result.dock_ring_created").format(nickname=nickname))

        self._set_dirty(True)
        self._write_to_file(reload=False)

        self._pending_dock_ring = None
        self._set_placement_mode(False)

        msg = tr("msg.dock_ring_created") + ": "
        msg += tr("status.dock_ring_created_detail").format(
            nickname=nickname, planet=planet_nick, base=base_nick
        )
        msg += ":\n\n" + "\n".join(patch_result)
        QMessageBox.information(self, tr("msg.dock_ring_created"), msg)
        self.statusBar().showMessage(
            tr("status.dock_ring_created_detail").format(
                nickname=nickname, planet=planet_nick, base=base_nick
            )
        )

    def _remove_dock_ring_orbit(self):
        """Entfernt Orbit-Kreis und Vorschau-Punkt."""
        scene = getattr(getattr(self, "view", None), "_scene", None)
        if hasattr(self, "_dock_ring_orbit_circle") and self._dock_ring_orbit_circle:
            try:
                if scene is not None:
                    scene.removeItem(self._dock_ring_orbit_circle)
            except RuntimeError:
                pass
            self._dock_ring_orbit_circle = None
        if hasattr(self, "_dock_ring_preview_dot") and self._dock_ring_preview_dot:
            try:
                if scene is not None:
                    scene.removeItem(self._dock_ring_preview_dot)
            except RuntimeError:
                pass
            self._dock_ring_preview_dot = None
        if bool(getattr(self, "_dock_ring_preview_connected", False)):
            self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_dock_ring_preview)
            self._dock_ring_preview_connected = False

    def _on_zone_click(self, pos: QPointF):
        """Zwei-Klick-Modus für Asteroid/Nebel-Zone: Klick 1 = Position,
        Maus bewegen = Größe, Klick 2 = Bestätigen."""
        pz = self._pending_zone
        if not pz:
            return
        step = pz.get("step", 1)
        if step == 1:
            # Erster Klick: Position merken, Rubber-Band starten
            pz["center"] = pos
            pz["step"] = 2
            pen = QPen(self._scene_role_color("zone", 200), 2, Qt.DashLine)
            brush = QBrush(self._scene_role_color("zone_fill", 30))
            shape = pz.get("shape", "SPHERE").upper()
            corner_mode = shape in ("BOX", "CYLINDER")
            if corner_mode:
                pz["corner_start"] = QPointF(pos.x(), pos.y())
                self._zone_rubber_ellipse = QGraphicsRectItem(pos.x(), pos.y(), 0, 0)
                self._zone_rubber_ellipse.setPen(pen)
                self._zone_rubber_ellipse.setBrush(brush)
                self.view._scene.addItem(self._zone_rubber_ellipse)
            else:
                self._zone_rubber_ellipse = self.view._scene.addEllipse(
                    pos.x(), pos.y(), 0, 0, pen, brush
                )
            self._zone_rubber_ellipse.setZValue(9999)
            self._zone_rubber_origin = pos
            self.view.mouse_moved.connect(self._update_zone_rubber_ellipse)
            self.statusBar().showMessage(tr("status.zone_size"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.zone_size")))
        elif step == 2:
            # Zweiter Klick: Größe berechnen und Zone erstellen
            shape = pz.get("shape", "SPHERE").upper()
            corner_mode = shape in ("BOX", "CYLINDER")
            if corner_mode:
                c0 = pz.get("corner_start", pz.get("center", pos))
                x0, y0 = float(c0.x()), float(c0.y())
                x1, y1 = float(pos.x()), float(pos.y())
                size_x = max(abs(x1 - x0) / self._scale, 1.0)
                size_z = max(abs(y1 - y0) / self._scale, 1.0)
                create_pos = QPointF((x0 + x1) * 0.5, (y0 + y1) * 0.5)
            else:
                center = pz["center"]
                dx = abs(pos.x() - center.x())
                dy = abs(pos.y() - center.y())
                size_x = max(dx / self._scale, 500)
                size_z = max(dy / self._scale, 500)
                create_pos = center
            self._remove_zone_rubber_ellipse()
            self._create_zone_at_pos(create_pos, size_x, size_z)
            self._set_placement_mode(False)

    def _create_zone_at_pos(self, pos: QPointF, size_x: float = 1000, size_z: float = 1000):
        if not self._pending_zone:
            return
        pz = self._pending_zone
        zone_type = pz["type"]
        ref_file = pz["ref_file"]
        zone_name = pz["name"]
        game_path = pz["game_path"]

        if zone_type == "Asteroid Field":
            src_dir_name = "solar\\asteroids"
            section_name = "Asteroids"
            solar_subdir = "asteroids"
            solar_subdir_fs = "ASTEROIDS"
            src_dir_name_fs = "solar\\ASTEROIDS"
        else:
            src_dir_name = "solar\\nebula"
            section_name = "Nebula"
            solar_subdir = "nebula"
            solar_subdir_fs = "NEBULA"
            src_dir_name_fs = "solar\\NEBULA"

        src_file = self._resolve_game_path_case_insensitive(
            game_path,
            f"DATA/SOLAR/{solar_subdir}/{ref_file}",
        )
        if not src_file or not src_file.exists():
            QMessageBox.warning(self, tr("msg.error"), tr("msg.ref_file_not_found").format(file=ref_file))
            return

        sys_name = Path(self._filepath).stem.upper()
        art_name = self._zone_art_from_input(zone_name, "asteroid" if zone_type == "Asteroid Field" else "nebula")
        zone_nick = self._suggest_zone_name(art_name, [z.nickname for z in self._zones])
        zparts = zone_nick.split("_")
        num_suffix = zparts[-1] if zparts and zparts[-1].isdigit() else "001"
        new_zone_file = f"{sys_name}_{art_name}_{num_suffix}.ini"
        new_zone_path = self._target_game_path_for_rel(
            game_path, f"DATA/SOLAR/{solar_subdir_fs}/{new_zone_file}"
        )
        if new_zone_path is None:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.dir_not_found"))
            return

        try:
            content = self._read_text_best_effort(src_file)
            lines = content.split("\n")
            new_lines = []
            skip_section = False
            for line in lines:
                l_lower = line.strip().lower()
                if l_lower == "[exclusion zones]":
                    skip_section = True
                elif l_lower.startswith("[") and skip_section:
                    skip_section = False
                if not skip_section:
                    new_lines.append(line)
            new_lines.append(f"\n; Copied by FL Atlas from file: {src_dir_name_fs}\\{ref_file}")
            new_zone_path.parent.mkdir(parents=True, exist_ok=True)
            new_zone_path.write_text("\n".join(new_lines), encoding="utf-8")
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.copy_error"), str(ex))
            return

        size_y = min(size_x, size_z)
        size_str = f"{size_x:.0f}, {size_y:.0f}, {size_z:.0f}"

        zone_entries = [
            ("nickname", zone_nick),
            ("ids_name", "0"),
            ("pos", f"{pos.x() / self._scale:.2f}, 0, {pos.y() / self._scale:.2f}"),
            ("rotate", "0,0,0"),
            ("shape", "ELLIPSOID"),
            ("size", size_str),
            ("property_flags", "0"),
            ("ids_info", "66146"),
            ("visit", "0"),
            ("damage", str(int(pz.get("damage", 0)))),
        ]
        ids_name_text = str(pz.get("ids_name_text", "") or "").strip()
        if ids_name_text:
            try:
                new_ids_name = self._ensure_ids_name_in_user_dll("0", ids_name_text)
                zone_entries = self._entry_set(zone_entries, "ids_name", new_ids_name)
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
        zone_data = {"_entries": zone_entries}
        for k, v in zone_entries:
            zone_data[k.lower()] = v
        zone = ZoneItem(zone_data, self._scale)
        zone.set_label_visibility(self._viewer_text_visible)
        self.view._scene.addItem(zone)
        self._zones.append(zone)

        self._sections.append(("Zone", list(zone_entries)))
        rel_path = f"{src_dir_name_fs}\\{new_zone_file}"
        entry = (section_name, [("file", rel_path), ("zone", zone_nick)])
        insert_idx = None
        for i, (sec_name, _) in enumerate(self._sections):
            if sec_name.lower() == "music":
                insert_idx = i + 1
                break
        if insert_idx is not None:
            self._sections.insert(insert_idx, entry)
        else:
            self._sections.append(entry)
        self._push_undo_action(
            {
                "type": "create_zone",
                "label": f"Zone erstellt: {zone_nick}",
                "filepath": self._filepath or "",
                "nickname": zone_nick,
                "linked_section": section_name,
                "linked_file_abs": str(new_zone_path),
            }
        )
        self._append_change_log(f"Zone erstellt: {zone_nick}")
        self._set_dirty(True)
        # Persist immediately so follow-up actions (e.g. exclusion linking) see latest zone state.
        self._write_to_file(reload=False)
        self._pending_zone = None
        status_msg = tr("status.zone_created_detail").format(
            nickname=zone_name,
            size=f"{size_x:.0f} × {size_y:.0f} × {size_z:.0f}"
        )
        QTimer.singleShot(
            0,
            lambda z=zone, msg=status_msg: self._finalize_created_zone_ui(z, msg),
        )

    # ------------------------------------------------------------------
    #  Jump-Verbindung
    # ------------------------------------------------------------------
    def _start_zone_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"), tr("msg.no_game_path_config"))
            return

        # Some installs contain both uppercase/lowercase folder variants
        # (e.g. NEBULA + nebula). Merge both to avoid missing templates.
        asteroids = sorted(
            set(self._zone_reference_files(game_path, "asteroids")) | set(self._zone_reference_files(game_path, "ASTEROIDS")),
            key=str.lower,
        )
        nebulas = sorted(
            set(self._zone_reference_files(game_path, "nebula")) | set(self._zone_reference_files(game_path, "NEBULA")),
            key=str.lower,
        )
        if not asteroids and not nebulas:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.solar_dir_not_found").format(path=game_path))
            return

        dlg = ZoneCreationDialog(self, asteroids, nebulas)
        existing_zone_nicks = [z.nickname for z in self._zones]
        last_auto_name = [""]

        def _auto_zone_name(typ: str) -> str:
            kind = "asteroid" if str(typ).strip().lower() == "asteroid field" else "nebula"
            return self._suggest_zone_name(kind, existing_zone_nicks)

        first_auto = _auto_zone_name(dlg.type_cb.currentText())
        dlg.name_edit.setText(first_auto)
        last_auto_name[0] = first_auto

        def _update_auto_name(typ: str):
            cur = dlg.name_edit.text().strip()
            if not cur or cur == last_auto_name[0]:
                nxt = _auto_zone_name(typ)
                dlg.name_edit.setText(nxt)
                last_auto_name[0] = nxt

        dlg.type_cb.currentTextChanged.connect(_update_auto_name)
        if dlg.exec() != QDialog.Accepted:
            return
        zone_type = dlg.type_cb.currentText()
        ref_file = dlg.ref_cb.currentText()
        zone_name = dlg.name_edit.text().strip()
        ids_name_text = str(dlg.ids_name_edit.text() if hasattr(dlg, "ids_name_edit") else "").strip()
        if not zone_name or not ref_file:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.enter_name_ref"))
            return
        self._pending_zone = {
            "type": zone_type, "ref_file": ref_file,
            "name": zone_name, "game_path": game_path,
            "ids_name_text": ids_name_text,
            "damage": int(dlg.damage_spin.value()),
            "step": 1,
        }
        self._set_placement_mode(True, tr("placement.zone").format(name=zone_name))

    # ------------------------------------------------------------------
    #  Einfache Zone erstellen (Population-Zone)
    # ------------------------------------------------------------------
    def _start_simple_zone_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        dlg = SimpleZoneDialog(self)
        dlg.name_edit.setText(
            self._suggest_zone_name("zone", [z.nickname for z in self._zones])
        )
        if dlg.exec() != QDialog.Accepted:
            return
        zone_name = dlg.name_edit.text().strip()
        if not zone_name:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.enter_name"))
            return
        self._pending_simple_zone = {
            "mode": "simple",
            "name": zone_name,
            "comment": dlg.comment_edit.text().strip(),
            "shape": dlg.shape_cb.currentText(),
            "sort": dlg.sort_spin.value(),
            "damage": int(dlg.damage_spin.value()),
            "step": 1,
        }
        self._set_placement_mode(True, tr("placement.zone").format(name=zone_name))

    def _collect_all_encounter_names(self) -> list[str]:
        enc_params: list[str] = []
        for sec_name, entries in self._sections:
            if sec_name.lower() == "encounterparameters":
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip()
                        if nick and nick not in enc_params:
                            enc_params.append(nick)
        game_path = self._primary_game_path()
        all_encounters = list(enc_params)
        if game_path:
            enc_dir = self._resolve_data_subdir_case_insensitive(game_path, "MISSIONS/ENCOUNTERS")
            if enc_dir and enc_dir.is_dir():
                for f in sorted(enc_dir.iterdir()):
                    if f.suffix.lower() == ".ini":
                        nick = f.stem
                        if nick not in all_encounters:
                            all_encounters.append(nick)
        return all_encounters

    def _ensure_encounter_parameters(self, names: set[str]) -> None:
        need = {str(n).strip() for n in names if str(n).strip()}
        if not need:
            return
        existing = set()
        for sec_name, entries in self._sections:
            if sec_name.lower() != "encounterparameters":
                continue
            for k, v in entries:
                if k.lower() == "nickname":
                    existing.add(v.strip().lower())
        missing = sorted([n for n in need if n.lower() not in existing], key=str.lower)
        if not missing:
            return
        insert_pos = 1
        for i, (sn, _) in enumerate(self._sections):
            if sn.lower() == "systeminfo":
                insert_pos = i + 1
                break
        for enc_nick in missing:
            self._sections.insert(
                insert_pos,
                (
                    "EncounterParameters",
                    [
                        ("nickname", enc_nick),
                        ("filename", f"missions\\encounters\\{enc_nick}.ini"),
                    ],
                ),
            )
            insert_pos += 1

    def _start_patrol_zone_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        factions = list(self._cached_faction_labels) if self._cached_faction_labels else list(self._cached_factions)
        encounters = self._collect_all_encounter_names()
        dlg = PatrolZoneDialog(self, encounters=encounters, factions=factions)
        dlg.name_edit.setText(
            self._suggest_zone_name("path", [z.nickname for z in self._zones])
        )
        if dlg.exec() != QDialog.Accepted:
            return
        payload = dlg.payload()
        zone_name = payload.get("name", "").strip()
        encounter = payload.get("encounter", "").strip()
        faction = self._faction_from_ui(payload.get("faction", "").strip())
        if not zone_name or not encounter or not faction:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.enter_name"))
            return
        self._pending_simple_zone = {
            "mode": "patrol",
            "name": zone_name,
            "comment": payload.get("comment", "").strip(),
            "usage": payload.get("usage", "patrol").strip().lower() or "patrol",
            "shape": "CYLINDER",
            "sort": int(payload.get("sort", 76)),
            "damage": int(payload.get("damage", 0)),
            "toughness": int(payload.get("toughness", 19)),
            "density": int(payload.get("density", 10)),
            "repop_time": int(payload.get("repop_time", 90)),
            "max_battle_size": int(payload.get("max_battle_size", 10)),
            "pop_type": payload.get("pop_type", "attack_patrol").strip() or "attack_patrol",
            "relief_time": int(payload.get("relief_time", 30)),
            "path_label": payload.get("path_label", "patrol").strip() or "patrol",
            "path_index": int(payload.get("path_index", 1)),
            "encounter": encounter,
            "faction": faction,
            "encounter_pairs": list(payload.get("encounter_pairs", [])),
            "mission_eligible": bool(payload.get("mission_eligible", True)),
            "radius": int(payload.get("radius", 750)),
            "step": 1,
        }
        self._set_placement_mode(True, tr("placement.zone").format(name=zone_name))

    def _on_simple_zone_click(self, pos: QPointF):
        """Zwei-Klick-Modus für einfache Zone: Klick 1 = Position,
        Maus bewegen = Größe, Klick 2 = Bestätigen."""
        pz = self._pending_simple_zone
        if not pz:
            return
        step = pz.get("step", 1)
        shape = pz.get("shape", "SPHERE").upper()
        oriented_mode = shape in ("BOX", "CYLINDER")
        if oriented_mode:
            if step == 1:
                pz["axis_start"] = QPointF(pos.x(), pos.y())
                pz["step"] = 2
                pen = QPen(self._scene_role_color("simple_zone", 220), 2, Qt.DashLine)
                self._zone_axis_line = self.view._scene.addLine(pos.x(), pos.y(), pos.x(), pos.y(), pen)
                self._zone_axis_line.setZValue(9999)
                self.view.mouse_moved.connect(self._update_zone_axis_line)
                self.statusBar().showMessage(tr("status.zone_size"))
                self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.zone_size")))
                return
            if step == 2:
                a = pz.get("axis_start", pos)
                pz["axis_end"] = QPointF(pos.x(), pos.y())
                pz["step"] = 3
                if self._zone_axis_line:
                    self.view._scene.removeItem(self._zone_axis_line)
                    self._zone_axis_line = None
                self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_zone_axis_line)
                pen = QPen(self._scene_role_color("simple_zone", 220), 2, Qt.DashLine)
                brush = QBrush(self._scene_role_color("simple_zone_fill", 30))
                self._zone_width_poly = QGraphicsPolygonItem(self._oriented_rect_polygon(a, pos, 1.0))
                self._zone_width_poly.setPen(pen)
                self._zone_width_poly.setBrush(brush)
                self._zone_width_poly.setZValue(9999)
                self.view._scene.addItem(self._zone_width_poly)
                self.view.mouse_moved.connect(self._update_zone_width_poly)
                self.statusBar().showMessage(tr("status.zone_size"))
                self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.zone_size")))
                return
            if step == 3:
                a = pz.get("axis_start")
                b = pz.get("axis_end")
                if not isinstance(a, QPointF) or not isinstance(b, QPointF):
                    self._remove_zone_rubber_ellipse()
                    self._pending_simple_zone = None
                    self._set_placement_mode(False)
                    return
                half_w = max(1.0, self._point_line_distance(pos, a, b))
                center = QPointF((a.x() + b.x()) * 0.5, (a.y() + b.y()) * 0.5)
                self._remove_zone_rubber_ellipse()
                self._create_simple_zone(
                    center,
                    1.0,
                    1.0,
                    end_pos=b,
                    axis_start=a,
                    axis_end=b,
                    half_width_scene=half_w,
                )
                self._set_placement_mode(False)
                return

        if step == 1:
            pz["center"] = pos
            pz["step"] = 2
            pen = QPen(self._scene_role_color("simple_zone", 200), 2, Qt.DashLine)
            brush = QBrush(self._scene_role_color("simple_zone_fill", 30))
            corner_mode = shape in ("BOX", "CYLINDER")
            if corner_mode:
                pz["corner_start"] = QPointF(pos.x(), pos.y())
                self._zone_rubber_ellipse = QGraphicsRectItem(pos.x(), pos.y(), 0, 0)
                self._zone_rubber_ellipse.setPen(pen)
                self._zone_rubber_ellipse.setBrush(brush)
                self.view._scene.addItem(self._zone_rubber_ellipse)
            else:
                self._zone_rubber_ellipse = self.view._scene.addEllipse(
                    pos.x(), pos.y(), 0, 0, pen, brush
                )
            self._zone_rubber_ellipse.setZValue(9999)
            self._zone_rubber_origin = pos
            self.view.mouse_moved.connect(self._update_zone_rubber_ellipse)
            self.statusBar().showMessage(tr("status.zone_size"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.zone_size")))
        elif step == 2:
            corner_mode = shape in ("BOX", "CYLINDER")
            if corner_mode:
                c0 = pz.get("corner_start", pz.get("center", pos))
                x0, y0 = float(c0.x()), float(c0.y())
                x1, y1 = float(pos.x()), float(pos.y())
                size_x = max(abs(x1 - x0) / self._scale, 1.0)
                size_z = max(abs(y1 - y0) / self._scale, 1.0)
                create_pos = QPointF((x0 + x1) * 0.5, (y0 + y1) * 0.5)
            else:
                center = pz["center"]
                dx = abs(pos.x() - center.x())
                dy = abs(pos.y() - center.y())
                size_x = max(dx / self._scale, 500)
                size_z = max(dy / self._scale, 500)
                create_pos = center
            self._remove_zone_rubber_ellipse()
            self._create_simple_zone(create_pos, size_x, size_z, end_pos=pos)
            self._set_placement_mode(False)

    def _create_simple_zone(
        self,
        pos: QPointF,
        size_x: float,
        size_z: float,
        end_pos: QPointF | None = None,
        axis_start: QPointF | None = None,
        axis_end: QPointF | None = None,
        half_width_scene: float | None = None,
    ):
        pz = self._pending_simple_zone
        if not pz:
            return
        zone_name = pz["name"]
        comment = pz["comment"]
        mode = str(pz.get("mode", "simple")).lower()
        shape = "CYLINDER" if mode == "patrol" else pz["shape"]
        sort_val = pz["sort"]
        damage_val = int(pz.get("damage", 0))

        def _yaw_from_axis_for_cylinder(dxs: float, dys: float) -> float:
            # Match ZoneItem 2D display behavior for CYLINDER:
            # local +Y axis should follow the drawn axis direction.
            axis_angle = math.degrees(math.atan2(dys, dxs))
            yaw_val = 90.0 - axis_angle
            return (yaw_val + 180.0) % 360.0 - 180.0

        if mode == "patrol":
            path_name = str(pz.get("path_label", "patrol")).strip() or "patrol"
            zone_nick = self._suggest_patrol_zone_name(path_name, [z.nickname for z in self._zones])
        else:
            art_name = self._zone_art_from_input(zone_name, "zone")
            zone_nick = self._suggest_zone_name(art_name, [z.nickname for z in self._zones])

        size_y = min(size_x, size_z)
        if mode == "patrol":
            radius = float(max(100, int(pz.get("radius", 750))))
            if axis_start is not None and axis_end is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                yaw_deg = _yaw_from_axis_for_cylinder(dxs, dys)
                length = max(axis_len_scene / self._scale, 1.0)
            else:
                length = max(size_z, 1.0)
                yaw_deg = 0.0
            if half_width_scene is not None:
                radius = max(half_width_scene / self._scale, 1.0)
            size_str = f"{radius:.0f}, {length:.0f}"
            rotate_str = f"90, {yaw_deg:.6f}, 0"
        elif shape == "CYLINDER":
            if axis_start is not None and axis_end is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                yaw_deg = _yaw_from_axis_for_cylinder(dxs, dys)
                length = max(axis_len_scene / self._scale, 1.0)
            else:
                length = max(size_z, 1.0)
                yaw_deg = 0.0
            # CYLINDER size schema: radius, length
            if half_width_scene is not None:
                radius = max(half_width_scene / self._scale, 1.0)
            else:
                radius = max(size_x * 0.5, 1.0)
            size_str = f"{radius:.0f}, {length:.0f}"
            rotate_str = f"90, {yaw_deg:.6f}, 0"
        elif shape == "SPHERE":
            r = max(size_x, size_z)
            size_str = f"{r:.0f}"
            rotate_str = "0,0,0"
        elif shape == "BOX":
            if axis_start is not None and axis_end is not None and half_width_scene is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                yaw_deg = math.degrees(math.atan2(dys, dxs))
                yaw_deg = (yaw_deg + 180.0) % 360.0 - 180.0
                len_world = max(axis_len_scene / self._scale, 1.0)
                thick_world = max((half_width_scene * 2.0) / self._scale, 1.0)
                size_mid = min(len_world, thick_world)
                size_str = f"{len_world:.0f}, {size_mid:.0f}, {thick_world:.0f}"
                rotate_str = f"0, {yaw_deg:.6f}, 0"
            else:
                # Keep BOX exactly as drawn by the rectangular preview.
                rotate_str = "0,0,0"
                size_str = f"{size_x:.0f}, {size_y:.0f}, {size_z:.0f}"
        else:
            size_str = f"{size_x:.0f}, {size_y:.0f}, {size_z:.0f}"
            rotate_str = "0,0,0"

        zone_entries: list[tuple[str, str]] = [
            ("nickname", zone_nick),
        ]
        if comment:
            zone_entries.append(("comment", comment))
        zone_entries.extend([
            ("pos", f"{pos.x() / self._scale:.0f}, 0, {pos.y() / self._scale:.0f}"),
            ("rotate", rotate_str),
            ("shape", shape),
            ("size", size_str),
            ("sort", str(sort_val)),
            ("damage", str(max(0, damage_val))),
        ])
        if mode == "patrol":
            zone_entries.extend([
                ("toughness", str(int(pz.get("toughness", 19)))),
                ("density", str(int(pz.get("density", 10)))),
                ("repop_time", str(int(pz.get("repop_time", 90)))),
                ("max_battle_size", str(int(pz.get("max_battle_size", 10)))),
                ("pop_type", str(pz.get("pop_type", "attack_patrol"))),
                ("relief_time", str(int(pz.get("relief_time", 30)))),
                ("path_label", f"{str(pz.get('path_label', 'patrol')).strip()}, {int(pz.get('path_index', 1))}"),
                ("usage", str(pz.get("usage", "patrol")).strip().lower() or "patrol"),
            ])
            enc_name = str(pz.get("encounter", "")).strip()
            fac_name = str(pz.get("faction", "")).strip()
            for lvl, chance in list(pz.get("encounter_pairs", [])):
                zone_entries.append(("encounter", f"{enc_name}, {int(lvl)}, {int(chance)}"))
                zone_entries.append(("faction", f"{fac_name}, 1"))
            if bool(pz.get("mission_eligible", True)):
                zone_entries.append(("mission_eligible", "True"))
            self._ensure_encounter_parameters({enc_name})

        zone_data: dict = {"_entries": list(zone_entries)}
        for k, v in zone_entries:
            zone_data[k.lower()] = v
        zone = ZoneItem(zone_data, self._scale)
        zone.set_label_visibility(self._viewer_text_visible)
        self.view._scene.addItem(zone)
        self._zones.append(zone)

        self._sections.append(("Zone", list(zone_entries)))
        self._push_undo_action(
            {
                "type": "create_zone",
                "label": f"Zone erstellt: {zone_nick}",
                "filepath": self._filepath or "",
                "nickname": zone_nick,
            }
        )
        self._append_change_log(f"Zone erstellt: {zone_nick}")
        self._set_dirty(True)
        self._pending_simple_zone = None
        self._write_to_file(reload=False)
        status_msg = tr("status.zone_created_detail").format(
            nickname=zone_nick, size=size_str
        )
        QTimer.singleShot(
            0,
            lambda z=zone, msg=status_msg: self._finalize_created_zone_ui(z, msg),
        )

    def _finalize_created_zone_ui(self, zone: ZoneItem, status_msg: str):
        """Wendet Folge-UI erst nach Abschluss des Platzierungs-Mausevents an."""
        if zone not in self._zones:
            return
        self._rebuild_object_combo()
        self._select_zone(zone)
        self.statusBar().showMessage(status_msg)
        self._apply_group_visibility()
        self._refresh_3d_scene(preserve_camera=True)

    def _is_field_zone(self, zone_nickname: str) -> bool:
        return is_field_zone_nickname(self._sections, zone_nickname)

    @staticmethod
    def _find_nickname_in_entries(entries: list[tuple[str, str]]) -> str:
        for k, v in entries:
            if k.lower() == "nickname":
                return v.strip()
        return ""

    def _find_zone_entries_index(self, zone_nickname: str) -> int | None:
        target = zone_nickname.strip().lower()
        for idx, (sec_name, entries) in enumerate(self._sections):
            if sec_name.lower() != "zone":
                continue
            nick = self._find_nickname_in_entries(entries)
            if nick.lower() == target:
                return idx
        return None

    @staticmethod
    def _zone_default_pos_size(zone: ZoneItem) -> tuple[tuple[float, float, float], tuple[float, float, float]]:
        pos = zone.data.get("pos", "0, 0, 0")
        pparts = [p.strip() for p in pos.split(",")]
        px = float(pparts[0]) if len(pparts) > 0 and pparts[0] else 0.0
        py = float(pparts[1]) if len(pparts) > 1 and pparts[1] else 0.0
        pz = float(pparts[2]) if len(pparts) > 2 and pparts[2] else 0.0

        size = zone.data.get("size", "1000")
        sparts = [s.strip() for s in size.split(",")]
        sx = float(sparts[0]) if len(sparts) > 0 and sparts[0] else 1000.0
        sy = float(sparts[1]) if len(sparts) > 1 and sparts[1] else sx
        sz = float(sparts[2]) if len(sparts) > 2 and sparts[2] else sx
        return (px, py, pz), (max(1.0, sx), max(1.0, sy), max(1.0, sz))

    def _start_exclusion_zone_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        if not isinstance(self._selected, ZoneItem):
            QMessageBox.warning(self, tr("msg.error"), tr("msg.exclusion_select_field_zone"))
            return
        field_zone = self._selected
        if not self._is_field_zone(field_zone.nickname):
            QMessageBox.warning(self, tr("msg.error"), tr("msg.exclusion_not_field_zone"))
            return

        system_nick = Path(self._filepath).stem
        existing = [z.nickname for z in self._zones]
        suggested = generate_exclusion_nickname(system_nick, field_zone.nickname, existing)
        default_pos, default_size = self._zone_default_pos_size(field_zone)

        dlg = ExclusionZoneDialog(self, suggested, default_pos, default_size)
        if dlg.exec() != QDialog.Accepted:
            return
        data = dlg.get_data()
        nickname = data.get("nickname", "").strip()
        if not nickname:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.exclusion_nickname_empty"))
            return

        params = {
            "shape": data.get("shape", "SPHERE"),
            "comment": data.get("comment", ""),
            "sort": data.get("sort", 99),
            "nickname": nickname,
            "link_to_field_zone": data.get("link_to_field_zone", True),
        }
        self._pending_exclusion_zone = {
            "system": system_nick,
            "field_zone_nickname": field_zone.nickname,
            "params": params,
            "step": 1,
        }
        self._set_placement_mode(True, tr("placement.exclusion_pos").format(name=nickname))

    def _on_exclusion_zone_click(self, pos: QPointF):
        """Zwei-Klick-Modus für Exclusion-Zone: Klick 1 = Position,
        Maus bewegen = Größe, Klick 2 = Erstellen."""
        pe = self._pending_exclusion_zone
        if not pe:
            return
        step = pe.get("step", 1)
        shape = str(pe.get("params", {}).get("shape", "SPHERE")).upper()
        oriented_mode = shape in ("BOX", "CYLINDER")
        if oriented_mode:
            if step == 1:
                pe["axis_start"] = QPointF(pos.x(), pos.y())
                pe["step"] = 2
                pen = QPen(self._scene_role_color("exclusion", 220), 2, Qt.DashLine)
                self._zone_axis_line = self.view._scene.addLine(pos.x(), pos.y(), pos.x(), pos.y(), pen)
                self._zone_axis_line.setZValue(9999)
                self.view.mouse_moved.connect(self._update_zone_axis_line)
                self.statusBar().showMessage(tr("status.exclusion_size"))
                self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.exclusion_size")))
                return
            if step == 2:
                a = pe.get("axis_start", pos)
                pe["axis_end"] = QPointF(pos.x(), pos.y())
                pe["step"] = 3
                if self._zone_axis_line:
                    self.view._scene.removeItem(self._zone_axis_line)
                    self._zone_axis_line = None
                self._disconnect_view_signal(getattr(self, "view", None), "mouse_moved", self._update_zone_axis_line)
                pen = QPen(self._scene_role_color("exclusion", 220), 2, Qt.DashLine)
                brush = QBrush(self._scene_role_color("exclusion_fill", 35))
                self._zone_width_poly = QGraphicsPolygonItem(self._oriented_rect_polygon(a, pos, 1.0))
                self._zone_width_poly.setPen(pen)
                self._zone_width_poly.setBrush(brush)
                self._zone_width_poly.setZValue(9999)
                self.view._scene.addItem(self._zone_width_poly)
                self.view.mouse_moved.connect(self._update_zone_width_poly)
                self.statusBar().showMessage(tr("status.exclusion_size"))
                self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.exclusion_size")))
                return
            if step == 3:
                a = pe.get("axis_start")
                b = pe.get("axis_end")
                if not isinstance(a, QPointF) or not isinstance(b, QPointF):
                    self._remove_zone_rubber_ellipse()
                    self._pending_exclusion_zone = None
                    self._set_placement_mode(False)
                    return
                half_w = max(1.0, self._point_line_distance(pos, a, b))
                center = QPointF((a.x() + b.x()) * 0.5, (a.y() + b.y()) * 0.5)
                self._remove_zone_rubber_ellipse()
                self._create_exclusion_zone_at_pos(
                    center,
                    1.0,
                    1.0,
                    axis_start=a,
                    axis_end=b,
                    half_width_scene=half_w,
                )
                self._set_placement_mode(False)
                return
        if step == 1:
            pe["center"] = pos
            pe["step"] = 2
            pen = QPen(self._scene_role_color("exclusion", 220), 2, Qt.DashLine)
            brush = QBrush(self._scene_role_color("exclusion_fill", 35))
            if shape in ("BOX", "ELLIPSOID"):
                pe["corner_start"] = QPointF(pos.x(), pos.y())
                self._zone_rubber_ellipse = QGraphicsRectItem(pos.x(), pos.y(), 0, 0)
                self._zone_rubber_ellipse.setPen(pen)
                self._zone_rubber_ellipse.setBrush(brush)
                self.view._scene.addItem(self._zone_rubber_ellipse)
            else:
                self._zone_rubber_ellipse = self.view._scene.addEllipse(
                    pos.x(), pos.y(), 0, 0, pen, brush
                )
            self._zone_rubber_ellipse.setZValue(9999)
            self._zone_rubber_origin = pos
            self.view.mouse_moved.connect(self._update_zone_rubber_ellipse)
            self.statusBar().showMessage(tr("status.exclusion_size"))
            self.mode_lbl.setText(tr("placement.esc").format(text=tr("placement.exclusion_size")))
        elif step == 2:
            corner_mode = shape in ("BOX", "ELLIPSOID")
            if corner_mode:
                # BOX/ELLIPSOID are previewed as a rectangle between both clicks.
                start0 = pe.get("corner_start", pe.get("center", pos))
                x0, y0 = float(start0.x()), float(start0.y())
                x1, y1 = float(pos.x()), float(pos.y())
                left = min(x0, x1)
                top = min(y0, y1)
                width = abs(x1 - x0)
                height = abs(y1 - y0)
                center = QPointF(left + width / 2, top + height / 2)
                width_world = width / self._scale
                height_world = height / self._scale
                if shape == "BOX":
                    size_x = max(width_world, 500)
                    size_z = max(height_world, 500)
                else:
                    # ELLIPSOID stores half-axes; rectangle width/height are full extents.
                    size_x = max(width_world * 0.5, 500)
                    size_z = max(height_world * 0.5, 500)
            else:
                # SPHERE/CYLINDER preview is centered on first click.
                center = pe.get("center", pos)
                dx = abs(pos.x() - center.x())
                dy = abs(pos.y() - center.y())
                size_x = max(dx / self._scale, 500)
                size_z = max(dy / self._scale, 500)
            self._remove_zone_rubber_ellipse()
            self._create_exclusion_zone_at_pos(center, size_x, size_z)
            self._set_placement_mode(False)

    def _create_exclusion_zone_at_pos(
        self,
        pos: QPointF,
        size_x: float,
        size_z: float,
        axis_start: QPointF | None = None,
        axis_end: QPointF | None = None,
        half_width_scene: float | None = None,
    ):
        pe = self._pending_exclusion_zone
        if not pe:
            return
        params = dict(pe.get("params", {}))
        old_pos = params.get("pos", (0.0, 0.0, 0.0))
        y_pos = float(old_pos[1]) if isinstance(old_pos, tuple) and len(old_pos) > 1 else 0.0
        params["pos"] = (pos.x() / self._scale, y_pos, pos.y() / self._scale)

        shape = str(params.get("shape", "SPHERE")).upper()
        old_size = params.get("size", (1000.0, 1000.0, 1000.0))
        size_y = 1000.0
        if isinstance(old_size, tuple) and len(old_size) > 1:
            size_y = max(1.0, float(old_size[1]))
        if shape == "SPHERE":
            params["size"] = max(size_x, size_z)
        elif shape == "BOX":
            if axis_start is not None and axis_end is not None and half_width_scene is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                yaw_deg = math.degrees(math.atan2(dys, dxs))
                yaw_deg = (yaw_deg + 180.0) % 360.0 - 180.0
                len_world = max(axis_len_scene / self._scale, 1.0)
                thick_world = max((half_width_scene * 2.0) / self._scale, 1.0)
                params["size"] = (len_world, size_y, thick_world)
                params["rotate"] = (0.0, yaw_deg, 0.0)
            else:
                params["size"] = (size_x, size_y, size_z)
        elif shape == "ELLIPSOID":
            if axis_start is not None and axis_end is not None and half_width_scene is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                yaw_deg = math.degrees(math.atan2(dys, dxs)) + 90.0
                yaw_deg = (yaw_deg + 180.0) % 360.0 - 180.0
                # ELLIPSOID uses radii in size tuple.
                len_radius = max((axis_len_scene * 0.5) / self._scale, 1.0)
                thick_radius = max(half_width_scene / self._scale, 1.0)
                params["size"] = (len_radius, size_y, thick_radius)
                params["rotate"] = (0.0, yaw_deg, 0.0)
            else:
                params["size"] = (size_x, size_y, size_z)
        elif shape == "CYLINDER":
            if axis_start is not None and axis_end is not None and half_width_scene is not None:
                dxs = float(axis_end.x() - axis_start.x())
                dys = float(axis_end.y() - axis_start.y())
                axis_len_scene = max(math.hypot(dxs, dys), 1.0)
                # Keep CYLINDER creation aligned with the Patrol-Zone fix:
                # local +Y axis follows drawn direction in 2D/3D consistently.
                axis_angle = math.degrees(math.atan2(dys, dxs))
                yaw_deg = 90.0 - axis_angle
                yaw_deg = (yaw_deg + 180.0) % 360.0 - 180.0
                length_world = max(axis_len_scene / self._scale, 1.0)
                radius_world = max(half_width_scene / self._scale, 1.0)
                params["size"] = (radius_world, length_world)
                params["rotate"] = (90.0, yaw_deg, 0.0)
            else:
                params["size"] = (max(size_x * 0.5, 1.0), max(size_z, 1.0))
                params["rotate"] = (90.0, 0.0, 0.0)
        else:
            params["size"] = (size_x, size_y, size_z)

        # Ensure pending in-memory edits are flushed before patching system INI directly.
        if self._dirty:
            self._write_to_file(reload=False)

        try:
            result = self.CreateExclusionZone(
                pe["system"],
                pe["field_zone_nickname"],
                params,
            )
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.error"), str(ex))
            self._pending_exclusion_zone = None
            return

        self._pending_exclusion_zone = None
        linked_files = result.get("linked_files", [])
        self._push_undo_action(
            {
                "type": "create_exclusion_zone",
                "label": f"Exclusion-Zone erstellt: {result['zone_nickname']}",
                "filepath": self._filepath or "",
                "nickname": result["zone_nickname"],
                "linked_files": [dict(x) for x in linked_files if isinstance(x, dict)],
            }
        )
        self._append_change_log(f"Exclusion-Zone erstellt: {result['zone_nickname']}")
        self.statusBar().showMessage(
            tr("status.exclusion_created").format(nickname=result["zone_nickname"])
        )

    def LinkExclusionToFieldZone(
        self,
        system: str,
        field_zone_nickname: str,
        exclusion_zone_nickname: str,
    ) -> dict:
        if not self._filepath:
            raise ValueError("No system loaded")
        if Path(self._filepath).stem.lower() != system.strip().lower():
            raise ValueError("System mismatch")

        field_zone = next(
            (z for z in self._zones if z.nickname.lower() == field_zone_nickname.strip().lower()),
            None,
        )
        if field_zone is None:
            raise ValueError(f"Field zone not found: {field_zone_nickname}")
        if not self._is_field_zone(field_zone.nickname):
            raise ValueError("Selected field zone is not nebula/asteroid linked")

        exclusion_nick = exclusion_zone_nickname.strip()
        if not exclusion_nick:
            raise ValueError("Exclusion zone nickname is empty")

        game_path = self._primary_game_path()
        if not game_path:
            raise ValueError("No game path configured")

        file_rel = ""
        for sec_name, entries in self._sections:
            if sec_name.lower() not in ("nebula", "asteroids"):
                continue
            zone_val = ""
            for k, v in entries:
                if k.lower() == "zone":
                    zone_val = v.strip().lower()
                elif k.lower() == "file":
                    file_rel = v.strip()
            if zone_val == field_zone.nickname.strip().lower():
                break
            file_rel = ""

        if not file_rel:
            raise ValueError(f"Linked field ini file not found for zone: {field_zone.nickname}")

        linked_file = self._resolve_game_path_case_insensitive(game_path, file_rel)
        if not linked_file or not linked_file.is_file():
            rel_norm = str(file_rel or "").replace("\\", "/").strip().lstrip("/")
            candidates = [rel_norm]
            if rel_norm and not rel_norm.lower().startswith("data/"):
                candidates.append(f"DATA/{rel_norm}")
            for rel_try in candidates:
                tgt = self._target_game_path_for_rel(game_path, rel_try)
                if tgt and tgt.is_file():
                    linked_file = tgt
                    break
        if (not linked_file or not linked_file.is_file()) and self._filepath:
            rel_norm = str(file_rel or "").replace("\\", "/").strip().lstrip("/")
            candidates = [rel_norm]
            if rel_norm and not rel_norm.lower().startswith("data/"):
                candidates.append(f"DATA/{rel_norm}")
            sys_path = Path(self._filepath)
            data_dir = None
            for parent in [sys_path.parent, *sys_path.parents]:
                if parent.name.lower() == "data":
                    data_dir = parent
                    break
            extra_roots: list[Path] = []
            if data_dir and data_dir.parent.is_dir():
                extra_roots.append(data_dir.parent)
            if sys_path.parent.is_dir():
                extra_roots.append(sys_path.parent)
            for root in extra_roots:
                for rel_try in candidates:
                    hit = ci_resolve(root, rel_try)
                    if not hit and data_dir and data_dir.is_dir():
                        hit = ci_resolve(data_dir, rel_try)
                    if hit and hit.is_file():
                        linked_file = hit
                        break
                if linked_file and linked_file.is_file():
                    break
        if not linked_file or not linked_file.is_file():
            raise ValueError(f"Field ini file not found: {file_rel}")

        original = self._read_text_best_effort(linked_file)
        patched, changed = patch_field_ini_exclusion_section(original, exclusion_nick)
        if changed:
            tmp = str(linked_file) + ".tmp"
            Path(tmp).write_text(patched, encoding="utf-8")
            shutil.move(tmp, linked_file)
            self._set_dirty(True)
        return {
            "changed": bool(changed),
            "rel": file_rel,
            "original": original,
        }

    def CreateExclusionZone(self, system: str, field_zone_nickname: str, params: dict) -> dict:
        if not self._filepath:
            raise ValueError("No system loaded")
        if Path(self._filepath).stem.lower() != system.strip().lower():
            raise ValueError("System mismatch")

        field_zone = next(
            (z for z in self._zones if z.nickname.lower() == field_zone_nickname.strip().lower()),
            None,
        )
        if field_zone is None:
            raise ValueError(f"Field zone not found: {field_zone_nickname}")
        if not self._is_field_zone(field_zone.nickname):
            raise ValueError("Selected zone is not a nebula/asteroid field zone")

        zone_nickname = params.get("nickname", "").strip()
        existing_nicks = [z.nickname.lower() for z in self._zones]
        if not zone_nickname:
            zone_nickname = generate_exclusion_nickname(system, field_zone.nickname, [z.nickname for z in self._zones])
        if zone_nickname.lower() in existing_nicks:
            raise ValueError(f"Zone nickname already exists: {zone_nickname}")

        shape = params.get("shape", "SPHERE")
        pos = params.get("pos", (0.0, 0.0, 0.0))
        size_raw = params.get("size", (1000.0, 1000.0, 1000.0))
        rotate = params.get("rotate", (0.0, 0.0, 0.0))
        comment = params.get("comment", "")
        sort_val = params.get("sort", 99)
        link_to_field = bool(params.get("link_to_field_zone", True))

        shape_up = str(shape).upper()
        if shape_up == "SPHERE":
            if isinstance(size_raw, tuple):
                size_value: float | tuple[float, ...] = float(size_raw[0])
            else:
                size_value = float(size_raw)
        elif shape_up == "CYLINDER":
            if isinstance(size_raw, tuple):
                if len(size_raw) < 2:
                    raise ValueError("Size tuple must have at least 2 values for CYLINDER")
                size_value = (float(size_raw[0]), float(size_raw[1]))
            else:
                size_num = float(size_raw)
                size_value = (size_num, size_num)
        else:
            if isinstance(size_raw, tuple):
                if len(size_raw) != 3:
                    raise ValueError("Size tuple must have 3 values for ELLIPSOID/BOX")
                size_value = (float(size_raw[0]), float(size_raw[1]), float(size_raw[2]))
            else:
                size_num = float(size_raw)
                size_value = (size_num, size_num, size_num)

        exclusion_entries = build_exclusion_zone_entries(
            nickname=zone_nickname,
            shape=shape_up,
            pos=(float(pos[0]), float(pos[1]), float(pos[2])),
            size=size_value,
            rotate=(float(rotate[0]), float(rotate[1]), float(rotate[2])),
            comment=comment,
            sort=int(sort_val),
        )

        ini_path = Path(self._filepath)
        original_text = self._read_text_best_effort(ini_path)
        patched = patch_system_ini_for_exclusion(
            original_text,
            field_zone_nickname=field_zone.nickname,
            exclusion_zone_nickname=zone_nickname,
            exclusion_zone_entries=exclusion_entries,
            link_to_field_zone=False,
        )

        tmp = str(ini_path) + ".tmp"
        Path(tmp).write_text(patched, encoding="utf-8")
        shutil.move(tmp, ini_path)

        linked_files: list[dict] = []
        if link_to_field:
            link_info = self.LinkExclusionToFieldZone(system, field_zone.nickname, zone_nickname)
            if isinstance(link_info, dict) and link_info.get("changed"):
                linked_files.append(
                    {
                        "rel": str(link_info.get("rel", "")).strip(),
                        "content": str(link_info.get("original", "")),
                    }
                )

        self._set_dirty(False)
        self._load(self._filepath, restore=self._capture_2d_view_restore_state())
        self.browser.highlight_current(self._filepath)

        created_zone = next(
            (z for z in self._zones if z.nickname.lower() == zone_nickname.lower()),
            None,
        )
        if created_zone is not None:
            self._select_zone(created_zone)

        return {
            "zone": created_zone,
            "zone_nickname": zone_nickname,
            "ini_block": "\n".join(["[Zone]"] + [f"{k} = {v}" for k, v in exclusion_entries]),
            "linked_files": linked_files,
        }

    # ==================================================================
    #  Base erstellen
    # ==================================================================
    def _start_base_creation(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        game_path = self._primary_game_path()
        if not game_path:
            self._warn_missing_game_path("msg.error")
            return
        sys_nick = Path(self._filepath).stem
        sys_upper = sys_nick.upper()
        static_data = self._base_dialog_static_data(game_path)
        archetypes = list(static_data.get("archetypes", []))
        default_loadouts_by_archetype = dict(static_data.get("default_loadouts_by_archetype", {}))
        if not archetypes:
            QMessageBox.warning(self, tr("msg.error"), "No base archetypes found in DATA/SOLAR/solararch.ini.")
            return
        loadouts = [self.loadout_cb.itemText(i) for i in range(self.loadout_cb.count()) if self.loadout_cb.itemText(i)]
        factions = [self.faction_cb.itemText(i) for i in range(self.faction_cb.count()) if self.faction_cb.itemText(i)]

        # Nächste freie Base-Nummer ermitteln
        existing_nums: list[int] = []
        prefix = f"{sys_upper}_"
        for sec_name, entries in self._uni_sections:
            if sec_name.lower() == "base":
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip().upper()
                        if nick.startswith(prefix) and nick.endswith("_BASE"):
                            mid = nick[len(prefix):-len("_BASE")]
                            if mid.isdigit():
                                existing_nums.append(int(mid))
                        break
        next_num = max(existing_nums, default=0) + 1

        # Existierende Bases sammeln (für Template-Dropdown): nickname - ingamename
        existing_bases: list[tuple[str, str]] = []
        for sec_name, entries in self._uni_sections:
            if sec_name.lower() == "base":
                base_nick = ""
                base_strid = ""
                for k, v in entries:
                    kl = k.lower()
                    if kl == "nickname":
                        base_nick = v.strip()
                    elif kl == "strid_name":
                        base_strid = v.strip()
                if base_nick:
                    ingame = self._display_name_from_ids_name(base_strid)
                    ingame = str(ingame or "").strip() or base_nick
                    existing_bases.append((f"{base_nick} - {ingame}", base_nick))

        # Piloten, Voices und Kostüme aus Spieldaten laden
        pilots = list(static_data.get("pilots", []))
        voices = list(static_data.get("voices", []))
        heads, bodies = tuple(static_data.get("bodyparts", ([], [])))
        li01_03_xml = self._base_infocard_xml_by_base_nickname(game_path, "Li01_03_Base")

        dlg = BaseCreationDialog(
            self, sys_nick, archetypes, loadouts, factions, existing_bases,
            next_base_num=next_num, pilots=pilots, voices=voices,
            heads=heads, bodies=bodies,
            template_data_provider=lambda template_nick, gp=game_path: self._base_template_dialog_data(gp, template_nick),
            ids_info_template_xml=li01_03_xml,
            default_loadouts_by_archetype=default_loadouts_by_archetype,
        )
        if dlg.exec() != QDialog.Accepted:
            return
        payload = dlg.payload()
        base_nick = payload["base_nickname"]
        obj_nick = payload["obj_nickname"]
        if not base_nick or not obj_nick:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.base_obj_required"))
            return
        if not payload["rooms"]:
            QMessageBox.warning(self, tr("msg.incomplete"), tr("msg.min_one_room"))
            return
        # Validierung: start_room muss in Rooms enthalten sein
        if payload["start_room"] not in payload["rooms"]:
            QMessageBox.warning(
                self, tr("msg.invalid"),
                tr("msg.start_room_invalid").format(room=payload['start_room'])
            )
            return
        self._pending_base = {
            "game_path": game_path,
            "sys_nick": sys_nick,
            **payload,
        }
        self._set_placement_mode(True, tr("placement.base").format(name=base_nick))

    def _create_base_at_pos(self, pos: QPointF):
        """Erstellt alle Dateien und Einträge für eine neue Base."""
        info = self._pending_base
        if not info:
            return
        self._pending_base = None
        has_ids_toolchain = bool(self._has_ids_resource_toolchain())

        game_path = info["game_path"]
        sys_nick = info["sys_nick"]
        base_nick = info["base_nickname"]
        obj_nick = info["obj_nickname"]
        rooms = info["rooms"]
        start_room = info["start_room"]
        template_base = info.get("template_base", "")
        room_customizations = info.get("room_customizations", {}) if isinstance(info.get("room_customizations"), dict) else {}
        ids_name_val = "0"
        strid_name_val = "0"
        ids_info_val = "0"
        ids_name_text = str(info.get("ids_name_text", "") or "").strip()
        ids_info_template_xml = str(info.get("ids_info_template_xml", "") or "").strip()
        rep_nick = self._normalize_reputation_value(info.get("reputation", ""))
        safe_archetype, arch_changed = self._normalize_base_archetype(game_path, info.get("archetype", ""))
        ids_strings_changed = False
        if ids_name_text and has_ids_toolchain:
            try:
                ids_name_val = self._ensure_ids_name_in_user_dll(ids_name_val, ids_name_text)
                # Base-Objektname und universe.strid_name teilen sich denselben DLL-Eintrag.
                strid_name_val = ids_name_val
                ids_strings_changed = True
            except Exception as exc:
                QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
        if ids_info_template_xml and has_ids_toolchain:
            try:
                ids_info_val = self._ensure_ids_info_in_user_dll("0", ids_info_template_xml)
                patch_result_info = f"ids_info created from Li01_03_Base template: {ids_info_val}"
                ids_strings_changed = True
            except Exception as exc:
                patch_result_info = f"ids_info template copy failed ({exc})"
        else:
            patch_result_info = "ids_info template source not found (Li01_03_Base)"

        sys_dir = Path(self._filepath).parent
        bases_dir = sys_dir / "BASES"
        rooms_dir = bases_dir / "ROOMS"
        bases_dir.mkdir(parents=True, exist_ok=True)
        rooms_dir.mkdir(parents=True, exist_ok=True)

        patch_result: list[str] = []
        if callable(getattr(self, "_set_loading_visible", None)):
            self._set_loading_visible(True, tr("status.loading"))
            QApplication.processEvents()

        # ----- 1) Room-INI-Dateien erstellen -----
        template_rooms: dict[str, str] = self._load_template_rooms(game_path, template_base) if template_base else {}
        patch_result.extend(
            create_base_room_files(
                rooms_dir=rooms_dir,
                base_nick=base_nick,
                rooms=rooms,
                start_room=start_room,
                template_rooms=template_rooms,
                room_customizations=room_customizations,
                adapt_template_room=self._adapt_template_room,
                generate_room_ini=self._generate_room_ini,
                override_room_scene=self._override_room_scene,
                normalize_room_navigation_callback=MainWindow._normalize_room_navigation,
                room_exists_message=lambda file: tr("result.room_exists").format(file=file),
                room_created_message=lambda file: tr("result.room_created").format(file=file),
            )
        )
        patch_result.append(patch_result_info)

        # ----- 2) Base-INI erstellen -----
        base_ini_path = bases_dir / f"{base_nick}.ini"
        write_base_ini(
            base_ini_path,
            base_nick=base_nick,
            system_nick=sys_nick,
            start_room=start_room,
            price_variance=float(info["price_variance"]),
            rooms=rooms,
        )
        patch_result.append(tr("result.base_ini_created").format(file=base_ini_path.name))

        # ----- 3) [Object] ins System-INI einfügen -----
        pos_str = f"{pos.x() / self._scale:.2f}, 0.00, {pos.y() / self._scale:.2f}"
        obj_entries = build_base_object_entries(
            obj_nick=obj_nick,
            pos_str=pos_str,
            ids_name_val=ids_name_val,
            ids_info_val=ids_info_val,
            archetype=safe_archetype,
            base_nick=base_nick,
            loadout=str(info.get("loadout", "") or ""),
            pilot=str(info.get("pilot", "") or ""),
            reputation=rep_nick,
            voice=str(info.get("voice", "") or ""),
            space_costume=str(info.get("space_costume", "") or ""),
        )

        self._add_object_from_entries(obj_entries, "Object", refresh_3d=False)
        if arch_changed:
            patch_result.append(f"Archetype fallback applied: {info.get('archetype', '')} -> {safe_archetype}")
        # Neu geschriebene DLL-Strings sofort auflösen, damit direkt der Ingame-Name erscheint.
        if ids_strings_changed:
            self._reload_dll_name_cache()
            self._ids_display_cache.clear()
            self._apply_system_name_mode_to_ui()
        patch_result.append(tr("result.obj_inserted").format(nickname=obj_nick))

        # ----- 4) [Base] in universe.ini anhängen -----
        uni_ini = self._find_universe_ini_write(game_path)
        if uni_ini:
            rel_base = f"Universe\\Systems\\{sys_nick}\\Bases\\{base_nick}.ini"
            base_entries = build_universe_base_entries(
                base_nick=base_nick,
                system_nick=sys_nick,
                strid_name_val=str(strid_name_val),
                file_rel=rel_base,
                bgcs_base_run_by=str(info.get("bgcs_base_run_by", "") or ""),
            )
            append_ini_section_block(uni_ini, "Base", base_entries)
            # _uni_sections aktualisieren
            self._uni_sections.append(("Base", base_entries))
            patch_result.append(tr("result.base_registered").format(nickname=base_nick))
        else:
            patch_result.append(tr("result.uni_not_found_base"))

        # ----- 4b) Minimalen MBase-Eintrag in mbases.ini sicherstellen -----
        try:
            mbase_added, _ = self._ensure_mbase_entry_for_base(
                game_path=game_path,
                base_nick=base_nick,
                local_faction=(rep_nick or "li_n_grp"),
                diff=1,
            )
            if mbase_added:
                patch_result.append(f"mbases.ini: created MBase for {base_nick}")
        except Exception as exc:
            patch_result.append(f"mbases.ini: could not create MBase ({exc})")

        # ----- 4c) Optionale NPC-Zuweisungen aus dem Room-Editor -----
        if self._room_customizations_have_npcs(room_customizations):
            try:
                npc_created = self._apply_room_npcs_to_base(
                    game_path=game_path,
                    base_nick=base_nick,
                    local_faction=(rep_nick or "li_n_grp"),
                    room_customizations=room_customizations,
                    valid_rooms=rooms,
                )
                if npc_created > 0:
                    patch_result.append(f"mbases.ini: created {npc_created} room NPC(s)")
            except Exception as exc:
                patch_result.append(f"mbases.ini: room NPC assignment failed ({exc})")

        # ----- 5) Validierung -----
        errors: list[str] = []
        # Prüfe Room-Dateien
        for room_name in rooms:
            room_lower = room_name.lower()
            rf = rooms_dir / f"{base_nick}_{room_lower}.ini"
            if not rf.exists():
                errors.append(tr("audit.room_not_found").format(file=rf.name))
        # Prüfe Konsistenz
        if not base_ini_path.exists():
            errors.append(tr("audit.base_ini_not_found").format(path=base_ini_path.name))

        # ----- Ergebnis anzeigen -----
        self._set_dirty(True)
        self._write_to_file(reload=False)
        if self.view3d_switch.isChecked():
            self._refresh_3d_scene()
        if callable(getattr(self, "_set_loading_visible", None)):
            self._set_loading_visible(False)

        result_msg = tr("msg.base_creation_done") + "\n".join(patch_result)
        if errors:
            result_msg += "\n\n" + tr("msg.validation_errors") + "\n".join(f"  • {e}" for e in errors)
        QMessageBox.information(self, tr("msg.base_created"), result_msg)
        self.statusBar().showMessage(tr("status.base_created").format(nickname=base_nick))

    @staticmethod
    def _room_customizations_have_npcs(room_customizations: dict | None) -> bool:
        if not isinstance(room_customizations, dict):
            return False
        for cfg in room_customizations.values():
            if not isinstance(cfg, dict):
                continue
            npc_rows = cfg.get("npc_rows", [])
            if isinstance(npc_rows, list) and any(
                str((row.get("nickname", "") if isinstance(row, dict) else row) or "").strip()
                for row in npc_rows
            ):
                return True
            legacy_npcs = cfg.get("npcs", [])
            if isinstance(legacy_npcs, list) and any(str(row or "").strip() for row in legacy_npcs):
                return True
        return False

    def _ensure_mbase_entry_for_base(
        self,
        game_path: str,
        base_nick: str,
        local_faction: str,
        diff: int = 1,
    ) -> tuple[bool, str]:
        """Ensures a minimal [MBase] (+ [MVendor]) entry exists for a base."""
        if not str(base_nick or "").strip():
            return False, "empty base nickname"

        mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
        if not mbases_path:
            return False, "mbases.ini not found"
        mbases_path = Path(self._ensure_writable_path(mbases_path))
        mbases_path.parent.mkdir(parents=True, exist_ok=True)
        if not mbases_path.exists():
            mbases_path.write_text("", encoding="utf-8")

        sections = self._parser.parse(str(mbases_path))
        for sec_name, entries in sections:
            if sec_name.strip().lower() != "mbase":
                continue
            nick = self._entry_get_value(entries, "nickname").strip()
            if nick.lower() == base_nick.lower():
                return False, "already exists"

        fac = self._normalize_reputation_value(local_faction or "").strip() or "li_n_grp"
        try:
            diff_val = max(0, int(diff))
        except Exception:
            diff_val = 1

        sections.append(
            (
                "MBase",
                [
                    ("nickname", base_nick),
                    ("local_faction", fac),
                    ("diff", str(diff_val)),
                    ("msg_id_prefix", f"gcs_refer_base_{base_nick}"),
                ],
            )
        )
        sections.append(("MVendor", [("num_offers", "0, 0")]))
        self._write_sections_to_file(str(mbases_path), sections)
        return True, str(mbases_path)

    # ------------------------------------------------------------------
    #  Room-Template-Hilfsfunktionen
    # ------------------------------------------------------------------
    def _base_infocard_xml_by_base_nickname(self, game_path: str, base_nickname: str) -> str:
        base_ids = self._find_base_object_ids_info(game_path, base_nickname)
        if base_ids <= 0:
            return ""
        return str(self._resolve_infocard_xml_by_global_id(base_ids) or "")

    def _find_base_object_ids_info(self, game_path: str, base_nickname: str) -> int:
        base_low = str(base_nickname or "").strip().lower()
        if not base_low:
            return 0
        for row in self._find_all_systems(game_path):
            sys_path = str(row.get("path", "") or "").strip()
            if not sys_path:
                continue
            try:
                secs = self._parser.parse(sys_path)
            except Exception:
                continue
            for sec_name, entries in secs:
                if str(sec_name).strip().lower() != "object":
                    continue
                obj_base = self._entry_get_value(entries, "base").strip().lower()
                obj_dock = self._entry_get_value(entries, "dock_with").strip().lower()
                if obj_base != base_low and obj_dock != base_low:
                    continue
                raw = self._entry_get_value(entries, "ids_info").strip()
                try:
                    gid = int(raw or "0")
                except Exception:
                    gid = 0
                if gid > 0:
                    return gid
        return 0

    def _load_base_room_template_details(self, game_path: str, template_base_nick: str) -> list[dict]:
        return load_base_room_template_details(
            universe_sections=self._uni_sections,
            template_base_nick=template_base_nick,
            game_path=game_path,
            resolve_game_path_case_insensitive=self._resolve_game_path_case_insensitive,
            parse_sections=lambda path: self._parser.parse(path),
            read_text_best_effort=self._read_text_best_effort,
            extract_room_scene_path=self._extract_room_scene_path,
        )

    def _load_base_template_virtual_room_targets(self, game_path: str, template_base_nick: str) -> list[str]:
        return load_base_template_virtual_room_targets(
            template_rooms=self._load_template_rooms(game_path, template_base_nick),
            extract_virtual_room_targets=self._extract_virtual_room_targets,
        )

    def _load_base_template_room_npcs(self, game_path: str, template_base_nick: str) -> dict[str, list[dict[str, str]]]:
        out: dict[str, list[dict[str, str]]] = {}
        mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
        if not mbases_path or not mbases_path.exists():
            return out
        try:
            sections = self._parser.parse(str(mbases_path))
        except Exception:
            return out
        base_low = str(template_base_nick or "").strip().lower()
        if not base_low:
            return out

        mbase_idx: int | None = None
        for i, (sec_name, entries) in enumerate(sections):
            if str(sec_name).strip().lower() != "mbase":
                continue
            if self._entry_get_value(entries, "nickname").strip().lower() == base_low:
                mbase_idx = i
                break
        if mbase_idx is None:
            return out
        start_idx, end_idx = self._npc_find_section_range(sections, mbase_idx)

        npc_to_faction: dict[str, str] = {}
        local_faction = self._entry_get_value(sections[mbase_idx][1], "local_faction").strip()
        for i in range(start_idx + 1, end_idx):
            sec_name, entries = sections[i]
            if str(sec_name).strip().lower() != "basefaction":
                continue
            fac = self._normalize_reputation_value(self._entry_get_value(entries, "faction").strip())
            for k, v in entries:
                if str(k).strip().lower() != "npc":
                    continue
                npc = str(v or "").strip()
                if npc and npc.lower() not in npc_to_faction:
                    npc_to_faction[npc.lower()] = fac

        fixture_map: dict[str, tuple[str, str]] = {}
        for i in range(start_idx + 1, end_idx):
            sec_name, entries = sections[i]
            if str(sec_name).strip().lower() != "mroom":
                continue
            room = self._npc_room_key(self._entry_get_value(entries, "nickname").strip())
            if not room:
                continue
            for k, v in entries:
                if str(k).strip().lower() != "fixture":
                    continue
                parts = [p.strip() for p in str(v or "").split(",")]
                if not parts:
                    continue
                npc = parts[0].strip()
                role = self._npc_normalize_role_for_room(parts[-1].strip() if len(parts) >= 2 else "", room)
                if npc:
                    fixture_map[npc.lower()] = (room, role)

        for i in range(start_idx + 1, end_idx):
            sec_name, entries = sections[i]
            if str(sec_name).strip().lower() != "gf_npc":
                continue
            npc = self._entry_get_value(entries, "nickname").strip()
            if not npc:
                continue
            room = self._entry_get_value(entries, "room").strip().lower()
            role = ""
            fx = fixture_map.get(npc.lower())
            if fx:
                # MRoom.fixture is the authoritative spawn/role source for fixed base NPCs.
                # Prefer it over GF_NPC.room to avoid inheriting stale room assignments
                # from previously edited/corrupted templates.
                room = fx[0] or room
                role = fx[1]
            room = self._npc_room_key(room)
            if not room:
                continue
            ids_val = self._entry_get_value(entries, "individual_name").strip()
            name_text = self._display_name_from_ids_name(ids_val).strip() if ids_val else ""
            if not name_text:
                name_text = npc
            rep = self._normalize_reputation_value(npc_to_faction.get(npc.lower(), "") or local_faction)
            aff = self._normalize_reputation_value(self._entry_get_value(entries, "affiliation").strip())
            out.setdefault(room, [])
            if not any(str(n.get("nickname", "")).strip().lower() == npc.lower() for n in out[room]):
                out[room].append(
                    {
                        "nickname": npc,
                        "name_text": name_text,
                        "reputation": rep,
                        "affiliation": aff or rep,
                        "role": role,
                    }
                )
        return out

    @staticmethod
    def _npc_room_density(room_name: str) -> int:
        return npc_room_density(room_name)

    @staticmethod
    def _npc_room_key(room_name: str) -> str:
        return npc_room_key(room_name)

    @staticmethod
    def _npc_canonical_mroom_name(room_name: str) -> str:
        return npc_canonical_mroom_name(room_name)

    @staticmethod
    def _npc_allowed_roles_for_room(room_name: str) -> list[str]:
        return npc_allowed_roles_for_room(room_name)

    @staticmethod
    def _npc_normalize_role_for_room(role: str, room_name: str) -> str:
        return npc_normalize_role_for_room(role, room_name)

    @staticmethod
    def _npc_fixture_scene_for_role(role: str) -> tuple[str, str]:
        return npc_fixture_scene_for_role(role)

    def _npc_upsert_mrooms_for_base(
        self,
        sections: list[tuple[str, list[tuple[str, str]]]],
        base_nickname: str,
        room_fixtures: dict[str, list[tuple[str, str]]],
    ) -> bool:
        return npc_upsert_mrooms_for_base(
            sections,
            base_nickname=base_nickname,
            room_fixtures=room_fixtures,
            entry_get_value=self._entry_get_value,
        )

    @staticmethod
    def _extract_virtual_room_targets(content: str) -> list[str]:
        return extract_virtual_room_targets(content)

    @staticmethod
    def _extract_room_scene_path(content: str) -> str:
        return extract_room_scene_path(content)

    @staticmethod
    def _override_room_scene(content: str, scene_path: str) -> str:
        return override_room_scene(content, scene_path)

    def _apply_room_npcs_to_base(
        self,
        game_path: str,
        base_nick: str,
        local_faction: str,
        room_customizations: dict,
        valid_rooms: list[str],
    ) -> int:
        valid = {self._npc_room_key(str(r or "").strip()) for r in valid_rooms if str(r or "").strip()}
        if not valid:
            return 0
        mbases_path = self._target_game_path_for_rel(game_path, "DATA/MISSIONS/mbases.ini")
        if not mbases_path:
            return 0
        mbases_path = str(self._ensure_writable_path(mbases_path))
        sections = self._parser.parse(mbases_path)
        base_fac = self._normalize_reputation_value(local_faction or "").strip() or "li_n_grp"
        created = 0
        changed = False
        if not isinstance(room_customizations, dict):
            return 0

        def _set_entry(entries: list[tuple[str, str]], key: str, value: str) -> list[tuple[str, str]]:
            out = list(entries)
            for i, (k, _v) in enumerate(out):
                if str(k).strip().lower() == key.lower():
                    out[i] = (k, value)
                    return out
            out.append((key, value))
            return out

        def _drop_entry(entries: list[tuple[str, str]], key: str) -> list[tuple[str, str]]:
            return [(k, v) for (k, v) in list(entries) if str(k).strip().lower() != key.lower()]

        # Locate MBase block for this base and inspect current room/npc references.
        base_low = str(base_nick or "").strip().lower()
        mbase_idx: int | None = None
        for i, (sec_name, entries) in enumerate(sections):
            if str(sec_name).strip().lower() != "mbase":
                continue
            if self._entry_get_value(entries, "nickname").strip().lower() == base_low:
                mbase_idx = i
                break
        if mbase_idx is None:
            return 0
        start_idx, end_idx = self._npc_find_section_range(sections, mbase_idx)

        existing_fixture_nicks_by_room: dict[str, set[str]] = {}
        for i in range(start_idx + 1, end_idx):
            sec_name, entries = sections[i]
            if str(sec_name).strip().lower() != "mroom":
                continue
            room_key = self._npc_room_key(self._entry_get_value(entries, "nickname").strip())
            if not room_key or room_key not in valid:
                continue
            for k, v in entries:
                if str(k).strip().lower() != "fixture":
                    continue
                parts = [p.strip() for p in str(v or "").split(",")]
                if not parts:
                    continue
                npc = str(parts[0] or "").strip()
                if not npc:
                    continue
                existing_fixture_nicks_by_room.setdefault(room_key, set()).add(npc.lower())

        existing_gf_nicks_by_room: dict[str, set[str]] = {}
        for i in range(start_idx + 1, end_idx):
            sec_name, entries = sections[i]
            if str(sec_name).strip().lower() != "gf_npc":
                continue
            npc = self._entry_get_value(entries, "nickname").strip()
            if not npc:
                continue
            room_val = self._npc_room_key(self._entry_get_value(entries, "room").strip())
            if not room_val or room_val not in valid:
                continue
            existing_gf_nicks_by_room.setdefault(room_val, set()).add(npc.lower())

        existing_managed_nicks: set[str] = set()
        for _room, vals in existing_fixture_nicks_by_room.items():
            existing_managed_nicks.update(vals)
        for _room, vals in existing_gf_nicks_by_room.items():
            existing_managed_nicks.update(vals)

        # Build desired NPC rows + fixtures from editor payload.
        seen_npcs: set[str] = set()
        desired_by_nick: dict[str, dict[str, str]] = {}
        room_fixtures: dict[str, list[tuple[str, str]]] = {}
        for room_key, cfg in room_customizations.items():
            room_name = self._npc_room_key(str(room_key or "").strip())
            if not room_name or room_name not in valid:
                continue
            room_fixtures.setdefault(room_name, [])
            npc_rows = cfg.get("npc_rows", []) if isinstance(cfg, dict) else []
            if not isinstance(npc_rows, list):
                npc_rows = []
            if not npc_rows:
                npc_list = cfg.get("npcs", []) if isinstance(cfg, dict) else []
                if isinstance(npc_list, list):
                    npc_rows = [
                        {
                            "nickname": str(raw_npc or "").strip(),
                            "name_text": str(raw_npc or "").strip(),
                            "role": "",
                        }
                        for raw_npc in npc_list
                    ]
            for npc_row in npc_rows:
                if isinstance(npc_row, dict):
                    npc = str(npc_row.get("nickname", "") or "").strip()
                    name_text = str(npc_row.get("name_text", "") or "").strip()
                    rep = self._normalize_reputation_value(str(npc_row.get("reputation", "") or "").strip())
                    aff = self._normalize_reputation_value(str(npc_row.get("affiliation", "") or "").strip())
                    role = self._npc_normalize_role_for_room(str(npc_row.get("role", "") or "").strip(), room_name)
                else:
                    npc = str(npc_row or "").strip()
                    name_text = npc
                    rep = ""
                    aff = ""
                    role = self._npc_normalize_role_for_room("", room_name)
                if not npc:
                    continue
                npc_low = npc.lower()
                if npc_low in seen_npcs:
                    continue
                seen_npcs.add(npc_low)
                fac = rep or base_fac
                npc_aff = aff or fac
                desired_by_nick[npc_low] = {
                    "nickname": npc,
                    "room": room_name,
                    "role": role,
                    "name_text": name_text or npc,
                    "reputation": fac,
                    "affiliation": npc_aff,
                }
                room_fixtures.setdefault(room_name, []).append((npc, role))

        desired_nicks = set(desired_by_nick.keys())
        delete_nicks = existing_managed_nicks - desired_nicks

        # Delete removed NPCs from this base block.
        for nick_low in sorted(delete_nicks):
            gf_idx = self._npc_find_gf_section_index(sections, nick_low)
            if gf_idx is not None:
                sections.pop(gf_idx)
                changed = True
            sections = self._npc_detach_from_mbase(sections, base_nick, nick_low)
            changed = True

        # Upsert desired NPCs (create + update + reattach faction).
        for nick_low in sorted(desired_nicks):
            row = desired_by_nick[nick_low]
            npc = row["nickname"]
            room_name = row["room"]
            fac = row["reputation"]
            npc_aff = row["affiliation"]
            name_for_ids = row["name_text"]

            gf_idx = self._npc_find_gf_section_index(sections, npc)
            if gf_idx is None:
                individual_name = self._ensure_ids_name_in_user_dll("0", name_for_ids)
                npc_entries: list[tuple[str, str]] = [
                    ("nickname", npc),
                    ("body", "benchmark_male_body"),
                    ("head", "benchmark_male_head"),
                    ("lefthand", "benchmark_male_hand_left"),
                    ("righthand", "benchmark_male_hand_right"),
                    ("individual_name", str(individual_name)),
                    ("affiliation", npc_aff),
                    ("voice", "mc_leg_m01"),
                ]
                sections = self._npc_insert_gf_for_base(sections, base_nick, npc_entries)
                created += 1
                changed = True
            else:
                sec_name, entries = sections[gf_idx]
                cur_individual = self._entry_get_value(entries, "individual_name").strip()
                try:
                    new_individual = self._ensure_ids_name_in_user_dll(cur_individual or "0", name_for_ids)
                except Exception:
                    new_individual = cur_individual or "0"
                new_entries = list(entries)
                new_entries = _set_entry(new_entries, "individual_name", str(new_individual))
                new_entries = _set_entry(new_entries, "affiliation", npc_aff)
                # Fixed room vendors are spawned via MRoom fixtures; a GF_NPC room
                # assignment causes them to appear a second time as ambient NPC.
                new_entries = _drop_entry(new_entries, "room")
                sections[gf_idx] = (sec_name, new_entries)
                changed = True

            # Rebind npc to the selected BaseFaction.
            sections = self._npc_detach_from_mbase(sections, base_nick, npc)
            sections = self._npc_attach_to_mbase(sections, base_nick, fac, npc)
            changed = True

        fixtures_changed = self._npc_upsert_mrooms_for_base(sections, base_nick, room_fixtures)
        changed = changed or fixtures_changed
        if changed:
            self._write_sections_to_file(mbases_path, sections)
        return created

    def _load_template_rooms(self, game_path: str, template_base_nick: str) -> dict[str, str]:
        """Lädt Room-INI-Dateien einer existierenden Base als Templates.
        Gibt {room_lower: content} zurück."""
        return load_template_rooms(
            universe_sections=self._uni_sections,
            template_base_nick=template_base_nick,
            game_path=game_path,
            resolve_game_path_case_insensitive=self._resolve_game_path_case_insensitive,
            parse_sections=lambda path: self._parser.parse(path),
            read_text_best_effort=self._read_text_best_effort,
        )

    def _adapt_template_room(
        self, content: str, new_base_nick: str, rooms: list[str]
    ) -> str:
        """Passt ein kopiertes Room-Template an.

        Entfernt [Hotspot]-Blöcke, die auf nicht vorhandene Rooms zeigen
        (room_switch / virtual_room). Zusätzlich werden unvollständige
        VirtualRoom-Hotspots ohne room_switch verworfen.
        """
        _ = new_base_nick
        return adapt_template_room(content, rooms)

    @staticmethod
    def _generate_room_ini(room_name: str, all_rooms: list[str], start_room: str) -> str:
        return generate_room_ini_text(room_name, all_rooms, start_room)

    # Mapping Room-Typ → IDS-Hotspot-Name (für Nicht-Hub-Rooms)
    @staticmethod
    def _build_nav_hotspots(
        all_rooms: list[str], start_room: str
    ) -> list[tuple[str, str]]:
        return build_nav_hotspots(all_rooms, start_room)

    @staticmethod
    def _normalize_room_navigation(
        content: str,
        room_name: str,
        all_rooms: list[str],
        start_room: str,
    ) -> str:
        return normalize_room_navigation(content, room_name, all_rooms, start_room)

    def normalize_base_rooms(
        self, base_ini_path: str, game_path: str
    ) -> list[str]:
        """Liest eine Base-INI, patcht alle Room-INIs idempotent.

        Stellt sicher:
          • Jeder Room enthält den vollständigen Satz an Navigation-Hotspots
            (inkl. Self-Button).
          • Launch/Abflug funktioniert korrekt (EXIT → room_switch = Hub,
            Selbstreferenz im Hub = Launch).
          • Keine überflüssigen oder fehlenden ExitDoor-Hotspots.

        Gibt einen Patch-Report zurück (Liste von Strings).
        """
        report: list[str] = []
        base_path = Path(base_ini_path)

        if not base_path.exists():
            report.append(tr("audit.base_ini_not_found").format(path=base_ini_path))
            return report

        try:
            sections = self._parser.parse(str(base_path))
        except Exception as exc:
            report.append(tr("audit.parse_error").format(error=exc))
            return report

        start_room = ""
        rooms: list[tuple[str, str]] = []  # (nickname, file_rel)
        for sec_name, entries in sections:
            if sec_name.lower() == "baseinfo":
                for k, v in entries:
                    if k.lower() == "start_room":
                        start_room = v.strip()
            elif sec_name.lower() == "room":
                nick = ""
                file_rel = ""
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip()
                    elif k.lower() == "file":
                        file_rel = v.strip()
                if nick and file_rel:
                    rooms.append((nick, file_rel))

        if not start_room:
            report.append(tr("audit.no_start_room"))
            return report
        if not rooms:
            report.append(tr("audit.no_rooms"))
            return report

        all_room_names = [r[0] for r in rooms]
        report.append(f"Base: {base_path.name}")
        report.append(f"  Hub (start_room): {start_room}")
        report.append(f"  Rooms: {', '.join(all_room_names)}")
        report.append("")

        for nick, file_rel in rooms:
            room_path = self._resolve_game_path_case_insensitive(
                game_path, file_rel
            )
            if not room_path or not room_path.exists():
                report.append(tr("audit.room_not_found").format(file=file_rel))
                continue

            try:
                content = self._read_text_best_effort(room_path)
            except Exception as exc:
                report.append(tr("audit.room_read_error").format(file=room_path.name, error=exc))
                continue

            new_content = MainWindow._normalize_room_navigation(
                content, nick, all_room_names, start_room
            )

            if content == new_content:
                report.append(tr("audit.unchanged").format(file=room_path.name))
            else:
                room_path.write_text(new_content, encoding="utf-8")
                # Detailbericht: welche Hotspots wurden gesetzt?
                nav = MainWindow._build_nav_hotspots(all_room_names, start_room)
                nav_names = [n for n, _ in nav]
                report.append(
                    tr("audit.patched").format(file=room_path.name, hotspots=", ".join(nav_names))
                )

        return report

    # ------------------------------------------------------------------
    #  Scan-Helfer für Base-Dialog Dropdowns
    # ------------------------------------------------------------------
    def _scan_pilots(self, game_path: str) -> list[str]:
        """Scannt pilots_population.ini nach allen [Pilot]-Nicknames."""
        pilots: list[str] = []
        pp = self._resolve_game_path_case_insensitive(game_path, "DATA/MISSIONS/pilots_population.ini")
        if not pp or not pp.is_file():
            return pilots
        try:
            sections = self._parser.parse(str(pp))
            for sec_name, entries in sections:
                if sec_name.lower() == "pilot":
                    for k, v in entries:
                        if k.lower() == "nickname":
                            pilots.append(v.strip())
                            break
        except Exception:
            pass
        return pilots

    def _scan_voices(self, game_path: str) -> list[str]:
        """Scannt Voice-INIs unter DATA/AUDIO nach allen [Voice]-Nicknames."""
        voices: list[str] = []
        audio_dir = self._resolve_data_subdir_case_insensitive(game_path, "AUDIO")
        if not audio_dir or not audio_dir.is_dir():
            return voices
        voice_files = [
            "voices_space_male.ini", "voices_space_female.ini",
            "voices_base_male.ini", "voices_base_female.ini",
            "voices_recognizable.ini",
        ]
        for fname in voice_files:
            vf = self._resolve_game_path_case_insensitive(game_path, f"DATA/AUDIO/{fname}")
            if not vf or not vf.is_file():
                continue
            try:
                sections = self._parser.parse(str(vf))
                for sec_name, entries in sections:
                    if sec_name.lower() == "voice":
                        for k, v in entries:
                            if k.lower() == "nickname":
                                voices.append(v.strip())
                                break
            except Exception:
                pass
        return voices

    def _scan_bodyparts(self, game_path: str) -> tuple[list[str], list[str]]:
        """Scannt DATA/CHARACTERS/bodyparts.ini nach Head- und Body-Teilen."""
        heads: list[str] = []
        bodies: list[str] = []
        bp = self._resolve_game_path_case_insensitive(game_path, "DATA/CHARACTERS/bodyparts.ini")
        if not bp or not bp.is_file():
            return heads, bodies
        try:
            sections = self._parser.parse(str(bp))
            for sec_name, entries in sections:
                if sec_name.lower() not in ("body", "head"):
                    continue
                for k, v in entries:
                    if k.lower() == "nickname":
                        nick = v.strip()
                        if sec_name.lower() == "head":
                            heads.append(nick)
                        else:
                            bodies.append(nick)
                        break
        except Exception:
            pass
        return heads, bodies

    def _iter_character_ini_paths_for_usage(self, game_path: str) -> list[Path]:
        char_dir = self._resolve_data_subdir_case_insensitive(game_path, "CHARACTERS")
        if not char_dir or not char_dir.is_dir():
            return []
        try:
            return sorted(path for path in char_dir.rglob("*.ini") if path.is_file())
        except Exception:
            return []

    def _resolve_character_model_path(self, game_path: str, raw_value: str) -> Path | None:
        raw = str(raw_value or "").strip().replace("\\", "/").lstrip("/")
        if not raw:
            return None
        candidates = [raw]
        if raw.lower().startswith("data/"):
            trimmed = raw.split("/", 1)[1] if "/" in raw else ""
            if trimmed:
                candidates.append(trimmed)
        else:
            candidates.append(f"DATA/{raw}")
        seen: set[str] = set()
        for candidate in candidates:
            key = candidate.lower()
            if key in seen:
                continue
            seen.add(key)
            path = self._resolve_game_path_case_insensitive(game_path, candidate)
            if path is not None and path.is_file():
                return path
        return None

    def _collect_character_costumes(self, game_path: str) -> dict[str, dict[str, str]]:
        out: dict[str, dict[str, str]] = {}
        fp = self._resolve_game_path_case_insensitive(game_path, "DATA/CHARACTERS/costumes.ini")
        if not fp or not fp.is_file():
            return out
        try:
            sections = self._parser.parse(str(fp))
        except Exception:
            return out
        for sec_name, entries in sections:
            if str(sec_name or "").strip().lower() != "costume":
                continue
            nick = self._entry_get_value(entries, "nickname").strip()
            if not nick:
                continue
            out[nick.lower()] = {
                "nickname": nick,
                "head": self._entry_get_value(entries, "head").strip(),
                "body": self._entry_get_value(entries, "body").strip(),
                "lefthand": self._entry_get_value(entries, "lefthand").strip(),
                "righthand": self._entry_get_value(entries, "righthand").strip(),
            }
        return out

    def _collect_character_viewer_data(self, game_path: str) -> dict[str, object]:
        out: dict[str, object] = {
            "parts_by_kind": {"body": [], "head": [], "lefthand": [], "righthand": []},
            "parts_by_nick": {},
            "costumes": {},
        }
        game_root = str(game_path or "").strip()
        if not game_root:
            return out
        parts_by_kind: dict[str, list[dict[str, object]]] = {
            "body": [],
            "head": [],
            "lefthand": [],
            "righthand": [],
        }
        parts_by_nick: dict[str, dict[str, object]] = {}
        seen_by_kind: dict[str, set[str]] = {kind: set() for kind in parts_by_kind}
        for fp in self._iter_character_ini_paths_for_usage(game_root):
            try:
                sections = self._parser.parse(str(fp))
            except Exception:
                continue
            for sec_name, entries in sections:
                sec = str(sec_name or "").strip().lower()
                if sec == "left_hand":
                    sec = "lefthand"
                elif sec == "right_hand":
                    sec = "righthand"
                if sec not in parts_by_kind:
                    continue
                nick = self._entry_get_value(entries, "nickname").strip()
                if not nick:
                    continue
                nick_key = nick.lower()
                model_path = self._resolve_character_model_path(
                    game_root,
                    self._entry_get_value(entries, "da_archetype").strip()
                    or self._entry_get_value(entries, "mesh").strip(),
                )
                record = parts_by_nick.get(nick_key)
                if record is None:
                    ids_name = self._entry_get_value(entries, "ids_name").strip() or self._entry_get_value(entries, "strid_name").strip()
                    record = {
                        "nickname": nick,
                        "kind": sec,
                        "model_path": model_path,
                        "source_ini_path": fp,
                        "display_name": self._display_name_from_ids_name(ids_name).strip() or nick,
                    }
                    parts_by_nick[nick_key] = record
                else:
                    if record.get("model_path") is None and model_path is not None:
                        record["model_path"] = model_path
                if nick_key in seen_by_kind[sec]:
                    continue
                seen_by_kind[sec].add(nick_key)
                parts_by_kind[sec].append(record)
        for kind, rows in parts_by_kind.items():
            rows.sort(key=lambda item: str(item.get("display_name") or item.get("nickname") or "").lower())
        out["parts_by_kind"] = parts_by_kind
        out["parts_by_nick"] = parts_by_nick
        out["costumes"] = self._collect_character_costumes(game_root)
        return out

    def _start_connection_dialog(self):
        if not self._filepath:
            QMessageBox.warning(self, tr("msg.no_system"), tr("msg.no_system_text"))
            return
        if self._pending_snapshots:
            self._pending_snapshots.clear()
            if hasattr(self, "save_conn_btn"):
                self.save_conn_btn.setVisible(False)
            if hasattr(self, "create_conn_btn"):
                self.create_conn_btn.setEnabled(True)
        systems = []
        for s in self._find_all_systems(self._primary_game_path()):
            nick = str(s.get("nickname", "")).strip().upper()
            p = str(s.get("path", "")).strip()
            if not nick or not p:
                continue
            ingame = self._system_display_name(nick) or nick
            systems.append((f"{nick} - {ingame}", p))
        dlg = ConnectionDialog(self, systems)
        if dlg.exec() != QDialog.Accepted:
            return
        dest_path = dlg.dest_cb.currentData()
        typ = dlg.type_cb.currentText()
        ids_name_text = ""
        origin = self._filepath
        if not origin:
            return
        origin_nick = Path(origin).stem.upper()
        gate_info: dict | None = None
        if typ in ("Jump Gate", "Nomad Gate"):
            loads = [
                self.loadout_cb.itemText(i) for i in range(self.loadout_cb.count())
                if "jumpgate" in self.loadout_cb.itemText(i).lower()
            ]
            facts = [self.faction_cb.itemText(i) for i in range(self.faction_cb.count())]
            gdlg = GateInfoDialog(self, loads, facts)
            if gdlg.exec() != QDialog.Accepted:
                return
            gate_info = {
                "behavior": gdlg.behavior_edit.text().strip(),
                "difficulty": gdlg.difficulty_spin.value(),
                "loadout": gdlg.loadout_cb.currentText().strip(),
                "pilot": gdlg.pilot_edit.text().strip(),
                "reputation": self._faction_from_ui(gdlg.rep_cb.currentText().strip()),
            }
        self._pending_conn = {
            "origin": origin, "origin_nick": origin_nick,
            "dest": dest_path,
            "dest_nick": Path(str(dest_path or "")).stem.upper(),
            "type": typ,
            "phase": "origin",
            "gate_info": gate_info,
            "ids_name_text": ids_name_text,
        }
        self.statusBar().showMessage(tr("status.click_conn_origin"))
        self._set_placement_mode(True, tr("placement.conn_origin"))
        self._preserve_active_system_tab_document()

    # ------------------------------------------------------------------
    #  Neues System erstellen
    # ------------------------------------------------------------------
    def _start_new_system(self):
        """Öffnet Dialog und aktiviert Platzierungsmodus auf der Karte."""
        if self._filepath is not None:
            QMessageBox.information(
                self,
                tr("msg.error"),
                "New System ist nur in der Universe-Map verfügbar.",
            )
            return
        game_path = self._primary_game_path()
        if not game_path:
            self._warn_missing_game_path("msg.no_path")
            return

        # Sammle Optionen aus allen vorhandenen Systemen
        music_vals = {"space": set(), "danger": set(), "battle": set()}
        bg_vals = {"basic_stars": set(), "complex_stars": set(), "nebulae": set()}
        try:
            for s in self._find_all_systems(game_path):
                try:
                    secs = self._parser.parse(s["path"])
                except Exception:
                    continue
                for sec_name, entries in secs:
                    low = sec_name.lower()
                    if low == "music":
                        for k, v in entries:
                            lk = k.lower()
                            if lk in music_vals and v:
                                music_vals[lk].add(v)
                    elif low == "background":
                        for k, v in entries:
                            lk = k.lower()
                            if lk in bg_vals and v:
                                bg_vals[lk].add(v)
        except Exception:
            pass

        factions = list(self._cached_faction_labels) if self._cached_faction_labels else list(self._cached_factions)

        dlg = SystemCreationDialog(
            self,
            music_space=sorted(music_vals["space"], key=str.lower),
            music_danger=sorted(music_vals["danger"], key=str.lower),
            music_battle=sorted(music_vals["battle"], key=str.lower),
            bg_basic=sorted(bg_vals["basic_stars"], key=str.lower),
            bg_complex=sorted(bg_vals["complex_stars"], key=str.lower),
            bg_nebulae=sorted(bg_vals["nebulae"], key=str.lower),
            factions=factions,
        )
        if dlg.exec() != QDialog.Accepted:
            return

        payload = dlg.payload()
        if not payload["name"] or not payload["prefix"]:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.name_prefix_required"))
            return

        self._pending_new_system = {**payload, "game_path": game_path}
        self._set_placement_mode(True, tr("placement.new_system"))
        self.statusBar().showMessage(tr("status.click_system_place"))

    def _create_system_at_pos(self, pos: QPointF):
        """Erstellt das neue System an der Klickposition auf der Karte."""
        info = self._pending_new_system
        if not info:
            return
        self._pending_new_system = None

        game_path = info["game_path"]
        prefix = info["prefix"]
        name = info["name"]
        size = info["size"]
        local_faction = self._faction_from_ui(info.get("local_faction", ""))

        # Auto-Nummerierung: existierende Systeme mit gleichem Prefix zählen
        existing_nums: list[int] = []
        try:
            systems = self._find_all_systems(game_path)
            for s in systems:
                nick = s["nickname"].upper()
                if nick.startswith(prefix):
                    suffix = nick[len(prefix):]
                    if suffix.isdigit():
                        existing_nums.append(int(suffix))
        except Exception:
            pass
        next_num = max(existing_nums, default=0) + 1
        num_str = f"{next_num:02d}"
        nickname = f"{prefix}{num_str}"
        strid_name = "0"
        try:
            strid_name = self._ensure_ids_name_in_user_dll("0", name)
        except Exception as exc:
            QMessageBox.warning(
                self,
                tr("msg.save_error"),
                f"System name IDS could not be written: {exc}\n\n"
                "System creation will continue with strid_name = 0.",
            )

        # Verzeichnis erstellen
        uni_ini = self._find_universe_ini_write(game_path)
        if not uni_ini:
            QMessageBox.critical(self, tr("msg.error"), tr("msg.universe_not_found_2"))
            return

        # System-Datei Pfad (Großbuchstaben für Ordner/Datei)
        systems_dir = uni_ini.parent / "SYSTEMS"
        systems_dir.mkdir(parents=True, exist_ok=True)
        sys_dir = systems_dir / nickname
        sys_dir.mkdir(parents=True, exist_ok=True)
        sys_file = sys_dir / f"{nickname}.ini"

        # System-INI schreiben
        light_nick = f"{nickname}_system_light"
        write_text_atomic(
            sys_file,
            build_system_ini_text(
                space_color=info["space_color"],
                local_faction=local_faction,
                music_space=info["music_space"],
                music_danger=info["music_danger"],
                music_battle=info["music_battle"],
                ambient_color=info["ambient_color"],
                bg_basic=info["bg_basic"],
                bg_complex=info["bg_complex"],
                bg_nebulae=info["bg_nebulae"],
                light_nick=light_nick,
                light_color=info["light_color"],
                size=size,
            ),
        )

        # universe.ini aktualisieren: immer als Text neu schreiben (auch wenn Quelle BINI war)
        uni_x = pos.x() / self._scale
        uni_y = pos.y() / self._scale
        rel_path = f"systems\\{nickname}\\{nickname}.ini"
        uni_ini = self._ensure_writable_path(uni_ini)
        uni_sections = self._parser.parse(str(uni_ini))
        write_text_atomic(
            uni_ini,
            serialize_universe_with_new_system(
                uni_sections,
                nickname=nickname,
                rel_path=rel_path,
                pos_x=uni_x,
                pos_y=uni_y,
                strid_name=str(strid_name),
            ),
        )

        self.statusBar().showMessage(
            tr("status.system_created").format(
                name=name, nickname=nickname, path=sys_file
            )
        )

        self._uni_sections = self._parser.parse(str(uni_ini))
        self._reload_dll_name_cache()
        self._system_display_names_by_nick[nickname.upper()] = name
        self._system_nick_by_path[str(Path(sys_file)).lower()] = nickname.upper()
        if hasattr(self, "browser"):
            self.browser.set_system_name_map(self._system_display_names_by_nick, scan=False)
            self.browser.set_system_name_mode(self._system_name_mode, scan=False)
            self.browser.set_game_path(game_path, scan=True)
        self._filepath = str(sys_file)
        self._load(str(sys_file))
        self.browser.highlight_current(str(sys_file))

    def _on_background_click(self, pos: QPointF):
        if self._pending_new_system:
            self._create_system_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_new_object:
            self._create_object_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_zone:
            self._on_zone_click(pos)
            return
        if self._pending_simple_zone:
            self._on_simple_zone_click(pos)
            return
        if self._pending_exclusion_zone:
            self._on_exclusion_zone_click(pos)
            return
        if self._pending_base:
            self._create_base_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_template_object:
            self._create_template_object_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_buoy:
            self._on_buoy_click(pos)
            if not self._pending_buoy:
                self._set_placement_mode(False)
            return
        if self._pending_light_source:
            self._create_light_source_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_create:
            self._create_solar_at_pos(pos)
            self._set_placement_mode(False)
            return
        if self._pending_tradelane:
            self._on_tradelane_click(pos)
            return
        if self._pending_tl_reposition:
            self._on_tl_reposition_click(pos)
            return
        if self._pending_dock_ring and self._pending_dock_ring.get("step") == 2:
            self._on_dock_ring_orbit_click(pos)
            return
        if not self._pending_conn:
            return
        self._place_connection(pos)

    def _place_connection(self, pos: QPointF):
        """Platziert ein Jump-Verbindungsobjekt an der Klickposition."""
        pending = dict(self._pending_conn or {})
        phase = str(pending.get("phase", "") or "").strip().lower()
        if not phase:
            phase = "origin" if int(pending.get("step", 1) or 1) <= 1 else "destination"
        orig = str(pending.get("origin_nick", "") or "").strip().upper()
        dest_path = str(pending.get("dest", "") or "").strip()
        dest_nick = str(pending.get("dest_nick", "") or "").strip().upper() or Path(dest_path).stem.upper()
        typ = str(pending.get("type", "") or "").strip()
        if not orig or not dest_path or not typ or not self._filepath:
            self._pending_conn = None
            self._set_placement_mode(False)
            return
        if typ == "Jump Gate":
            arch = "jumpgate"
        elif typ == "Nomad Gate":
            arch = "nomad_gate"
        else:
            arch = "jumphole"

        def _make_obj(nick, goto_val, extras=None):
            entries = [
                ("nickname", nick),
                ("pos", f"{pos.x() / self._scale:.2f}, 0, {pos.y() / self._scale:.2f}"),
                ("archetype", arch),
                ("goto", goto_val),
            ]
            if extras:
                entries.extend(extras)
            data = {"_entries": entries}
            for k, v in entries:
                if k.lower() not in data:
                    data[k.lower()] = v
            obj = SolarObject(data, self._scale)
            obj.setFlag(QGraphicsItem.ItemIsMovable, self.move_cb.isChecked())
            self.view._scene.addItem(obj)
            self._objects.append(obj)
            self._select(obj)
            self._set_dirty(True)
            return obj

        def _gate_extras(counterpart_sys: str):
            has_ids_toolchain = bool(self._has_ids_resource_toolchain())
            custom_ids_text = str(self._pending_conn.get("ids_name_text", "") if self._pending_conn else "").strip()
            sys_disp = self._system_display_name(str(counterpart_sys or "").upper()) or str(counterpart_sys or "").upper()
            current_sys_nick = Path(self._filepath).stem.upper() if self._filepath else ""
            current_sys_disp = self._system_display_name(current_sys_nick) or current_sys_nick or "Unknown"
            if arch in ("jumpgate", "nomad_gate"):
                # Gate names are always directional: origin -> destination.
                ids_text = self._default_gate_connection_name(current_sys_disp, sys_disp)
            elif custom_ids_text:
                ids_text = custom_ids_text.replace("{system}", sys_disp)
            else:
                ids_text = self._default_jump_ids_name(arch, sys_disp)
            extras = [
                ("rotate", "0,0,0"),
                ("ids_name", "0"),
                ("ids_info", ("66145" if arch in ("jumpgate", "nomad_gate") else "66146") if has_ids_toolchain else "0"),
            ]
            if has_ids_toolchain:
                try:
                    ids_name_val = self._ensure_ids_name_in_user_dll("0", ids_text)
                    extras = self._entry_set(extras, "ids_name", ids_name_val)
                except Exception as exc:
                    QMessageBox.warning(self, tr("msg.save_error"), f"ids_name not written: {exc}")
            if arch in ("jumpgate", "nomad_gate"):
                info = self._pending_conn.get("gate_info", {}) or {}
                extras += [
                    ("behavior", info.get("behavior", "NOTHING")),
                    ("difficulty_level", str(info.get("difficulty", 1))),
                    ("loadout", info.get("loadout", "")),
                    ("pilot", info.get("pilot", "pilot_solar_hardest")),
                    ("reputation", info.get("reputation", "")),
                ]
            return extras

        if phase == "origin":
            nick = f"{orig}_to_{dest_nick}_{arch}"
            goto_str = f"{dest_nick}, {dest_nick}_to_{orig}_{arch}, gate_tunnel_bretonia"
            extras = _gate_extras(dest_nick)
            extras.append(("msg_id_prefix", f"gcs_refer_system_{dest_nick}"))
            _make_obj(nick, goto_str, extras)
            self._write_to_file(reload=False)
            if self._dirty:
                return
            self._preserve_active_system_tab_document()
            pending["phase"] = "destination"
            self._open_system_tab(dest_path, new_tab=True)
            self._pending_conn = pending
            self.browser.highlight_current(dest_path)
            self.statusBar().showMessage(tr("status.conn_origin_placed"))
            self._set_placement_mode(True, tr("placement.conn_dest"))
            self._preserve_active_system_tab_document()
        else:
            destnick = Path(self._filepath).stem.upper()
            nick = f"{destnick}_to_{orig}_{arch}"
            goto_str = f"{orig}, {orig}_to_{destnick}_{arch}, gate_tunnel_bretonia"
            extras = _gate_extras(orig)
            extras.append(("msg_id_prefix", f"gcs_refer_system_{orig}"))
            _make_obj(nick, goto_str, extras)
            self._write_to_file(reload=False)
            if self._dirty:
                return
            if hasattr(self, "save_conn_btn"):
                self.save_conn_btn.setVisible(False)
            if hasattr(self, "create_conn_btn"):
                self.create_conn_btn.setEnabled(True)
            origin_path = str(pending.get("origin", "") or "").strip()
            self._pending_conn = None
            self._set_placement_mode(False)
            self._preserve_active_system_tab_document()
            if origin_path and Path(origin_path).exists():
                self._open_system_tab(origin_path, new_tab=False)
                self.browser.highlight_current(origin_path)
            game_path = self._primary_game_path()
            if game_path:
                from .pathgen import regenerate_shortest_paths
                try:
                    msg = regenerate_shortest_paths(
                        game_path,
                        self._parser,
                        fallback_root=self._fallback_game_path(),
                    )
                    self.statusBar().showMessage(tr("status.connections_saved") + f" – {msg}")
                except Exception as ex:
                    self.statusBar().showMessage(tr("status.connections_saved") + f" ({ex})")
            else:
                self.statusBar().showMessage(tr("status.connections_saved"))
            self._set_placement_mode(False)

    # ==================================================================
    #  Löschen
    # ==================================================================
    def _delete_object(self):
        if self._flight_lock_active:
            return
        if self._multi_selected:
            targets = [it for it in self._multi_selected if isinstance(it, (SolarObject, ZoneItem))]
            self._clear_multi_selection()
            deleted = 0
            for it in list(targets):
                if isinstance(it, ZoneItem):
                    if it in self._zones:
                        self._delete_zone(it)
                        deleted += 1
                else:
                    if it in self._objects:
                        self._delete_solar_object(it)
                        deleted += 1
            if deleted:
                self.statusBar().showMessage(tr("status.multi_deleted").format(count=deleted))
            return
        if not self._selected:
            return
        obj = self._selected
        if isinstance(obj, ZoneItem):
            self._delete_zone(obj)
            return
        self._delete_solar_object(obj)

    def _delete_zone(self, zone: ZoneItem):
        z_idx = None
        try:
            z_idx = self._zones.index(zone)
        except ValueError:
            pass
        z_sec_idx = self._section_index_for_zone_index(z_idx) if z_idx is not None else None
        # --- 1) [Zone]-Sektion aus _sections entfernen ---
        if z_idx is not None:
            count = 0
            for i, (sec_name, entries) in enumerate(list(self._sections)):
                if sec_name.lower() == "zone":
                    if count == z_idx:
                        self._sections.pop(i)
                        break
                    count += 1

        # --- 2) Verknüpfte [Asteroids]/[Nebula]-Sektion + externe Datei entfernen ---
        zone_nick = zone.nickname.strip().lower()
        linked_sec_idx = None
        linked_section_name = None
        linked_section_entries = None
        linked_file_rel = ""
        linked_file_content = ""
        exclusion_linked_files: list[dict] = []
        exclusion_seen_files: set[str] = set()
        linked_exclusion_nicks: list[str] = []
        deleted_exclusion_zones: list[dict] = []
        for idx, (sec_name, entries) in enumerate(self._sections):
            if sec_name.lower() not in ("nebula", "asteroids"):
                continue
            zone_val = ""
            file_val = ""
            for k, v in entries:
                if k.lower() == "zone":
                    zone_val = v.strip().lower()
                elif k.lower() == "file":
                    file_val = v.strip()

            if file_val:
                file_key = file_val.strip().lower()
                if file_key not in exclusion_seen_files:
                    exclusion_seen_files.add(file_key)
                    game_path = self._primary_game_path()
                    linked_file = self._resolve_game_path_case_insensitive(game_path, file_val)
                    if linked_file and linked_file.is_file():
                        try:
                            original_text = self._read_text_best_effort(linked_file)
                        except Exception:
                            original_text = ""
                        if original_text:
                            patched_text, changed = patch_field_ini_remove_exclusion(original_text, zone.nickname)
                            if changed:
                                try:
                                    tmp = str(linked_file) + ".tmp"
                                    Path(tmp).write_text(patched_text, encoding="utf-8")
                                    shutil.move(tmp, linked_file)
                                    exclusion_linked_files.append({"rel": file_val, "content": original_text})
                                except Exception:
                                    pass
            if zone_val == zone_nick and linked_sec_idx is None:
                linked_sec_idx = idx
                linked_section_name = sec_name
                linked_section_entries = list(entries)
                for k, v in entries:
                    if k.lower() == "file":
                        linked_file_rel = v.strip()
                        break
                if linked_file_rel:
                    game_path = self._primary_game_path()
                    linked_file = self._resolve_game_path_case_insensitive(game_path, linked_file_rel)
                    if linked_file and linked_file.is_file():
                        try:
                            linked_file_content = self._read_text_best_effort(linked_file)
                        except Exception:
                            linked_file_content = ""
                        if linked_file_content:
                            linked_exclusion_nicks = self._parse_exclusion_nicks_from_field_ini(linked_file_content)
                    known_excl = {n.lower() for n in linked_exclusion_nicks}
                    prefix = f"{zone_nick}_exclusion_"
                    for z in self._zones:
                        zn = z.nickname.strip()
                        if zn.lower().startswith(prefix) and zn.lower() not in known_excl:
                            linked_exclusion_nicks.append(zn)
                            known_excl.add(zn.lower())

        if linked_exclusion_nicks:
            msg = QMessageBox(self)
            msg.setIcon(QMessageBox.Question)
            msg.setWindowTitle("Verknüpfte Exclusion-Zonen")
            msg.setText("Für dieses Asteroiden-/Nebel-Feld wurden Exclusion-Zonen gefunden.")
            msg.setInformativeText(
                "Sollen diese ebenfalls gelöscht werden?\n\n"
                + "\n".join(f"- {n}" for n in linked_exclusion_nicks)
            )
            msg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
            msg.setDefaultButton(QMessageBox.No)
            if msg.exec() == QMessageBox.Yes:
                for ex_nick in linked_exclusion_nicks:
                    removed = self._remove_zones_by_nickname(ex_nick)
                    if removed:
                        deleted_exclusion_zones.extend(removed)

        if linked_sec_idx is not None:
            self._sections.pop(linked_sec_idx)
        # Externe .ini-Datei löschen
        if linked_file_rel:
            game_path = self._primary_game_path()
            linked_file = self._resolve_game_path_case_insensitive(game_path, linked_file_rel)
            if linked_file and linked_file.is_file():
                try:
                    linked_file.unlink()
                except Exception as ex:
                    QMessageBox.warning(self, tr("msg.file_error"),
                                        tr("msg.file_delete_error").format(error=ex))

        if z_idx is not None:
            action = {
                "type": "delete_zone",
                "label": f"Zone gelöscht: {zone.nickname}",
                "filepath": self._filepath or "",
                "zone": {
                    "nickname": zone.nickname,
                    "entries": [list(p) for p in zone.data.get("_entries", [])],
                    "zone_index": int(z_idx),
                    "section_index": int(z_sec_idx) if z_sec_idx is not None else None,
                },
            }
            if linked_sec_idx is not None and linked_section_name and linked_section_entries:
                action["linked_section"] = {
                    "section_index": int(linked_sec_idx),
                    "name": linked_section_name,
                    "entries": [list(p) for p in linked_section_entries],
                }
            if linked_file_rel:
                action["linked_file"] = {
                    "rel": linked_file_rel,
                    "content": linked_file_content,
                }
            if exclusion_linked_files:
                action["exclusion_linked_files"] = exclusion_linked_files
            if deleted_exclusion_zones:
                action["deleted_exclusion_zones"] = deleted_exclusion_zones
            self._push_undo_action(action)

        self.view._scene.removeItem(zone)
        if zone in self._zones:
            self._zones.remove(zone)
        self._rebuild_object_combo()
        self._selected = None
        self._clear_selection_ui()
        self._hide_zone_extra_editors()
        self._set_dirty(True)
        self._write_to_file(reload=False)
        extra = ""
        if linked_sec_idx is not None:
            extra += tr("status.zone_extra_section")
        if linked_file_rel:
            extra += tr("status.zone_extra_linked")
        self.statusBar().showMessage(tr("status.zone_deleted").format(nickname=zone.nickname, extra=extra))
        self._refresh_3d_scene()

    def _delete_solar_object(self, obj: SolarObject):
        nick = obj.nickname.lower()
        arch = obj.data.get("archetype", "").lower()
        base_nick = obj.data.get("base", "").strip()

        if "planet" in arch and base_nick:
            has_dock_ring = any(
                o is not obj and o.data.get("dock_with", "").strip().lower() == base_nick.lower()
                for o in self._objects
            )
            if has_dock_ring:
                self._delete_base()
                return

        jump_kind = classify_jump_connection_kind(
            archetype=arch,
            msg_id_prefix=obj.data.get("msg_id_prefix", ""),
            reputation=obj.data.get("reputation", ""),
            jump_effect=obj.data.get("jump_effect", ""),
            goto_value=obj.data.get("goto", ""),
        )
        is_gate = jump_kind in ("gate", "alien_gate")
        is_hole = jump_kind == "hole"
        counterpart_nick = counterpart_file = counterpart_sys = None

        if is_gate or is_hole:
            goto_val = obj.data.get("goto", "").strip()
            if goto_val:
                tokens = [t.strip() for t in goto_val.split(",") if t.strip()]
                if len(tokens) >= 2:
                    counterpart_sys = tokens[0]
                    counterpart_nick = tokens[1]
                    try:
                        systems = self._find_all_systems(self._primary_game_path())
                        for sys_ in systems:
                            if sys_.get("nickname", "").upper() == counterpart_sys.upper():
                                counterpart_file = sys_.get("path")
                                break
                    except Exception:
                        pass

        msg = tr("msg.confirm_delete_text").format(nickname=obj.nickname)
        if counterpart_nick and counterpart_file:
            msg = tr("msg.confirm_delete_gate").format(
                nickname=obj.nickname, counterpart=counterpart_nick
            )
            if QMessageBox.warning(self, tr("msg.confirm_delete"), msg,
                                   QMessageBox.Ok | QMessageBox.Cancel) != QMessageBox.Ok:
                return
        elif counterpart_nick and not counterpart_file:
            err = tr("msg.counterpart_not_found_text").format(
                counterpart=counterpart_nick, system=counterpart_sys
            )
            if QMessageBox.question(self, tr("msg.counterpart_not_found"), err,
                                    QMessageBox.Yes | QMessageBox.No) != QMessageBox.Yes:
                return

        # Sektion entfernen
        obj_idx = None
        try:
            obj_idx = self._objects.index(obj)
        except ValueError:
            pass
        obj_sec_idx = self._section_index_for_object_index(obj_idx) if obj_idx is not None else None

        linked_zone_action = None
        if "sun" in arch or "planet" in arch:
            target_zone_nick = f"zone_{nick}_death"
            linked_zone = next(
                (z for z in self._zones if z.nickname.lower() == target_zone_nick), None
            )
            if linked_zone is not None:
                try:
                    lz_idx = self._zones.index(linked_zone)
                except ValueError:
                    lz_idx = None
                lz_sec_idx = self._section_index_for_zone_index(lz_idx) if lz_idx is not None else None
                linked_zone_action = {
                    "nickname": linked_zone.nickname,
                    "entries": [list(p) for p in linked_zone.data.get("_entries", [])],
                    "zone_index": int(lz_idx) if lz_idx is not None else None,
                    "section_index": int(lz_sec_idx) if lz_sec_idx is not None else None,
                }

        if obj_idx is not None:
            action = {
                "type": "delete_object",
                "label": f"Objekt gelöscht: {obj.nickname}",
                "filepath": self._filepath or "",
                "object": {
                    "nickname": obj.nickname,
                    "entries": [list(p) for p in obj.data.get("_entries", [])],
                    "object_index": int(obj_idx),
                    "section_index": int(obj_sec_idx) if obj_sec_idx is not None else None,
                },
            }
            if linked_zone_action:
                action["linked_zone"] = linked_zone_action
            self._push_undo_action(action)

        if obj_idx is not None:
            count = 0
            for i, (sec_name, entries) in enumerate(list(self._sections)):
                if sec_name.lower() == "object":
                    if count == obj_idx:
                        self._sections.pop(i)
                        break
                    count += 1
        self.view._scene.removeItem(obj)
        if obj in self._objects:
            self._objects.remove(obj)

        # Sonne/Planet → verknüpfte Death-Zone löschen
        if "sun" in arch or "planet" in arch:
            target_zone_nick = f"zone_{nick}_death"
            linked_zone = next(
                (z for z in self._zones if z.nickname.lower() == target_zone_nick), None
            )
            if linked_zone:
                z_idx = None
                try:
                    z_idx = self._zones.index(linked_zone)
                except ValueError:
                    pass
                if z_idx is not None:
                    count = 0
                    for i, (sec_name, entries) in enumerate(list(self._sections)):
                        if sec_name.lower() == "zone":
                            if count == z_idx:
                                self._sections.pop(i)
                                break
                            count += 1
                self.view._scene.removeItem(linked_zone)
                if linked_zone in self._zones:
                    self._zones.remove(linked_zone)

        self._rebuild_object_combo()
        self._selected = None
        self._clear_selection_ui()
        self._hide_zone_extra_editors()
        self._set_dirty(True)
        self._write_to_file(reload=False)
        if self._base_builder_active_base_nick:
            active = str(self._base_builder_active_base_nick).lower()
            if base_nick.strip().lower() == active or self._is_base_builder_child_object(obj, active):
                self._refresh_base_builder_dialog_parts()

        if counterpart_nick and counterpart_file:
            try:
                self._delete_counterpart(counterpart_file, counterpart_nick)
            except Exception as ex:
                QMessageBox.warning(self, tr("msg.counterpart_delete_error"),
                                    tr("msg.counterpart_delete_error_text").format(error=ex))
        self.statusBar().showMessage(tr("status.object_deleted").format(nickname=nick))
        self._refresh_3d_scene()

    def _delete_counterpart(self, filepath: str, nick_to_delete: str):
        filepath = str(self._ensure_writable_path(filepath))
        secs = self._parser.parse(filepath)
        objs = self._parser.get_objects(secs)
        obj_idx = -1
        for i, o in enumerate(objs):
            if o.get("nickname", "").lower() == nick_to_delete.lower():
                obj_idx = i
                break
        if obj_idx < 0:
            return
        obj_count = 0
        new_secs = []
        for sec_name, entries in secs:
            if sec_name.lower() == "object":
                if obj_count == obj_idx:
                    obj_count += 1
                    continue
                obj_count += 1
            new_secs.append((sec_name, entries))
        try:
            write_sections_to_file(filepath, new_secs)
        except Exception:
            try:
                write_text_atomic(filepath, serialize_sections_to_ini_text(new_secs))
            except Exception:
                pass

    # ==================================================================
    #  Änderungen übernehmen / Speichern
    # ==================================================================
    def _open_current_system_ini(self):
        if not self._filepath:
            QMessageBox.information(self, tr("msg.not_found"), tr("lbl.no_file"))
            return
        ini_path = Path(self._filepath)
        if not ini_path.is_file():
            QMessageBox.warning(self, tr("msg.not_found"), f"{tr('lbl.no_file')}\n{ini_path}")
            return
        self._open_ini_editor_view()
        item = self._ini_editor_find_tree_item_by_path(ini_path)
        if item is None:
            self._ini_editor_open_file_in_tab(str(ini_path), ensure_workspace=False)
            return
        if hasattr(self, "ini_tree"):
            self.ini_tree.setCurrentItem(item)
            self.ini_tree.scrollToItem(item)
        self._ini_editor_open_tree_item(item)

    def _apply(self):
        if not self._selected:
            return
        old_entries = [(str(k), str(v)) for k, v in self._selected.data.get("_entries", [])]
        old_nickname = str(getattr(self._selected, "nickname", ""))
        self._selected.apply_text(self.editor.toPlainText())
        if isinstance(self._selected, SolarObject) and self._selected.label:
            self._selected.label.setPlainText(self._object_display_label(self._selected))
        self._refresh_3d_scene(preserve_camera=True)

        if isinstance(self._selected, ZoneItem) and self._zone_link_section_index is not None:
            sec_name, sec_entries = self._text_to_section_entries(
                self.zone_link_editor.toPlainText(),
                self._zone_link_section_name or "Nebula",
            )
            if sec_entries:
                self._sections[self._zone_link_section_index] = (sec_name, sec_entries)
            if self._zone_link_file_path and self.zone_file_editor.isVisible():
                try:
                    persist_zone_link_file(
                        self._zone_link_file_path,
                        visible=self.zone_file_editor.isVisible(),
                        text=self.zone_file_editor.toPlainText(),
                    )
                except Exception as ex:
                    QMessageBox.warning(self, tr("msg.zone_file_error"),
                                        tr("msg.zone_file_error_text").format(error=ex))

        self.name_lbl.setText(f"📍 {self._object_display_label(self._selected)}")
        if isinstance(self._selected, SolarObject) and not hasattr(self._selected, "sys_path"):
            new_entries = [(str(k), str(v)) for k, v in self._selected.data.get("_entries", [])]
            if new_entries != old_entries:
                try:
                    obj_idx = self._objects.index(self._selected)
                except ValueError:
                    obj_idx = None
                self._push_undo_action(
                    {
                        "type": "edit_object",
                        "label": f"Objekt bearbeitet: {self._selected.nickname}",
                        "filepath": self._filepath or "",
                        "object_index": obj_idx,
                        "old_nickname": old_nickname,
                        "new_nickname": self._selected.nickname,
                        "old_entries": [list(p) for p in old_entries],
                        "new_entries": [list(p) for p in new_entries],
                    }
                )
                self._append_change_log(f"Objekt bearbeitet: {old_nickname} -> {self._selected.nickname}")
        self._set_dirty(True)
        selected_name = self._selected.nickname
        if isinstance(self._selected, SolarObject):
            selected_name = self._object_display_label(self._selected)
        self.statusBar().showMessage(
            tr("status.changes_applied").format(nickname=selected_name)
        )

    def _capture_selection_ref(self):
        if isinstance(self._selected, ZoneItem):
            return ("zone", self._selected.nickname)
        if isinstance(self._selected, SolarObject) and not hasattr(self._selected, "sys_path"):
            return ("obj", self._selected.nickname)
        return None

    def _restore_selection_ref(self, sel_ref):
        if not sel_ref:
            return
        kind, nick = sel_ref
        nick_low = str(nick).lower()
        if kind == "zone":
            for z in self._zones:
                if z.nickname.lower() == nick_low:
                    self._select_zone(z)
                    return
            return
        for o in self._objects:
            if o.nickname.lower() == nick_low:
                self._select(o)
                return

    def _write_to_file(self, reload: bool = True):
        if not self._filepath:
            # Universum-Ansicht: Positionen in universe.ini speichern
            self._save_universe_positions()
            return
        cam_state = None
        keep_cam = bool(
            hasattr(self, "view3d")
            and self.view3d_switch.isChecked()
            and hasattr(self.view3d, "get_camera_state")
        )
        if keep_cam:
            cam_state = self.view3d.get_camera_state()
        sel_ref = self._capture_selection_ref()
        if self._selected:
            self._selected.apply_text(self.editor.toPlainText())

        for obj in self._objects:
            new_pos = obj.fl_pos_str()
            obj.data["_entries"] = [
                (k, new_pos if k.lower() == "pos" else v) for k, v in obj.data["_entries"]
            ]

        saved_sections = build_saved_system_sections(
            self._sections,
            self._objects,
            self._zones,
            extract_nickname_from_entries=self._extract_nickname_from_entries,
        )

        target_path = str(self._ensure_writable_path(self._filepath))
        if target_path != self._filepath:
            self._filepath = target_path
        try:
            write_text_atomic(self._filepath, serialize_sections_to_ini_text(saved_sections))
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.save_error"), str(ex))
            return

        if reload:
            self.statusBar().showMessage(tr("status.saved_reloading"))
            self._load(self._filepath, restore=self._capture_2d_view_restore_state())
            self.browser.highlight_current(self._filepath)
            self._restore_selection_ref(sel_ref)
            if cam_state and hasattr(self.view3d, "set_camera_state"):
                self.view3d.set_camera_state(cam_state)
            self._preserve_active_system_tab_document()
        else:
            self._set_dirty(False)
            self._preserve_active_system_tab_document()
            self.statusBar().showMessage(f"{tr('status.saved')}  ({self._filepath})")

    def _on_universe_system_moved(self, obj: SolarObject):
        """Callback wenn ein System auf der Universumskarte verschoben wird."""
        if self._uni_multi_move_guard:
            obj._last_scene_pos = (obj.pos().x(), obj.pos().y())
            return

        moved_nodes: set[str] = {str(getattr(obj, "nickname", "") or "").upper()}
        group = [
            it for it in self._multi_selected
            if isinstance(it, SolarObject) and hasattr(it, "sys_path")
        ]
        if obj in group and len(group) > 1:
            prev = getattr(obj, "_last_scene_pos", None)
            if isinstance(prev, tuple) and len(prev) == 2:
                prev_x, prev_y = float(prev[0]), float(prev[1])
            else:
                start = getattr(obj, "_drag_start_scene_pos", None)
                if isinstance(start, QPointF):
                    prev_x, prev_y = start.x(), start.y()
                else:
                    prev_x, prev_y = obj.pos().x(), obj.pos().y()
            dx_scene = obj.pos().x() - prev_x
            dy_scene = obj.pos().y() - prev_y
            if abs(dx_scene) > 1e-6 or abs(dy_scene) > 1e-6:
                self._uni_multi_move_guard = True
                try:
                    for other in group:
                        if other is obj:
                            continue
                        moved_nodes.add(str(getattr(other, "nickname", "") or "").upper())
                        other.setPos(other.pos().x() + dx_scene, other.pos().y() + dy_scene)
                        other._last_scene_pos = (other.pos().x(), other.pos().y())
                finally:
                    self._uni_multi_move_guard = False
            obj._last_scene_pos = (obj.pos().x(), obj.pos().y())

        self._set_dirty(True)
        x = obj.pos().x() / self._scale
        y = obj.pos().y() / self._scale
        self.statusBar().showMessage(
            tr("status.system_position").format(
                nickname=self._system_display_name(obj.nickname), x=x, y=y
            )
        )
        self._update_universe_lines_for_nodes(moved_nodes)
        # Position im Editor aktualisieren
        if self._uni_selected_nick and self._uni_selected_nick.lower() == obj.nickname.lower():
            self._show_uni_system_editor(obj.nickname)

    def _show_uni_system_editor(self, nickname: str):
        """Zeigt den universe.ini-Eintrag für das gewählte System im Editor."""
        self._uni_selected_nick = nickname
        nick_lower = nickname.lower()
        ids_info_val = 0

        # Eintrag aus den geparsed sections finden
        text_lines = []
        for sec_name, entries in self._uni_sections:
            if sec_name.lower() == "system":
                sec_nick = None
                for k, v in entries:
                    if k.lower() == "nickname":
                        sec_nick = v.lower()
                        break
                if sec_nick == nick_lower:
                    for k, v in entries:
                        # Pos aus aktueller Szene nehmen
                        if k.lower() == "pos" and self._selected and hasattr(self._selected, "sys_path"):
                            sx = self._selected.pos().x() / self._scale
                            sy = self._selected.pos().y() / self._scale
                            text_lines.append(f"pos = {sx:.0f}, {sy:.0f}")
                        else:
                            text_lines.append(f"{k} = {v}")
                        if k.lower() == "ids_info":
                            ids_info_val = self._safe_int(v)
                    break

        self.uni_sys_lbl.setText(f"🌐 {self._system_display_name(nickname)}")
        self.uni_editor.setPlainText("\n".join(text_lines))
        self._update_uni_infocard_preview(ids_info_val)
        if hasattr(self, "left_stack"):
            self.left_stack.setCurrentWidget(self.left_uni_panel)

    def _resolve_infocard_xml_by_global_id(self, ids_info: int) -> str:
        gid = int(ids_info or 0)
        if gid <= 0:
            return ""
        slot = (gid >> 16) & 0xFFFF
        local_id = gid & 0xFFFF
        if local_id <= 0:
            return ""
        pairs = self._resource_dll_pairs_for_lookup()
        resolver = DllStringResolver()
        if 0 < slot <= len(pairs):
            ini_path, dll_name = pairs[slot - 1]
            dll_path = resolver._resolve_dll_path(Path(ini_path), str(dll_name))  # noqa: SLF001
            if dll_path and dll_path.is_file():
                infos = self._load_dll_html_resources(dll_path)
                return str(infos.get(local_id, "") or "")
        # Fallback für Legacy-/inkonsistente Slot-Zuordnung.
        for ini_path, dll_name in pairs:
            dll_path = resolver._resolve_dll_path(Path(ini_path), str(dll_name))  # noqa: SLF001
            if not dll_path or not dll_path.is_file():
                continue
            infos = self._load_dll_html_resources(dll_path)
            txt = str(infos.get(local_id, "") or "")
            if txt:
                return txt
        return ""

    def _update_uni_infocard_preview(self, ids_info: int):
        if not hasattr(self, "uni_infocard_preview"):
            return
        gid = int(ids_info or 0)
        if gid <= 0:
            self.uni_infocard_preview.setPlainText(tr("uni.infocard.none"))
            return
        raw_xml = self._resolve_infocard_xml_by_global_id(gid)
        if not raw_xml.strip():
            self.uni_infocard_preview.setPlainText(tr("uni.infocard.not_found").format(ids=gid))
            return
        try:
            self.uni_infocard_preview.setHtml(self._render_infocard_xml_to_html(raw_xml))
        except Exception:
            self.uni_infocard_preview.setPlainText(self._xml_to_plain_preview(raw_xml))

    def _apply_uni_system_edit(self):
        """Speichert den bearbeiteten universe.ini-Eintrag."""
        if not self._uni_selected_nick or not self._uni_ini_path:
            return

        nick_lower = self._uni_selected_nick.lower()
        new_text = self.uni_editor.toPlainText()

        # Neue Einträge parsen
        new_entries: list[tuple[str, str]] = []
        for line in new_text.splitlines():
            line = line.strip()
            if "=" in line:
                k, _, v = line.partition("=")
                new_entries.append((k.strip(), v.strip()))

        if not new_entries:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.no_valid_entries"))
            return

        # Sektionen aktualisieren
        updated = False
        for i, (sec_name, entries) in enumerate(self._uni_sections):
            if sec_name.lower() == "system":
                sec_nick = None
                for k, v in entries:
                    if k.lower() == "nickname":
                        sec_nick = v.lower()
                        break
                if sec_nick == nick_lower:
                    self._uni_sections[i] = (sec_name, new_entries)
                    updated = True
                    break

        if not updated:
            QMessageBox.warning(self, tr("msg.error"), tr("msg.system_not_found").format(nickname=self._uni_selected_nick))
            return

        try:
            write_sections_to_file(self._uni_ini_path, self._uni_sections)
            self.statusBar().showMessage(tr("status.uni_system_saved").format(nickname=self._uni_selected_nick))
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.save_error"), str(ex))

    def _update_universe_lines(self):
        """Aktualisiert alle Verbindungslinien nach Systemverschiebung."""
        pos_map, visible_map = self._universe_pos_visible_maps()
        for key, line_item in self._uni_lines:
            self._update_universe_line_item(key, line_item, pos_map, visible_map)

    def _universe_pos_visible_maps(self) -> tuple[dict[str, tuple[float, float]], dict[str, bool]]:
        pos_map: dict[str, tuple[float, float]] = {}
        visible_map: dict[str, bool] = {}
        for obj in self._objects:
            if hasattr(obj, "sys_path"):
                key = str(obj.nickname).upper()
                pos_map[key] = (obj.pos().x(), obj.pos().y())
                visible_map[key] = bool(obj.isVisible())
        return pos_map, visible_map

    def _update_universe_line_item(
        self,
        key: frozenset,
        line_item,
        pos_map: dict[str, tuple[float, float]],
        visible_map: dict[str, bool],
    ) -> None:
        nodes = list(key)
        if len(nodes) != 2:
            return
        a, b = nodes
        if a in pos_map and b in pos_map:
            ax, ay = pos_map[a]
            bx, by = pos_map[b]
            line_item.setLine(ax, ay, bx, by)
            base_visible = bool(visible_map.get(a, False) and visible_map.get(b, False))
            overlap_visible = self._is_overlap_endpoint_visible(a) and self._is_overlap_endpoint_visible(b)
            world_len = math.hypot(float(bx) - float(ax), float(by) - float(ay)) / max(self._scale, 1e-9)
            limit = float(getattr(self, "_uni_line_length_limit_world", 0.0) or 0.0)
            length_ok = True if limit <= 0.0 else (world_len <= limit)
            line_item.setVisible(base_visible and overlap_visible and length_ok)
            typ = str(getattr(self, "_uni_edges", {}).get(key, "")).strip().lower()
            if self._is_overlap_endpoint_red(a) or self._is_overlap_endpoint_red(b):
                col = QColor(255, 70, 70, 230)
                width = 2.4
            elif typ == "gate":
                col = self._scene_object_color("tradelane", 140)
                width = 1.8
            elif typ == "alien_gate":
                col = QColor(90, 230, 120, 220)
                width = 2.0
            else:
                col = self._scene_role_color("measure", 100)
                width = 1.2
            pen = QPen(col, width)
            pen.setCosmetic(True)
            line_item.setPen(pen)
        else:
            line_item.setVisible(False)

    def _update_universe_lines_for_nodes(self, node_keys: set[str] | list[str] | tuple[str, ...]):
        keys = {str(k or "").upper() for k in node_keys if str(k or "").strip()}
        if not keys:
            return
        if not self._uni_line_index:
            self._update_universe_lines()
            return
        pos_map, visible_map = self._universe_pos_visible_maps()
        done: set[int] = set()
        for key_name in keys:
            for edge_key, line_item in self._uni_line_index.get(key_name, []):
                line_id = id(line_item)
                if line_id in done:
                    continue
                done.add(line_id)
                self._update_universe_line_item(edge_key, line_item, pos_map, visible_map)

    def _undo_universe_moves(self):
        """Setzt alle Systeme auf ihre Originalpositionen zurück."""
        if self._flight_lock_active:
            return
        if not self._uni_original_pos:
            return
        for obj in self._objects:
            if hasattr(obj, "sys_path"):
                key = obj.nickname.upper()
                if key in self._uni_original_pos:
                    ox, oy = self._uni_original_pos[key]
                    obj.setPos(ox, oy)
        self._update_universe_lines()
        self._set_dirty(False)
        self.statusBar().showMessage(tr("status.undo_done"))

    def _save_universe_positions(self):
        """Speichert verschobene System-Positionen zurück in universe.ini."""
        game_path = self._primary_game_path()
        if not game_path:
            return
        uni_ini = self._find_universe_ini_write(game_path)
        if not uni_ini:
            return
        uni_ini = self._ensure_writable_path(uni_ini)

        # Aktuelle Positionen aus der Szene sammeln
        pos_map: dict[str, tuple[float, float]] = {}
        for obj in self._objects:
            if hasattr(obj, "sys_path"):
                x = obj.pos().x() / self._scale
                y = obj.pos().y() / self._scale
                pos_map[obj.nickname.lower()] = (x, y)

        if not pos_map:
            return

        sections = self._parser.parse(str(uni_ini))
        serialized = serialize_universe_sections_with_positions(sections, pos_map)

        try:
            write_text_atomic(uni_ini, serialized)
            self._set_dirty(False)
            self.statusBar().showMessage(tr("status.uni_positions_saved"))
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.save_error"), str(ex))

    @staticmethod
    def _extract_nickname_from_entries(entries) -> str | None:
        return extract_nickname_from_entries(entries)

    def _write_snapshot(self, snapshot):
        filepath, sections, objs = snapshot
        filepath = str(self._ensure_writable_path(filepath))
        serialized = serialize_snapshot_sections(sections, objs)
        try:
            write_text_atomic(filepath, serialized)
        except Exception as ex:
            QMessageBox.critical(self, tr("msg.save_error"), str(ex))

    def _save_pending_connections(self):
        origin_path = self._pending_snapshots[0][0] if self._pending_snapshots else None
        for snap in list(self._pending_snapshots):
            self._write_snapshot(snap)
        self._pending_snapshots.clear()
        self.save_conn_btn.setVisible(False)
        self.create_conn_btn.setEnabled(True)
        if origin_path and Path(origin_path).exists():
            self._load(origin_path, restore=self._capture_2d_view_restore_state())
            self.browser.highlight_current(origin_path)
        self._set_dirty(False)
        self._set_placement_mode(False)

        # Shortest-Path-Dateien neu generieren
        game_path = self._primary_game_path()
        if game_path:
            from .pathgen import regenerate_shortest_paths
            try:
                msg = regenerate_shortest_paths(
                    game_path,
                    self._parser,
                    fallback_root=self._fallback_game_path(),
                )
                self.statusBar().showMessage(tr("status.connections_saved") + f" – {msg}")
            except Exception as ex:
                self.statusBar().showMessage(tr("status.connections_saved") + f" ({ex})")
        else:
            self.statusBar().showMessage(tr("status.connections_saved"))

    # ==================================================================
    #  Dirty-Flag  &  Diverse Toggler
    # ==================================================================
    def _set_dirty(self, d: bool):
        self._dirty = d
        # Im Universe-Modus den Universe-Save-Button aktivieren
        is_universe = (
            self._filepath is None
            and hasattr(self, '_uni_save_action')
        )
        self.write_btn.setEnabled(bool(self._filepath) and d and not self._flight_lock_active)
        self._apply_write_button_state_style()
        if is_universe and hasattr(self, 'uni_save_btn'):
            self._uni_save_action.setVisible(d)
            self._uni_undo_action.setVisible(d)
        t = self.windowTitle()
        if d and not t.startswith("*"):
            self.setWindowTitle("* " + t)
        elif not d and t.startswith("* "):
            self.setWindowTitle(t[2:])
        self._center_update_current_system_tab_title()

    def _toggle_move(self, checked: bool):
        if self._flight_lock_active:
            return
        if self._filepath is None:
            self.view.set_left_drag_pan_enabled(not bool(checked))
        for obj in self._objects:
            obj.setFlag(QGraphicsItem.ItemIsMovable, checked)
        self.view3d.set_move_mode(checked)
        self._refresh_viewer_move_border()
        if not checked:
            self._clear_move_delta_indicator()
        self.statusBar().showMessage(
            tr("status.move_on")
            if checked else tr("status.move_off")
        )

    def _toggle_zones(self, checked: bool):
        self._cfg.set("view.show_zones", bool(checked))
        self._apply_group_visibility()
        self._refresh_3d_scene(preserve_camera=True)

    def _fit(self):
        r = QRectF()
        has_visible = False
        if self._filepath:
            reference_rect = QRectF(getattr(self.view, "_zoom_out_reference_rect", QRectF()))
            if reference_rect.isNull() or reference_rect.width() <= 0.0 or reference_rect.height() <= 0.0:
                reference_rect = self.view.sceneRect()
            if not reference_rect.isNull() and reference_rect.width() > 0.0 and reference_rect.height() > 0.0:
                self.view.fitInView(reference_rect, Qt.KeepAspectRatio)
                self._sync_zoom_slider_from_view(self.view.current_zoom_factor())
                return
        # In der Systemansicht Zonen beim Auto-Fit ignorieren, weil sie oft
        # deutlich groesser als die eigentlich spielrelevanten Objekte sind.
        fit_items = self.view._scene.items() if self._filepath is None else list(self._objects)
        for item in fit_items:
            if item is None or not item.isVisible():
                continue
            try:
                item_rect = item.mapToScene(item.boundingRect()).boundingRect()
            except Exception:
                continue
            if item_rect.isNull():
                continue
            r = item_rect if not has_visible else r.united(item_rect)
            has_visible = True
        if not has_visible:
            r = self.view._scene.itemsBoundingRect()
        pad = 80 if self._filepath else 60
        self.view.fitInView(r.adjusted(-pad, -pad, pad, pad), Qt.KeepAspectRatio)
        self._sync_zoom_slider_from_view(self.view.current_zoom_factor())

    # ==================================================================
    #  Quick-Editor-Optionen & System-Metadaten
    # ==================================================================
    def _populate_quick_editor_options(self, game_path: str | None = None):
        if game_path is None:
            game_path = self._primary_game_path()
        if not game_path:
            return
        # Fraktionen
        self.faction_cb.clear()
        iw_file = self._resolve_game_path_case_insensitive(game_path, "DATA/initialworld.ini")
        group_rows: list[tuple[str, str]] = []
        if iw_file and iw_file.exists():
            try:
                secs = self._parser.parse(str(iw_file))
                for name, entries in secs:
                    if name.lower() == "group":
                        nick = ""
                        ids_name = ""
                        for k, v in entries:
                            lk = k.lower()
                            if lk == "nickname":
                                nick = v.strip()
                            elif lk == "ids_name":
                                ids_name = v.strip()
                        if nick and all(nick.lower() != existing.lower() for existing, _ in group_rows):
                            group_rows.append((nick, ids_name))
            except Exception:
                pass
        group_rows.sort(key=lambda x: x[0].lower())
        self._build_faction_label_cache(group_rows)
        self.faction_cb.addItems(self._cached_faction_labels)

        # Loadouts
        self.loadout_cb.clear()
        loadouts: list[str] = []
        seen_loadouts: set[str] = set()

        def _add_loadout(raw: str):
            txt = str(raw or "").strip()
            if not txt:
                return
            key = txt.lower()
            if key in seen_loadouts:
                return
            seen_loadouts.add(key)
            loadouts.append(txt)

        def _collect_loadouts_from_ini(path: Path):
            if not path or not path.is_file():
                return
            try:
                secs = self._parser.parse(str(path))
            except Exception:
                return
            for name, entries in secs:
                if name.lower() != "loadout":
                    continue
                for k, v in entries:
                    if k.lower() == "nickname":
                        _add_loadout(v)

        roots: list[Path] = []
        primary = (game_path or self._primary_game_path() or "").strip()
        if primary:
            roots.append(Path(primary))
        fb = self._fallback_game_path().strip()
        if fb:
            fb_path = Path(fb)
            if fb_path not in roots:
                roots.append(fb_path)

        # Feste Standardpfade
        for base in roots:
            for rel in (
                "DATA/SOLAR/loadouts.ini",
                "DATA/SHIPS/loadouts.ini",
                "DATA/SHIPS/loadouts_special.ini",
            ):
                p = ci_resolve(base, rel)
                if p and p.is_file():
                    _collect_loadouts_from_ini(p)

            # Zusätzliche SHIPS-Loadout-Dateien (z.B. loadouts_*.ini)
            ships_dir = ci_resolve(base, "DATA/SHIPS")
            if ships_dir and ships_dir.is_dir():
                try:
                    for ini_file in ships_dir.glob("loadouts*.ini"):
                        if ini_file.is_file():
                            _collect_loadouts_from_ini(ini_file)
                except Exception:
                    pass

        # Bereits verwendete Loadouts aus System-Objekten ergänzen
        try:
            for s in self._find_all_systems(game_path):
                try:
                    secs = self._parser.parse(s["path"])
                except Exception:
                    continue
                for o in self._parser.get_objects(secs):
                    _add_loadout(o.get("loadout", ""))
        except Exception:
            pass

        loadouts.sort(key=str.lower)
        self.loadout_cb.addItems(loadouts)

        # Archetypen
        self.arch_cb.clear()
        archs: set[str] = set()
        try:
            systems = self._find_all_systems(game_path)
            for s in systems:
                try:
                    secs = self._parser.parse(s["path"])
                except Exception:
                    continue
                for o in self._parser.get_objects(secs):
                    a = o.get("archetype", "")
                    if a:
                        archs.add(a)
        except Exception:
            pass
        for item in sorted(archs, key=str.lower):
            self.arch_cb.addItem(item)

        # Stars
        self._stars = []
        star_file = self._resolve_game_path_case_insensitive(game_path, "DATA/SOLAR/stararch.ini")
        if star_file and star_file.exists():
            try:
                secs = self._parser.parse(str(star_file))
                for name, entries in secs:
                    if name.lower() == "star":
                        for k, v in entries:
                            if k.lower() == "nickname" and v not in self._stars:
                                self._stars.append(v)
            except Exception:
                pass
        self._stars.sort(key=str.lower)
        self._build_archetype_model_index(game_path)

    def _build_archetype_model_index(self, game_path: str):
        if not game_path:
            return
        if self._arch_index_game_path == game_path and self._arch_model_map:
            return
        self._arch_matlib_map = {}
        self._arch_model_map = build_archetype_model_index(
            game_path,
            resolve_game_path=self._resolve_game_path_case_insensitive,
            parse_ini=self._parser.parse,
            matlib_map=self._arch_matlib_map,
        )
        self._arch_index_game_path = game_path

    @staticmethod
    def _model_viewer_category_labels() -> dict[str, str]:
        return {
            "ships": "Ships",
            "stations": "Stations / Bases",
            "planets": "Planets",
            "suns": "Suns",
            "jump": "Jump Objects",
            "tradelanes": "Tradelanes / Rings",
            "weapons": "Weapons / Turrets",
            "equipment": "Equipment / Props",
            "asteroids": "Asteroids / Debris",
            "satellites": "Satellites / Buoys",
            "solars": "Other Solars",
            "misc": "Misc",
        }

    @staticmethod
    def _model_viewer_category_order() -> tuple[str, ...]:
        return (
            "ships",
            "stations",
            "planets",
            "suns",
            "jump",
            "tradelanes",
            "weapons",
            "equipment",
            "asteroids",
            "satellites",
            "solars",
            "misc",
        )

    def _categorize_model_viewer_entry(
        self,
        *,
        source_ini_path: Path,
        section_name: str,
        nickname: str,
        da_archetype: str,
        type_value: str,
    ) -> str:
        source_name = source_ini_path.name.lower()
        nick = nickname.lower()
        da_arch = da_archetype.lower()
        section = section_name.lower()
        type_l = type_value.lower()
        text = " ".join((source_name, section, nick, da_arch, type_l))
        if "shiparch" in source_name:
            return "ships"
        if any(token in text for token in ("planet", "moon")):
            return "planets"
        if "sun" in text or type_l == "star":
            return "suns"
        if any(token in text for token in ("jumpgate", "jump_gate", "jumphole", "jump_hole", "nomad_gate")):
            return "jump"
        if any(token in text for token in ("tradelane", "trade_lane", "lane_ring", "lane_segment")):
            return "tradelanes"
        if source_name == "asteroidarch.ini" or any(token in text for token in ("asteroid", "debris", "mineable", "rock")):
            return "asteroids"
        if (
            type_l == "station"
            or any(token in text for token in ("station", "outpost", "shipyard", "dock_ring", "_base", "space_"))
        ):
            return "stations"
        if any(token in text for token in ("satellite", "buoy", "nav", "relay", "comm_")):
            return "satellites"
        if source_name.endswith("_equip.ini") or source_name == "weapon_equip.ini":
            if any(token in text for token in ("weapon", "turret", "gun", "missile", "mine", "torpedo", "launcher", "tesla", "blaster", "cannon")):
                return "weapons"
            return "equipment"
        if "weapon" in text or "turret" in text or section in {"gun", "munition"}:
            return "weapons"
        if source_name in {"solararch.ini", "stationarch.ini"}:
            return "solars"
        return "misc"

    @staticmethod
    def _model_viewer_render_label(model_path: Path) -> tuple[str, Path | None]:
        resolution = resolve_preview_mesh_candidate(model_path)
        if resolution.kind == "direct_renderable":
            return "Direct Mesh", resolution.preview_path
        if resolution.kind == "alternate_renderable":
            return "Alt Preview Mesh", resolution.preview_path
        if resolution.kind == "freelancer_native":
            return "Freelancer Native", resolution.preview_path
        if resolution.kind == "freelancer_primitive":
            return "Freelancer Primitive", resolution.preview_path
        return "Unrenderable", resolution.preview_path

    def _collect_3d_model_viewer_entries(self) -> list[ModelViewerEntry]:
        game_path = self._primary_game_path()
        if not game_path:
            return []
        self._build_archetype_model_index(game_path)
        labels = self._model_viewer_category_labels()
        order = {key: index for index, key in enumerate(self._model_viewer_category_order())}
        ini_paths: list[Path] = []
        seen_ini_paths: set[str] = set()
        for rel in (
            "DATA/SOLAR/solararch.ini",
            "DATA/SHIPS/shiparch.ini",
            "DATA/EQUIPMENT/stationarch.ini",
            "DATA/EQUIPMENT/asteroidarch.ini",
        ):
            ini_path = self._resolve_game_path_case_insensitive(game_path, rel)
            if ini_path is None or not ini_path.exists():
                continue
            ini_key = str(ini_path).lower()
            if ini_key in seen_ini_paths:
                continue
            seen_ini_paths.add(ini_key)
            ini_paths.append(ini_path)
        for ini_path in self._iter_equipment_ini_paths_for_usage(game_path):
            ini_key = str(ini_path).lower()
            if ini_key in seen_ini_paths:
                continue
            seen_ini_paths.add(ini_key)
            ini_paths.append(ini_path)

        entries: list[ModelViewerEntry] = []
        seen_entries: set[tuple[str, str]] = set()
        for ini_path in ini_paths:
            try:
                sections = self._parser.parse(str(ini_path))
            except Exception:
                continue
            for section_name, section_entries in sections:
                nickname = self._entry_get_value(section_entries, "nickname").strip()
                da_archetype = self._entry_get_value(section_entries, "da_archetype").strip()
                if not nickname or not da_archetype:
                    continue
                model_path = self._resolve_game_path_case_insensitive(game_path, da_archetype)
                if model_path is None or not model_path.exists():
                    continue
                entry_key = (nickname.lower(), str(model_path).lower())
                if entry_key in seen_entries:
                    continue
                seen_entries.add(entry_key)
                ids_name = (
                    self._entry_get_value(section_entries, "ids_name").strip()
                    or self._entry_get_value(section_entries, "strid_name").strip()
                )
                display_name = self._display_name_from_ids_name(ids_name).strip() if ids_name else ""
                type_value = self._entry_get_value(section_entries, "type").strip()
                category_key = self._categorize_model_viewer_entry(
                    source_ini_path=ini_path,
                    section_name=str(section_name or ""),
                    nickname=nickname,
                    da_archetype=da_archetype,
                    type_value=type_value,
                )
                render_kind, preview_path = self._model_viewer_render_label(model_path)
                material_library_paths: list[Path] = []
                for raw_mat in self._arch_matlib_map.get(nickname.lower(), ()):
                    rel_mat = str(raw_mat or "").replace("\\", "/").strip().lstrip("/")
                    if not rel_mat:
                        continue
                    if not rel_mat.lower().startswith("data/"):
                        rel_mat = f"DATA/{rel_mat}"
                    mat_path = self._resolve_game_path_case_insensitive(game_path, rel_mat)
                    if mat_path is not None and mat_path.exists():
                        material_library_paths.append(mat_path)
                ring = self._entry_get_value(section_entries, "ring").strip()
                atmosphere_range = self._entry_get_value(section_entries, "atmosphere_range").strip()
                burn_color = self._entry_get_value(section_entries, "burn_color").strip()
                entries.append(
                    ModelViewerEntry(
                        category_key=category_key,
                        category_label=labels.get(category_key, category_key),
                        nickname=nickname,
                        display_name=display_name,
                        archetype=nickname,
                        da_archetype=da_archetype,
                        model_path=model_path,
                        source_ini_path=ini_path,
                        source_section=str(section_name or ""),
                        ids_name=ids_name,
                        type_value=type_value,
                        render_kind=render_kind,
                        preview_path=preview_path,
                        material_library_paths=tuple(material_library_paths),
                        ring=ring,
                        atmosphere_range=atmosphere_range,
                        burn_color=burn_color,
                    )
                )
        entries.sort(
            key=lambda entry: (
                order.get(entry.category_key, 999),
                (entry.display_name or entry.nickname).lower(),
                entry.nickname.lower(),
            )
        )
        return entries

    def _base_archetypes_from_solararch(self, game_path: str) -> list[str]:
        """Return base-capable archetypes from solararch only (no system-INI heuristics)."""
        if not game_path:
            return []
        if self._base_arch_cache_game_path == game_path and self._base_arch_cache:
            return list(self._base_arch_cache)
        solararch = self._resolve_game_path_case_insensitive(game_path, "DATA/SOLAR/solararch.ini")
        if not solararch or not solararch.exists():
            self._base_arch_cache = []
            self._base_arch_default_loadouts = {}
            self._base_arch_cache_game_path = game_path
            return []
        seen: set[str] = set()
        result: list[str] = []
        default_loadouts: dict[str, str] = {}
        try:
            secs = self._parser.parse(str(solararch))
        except Exception:
            self._base_arch_cache = []
            self._base_arch_default_loadouts = {}
            self._base_arch_cache_game_path = game_path
            return []
        for sec_name, entries in secs:
            if str(sec_name).strip().lower() != "solar":
                continue
            nick = ""
            typ = ""
            loadout = ""
            for k, v in entries:
                lk = str(k).strip().lower()
                if lk == "nickname":
                    nick = str(v).strip()
                elif lk == "type":
                    typ = str(v).strip().lower()
                elif lk == "loadout":
                    loadout = str(v).strip()
            if not nick or typ != "station":
                continue
            key = nick.lower()
            if key in seen:
                continue
            seen.add(key)
            result.append(nick)
            if loadout:
                default_loadouts[key] = loadout
        result.sort(key=str.lower)
        self._base_arch_cache = result
        self._base_arch_default_loadouts = default_loadouts
        self._base_arch_cache_game_path = game_path
        return list(result)

    def _base_default_loadouts_from_solararch(self, game_path: str) -> dict[str, str]:
        self._base_archetypes_from_solararch(game_path)
        return dict(self._base_arch_default_loadouts)

    def _is_known_archetype(self, game_path: str, archetype: str) -> bool:
        arch = str(archetype or "").strip().lower()
        if not arch:
            return False
        self._build_archetype_model_index(game_path)
        return arch in self._arch_model_map

    def _normalize_base_archetype(self, game_path: str, archetype: str) -> tuple[str, bool]:
        """Returns (archetype, changed) with a safe fallback for invalid values."""
        raw = str(archetype or "").strip()
        if raw and self._is_known_archetype(game_path, raw):
            return raw, False
        for cand in ("largestation1", "smallstation1", "outpost"):
            if self._is_known_archetype(game_path, cand):
                return cand, True
        return (raw or "outpost"), True

    def _resolve_game_path_case_insensitive(self, game_path: str, rel_path: str) -> Path | None:
        if not rel_path:
            return None
        roots: list[Path] = []
        primary = (game_path or self._primary_game_path() or "").strip()
        if primary:
            roots.append(Path(primary))
        fb = self._fallback_game_path().strip()
        if fb:
            roots.append(Path(fb))
        for base in roots:
            hit = ci_resolve(base, rel_path)
            if hit:
                return hit
            data_dir = ci_find(base, "DATA")
            if data_dir and data_dir.is_dir():
                hit = ci_resolve(data_dir, rel_path)
                if hit:
                    return hit
        return None

    def _resolve_data_subdir_case_insensitive(self, game_path: str, rel_subdir: str) -> Path | None:
        rel = str(rel_subdir or "").replace("\\", "/").strip().strip("/")
        if not rel:
            return None
        parts = [p for p in rel.split("/") if p]
        roots: list[Path] = []
        primary = (game_path or self._primary_game_path() or "").strip()
        if primary:
            roots.append(Path(primary))
        fb = self._fallback_game_path().strip()
        if fb:
            fb_path = Path(fb)
            if fb_path not in roots:
                roots.append(fb_path)
        for base in roots:
            data_dir = ci_find(base, "DATA")
            if not data_dir or not data_dir.is_dir():
                continue
            cur = data_dir
            ok = True
            for seg in parts:
                nxt = ci_find(cur, seg)
                if not nxt or not nxt.is_dir():
                    ok = False
                    break
                cur = nxt
            if ok and cur.is_dir():
                return cur
        return None

    def _target_game_path_for_rel(self, game_path: str, rel_path: str) -> Path | None:
        """Resolve existing file case-insensitively; otherwise build target under DATA/."""
        if not rel_path:
            return None
        target_root = (self._primary_game_path() if self._is_overlay_mode() else game_path) or self._primary_game_path()
        if not target_root:
            return None
        base = Path(target_root)
        rel = rel_path.replace("\\", "/").strip().lstrip("/")
        if not rel:
            return None
        data_dir = ci_find(base, "DATA")
        if data_dir is None:
            data_dir = base / "DATA"
        if rel.lower().startswith("data/"):
            rel = rel.split("/", 1)[1] if "/" in rel else ""
            if not rel:
                return data_dir

        # Reuse existing directory components case-insensitively to avoid
        # creating duplicate folders like NEBULA/nebula on Linux.
        parts = [p for p in rel.split("/") if p]
        if not parts:
            return data_dir
        cur = data_dir
        for seg in parts[:-1]:
            hit = ci_find(cur, seg)
            if hit and hit.is_dir():
                cur = hit
            else:
                nxt = cur / seg
                try:
                    nxt.mkdir(parents=True, exist_ok=True)
                except Exception:
                    pass
                cur = nxt
        target = cur / parts[-1]
        if target.exists():
            return target
        src = self._resolve_game_path_case_insensitive(game_path, rel_path)
        if src is not None and src.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            try:
                shutil.copy2(src, target)
            except Exception:
                pass
        return target

    def _resolve_model_for_archetype(self, archetype: str, game_path: str) -> tuple[Path | None, str | None]:
        if not archetype:
            return None, None
        self._build_archetype_model_index(game_path)
        resolved = resolve_archetype_model(
            archetype=archetype,
            game_path=game_path,
            arch_map=self._arch_model_map,
            resolve_game_path=self._resolve_game_path_case_insensitive,
        )
        return resolved.model_path, resolved.da_archetype

    def _resolve_material_library_paths(self, archetype: str, game_path: str) -> tuple[Path, ...]:
        if not archetype or not game_path:
            return ()
        self._build_archetype_model_index(game_path)
        rel_paths = self._arch_matlib_map.get(archetype.lower(), ())
        if not rel_paths:
            return ()
        resolved: list[Path] = []
        for rel in rel_paths:
            abs_path = self._resolve_game_path_case_insensitive(game_path, f"DATA/{rel}")
            if abs_path is not None and abs_path.exists():
                resolved.append(abs_path)
        return tuple(resolved)

    @staticmethod
    def _path_is_within_root(path: Path | None, root: str) -> bool:
        if path is None or not root:
            return False
        try:
            path.resolve().relative_to(Path(root).resolve())
            return True
        except Exception:
            return False

    def _top_view_icon_profile_key_for_model_path(self, model_path: Path) -> str:
        fallback_root = str(self._fallback_game_path() or "").strip()
        primary_root = str(self._primary_game_path() or "").strip()
        if fallback_root and self._path_is_within_root(model_path, fallback_root):
            root_key = fallback_root
            profile_kind = "vanilla"
        elif primary_root and self._path_is_within_root(model_path, primary_root):
            root_key = primary_root
            profile_kind = "mod"
        else:
            root_key = primary_root or fallback_root or ""
            profile_kind = "vanilla"
        root_hash = hashlib.sha1(root_key.lower().encode("utf-8", errors="ignore")).hexdigest()[:12]
        return f"{profile_kind}-{root_hash}"

    def _mod_settings_top_view_icons_mod_content_enabled(self, profile: dict | None = None) -> bool:
        prof = profile if isinstance(profile, dict) else self._mod_manager_editing_profile()
        if not isinstance(prof, dict):
            return bool(self._cfg.get("view.top_view_icons.mod_content_enabled", False))
        cfg = self._mod_settings_read_profile_config(prof)
        if "top_view_icons_mod_content_enabled" in cfg:
            return bool(cfg.get("top_view_icons_mod_content_enabled", False))
        legacy = bool(self._cfg.get("view.top_view_icons.mod_content_enabled", False))
        if legacy:
            cfg["top_view_icons_mod_content_enabled"] = True
            try:
                self._mod_settings_write_profile_config(cfg, prof)
            except Exception:
                pass
            self._cfg.set("view.top_view_icons.mod_content_enabled", False)
        return legacy

    def _top_view_icons_allowed_for_model_path(self, model_path: Path) -> bool:
        fallback_root = str(self._fallback_game_path() or "").strip()
        primary_root = str(self._primary_game_path() or "").strip()
        if fallback_root and self._path_is_within_root(model_path, fallback_root):
            return True
        if fallback_root and primary_root and self._path_is_within_root(model_path, primary_root):
            return bool(self._mod_settings_top_view_icons_mod_content_enabled())
        return True

    def _top_view_icon_cache_path_for_object(self, obj) -> Path | None:
        if obj is None:
            return None
        archetype = str(getattr(obj, "data", {}).get("archetype", "") or "").strip()
        if not archetype:
            return None
        game_path = self._primary_game_path()
        if not game_path:
            return None
        lowered_arch = archetype.lower()
        if "planet" in lowered_arch:
            texture_path = self._resolve_planet_texture_for_object(obj)
            if texture_path is None:
                return None
            return top_view_icon_cache_path(
                profile_key=self._top_view_icon_profile_key_for_model_path(texture_path),
                archetype=archetype,
                model_path=texture_path,
            )
        model_path = self._native_model_path_for_archetype_cached(archetype, game_path)
        if model_path is None or not self._top_view_icons_allowed_for_model_path(model_path):
            return None
        preview_resolution = resolve_preview_mesh_candidate(model_path)
        if not preview_resolution.is_freelancer_native:
            return None
        return top_view_icon_cache_path(
            profile_key=self._top_view_icon_profile_key_for_model_path(model_path),
            archetype=archetype,
            model_path=model_path,
        )

    def _resolve_top_view_icon_for_object(self, obj) -> QPixmap | None:
        if obj is None:
            return None
        archetype = str(getattr(obj, "data", {}).get("archetype", "") or "").strip().lower()
        if not archetype or "sun" in archetype or "star" in archetype:
            return None
        cache_path = self._top_view_icon_cache_path_for_object(obj)
        if cache_path is None:
            return None
        cache_key = str(cache_path)
        if hasattr(obj, "set_model_world_radius"):
            cached_radius = self._top_view_icon_radius_cache.get(cache_key)
            if cached_radius is not None:
                try:
                    obj.set_model_world_radius(float(cached_radius))
                except Exception:
                    pass
        cached_pixmap = self._top_view_icon_pixmap_cache.get(cache_key)
        if cached_pixmap is not None and not cached_pixmap.isNull():
            return cached_pixmap
        disk_pixmap = load_cached_top_view_icon(cache_path)
        if "planet" in archetype:
            if disk_pixmap is not None:
                self._top_view_icon_pixmap_cache[cache_key] = disk_pixmap
                return disk_pixmap
            image = render_planet_texture_top_view_icon(
                self._resolve_planet_texture_for_object(obj),
                cloud_texture_path=self._resolve_planet_cloud_texture_for_object(obj),
            )
            if image is None or image.isNull():
                return None
            save_top_view_icon(cache_path, image)
            pixmap = QPixmap.fromImage(image)
            if pixmap.isNull():
                return None
            self._top_view_icon_pixmap_cache[cache_key] = pixmap
            return pixmap
        scene_data = self._resolve_system_view_native_scene_data_for_object(obj)
        if scene_data is None or not getattr(scene_data, "geometries", ()):
            if disk_pixmap is not None:
                self._top_view_icon_pixmap_cache[cache_key] = disk_pixmap
                return disk_pixmap
            return None
        bounds = getattr(scene_data, "bounds", None)
        radius_value = float(getattr(bounds, "radius", 0.0) or 0.0)
        if radius_value > 0.0:
            scene_radius = radius_value * max(float(getattr(obj, "_scale", 1.0) or 1.0), 1e-6)
            self._top_view_icon_radius_cache[cache_key] = scene_radius
            if hasattr(obj, "set_model_world_radius"):
                try:
                    obj.set_model_world_radius(scene_radius)
                except Exception:
                    pass
        if disk_pixmap is not None:
            self._top_view_icon_pixmap_cache[cache_key] = disk_pixmap
            return disk_pixmap
        transform_state = native_detail_transform_state(
            nickname=str(getattr(obj, "nickname", "") or ""),
            archetype=str(getattr(obj, "data", {}).get("archetype", "") or ""),
            bounds=getattr(scene_data, "bounds", None),
            label_y_offset=3.8,
            scene_scale=1.0,
            cmp_up_correction_euler_deg=tuple(
                getattr(scene_data, "cmp_up_correction_euler_deg", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0)
            ),
        )
        image = render_native_scene_top_view_icon(
            scene_data,
            rotate_euler_deg=tuple(transform_state.get("rotate_euler_deg", (0.0, 0.0, 0.0))),
        )
        if image is None or image.isNull():
            return None
        save_top_view_icon(cache_path, image)
        pixmap = QPixmap.fromImage(image)
        if pixmap.isNull():
            return None
        self._top_view_icon_pixmap_cache[cache_key] = pixmap
        return pixmap

    def _refresh_all_top_view_icons(self) -> None:
        for obj in list(getattr(self, "_objects", []) or []):
            try:
                obj.refresh_top_view_icon()
            except Exception:
                pass

    def _queue_top_view_icon_refresh(self, objects: list[object] | tuple[object, ...] | None = None) -> None:
        candidates = list(objects if objects is not None else (getattr(self, "_objects", []) or []))
        if not candidates:
            return
        for obj in candidates:
            if obj is None:
                continue
            key = id(obj)
            if key in self._top_view_icon_refresh_seen:
                continue
            self._top_view_icon_refresh_seen.add(key)
            self._top_view_icon_refresh_queue.append(obj)
        if not self._top_view_icon_refresh_queue:
            return
        if self._top_view_icon_refresh_total <= 0:
            self._top_view_icon_refresh_total = len(self._top_view_icon_refresh_queue)
            self._top_view_icon_refresh_done = 0
            self.statusBar().showMessage(f"Preparing 2D icons... 0/{self._top_view_icon_refresh_total}")
        if self._top_view_icon_refresh_timer is None:
            self._top_view_icon_refresh_timer = QTimer(self)
            self._top_view_icon_refresh_timer.setInterval(0)
            self._top_view_icon_refresh_timer.timeout.connect(self._process_top_view_icon_refresh_batch)
        if not self._top_view_icon_refresh_timer.isActive():
            self._top_view_icon_refresh_timer.start()

    def _process_top_view_icon_refresh_batch(self) -> None:
        timer = self._top_view_icon_refresh_timer
        if timer is None:
            return
        processed = 0
        while self._top_view_icon_refresh_queue and processed < max(1, int(self._top_view_icon_refresh_batch_size)):
            obj = self._top_view_icon_refresh_queue.pop(0)
            try:
                obj.refresh_top_view_icon()
            except Exception:
                pass
            self._top_view_icon_refresh_seen.discard(id(obj))
            self._top_view_icon_refresh_done += 1
            processed += 1
        total = max(self._top_view_icon_refresh_total, self._top_view_icon_refresh_done)
        if self._top_view_icon_refresh_queue:
            self.statusBar().showMessage(
                f"Preparing 2D icons... {self._top_view_icon_refresh_done}/{max(1, total)}"
            )
            timer.start()
            return
        timer.stop()
        if total > 0:
            self.statusBar().showMessage(f"2D icons ready ({self._top_view_icon_refresh_done}/{total})")
        self._top_view_icon_refresh_total = 0
        self._top_view_icon_refresh_done = 0

    def _refresh_top_view_icons_for_model_path(self, model_path: Path | None) -> None:
        if model_path is None:
            return
        for obj in list(getattr(self, "_objects", []) or []):
            try:
                obj_model_path = self._native_model_path_for_object(obj)
            except Exception:
                obj_model_path = None
            if obj_model_path != model_path:
                continue
            try:
                obj.refresh_top_view_icon()
            except Exception:
                pass

    def _resolve_planet_texture_for_object(self, obj) -> Path | None:
        if obj is None:
            return None
        archetype = str(getattr(obj, "data", {}).get("archetype", "") or "").strip()
        if not archetype or "planet" not in archetype.lower():
            return None
        game_path = self._primary_game_path()
        if not game_path:
            return None
        cache = getattr(self, "_planet_texture_cache", None)
        if cache is None:
            cache = {}
            self._planet_texture_cache = cache
        cache_key = f"{game_path.lower()}::{archetype.lower()}"
        if cache_key in cache:
            cached_path = cache[cache_key]
            cached_name = Path(cached_path).stem if isinstance(cached_path, Path) else str(cached_path or "")
            if not _is_planet_cap_texture_name(cached_name):
                return cached_path
        mat_paths = self._resolve_material_library_paths(archetype, game_path)
        texture_path = None
        if mat_paths:
            textures = extract_all_mat_textures(mat_paths)
            texture_path = find_mat_texture_for_planet_archetype(archetype, textures)
            if texture_path is None:
                texture_path = find_best_mat_texture_for_planet_surface(textures)
            if texture_path is None:
                texture_path = find_best_mat_texture(textures)
        cache[cache_key] = texture_path
        return texture_path

    def _resolve_planet_cloud_texture_for_object(self, obj) -> Path | None:
        if obj is None:
            return None
        archetype = str(getattr(obj, "data", {}).get("archetype", "") or "").strip()
        if not archetype or "planet" not in archetype.lower():
            return None
        game_path = self._primary_game_path()
        if not game_path:
            return None
        cache = getattr(self, "_planet_cloud_texture_cache", None)
        if cache is None:
            cache = {}
            self._planet_cloud_texture_cache = cache
        cache_key = f"{game_path.lower()}::{archetype.lower()}"
        if cache_key in cache:
            return cache[cache_key]
        mat_paths = self._resolve_material_library_paths(archetype, game_path)
        texture_path = None
        if mat_paths:
            textures = extract_all_mat_textures(mat_paths)
            texture_path = find_mat_texture_for_planet_clouds(archetype, textures)
        cache[cache_key] = texture_path
        return texture_path

    def _resolve_planet_ring_render_info_for_object(self, obj) -> dict[str, object] | None:
        if obj is None:
            return None
        ring_rel = str(getattr(obj, "data", {}).get("ring", "") or "").strip()
        archetype = str(getattr(obj, "data", {}).get("archetype", "") or "").strip()
        if not ring_rel or not archetype or "planet" not in archetype.lower():
            return None
        game_path = self._primary_game_path()
        if not game_path:
            return None
        cache = getattr(self, "_planet_ring_render_cache", None)
        if cache is None:
            cache = {}
            self._planet_ring_render_cache = cache
        cache_key = f"{game_path.lower()}::{archetype.lower()}::{ring_rel.lower()}"
        if cache_key in cache:
            return cache[cache_key]

        rel = ring_rel.replace("\\", "/").strip().lstrip("/")
        if "," in rel:
            parts = [part.strip().lstrip("/") for part in rel.split(",") if part.strip()]
            ring_path_candidates = [
                part for part in parts
                if "/" in part or part.lower().endswith(".ini")
            ]
            if ring_path_candidates:
                rel = ring_path_candidates[-1]
            elif parts:
                rel = parts[-1]
        if not rel.lower().startswith("data/"):
            rel = f"DATA/{rel}"
        ring_ini_path = self._resolve_game_path_case_insensitive(game_path, rel)
        if ring_ini_path is None or not ring_ini_path.exists():
            cache[cache_key] = None
            return None

        direct_texture: Path | None = None
        mat_paths: list[Path] = []
        inner_radius: float | None = None
        outer_radius: float | None = None
        rotate_xyz: tuple[float, float, float] | None = None
        zone_nickname = None
        if "," in ring_rel:
            parts = [part.strip() for part in ring_rel.split(",") if part.strip()]
            if parts:
                first = parts[0]
                if "/" not in first and "\\" not in first and not first.lower().endswith(".ini"):
                    zone_nickname = first.lower()
        if zone_nickname:
            for sec_name, entries in list(getattr(self, "_sections", []) or []):
                if str(sec_name or "").strip().lower() != "zone":
                    continue
                sec_nick = ""
                sec_rotate = ""
                for key, value in entries:
                    key_l = str(key or "").strip().lower()
                    if key_l == "nickname":
                        sec_nick = str(value or "").strip().lower()
                    elif key_l == "rotate":
                        sec_rotate = str(value or "").strip()
                if sec_nick != zone_nickname:
                    continue
                parts = [part.strip() for part in sec_rotate.split(",")] if sec_rotate else []
                try:
                    rotate_xyz = tuple(float(parts[index]) if index < len(parts) else 0.0 for index in range(3))
                except Exception:
                    rotate_xyz = None
                break
        try:
            sections = self._parser.parse(str(ring_ini_path))
        except Exception:
            sections = []
        for _sec_name, entries in sections:
            for key, value in entries:
                key_l = str(key or "").strip().lower()
                value_s = str(value or "").strip()
                if not value_s:
                    continue
                if key_l == "material_library":
                    rel_mat = value_s.replace("\\", "/").strip().lstrip("/")
                    if not rel_mat.lower().startswith("data/"):
                        rel_mat = f"DATA/{rel_mat}"
                    mat_path = self._resolve_game_path_case_insensitive(game_path, rel_mat)
                    if mat_path is not None and mat_path.exists():
                        mat_paths.append(mat_path)
                elif key_l in {"texture", "texname", "diffuse", "diffuse_texture"}:
                    rel_tex = value_s.replace("\\", "/").strip().lstrip("/")
                    if not rel_tex.lower().startswith("data/"):
                        rel_tex = f"DATA/{rel_tex}"
                    tex_path = self._resolve_game_path_case_insensitive(game_path, rel_tex)
                    if tex_path is not None and tex_path.exists():
                        direct_texture = tex_path
                elif key_l in {"inner_radius", "radius_inner", "min_radius"}:
                    try:
                        inner_radius = float(value_s)
                    except Exception:
                        pass
                elif key_l in {"outer_radius", "radius_outer", "max_radius"}:
                    try:
                        outer_radius = float(value_s)
                    except Exception:
                        pass

        texture_path = direct_texture
        if texture_path is None and mat_paths:
            textures = extract_all_mat_textures(tuple(mat_paths))
            texture_path = find_mat_texture_for_planet_ring(textures)
            if texture_path is None:
                texture_path = find_best_mat_texture(textures)

        size_match = re.search(r"_(\d+(?:\.\d+)?)\s*$", archetype)
        planet_radius = None
        if size_match is not None:
            try:
                planet_radius = float(size_match.group(1))
            except Exception:
                planet_radius = None
        if planet_radius is None or planet_radius <= 0.0:
            planet_radius = 1.0
        if inner_radius is None or inner_radius <= 0.0:
            inner_radius = planet_radius * 1.35
        if outer_radius is None or outer_radius <= inner_radius:
            outer_radius = planet_radius * 2.2

        info = {
            "texture_path": texture_path,
            "inner_ratio": max(1.02, float(inner_radius) / max(float(planet_radius), 1e-6)),
            "outer_ratio": max(1.08, float(outer_radius) / max(float(planet_radius), 1e-6)),
            "rotate_xyz": rotate_xyz,
        }
        cache[cache_key] = info
        return info

