    @staticmethod
    def _primitive_for_model(obj, model_path: Path) -> str:
        ext = model_path.suffix.lower()
        archetype = obj.data.get("archetype", "").lower()
        if ext == ".sph" or "sun" in archetype or "planet" in archetype:
            return "sphere"
        if any(token in archetype for token in ("jumpgate", "jump_gate", "nomad_gate")):
            return "jumpgate"
        return "cube"

    def _character_viewer_title(self) -> str:
        lang = str(get_language() or "").strip().lower()
        return "Character 3D Model Viewer" if lang.startswith("en") else "Charakter 3D-Modellviewer"

    def _character_viewer_none_text(self) -> str:
        lang = str(get_language() or "").strip().lower()
        return "<none>" if lang.startswith("en") else "<leer>"

    def _character_viewer_custom_costume_text(self) -> str:
        lang = str(get_language() or "").strip().lower()
        return "Custom Selection" if lang.startswith("en") else "Benutzerdefinierte Auswahl"

    def _character_viewer_combo_label(self, record: dict[str, object]) -> str:
        nick = str(record.get("nickname", "") or "").strip()
        display_name = str(record.get("display_name", "") or "").strip()
        if display_name and display_name.lower() != nick.lower():
            return f"{display_name} ({nick})"
        return nick

    def _character_viewer_selected_nick(self, combo: QComboBox) -> str:
        return str(combo.currentData() or "").strip().lower()

    def _character_viewer_selected_record(self, combo: QComboBox) -> dict[str, object] | None:
        nick_key = self._character_viewer_selected_nick(combo)
        if not nick_key:
            return None
        data = getattr(self, "_character_viewer_data", {}) or {}
        return dict(data.get("parts_by_nick", {}) or {}).get(nick_key)

    def _character_viewer_set_part_combo(
        self,
        combo: QComboBox,
        kind: str,
        *,
        selected_nick: str = "",
    ) -> None:
        data = getattr(self, "_character_viewer_data", {}) or {}
        rows = list(dict(data.get("parts_by_kind", {}) or {}).get(kind, []) or [])
        combo.blockSignals(True)
        combo.clear()
        combo.addItem(self._character_viewer_none_text(), "")
        selected_key = str(selected_nick or "").strip().lower()
        selected_index = 0
        for row in rows:
            nick = str(row.get("nickname", "") or "").strip()
            nick_key = nick.lower()
            combo.addItem(self._character_viewer_combo_label(row), nick_key)
            if nick_key and nick_key == selected_key:
                selected_index = combo.count() - 1
        combo.setCurrentIndex(selected_index)
        combo.blockSignals(False)

    def _character_viewer_fill_costume_combo(self, *, selected_key: str = "") -> None:
        combo = getattr(self, "_character_viewer_costume_cb", None)
        if combo is None:
            return
        data = getattr(self, "_character_viewer_data", {}) or {}
        costumes = dict(data.get("costumes", {}) or {})
        combo.blockSignals(True)
        combo.clear()
        combo.addItem(self._character_viewer_custom_costume_text(), "")
        selected_index = 0
        for key in sorted(costumes.keys(), key=str.lower):
            costume = dict(costumes.get(key, {}) or {})
            nickname = str(costume.get("nickname", "") or key).strip() or key
            combo.addItem(nickname, key)
            if key == selected_key:
                selected_index = combo.count() - 1
        combo.setCurrentIndex(selected_index)
        combo.blockSignals(False)

    def _character_viewer_apply_costume_to_part_combos(self, costume_key: str) -> None:
        data = getattr(self, "_character_viewer_data", {}) or {}
        costume = dict(dict(data.get("costumes", {}) or {}).get(str(costume_key or "").strip().lower(), {}) or {})
        self._character_viewer_set_part_combo(
            self._character_viewer_body_cb,
            "body",
            selected_nick=str(costume.get("body", "") or ""),
        )
        self._character_viewer_set_part_combo(
            self._character_viewer_head_cb,
            "head",
            selected_nick=str(costume.get("head", "") or ""),
        )
        self._character_viewer_set_part_combo(
            self._character_viewer_left_cb,
            "lefthand",
            selected_nick=str(costume.get("lefthand", "") or ""),
        )
        self._character_viewer_set_part_combo(
            self._character_viewer_right_cb,
            "righthand",
            selected_nick=str(costume.get("righthand", "") or ""),
        )

    def _refresh_character_3d_model_viewer(self, *, preserve_selection: bool = True) -> None:
        if not hasattr(self, "_character_viewer_preview"):
            return
        prev_costume = self._character_viewer_selected_nick(self._character_viewer_costume_cb) if preserve_selection else ""
        prev_body = self._character_viewer_selected_nick(self._character_viewer_body_cb) if preserve_selection else ""
        prev_head = self._character_viewer_selected_nick(self._character_viewer_head_cb) if preserve_selection else ""
        prev_left = self._character_viewer_selected_nick(self._character_viewer_left_cb) if preserve_selection else ""
        prev_right = self._character_viewer_selected_nick(self._character_viewer_right_cb) if preserve_selection else ""
        game_path = self._primary_game_path()
        self._character_viewer_data = self._collect_character_viewer_data(game_path)
        parts_by_kind = dict(self._character_viewer_data.get("parts_by_kind", {}) or {})
        total_parts = sum(len(list(parts_by_kind.get(kind, []) or [])) for kind in ("body", "head", "lefthand", "righthand"))
        self._character_viewer_fill_costume_combo(selected_key=prev_costume)
        active_costume = self._character_viewer_selected_nick(self._character_viewer_costume_cb)
        if active_costume:
            self._character_viewer_apply_costume_to_part_combos(active_costume)
        else:
            self._character_viewer_set_part_combo(self._character_viewer_body_cb, "body", selected_nick=prev_body)
            self._character_viewer_set_part_combo(self._character_viewer_head_cb, "head", selected_nick=prev_head)
            self._character_viewer_set_part_combo(self._character_viewer_left_cb, "lefthand", selected_nick=prev_left)
            self._character_viewer_set_part_combo(self._character_viewer_right_cb, "righthand", selected_nick=prev_right)
        self._character_viewer_summary_lbl.setText(
            f"{len(dict(self._character_viewer_data.get('costumes', {}) or {}))} costumes, {total_parts} body parts"
        )
        self._character_viewer_update_preview()

    def _on_character_viewer_costume_changed(self, _index: int) -> None:
        costume_key = self._character_viewer_selected_nick(self._character_viewer_costume_cb)
        if costume_key:
            self._character_viewer_apply_costume_to_part_combos(costume_key)
        self._character_viewer_update_preview()

    def _on_character_viewer_part_changed(self, _index: int) -> None:
        if self._character_viewer_selected_nick(self._character_viewer_costume_cb):
            self._character_viewer_costume_cb.blockSignals(True)
            self._character_viewer_costume_cb.setCurrentIndex(0)
            self._character_viewer_costume_cb.blockSignals(False)
        self._character_viewer_update_preview()

    def _character_viewer_update_preview(self) -> None:
        if not hasattr(self, "_character_viewer_preview"):
            return
        self._character_viewer_preview.set_theme_mode(current_theme() in ("light", "xp"))
        selections = [
            ("Body", self._character_viewer_selected_record(self._character_viewer_body_cb)),
            ("Head", self._character_viewer_selected_record(self._character_viewer_head_cb)),
            ("Left Hand", self._character_viewer_selected_record(self._character_viewer_left_cb)),
            ("Right Hand", self._character_viewer_selected_record(self._character_viewer_right_cb)),
        ]
        model_paths: list[Path | None] = []
        detail_lines: list[str] = []
        missing_labels: list[str] = []
        for label, record in selections:
            if record is None:
                detail_lines.append(f"{label}: {self._character_viewer_none_text()}")
                continue
            model_path = record.get("model_path")
            model_paths.append(model_path if isinstance(model_path, Path) else None)
            detail_lines.append(
                f"{label}: {self._character_viewer_combo_label(record)}"
            )
            if not isinstance(model_path, Path):
                missing_labels.append(label)
        costume_key = self._character_viewer_selected_nick(self._character_viewer_costume_cb)
        costume_text = self._character_viewer_custom_costume_text()
        if costume_key:
            costume = dict(dict(self._character_viewer_data.get("costumes", {}) or {}).get(costume_key, {}) or {})
            costume_text = str(costume.get("nickname", "") or costume_key).strip() or costume_text
        meta = " | ".join(detail_lines)
        if missing_labels:
            meta += " | Missing model: " + ", ".join(missing_labels)
        self._character_viewer_preview.set_model_paths(model_paths, caption=costume_text, meta=meta)
        self._character_viewer_detail_lbl.setText("\n".join(detail_lines))

    def _open_character_3d_model_viewer(self) -> None:
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.3d_preview"), tr("msg.3d_no_game_path"))
            return
        data = self._collect_character_viewer_data(game_path)
        parts_by_kind = dict(data.get("parts_by_kind", {}) or {})
        if not any(parts_by_kind.get(kind) for kind in ("body", "head", "lefthand", "righthand")):
            QMessageBox.information(
                self,
                tr("msg.3d_preview"),
                "No character body parts with resolvable model paths were found.",
            )
            return
        title = self._character_viewer_title()
        page, root = self._prepare_editor_page("character_model_viewer_page", title)

        top_row = QHBoxLayout()
        self._character_viewer_summary_lbl = QLabel("", page)
        top_row.addWidget(self._character_viewer_summary_lbl, 1)
        refresh_btn = QPushButton("Refresh", page)
        refresh_btn.clicked.connect(lambda: self._refresh_character_3d_model_viewer(preserve_selection=True))
        top_row.addWidget(refresh_btn)
        root.addLayout(top_row)

        controls_box = QGroupBox("Character Setup", page)
        controls_form = QFormLayout(controls_box)
        self._character_viewer_costume_cb = QComboBox(controls_box)
        self._character_viewer_costume_cb.currentIndexChanged.connect(self._on_character_viewer_costume_changed)
        controls_form.addRow("Costume", self._character_viewer_costume_cb)
        self._character_viewer_body_cb = QComboBox(controls_box)
        self._character_viewer_body_cb.currentIndexChanged.connect(self._on_character_viewer_part_changed)
        controls_form.addRow("Body", self._character_viewer_body_cb)
        self._character_viewer_head_cb = QComboBox(controls_box)
        self._character_viewer_head_cb.currentIndexChanged.connect(self._on_character_viewer_part_changed)
        controls_form.addRow("Head", self._character_viewer_head_cb)
        self._character_viewer_left_cb = QComboBox(controls_box)
        self._character_viewer_left_cb.currentIndexChanged.connect(self._on_character_viewer_part_changed)
        controls_form.addRow("Left Hand", self._character_viewer_left_cb)
        self._character_viewer_right_cb = QComboBox(controls_box)
        self._character_viewer_right_cb.currentIndexChanged.connect(self._on_character_viewer_part_changed)
        controls_form.addRow("Right Hand", self._character_viewer_right_cb)
        root.addWidget(controls_box)

        self._character_viewer_detail_lbl = QLabel("", page)
        self._character_viewer_detail_lbl.setWordWrap(True)
        self._character_viewer_detail_lbl.setTextInteractionFlags(Qt.TextSelectableByMouse)
        root.addWidget(self._character_viewer_detail_lbl)

        self._character_viewer_preview = FreelancerModelPreviewWidget(title, page)
        self._character_viewer_preview.set_compact_mode(True)
        self._character_viewer_preview.set_theme_mode(current_theme() in ("light", "xp"))
        root.addWidget(self._character_viewer_preview, 1)

        self._character_viewer_data = data
        self._refresh_character_3d_model_viewer(preserve_selection=False)
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="character_model_viewer",
            current_widget=page,
            tab_key="character_model_viewer",
            open_extra_tab=True,
            title=title,
        )

    def _open_3d_model_viewer(self):
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.3d_preview"), tr("msg.3d_no_game_path"))
            return
        entries = self._collect_3d_model_viewer_entries()
        if not entries:
            QMessageBox.information(self, tr("msg.3d_preview"), "No 3D models with resolvable archetypes were found.")
            return
        page, root = self._prepare_editor_page("model_viewer_page", "3D Model Manager")
        viewer = ModelViewerWidget(
            page,
            entries=entries,
            preview_callback=self._show_model_viewer_entry_3d_preview,
            embedded_preview_factory=self._build_embedded_model_viewer_preview_widget,
            open_ini_callback=self._open_model_viewer_entry_source_ini,
            refresh_callback=self._collect_3d_model_viewer_entries,
        )
        root.addWidget(viewer, 1)
        activate_non_universe_view(
            self,
            layout_state=WorkspaceLayoutState(
                left_sidebar_visible=False,
                right_panel_visible=False,
                legend_visible=False,
                zoom_controls_visible=False,
                view3d_toggle_visible=False,
                view3d_toggle_enabled=False,
                view3d_toggle_checked=False,
                sidebar_3d_enabled=False,
            ),
            nav_key="model_viewer",
            current_widget=page,
            tab_key="model_viewer",
            open_extra_tab=True,
            title="3D Model Manager",
        )

    def _open_model_viewer_entry_source_ini(self, entry: ModelViewerEntry) -> None:
        self._open_ini_editor_view()
        self._ini_editor_open_file_in_tab(str(entry.source_ini_path))

    def _create_model_viewer_preview_widget(self, entry: ModelViewerEntry, parent: QWidget, *, embedded: bool) -> QWidget | None:
        model_path = entry.model_path
        preview_resolution = resolve_preview_mesh_candidate(model_path)
        preview_mesh = preview_resolution.preview_path
        if not QT3D_AVAILABLE:
            if embedded:
                label = QLabel(
                    tr("msg.3d_not_available").format(path=f"{entry.archetype} / {entry.da_archetype} / {model_path}"),
                    parent,
                )
                label.setWordWrap(True)
                label.setAlignment(Qt.AlignCenter)
                return label
            return None
        obj = SimpleNamespace(
            data={
                "archetype": entry.archetype,
                "ring": entry.ring,
                "atmosphere_range": entry.atmosphere_range,
                "burn_color": entry.burn_color,
            },
        )
        if preview_mesh:
            dlg = MeshPreviewDialog(parent, preview_mesh, f"3D Preview — {entry.title_text}")
            if embedded:
                dlg.setWindowFlags(Qt.Widget)
                dlg.setMinimumSize(0, 0)
            return dlg
        prim = self._primitive_for_model(obj, model_path)
        prefix = ""
        native_model = None
        native_scene_data = None
        if preview_resolution.is_freelancer_native:
            try:
                native_model = load_native_freelancer_model(model_path)
                native_scene_result = load_native_scene_data(model_path)
                native_scene_data = native_scene_result.scene_data if native_scene_result is not None else None
                prefix = build_native_model_info_text(native_model)
            except Exception as exc:
                prefix = (
                    f"Freelancer native model detected ({preview_resolution.extension}). "
                    f"Native load failed: {type(exc).__name__}: {exc}\n\n"
                )
        planet_surface_texture = None
        planet_cloud_texture = None
        planet_ring_info = None
        atmosphere_range = None
        burn_color = None
        planet_radius = None
        if prim == "sphere" and "planet" in entry.archetype.lower():
            planet_surface_texture = self._resolve_planet_texture_for_object(obj)
            planet_cloud_texture = self._resolve_planet_cloud_texture_for_object(obj)
            planet_ring_info = self._resolve_planet_ring_render_info_for_object(obj)
            try:
                atmosphere_range = float(entry.atmosphere_range.strip() or "0")
            except Exception:
                atmosphere_range = None
            burn_parts = [part.strip() for part in entry.burn_color.split(",") if part.strip()]
            if len(burn_parts) >= 3:
                try:
                    burn_color = tuple(max(0, min(255, int(float(part)))) for part in burn_parts[:3])
                except Exception:
                    burn_color = None
            size_match = re.search(r"_(\d+(?:\.\d+)?)\s*$", entry.archetype)
            if size_match is not None:
                try:
                    planet_radius = float(size_match.group(1))
                except Exception:
                    planet_radius = None
        has_native_geometry = bool(native_scene_data is not None and getattr(native_scene_data, "geometries", ()))
        dlg = MeshPreviewDialog(
            parent,
            None,
            f"3D Preview — {entry.title_text}" + (" (Fallback)" if not has_native_geometry else ""),
            primitive=prim,
            native_model=native_model,
            info_text=(
                prefix
                if has_native_geometry
                else prefix + tr("msg.3d_original_not_renderable").format(
                    archetype=entry.archetype,
                    file=f"{entry.da_archetype} → {model_path}",
                    fallback=prim,
                )
            ),
            material_library_paths=entry.material_library_paths,
            planet_surface_texture_path=planet_surface_texture,
            planet_cloud_texture_path=planet_cloud_texture,
            planet_ring_texture_path=(planet_ring_info or {}).get("texture_path"),
            planet_ring_inner_ratio=(planet_ring_info or {}).get("inner_ratio"),
            planet_ring_outer_ratio=(planet_ring_info or {}).get("outer_ratio"),
            planet_ring_rotate_xyz=(planet_ring_info or {}).get("rotate_xyz"),
            planet_atmosphere_range=atmosphere_range,
            planet_burn_color=burn_color,
            planet_radius=planet_radius,
            scene_data=native_scene_data,
        )
        if embedded:
            dlg.setWindowFlags(Qt.Widget)
            dlg.setMinimumSize(0, 0)
        if has_native_geometry:
            dlg.setWindowTitle(f"3D Preview - {entry.title_text}")
        return dlg

    def _build_embedded_model_viewer_preview_widget(self, entry: ModelViewerEntry, parent: QWidget) -> QWidget | None:
        return self._create_model_viewer_preview_widget(entry, parent, embedded=True)

    def _show_model_viewer_entry_3d_preview(self, entry: ModelViewerEntry) -> None:
        preview_widget = self._create_model_viewer_preview_widget(entry, self, embedded=False)
        if preview_widget is None:
            QMessageBox.information(
                self,
                tr("msg.3d_preview"),
                tr("msg.3d_not_available").format(path=f"{entry.archetype} / {entry.da_archetype} / {entry.model_path}"),
            )
            return
        if isinstance(preview_widget, QDialog):
            preview_widget.exec()

    # ==================================================================
    #  3D-Preview / Modell öffnen
    # ==================================================================
    def _show_selected_3d_preview(self):
        obj = self._selected
        if not obj or isinstance(obj, ZoneItem):
            QMessageBox.information(self, tr("msg.3d_preview"), tr("msg.3d_select_first"))
            return
        base_nick = self._base_nickname_for_object(obj)
        if base_nick and self._show_base_related_3d_preview(obj, base_nick):
            return
        archetype = obj.data.get("archetype", "").strip()
        if not archetype:
            QMessageBox.warning(self, tr("msg.3d_preview"), tr("msg.3d_no_archetype"))
            return
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.3d_preview"), tr("msg.3d_no_game_path"))
            return
        model_path, da_arch = self._resolve_model_for_archetype(archetype, game_path)
        if not da_arch:
            QMessageBox.warning(self, tr("msg.3d_preview"),
                                tr("msg.3d_no_da").format(archetype=archetype))
            return
        if not model_path:
            QMessageBox.warning(self, tr("msg.3d_preview"),
                                tr("msg.3d_da_not_resolved").format(da_arch=da_arch))
            return
        preview_resolution = resolve_preview_mesh_candidate(model_path)
        preview_mesh = preview_resolution.preview_path
        if not preview_mesh and preview_resolution.is_freelancer_native:
            self._show_selected_native_3d_preview_async(
                obj=obj,
                archetype=archetype,
                game_path=game_path,
                model_path=model_path,
                da_arch=da_arch,
                preview_resolution=preview_resolution,
            )
            return
        if not QT3D_AVAILABLE:
            QMessageBox.information(
                self, tr("msg.3d_preview"),
                tr("msg.3d_not_available").format(path=f"{archetype} / {da_arch} / {model_path}"),
            )
            return
        if not preview_mesh:
            prim = self._primitive_for_model(obj, model_path)
            prefix = ""
            native_model = None
            native_scene_data = None
            if preview_resolution.is_freelancer_native:
                try:
                    native_model = load_native_freelancer_model(model_path)
                    native_scene_result = load_native_scene_data(model_path)
                    native_scene_data = native_scene_result.scene_data if native_scene_result is not None else None
                    prefix = build_native_model_info_text(native_model)
                except Exception as exc:
                    prefix = (
                        f"Freelancer native model detected ({preview_resolution.extension}). "
                        f"Native load failed: {type(exc).__name__}: {exc}\n\n"
                    )
            mat_lib_paths = self._resolve_material_library_paths(archetype, game_path)
            planet_surface_texture = None
            planet_cloud_texture = None
            planet_ring_info = None
            atmosphere_range = None
            burn_color = None
            planet_radius = None
            if prim == "sphere" and "planet" in archetype.lower():
                planet_surface_texture = self._resolve_planet_texture_for_object(obj)
                planet_cloud_texture = self._resolve_planet_cloud_texture_for_object(obj)
                planet_ring_info = self._resolve_planet_ring_render_info_for_object(obj)
                try:
                    atmosphere_range = float(str(obj.data.get("atmosphere_range", "") or "0").strip() or "0")
                except Exception:
                    atmosphere_range = None
                burn_parts = [part.strip() for part in str(obj.data.get("burn_color", "") or "").split(",") if part.strip()]
                if len(burn_parts) >= 3:
                    try:
                        burn_color = tuple(max(0, min(255, int(float(part)))) for part in burn_parts[:3])
                    except Exception:
                        burn_color = None
                size_match = re.search(r"_(\d+(?:\.\d+)?)\s*$", archetype)
                if size_match is not None:
                    try:
                        planet_radius = float(size_match.group(1))
                    except Exception:
                        planet_radius = None
            has_native_geometry = bool(native_scene_data is not None and getattr(native_scene_data, "geometries", ()))
            dlg = MeshPreviewDialog(
                self, None, f"3D Preview — {obj.nickname}" + (" (Fallback)" if not has_native_geometry else ""),
                primitive=prim,
                native_model=native_model,
                info_text=(
                    prefix
                    if has_native_geometry
                    else prefix + tr("msg.3d_original_not_renderable").format(
                        archetype=archetype, file=f"{da_arch} → {model_path}", fallback=prim)
                ),
                material_library_paths=mat_lib_paths,
                planet_surface_texture_path=planet_surface_texture,
                planet_cloud_texture_path=planet_cloud_texture,
                planet_ring_texture_path=(planet_ring_info or {}).get("texture_path"),
                planet_ring_inner_ratio=(planet_ring_info or {}).get("inner_ratio"),
                planet_ring_outer_ratio=(planet_ring_info or {}).get("outer_ratio"),
                planet_ring_rotate_xyz=(planet_ring_info or {}).get("rotate_xyz"),
                planet_atmosphere_range=atmosphere_range,
                planet_burn_color=burn_color,
                planet_radius=planet_radius,
                scene_data=native_scene_data,
            )
            if has_native_geometry:
                dlg.setWindowTitle(f"3D Preview - {obj.nickname}")
            dlg.exec()
            return
        MeshPreviewDialog(self, preview_mesh, f"3D Preview — {obj.nickname}").exec()

    def _show_selected_native_3d_preview_async(
        self,
        *,
        obj,
        archetype: str,
        game_path: str,
        model_path: Path,
        da_arch: str,
        preview_resolution,
    ) -> None:
        if not QT3D_AVAILABLE:
            QMessageBox.information(
                self,
                tr("msg.3d_preview"),
                tr("msg.3d_not_available").format(path=f"{archetype} / {da_arch} / {model_path}"),
            )
            return

        prim = self._primitive_for_model(obj, model_path)
        mat_lib_paths = self._resolve_material_library_paths(archetype, game_path)
        planet_surface_texture = None
        planet_cloud_texture = None
        planet_ring_info = None
        atmosphere_range = None
        burn_color = None
        planet_radius = None
        if prim == "sphere" and "planet" in archetype.lower():
            planet_surface_texture = self._resolve_planet_texture_for_object(obj)
            planet_cloud_texture = self._resolve_planet_cloud_texture_for_object(obj)
            planet_ring_info = self._resolve_planet_ring_render_info_for_object(obj)
            try:
                atmosphere_range = float(str(obj.data.get("atmosphere_range", "") or "0").strip() or "0")
            except Exception:
                atmosphere_range = None
            burn_parts = [part.strip() for part in str(obj.data.get("burn_color", "") or "").split(",") if part.strip()]
            if len(burn_parts) >= 3:
                try:
                    burn_color = tuple(max(0, min(255, int(float(part)))) for part in burn_parts[:3])
                except Exception:
                    burn_color = None
            size_match = re.search(r"_(\d+(?:\.\d+)?)\s*$", archetype)
            if size_match is not None:
                try:
                    planet_radius = float(size_match.group(1))
                except Exception:
                    planet_radius = None

        def _open_dialog(native_scene_data=None) -> None:
            has_native_geometry = bool(native_scene_data is not None and getattr(native_scene_data, "geometries", ()))
            info_text = (
                f"Freelancer native model detected ({preview_resolution.extension}). Native geometry loaded.\n"
                if has_native_geometry
                else tr("msg.3d_original_not_renderable").format(
                    archetype=archetype,
                    file=f"{da_arch} -> {model_path}",
                    fallback=prim,
                )
            )
            dlg = MeshPreviewDialog(
                self,
                None,
                f"3D Preview - {obj.nickname}" + (" (Fallback)" if not has_native_geometry else ""),
                primitive=prim,
                native_model=None,
                info_text=info_text,
                material_library_paths=mat_lib_paths,
                planet_surface_texture_path=planet_surface_texture,
                planet_cloud_texture_path=planet_cloud_texture,
                planet_ring_texture_path=(planet_ring_info or {}).get("texture_path"),
                planet_ring_inner_ratio=(planet_ring_info or {}).get("inner_ratio"),
                planet_ring_outer_ratio=(planet_ring_info or {}).get("outer_ratio"),
                planet_ring_rotate_xyz=(planet_ring_info or {}).get("rotate_xyz"),
                planet_atmosphere_range=atmosphere_range,
                planet_burn_color=burn_color,
                planet_radius=planet_radius,
                scene_data=native_scene_data,
            )
            dlg.exec()

        native_scene_data = self._resolve_native_scene_data_for_object(obj)
        if native_scene_data is not None and getattr(native_scene_data, "geometries", ()):
            _open_dialog(native_scene_data)
            return

        if callable(getattr(self, "_set_loading_visible", None)):
            self._set_loading_visible(True, f"Loading 3D preview... {getattr(obj, 'nickname', '')}")

        poll_state = {"attempts": 0}

        def _poll_native_preview() -> None:
            poll_state["attempts"] += 1
            current_scene_data = self._resolve_native_scene_data_for_object(obj)
            if current_scene_data is not None and getattr(current_scene_data, "geometries", ()):
                if callable(getattr(self, "_set_loading_visible", None)):
                    self._set_loading_visible(False)
                _open_dialog(current_scene_data)
                return
            runtime = getattr(self, "_native_scene_runtime_store", None)
            failed_paths = ()
            if runtime is not None:
                try:
                    failed_paths = tuple(runtime.get_debug_state().get("failed_paths", ()) or ())
                except Exception:
                    failed_paths = ()
            if model_path in failed_paths or poll_state["attempts"] >= 200:
                if callable(getattr(self, "_set_loading_visible", None)):
                    self._set_loading_visible(False)
                _open_dialog(None)
                return
            QTimer.singleShot(30, _poll_native_preview)

        QTimer.singleShot(0, _poll_native_preview)

    def _open_model_file(self):
        selected = getattr(self, "_selected", None)
        if selected is not None and not isinstance(selected, ZoneItem):
            archetype = str(selected.data.get("archetype", "") or "").strip()
            game_path = self._primary_game_path()
            if archetype and game_path:
                self._show_selected_3d_preview()
                return
        start_dir = self._primary_game_path() or str(Path.home())
        path, _ = QFileDialog.getOpenFileName(
            self, tr("msg.open_model"), start_dir,
            "Freelancer/3D (*.cmp *.3db *.sph *.obj *.stl *.ply "
            f"*.gltf *.glb *.dae *.fbx *.3ds);;{tr('msg.all_files')}",
        )
        if not path:
            return
        model_path = Path(path)
        preview_resolution = resolve_preview_mesh_candidate(model_path)
        preview_mesh = preview_resolution.preview_path
        if not QT3D_AVAILABLE:
            QMessageBox.information(self, tr("msg.3d_preview"), tr("msg.3d_not_available").format(path=model_path))
            return
        if preview_mesh:
            MeshPreviewDialog(self, preview_mesh, f"3D Preview — {model_path.name}").exec()
            return
        prim = "sphere" if model_path.suffix.lower() == ".sph" else "cube"
        prefix = ""
        native_model = None
        if preview_resolution.is_freelancer_native:
            try:
                native_model = load_native_freelancer_model(model_path)
                prefix = build_native_model_info_text(native_model)
            except Exception as exc:
                prefix = (
                    f"Freelancer native model detected ({preview_resolution.extension}). "
                    f"Native load failed: {type(exc).__name__}: {exc}\n\n"
                )
        MeshPreviewDialog(
            self, None, f"3D Preview — {model_path.name} (Fallback)",
            primitive=prim,
            native_model=native_model,
            info_text=prefix + tr("msg.3d_not_renderable").format(
                file=model_path, format=model_path.suffix.lower(), fallback=prim),
        ).exec()

    # ==================================================================
    #  System-Metadaten  (Musik, Farben, Background)
    # ==================================================================
    def _get_section_value(self, section: str, key: str) -> str:
        for sec_name, entries in self._sections:
            if sec_name.lower() == section.lower():
                for k, v in entries:
                    if k.lower() == key.lower():
                        return v
        return ""

    def _set_section_value(self, section: str, key: str, value: str):
        section_l = section.lower()
        key_l = key.lower()
        matching_indices: list[int] = []
        updated_any_key = False

        for idx, (sec_name, entries) in enumerate(self._sections):
            if sec_name.lower() != section_l:
                continue
            matching_indices.append(idx)
            changed = False
            for j, (k, v) in enumerate(entries):
                if k.lower() == key_l:
                    entries[j] = (k, value)
                    changed = True
                    updated_any_key = True
            if changed:
                self._sections[idx] = (sec_name, entries)

        if matching_indices and not updated_any_key:
            first_idx = matching_indices[0]
            sec_name, entries = self._sections[first_idx]
            entries.append((key, value))
            self._sections[first_idx] = (sec_name, entries)
            return

        if not matching_indices:
            self._sections.append((section, [(key, value)]))

    def _open_system_settings(self):
        """Öffnet den System-Einstellungen-Dialog."""
        if not self._filepath:
            return
        current = {
            "nickname": Path(self._filepath).stem.upper(),
            "music_space": self._get_section_value("Music", "space"),
            "music_danger": self._get_section_value("Music", "danger"),
            "music_battle": self._get_section_value("Music", "battle"),
            "space_color": self._get_section_value("SystemInfo", "space_color"),
            "local_faction": self._faction_ui_label(self._get_section_value("SystemInfo", "local_faction")),
            "ambient_color": self._get_section_value("Ambient", "color"),
            "dust": self._get_section_value("Dust", "spacedust"),
            "bg_basic": self._get_section_value("Background", "basic_stars"),
            "bg_complex": self._get_section_value("Background", "complex_stars"),
            "bg_nebulae": self._get_section_value("Background", "nebulae"),
        }
        dlg = SystemSettingsDialog(
            self,
            current=current,
            music_options=self._cached_music_opts,
            bg_options=self._cached_bg_opts,
            factions=self._cached_faction_labels if self._cached_faction_labels else self._cached_factions,
            dust_options=self._cached_dust_opts,
        )
        if dlg.exec() != QDialog.Accepted:
            return
        data = dlg.result_data()
        self._set_section_value("Music", "space", data["music_space"])
        self._set_section_value("Music", "danger", data["music_danger"])
        self._set_section_value("Music", "battle", data["music_battle"])
        self._set_section_value("SystemInfo", "space_color", data["space_color"])
        self._set_section_value("SystemInfo", "local_faction", self._faction_from_ui(data["local_faction"]))
        self._set_section_value("Ambient", "color", data["ambient_color"])
        self._set_section_value("Dust", "spacedust", data["dust"])
        self._set_section_value("Background", "basic_stars", data["bg_basic"])
        self._set_section_value("Background", "complex_stars", data["bg_complex"])
        self._set_section_value("Background", "nebulae", data["bg_nebulae"])
        self._set_dirty(True)
        self._write_to_file(reload=True)

    def _populate_system_options(self):
        """Scannt alle Systeme und cached Dropdown-Optionen für den Einstellungen-Dialog."""
        game_path = self._primary_game_path()
        music_vals = {"space": set(), "danger": set(), "battle": set()}
        bg_vals = {"basic_stars": set(), "complex_stars": set(), "nebulae": set()}
        dust_vals: set[str] = set()
        if game_path:
            try:
                for s in self._find_all_systems(game_path):
                    try:
                        secs = self._parser.parse(s["path"])
                    except Exception:
                        continue
                    for sec_name, entries in secs:
                        low = sec_name.lower()
                        if low == "music":
                            for k, v in entries:
                                lk = k.lower()
                                if lk in music_vals and v:
                                    music_vals[lk].add(v)
                        elif low == "background":
                            for k, v in entries:
                                lk = k.lower()
                                if lk in bg_vals and v:
                                    bg_vals[lk].add(v)
                        elif low == "system":
                            for k, v in entries:
                                if k.lower() == "dust" and v:
                                    dust_vals.add(v)
            except Exception:
                pass
        self._cached_music_opts = {
            "space": sorted(music_vals["space"], key=str.lower),
            "danger": sorted(music_vals["danger"], key=str.lower),
            "battle": sorted(music_vals["battle"], key=str.lower),
        }
        self._cached_bg_opts = {
            "basic_stars": sorted(bg_vals["basic_stars"], key=str.lower),
            "complex_stars": sorted(bg_vals["complex_stars"], key=str.lower),
            "nebulae": sorted(bg_vals["nebulae"], key=str.lower),
        }
        self._cached_dust_opts = sorted(dust_vals, key=str.lower)

        # Local Factions
        group_rows: list[tuple[str, str]] = []
        if game_path:
            iw_file = self._resolve_game_path_case_insensitive(game_path, "DATA/initialworld.ini")
            if iw_file and iw_file.exists():
                try:
                    for sec_name, entries in self._parser.parse(str(iw_file)):
                        if sec_name.lower() == "group":
                            nick = ""
                            ids_name = ""
                            for k, v in entries:
                                lk = k.lower()
                                if lk == "nickname":
                                    nick = v.strip()
                                elif lk == "ids_name":
                                    ids_name = v.strip()
                            if nick and all(nick.lower() != existing.lower() for existing, _ in group_rows):
                                group_rows.append((nick, ids_name))
                except Exception:
                    pass
        group_rows.sort(key=lambda x: x[0].lower())
        self._build_faction_label_cache(group_rows)

    def _refresh_system_fields(self):
        """Aktualisiert den Button-Text mit dem System-Kürzel."""
        if self._filepath:
            nickname = self._system_nickname_for_path(self._filepath)
            display = self._system_display_name(nickname)
            self.sys_settings_btn.setText(f"⚙️  {tr('dlg.system_settings').format(nickname=display)}")

    def _search_nickname(self):
        term = self.search_edit.text().strip().lower()
        if not term:
            return
        for o in self._objects:
            if o.nickname.lower() == term:
                self.view.centerOn(o)
                self._select(o)
                return
        QMessageBox.information(self, tr("msg.not_found"), tr("msg.not_found_nickname").format(term=term))

    # ── Fehlende IDS scannen & CSV-Export ─────────────────────────
    def _scan_missing_ids(self):
        self._open_name_editor_view()

    # ── IDS aus CSV importieren ───────────────────────────────────
    def _import_ids_from_csv(self):
        """Liest die CSV-Dateien, trägt ausgefüllte ids_name/ids_info
        Nummern in die jeweiligen System-INI-Dateien ein und entfernt
        verarbeitete Zeilen aus den CSVs.
        """
        game_path = self._primary_game_path()
        if not game_path:
            QMessageBox.warning(self, tr("msg.no_game_path"),
                                tr("msg.no_game_loaded"))
            return

        folder = Path(game_path)
        name_csv = folder / "missing_ids_name.csv"
        info_csv = folder / "missing_ids_info.csv"

        if not name_csv.exists() and not info_csv.exists():
            QMessageBox.information(
                self, tr("msg.no_csv_files"),
                tr("msg.no_csv_text")
            )
            return

        systems = self._find_all_systems(game_path)
        sys_map: dict[str, str] = {s["nickname"].lower(): s["path"] for s in systems}

        updated_name = 0
        updated_info = 0

        # ── ids_name CSV verarbeiten ─────────────────────────────
        remaining_name: list[dict] = []
        if name_csv.exists():
            updated_name, remaining_name = process_ids_csv_rows(
                load_ids_csv_rows(name_csv),
                value_key="ids_name",
                sys_map=sys_map,
                update_entry=lambda sys_path, sec_type, obj_nick, ids_val: self._update_ids_in_file(
                    sys_path,
                    sec_type,
                    obj_nick,
                    "ids_name",
                    ids_val,
                ),
            )
            persist_remaining_ids_csv(name_csv, remaining_name, fieldnames=NAME_CSV_FIELDS)

        # ── ids_info CSV verarbeiten ─────────────────────────────
        remaining_info: list[dict] = []
        if info_csv.exists():
            updated_info, remaining_info = process_ids_csv_rows(
                load_ids_csv_rows(info_csv),
                value_key="ids_info",
                sys_map=sys_map,
                update_entry=lambda sys_path, sec_type, obj_nick, ids_val: self._update_ids_in_file(
                    sys_path,
                    sec_type,
                    obj_nick,
                    "ids_info",
                    ids_val,
                ),
            )
            persist_remaining_ids_csv(info_csv, remaining_info, fieldnames=INFO_CSV_FIELDS)

        if updated_name == 0 and updated_info == 0:
            QMessageBox.information(
                self, tr("msg.no_changes"),
                tr("msg.no_csv_entries")
            )
            return

        parts: list[str] = []
        if updated_name:
            rest_n = len(remaining_name)
            parts.append(tr("ids.name_updated").format(count=updated_name)
                         + (tr("ids.remaining").format(count=rest_n) if rest_n else tr("ids.csv_deleted")))
        if updated_info:
            rest_i = len(remaining_info)
            parts.append(tr("ids.info_updated").format(count=updated_info)
                         + (tr("ids.remaining").format(count=rest_i) if rest_i else tr("ids.csv_deleted")))

        QMessageBox.information(
            self, tr("msg.ids_import_done"),
            "\n".join(parts)
        )

    def _update_ids_in_file(self, sys_path: str, sec_type: str,
                            obj_nick: str, key: str, value: str) -> bool:
        """Aktualisiert einen ``ids_name`` oder ``ids_info`` Wert in einer
        System-INI-Datei.  Gibt ``True`` zurück wenn erfolgreich.
        """
        sys_path = str(self._ensure_writable_path(sys_path))
        try:
            sections = self._parser.parse(sys_path)
        except Exception:
            return False

        if not update_ids_entry_in_sections(sections, sec_type, obj_nick, key, value):
            return False

        # Datei zurückschreiben
        try:
            self._write_sections_to_file(sys_path, sections)
        except Exception:
            return False
        return True

    def _write_sections_to_file(self, filepath: str, sections: list) -> None:
        """Schreibt geparste Sektionen zurück in eine INI-Datei."""
        filepath = str(self._ensure_writable_path(filepath))
        write_sections_to_file(filepath, sections)
